def main_notebook_tab_labels(window_width, compact_below=1100):
    """Возвращает полные или компактные подписи главных вкладок."""
    try:
        compact = int(window_width) < int(compact_below)
    except (TypeError, ValueError, OverflowError):
        compact = False
    label_index = 1 if compact else 0
    return tuple(labels[label_index] for labels in MAIN_NOTEBOOK_TAB_LABELS)

