def m4b_group_sequence_key(group, fallback_id=""):
    """Возвращает ключ последовательности томов для группы M4B."""
    group = group if isinstance(group, dict) else {}
    album = str(group.get("album") or "").strip()
    album_artist = str(
        group.get("album_artist") or group.get("artist") or ""
    ).strip()
    if album:
        return ("album", album.casefold(), album_artist.casefold())
    return ("group", str(fallback_id or group.get("source_path") or group.get("name") or ""))


def assign_m4b_volume_numbers(entries):
    """Назначает стабильные номера томов внутри каждой книги.

    ``entries`` содержит кортежи ``(sequence_key, item_id, local_part,
    preferred_number, total_hint)``. Исходный номер сохраняется, если он
    однозначен; отсутствующие или конфликтующие номера получают ближайшее
    свободное значение в порядке дерева.
    """
    grouped = {}
    for entry in entries or ():
        try:
            sequence_key, item_id, local_part, preferred, total_hint = entry
        except (TypeError, ValueError):
            continue
        grouped.setdefault(sequence_key, []).append(
            (item_id, local_part, preferred, total_hint)
        )
    result = {}
    for sequence_key, sequence_entries in grouped.items():
        used = set()
        assigned = []
        base_numbers = {}
        total_hint = 0
        for item_id, local_part, preferred, hint in sequence_entries:
            try:
                preferred_number = int(preferred or 0)
            except (TypeError, ValueError, OverflowError):
                preferred_number = 0
            try:
                total_hint = max(total_hint, int(hint or 0))
            except (TypeError, ValueError, OverflowError):
                pass
            if item_id in base_numbers:
                number = base_numbers[item_id] + max(0, int(local_part or 1) - 1)
            elif preferred_number > 0:
                number = preferred_number
            else:
                number = 1
            while number in used or number <= 0:
                number += 1
            base_numbers.setdefault(item_id, number)
            used.add(number)
            assigned.append((item_id, local_part, number))
        total = max(
            len(sequence_entries),
            total_hint,
            max((number for _item, _part, number in assigned), default=1),
        )
        for item_id, local_part, number in assigned:
            result[(item_id, local_part)] = (number, total)
    return result
# Небольшой запас до 24 часов предотвращает ситуацию, когда округление
# временных меток контейнером или проигрывателем выводит номинально суточный
# том за допустимый предел. Это автоматический защитный лимит, а не утверждение,
# что каждый проигрыватель M4B отвергает файл ровно такой длительности.
M4B_SAFE_VOLUME_SECONDS = (23 * 60 + 50) * 60
# Автоматическое разделение томов запускается только после того, как вся книга
# (или заданная вручную цель M4B) превысит сутки. Отдельный порог и лимит тома
# делают правило явным и не делят короткую книгу только из-за отсутствия
# пользовательского ограничения.
M4B_AUTO_SPLIT_THRESHOLD_SECONDS = 24 * 60 * 60
# Ноль означает, что пользователь не задал фиксированный лимит для тома.
# Тогда правило применяет ``M4B_SAFE_VOLUME_SECONDS`` только после превышения
# книгой 24 часов. Константа общая для значений по умолчанию, запасных значений
# интерфейса и снимков запуска, чтобы пропущенная или неверная настройка не
# превращала книгу в неожиданное разделение по 23 часа.
DEFAULT_M4B_MAX_DURATION_HOURS = 0.0


def normalize_m4b_audio_language(value, default=M4B_AUDIO_LANGUAGE):
    """Возвращает трёхбуквенный код языка аудиопотока M4B."""
    aliases = {
        "ru": "rus",
        "en": "eng",
    }
    text = str(value or "").strip().lower()
    text = aliases.get(text, text)
    if text == "und":
        text = ""
    if re.fullmatch(r"[a-z]{3}", text):
        return text
    fallback = str(default or M4B_AUDIO_LANGUAGE).strip().lower()
    fallback = aliases.get(fallback, fallback)
    return fallback if re.fullmatch(r"[a-z]{3}", fallback) else M4B_AUDIO_LANGUAGE


def normalize_source_m4b_template(value):
    """Вернуть сохранённый шаблон имени файла M4B для исходников.

    ``None`` означает отсутствие значения (используется историческое значение
    по умолчанию), а пустая строка или пробелы — явный запрос формы без
    диапазона. Единая чистая функция не даёт обновлению интерфейса или снимку
    фоновой задачи случайно вернуть ``{range}``.
    """
    if value is None:
        return DEFAULT_SOURCE_M4B_TEMPLATE
    text = str(value).strip()
    return text or SOURCE_M4B_NO_RANGE_TEMPLATE


def _source_m4b_template_from_config(config):
    """Получить шаблон M4B для исходников из снимка настроек или запуска.

    ``source_m4b_template`` — временное имя в снимке фоновой задачи, а
    ``synthesis_m4b_template`` — основной сохранённый ключ. Если временный
    ключ присутствует, он имеет приоритет (явная пустая строка означает форму
    ``{book}``); иначе используется основной. Это не позволяет старым прямым
    вызовам незаметно вернуть суффикс ``Главы {range}``.
    """
    values = config if isinstance(config, dict) else {}
    # ``None`` — маркер отсутствующего значения в старых прямых вызовах;
    # в отличие от явной пустой строки он не должен заменять пользовательское
    # значение основного ключа историческим значением по умолчанию.
    transient = values.get("source_m4b_template")
    if "source_m4b_template" in values and transient is not None:
        return normalize_source_m4b_template(transient)
    return normalize_source_m4b_template(values.get("synthesis_m4b_template"))


def normalize_source_m4b_album_template(value):
    """Нормализовать шаблон альбома M4B, сохранив явную пустую строку."""
    if value is None:
        return DEFAULT_SOURCE_M4B_ALBUM_TEMPLATE
    return str(value).strip()


def resolve_source_book_name(config=None, source_root=None, planned_name=None):
    """Возвращает стабильное имя книги для текущей папки исходников.

    Явное имя связано с папкой, в которой пользователь его задал. После смены
    ``input_dir`` старое значение не переезжает молча в следующую книгу. Для
    старых настроек без маркера папки сохраняется совместимость. Непустой
    буквальный альбом используется только как первоначальный запасной вариант:
    шаблон тега вроде ``{filename}`` не является названием книги.
    """
    values = config if isinstance(config, dict) else {}
    raw_root = source_root if source_root is not None else values.get("input_dir")
    try:
        root = Path(str(raw_root or "")).expanduser()
    except (TypeError, ValueError, OSError, RuntimeError):
        root = Path()

    explicit = str(
        values.get("source_book_name")
        or values.get("source_m4b_book_name")
        or ""
    )
    explicit = re.sub(r"\s+", " ", explicit).strip()
    bound_root = str(values.get("source_book_name_input_dir") or "").strip()
    if explicit:
        same_root = True
        if bound_root and raw_root:
            try:
                same_root = (
                    Path(bound_root).expanduser().resolve()
                    == root.resolve()
                )
            except (TypeError, ValueError, OSError, RuntimeError):
                same_root = False
        if same_root:
            return explicit

    planned = re.sub(r"\s+", " ", str(planned_name or "")).strip()
    if planned:
        return planned

    album = re.sub(r"\s+", " ", str(values.get("tag_album") or "")).strip()
    if album and not re.search(r"\{[^{}]+\}", album):
        return album
    try:
        fallback = root.name
    except (TypeError, ValueError, OSError, RuntimeError):
        fallback = ""
    return fallback or "Книга"


def effective_m4b_duration_limit(
    value,
    *,
    safety_limit=M4B_SAFE_VOLUME_SECONDS,
    cap_unlimited=False,
):
    """Вернуть безопасный лимит тома, не ослабляя явный лимит пользователя.

    Положительный лимит меньше 23:50 имеет приоритет. Больший положительный
    лимит ограничивается, чтобы длинная книга делилась по целым главам до
    объединения. Ноль или пустое значение сохраняет исторический смысл
    «без ограничений», если только ``cap_unlimited=True`` явно не включает
    автоматическое разделение. Отдельная глава всё же может превышать лимит:
    планировщик сохраняет её целиком и сообщает об этом.
    """
    requested = _finite_nonnegative_float(value, default=0.0)
    safe = _finite_nonnegative_float(safety_limit, default=0.0)
    if safe <= 0:
        return requested
    if requested <= 0:
        if not cap_unlimited:
            return 0.0
        return safe
    return min(requested, safe)


def resolve_m4b_auto_duration_limit(
    total_duration_seconds,
    configured_limit=0,
    *,
    threshold_seconds=M4B_AUTO_SPLIT_THRESHOLD_SECONDS,
    safety_limit=M4B_SAFE_VOLUME_SECONDS,
):
    """Определить лимит для автоматического разделения длинной книги M4B.

    ``configured_limit`` сохраняет обычный смысл: положительное значение —
    явный, возможно более строгий лимит тома, ноль — «лимит не задан». Без
    явного лимита книга делится автоматически только при длительности больше
    24 часов, а каждый том ограничивается 23 часами 50 минутами. Явный лимит
    выше защитного также ограничивается. Неверная или неизвестная длительность
    не запускает разделение и оставляет историческое значение без ограничений.

    Функция не обращается к файлам и интерфейсу; синтез и универсальный
    экспортёр вызывают её после собственных измерений длительности.
    """
    total = _finite_nonnegative_float(total_duration_seconds, default=0.0)
    requested = _finite_nonnegative_float(configured_limit, default=0.0)
    threshold = _finite_nonnegative_float(threshold_seconds, default=0.0)
    safe = _finite_nonnegative_float(safety_limit, default=0.0)
    if safe <= 0:
        return requested
    if requested > 0:
        return min(requested, safe)
    if total > threshold:
        return safe
    return 0.0


# Понятные алиасы делают правило доступным для интеграций и не требуют
# зависимости от внутреннего имени ``effective_*``.
automatic_m4b_duration_limit = resolve_m4b_auto_duration_limit
resolve_m4b_volume_limit = resolve_m4b_auto_duration_limit

# ``m4a`` — обычный аудиопоток AAC/MP4, поэтому для него подходит тот же
# профиль, что и для MP3/Opus/Vorbis/WAV. ``m4b`` остаётся целью с главами:
# имя файла, план глав и метаданные тома не являются параметрами аудиопрофиля
# и задаются в редакторе цели. Сам кэш по-прежнему хранится в каноническом
# Ogg/Opus; добавление M4A меняет только слой итогового вывода.
EXPORT_OUTPUT_FORMATS = ("mp3", "wav", "ogg", "opus", "m4a", "m4b")
OUTPUT_TARGET_ASSEMBLY_MODES = ("inherit", "merge", "files")
OUTPUT_TARGET_ASSEMBLY_LABELS = {
    "inherit": "Как у группы",
    "merge": "Один файл",
    "files": "Отдельные файлы",
}
OUTPUT_TARGET_ASSEMBLY_BY_LABEL = {
    label: mode for mode, label in OUTPUT_TARGET_ASSEMBLY_LABELS.items()
}
OUTPUT_TARGET_LIBRARY_SCHEMA = "silero-tts-studio-output-target-library"
OUTPUT_TARGET_LIBRARY_VERSION = 1
# Синтез из папки хранит собственный необязательный список целей. Пустой список
# имеет специальный смысл: выбирается прежний путь одного формата на основе
# ``output_format``/``output_dir``, поэтому старые настройки не меняются.
SYNTHESIS_TARGETS_CONFIG_KEY = "synthesis_targets"
# Это имя сохраняется как алиас для запуска. Принимаются оба ключа; если оба
# содержат непустой список, приоритет имеет ``synthesis_targets``.
SOURCE_OUTPUT_TARGETS_CONFIG_KEY = "source_output_targets"


@dataclass
class OutputTarget:
    """Одна независимая цель мультиформатного вывода.

    Обычные цели одного TXT или группы выполняются последовательно из общего
    снимка кэша; независимые файлы и группы могут кодироваться параллельно.
    Поля остаются простыми JSON-типами, чтобы набор можно было
    экспортировать как профиль без привязки к объектам Tkinter.
    """

    format: str
    output_dir: str = ""
    bitrate: str = "auto"
    sample_rate: str = "auto"
    channels: str = "auto"
    profile: str = ""
    filename_template: str = ""
    chapter_title_template: str = ""
    enabled: bool = True
    apply_effects: bool = False
    effects: dict = field(default_factory=dict)
    split_mode: str = "none"
    max_duration_seconds: float = 0.0
    max_chapters: int = 0
    scope: str = "selected"
    assembly_mode: str = "inherit"
    # Метаданные тома M4B полезны проигрывателям, сортирующим книгу по атому
    # iTunes ``trkn``, но не обязательны для каждого клиента. Сохраняем включённое
    # историческое значение по умолчанию и позволяем цели явно отказаться от него,
    # не меняя границы глав и атом ``disc``.
    include_track_metadata: bool = True

    def normalized(self):
        data = self.to_dict()
        data["format"] = str(data["format"] or "").strip().lower()
        data["bitrate"] = str(data["bitrate"] or "auto").strip().lower()
        data["sample_rate"] = str(data["sample_rate"] or "auto").strip().lower()
        data["channels"] = str(data["channels"] or "auto").strip().lower()
        data["output_dir"] = str(data["output_dir"] or "").strip()
        data["profile"] = str(data["profile"] or "").strip()
        data["filename_template"] = str(data["filename_template"] or "").strip()
        data["chapter_title_template"] = str(
            data["chapter_title_template"] or ""
        ).strip()
        data["enabled"] = _config_bool(data.get("enabled"), default=True)
        data["apply_effects"] = _config_bool(data.get("apply_effects"), default=False)
        data["include_track_metadata"] = _config_bool(
            data.get("include_track_metadata"), default=True
        )
        data["max_duration_seconds"] = _finite_nonnegative_float(
            data.get("max_duration_seconds", 0), default=0.0
        )
        try:
            data["max_chapters"] = max(0, int(data.get("max_chapters", 0) or 0))
        except (TypeError, ValueError, OverflowError):
            data["max_chapters"] = 0
        data["split_mode"] = str(data.get("split_mode") or "none").strip().lower()
        data["scope"] = str(data.get("scope") or "selected").strip().lower()
        data["assembly_mode"] = str(
            data.get("assembly_mode") or "inherit"
        ).strip().lower()
        return data

    def to_dict(self):
        return {
            "format": self.format,
            "output_dir": self.output_dir,
            "bitrate": self.bitrate,
            "sample_rate": self.sample_rate,
            "channels": self.channels,
            "profile": self.profile,
            "filename_template": self.filename_template,
            "chapter_title_template": self.chapter_title_template,
            # Не используем обычный bool(): в переносимом JSON или профиле
            # могут встретиться строки ``"false"`` и ``"true"``.
            "enabled": _config_bool(self.enabled, default=True),
            "apply_effects": _config_bool(self.apply_effects, default=False),
            "effects": copy.deepcopy(self.effects or {}),
            "split_mode": self.split_mode,
            "max_duration_seconds": self.max_duration_seconds,
            "max_chapters": self.max_chapters,
            "scope": self.scope,
            "assembly_mode": self.assembly_mode,
            "include_track_metadata": _config_bool(
                self.include_track_metadata, default=True
            ),
        }


def normalize_output_target(target, *, require_format=True):
    """Нормализует одну цель набора вывода для настроек и переносимого JSON."""
    if isinstance(target, OutputTarget):
        data = target.normalized()
    elif isinstance(target, dict):
        data = OutputTarget(**target).normalized()
    else:
        raise ValueError("цель вывода должна быть объектом")
    if require_format and data["format"] not in EXPORT_OUTPUT_FORMATS:
        raise ValueError(
            "формат цели должен быть одним из: "
            + ", ".join(EXPORT_OUTPUT_FORMATS)
        )
    if data["split_mode"] not in {"none", "duration", "chapters"}:
        raise ValueError(
            "режим разбиения цели должен быть none, duration или chapters"
        )
    if data["scope"] not in {"selected", "group_subfolder"}:
        raise ValueError(
            "область каталога цели должна быть selected или group_subfolder"
        )
    if data["assembly_mode"] not in OUTPUT_TARGET_ASSEMBLY_MODES:
        raise ValueError(
            "режим сборки цели должен быть inherit, merge или files"
        )
    # M4B всегда представляет одну книгу или том с главами. Отдельный M4B на
    # каждый исходный файл не добавляет структуры и противоречит назначению
    # этой цели, поэтому импортированные значения также приводятся к merge.
    if data["format"] == "m4b":
        data["assembly_mode"] = "merge"
    # Режим разделения без соответствующего положительного лимита равен
    # отсутствию разделения. Нормализуем его явно, чтобы импортированный
    # профиль не показывал настройку, которая ничего не делает.
    if data["split_mode"] == "duration" and data["max_duration_seconds"] <= 0:
        data["split_mode"] = "none"
    if data["split_mode"] == "chapters" and data["max_chapters"] <= 0:
        data["split_mode"] = "none"
    if data["format"] == "wav":
        if data["bitrate"] not in {"", "auto"}:
            raise ValueError("для WAV цель должна использовать битрейт auto")
        data["bitrate"] = "auto"
    elif data["bitrate"] != "auto" and not re.fullmatch(
        r"[1-9]\d*k", data["bitrate"]
    ):
        raise ValueError("битрейт цели должен иметь вид 48k либо auto")
    elif data["bitrate"] != "auto":
        bitrate_kbps = int(data["bitrate"][:-1])
        bitrate_limits = {
            "mp3": (8, 320),
            "ogg": (32, 500),
            "opus": (6, 510),
            # Для AAC ниже используется тот же консервативный диапазон,
            # что и в кодировщике M4A/M4B.
            "m4a": (16, 512),
            "m4b": (16, 512),
        }
        limits = bitrate_limits.get(data["format"])
        if limits is not None and not limits[0] <= bitrate_kbps <= limits[1]:
            raise ValueError(
                f"битрейт {data['format'].upper()} должен быть в диапазоне "
                f"{limits[0]}–{limits[1]} кбит/с"
            )
    if data["sample_rate"] not in AUDIO_PROFILE_SAMPLE_RATES:
        raise ValueError("цель содержит неподдерживаемую частоту")
    if data["channels"] not in AUDIO_PROFILE_CHANNELS:
        raise ValueError("цель содержит неподдерживаемый режим каналов")
    effects = data.get("effects")
    if not isinstance(effects, dict):
        raise ValueError("поле effects цели должно быть JSON-объектом")
    allowed_effects = {
        "speed", "pitch", "echo", "echo_delay", "echo_decay"
    }
    unknown_effects = sorted(set(effects) - allowed_effects)
    if unknown_effects:
        raise ValueError(
            "неизвестные поля effects цели: " + ", ".join(unknown_effects)
        )
    normalized_effects = {}
    try:
        speed = float(effects.get("speed", 1.0))
        pitch = float(effects.get("pitch", 1.0))
        delay = int(float(effects.get("echo_delay", 300)))
        decay = float(effects.get("echo_decay", 0.3))
    except (TypeError, ValueError, OverflowError):
        raise ValueError("некорректные числовые эффекты цели") from None
    if not all(math.isfinite(value) for value in (speed, pitch, decay)):
        raise ValueError("эффекты цели не могут содержать NaN или бесконечность")
    if not 0.5 <= speed <= 3.0:
        raise ValueError("скорость эффекта цели должна быть в диапазоне 0.5–3.0")
    if not 0.5 <= pitch <= 2.0:
        raise ValueError("тон эффекта цели должен быть в диапазоне 0.5–2.0")
    if not 50 <= delay <= 1000:
        raise ValueError("задержка эхо цели должна быть в диапазоне 50–1000 мс")
    if not 0.1 <= decay <= 0.8:
        raise ValueError("сила эхо цели должна быть в диапазоне 0.1–0.8")
    normalized_effects.update(
        speed=speed,
        pitch=pitch,
        echo=_config_bool(effects.get("echo", False), default=False),
        echo_delay=delay,
        echo_decay=decay,
    )
    data["effects"] = normalized_effects
    if data["filename_template"]:
        validate_filename_template(
            data["filename_template"],
            TEMPLATE_FIELDS_OUTPUT,
        )
    if data["format"] == "m4b" and data["apply_effects"]:
        # Отклоняем явно включённый ненейтральный эффект уже при проверке или
        # импорте цели. Низкоуровневые помощники FFmpeg повторяют проверку,
        # потому что интеграция может обойти этот нормализатор.
        _validate_m4b_effects_disabled(
            speed=normalized_effects["speed"],
            pitch=normalized_effects["pitch"],
            echo=normalized_effects["echo"],
        )
        # Нейтральный устаревший флаг не меняет закодированный звук, но вводит
        # в заблуждение в сохранённом JSON и может создать впечатление, что
        # эффекты M4B доступны. После проверки удаляем этот флаг; ненейтральное
        # значение уже вызвало понятную ошибку. Так интерфейс, профили и
        # низкоуровневые экспортёры используют одинаковую политику.
        data["apply_effects"] = False
    # Для AAC в M4A/M4B действует консервативный диапазон, общий с проверкой
    # самостоятельных аудиопрофилей. ``auto`` остаётся допустимым и разрешается
    # исполнителем цели (для M4B по умолчанию используется 64 кбит/с).
    if data["format"] in {"m4a", "m4b"} and data["bitrate"] != "auto":
        bitrate_kbps = int(data["bitrate"][:-1])
        if not 16 <= bitrate_kbps <= 512:
            raise ValueError("битрейт AAC/M4A/M4B должен быть 16–512 кбит/с")
    if data["format"] == "m4b":
        if data["chapter_title_template"]:
            validate_filename_template(
                data["chapter_title_template"],
                M4B_CHAPTER_TEMPLATE_FIELDS,
            )
    else:
        # Метки глав существуют только у M4B. Не переносим скрытое значение в
        # другую цель, если пользователь сменил формат строки.
        data["chapter_title_template"] = ""
    return data


def compact_export_output_target(
    *,
    output_format,
    bitrate="auto",
    sample_rate="auto",
    channels="auto",
    apply_effects=False,
    effects=None,
    m4b_bitrate="64k",
    m4b_max_duration_seconds=0,
    m4b_max_chapters=0,
):
    """Преобразует быстрые параметры экспорта в обычную цель одного запуска.

    Цель не предназначена для сохранения в библиотеке: она позволяет пустому
    набору выходов использовать тот же планировщик, проверку путей и пул групп,
    что и явно настроенный набор. M4B всегда объединяет главы и не наследует
    эффекты, недоступные для его временной шкалы.
    """
    fmt = str(output_format or "").strip().lower()
    is_m4b = fmt == "m4b"
    target = OutputTarget(
        format=fmt,
        bitrate=str(m4b_bitrate if is_m4b else bitrate),
        sample_rate=str(sample_rate),
        channels=str(channels),
        apply_effects=bool(apply_effects) and not is_m4b,
        effects=copy.deepcopy(effects or {}),
        max_duration_seconds=(m4b_max_duration_seconds if is_m4b else 0),
        max_chapters=(m4b_max_chapters if is_m4b else 0),
        assembly_mode="merge" if is_m4b else "inherit",
    )
    return normalize_output_target(target)


def normalize_output_target_library(data):
    """Проверяет переносимый JSON набора выходных форматов."""
    if not isinstance(data, dict):
        raise ValueError("библиотека целей вывода должна быть JSON-объектом")
    unknown = sorted(set(data) - {"schema", "version", "name", "targets"})
    if unknown:
        raise ValueError("неизвестные поля библиотеки вывода: " + ", ".join(unknown))
    if data.get("schema") != OUTPUT_TARGET_LIBRARY_SCHEMA:
        raise ValueError("неподдерживаемый формат библиотеки вывода")
    raw_version = data.get("version")
    if isinstance(raw_version, bool) or not isinstance(raw_version, int):
        raise ValueError("версия библиотеки вывода должна быть целым числом")
    if raw_version != OUTPUT_TARGET_LIBRARY_VERSION:
        raise ValueError("неподдерживаемая версия библиотеки вывода")
    targets = data.get("targets")
    if not isinstance(targets, list) or not targets:
        raise ValueError("targets библиотеки вывода должен быть непустым массивом")
    result = []
    for target in targets:
        result.append(normalize_output_target(target))
    # Переносимая библиотека не должна возвращать устаревший абсолютный путь
    # отправителя, если в ней только одна активная цель. В библиотеках с
    # несколькими целями явные каталоги отдельных форматов сохраняются.
    result = list(normalize_output_target_directories(result))
    return {
        "schema": OUTPUT_TARGET_LIBRARY_SCHEMA,
        "version": OUTPUT_TARGET_LIBRARY_VERSION,
        "name": str(data.get("name") or "Набор выходов").strip(),
        "targets": result,
    }


def duplicate_output_target_formats(targets):
    """Возвращает форматы, встречающиеся в наборе более одного раза.

    Планировщик и переносимый JSON намеренно допускают две цели одного
    формата (например, Opus 32 и 48 кбит/с в разные каталоги). Функция
    оставлена как диагностическая вспомогательная функция; редактор целей
    отображает такие записи отдельными строками.
    """
    seen = set()
    duplicates = []
    for target in targets or ():
        if isinstance(target, OutputTarget):
            raw_format = target.format
        elif isinstance(target, dict):
            raw_format = target.get("format", "")
        else:
            continue
        fmt = str(raw_format or "").strip().lower()
        if not fmt:
            continue
        if fmt in seen and fmt not in duplicates:
            duplicates.append(fmt)
        else:
            seen.add(fmt)
    return tuple(duplicates)


def output_target_library_from_targets(targets, *, name="Набор выходов"):
    """Создаёт переносимую библиотеку из включённых целей."""
    normalized = list(
        normalize_output_target_directories(
            [normalize_output_target(item) for item in (targets or ())]
        )
    )
    if not normalized:
        raise ValueError("нельзя сохранить пустой набор выходов")
    return {
        "schema": OUTPUT_TARGET_LIBRARY_SCHEMA,
        "version": OUTPUT_TARGET_LIBRARY_VERSION,
        "name": str(name or "Набор выходов").strip() or "Набор выходов",
        "targets": normalized,
    }


@dataclass
class M4BPart:
    """Запланированная часть M4B, разделённая только по границам глав."""

    number: int
    total: int
    chapter_start: int
    chapter_end: int
    duration_seconds: float
    chapters: list = field(default_factory=list)

    @property
    def first_index(self):
        return self.chapter_start

    @property
    def last_index(self):
        return self.chapter_end


@dataclass(frozen=True)
class M4BReflowDiagnostic:
    """Диагностика главы, которая не помещается в лимит части M4B.

    Автоматическое перестроение не имеет права разрезать главу. Поэтому
    отдельная глава может оказаться длиннее заданного лимита и всё равно
    останется самостоятельной частью. Такие случаи возвращаются вызывающему
    коду явно, чтобы UI мог показать предупреждение, не смешивая его с
    ошибкой синтеза или сборки.
    """

    chapter_id: object
    chapter_index: int
    duration_seconds: float
    limit_seconds: float
    over_by_seconds: float
    source_group_index: int = 0
    reason: str = "chapter_exceeds_limit"

    def to_dict(self):
        """Возвращает безопасное JSON-подобное представление диагностики."""
        return {
            "chapter_id": self.chapter_id,
            "chapter_index": self.chapter_index,
            "duration_seconds": self.duration_seconds,
            "limit_seconds": self.limit_seconds,
            "over_by_seconds": self.over_by_seconds,
            "source_group_index": self.source_group_index,
            "reason": self.reason,
        }


@dataclass(frozen=True)
class M4BReflowResult:
    """Результат чистого перестроения частей M4B.

    ``groups`` содержит кортежи исходных идентификаторов глав в исходном
    порядке. ``oversized`` содержит :class:`M4BReflowDiagnostic` для каждой
    отдельной главы, превышающей лимит. Результат намеренно не содержит
    Tkinter-объектов, путей или вызовов FFmpeg и поэтому пригоден для фонового
    обработчика.
    """

    groups: tuple = ()
    oversized: tuple = ()
    total_duration_seconds: float = 0.0
    limit_seconds: float = 0.0
    pause_seconds: float = 0.0

    @property
    def diagnostics(self):
        """Синоним ``oversized`` для вызывающего кода и UI."""
        return self.oversized

    @property
    def oversized_chapters(self):
        """Более явное имя списка oversized-глав для внешних интеграций."""
        return self.oversized

    def to_dict(self):
        """Сериализует результат без потери порядка групп и диагностик."""
        return {
            "groups": [list(group) for group in self.groups],
            "oversized": [item.to_dict() for item in self.oversized],
            "total_duration_seconds": self.total_duration_seconds,
            "limit_seconds": self.limit_seconds,
            "pause_seconds": self.pause_seconds,
        }


class TemplateError(ValueError):
    """Ошибка безопасного шаблона имени файла."""


_STANDARD_INTEGER_FORMAT_RE = re.compile(r"0?\d*d")
_COUNTER_START_AND_FORMAT_RE = re.compile(
    r"(?P<start>\d+):(?P<number_format>0?\d*d|auto|adaptive)"
)
ADAPTIVE_COUNTER_FORMAT = "__adaptive__"
_ADAPTIVE_COUNTER_FORMAT_ALIASES = frozenset({"00d", "auto", "adaptive"})


def _parse_counter_format_spec(format_spec):
    """Разбирает старт и формат счётчика без изменения старого синтаксиса.

    Пустая строка не задаёт параметров, ``10`` означает начальное значение,
    а ``03d`` — обычную ширину Python с ведущими нулями. Комбинированная
    запись ``10:03d`` применяет оба правила и соответствует пользовательскому
    токену ``{num:10:03d}``.
    """
    value = str(format_spec or "")
    if not value:
        return None, ""
    if re.fullmatch(r"\d+", value):
        try:
            return int(value), ""
        except (ValueError, OverflowError):
            raise TemplateError("начальный номер слишком длинный") from None
    # ``00d`` — короткая форма для адаптивной разрядности. Алиасы ``auto`` и
    # ``adaptive`` оставлены для шаблонов, которые читаются не только людьми,
    # но и внешними настройками. Проверяем их до обычного ``02d``: иначе
    # ``00d`` воспринимался бы как фиксированная ширина два знака.
    if value in _ADAPTIVE_COUNTER_FORMAT_ALIASES:
        return None, ADAPTIVE_COUNTER_FORMAT
    if _STANDARD_INTEGER_FORMAT_RE.fullmatch(value):
        return None, value
    combined = _COUNTER_START_AND_FORMAT_RE.fullmatch(value)
    if combined is not None:
        try:
            start = int(combined.group("start"))
        except (ValueError, OverflowError):
            raise TemplateError("начальный номер слишком длинный") from None
        number_format = combined.group("number_format")
        if number_format in _ADAPTIVE_COUNTER_FORMAT_ALIASES:
            number_format = ADAPTIVE_COUNTER_FORMAT
        return start, number_format
    raise TemplateError(f"спецификатор :{value} не поддерживается")


def _adaptive_counter_width(field_name, raw, context, start=None, offset=0):
    """Подбирает ширину для адаптивного числового заполнителя.

    Планировщики могут передать точные размеры через закрытый словарь
    ``_adaptive_totals``. Для старых снимков остаются понятные резервные
    правила: тома используют ``parts``, файлы и главы — число элементов в
    группе, а главы текущего тома — ``volume_chapter_count``.
    """
    context = context if isinstance(context, Mapping) else {}
    totals = context.get("_adaptive_totals")
    total = None
    if isinstance(totals, Mapping):
        total = totals.get(field_name)
    if total is None:
        if field_name in {"part", "volume"}:
            total = context.get("parts", 1)
        elif field_name == "group_index":
            total = context.get("_group_count", context.get("parts", 1))
        elif field_name == "file_index":
            total = context.get(
                "_file_count",
                context.get("volume_chapter_count", context.get("chapter_count", 1)),
            )
        elif field_name == "volume_index":
            total = context.get(
                "volume_chapter_count", context.get("chapter_count", 1)
            )
        elif field_name == "num":
            # В групповых шаблонах num — номер тома/группы, в шаблонах
            # отдельных файлов и глав — позиция элемента.
            if context.get("num") == context.get("part"):
                total = context.get("parts", 1)
            else:
                total = context.get("chapter_count", 1)
        else:
            total = context.get("chapter_count", 1)
    try:
        total = max(1, int(total or 1))
    except (TypeError, ValueError, OverflowError):
        total = 1
    try:
        current = int(raw)
    except (TypeError, ValueError, OverflowError):
        current = 1
    try:
        if start is not None:
            first = int(start)
        else:
            # При явном контексте текущий номер может быть не первым в серии
            # (например, файл 9 из 9). Смещение рендера восстанавливает
            # начало последовательности и не создаёт лишний ноль на границе.
            first = current - int(offset or 0)
    except (TypeError, ValueError, OverflowError):
        first = current
    last = first + total - 1
    return max(1, len(str(max(abs(current), abs(first), abs(last)))))


def validate_filename_template(template, allowed_fields):
    """Проверяет шаблон и возвращает используемые поля.

    Разрешены только простые имена полей и числовые спецификаторы (`:02d`,
    ``:04d``). ``:00d`` (а также ``:auto``) включает адаптивную разрядность
    по общему диапазону счётчика. Для счётчиков меток M4B обычное число после двоеточия (``:10``)
    означает начальное значение; суффикс `d` сохраняет обычное форматирование.
    Запись ``:10:03d`` сочетает старт с 10 и трёхзначное представление.
    Доступ к атрибутам/индексам (`{x.__class__}`, `{x[0]}`) и неизвестные
    токены блокируются до запуска фонового обработчика. `{{` и `}}` остаются обычными
    экранированными скобками Python Formatter.
    """
    template = str(template or "")
    allowed = {str(item) for item in (allowed_fields or ())}
    fields = []
    formatter = string.Formatter()
    try:
        parsed = formatter.parse(template)
        for _literal, field_name, format_spec, conversion in parsed:
            if field_name is None:
                continue
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", field_name):
                raise TemplateError(
                    f"поле {{{field_name}}} должно быть простым именем"
                )
            if field_name not in allowed:
                raise TemplateError(
                    f"поле {{{field_name}}} недоступно в этом контексте"
                )
            if conversion not in (None, "s"):
                raise TemplateError(
                    f"преобразование !{conversion} не поддерживается"
                )
            if format_spec and not (
                re.fullmatch(r"0?\d*d?", format_spec)
                or format_spec in _ADAPTIVE_COUNTER_FORMAT_ALIASES
                or _COUNTER_START_AND_FORMAT_RE.fullmatch(format_spec)
            ):
                raise TemplateError(
                    f"спецификатор :{format_spec} не поддерживается"
                )
            fields.append(field_name)
    except TemplateError:
        raise
    except ValueError as exc:
        raise TemplateError(f"некорректные фигурные скобки: {exc}") from exc
    return tuple(dict.fromkeys(fields))


def render_filename_template(template, context, allowed_fields=None):
    """Рендерит шаблон после строгой проверки полей.

    Санитизация выполняется вызывающей стороной после рендера, потому что
    один и тот же механизм используется и для имени файла, и для предпросмотра.
    """
    # Используем тот же рендерер, что и рабочие цели. Это важно для записи
    # ``{volume:1:02d}``: обычный Formatter не понимает составной формат
    # стартового значения и разрядности.
    return render_output_file_template(template, context, allowed_fields)


def render_output_file_template(template, context, allowed_fields=None):
    """Рендерит имя результата с поддержкой старта и ведущих нулей.

    В шаблонах целей ``{index:N}`` задаёт первое отображаемое значение, а
    ``{index:03d}`` только ширину. Для одного файла смещение равно нулю;
    планировщик передаёт фактический индекс в самом контексте.
    """
    context = dict(context or {})
    if "filename" not in context:
        context["filename"] = str(
            context.get("source_name")
            or context.get("source_title")
            or context.get("name")
            or ""
        )
    offsets = {}
    # Все позиционные поля поддерживают одинаковый синтаксис ``:N`` и
    # ``:N:03d``. Значение контекста уже содержит фактическую позицию, поэтому
    # стартовый номер применяется относительно неё, а не только к ``index``.
    for field_name in (
        "index", "chapter", "num", "part", "volume",
        "group_index", "file_index",
    ):
        try:
            position = int(context.get(field_name, 1) or 1)
        except (TypeError, ValueError, OverflowError):
            position = 1
        offsets[field_name] = max(0, position - 1)
    return render_template_with_counter_starts(
        template,
        context,
        allowed_fields or TEMPLATE_FIELDS_OUTPUT,
        offsets,
    )


def render_template_with_counter_starts(
    template,
    context,
    allowed_fields,
    counter_offsets=None,
):
    """Рендерит шаблон с поддержкой начального значения счётчиков.

    Обычный числовой спецификатор без ``d`` задаёт первое отображаемое
    значение: при нулевом смещении ``{volume:10}`` даёт 10, а при смещении
    следующего тома — 11. Спецификатор с ``d`` остаётся стандартным
    форматированием Python, поэтому ``{volume:03d}`` даёт 001, 002 и далее.
    """
    value = str(template or "")
    context = dict(context or {})
    allowed = set(allowed_fields or context.keys())
    fields = validate_filename_template(value, allowed)
    missing = [field_name for field_name in fields if field_name not in context]
    if missing:
        raise TemplateError("нет значения для поля: " + ", ".join(missing))
    offsets = dict(counter_offsets or {})
    formatter = string.Formatter()
    output = []
    try:
        for literal, field_name, format_spec, conversion in formatter.parse(value):
            output.append(literal)
            if field_name is None:
                continue
            raw = context[field_name]
            if field_name in offsets and format_spec:
                start, number_format = _parse_counter_format_spec(format_spec)
                if start is not None:
                    raw = start + max(0, int(offsets[field_name]))
                    format_spec = number_format
                if number_format == ADAPTIVE_COUNTER_FORMAT:
                    format_spec = "0{}d".format(
                        _adaptive_counter_width(
                            field_name,
                            raw,
                            context,
                            start=start,
                            offset=offsets.get(field_name, 0),
                        )
                    )
            converted = formatter.convert_field(raw, conversion)
            output.append(formatter.format_field(converted, format_spec))
        return "".join(output)
    except (KeyError, ValueError, IndexError, TypeError, OverflowError) as exc:
        raise TemplateError(f"не удалось применить шаблон: {exc}") from exc


def render_m4b_part_template(template, context, allowed_fields=None):
    """Рендерит имя или тег части M4B с настраиваемым номером тома."""
    context = dict(context or {})
    if "filename" not in context:
        context["filename"] = str(
            context.get("first_name")
            or context.get("source_name")
            or context.get("source_title")
            or context.get("name")
            or ""
        )
    try:
        part_number = int(
            context.get("volume", context.get("part", context.get("num", 1)))
            or 1
        )
    except (TypeError, ValueError, OverflowError):
        part_number = 1
    part_offset = max(0, part_number - 1)
    def context_offset(field_name, fallback):
        try:
            return max(0, int(context.get(field_name, fallback) or fallback) - 1)
        except (TypeError, ValueError, OverflowError):
            return max(0, int(fallback) - 1)
    return render_template_with_counter_starts(
        template,
        context,
        allowed_fields or context.keys(),
        {
            "volume": part_offset,
            "part": part_offset,
            "num": part_offset,
            "index": part_offset,
            "group_index": context_offset("group_index", part_number),
            "file_index": context_offset("file_index", 1),
        },
    )


# Метаданные M4B (в отличие от имени файла) могут содержать знаки препинания и
# пробелы, но для них полезен тот же небольшой язык заполнителей. Помощник
# остаётся чистым, чтобы фоновая задача могла использовать его без создания
# виджета Tk. ``None`` означает «использовать значение вызывающего
# кода», а явная пустая строка — «не записывать переопределение».
SOURCE_M4B_TEMPLATE_FIELDS = frozenset(
    set(TEMPLATE_FIELDS_OUTPUT) | {"num", "first", "last"}
)

# Поля, которые действительно меняются от одной части книги к другой.
# ``{parts}`` и ``{chapter_count}`` сами по себе содержат только общее
# количество и поэтому не предотвращают коллизию имён. Если пользователь
# задал статический шаблон (например, просто ``{book}``) для нескольких M4B,
# планировщик добавит к имени детерминированный суффикс ``Часть N``.
M4B_UNIQUE_PART_TEMPLATE_FIELDS = frozenset(
    {
        "part",
        "volume",
        "index",
        "chapter",
        "first_index",
        "last_index",
        "range",
        "first_name",
        "last_name",
        # Алиасы, поддерживаемые шаблоном вкладки «Синтез из папки».
        "num",
        "first",
        "last",
    }
)

# Эти алиасы могут быть уникальны между виртуальными группами исходников, но
# остаются одинаковыми при разбиении одной экспортной группы на несколько
# томов. Поэтому они учитываются только когда конкретный планировщик уже
# проверил уникальность фактических имён групп.
M4B_GROUP_NAME_TEMPLATE_FIELDS = frozenset(
    {"name", "group", "title", "source_name", "source_title"}
)


def render_m4b_album_template(template, context, *, fallback=""):
    """Рендерит шаблон альбома M4B без санитизации имени файла.

    ``template`` может быть пустым, если вызывающий код намеренно оставляет тег
    альбома пустым или без изменений. Отсутствующее значение (``None``) берёт
    переданный ``fallback``. Та же проверка заполнителей, что и для имён файлов,
    запрещает случайный доступ к атрибутам или индексам в переносимых настройках.
    """
    if template is None:
        return str(fallback or "").strip()
    value = str(template)
    if not value.strip():
        return ""
    rendered = render_m4b_part_template(
        value,
        context,
        SOURCE_M4B_TEMPLATE_FIELDS,
    )
    return str(rendered or "").strip()


def render_m4b_chapter_title(template, context, *, fallback="Глава"):
    """Рендерит одну пользовательскую метку главы M4B.

    Пустой шаблон сохраняет исходное название. Метка является текстовыми
    метаданными, поэтому файловая санитизация ей не нужна; переносы и лишние
    пробелы сворачиваются, чтобы проигрыватели показывали одну аккуратную
    строку.
    """
    fallback_text = re.sub(r"\s+", " ", str(fallback or "")).strip() or "Глава"
    value = str(template or "")
    context = dict(context or {})
    if "filename" not in context:
        context["filename"] = str(
            context.get("first_name")
            or context.get("source_name")
            or context.get("source_title")
            or context.get("name")
            or ""
        )
    if not value.strip():
        return fallback_text
    # У меток глав M4B есть небольшое расширение обычного синтаксиса Python.
    # Простое десятичное число после двоеточия задаёт старт, как в существующем
    # соглашении ``{num:N}`` для импорта и имён групп: ``{global_index:10}``
    # начинает шкалу книги с 10 и продолжает её по глобальным позициям, а
    # ``{volume_index:10}`` заново начинает с 10 в каждом томе и увеличивается
    # по локальному порядку. Спецификатор с завершающей ``d`` сохраняет обычное
    # форматирование ширины и ведущих нулей (например, ``:03d``), а
    # ``:10:03d`` сочетает оба режима.
    #
    # Поля рендерим вручную, а не переписываем шаблон: два вхождения могут
    # законно иметь разные начальные значения в одной метке. Formatter.parse
    # по-прежнему обрабатывает экранированные фигурные скобки как раньше.
    formatter = string.Formatter()
    allowed = M4B_CHAPTER_TEMPLATE_FIELDS
    fields = validate_filename_template(value, allowed)
    missing = [field_name for field_name in fields if field_name not in context]
    if missing:
        raise TemplateError("нет значения для поля: " + ", ".join(missing))
    counter_fields = {
        "global_index",
        "index",
        "chapter",
        "num",
        "volume_index",
        "part",
        "volume",
        "group_index",
        "file_index",
    }

    def integer_value(raw, field_name):
        try:
            return int(raw)
        except (TypeError, ValueError, OverflowError):
            raise TemplateError(
                f"счётчик {field_name} должен быть целым числом"
            ) from None

    def counter_offset(field_name, raw):
        # Рендерер добавляет эти закрытые значения контекста, чтобы явные
        # индексы глав (в том числе с пропуском) сохраняли настоящий глобальный
        # сдвиг.
        if field_name == "volume_index":
            # При одиночном вызове метаданных последовательности нет, поэтому
            # первый элемент получает нулевой сдвиг. Пакетный помощник всегда
            # передаёт закрытый сдвиг и сохраняет непрерывность между томами.
            fallback = 0
            return max(
                0,
                integer_value(context.get("_volume_offset", fallback), field_name),
            )
        if field_name in {"part", "volume"}:
            return max(0, integer_value(context.get("part", 1), field_name) - 1)
        if field_name == "group_index":
            return max(
                0,
                integer_value(context.get("group_index", 1), field_name) - 1,
            )
        if field_name == "file_index":
            return max(
                0,
                integer_value(context.get("file_index", 1), field_name) - 1,
            )
        fallback = 0
        return max(
            0,
            integer_value(context.get("_global_offset", fallback), field_name),
        )

    output = []
    try:
        parsed = formatter.parse(value)
        for literal, field_name, format_spec, conversion in parsed:
            output.append(literal)
            if field_name is None:
                continue
            raw = context[field_name]
            if field_name in counter_fields and format_spec:
                start, number_format = _parse_counter_format_spec(format_spec)
                if start is not None:
                    raw = start + counter_offset(field_name, raw)
                    format_spec = number_format
                if number_format == ADAPTIVE_COUNTER_FORMAT:
                    adaptive_offset = counter_offset(field_name, raw)
                    format_spec = "0{}d".format(
                        _adaptive_counter_width(
                            field_name,
                            raw,
                            context,
                            start=start,
                            offset=adaptive_offset,
                        )
                    )
            converted = formatter.convert_field(raw, conversion)
            output.append(formatter.format_field(converted, format_spec))
        rendered = "".join(output)
    except TemplateError:
        raise
    except (KeyError, ValueError, IndexError, TypeError, OverflowError) as exc:
        raise TemplateError(f"не удалось применить шаблон: {exc}") from exc
    return re.sub(r"\s+", " ", str(rendered or "")).strip() or fallback_text


def render_m4b_chapter_titles(
    chapters,
    template,
    *,
    book,
    group="",
    part=1,
    parts=1,
    chapter_start=1,
    chapter_count=None,
    profile="",
    author="",
    global_start=None,
    global_offset=None,
    group_index=None,
):
    """Возвращает копии глав с метками по единому M4B-шаблону.

    ``chapter_start`` задаёт сквозной номер первой главы текущего тома.
    Явный ``index`` в записи главы имеет приоритет, поэтому уже рассчитанный
    план экспорта сохраняет общую нумерацию после разбиения. Явный
    ``global_index`` имеет то же значение. ``volume_index`` начинается с 1 в
    каждом переданном томе и не зависит от его номера. ``global_start`` задаёт
    номер первой главы всей книги для пользовательского стартового
    спецификатора (`{global_index:N}`). Если параметр не указан, текущая
    последовательность считается самостоятельной и начинается с
    ``chapter_start``; внутренние вызовы сборщика передают начало книги, чтобы
    сквозной счётчик продолжался между томами. ``global_offset`` предназначен
    для экспортёра: если он передан (включая нулевое значение), главы
    нумеруются по порядку внутри текущей части и получают это смещение перед
    первой главой. Это не зависит от локальных полей ``index`` в части и
    поэтому корректно работает, когда одна группа автоматически разделена на
    несколько M4B-файлов. Обычным вызывающим функциям его задавать не нужно.
    """
    source_items = list(chapters or ())

    def positive_int(value, fallback):
        try:
            value = int(value)
        except (TypeError, ValueError, OverflowError):
            value = int(fallback)
        return max(1, value)

    first_index = positive_int(chapter_start, 1)
    has_global_offset = global_offset is not None
    if has_global_offset:
        try:
            global_offset = int(global_offset or 0)
        except (TypeError, ValueError, OverflowError):
            global_offset = 0
        # Отрицательный сдвиг возможен только в повреждённом снимке интеграции;
        # не позволяем ему породить неположительный номер главы.
        global_offset = max(0, global_offset)
    if global_start is None:
        global_origin = first_index
    else:
        global_origin = positive_int(global_start, first_index)
    part_number = positive_int(part, 1)
    part_count = max(part_number, positive_int(parts, part_number))
    group_number = positive_int(group_index, part_number)
    # Если вызывающий код не указал ``chapter_count``, используем наибольшую
    # явную позицию в источнике как дополнительную нижнюю границу. В импортном
    # или старом плане может быть пропуск (например, главы 7 и 9); число 8 в
    # качестве итога противоречило бы видимой глобальной нумерации
    # ``{chapter_count}``. Для непрерывной последовательности расчёт прежний.
    explicit_positions = []
    for raw_chapter in source_items:
        if not isinstance(raw_chapter, dict):
            continue
        try:
            position = int(raw_chapter.get("global_index", raw_chapter.get("index")))
        except (TypeError, ValueError, OverflowError):
            continue
        if position > 0:
            explicit_positions.append(position)
    minimum_count = max(
        first_index + max(0, len(source_items) - 1),
        max(explicit_positions, default=0),
    )
    total_count = max(
        minimum_count,
        positive_int(chapter_count, minimum_count or 1),
    )
    book_name = re.sub(r"\s+", " ", str(book or "Книга")).strip() or "Книга"
    group_name = re.sub(r"\s+", " ", str(group or book_name)).strip() or book_name
    volume_chapter_count = len(source_items)
    rendered_items = []
    for offset, raw_chapter in enumerate(source_items):
        if isinstance(raw_chapter, dict):
            chapter = copy.deepcopy(raw_chapter)
        else:
            try:
                raw_title, raw_duration = raw_chapter
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    "глава должна быть dict или парой title,duration"
                ) from exc
            chapter = {"title": raw_title, "duration": raw_duration}

        # Планировщик мог уже добавить явную глобальную позицию. При наличии
        # предпочитаем описательное поле, сохраняя историческое поле ``index``
        # для старых снимков.
        explicit_global_index = chapter.get("global_index")
        if explicit_global_index is None:
            explicit_global_index = chapter.get("index")
        if has_global_offset:
            # ``global_offset`` — это начало последовательности, а не
            # арифметическая поправка к уже глобальному ``index``. Последний
            # часто локален для вручную разделённой части (1, 2, …), и сложение
            # начала с ним пропустило бы номера на каждой границе. Используем
            # порядковый номер внутри этой части; обычная ветка ниже сохраняет
            # историческое поведение явного индекса в плане исходников.
            global_index = max(1, 1 + offset + global_offset)
        else:
            local_global_index = positive_int(
                explicit_global_index,
                first_index + offset,
            )
            global_index = local_global_index
        original_title = re.sub(
            r"\s+",
            " ",
            str(chapter.get("title") or f"Глава {global_index}"),
        ).strip() or f"Глава {global_index}"
        source_title = re.sub(
            r"\s+",
            " ",
            str(chapter.get("source_title") or original_title),
        ).strip() or original_title
        source_name = str(chapter.get("source_name") or "").strip()
        if not source_name and chapter.get("path"):
            try:
                source_name = Path(chapter["path"]).stem
            except (TypeError, ValueError, OSError):
                source_name = ""
        source_name = re.sub(r"\s+", " ", source_name).strip() or source_title
        try:
            file_number = int(
                chapter.get(
                    "file_index",
                    chapter.get("chapter_index", offset + 1),
                )
            )
        except (TypeError, ValueError, OverflowError):
            file_number = offset + 1
        file_number = max(1, file_number)
        context = {
            "name": original_title,
            "title": original_title,
            "source_name": source_name,
            "source_title": source_title,
            "chapter_title": original_title,
            "global_index": global_index,
            "volume_index": offset + 1,
            "index": global_index,
            "chapter": global_index,
            "num": global_index,
            "chapter_count": total_count,
            "volume_chapter_count": volume_chapter_count,
            "group_index": group_number,
            "file_index": file_number,
            "book": book_name,
            "group": group_name,
            "part": part_number,
            "volume": part_number,
            "parts": part_count,
            "format": "m4b",
            "ext": "m4b",
            "profile": str(profile or ""),
            "author": str(author or ""),
            # Закрытые сдвиги намеренно не являются заполнителями: они лишь
            # дают рендереру сведения для пользовательского старта после
            # двоеточия, не расширяя публичный словарь шаблона.
            "_global_base": global_origin,
            "_global_offset": global_index - global_origin,
            "_volume_offset": offset,
        }
        chapter["title"] = render_m4b_chapter_title(
            template,
            context,
            fallback=original_title,
        )
        rendered_items.append(chapter)
    return rendered_items


def source_m4b_metadata_context(config=None, record=None, output_path=None):
    """Строит стабильный контекст ``{book}``/``{part}`` для M4B-тегов.

    Планировщик исходников сохраняет индексы глав в каждой записи отложенного
    этапа. Адаптер принимает и неполные записи, сохраняя совместимость прямых
    вызовов и старых переносимых снимков.
    """
    config = config if isinstance(config, dict) else {}
    record = record if isinstance(record, dict) else {}
    path = Path(str(output_path or record.get("path", "Книга.m4b")))
    book = resolve_source_book_name(
        config,
        config.get("input_dir"),
        record.get("book"),
    )
    try:
        part = int(record.get("group_index", record.get("part", 1)) or 1)
    except (TypeError, ValueError, OverflowError):
        part = 1
    part = max(1, part)
    try:
        parts = int(
            record.get(
                "parts",
                config.get("source_m4b_parts_count", part),
            )
            or part
        )
    except (TypeError, ValueError, OverflowError):
        parts = part
    parts = max(part, parts)
    try:
        first_index = int(record.get("chapter_start", 1) or 1)
    except (TypeError, ValueError, OverflowError):
        first_index = 1
    try:
        last_index = int(record.get("chapter_end", first_index) or first_index)
    except (TypeError, ValueError, OverflowError):
        last_index = first_index
    first_index = max(1, first_index)
    last_index = max(first_index, last_index)
    try:
        chapter_count = int(
            record.get("chapter_count", config.get("source_m4b_chapter_count", last_index))
            or last_index
        )
    except (TypeError, ValueError, OverflowError):
        chapter_count = last_index
    chapter_count = max(last_index, chapter_count)
    first_name = ""
    last_name = ""
    source_paths = tuple(record.get("source_paths", ()) or ())
    if source_paths:
        first_name = Path(str(source_paths[0])).stem
        last_name = Path(str(source_paths[-1])).stem
    target = record.get("target")
    if isinstance(target, OutputTarget):
        target = target.normalized()
    if not isinstance(target, dict):
        target = {}
    return {
        "book": book,
        "name": str(record.get("group_name") or book),
        "group": str(record.get("group_name") or book),
        "title": str(record.get("group_name") or book),
        "source_name": str(record.get("group_name") or book),
        "source_title": str(record.get("group_name") or book),
        "num": part,
        "index": part,
        "group_index": part,
        "file_index": 1,
        "chapter": first_index,
        "chapter_count": chapter_count,
        "part": part,
        "volume": part,
        "parts": parts,
        "first_index": first_index,
        "last_index": last_index,
        "first": first_index,
        "last": last_index,
        "range": format_chapter_range(
            first_index,
            last_index,
            total_count=chapter_count,
        ),
        "first_name": first_name,
        "last_name": last_name,
        "format": "m4b",
        "profile": str(target.get("profile", "")),
        "ext": "m4b",
        "author": "",
        "filename": first_name or path.stem,
    }


def adaptive_number_width(total_count, last_index=None, start_index=1):
    """Возвращает стабильную ширину номера для всей книги/серии."""
    try:
        total_count = max(1, int(total_count))
    except (TypeError, ValueError):
        total_count = 1
    try:
        start_index = int(start_index)
    except (TypeError, ValueError):
        start_index = 1
    if last_index is None:
        last_index = start_index + total_count - 1
    try:
        last_index = int(last_index)
    except (TypeError, ValueError):
        last_index = start_index + total_count - 1
    # ``total_count`` обычно является количеством глав во всей книге. Даже
    # если текущая часть содержит 1--10 из 100, ширина должна остаться
    # трёхзначной, иначе имена частей будут прыгать от `01` к `001`.
    global_last = max(
        abs(last_index),
        abs(start_index + total_count - 1),
        abs(total_count),
    )
    return max(1, len(str(global_last)))


def format_adaptive_index(number, total_count, *, last_index=None, start_index=1, width=None):
    """Форматирует порядковый номер с ведущими нулями по общему контексту."""
    number = int(number)
    width = int(width or adaptive_number_width(total_count, last_index, start_index))
    width = max(1, width)
    sign = "-" if number < 0 else ""
    return sign + str(abs(number)).zfill(width)


def format_chapter_range(first_index, last_index, total_count=None, *, width=None):
    """Возвращает диапазон с адаптивной шириной номера для имени M4B."""
    first_index = int(first_index)
    last_index = int(last_index)
    if width is None:
        width = adaptive_number_width(
            total_count or max(first_index, last_index),
            last_index=max(first_index, last_index),
            start_index=min(first_index, last_index),
        )
    return (
        format_adaptive_index(first_index, max(1, total_count or last_index), width=width)
        + "-"
        + format_adaptive_index(last_index, max(1, total_count or last_index), width=width)
    )


def _source_node_id(kind, relative_path):
    normalized = PurePosixPath(str(relative_path or ".")).as_posix()
    if normalized == ".":
        normalized = ""
    return f"{kind}:{normalized}"


def scan_source_tree(root, *, include_hidden=False, extensions=(".txt",)):
    """Строит дерево физических подпапок без обхода симлинков.

    Возвращается корневой ``SourceNode``. Порядок детей стабилен и использует
    естественную сортировку. Ошибки чтения отдельных каталогов не скрываются:
    вызывающий код получает понятное исключение до начала синтеза.
    """
    root_path = Path(root).expanduser().resolve()
    if not root_path.is_dir():
        raise ValueError(f"папка источников не существует: {root_path}")
    suffixes = {str(ext).lower() for ext in extensions}

    def natural_key(value):
        return [int(part) if part.isdigit() else part.casefold() for part in re.split(r"(\d+)", str(value))]

    def build(directory, relative="", parent_id=""):
        name = directory.name if relative else directory.name
        node = SourceNode(
            id=_source_node_id("dir", relative),
            kind="directory",
            name=name,
            relative_path=PurePosixPath(relative).as_posix() if relative else "",
            path=str(directory),
            parent_id=parent_id,
        )
        try:
            entries = list(os.scandir(directory))
        except OSError as exc:
            raise OSError(f"не удалось прочитать каталог {directory}: {exc}") from exc
        entries.sort(key=lambda entry: natural_key(entry.name))
        for entry in entries:
            if entry.is_symlink():
                continue
            if not include_hidden and entry.name.startswith("."):
                continue
            child_relative = f"{relative}/{entry.name}" if relative else entry.name
            try:
                is_dir = entry.is_dir(follow_symlinks=False)
                is_file = entry.is_file(follow_symlinks=False)
            except OSError as exc:
                logging.warning("Пропущен недоступный источник %s: %s", entry.path, exc)
                continue
            if is_dir:
                child = build(Path(entry.path), child_relative, node.id)
                if child.children:
                    node.children.append(child)
            elif is_file and Path(entry.name).suffix.lower() in suffixes:
                child = SourceNode(
                    id=_source_node_id("file", child_relative),
                    kind="text_file",
                    name=entry.name,
                    relative_path=PurePosixPath(child_relative).as_posix(),
                    path=str(Path(entry.path).resolve()),
                    parent_id=node.id,
                )
                node.children.append(child)
        return node

    return build(root_path)


def flatten_source_tree(node):
    """Возвращает листья дерева в стабильном порядке."""
    result = []
    for child in node.children:
        if isinstance(child, SourceNode):
            result.extend(flatten_source_tree(child) if child.is_group else [child])
    return result


def source_tree_to_dict(node):
    """Сериализует дерево источников для профиля сеанса или сопутствующего файла."""
    if not isinstance(node, SourceNode):
        raise TypeError("ожидался SourceNode")
    result = node.to_dict()
    result["children"] = [
        source_tree_to_dict(child) for child in node.children if isinstance(child, SourceNode)
    ]
    return result


def merge_metadata_overrides(*layers):
    """Объединяет теги от глобального уровня к ближайшей группе.

    Отсутствующий ключ означает наследование, а явная пустая строка —
    намеренную очистку. Это важно для групповых тегов и не влияет на ключ кэша.
    """
    result = {}
    for layer in layers:
        if not isinstance(layer, dict):
            continue
        for key, value in layer.items():
            if key in SOURCE_TAG_FIELDS:
                result[key] = copy.deepcopy(value)
    return result


def effective_source_tags(global_tags, ancestors=(), file_overrides=None):
    """Возвращает эффективные теги файла по цепочке наследования."""
    layers = [global_tags]
    layers.extend(ancestors or ())
    layers.append(file_overrides or {})
    return merge_metadata_overrides(*layers)


def plan_source_output_paths(source_root, output_root, files, *, mirror_relative=True, extension="mp3"):
    """Строит и проверяет выходные пути для рекурсивного синтеза."""
    source_root = Path(source_root).expanduser().resolve()
    output_root = Path(output_root).expanduser()
    extension = str(extension or "mp3").lstrip(".").lower()
    planned = []
    seen = {}
    for item in files or ():
        path = Path(item.path if isinstance(item, SourceNode) else item).expanduser().resolve()
        try:
            relative = path.relative_to(source_root)
        except ValueError as exc:
            raise ValueError(f"источник находится вне корневой папки: {path}") from exc
        stem = sanitize_filename_component(path.stem, fallback="Без названия")
        parent = relative.parent if mirror_relative else Path(".")
        target = output_root / parent / f"{stem}.{extension}"
        key = str(target).casefold()
        if key in seen:
            raise ValueError(
                f"совпадающие выходные имена: {seen[key]} и {path} -> {target}"
            )
        seen[key] = str(path)
        planned.append((str(path), target))
    return tuple(planned)


def escape_ffmetadata_value(value):
    """Экранирует значение для FFmpeg ffmetadata (UTF-8)."""
    text = str(value if value is not None else "")
    text = text.replace("\\", "\\\\")
    text = text.replace("\n", "\\n").replace("\r", "\\r")
    text = text.replace("=", "\\=").replace(";", "\\;").replace("#", "\\#")
    return text


def build_ffmetadata_chapters(
    chapters,
    *,
    timebase="1/1000",
    metadata=None,
):
    """Создаёт содержимое ffmetadata с точными границами глав.

    ``chapters`` принимает записи ``{title, start, end}`` либо пары
    ``(title, duration_seconds)``. Временная шкала округляется только при
    финальной записи в миллисекунды; накопление выполняется в float.
    """
    lines = [";FFMETADATA1"]
    for key, value in (metadata or {}).items():
        if value not in (None, ""):
            lines.append(f"{key}={escape_ffmetadata_value(value)}")
    current = 0.0
    for index, chapter in enumerate(chapters or (), 1):
        if isinstance(chapter, dict):
            title = chapter.get("title", f"Глава {index}")
            start = chapter.get("start")
            end = chapter.get("end")
            duration = chapter.get("duration")
        else:
            try:
                title, duration = chapter
            except (TypeError, ValueError) as exc:
                raise ValueError("глава должна быть dict или парой title,duration") from exc
            start = end = None
        if start is None:
            start = current
        try:
            start = float(start)
        except (TypeError, ValueError, OverflowError):
            raise ValueError(f"у главы {index} некорректный START") from None
        if not math.isfinite(start) or start < 0:
            raise ValueError(f"у главы {index} START должен быть конечным")
        if end is None:
            if duration is None:
                raise ValueError(f"у главы {index} нет duration/end")
            duration = _finite_nonnegative_float(duration, default=-1.0)
            if duration < 0:
                raise ValueError(f"у главы {index} некорректная duration")
            end = start + duration
        try:
            end = float(end)
        except (TypeError, ValueError, OverflowError):
            raise ValueError(f"у главы {index} некорректный END") from None
        if not math.isfinite(end):
            raise ValueError(f"у главы {index} END должен быть конечным")
        start_ms = max(0, int(round(start * 1000)))
        end_ms = max(start_ms + 1, int(round(end * 1000)))
        lines.extend(
            [
                "[CHAPTER]",
                f"TIMEBASE={timebase}",
                f"START={start_ms}",
                f"END={end_ms}",
                f"title={escape_ffmetadata_value(title)}",
            ]
        )
        current = end
    return "\n".join(lines) + "\n"


def plan_m4b_parts(
    chapters,
    *,
    max_duration_seconds=0,
    max_chapters=0,
    pause_seconds=0,
    auto_split_long=False,
    auto_split_threshold_seconds=M4B_AUTO_SPLIT_THRESHOLD_SECONDS,
):
    """Делит главы на части без разрезания отдельной главы.

    ``pause_seconds`` учитывает вставляемую между главами
    паузу только при расчёте границы части. Исходные
    длительности глав не меняются, чтобы FFmetadata не добавила
    ту же паузу дважды.
    """
    normalized = []
    for index, chapter in enumerate(chapters or (), 1):
        if isinstance(chapter, dict):
            try:
                duration = float(chapter.get("duration", 0) or 0)
            except (TypeError, ValueError, OverflowError):
                duration = 0.0
            item = copy.deepcopy(chapter)
        else:
            title, raw_duration = chapter
            try:
                duration = float(raw_duration or 0)
            except (TypeError, ValueError, OverflowError):
                duration = 0.0
            item = {"title": title, "duration": duration}
        if not math.isfinite(duration) or duration < 0:
            duration = 0.0
        item.setdefault("index", index)
        item["duration"] = max(0.0, duration)
        normalized.append(item)
    if not normalized:
        return tuple()
    # ``0`` остаётся явным значением без ограничений, пока вызывающий код не
    # включит правило для длинных книг. Оно сначала вычисляет полную
    # длительность глав и применяет защитный лимит 23:50 лишь после 24 часов.
    duration_limit = _finite_nonnegative_float(max_duration_seconds, default=0.0)
    pause_seconds = _finite_nonnegative_float(pause_seconds, default=0.0)
    if auto_split_long:
        measured_total = sum(item["duration"] for item in normalized)
        measured_total += max(0, len(normalized) - 1) * pause_seconds
        duration_limit = resolve_m4b_auto_duration_limit(
            measured_total,
            duration_limit,
            threshold_seconds=auto_split_threshold_seconds,
        )
    try:
        chapter_limit = max(0, int(max_chapters or 0))
    except (TypeError, ValueError, OverflowError):
        chapter_limit = 0
    chunks = []
    current = []
    current_duration = 0.0
    for item in normalized:
        duration_with_separator = (
            current_duration
            + (pause_seconds if current else 0.0)
            + item["duration"]
        )
        would_exceed_duration = (
            duration_limit > 0
            and current
            and duration_with_separator > duration_limit
        )
        would_exceed_count = chapter_limit > 0 and current and len(current) >= chapter_limit
        if would_exceed_duration or would_exceed_count:
            chunks.append(current)
            current = []
            current_duration = 0.0
        elif current:
            current_duration += pause_seconds
        current.append(item)
        current_duration += item["duration"]
    if current:
        chunks.append(current)
    total = len(chunks)
    result = []
    for part_number, items in enumerate(chunks, 1):
        result.append(
            M4BPart(
                number=part_number,
                total=total,
                chapter_start=int(items[0].get("index", 1)),
                chapter_end=int(items[-1].get("index", len(items))),
                duration_seconds=(
                    sum(float(item.get("duration", 0) or 0) for item in items)
                    + max(0, len(items) - 1) * pause_seconds
                ),
                chapters=items,
            )
        )
    return tuple(result)


def _normalize_m4b_reflow_groups(groups):
    """Приводит разные удобные формы групп к ``tuple[tuple[id, ...], ...]``.

    Публичная вспомогательная функция принимает обычную последовательность
    групп. Для интеграции с текущим планом источников дополнительно разрешено
    отображение вида
    ``{group_id: {"file_ids": [...]}}`` и словарь группы с ключами
    ``file_ids``/``ids``/``chapters``/``files``. Плоская последовательность
    идентификаторов трактуется как одна книга, а не как набор одноэлементных
    групп. Никаких объектов GUI здесь нет.
    """
    if groups is None:
        return tuple(), tuple()

    if isinstance(groups, Mapping):
        raw_groups = []
        for group_key, raw_group in groups.items():
            if isinstance(raw_group, Mapping):
                item = dict(raw_group)
                item.setdefault("_source_group_index", len(raw_groups) + 1)
                item.setdefault("_source_group_id", group_key)
                raw_groups.append(item)
            else:
                raw_groups.append(
                    {
                        "file_ids": raw_group,
                        "_source_group_index": len(raw_groups) + 1,
                        "_source_group_id": group_key,
                    }
                )
    else:
        try:
            raw_groups = list(groups)
        except TypeError:
            raw_groups = [groups]

    if not raw_groups:
        return tuple(), tuple()

    def is_scalar(value):
        return isinstance(value, (str, bytes, Path, PurePosixPath)) or not isinstance(
            value, (Mapping, list, tuple, set, frozenset)
        )

    # ``["chapter-1", "chapter-2"]`` — удобная плоская форма одной книги.
    # Последовательность последовательностей остаётся набором явных групп.
    if all(is_scalar(item) for item in raw_groups):
        raw_groups = [raw_groups]

    normalized = []
    seen_ids = set()
    for group_index, raw_group in enumerate(raw_groups, 1):
        source_group_index = group_index
        if isinstance(raw_group, Mapping):
            source_group_index = raw_group.get(
                "_source_group_index", raw_group.get("index", group_index)
            )
            members = None
            for key in ("file_ids", "ids", "chapters", "files", "paths"):
                if key in raw_group:
                    members = raw_group.get(key)
                    break
            if members is None:
                raise ValueError(
                    f"M4B-группа {group_index} не содержит file_ids/chapters"
                )
        elif is_scalar(raw_group):
            members = (raw_group,)
        else:
            members = raw_group
        try:
            members = tuple(members or ())
        except TypeError as exc:
            raise ValueError(f"M4B-группа {group_index} имеет неверный состав") from exc

        normalized_members = []
        for member in members:
            # Записи глав принимаются для удобства, но результат всегда хранит
            # их стабильный идентификатор, а не изменяемый словарь.
            if isinstance(member, Mapping):
                member_id = (
                    member.get("id")
                    or member.get("file_id")
                    or member.get("path")
                )
                if member_id is None:
                    raise ValueError(
                        f"глава в M4B-группе {group_index} не содержит id"
                    )
                member = member_id
            if isinstance(member, (list, tuple, set, frozenset, Mapping)):
                raise ValueError("идентификатор главы M4B должен быть простым значением")
            try:
                if member in seen_ids:
                    raise ValueError(
                        f"глава {member!s} входит в несколько M4B-групп"
                    )
                seen_ids.add(member)
            except TypeError as exc:
                raise ValueError(
                    "идентификатор главы M4B должен быть хешируемым"
                ) from exc
            normalized_members.append(member)
        if not normalized_members:
            # В пустых виртуальных группах нет глав для перестроения, поэтому
            # они пропускаются, как и в правиле планировщика исходников.
            continue
        try:
            source_group_index = int(source_group_index)
        except (TypeError, ValueError, OverflowError):
            source_group_index = group_index
        normalized.append((tuple(normalized_members), source_group_index))
    return tuple(normalized), tuple(
        member for group, _index in normalized for member in group
    )


def _m4b_reflow_duration_lookup(durations, chapter_ids):
    """Проверяет и нормализует фактические длительности глав."""
    if isinstance(durations, Mapping):
        result = {}
        missing = []
        for chapter_id in chapter_ids:
            try:
                present = chapter_id in durations
            except TypeError as exc:
                raise ValueError("идентификатор главы M4B должен быть хешируемым") from exc
            if not present and str(chapter_id) in durations:
                value = durations[str(chapter_id)]
            elif present:
                value = durations[chapter_id]
            else:
                missing.append(chapter_id)
                continue
            if isinstance(value, bool):
                raise ValueError(
                    f"некорректная длительность главы {chapter_id!s}"
                )
            try:
                value = float(value)
            except (TypeError, ValueError, OverflowError):
                raise ValueError(
                    f"некорректная длительность главы {chapter_id!s}"
                ) from None
            if not math.isfinite(value) or value < 0:
                raise ValueError(
                    f"длительность главы {chapter_id!s} должна быть конечной и "
                    "неотрицательной"
                )
            result[chapter_id] = value
        if missing:
            raise ValueError(
                "нет фактической длительности для глав: "
                + ", ".join(str(item) for item in missing)
            )
        return result

    try:
        values = list(durations or ())
    except TypeError as exc:
        raise ValueError("durations должен быть mapping или последовательностью") from exc
    if len(values) != len(chapter_ids):
        raise ValueError(
            "число длительностей не совпадает с числом глав M4B"
        )
    return _m4b_reflow_duration_lookup(
        dict(zip(chapter_ids, values)), chapter_ids
    )


def reflow_m4b_groups_by_duration(
    groups,
    durations,
    limit_seconds,
    *,
    pause_seconds=0,
):
    """Перестраивает M4B-группы по фактической длительности глав.

    Параметры:

    ``groups``
        Последовательность групп (каждая группа — последовательность
        идентификаторов глав), либо плоская последовательность ID. При
        перестроении исходные границы групп снимаются, а глобальный порядок
        глав сохраняется.
    ``durations``
        Mapping ``chapter_id -> seconds`` либо последовательность секунд,
        выровненная по плоскому порядку глав.
    ``limit_seconds``
        Максимальная длительность части. Ноль отключает лимит и возвращает
        исходные группы; отрицательное значение запрещено.
    ``pause_seconds``
        Необязательная пауза между соседними главами, учитываемая только при
        выборе границы. Она не превращает главу в делимую единицу.

    Возвращается :class:`M4BReflowResult`. Если отдельная глава сама длиннее
    лимита, она остаётся целиком в собственной части (или рядом с уже
    помещёнными главами, если это возможно), а запись об этом попадает в
    ``result.oversized``. Функция не пишет в лог и не вызывает FFmpeg/Tk.
    """
    normalized_groups, chapter_ids = _normalize_m4b_reflow_groups(groups)
    if not chapter_ids:
        return M4BReflowResult()
    durations_by_id = _m4b_reflow_duration_lookup(durations, chapter_ids)

    def nonnegative_number(value, label):
        if isinstance(value, bool):
            raise ValueError(f"{label} должен быть числом")
        try:
            number = float(value or 0)
        except (TypeError, ValueError, OverflowError):
            raise ValueError(f"{label} должен быть числом") from None
        if not math.isfinite(number) or number < 0:
            raise ValueError(f"{label} должен быть конечным и неотрицательным")
        return number

    limit = nonnegative_number(limit_seconds, "лимит длительности")
    pause = nonnegative_number(pause_seconds, "пауза между главами")

    # ``limit=0`` во всех планировщиках означает отключение ограничения.
    # В этом случае сохраняем пользовательские границы: безопаснее ничего не
    # менять, как если бы вызывающий код вовсе не запустил помощник.
    if limit <= 0:
        total = sum(durations_by_id.values()) + max(0, len(chapter_ids) - 1) * pause
        return M4BReflowResult(
            groups=tuple(group for group, _index in normalized_groups),
            oversized=tuple(),
            total_duration_seconds=total,
            limit_seconds=limit,
            pause_seconds=pause,
        )

    source_group_by_id = {}
    for group, source_index in normalized_groups:
        for chapter_id in group:
            source_group_by_id[chapter_id] = source_index

    rebuilt = []
    current = []
    current_duration = 0.0
    oversized = []
    for chapter_index, chapter_id in enumerate(chapter_ids, 1):
        duration = durations_by_id[chapter_id]
        if duration > limit:
            oversized.append(
                M4BReflowDiagnostic(
                    chapter_id=chapter_id,
                    chapter_index=chapter_index,
                    duration_seconds=duration,
                    limit_seconds=limit,
                    over_by_seconds=duration - limit,
                    source_group_index=source_group_by_id.get(chapter_id, 0),
                )
            )
        candidate = current_duration + (pause if current else 0.0) + duration
        if current and candidate > limit:
            rebuilt.append(tuple(current))
            current = []
            current_duration = 0.0
        if current:
            current_duration += pause
        current.append(chapter_id)
        current_duration += duration
    if current:
        rebuilt.append(tuple(current))

    total = sum(durations_by_id.values()) + max(0, len(chapter_ids) - 1) * pause
    return M4BReflowResult(
        groups=tuple(rebuilt),
        oversized=tuple(oversized),
        total_duration_seconds=total,
        limit_seconds=limit,
        pause_seconds=pause,
    )


def reflow_m4b_parts_by_duration(
    groups,
    durations,
    max_duration_seconds,
    *,
    pause_seconds=0,
):
    """Совместимое имя вспомогательной функции с терминологией ``M4BPart``."""
    return reflow_m4b_groups_by_duration(
        groups,
        durations,
        max_duration_seconds,
        pause_seconds=pause_seconds,
    )


# Короткое имя используется фоновыми задачами; длинное сохраняет совместимость.
reflow_m4b_groups = reflow_m4b_groups_by_duration


def build_m4b_ffmpeg_command(
    concat_manifest,
    metadata_file,
    output_file,
    *,
    bitrate="64k",
    sample_rate=48000,
    channels=1,
    cover=None,
    disk_number=None,
    disk_total=None,
    track_number=None,
    track_total=None,
    include_track_metadata=True,
    language=M4B_AUDIO_LANGUAGE,
    ffmpeg_path="ffmpeg",
):
    """Возвращает воспроизводимую AAC-LC/M4B-команду FFmpeg.

    ``include_track_metadata=False`` сохраняет пару тома ``disc``, но не
    записывает необязательный атом ``track``/``trkn``.
    """
    cmd = [
        str(ffmpeg_path),
        "-y",
        "-hide_banner",
        "-f",
        "concat",
        "-safe",
        "0",
        "-i",
        str(concat_manifest),
        "-f",
        "ffmetadata",
        "-i",
        str(metadata_file),
    ]
    if cover:
        # Все входные адреса должны идти до параметров вывода. Поэтому ``-i``
        # обложки находится здесь, а не после ``-map``; этого требует FFmpeg
        # как в Windows, так и в macOS.
        cmd.extend(["-i", str(cover)])
    cmd.extend([
        "-map",
        "0:a:0",
        "-map_metadata",
        "1",
        "-c:a",
        "aac",
        "-profile:a",
        "aac_low",
        "-b:a",
        str(bitrate or "64k"),
        "-ar",
        str(int(sample_rate)),
        "-ac",
        str(int(channels)),
        "-f",
        "ipod",
        "-brand",
        "M4B ",
        "-metadata",
        "media_type=2",
        "-metadata:s:a:0",
        f"language={normalize_m4b_audio_language(language)}",
        "-movflags",
        "+faststart",
    ])
    # Мультиплексор MP4/MOV понимает и ``disc``, и ``track``. Первое поле
    # заполняет атом QuickTime ``disk``, второе — ``trkn``; у разделённой
    # аудиокниги обе пары описывают один номер тома.
    for key, value in m4b_volume_metadata(
        disk_number,
        disk_total,
        track_number=track_number,
        track_total=track_total,
        include_track=include_track_metadata,
    ).items():
        cmd.extend(["-metadata", f"{key}={value}"])
    if cover:
        cmd.extend(
            [
                "-map",
                "2:v:0",
                "-c:v",
                _m4b_cover_codec(cover),
                "-disposition:v:0",
                "attached_pic",
            ]
        )
    cmd.append(str(output_file))
    return tuple(cmd)


def format_m4b_disk_tag(disk_number, disk_total=None):
    """Вернуть метаданные диска FFmpeg/iTunes в форме ``N[/T]``.

    Публичный ключ метаданных FFmpeg называется ``disc``; мультиплексор MOV
    записывает его в атом QuickTime ``disk``. Написание выбрано намеренно:
    ``disk`` — имя атома, но не ключ, принимаемый FFmpeg. Это различие не даёт
    незаметно потерять внешне корректное значение при повторной упаковке.
    """
    try:
        number = int(disk_number or 0)
    except (TypeError, ValueError, OverflowError):
        return ""
    try:
        total = int(disk_total or 0)
    except (TypeError, ValueError, OverflowError):
        total = 0
    if number <= 0:
        return ""
    if total > 0:
        total = max(number, total)
        return f"{number}/{total}"
    return str(number)


def m4b_disk_metadata(disk_number, disk_total=None):
    """Построить каноническое отображение метаданных FFmpeg для номера тома.

    ``disc`` — ключ FFmpeg, который мультиплексор MOV записывает в атом iTunes
    ``disk``. Второй ключ ``disk`` добавлять нельзя: текущий FFmpeg молча его
    игнорирует и создаёт ложное впечатление записи метаданных. Значение остаётся
    числовой строкой ``N/T``; текст наподобие ``Disk 1 of 3`` нужен только в
    интерфейсе или строке состояния.
    """
    value = format_m4b_disk_tag(disk_number, disk_total)
    return {"disc": value} if value else {}


def m4b_volume_metadata(
    disk_number=None,
    disk_total=None,
    *,
    track_number=None,
    track_total=None,
    include_track=True,
    include_track_metadata=None,
):
    """Вернуть числовые метаданные тома для части M4B.

    Мультиплексор MOV записывает ``disc=N/T`` в атом QuickTime ``disk``, а
    ``track=N/T`` — в ``trkn`` при включённом ``include_track``.
    ``include_track_metadata`` принимается как понятный алиас имени поля цели.
    Разные медиатеки проверяют разные атомы, поэтому разделённая книга получает
    оба; это улучшает совместимость, но не заменяет отдельные метаданные доставки
    Apple ``.itmsp``. По умолчанию пара дорожки совпадает с парой диска, а явные
    ``track_*`` позволяют задать другую последовательность без изменения
    совместимого помощника :func:`m4b_disk_metadata`.

    Пустые и неверные пары пропускаются независимо. Это удобно для одного
    неразделённого файла без метаданных тома и исключает ложные значения ``0/0``.
    """
    if include_track_metadata is not None:
        include_track = _config_bool(include_track_metadata, default=True)
    disk = m4b_disk_metadata(disk_number, disk_total)
    if include_track:
        if track_number is None:
            track_number = disk_number
        if track_total is None:
            track_total = disk_total
        track_value = format_m4b_disk_tag(track_number, track_total)
        if track_value:
            disk["track"] = track_value
    return disk


def output_target_directory_name(target):
    """Стабильное имя подпапки для нескольких целей вывода."""
    target = target if isinstance(target, OutputTarget) else OutputTarget(**dict(target or {}))
    data = target.normalized()
    fmt = data["format"] or "audio"
    profile = data.get("profile") or ""
    # Пустой профиль не должен превращаться в ``mp3_Без названия``: имена
    # каталогов набора являются частью пользовательского контракта и в
    # простом случае совпадают с расширением/форматом.
    suffix = ""
    if profile:
        suffix = sanitize_filename_component(profile, fallback="").strip()
    return sanitize_filename_component(
        f"{fmt}_{suffix}" if suffix else fmt,
        fallback="audio",
    )


def plan_output_targets(targets, base_dir, *, legacy_single_dir=None):
    """Нормализует набор целей и назначает безопасные каталоги.

    При одной цели без явного пути сохраняется прежний каталог. Интерфейс и загрузчик
    настроек заранее очищают путь одиночной цели, поэтому приложение всегда
    использует выбранную общую папку; низкоуровневый планировщик продолжает
    принимать явный путь для совместимости интеграций. При нескольких целях
    общая папка получает отдельный подкаталог для каждой цели, если
    пользователь не указал собственный путь.
    """
    normalized = []
    for target in targets or ():
        if not isinstance(target, (OutputTarget, dict)):
            raise TypeError("цель вывода должна быть OutputTarget или dict")
        # Чистый планировщик проходит ту же проверку, что настройки и
        # переносимый импорт. Иначе прямой вызов мог бы получить путь цели,
        # которую фоновая задача отклонит лишь после запуска.
        data = normalize_output_target(target)
        if data.get("enabled", True):
            normalized.append(data)
    if not normalized:
        return tuple()
    result = []
    multiple = len(normalized) > 1
    # Абсолютная база делает планирование идемпотентным: окончательный M4B-план
    # уточняется после ffprobe и повторно проходит через эту функцию. Относительный
    # каталог цели не должен при каждом проходе получать ещё одну копию базы.
    base = Path(base_dir).expanduser().resolve(strict=False)
    used = set()
    for data in normalized:
        directory = Path(data["output_dir"]).expanduser() if data.get("output_dir") else None
        if directory is not None and not directory.is_absolute():
            directory = base / directory
        if directory is None:
            if multiple:
                directory = base / output_target_directory_name(data)
            else:
                directory = Path(legacy_single_dir or base).expanduser()
                if not directory.is_absolute():
                    directory = directory.resolve(strict=False)
        key = str(directory).casefold()
        if multiple and not data.get("output_dir"):
            # Не допускаем одинаковые имена при двух профилях одного формата.
            suffix = 2
            original = directory
            while key in used:
                directory = original.with_name(f"{original.name}_{suffix}")
                key = str(directory).casefold()
                suffix += 1
        used.add(key)
        data["output_dir"] = str(directory)
        result.append(data)
    return tuple(result)


def clear_output_target_directories(targets):
    """Вернуть снимок целей, передающий выбор каталогов планировщику.

    В наборе с несколькими целями ``output_dir`` является явным
    переопределением, поэтому смена общей папки намеренно не перемещает такую
    цель. Помощник используется неразрушающим действием «Использовать общую
    папку»: очищаются только поля JSON, а файлы на диске не затрагиваются.
    Результат нормализован и сохраняет параметры профиля, кодека, эффектов и
    шаблона.
    """
    cleared = []
    for target in targets or ():
        if not isinstance(target, (OutputTarget, dict)):
            raise ValueError("цель вывода должна быть OutputTarget или dict")
        data = normalize_output_target(target)
        data["output_dir"] = ""
        cleared.append(data)
    return tuple(cleared)


def normalize_output_target_directories(targets):
    """Применить правило каталогов по умолчанию к сохранённому набору целей.

    У набора с одной активной целью отдельный каталог цели не имеет смысла:
    назначением операции служит компактное поле ``export_dir``/``output_dir``.
    Старые предварительные снимки могли хранить в строке каталог прошлого
    запуска, который молча получал приоритет после смены общей папки. Поэтому
    при единственной активной цели её переопределение очищается.

    При двух и более целях непустой каталог строки остаётся намеренным
    переопределением, а пустой ``plan_output_targets`` помещает в подпапку
    формата. Отключённые строки сохраняются, чтобы временно отключённую
    заготовку можно было включить без потери каталога. Помощник применяется к
    снимкам настроек и интерфейса; прямые вызовы планировщика сохраняют прежний
    контракт явного каталога.
    """
    normalized = []
    for target in targets or ():
        if not isinstance(target, (OutputTarget, dict)):
            raise ValueError("цель вывода должна быть OutputTarget или dict")
        normalized.append(normalize_output_target(target))

    active_indices = [
        index
        for index, target in enumerate(normalized)
        if _config_bool(target.get("enabled", True), default=True)
    ]
    if len(active_indices) == 1:
        target = normalized[active_indices[0]]
        if str(target.get("output_dir", "") or "").strip():
            target["output_dir"] = ""
    return tuple(normalized)


def output_target_directory_diagnostics(targets, common_dir="", *, base_dir=None):
    """Описать явные каталоги целей до начала экспорта.

    Результат намеренно состоит из простых данных, чтобы предварительная
    проверка могла сообщить об устаревшей цели без запуска Tk и создания
    каталогов. ``explicit`` содержит активные цели со своим каталогом,
    ``common`` — нормализованный каталог пользователя (либо ``None``), а
    ``single_mismatch`` сохранён для диагностики сырых и старых снимков.
    Приложение переносит такой снимок до экспорта, поэтому единственная активная
    цель не использует устаревшее переопределение. Диагностика сама не меняет
    пути.
    """
    active = []
    for target in targets or ():
        if isinstance(target, OutputTarget):
            enabled = _config_bool(target.enabled, default=True)
            raw_dir = target.output_dir
        elif isinstance(target, dict):
            enabled = _config_bool(target.get("enabled"), default=True)
            raw_dir = target.get("output_dir", "")
        else:
            continue
        if not enabled:
            continue
        try:
            normalized = normalize_output_target(target)
        except (TypeError, ValueError):
            # Настоящая проверка выполняется перед экспортом. Диагностика
            # остаётся максимально мягкой, чтобы повреждённые импортированные
            # настройки не скрыли полезное сообщение основной проверки.
            normalized = {"output_dir": str(raw_dir or "").strip()}
        explicit = str(normalized.get("output_dir", "") or "").strip()
        active.append(explicit)

    common = str(common_dir or "").strip()
    common_path = None
    if common:
        try:
            common_path = Path(common).expanduser()
        except (TypeError, ValueError, OSError):
            common_path = None
    explicit_paths = tuple(path for path in active if path)
    mismatch = False
    if len(active) == 1 and explicit_paths and common_path is not None:
        try:
            # Диагностика использует ту же систему отсчёта, что
            # ``plan_output_targets``: относительные пути целей разрешаются от
            # базового каталога, а не от рабочей папки процесса.
            explicit_path = Path(explicit_paths[0]).expanduser()
            if not explicit_path.is_absolute():
                resolution_base = (
                    Path(base_dir).expanduser()
                    if base_dir not in (None, "")
                    else common_path
                )
                explicit_path = resolution_base / explicit_path
            mismatch = (
                explicit_path.resolve(strict=False)
                != common_path.resolve(strict=False)
            )
        except (TypeError, ValueError, OSError, RuntimeError):
            explicit_text = explicit_paths[0]
            if (
                not Path(explicit_text).expanduser().is_absolute()
                and base_dir not in (None, "")
            ):
                explicit_text = str(Path(base_dir).expanduser() / explicit_text)
            mismatch = explicit_text.casefold() != str(common_path).casefold()
    return {
        "active_count": len(active),
        "explicit": explicit_paths,
        "common": str(common_path) if common_path is not None else "",
        "single_mismatch": mismatch,
    }


def normalize_source_synthesis_targets(raw_targets):
    """Нормализует список целей вкладки «Синтез из папки».

    Пустой список возвращается как ``()`` и означает совместимый старый режим
    с одним форматом из ``output_format``. В отличие от вспомогательных функций
    интерфейса эта
    функция строгая: испорченная запись не молча меняется на другой формат,
    а сообщает вызывающему коду, что профиль нужно отклонить или показать
    пользователю.
    """
    if raw_targets is None or raw_targets == "":
        return tuple()
    if not isinstance(raw_targets, (list, tuple)):
        raise ValueError("synthesis_targets должен быть массивом целей")
    normalized = []
    for index, target in enumerate(raw_targets, 1):
        try:
            item = normalize_output_target(target)
            # В исходниках нет общего флажка склейки: старое inherit означает
            # отдельный файл на каждый TXT. Явная склейка действует по группам.
            if item["assembly_mode"] == "inherit":
                item["assembly_mode"] = "files"
            normalized.append(item)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"цель синтеза {index}: {exc}") from exc
    return tuple(normalized)


def _legacy_source_synthesis_target(
    *,
    legacy_format="mp3",
    legacy_bitrate="128k",
    legacy_sample_rate="auto",
    legacy_channels="auto",
    legacy_output_dir="",
):
    """Строит цель из старых плоских параметров синтеза.

    Выделено в отдельную чистую функцию, чтобы рабочий код мог получить единый
    формат записи независимо от того, включён ли новый список целей.
    """
    target = normalize_output_target(
        OutputTarget(
            format=legacy_format,
            output_dir=legacy_output_dir,
            bitrate=("auto" if str(legacy_format or "").strip().lower() == "wav" else legacy_bitrate),
            sample_rate=legacy_sample_rate,
            channels=legacy_channels,
            enabled=True,
        )
    )
    target["assembly_mode"] = (
        "merge" if target["format"] == "m4b" else "files"
    )
    return target


def source_synthesis_targets_from_config(config):
    """Возвращает снимок целей синтеза, сохраняя прежний режим при пустом списке.

    ``config`` обычно уже прошёл ``normalize_config``.  Для прямого вызова
    вспомогательная функция всё равно аккуратно подставляет старые значения и
    проверяет их. Это единственная точка, где новый список включает несколько целей;
    отсутствие ключа или пустой список никогда не меняет старый вывод.
    """
    data = config if isinstance(config, dict) else {}
    raw_targets = data.get(SYNTHESIS_TARGETS_CONFIG_KEY, [])
    if not raw_targets:
        raw_targets = data.get(SOURCE_OUTPUT_TARGETS_CONFIG_KEY, [])
    targets = normalize_source_synthesis_targets(raw_targets)
    if targets:
        return targets
    return (
        _legacy_source_synthesis_target(
            legacy_format=data.get("output_format", "mp3"),
            legacy_bitrate=data.get("output_bitrate", "128k"),
            legacy_sample_rate=data.get("output_sample_rate", "auto"),
            legacy_channels=data.get("output_channels", "auto"),
            legacy_output_dir=data.get("output_dir", ""),
        ),
    )


def source_groups_have_metadata_overrides(groups):
    """Проверяет, требуют ли виртуальные части отдельного применения тегов."""
    if isinstance(groups, dict):
        values = tuple(groups.values())
    else:
        values = tuple(groups or ())
    for group in values:
        if not isinstance(group, dict):
            continue
        nested = group.get("source_group", {})
        nested_overrides = (
            nested.get("metadata_overrides", {})
            if isinstance(nested, dict)
            else {}
        )
        if merge_metadata_overrides(
            nested_overrides,
            group.get("metadata_overrides", {}),
        ):
            return True
    return False


def _source_synthesis_file_descriptor(item):
    """Возвращает ``(id, path, display_name, relative_path)`` для планировщика.

    Во время выполнения используются словари с ID, а прямые вызовы часто передают
    ``SourceNode`` или обычные ``Path``. Поддержка всех трёх форм не меняет
    публичную модель дерева и помогает избежать дублирования адаптеров.
    """
    if isinstance(item, SourceNode):
        path = Path(item.path or item.relative_path)
        item_id = str(item.id or path)
        name = item.name or path.name
        relative = str(item.relative_path or path.name)
        return item_id, path, str(name), relative
    if isinstance(item, dict):
        raw_path = item.get("path") or item.get("source_path")
        if raw_path is None:
            raise ValueError("элемент источника не содержит path")
        path = Path(raw_path)
        item_id = str(item.get("id") or item.get("file_id") or path)
        name = str(item.get("name") or path.name)
        relative = str(item.get("relative_path") or path.name)
        return item_id, path, name, relative
    path = Path(item)
    return str(path), path, path.name, path.name


def _source_synthesis_group_members(groups, file_records):
    """Нормализует группы сборки и сохраняет порядок исходников.

    Группа может быть словарём ``{file_ids, name, estimated_duration}`` (как
    текущий Treeview-план), последовательностью ID либо последовательностью
    путей. Непокрытые файлы добавляются отдельными группами, поэтому
    удаление/выделение части дерева не приводит к тихой потере глав.
    """
    by_id = {record["id"]: record for record in file_records}
    by_path = {}
    for record in file_records:
        by_path[str(record["path"])] = record
        try:
            by_path[str(record["path"].resolve())] = record
        except (OSError, RuntimeError):
            pass

    def resolve_member(value):
        if isinstance(value, SourceNode):
            value = value.id
        elif isinstance(value, dict):
            value = value.get("id") or value.get("file_id") or value.get("path")
        key = str(value)
        if key in by_id:
            return by_id[key]
        if key in by_path:
            return by_path[key]
        try:
            return by_path.get(str(Path(key).expanduser().resolve()))
        except (OSError, RuntimeError, TypeError, ValueError):
            return None

    # Пустой план имеет явный полезный смысл: цель M4B становится одной книгой
    # со всеми выбранными TXT. Непустой (в том числе устаревший или неполный)
    # план обрабатывается ниже, а непокрытые файлы остаются отдельными группами,
    # чтобы повреждённый план не мог молча потерять главы.
    if isinstance(groups, dict):
        # Вкладка исходников хранит ``_source_plan_groups`` с ключами
        # виртуальных групп. Принимаем отображение напрямую: это не требует
        # хрупкого адаптера ``.values()`` в интерфейсе и сохраняет ключ для имён.
        groups = tuple(
            dict(value or {}, id=key)
            for key, value in groups.items()
            if isinstance(value, dict)
        )
    else:
        groups = tuple(groups or ())
    had_explicit_groups = bool(groups)

    if not had_explicit_groups:
        return (
            {
                "index": 1,
                "name": "",
                "estimated_duration": 0.0,
                "records": tuple(file_records),
                "source_group": {},
            },
        ) if file_records else tuple()

    normalized = []
    covered = set()

    def preserved_range_width(name):
        """Сохраняет ширину нумерации из имени старой виртуальной части."""
        matches = re.findall(r"(?<!\d)(\d+)\s*-\s*(\d+)(?!\d)", str(name or ""))
        if not matches:
            return 0
        return max(len(first) for pair in matches for first in pair)

    for group_index, raw_group in enumerate(groups or (), 1):
        if isinstance(raw_group, dict):
            raw_members = (
                raw_group.get("file_ids")
                or raw_group.get("ids")
                or raw_group.get("files")
                or raw_group.get("paths")
                or ()
            )
            group_name = str(raw_group.get("name") or "").strip()
            estimated = raw_group.get("estimated_duration", 0)
            source_group = copy.deepcopy(raw_group)
        else:
            raw_members = raw_group or ()
            group_name = ""
            estimated = 0
            source_group = {}
        raw_members = tuple(raw_members or ())
        partial_group = False
        members = []
        member_ids = set()
        for raw_member in raw_members:
            record = resolve_member(raw_member)
            if record is None:
                # Устаревшие идентификаторы виртуального плана здесь
                # пропускаются; вызывающий код всё равно получит текущие файлы
                # через запасную ветку непокрытых. Выбранная часть готового
                # плана также не унаследует старое имя полного диапазона.
                partial_group = True
                continue
            if record["id"] in member_ids:
                # Повтор главы в одной импортированной группе безвреден:
                # оставляем первое вхождение и исходный порядок. Та же глава в
                # двух разных группах остаётся серьёзной ошибкой ниже.
                continue
            if record["id"] in covered:
                raise ValueError(
                    f"источник {record['id']} входит в несколько групп сборки"
                )
            members.append(record)
            member_ids.add(record["id"])
            covered.add(record["id"])
        if members:
            try:
                estimated_value = float(estimated or 0)
            except (TypeError, ValueError, OverflowError):
                estimated_value = 0.0
            if not math.isfinite(estimated_value) or estimated_value < 0:
                estimated_value = 0.0
            normalized.append(
                {
                    "index": group_index,
                    # Подготовленная группа может прийти только с выбранной
                    # частью листьев. Её старое имя/диапазон тогда описывает
                    # другую книгу, поэтому планировщик строит новый диапазон.
                    "name": "" if partial_group else group_name,
                    "estimated_duration": estimated_value,
                    # При повторном использовании подготовленной группы для
                    # части сохраняем старое количество только для ширины
                    # чисел (01-02 вместо 1-2). Сами файлы перенумеровываются
                    # с единицы, старое имя больше не используется.
                    "range_total_count": (
                        len(raw_members) if partial_group else 0
                    ),
                    "range_width": (
                        preserved_range_width(group_name) if partial_group else 0
                    ),
                    # Диалог плана сохраняет шаблон, из которого получена
                    # автоматическая метка группы. Этот небольшой маркер
                    # происхождения позволяет отличить устаревшую метку вроде
                    # ``Book Главы 1-26`` от имени, заданного вручную или при
                    # импорте, после смены шаблона.
                    "name_template": (
                        raw_group.get("name_template")
                        if isinstance(raw_group, dict)
                        else None
                    ),
                    "metadata_overrides": merge_metadata_overrides(
                        raw_group.get("metadata_overrides", {})
                        if isinstance(raw_group, dict)
                        else {}
                    ),
                    "records": tuple(members),
                    "source_group": source_group,
                }
            )
    # План мог быть создан для всей очереди, а затем выбрана только часть для
    # синтеза. Сохраняем порядок выбора и каждый выбранный файл.
    for record in file_records:
        if record["id"] not in covered:
            normalized.append(
                {
                    "index": len(normalized) + 1,
                    "name": "",
                    "estimated_duration": 0.0,
                    "records": (record,),
                    "source_group": {},
                }
            )
    if not normalized and file_records:
        normalized.append(
            {
                "index": 1,
                "name": "",
                "estimated_duration": 0.0,
                "records": tuple(file_records),
                "source_group": {},
            }
        )
    return tuple(normalized)


def plan_source_synthesis_target_paths(
    source_root,
    output_root,
    files,
    targets=None,
    *,
    mirror_relative=True,
    legacy_output_dir=None,
    legacy_format="mp3",
    legacy_bitrate="128k",
    legacy_sample_rate="auto",
    legacy_channels="auto",
    source_m4b_groups=(),
    book_name=None,
    path_by_id=None,
    m4b_template=DEFAULT_SOURCE_M4B_TEMPLATE,
):
    """Планирует вывод в несколько форматов вкладки «Синтез из папки».

    Результат — кортеж JSON-подобных записей. Отдельный TXT получает
    ``kind='file'``, склейка обычного формата — ``kind='group'``, а книга с
    метками — ``kind='m4b'``. Групповые записи содержат упорядоченные
    ``file_ids`` и ``source_paths``; длительности и таймкоды M4B добавляются
    после синтеза. Функция ничего не читает и не создаёт на диске.

    При одной цели старого режима пути совпадают с прежней политикой: каталог
    ``legacy_output_dir`` (либо ``output_root``), относительные подпапки — по
    ``mirror_relative``. При нескольких целях пустые каталоги получают
    отдельные подпапки формата через ``plan_output_targets``.
    """
    source_root = Path(source_root).expanduser().resolve()
    output_root = Path(output_root).expanduser()
    file_records = []
    seen_ids = set()
    for item in files or ():
        if (
            path_by_id
            and not isinstance(item, (SourceNode, dict, Path))
            and str(item) in path_by_id
        ):
            item = {"id": str(item), "path": path_by_id[str(item)]}
        item_id, path, name, relative_hint = _source_synthesis_file_descriptor(item)
        path = path.expanduser()
        try:
            relative = path.resolve().relative_to(source_root)
        except ValueError as exc:
            raise ValueError(f"источник находится вне корневой папки: {path}") from exc
        if item_id in seen_ids:
            raise ValueError(f"дублирующийся идентификатор источника: {item_id}")
        seen_ids.add(item_id)
        file_records.append(
            {
                "id": item_id,
                "path": path.resolve(),
                "name": name,
                "relative": relative,
                "relative_hint": relative_hint,
                "stem": sanitize_filename_component(
                    path.stem, fallback="Без названия"
                ),
            }
        )
    if not file_records:
        return tuple()

    if targets is None:
        normalized_targets = (
            _legacy_source_synthesis_target(
                legacy_format=legacy_format,
                legacy_bitrate=legacy_bitrate,
                legacy_sample_rate=legacy_sample_rate,
                legacy_channels=legacy_channels,
                legacy_output_dir=legacy_output_dir or str(output_root),
            ),
        )
    else:
        normalized_targets = normalize_source_synthesis_targets(targets)
    if not normalized_targets:
        normalized_targets = (
            _legacy_source_synthesis_target(
                legacy_format=legacy_format,
                legacy_bitrate=legacy_bitrate,
                legacy_sample_rate=legacy_sample_rate,
                legacy_channels=legacy_channels,
                legacy_output_dir=legacy_output_dir or str(output_root),
            ),
        )
    else:
        # `legacy_single_dir` учитывается только для одной цели с пустым путём.
        # Явные каталоги отдельных целей сохраняют приоритет.
        normalized_targets = plan_output_targets(
            normalized_targets,
            output_root,
            legacy_single_dir=legacy_output_dir or str(output_root),
        )

    if not normalized_targets:
        raise ValueError("выберите хотя бы одну активную цель синтеза")

    # Ветка выше намеренно обходит ``plan_output_targets`` для старой цели, чтобы
    # пустой список целей случайно не получил подпапку профиля. Нормализуем
    # результат один раз для единой структуры.
    if len(normalized_targets) == 1 and not normalized_targets[0].get("output_dir"):
        normalized_targets = plan_output_targets(
            normalized_targets,
            output_root,
            legacy_single_dir=legacy_output_dir or str(output_root),
        )
    elif len(normalized_targets) == 1:
        normalized_targets = tuple(normalized_targets)

    root_name = str(book_name or source_root.name or "Книга").strip() or "Книга"
    # Храним один нормализованный снимок шаблона M4B для всего плана. ``None``
    # означает старое значение по умолчанию, а пустая строка — явную компактную
    # форму ``{book}``; единая нормализация сохраняет это различие и при выводе,
    # и при проверке происхождения.
    effective_source_m4b_template = normalize_source_m4b_template(m4b_template)
    total_files = len(file_records)
    position_by_id = {record["id"]: index for index, record in enumerate(file_records, 1)}
    records = []
    used_paths = {}

    def add_record(record):
        path = Path(record["path"])
        key = os.path.normcase(str(path)).casefold()
        if key in used_paths:
            raise ValueError(
                "совпадающие выходные имена: "
                f"{used_paths[key]} и {path}"
            )
        used_paths[key] = path
        records.append(record)

    def render_target_name(
        target,
        context,
        fallback,
        extension,
        *,
        use_default_m4b_template=True,
        varying_m4b_fields=(),
        grouped=False,
    ):
        template = str(target.get("filename_template") or "").strip()
        if (
            not template
            and extension == "m4b"
            and use_default_m4b_template
        ):
            template = effective_source_m4b_template
        if template:
            # Шаблоны M4B исходников используют те же короткие алиасы, что и
            # универсальный планировщик. Оставляем отдельный набор для
            # отложенной цели, чтобы явно описать контекст исходников; обычные
            # форматы используют общий набор ниже.
            allowed_fields = (
                SOURCE_M4B_TEMPLATE_FIELDS
                if extension == "m4b"
                else TEMPLATE_FIELDS_OUTPUT
            )
            renderer = (
                render_m4b_part_template
                if extension == "m4b" or grouped
                else render_output_file_template
            )
            rendered = renderer(template, context, allowed_fields)
        else:
            rendered = fallback
        rendered = _template_basename(rendered, extension)
        if extension == "m4b" and _m4b_template_needs_part_suffix(
            template,
            context,
            SOURCE_M4B_TEMPLATE_FIELDS,
            varying_fields=varying_m4b_fields,
        ):
            rendered = _append_m4b_part_suffix(
                rendered,
                context,
                fallback=fallback,
            )
        return sanitize_filename_component(rendered, fallback=fallback)

    # Виртуальные части задают не только границы M4B, но и область действия
    # локальных тегов. Строим карту один раз до обхода целей, чтобы MP3,
    # Opus, OGG, M4A и WAV получили тот же снимок переопределений, что и M4B.
    source_groups = _source_synthesis_group_members(
        source_m4b_groups, file_records
    )
    metadata_overrides_by_file_id = {}
    for source_group in source_groups:
        group_overrides = merge_metadata_overrides(
            source_group.get("source_group", {}).get(
                "metadata_overrides", {}
            ),
            source_group.get("metadata_overrides", {}),
        )
        for member in source_group.get("records", ()):
            metadata_overrides_by_file_id[str(member["id"])] = copy.deepcopy(
                group_overrides
            )

    for target_index, target in enumerate(normalized_targets):
        fmt = str(target["format"]).lower()
        target_dir = Path(target.get("output_dir") or output_root).expanduser()
        if fmt != "m4b" and target.get("assembly_mode") != "merge":
            for index, file_record in enumerate(file_records, 1):
                relative_parent = (
                    file_record["relative"].parent if mirror_relative else Path(".")
                )
                context = {
                    "book": root_name,
                    "name": file_record["stem"],
                    "group": root_name,
                    "title": file_record["stem"],
                    "source_name": file_record["stem"],
                    "source_title": file_record["stem"],
                    "index": index,
                    "chapter": index,
                    "group_index": 1,
                    "file_index": index,
                    "chapter_count": total_files,
                    "part": 1,
                    "volume": 1,
                    "parts": 1,
                    "first_index": index,
                    "last_index": index,
                    "num": index,
                    "first": index,
                    "last": index,
                    "range": str(index),
                    "first_name": file_record["stem"],
                    "last_name": file_record["stem"],
                    "format": fmt,
                    "profile": target.get("profile", ""),
                    "ext": fmt,
                    "author": "",
                }
                basename = render_target_name(
                    target, context, file_record["stem"], fmt
                )
                add_record(
                    {
                        "target_index": target_index,
                        "target": target,
                        "item_id": file_record["id"],
                        "path": target_dir / relative_parent / f"{basename}.{fmt}",
                        "kind": "file",
                        "source_path": file_record["path"],
                        "source_paths": (file_record["path"],),
                        "file_ids": (file_record["id"],),
                        "metadata_overrides": copy.deepcopy(
                            metadata_overrides_by_file_id.get(
                                str(file_record["id"]), {}
                            )
                        ),
                    }
                )
            continue

        groups = source_groups
        if not groups:
            groups = (
                {
                    "index": 1,
                    "name": "",
                    "estimated_duration": 0.0,
                    "records": tuple(file_records),
                    "source_group": {},
                },
            )
        if fmt != "m4b":
            total_groups = len(groups)
            group_names = []
            for group in groups:
                members = tuple(group["records"])
                fallback = (
                    members[0]["stem"]
                    if len(members) == 1 and source_m4b_groups
                    else root_name
                )
                group_names.append(str(group.get("name") or "").strip() or fallback)
            name_counts = Counter(
                sanitize_filename_component(
                    _template_basename(name, fmt), fallback=root_name
                ).casefold()
                for name in group_names
            )
            for group_index, (group, group_name) in enumerate(
                zip(groups, group_names), 1
            ):
                members = tuple(group["records"])
                first_position = min(position_by_id[item["id"]] for item in members)
                last_position = max(position_by_id[item["id"]] for item in members)
                group_overrides = merge_metadata_overrides(
                    group.get("source_group", {}).get("metadata_overrides", {}),
                    group.get("metadata_overrides", {}),
                )
                context = {
                    "book": root_name,
                    "name": group_name,
                    "group": group_name,
                    "title": group_name,
                    "source_name": group_name,
                    "source_title": group_name,
                    "filename": members[0]["stem"],
                    "index": group_index,
                    "chapter": first_position,
                    "chapter_count": total_files,
                    "part": group_index,
                    "volume": group_index,
                    "parts": total_groups,
                    "num": group_index,
                    "first_index": first_position,
                    "last_index": last_position,
                    "first": first_position,
                    "last": last_position,
                    "range": format_chapter_range(
                        first_position, last_position, total_count=total_files
                    ),
                    "first_name": members[0]["stem"],
                    "last_name": members[-1]["stem"],
                    "format": fmt,
                    "profile": target.get("profile", ""),
                    "ext": fmt,
                    "author": str(group_overrides.get("artist", "") or ""),
                }
                basename = render_target_name(
                    target, context, group_name, fmt, grouped=True
                )
                # Одинаковые подпапки разных книг допустимы. Различаем их
                # стандартные имена, но ошибку явного шаблона не скрываем.
                if not target.get("filename_template") and name_counts[basename.casefold()] > 1:
                    basename = _append_m4b_part_suffix(
                        basename, {"part": group_index}, fallback=root_name
                    )
                add_record(
                    {
                        "target_index": target_index,
                        "target": target,
                        "item_id": str(
                            group.get("source_group", {}).get("id")
                            or f"source_group:{group_index}"
                        ),
                        "path": target_dir / f"{basename}.{fmt}",
                        "kind": "group",
                        "group_index": group_index,
                        "parts": total_groups,
                        "group_name": group_name,
                        "file_ids": tuple(item["id"] for item in members),
                        "source_paths": tuple(item["path"] for item in members),
                        "estimated_duration": float(group.get("estimated_duration", 0) or 0),
                        "chapter_count": total_files,
                        "book": root_name,
                        "chapter_start": first_position,
                        "chapter_end": last_position,
                        "metadata_overrides": copy.deepcopy(group_overrides),
                    }
                )
            continue
        # Ограничение числа глав безопасно применить до появления аудио, но
        # длительность в плане исходников является оценкой (интерфейс просит
        # символов в минуту), а не точным разделением. Для M4B фоновый обработчик выполняет
        # второй проход после синтеза: измеряет кэш и заново планирует целые
        # главы по импортированному лимиту и автоматическому ограничению длинной
        # книги перед записью итоговых файлов.
        try:
            imported_duration_limit = float(
                target.get("max_duration_seconds", 0) or 0
            )
        except (TypeError, ValueError, OverflowError):
            imported_duration_limit = 0.0
        if math.isfinite(imported_duration_limit) and imported_duration_limit > 0:
            logging.info(
                "Для M4B в синтезе из папки лимит длительности из набора "
                "выходов будет уточнён после синтеза по фактическим "
                "длительностям кэша; предварительный план остаётся оценочным."
            )
        max_chapters = int(target.get("max_chapters", 0) or 0)
        expanded_groups = []
        for group in groups:
            members = tuple(group["records"])
            if max_chapters > 0 and len(members) > max_chapters:
                for offset in range(0, len(members), max_chapters):
                    expanded_groups.append(
                        dict(
                            group,
                            records=members[offset : offset + max_chapters],
                            name=group.get("name", ""),
                            _split_part=True,
                        )
                    )
            else:
                expanded_groups.append(group)
        groups = tuple(expanded_groups)
        total_parts = len(groups)
        # В редакторе целей вкладки исходников намеренно нет отдельного поля
        # имени M4B. Старые снимки всё же сохраняли копию прежнего шаблона в
        # ``target.filename_template``. Если шаблон плана позже изменён, копия
        # не должна иметь приоритет. Историческое значение однозначно (строка
        # цели его не редактировала), поэтому правило действует и для группы
        # без плана. Для подготовленных групп такую защиту даёт маркер
        # происхождения ``name_template``, не затрагивая импортированные
        # пользовательские шаблоны без маркера.
        target_filename_template = str(
            target.get("filename_template") or ""
        ).strip()
        if (
            target_filename_template == DEFAULT_SOURCE_M4B_TEMPLATE
            and effective_source_m4b_template != DEFAULT_SOURCE_M4B_TEMPLATE
        ):
            target_filename_template = ""
        # Подготовленный или ручной виртуальный план может хранить понятное
        # имя группы вместо шаблона имени файла. При совпадении двух и более
        # имён сохраняем метку для метаданных, но ниже детерминированно
        # различаем файлы. Разные пользовательские имена не меняем: это не
        # добавляет неожиданный суффикс, а статический план ``{book}`` остаётся
        # безопасным.
        duplicate_group_name_keys = set()
        duplicate_template_name_keys = set()
        if fmt == "m4b" and total_parts > 1:
            fallback_name_counts = {}
            template_name_counts = {}
            for candidate_group in groups:
                candidate_name = str(candidate_group.get("name") or "").strip()
                stored_name_template = candidate_group.get("name_template")
                if (
                    stored_name_template is not None
                    and normalize_source_m4b_template(stored_name_template)
                    != effective_source_m4b_template
                ):
                    candidate_name = root_name
                candidate_name = candidate_name or root_name
                candidate_key = sanitize_filename_component(
                    _template_basename(candidate_name, "m4b"),
                    fallback="Группа",
                ).casefold()
                template_name_counts[candidate_key] = (
                    template_name_counts.get(candidate_key, 0) + 1
                )
                if not candidate_group.get("_split_part", False) and str(
                    candidate_group.get("name") or ""
                ).strip():
                    fallback_name_counts[candidate_key] = (
                        fallback_name_counts.get(candidate_key, 0) + 1
                    )
            duplicate_group_name_keys = {
                key for key, count in fallback_name_counts.items() if count > 1
            }
            duplicate_template_name_keys = {
                key for key, count in template_name_counts.items() if count > 1
            }
        for part_index, group in enumerate(groups, 1):
            members = tuple(group["records"])
            first_position = min(position_by_id[item["id"]] for item in members)
            last_position = max(position_by_id[item["id"]] for item in members)
            first = members[0]
            last = members[-1]
            group_name = str(group.get("name") or "").strip() or root_name
            group_metadata_overrides = merge_metadata_overrides(
                group.get("source_group", {}).get("metadata_overrides", {}),
                group.get("metadata_overrides", {}),
            )
            context = {
                "book": root_name,
                "name": group_name,
                "group": group_name,
                "title": group_name,
                "source_name": group_name,
                "source_title": group_name,
                "index": part_index,
                "chapter": first_position,
                "chapter_count": total_files,
                "part": part_index,
                "volume": part_index,
                "parts": total_parts,
                "group_index": part_index,
                "file_index": 1,
                # Короткие алиасы, разрешённые диалогом плана исходников,
                # заполняем и в фоновом планировщике. Иначе шаблон вроде
                # ``{num}`` пройдёт проверку интерфейса и сломается только при
                # рендеринге пути в фоновой задаче.
                "num": part_index,
                "first_index": first_position,
                "last_index": last_position,
                "first": first_position,
                "last": last_position,
                "range": format_chapter_range(
                    first_position,
                    last_position,
                    total_count=max(
                        total_files,
                        int(group.get("range_total_count", 0) or 0),
                    ),
                    width=(
                        int(group.get("range_width", 0) or 0) or None
                    ),
                ),
                "first_name": first["stem"],
                "last_name": last["stem"],
                "format": "m4b",
                "profile": target.get("profile", ""),
                "ext": "m4b",
                "author": str(
                    group_metadata_overrides.get("artist", "") or ""
                ),
            }
            # Диалог оценки выводит пользовательский шаблон в имя виртуальной
            # группы. Если у цели M4B нет отдельного шаблона имени файла,
            # используем видимую метку как основу имени; иначе дерево и файл на
            # диске описывали бы разные части. При запуске без плана имени нет,
            # поэтому остаётся исторический адаптивный запасной вариант
            # ``Книга Главы range``.
            has_group_name = bool(str(group.get("name") or "").strip())
            # Имя виртуальной группы создаётся из шаблона плана исходников.
            # Если шаблон потом изменён (например, очищен ``{range}``), старую
            # метку нельзя переиспользовать: она вернула бы устаревшее имя
            # ``Книга Главы 1-26`` вместо запрошенной ``Книга``. Маркер не
            # обязателен для совместимости с ручными и импортированными
            # планами: без него имя считается намеренной пользовательской
            # меткой. Явный пустой маркер нормализуем в ``{book}``.
            stored_name_template = group.get("name_template")
            stale_generated_name = False
            if stored_name_template is not None:
                stored_template = normalize_source_m4b_template(
                    stored_name_template
                )
                stale_generated_name = (
                    stored_template != effective_source_m4b_template
                )
                # ``name_template`` — происхождение автоматически созданной
                # метки виртуальной группы, а не пользовательский заголовок.
                # После смены шаблона старую метку нельзя подставлять в
                # ``{name}``, ``{group}`` или ``{title}``: новый шаблон вроде
                # ``{name}`` иначе получил бы текст ``Книга Главы 1-26``.
                # В этом случае алиасы начинаются со стабильного имени книги,
                # а поля главы и диапазона ниже описывают текущую группу.
                if stale_generated_name:
                    context["name"] = root_name
                    context["group"] = root_name
                    context["title"] = root_name
                    context["source_name"] = root_name
                    context["source_title"] = root_name
                # Шаблон цели, совпавший с шаблоном этой виртуальной метки,
                # также устарел после смены плана. Не меняем сохранённую цель,
                # а создаём копию только для вывода, чтобы импортированный
                # объект у вызывающего кода сохранил исходное значение.
                if (
                    target_filename_template
                    and normalize_source_m4b_template(
                        target_filename_template
                    )
                    == stored_template
                    and stored_template != effective_source_m4b_template
                ):
                    render_filename_template_override = ""
                else:
                    render_filename_template_override = (
                        target_filename_template
                    )
            else:
                render_filename_template_override = target_filename_template
            # Лимит глав на уровне цели может превратить одну виртуальную
            # группу в несколько записей отложенного этапа. Исходное имя оценки
            # тогда общее, поэтому для разделённых записей используем
            # адаптивный диапазон и сохраняем уникальные пути. Явный шаблон
            # цели по-прежнему имеет полный приоритет и может использовать
            # поле шаблона ``{part}``.
            use_group_name_fallback = (
                has_group_name
                and not group.get("_split_part", False)
                and not stale_generated_name
            )
            group_name_fallback = (
                group_name
                if use_group_name_fallback
                else f"{root_name} Главы {context['range']}"
            )
            target_for_render = target
            if (
                render_filename_template_override
                != target_filename_template
            ):
                target_for_render = dict(target)
                target_for_render[
                    "filename_template"
                ] = render_filename_template_override
            elif not target_filename_template and str(
                target.get("filename_template") or ""
            ).strip():
                # Для исторического значения по умолчанию без маркера также
                # нужна копия только для вывода. Отдельная ветка подчёркивает
                # намерение и не меняет нормализованную цель, общую для записей.
                target_for_render = dict(target)
                target_for_render["filename_template"] = ""
            basename = render_target_name(
                target_for_render,
                context,
                group_name_fallback,
                "m4b",
                use_default_m4b_template=not use_group_name_fallback,
                varying_m4b_fields=(
                    M4B_GROUP_NAME_TEMPLATE_FIELDS
                    if sanitize_filename_component(
                        _template_basename(context["name"], "m4b"),
                        fallback="Группа",
                    ).casefold()
                    not in duplicate_template_name_keys
                    else ()
                ),
            )
            if (
                use_group_name_fallback
                and not str(target_for_render.get("filename_template") or "").strip()
                and duplicate_group_name_keys
                and sanitize_filename_component(
                    _template_basename(group_name, "m4b"),
                    fallback="Группа",
                ).casefold()
                in duplicate_group_name_keys
            ):
                basename = _append_m4b_part_suffix(
                    basename,
                    {"part": part_index},
                    fallback=root_name,
                )
            base_group_id = str(
                group.get("source_group", {}).get("id")
                or f"source_m4b:{part_index}"
            )
            # Разделение по числу глав может создать несколько записей из одной
            # виртуальной группы. Для неразделённого случая сохраняем ID, а для
            # расширенного плана делаем каждую задачу адресуемой.
            group_id = (
                f"{base_group_id}:part-{part_index}"
                if group.get("_split_part")
                else base_group_id
            )
            add_record(
                {
                    "target_index": target_index,
                    "target": target,
                    # Строки M4B исходников именуются виртуальным планом.
                    # Храним происхождение отдельно от переносимой цели, чтобы
                    # импортированная цель со своим шаблоном сохранила его при
                    # перестроении по длительности. Старые записи без флага
                    # используют исторический порядок приоритетов.
                    "source_template_owned": not bool(
                        str(
                            target_for_render.get("filename_template") or ""
                        ).strip()
                    ),
                    "item_id": group_id,
                    "path": target_dir / f"{basename}.m4b",
                    "kind": "m4b",
                    "group_index": part_index,
                    "parts": total_parts,
                    "group_name": group_name,
                    "name_template": group.get("name_template"),
                    "file_ids": tuple(item["id"] for item in members),
                    "source_paths": tuple(item["path"] for item in members),
                    "estimated_duration": float(group.get("estimated_duration", 0) or 0),
                    "chapter_count": total_files,
                    "book": root_name,
                    "chapter_start": first_position,
                    "chapter_end": last_position,
                    "metadata_overrides": copy.deepcopy(
                        group_metadata_overrides
                    ),
                }
            )
    return tuple(records)


def _source_synthesis_tag_values(config, basename):
    """Возвращает теги книжного синтеза для конкретной цели вывода.

    Снимок конфигурации передаётся из интерфейса до запуска фонового обработчика.
    Поэтому функция
    не читает Tk-переменные и безопасна для фонового потока. Шаблоны старого
    профиля (`{filename}`, `{name}`, `{title}`) сохраняют прежнюю семантику.
    """
    if not _config_bool(
        (config or {}).get("apply_output_tags", True), default=True
    ):
        return {}
    basename = Path(str(basename or "Без названия")).stem
    result = {}
    for source_key, ffmpeg_key in (
        ("tag_title", "title"),
        ("tag_artist", "artist"),
        ("tag_album_artist", "album_artist"),
        ("tag_album", "album"),
        ("tag_genre", "genre"),
        ("tag_composer", "composer"),
        ("tag_year", "date"),
    ):
        value = str((config or {}).get(source_key, "") or "")
        if not value:
            continue
        for token in ("{filename}", "{name}", "{title}"):
            value = value.replace(token, basename)
        value = value.strip()
        if value:
            result[ffmpeg_key] = value
    # Название логической книги является безопасным альбомом по умолчанию.
    # Явный тег из настроек или локальное переопределение группы по-прежнему
    # имеют приоритет и применяются соответственно выше и вызывающей стороной.
    if "album" not in result:
        book_name = str((config or {}).get("source_book_name") or "").strip()
        if book_name:
            result["album"] = book_name
    return result


def log_saved_audio(path, *, has_warnings=False):
    """Записывает единое INFO-сообщение после успешного сохранения аудио."""
    try:
        resolved = Path(path).expanduser().resolve()
    except (OSError, RuntimeError, TypeError, ValueError):
        resolved = Path(str(path))
    suffix = " (с предупреждениями)" if has_warnings else ""
    logging.info("Аудиофайл сохранён%s: %s", suffix, resolved)


def apply_source_metadata_overrides(tags, overrides):
    """Применяет теги виртуальной части, включая явную очистку поля."""
    result = dict(tags or {})
    values = merge_metadata_overrides(overrides or {})
    mapping = {
        "title": "title",
        "artist": "artist",
        "album_artist": "album_artist",
        "album": "album",
        "genre": "genre",
        "composer": "composer",
        "year": "date",
    }
    for source_key, ffmpeg_key in mapping.items():
        if source_key not in values:
            continue
        value = str(values[source_key] or "").strip()
        if value:
            result[ffmpeg_key] = value
        else:
            result.pop(ffmpeg_key, None)
    return result


def _source_synthesis_target_effects(target, config):
    """Разрешает эффекты одной цели из неизменяемых снимков цели и конфигурации."""
    target = target if isinstance(target, dict) else {}
    effects = target.get("effects")
    if not isinstance(effects, dict):
        effects = {}
    # Профиль цели владеет значениями эффектов. Если он явно отключает
    # эффекты, сохраняем нейтральные значения, даже когда старая компактная
    # панель содержит ненейтральные параметры.
    enabled = _config_bool(target.get("apply_effects", False), default=False)
    if enabled:
        source = effects
    else:
        source = {}
    try:
        speed = float(source.get("speed", 1.0))
        pitch = float(source.get("pitch", 1.0))
        echo_delay = int(float(source.get("echo_delay", 300)))
        echo_decay = float(source.get("echo_decay", 0.3))
    except (TypeError, ValueError, OverflowError):
        # Цели уже прошли normalize_output_target; эта запасная ветка защищает
        # только прямые вызовы с вручную составленным отображением.
        speed, pitch, echo_delay, echo_decay = 1.0, 1.0, 300, 0.3
    return {
        "enabled": enabled,
        "speed": speed,
        "pitch": pitch,
        "echo": _config_bool(source.get("echo", False), default=False),
        "echo_delay": echo_delay,
        "echo_decay": echo_decay,
    }


def _call_source_target_status(callback, fmt, output_path, status):
    """Вызывает необязательный обработчик статуса с совместимыми резервными сигнатурами."""
    if callback is None:
        return
    try:
        callback(fmt, Path(output_path), status)
    except TypeError:
        # Небольшие интеграции, написанные до расширения контракта статуса,
        # часто принимают только ``(format, status)``. Сохраняем их работу, не
        # меняя публичные обратные вызовы TTSProcessor.
        try:
            callback(fmt, status)
        except TypeError:
            callback(status)


def _source_synthesis_cache_profiles(audio_files):
    """Построить быстрые профили ffprobe для канонических файлов кэша.

    Один TXT может содержать сотни фрагментов, и все цели вывода используют
    один и тот же набор. Запуск ``ffprobe`` для каждого фрагмента каждого
    формата сделал бы работу с попаданиями в кэш неоправданно медленной.
    TTSProcessor уже привёл файлы к Ogg/Opus, поэтому достаточно первой страницы
    Ogg. Хеш OpusHead также входит в профиль: копирование потока разрешается
    только при полном совпадении настроек кодека, а не только частоты и каналов.

    Для нечитаемой записи или записи не Opus сохраняем ``None``. Общий помощник
    выберет консервативный запасной путь, а FFmpeg сообщит настоящую ошибку для
    каждой независимой цели.
    """
    profiles = []
    for path in audio_files or ():
        codec, channels, identity = _inspect_ogg_audio_header_details(path)
        if codec != CACHE_AUDIO_CODEC or not channels or identity is None:
            profiles.append(None)
            continue
        profiles.append(
            {
                "codec": CACHE_AUDIO_CODEC,
                # Opus всегда декодируется на временной шкале 48 кГц; OpusHead
                # хранит каналы и параметры кодека, но не альтернативную частоту
                # формат PCM.
                "sample_rate": CACHE_AUDIO_SAMPLE_RATE,
                "channels": int(channels),
                "bitrate": None,
                "format_name": "ogg",
                "channel_layout": "mono" if int(channels) == 1 else "stereo",
                "time_base": f"1/{CACHE_AUDIO_SAMPLE_RATE}",
                "extradata_hash": hashlib.sha256(identity).hexdigest(),
            }
        )
    return tuple(profiles)


def run_source_synthesis_target_chain(
    processor,
    audio_files,
    records,
    config,
    *,
    skip_existing=False,
    status_callback=None,
    cancelled=None,
):
    """Кодирует обычные цели одного TXT или группы последовательно.

    ``audio_files`` уже собраны одним проходом API/кэша. Каждая запись
    планировщика кодируется в порядке ``target_index``, а независимые TXT и группы
    могут выполнять эту функцию в разных фоновых потоках. Ограничение ``processor``
    ``encode_semaphore`` охватывает ровно одну FFmpeg-операцию.

    M4B обрабатывает ``run_source_synthesis_m4b_target`` после готовности всех
    глав соответствующей группы; здесь его записи не кодируются.
    """
    source_files = tuple(Path(path).expanduser() for path in (audio_files or ()))
    # Используем один снимок заголовков для всех форматов. Это исключает
    # отдельный запуск ffprobe для каждой пары «цель × предложение» и не
    # добавляет промежуточное кодирование с потерями.
    source_profiles = _source_synthesis_cache_profiles(source_files)
    result_rows = []
    failures = 0
    deferred = 0
    for record in sorted(
        tuple(records or ()), key=lambda item: int(item.get("target_index", 0))
    ):
        target = normalize_output_target(record.get("target", {}))
        fmt = str(target.get("format", "")).lower()
        output_path = Path(record.get("path", "")).expanduser()
        if fmt == "m4b":
            deferred += 1
            message = (
                "M4B-цель отложена до заключительного этапа групп; "
                "используйте подготовленный план глав."
            )
            logging.warning("%s: %s", output_path.name, message)
            _call_source_target_status(status_callback, fmt, output_path, "warning")
            result_rows.append(
                {"format": fmt, "path": output_path, "status": "deferred"}
            )
            continue
        if cancelled and cancelled():
            raise InterruptedError("Синтез остановлен пользователем")
        if getattr(processor, "is_stopped", False):
            raise InterruptedError("Синтез остановлен пользователем")
        if not source_files:
            failures += 1
            _call_source_target_status(status_callback, fmt, output_path, "error")
            result_rows.append(
                {"format": fmt, "path": output_path, "status": "error"}
            )
            logging.error("Цель %s пропущена: нет канонических аудиофрагментов", output_path)
            continue

        output_path.parent.mkdir(parents=True, exist_ok=True)
        status_key = str(output_path.resolve())
        already_done = (
            bool(skip_existing)
            and output_path.is_file()
            and getattr(processor, "processing_statuses_ram", {}).get(
                status_key, "success"
            )
            == "success"
        )
        if already_done:
            _call_source_target_status(status_callback, fmt, output_path, "success")
            result_rows.append(
                {"format": fmt, "path": output_path, "status": "skipped"}
            )
            continue

        _call_source_target_status(status_callback, fmt, output_path, "encoding")
        effects = _source_synthesis_target_effects(target, config)
        requested_bitrate = str(target.get("bitrate", "auto") or "auto").lower()
        tags = _source_synthesis_tag_values(config, output_path.name)
        metadata_overrides = merge_metadata_overrides(
            record.get("metadata_overrides", {})
        )
        apply_tags = _config_bool(
            config.get("apply_output_tags", True), default=True
        )
        if apply_tags:
            tags = apply_source_metadata_overrides(tags, metadata_overrides)
            cover = str(
                metadata_overrides.get(
                    "cover", config.get("tag_cover", "")
                )
                or ""
            ).strip()
        else:
            cover = None
        kwargs = {
            "output_format": fmt,
            "bitrate": None if requested_bitrate == "auto" else requested_bitrate,
            "bitrate_mode": requested_bitrate,
            "sample_rate": target.get("sample_rate", "auto"),
            "channels": target.get("channels", "auto"),
            "pause_ms": 0,
            "speed": effects["speed"],
            "pitch": effects["pitch"],
            "echo": effects["echo"],
            "echo_delay": effects["echo_delay"],
            "echo_decay": effects["echo_decay"],
            "tags": tags,
            "cover": cover,
            "cancelled": lambda: bool(
                getattr(processor, "is_stopped", False)
                or (cancelled and cancelled())
            ),
            "_probed_profiles": source_profiles,
        }
        try:
            semaphore = getattr(processor, "encode_semaphore", None)
            if semaphore is not None:
                with semaphore:
                    _export_merged_audio_ffmpeg(
                        source_files, output_path, **kwargs
                    )
            else:
                _export_merged_audio_ffmpeg(source_files, output_path, **kwargs)
            if hasattr(processor, "_mark_output_status"):
                processor._mark_output_status(output_path, "success")
            _call_source_target_status(status_callback, fmt, output_path, "success")
            log_saved_audio(output_path)
            result_rows.append(
                {"format": fmt, "path": output_path, "status": "success"}
            )
        except InterruptedError:
            raise
        except Exception as exc:
            failures += 1
            if hasattr(processor, "_mark_output_status"):
                processor._mark_output_status(output_path, "error")
            _call_source_target_status(status_callback, fmt, output_path, "error")
            result_rows.append(
                {"format": fmt, "path": output_path, "status": "error", "error": str(exc)}
            )
            logging.error(
                "Ошибка сборки цели %s (%s): %s", output_path.name, fmt, exc
            )

    succeeded = sum(
        row["status"] in {"success", "skipped"} for row in result_rows
    )
    if failures and succeeded:
        status = "warning"
    elif failures or deferred and not succeeded:
        status = "error"
    elif deferred:
        status = "warning"
    else:
        status = "success"
    return {
        "status": status,
        "results": tuple(result_rows),
        "succeeded": succeeded,
        "failed": failures,
        "deferred": deferred,
    }


def _measure_source_m4b_chapter_durations(
    records,
    audio_by_file_id,
    *,
    cancelled=None,
    progress_callback=None,
    known_durations=None,
    duration_by_path=None,
):
    """Снимает фактические длительности TXT-глав из уже собранного кэша.

    Один TXT является неделимой главой M4B, даже если внутри него несколько
    Opus-фрагментов. Поэтому длительность главы складывается из длительностей
    всех её канонических фрагментов (включая сохранённые паузы). Функция
    намеренно не создаёт промежуточный файл и ничего не меняет в кэше; это
    позволяет выполнить второй проход после единственного API-прохода.

    ``_probe_audio_duration`` возвращает ``0`` при повреждённом/нечитаемом
    файле. В таком случае мы останавливаем перестроение целиком: частично
    рассчитанные границы были бы опаснее, чем сохранение исходного плана.
    """
    # Материализуем вход один раз: предварительный подсчёт и цикл измерения
    # должны пройти записи повторно.
    records = tuple(
        record for record in (records or ()) if isinstance(record, dict)
    )
    durations = {}
    for raw_id, raw_duration in dict(known_durations or {}).items():
        try:
            duration = float(raw_duration)
        except (TypeError, ValueError, OverflowError):
            continue
        if math.isfinite(duration) and duration > 0:
            durations[str(raw_id)] = duration
    # Проход измерения заметен на большом кэше: каждый канонический фрагмент
    # проверяется отдельным быстрым процессом ffprobe. Обратный вызов оставляем
    # необязательным, чтобы чистый фоновый обработчик работал и без интерфейса.
    # Ошибки обратного вызова намеренно подавляются: устаревшее окно Tk не должно испортить
    # корректное измерение.
    def notify_progress(current, total, text):
        if progress_callback is None:
            return
        try:
            progress_callback(current, total, str(text or "M4B: измерение…"))
        except Exception:
            logging.debug(
                "Не удалось обновить прогресс измерения M4B", exc_info=True
            )

    chapter_ids = []
    seen_ids = set()
    # Фрагменты пауз используются многими TXT. За проход измеряем каждый
    # физический путь один раз, не запуская ffprobe повторно для каждой главы,
    # ссылающейся на один файл тишины.
    if duration_by_path is None:
        duration_by_path = {}
    for record in records or ():
        for raw_id in tuple(record.get("file_ids", ())):
            file_id = str(raw_id)
            if file_id and file_id not in seen_ids:
                seen_ids.add(file_id)
                chapter_ids.append(file_id)
    total_chapters = max(1, len(chapter_ids))
    measured_chapters = sum(file_id in durations for file_id in chapter_ids)
    notify_progress(
        measured_chapters,
        total_chapters,
        "M4B: измерение длительности глав…",
    )
    chapter_position = {file_id: index for index, file_id in enumerate(chapter_ids, 1)}
    for record in records or ():
        for raw_id in tuple(record.get("file_ids", ())):
            file_id = str(raw_id)
            if file_id in durations:
                continue
            if cancelled and cancelled():
                raise InterruptedError("Синтез остановлен пользователем")
            raw_files = None
            try:
                raw_files = audio_by_file_id.get(raw_id)
            except AttributeError:
                raw_files = None
            if raw_files is None:
                try:
                    raw_files = audio_by_file_id.get(file_id)
                except AttributeError:
                    raw_files = None
            files = tuple(Path(path).expanduser() for path in (raw_files or ()))
            if not files:
                raise ValueError(
                    f"Для главы {file_id} нет собранных аудиофрагментов"
                )
            chapter_index = chapter_position.get(file_id, len(durations) + 1)
            # Для отдельных фрагментов кэша нет осмысленного процента по байтам.
            # Публикуем только статус: полоса остаётся на последней завершённой
            # главе и двигается целиком после её измерения.
            notify_progress(
                PROGRESS_STATUS_ONLY,
                total_chapters,
                f"M4B: измерение главы {chapter_index}/{total_chapters}…",
            )
            total = 0.0
            for path in files:
                if cancelled and cancelled():
                    raise InterruptedError("Синтез остановлен пользователем")
                try:
                    duration_key = str(path.resolve())
                except (OSError, RuntimeError, TypeError, ValueError):
                    duration_key = str(path)
                duration = duration_by_path.get(duration_key)
                try:
                    duration = float(duration)
                except (TypeError, ValueError, OverflowError):
                    duration = 0.0
                if not math.isfinite(duration) or duration <= 0:
                    duration_by_path.pop(duration_key, None)
                    duration = _probe_audio_duration(path)
                    try:
                        duration = float(duration)
                    except (TypeError, ValueError, OverflowError):
                        duration = 0.0
                if not math.isfinite(duration) or duration <= 0:
                    raise ValueError(
                        f"Не удалось определить фактическую длительность главы "
                        f"{file_id} (файл {path.name})"
                    )
                # Неудачный фоновый ffprobe не должен отравить общий кэш:
                # заключительный этап обязан суметь повторить измерение.
                duration_by_path[duration_key] = duration
                total += duration
            if not math.isfinite(total) or total <= 0:
                raise ValueError(
                    f"Не удалось определить фактическую длительность главы {file_id}"
                )
            durations[file_id] = total
            measured_chapters += 1
            notify_progress(
                measured_chapters,
                total_chapters,
                f"M4B: измерено глав {measured_chapters}/{total_chapters}…",
            )
    return durations


def _split_source_m4b_groups_by_chapter_count(groups, max_chapters):
    """Делит уже рассчитанные группы только по целым главам.

    Ограничение количества глав применяется после переразбиения по длительности и никогда
    не режет отдельный TXT. Нулевой лимит оставляет группы без изменений.
    """
    try:
        limit = int(max_chapters or 0)
    except (TypeError, ValueError, OverflowError):
        limit = 0
    if limit <= 0:
        return tuple(tuple(group) for group in groups or ())
    result = []
    for group in groups or ():
        values = tuple(group)
        for offset in range(0, len(values), limit):
            result.append(values[offset : offset + limit])
    return tuple(result)


def reflow_source_m4b_target_records(
    records,
    audio_by_file_id,
    config=None,
    *,
    source_root=None,
    output_root=None,
    source_path_by_id=None,
    cancelled=None,
    progress_callback=None,
    auto_split_long=None,
    chapter_duration_overrides=None,
    fragment_duration_cache=None,
):
    """Перестраивает записи M4B исходников по реальным длительностям кэша.

    Возвращает словарь с ``records`` (новый неизменяемый снимок), картой
    ``durations`` и диагностикой. Каждая цель перестраивается независимо,
    но порядок TXT внутри него сохраняется. Если лимит отсутствует, старые
    границы сохраняются, а измеренные длительности всё равно возвращаются для
    точных метаданных глав. При любой ошибке измерения выбрасывается
    исключение, чтобы вызывающий код мог безопасно продолжить со старым
    планом.

    Эта функция не обращается к Tkinter и подходит для фонового потока.
    """
    config = config if isinstance(config, dict) else {}
    if auto_split_long is None:
        # Защитное правило для M4B исходников включено по умолчанию.
        auto_split_long = _config_bool(
            config.get("source_m4b_auto_split_long", True), default=True
        )
    else:
        auto_split_long = _config_bool(auto_split_long, default=True)
    # Защитное правило и явная опция «перестроить по фактической длительности»
    # имеют разный смысл. Правило лишь удерживает случайно длинную книгу в
    # консервативном лимите M4B и не должно молча отменять ручные границы томов.
    # Явная опция, напротив, разрешает объединить границы и заново жадно
    # упаковать всю цель.
    explicit_reflow = _config_bool(
        config.get("source_m4b_reflow_actual_duration", False),
        default=False,
    )
    preserve_existing_boundaries = bool(auto_split_long and not explicit_reflow)
    records = tuple(record for record in (records or ()) if isinstance(record, dict))
    if not records:
        return {"records": tuple(), "durations": {}, "diagnostics": tuple(), "changed": False}

    durations = _measure_source_m4b_chapter_durations(
        records,
        audio_by_file_id,
        cancelled=cancelled,
        progress_callback=progress_callback,
        known_durations=chapter_duration_overrides,
        duration_by_path=fragment_duration_cache,
    )
    try:
        global_limit = float(
            config.get("source_m4b_reflow_limit_seconds", 0) or 0
        )
    except (TypeError, ValueError, OverflowError):
        global_limit = 0.0
    if not math.isfinite(global_limit) or global_limit < 0:
        global_limit = 0.0

    source_root = Path(
        source_root or config.get("input_dir") or "."
    ).expanduser().resolve()
    output_root = Path(
        output_root or config.get("output_dir") or "."
    ).expanduser()
    path_map = source_path_by_id or config.get("source_path_by_id") or {}

    # Перестроение по фактической длительности также применяет консервативный
    # предел 23:50. Меньший пользовательский лимит сохраняет приоритет;
    # слишком длинная отдельная глава остаётся целой и попадает в диагностику.
    # Обычные пути вывода не участвуют в проверке коллизий: вызывающий код
    # передаёт все записи, но помощник ожидает здесь только M4B.
    by_target = {}
    target_order = []
    for record in records:
        try:
            target_index = int(record.get("target_index", 0) or 0)
        except (TypeError, ValueError, OverflowError):
            target_index = 0
        if target_index not in by_target:
            by_target[target_index] = []
            target_order.append(target_index)
        by_target[target_index].append(record)

    rebuilt = []
    diagnostics = []
    changed = False

    def target_duration_limit(target_records, target):
        """Определить явный, общий или автоматический лимит M4B цели."""
        try:
            requested = float(target.get("max_duration_seconds", 0) or 0)
        except (TypeError, ValueError, OverflowError):
            requested = 0.0
        if not math.isfinite(requested) or requested < 0:
            requested = 0.0
        # В компактном редакторе строки целей исходников намеренно не показывают
        # собственное поле длительности. Переносимая или импортированная строка
        # всё же может его содержать; при явном включении второго прохода её общий
        # лимит в минутах имеет приоритет. Сохраняем более строгий импортированный
        # лимит, но не позволяем ему незаметно сделать перестроение длиннее видимого.
        if explicit_reflow and global_limit > 0:
            requested = (
                min(requested, global_limit) if requested > 0 else global_limit
            )
        elif requested <= 0:
            requested = global_limit
        # ``target_records`` — упорядоченные главы. Сумма измеренных длительностей
        # позволяет цели без лимита включить защитное разделение после 24 часов;
        # текст и главы этим расчётом никогда не режутся.
        chapter_ids = tuple(
            str(file_id)
            for record in target_records
            for file_id in tuple(record.get("file_ids", ()))
        )
        total_duration = sum(float(durations.get(file_id, 0.0) or 0.0)
                             for file_id in chapter_ids)
        if auto_split_long:
            return resolve_m4b_auto_duration_limit(
                total_duration,
                requested,
            )
        return effective_m4b_duration_limit(requested)

    def reflow_groups(old_groups, target_limit):
        """Вернуть новые группы и диагностику для одной цели исходников.

        При включённом только автоматическом ограничении свыше 24 часов каждая
        существующая виртуальная группа считается отдельным томом: слишком
        большую группу можно разделить по границам TXT, но главы не переходят
        через ручную границу. Явный флажок перестроения по длительности включает
        прежнюю глобальную жадную упаковку и может объединить соседние группы.
        """
        if target_limit <= 0:
            return tuple(old_groups), tuple()
        if not preserve_existing_boundaries:
            result = reflow_m4b_groups_by_duration(
                old_groups,
                durations,
                target_limit,
                pause_seconds=0,
            )
            return tuple(result.groups), tuple(result.oversized)

        rebuilt_groups = []
        local_diagnostics = []
        chapter_offset = 0
        for source_group_index, group in enumerate(old_groups, 1):
            result = reflow_m4b_groups_by_duration(
                (group,),
                durations,
                target_limit,
                pause_seconds=0,
            )
            rebuilt_groups.extend(result.groups)
            for diagnostic in result.oversized:
                # ``reflow_m4b_groups_by_duration`` получает одну группу за
                # раз, поэтому возвращаем координаты диагностики к полной цели
                # для понятного журнала и вызывающего кода.
                local_diagnostics.append(
                    M4BReflowDiagnostic(
                        chapter_id=diagnostic.chapter_id,
                        chapter_index=diagnostic.chapter_index + chapter_offset,
                        duration_seconds=diagnostic.duration_seconds,
                        limit_seconds=diagnostic.limit_seconds,
                        over_by_seconds=diagnostic.over_by_seconds,
                        source_group_index=source_group_index,
                        reason=diagnostic.reason,
                    )
                )
            chapter_offset += len(group)
        return tuple(rebuilt_groups), tuple(local_diagnostics)

    # Резервируем все существующие назначения, включая цели, которые должны
    # переместиться. Иначе ранняя цель могла бы занять старый путь поздней и
    # пройти проверку, а затем поздняя откатилась бы из-за другой коллизии;
    # итоговый снимок содержал бы две записи одного файла. Счётчики вместо
    # множества сохраняют защиту даже при дубликатах в повреждённом снимке.
    old_path_keys_by_target = {}
    occupied = Counter()
    for target_index, target_records in by_target.items():
        keys = []
        for record in target_records:
            try:
                key = os.path.normcase(
                    str(Path(record.get("path", "")))
                ).casefold()
            except (TypeError, ValueError, OSError):
                continue
            keys.append(key)
            occupied[key] += 1
        old_path_keys_by_target[target_index] = tuple(keys)
    for target_index in target_order:
        target_records = tuple(by_target[target_index])
        target = normalize_output_target(target_records[0].get("target", {}))
        target_limit = target_duration_limit(target_records, target)

        old_groups = tuple(
            tuple(str(file_id) for file_id in record.get("file_ids", ()))
            for record in target_records
        )
        if not any(old_groups):
            rebuilt.extend(target_records)
            continue

        if target_limit <= 0:
            new_groups = old_groups
            reflow_diagnostics = tuple()
        else:
            new_groups, reflow_diagnostics = reflow_groups(
                old_groups,
                target_limit,
            )
            new_groups = _split_source_m4b_groups_by_chapter_count(
                new_groups,
                target.get("max_chapters", 0),
            )
            if reflow_diagnostics:
                diagnostics.extend(reflow_diagnostics)

        if tuple(new_groups) == old_groups:
            # Если границы не изменились, сохраняем исходные имена и ID, но
            # всё равно передаём точные длительности экспортёру отложенного
            # этапа.
            rebuilt.extend(target_records)
            continue

        # Перепланируем только эту цель. Передача подмножества исходных узлов
        # не создаёт запасных групп для TXT, относящихся к другой цели.
        ordered_ids = tuple(
            file_id for group in new_groups for file_id in group
        )
        source_nodes = []
        for file_id in ordered_ids:
            raw_path = None
            try:
                raw_path = path_map.get(file_id)
                if raw_path is None:
                    raw_path = path_map.get(str(file_id))
            except AttributeError:
                raw_path = None
            if raw_path is None:
                for old_record in target_records:
                    ids = tuple(str(value) for value in old_record.get("file_ids", ()))
                    if file_id in ids:
                        paths = tuple(old_record.get("source_paths", ()))
                        position = ids.index(file_id)
                        raw_path = paths[position] if position < len(paths) else None
                        break
            if raw_path is None:
                raise ValueError(f"Для главы {file_id} не найден исходный TXT")
            source_nodes.append({"id": file_id, "path": str(raw_path)})

        old_by_exact_members = {
            tuple(str(value) for value in record.get("file_ids", ())): record
            for record in target_records
        }
        old_metadata_owners = tuple(
            (
                set(str(value) for value in record.get("file_ids", ())),
                merge_metadata_overrides(record.get("metadata_overrides", {})),
            )
            for record in target_records
        )

        def metadata_for_rebuilt_group(group):
            members = set(str(value) for value in group)
            owners = [
                metadata
                for old_members, metadata in old_metadata_owners
                if members and members.intersection(old_members)
            ]
            if len(owners) == 1:
                return copy.deepcopy(owners[0])
            if owners and all(owner == owners[0] for owner in owners[1:]):
                return copy.deepcopy(owners[0])
            return {}

        group_defs = []
        for index, group in enumerate(new_groups, 1):
            members = tuple(str(value) for value in group)
            exact_record = old_by_exact_members.get(members, {})
            group_defs.append(
                {
                    "id": f"source_m4b_reflow:{target_index}:{index}",
                    "file_ids": members,
                    # Неизменившаяся соседняя часть сохраняет ручное имя, даже
                    # если другая часть той же цели была разделена. Для новой
                    # границы имя заново строится по шаблону и диапазону.
                    "name": str(exact_record.get("group_name") or ""),
                    "name_template": exact_record.get("name_template"),
                    "metadata_overrides": metadata_for_rebuilt_group(members),
                }
            )
        group_defs = tuple(group_defs)
        target_for_plan = copy.deepcopy(target)
        source_template = _source_m4b_template_from_config(config)
        # Записи планировщика исходников содержат признак, что имя принадлежит
        # диалогу плана. При перестроении по длительности передаём планировщику
        # пустой шаблон цели, чтобы устаревшая копия не вернула ``Главы
        # {range}``. Старые и прямые интеграционные вызовы не имеют флага и
        # сохраняют явный шаблон уровня цели для совместимости.
        if target_records and target_records[0].get("source_template_owned"):
            target_for_plan["filename_template"] = ""
        elif source_template and not str(
            target_for_plan.get("filename_template") or ""
        ).strip():
            target_for_plan["filename_template"] = source_template
        # Имя входной папки является лишь запасным вариантом. Исходный план
        # уже хранит выбранное пользователем имя книги; второй проход по
        # длительности не должен внезапно переименовывать все новые части в
        # техническое имя каталога источников.
        planned_book_name = next(
            (
                str(record.get("book") or "").strip()
                for record in target_records
                if str(record.get("book") or "").strip()
            ),
            "",
        )
        planned_book_name = resolve_source_book_name(
            config,
            source_root,
            planned_book_name,
        )
        generated = plan_source_synthesis_target_paths(
            source_root,
            output_root,
            source_nodes,
            targets=(target_for_plan,),
            mirror_relative=False,
            legacy_output_dir=str(output_root),
            source_m4b_groups=group_defs,
            book_name=planned_book_name,
            path_by_id={str(node["id"]): Path(node["path"]) for node in source_nodes},
            m4b_template=source_template,
        )
        generated = tuple(
            dict(record, target_index=target_index)
            for record in generated
            if record.get("kind") == "m4b"
        )
        if len(generated) != len(new_groups):
            raise ValueError("Планировщик M4B вернул неполное число частей")
        # Проверяем полный набор кандидатов транзакционно. Изменение
        # ``occupied`` по ходу цикла раньше оставляло пути первых частей, если
        # поздняя сталкивалась, хотя цель откатывалась к исходным записям. И
        # внутренний дубликат зависел от порядка обхода. Сначала материализуем
        # все ключи, проверяем дубликаты и внешние пересечения и лишь затем
        # публикуем набор после успешной проверки всей цели.
        candidate_paths = tuple(
            Path(generated_record["path"])
            for generated_record in generated
        )
        candidate_keys = tuple(
            os.path.normcase(str(path)).casefold()
            for path in candidate_paths
        )
        # При проверке замены освобождаем только владение этой цели. Старые
        # пути последующих целей остаются зарезервированными до их успешного
        # перемещения, поэтому режим пропуска готовых файлов не примет старый файл другой
        # цели.
        old_target_keys = old_path_keys_by_target.get(target_index, ())
        for key in old_target_keys:
            occupied[key] -= 1
            if occupied[key] <= 0:
                del occupied[key]

        candidate_seen = set()
        collision = None
        for path, key in zip(candidate_paths, candidate_keys):
            if key in candidate_seen or key in occupied:
                collision = path
                break
            candidate_seen.add(key)
        if collision is not None:
            logging.warning(
                "Фактическое перестроение M4B отменено для цели %s: "
                "совпадает выходной путь %s; сохранён старый план.",
                target_index,
                collision,
            )
            rebuilt.extend(target_records)
            # Отклонённые цели продолжают владеть исходными назначениями.
            occupied.update(old_target_keys)
            # Эта цель остаётся на исходных путях; вызывающий код всё равно
            # получает точные переопределения длительности для метаданных глав.
            continue
        occupied.update(candidate_keys)
        rebuilt.extend(generated)
        # Сообщаем об изменении только после проверки коллизий и принятия
        # новых путей. Иначе вызывающий код объявил бы перестроение, хотя
        # безопасный запасной вариант сохранил старый план.
        changed = True

    return {
        "records": tuple(rebuilt),
        "durations": durations,
        "diagnostics": tuple(diagnostics),
        "changed": bool(changed),
    }


def run_source_synthesis_m4b_target(
    processor,
    record,
    audio_by_file_id,
    config,
    *,
    skip_existing=False,
    status_callback=None,
    progress_callback=None,
    cancelled=None,
    chapter_duration_overrides=None,
    preencoded_audio=None,
    audio_stage_path=None,
    defer_preencoded_error=False,
):
    """Создаёт одну цель M4B из собранных TXT-фрагментов.

    Обычно каждый TXT временно сводится в один канонический Opus-файл, чтобы
    границы глав соответствовали исходным файлам, а не отдельным предложениям.
    Готовая фоновая AAC-основа и известные длительности позволяют пропустить
    повторную склейку. Временные файлы удаляются в ``finally``; кэш
    пользователя не меняется.
    """
    config = config if isinstance(config, dict) else {}
    target = normalize_output_target(record.get("target", {}))
    output_path = Path(record.get("path", "")).expanduser()
    fmt = "m4b"
    if cancelled and cancelled():
        raise InterruptedError("Синтез остановлен пользователем")
    if getattr(processor, "is_stopped", False):
        raise InterruptedError("Синтез остановлен пользователем")
    if preencoded_audio is not None and audio_stage_path is not None:
        raise ValueError(
            "Нельзя одновременно передать готовую AAC-основу и путь её подготовки"
        )
    output_path.parent.mkdir(parents=True, exist_ok=True)
    status_key = str(output_path.resolve())
    if (
        bool(skip_existing)
        and output_path.is_file()
        and getattr(processor, "processing_statuses_ram", {}).get(
            status_key, "success"
        )
        == "success"
    ):
        _call_source_target_status(status_callback, fmt, output_path, "success")
        return {"status": "skipped", "path": output_path, "format": fmt}

    _call_source_target_status(status_callback, fmt, output_path, "encoding")

    def notify_progress(current, total, text):
        """Передать укрупнённые стадии M4B без привязки ядра к Tk."""
        if progress_callback is None:
            return
        try:
            progress_callback(current, total, str(text or "M4B: сборка…"))
        except Exception:
            # Прогресс нужен только для диагностики и интерфейса. Закрытое окно
            # или старый обратный вызов не должны превращать успешно закодированную
            # книгу в ошибку.
            logging.debug(
                "Не удалось обновить прогресс M4B исходников", exc_info=True
            )

    chapter_files = []
    temporary_files = []
    try:
        file_ids = tuple(record.get("file_ids", ()))
        if not file_ids:
            raise ValueError("M4B-цель не содержит глав")
        duration_overrides = chapter_duration_overrides or {}

        def duration_override_for(file_id):
            try:
                value = duration_overrides.get(file_id)
            except AttributeError:
                return None
            if value is None:
                value = duration_overrides.get(str(file_id))
            try:
                value = float(value)
            except (TypeError, ValueError, OverflowError):
                return None
            return value if math.isfinite(value) and value > 0 else None

        # Готовая AAC-основа уже содержит все фрагменты. Если второй проход
        # передал длительность каждой главы, для построения меток достаточно
        # одного существующего пути на главу: повторная FFmpeg-склейка десятков
        # фрагментов предложений ничего не меняет и только задерживает публикацию.
        use_preencoded_chapter_snapshot = bool(
            preencoded_audio is not None
            and all(
                duration_override_for(file_id) is not None
                for file_id in file_ids
            )
        )
        prep_total = max(1, len(file_ids))
        notify_progress(0, prep_total, "M4B: подготовка аудиофайлов…")
        for file_id in file_ids:
            if cancelled and cancelled():
                raise InterruptedError("Синтез остановлен пользователем")
            raw_files = audio_by_file_id.get(file_id)
            if raw_files is None:
                raw_files = audio_by_file_id.get(str(file_id), ())
            files = tuple(Path(path).expanduser() for path in (raw_files or ()))
            if not files:
                raise FileNotFoundError(
                    f"Для главы {file_id!s} нет собранных аудиофрагментов"
                )
            if use_preencoded_chapter_snapshot or len(files) == 1:
                chapter_files.append(files[0])
                notify_progress(
                    len(chapter_files),
                    prep_total,
                    f"M4B: подготовка главы {len(chapter_files)}/{prep_total}…",
                )
                continue
            notify_progress(
                PROGRESS_STATUS_ONLY,
                prep_total,
                f"M4B: объединение фрагментов главы {len(chapter_files) + 1}/{prep_total}…",
            )
            semaphore = getattr(processor, "encode_semaphore", None)
            if semaphore is not None:
                with semaphore:
                    merged = processor._run_ffmpeg_concat(
                        files,
                        cancelled=cancelled,
                    )
            else:
                merged = processor._run_ffmpeg_concat(
                    files,
                    cancelled=cancelled,
                )
            if merged is None or not Path(merged).is_file():
                raise RuntimeError(f"Не удалось собрать временную главу {file_id!s}")
            merged = Path(merged)
            chapter_files.append(merged)
            temporary_files.append(merged)
            notify_progress(
                len(chapter_files),
                prep_total,
                f"M4B: подготовка главы {len(chapter_files)}/{prep_total}…",
            )

        source_paths = tuple(record.get("source_paths", ()))
        chapters = []
        for index, file_id in enumerate(file_ids):
            title = ""
            if index < len(source_paths):
                title = Path(source_paths[index]).stem
            chapter = {
                "title": title or f"Глава {index + 1}",
                "file_index": index + 1,
            }
            # Необязательный второй проход уже измерил каждый TXT в каноническом кэше.
            # Передача значения через существующий контракт метаданных главы избавляет
            # от второго ffprobe и сохраняет целостность TXT, даже если он содержит
            # много фрагментов.
            duration = duration_override_for(file_id)
            if duration is not None:
                chapter["duration"] = duration
            chapters.append(chapter)
        chapter_context = source_m4b_metadata_context(
            config,
            record,
            output_path,
        )
        metadata_overrides = merge_metadata_overrides(
            record.get("metadata_overrides", {})
        )
        chapter_context["author"] = str(
            metadata_overrides.get(
                "artist",
                config.get("tag_artist", chapter_context.get("author", "")),
            )
            or ""
        ).strip()
        try:
            chapters = render_m4b_chapter_titles(
                chapters,
                target.get("chapter_title_template", ""),
                book=chapter_context["book"],
                group=chapter_context["group"],
                part=chapter_context["part"],
                parts=chapter_context["parts"],
                chapter_start=chapter_context["first_index"],
                chapter_count=chapter_context["chapter_count"],
                profile=target.get("profile", ""),
                author=chapter_context.get("author", ""),
                global_start=1,
                group_index=chapter_context.get(
                    "group_index", chapter_context.get("part", 1)
                ),
            )
        except TemplateError as exc:
            raise ValueError(f"Шаблон меток глав M4B: {exc}") from exc
        effects = _source_synthesis_target_effects(target, config)
        if effects["enabled"] and (
            abs(effects["speed"] - 1.0) > 1e-9
            or abs(effects["pitch"] - 1.0) > 1e-9
            or effects["echo"]
        ):
            raise ValueError(
                "Эффекты для M4B отключены: они меняют длительность глав"
            )
        tags = _source_synthesis_tag_values(config, output_path.name)
        # Разделённая книга должна передавать медиаменеджерам одно стабильное
        # значение альбома. Пользовательский шаблон важнее общего тега, но
        # стандартный ``{book}`` не заменяет альбом из настроек именем папки.
        # Индивидуальное переопределение группы применяется последним ниже.
        album_template = config.get("source_m4b_album_template")
        if album_template is None:
            album_template = config.get("synthesis_m4b_album_template")
        custom_album_template = bool(
            album_template is not None
            and str(album_template).strip()
            and str(album_template).strip() != DEFAULT_SOURCE_M4B_ALBUM_TEMPLATE
        )
        if (
            (not tags.get("album") or custom_album_template)
            and album_template is not None
            and _config_bool(config.get("apply_output_tags", True), default=True)
        ):
            try:
                rendered_album = render_m4b_album_template(
                    album_template,
                    chapter_context,
                    fallback=chapter_context.get("book", ""),
                )
            except TemplateError as exc:
                raise ValueError(f"Шаблон альбома M4B: {exc}") from exc
            if rendered_album:
                tags["album"] = rendered_album
        if _config_bool(config.get("apply_output_tags", True), default=True):
            tags = apply_source_metadata_overrides(tags, metadata_overrides)
        bitrate = str(target.get("bitrate", "auto") or "auto").lower()
        if bitrate == "auto":
            # У синтеза из папки есть собственное значение M4B по умолчанию.
            # Если сначала брать значение вкладки экспорта, импортированная
            # цель ``auto`` незаметно унаследует чужой профиль (например, 192k),
            # хотя компактный интерфейс хранит выбор в
            # ``synthesis_m4b_bitrate``. Ключ экспорта оставляем запасным для
            # старых прямых вызовов без настройки исходников.
            source_default = config.get("synthesis_m4b_bitrate")
            if source_default in (None, ""):
                source_default = config.get("export_m4b_bitrate", "64k")
            bitrate = str(source_default or "64k").lower()
        sample_rate = str(target.get("sample_rate", "auto") or "auto").lower()
        if sample_rate == "auto":
            sample_rate = "48000"
        channels = str(target.get("channels", "auto") or "auto").lower()
        channels = 2 if channels == "stereo" else 1
        kwargs = {
            "chapters": chapters,
            "bitrate": bitrate,
            "sample_rate": int(sample_rate),
            "channels": channels,
            "pause_ms": 0,
            "tags": tags,
            "disk_number": record.get("group_index"),
            "disk_total": record.get("parts"),
            "track_number": record.get("group_index"),
            "track_total": record.get("parts"),
            "include_track_metadata": _config_bool(
                target.get("include_track_metadata"), default=True
            ),
            "cover": (
                str(
                    metadata_overrides.get(
                        "cover", config.get("tag_cover", "")
                    )
                    or ""
                ).strip()
                if _config_bool(config.get("apply_output_tags", True), default=True)
                else None
            ),
            "cancelled": lambda: bool(
                getattr(processor, "is_stopped", False)
                or (cancelled and cancelled())
            ),
        }
        if progress_callback is not None:
            kwargs["progress_callback"] = progress_callback
        semaphore = getattr(processor, "encode_semaphore", None)

        if audio_stage_path is not None:
            stage_path = Path(audio_stage_path).expanduser()
            stage_path.parent.mkdir(parents=True, exist_ok=True)
            stage_path.unlink(missing_ok=True)

            def encode_stage():
                _export_merged_audio_ffmpeg(
                    chapter_files,
                    stage_path,
                    output_format="m4a",
                    bitrate=bitrate,
                    bitrate_mode=bitrate or "auto",
                    sample_rate=str(sample_rate),
                    channels=("stereo" if channels == 2 else "mono"),
                    pause_ms=0,
                    speed=1.0,
                    pitch=1.0,
                    echo=False,
                    tags=None,
                    cover=None,
                    cancelled=kwargs["cancelled"],
                    faststart=False,
                )

            if semaphore is not None:
                with semaphore:
                    encode_stage()
            else:
                encode_stage()
            if not stage_path.is_file():
                raise RuntimeError("FFmpeg не создал временную AAC-основу M4B")
            return {
                "status": "success",
                "path": output_path,
                "format": fmt,
                "stage_path": stage_path,
            }

        if preencoded_audio is not None:
            kwargs["preencoded_audio"] = preencoded_audio
        if semaphore is not None:
            with semaphore:
                _export_m4b_ffmpeg(
                    chapter_files,
                    output_path,
                    **kwargs,
                )
        else:
            _export_m4b_ffmpeg(
                chapter_files,
                output_path,
                **kwargs,
            )
        if hasattr(processor, "_mark_output_status"):
            processor._mark_output_status(output_path, "success")
        _call_source_target_status(status_callback, fmt, output_path, "success")
        log_saved_audio(output_path)
        return {"status": "success", "path": output_path, "format": fmt}
    except InterruptedError:
        raise
    except Exception as exc:
        if audio_stage_path is not None:
            Path(audio_stage_path).unlink(missing_ok=True)
            logging.warning(
                "Не удалось подготовить AAC-основу M4B %s: %s. "
                "Итоговая стадия повторит обычную сборку.",
                output_path.name,
                exc,
            )
            return {
                "status": "error",
                "path": output_path,
                "format": fmt,
                "error": str(exc),
            }
        if preencoded_audio is not None and defer_preencoded_error:
            logging.warning(
                "Не удалось применить AAC-основу M4B %s: %s",
                output_path.name,
                exc,
            )
            return {
                "status": "error",
                "path": output_path,
                "format": fmt,
                "error": str(exc),
            }
        if hasattr(processor, "_mark_output_status"):
            processor._mark_output_status(output_path, "error")
        _call_source_target_status(status_callback, fmt, output_path, "error")
        logging.error("Ошибка сборки M4B %s: %s", output_path.name, exc)
        return {"status": "error", "path": output_path, "format": fmt, "error": str(exc)}
    finally:
        for temporary in temporary_files:
            Path(temporary).unlink(missing_ok=True)


def _template_basename(rendered, extension):
    """Удаляет конечное расширение (включая случайное повторение).

    В шаблонах и заголовках метаданных для удобства можно указывать
    расширение, хотя экспортёр добавляет выбранный формат сам. Цикл сохраняет
    это правило и для значений вроде ``name.mp3.mp3``; остальные точки в
    настоящем названии не изменяются.
    """
    value = str(rendered or "").strip()
    suffix = "." + str(extension or "").lstrip(".").lower()
    if suffix != ".":
        while value.lower().endswith(suffix):
            value = value[: -len(suffix)].rstrip()
    return value


def _effective_export_m4b_template(target_template, global_template):
    """Разрешает шаблон M4B, не возвращая устаревший диапазон.

    До появления переносимых снимков редактора строка M4B могла сохранить
    историческое ``{book} Главы {range}``, хотя компактное поле уже изменили
    или очистили. Такое точное значение считается устаревшим, если текущее
    общее поле отличается; другие непустые шаблоны цели сохраняют приоритет.
    Пустой результат намеренный: используется имя группы, а для нескольких
    частей добавляется ``Часть N``.
    """
    target = str(target_template or "").strip()
    global_value = str(global_template or "").strip()
    if (
        target == DEFAULT_SOURCE_M4B_TEMPLATE
        and global_value != DEFAULT_SOURCE_M4B_TEMPLATE
    ):
        return global_value
    return target or global_value


def _m4b_template_needs_part_suffix(
    template,
    context,
    allowed_fields,
    *,
    varying_fields=(),
):
    """Возвращает ``True`` для статического многочастного M4B-шаблона.

    Шаблон вроде ``{book}`` допустим для книги из одного файла, но после
    автоматического разделения дал бы одинаковый путь каждому тому. Запасной
    суффикс добавляется только при отсутствии поля, определяющего текущую
    часть. ``varying_fields`` позволяет планировщику учесть поля, уникальность
    которых он проверил по всему текущему набору. Проверка передаётся общему
    валидатору, чтобы сохранить прежние сообщения об ошибках.
    """
    template = str(template or "").strip()
    if not template:
        return False
    fields = validate_filename_template(template, allowed_fields)
    try:
        part_count = int(
            context.get("_local_parts", context.get("parts", 1)) or 1
        )
    except (TypeError, ValueError, OverflowError):
        part_count = 1
    return (
        part_count > 1
        and not set(fields).intersection(
            M4B_UNIQUE_PART_TEMPLATE_FIELDS | frozenset(varying_fields)
        )
    )


def _m4b_part_suffix(context):
    """Формирует безопасный номер части для резервного имени."""
    try:
        part_number = int(context.get("part", context.get("index", 1)) or 1)
    except (TypeError, ValueError, OverflowError):
        part_number = 1
    return max(1, part_number)


def _append_m4b_part_suffix(value, context, *, fallback):
    """Добавляет ``Часть N``, сохраняя суффикс при ограничении длины."""
    max_length = 180
    suffix = sanitize_filename_component(
        f"Часть {_m4b_part_suffix(context)}",
        fallback="Часть",
        max_length=max_length,
    )
    separator = " "
    base_limit = max(1, max_length - len(separator) - len(suffix))
    base = sanitize_filename_component(
        value,
        fallback=fallback,
        max_length=base_limit,
    )
    return sanitize_filename_component(
        f"{base}{separator}{suffix}",
        fallback=fallback,
        max_length=max_length,
    )


def _m4b_context_has_multiple_parts(context):
    """Проверить, описывает ли контекст рендера несколько частей M4B."""
    try:
        parts = int((context or {}).get("parts", 1) or 1)
    except (AttributeError, TypeError, ValueError, OverflowError):
        parts = 1
    return parts > 1


def plan_export_target_paths(
    items,
    group_children,
    export_groups,
    export_files,
    targets,
    base_dir,
    *,
    m4b_template=DEFAULT_EXPORT_M4B_TEMPLATE,
    m4b_max_duration_seconds=0,
    m4b_max_chapters=0,
    auto_split_long_m4b=True,
):
    """Планирует все выходные имена набора до запуска FFmpeg.

    Возвращает кортеж словарей ``{target, item_id, path, kind, part}`` и
    отклоняет совпадения с учётом регистра. Планировщик не читает аудио и не
    создаёт каталогов, поэтому его можно безопасно вызывать из UI до
    блокировки окна. Неизвестные длительности M4B считаются нулевыми; сам
    фоновый обработчик при необходимости дополнительно уточнит их через ffprobe.
    При ``auto_split_long_m4b=True`` известная длительность книги больше 24 часов
    включает профилактический предел 23:50 даже для цели без явного лимита; главы
    остаются неделимыми. Для уже заданных виртуальных групп автоматическая
    защита сохраняет границы и делит только слишком длинную группу. Явный
    флажок перестройки по фактической длительности может, напротив, перепаковать
    всю цель; короткие книги и положительные лимиты остаются без изменений
    (кроме защитного ограничения сверху 23:50).
    """
    # Обычный словарь может намеренно не содержать лимиты M4B для цели и
    # унаследовать текущие компактные значения планировщика. Явный ноль по-
    # прежнему означает отсутствие лимита, а ``OutputTarget`` всегда хранит
    # полный собственный снимок.
    prepared_targets = []
    for raw_target in targets or ():
        if isinstance(raw_target, dict):
            prepared = copy.deepcopy(raw_target)
            if str(prepared.get("format", "")).strip().lower() == "m4b":
                # Переносимый JSON старых версий может содержать явный ``null``
                # для необязательного лимита. Считаем его пропущенным полем и
                # берём компактное значение по умолчанию; только числовой ноль
                # означает «без ограничений».
                if prepared.get("max_duration_seconds") is None:
                    prepared["max_duration_seconds"] = m4b_max_duration_seconds
                if prepared.get("max_chapters") is None:
                    prepared["max_chapters"] = m4b_max_chapters
            prepared_targets.append(prepared)
        else:
            prepared_targets.append(raw_target)
    normalized_targets = plan_output_targets(
        prepared_targets,
        base_dir,
        legacy_single_dir=base_dir,
    )
    records = []
    seen = {}

    def add_record(target_index, target, item_id, path, kind, part=None):
        path = Path(path)
        # Приводим написание к одному виду, чтобы проверка была одинаковой
        # на файловых системах с разным отношением к регистру.
        key = os.path.normcase(str(path)).casefold()
        if key in seen:
            previous = seen[key]
            raise ValueError(
                "совпадающие выходные имена: "
                f"{previous['path']} и {path}"
            )
        record = {
            "target": target,
            "target_index": target_index,
            "item_id": item_id,
            "path": path,
            "kind": kind,
            "part": part,
        }
        seen[key] = record
        records.append(record)

    def add_m4b_record(target_index, target, item_id, path, part):
        """Добавляет M4B и безопасно различает совпавшие имена частей."""
        path = Path(path)
        if os.path.normcase(str(path)).casefold() in seen:
            stem = path.stem
            suffix = 2
            while True:
                candidate = path.with_name(
                    f"{stem} Часть {suffix}{path.suffix}"
                )
                key = os.path.normcase(str(candidate)).casefold()
                if key not in seen:
                    path = candidate
                    break
                suffix += 1
        add_record(target_index, target, item_id, path, "m4b", part)

    def render_name(target, context, fallback, extension):
        template = str(target.get("filename_template") or "").strip()
        if extension == "m4b":
            template = _effective_export_m4b_template(template, m4b_template)
        if not template:
            rendered = fallback
        else:
            renderer = (
                render_m4b_part_template
                if extension == "m4b"
                else render_output_file_template
            )
            rendered = renderer(template, context, TEMPLATE_FIELDS_OUTPUT)
        rendered = _template_basename(rendered, extension)
        if extension == "m4b":
            if _m4b_template_needs_part_suffix(
                template, context, TEMPLATE_FIELDS_OUTPUT
            ) or (
                not template
                and _m4b_context_has_multiple_parts(context)
            ):
                rendered = _append_m4b_part_suffix(
                    rendered,
                    context,
                    fallback=fallback,
                )
        return sanitize_filename_component(rendered, fallback=fallback)

    def prepare_m4b_group_parts(target, group, children):
        """Готовит главы и границы M4B ровно один раз для цели."""
        chapters = []
        for index, file_id in enumerate(children, 1):
            file_record = normalize_export_file_record(export_files[file_id])
            raw_duration = file_record.get("duration", 0) or 0
            try:
                duration = float(raw_duration)
            except (TypeError, ValueError, OverflowError):
                duration = 0.0
            if not math.isfinite(duration) or duration < 0:
                duration = 0.0
            chapters.append(
                {
                    "index": index,
                    "file_index": index,
                    "title": effective_export_file_title(file_record),
                    "source_name": file_record["source_name"],
                    "source_title": file_record["source_title"],
                    "path": file_record["path"],
                    "duration": duration,
                }
            )
        target_duration_limit = target.get("max_duration_seconds")
        if target_duration_limit is None:
            target_duration_limit = m4b_max_duration_seconds
        target_chapter_limit = target.get("max_chapters")
        if target_chapter_limit is None:
            target_chapter_limit = m4b_max_chapters
        pause_ms = _normalized_pause_milliseconds(group.get("pause", 0))
        estimated_total = sum(
            float(chapter.get("duration", 0) or 0) for chapter in chapters
        ) + max(0, len(chapters) - 1) * pause_ms / 1000.0
        if auto_split_long_m4b:
            target_duration_limit = resolve_m4b_auto_duration_limit(
                estimated_total,
                target_duration_limit,
            )
        else:
            target_duration_limit = effective_m4b_duration_limit(
                target_duration_limit
            )
        parts = plan_m4b_parts(
            chapters,
            max_duration_seconds=target_duration_limit,
            max_chapters=target_chapter_limit,
            pause_seconds=pause_ms / 1000.0,
        )
        if not parts:
            parts = (M4BPart(1, 1, 1, len(children), 0, chapters),)
        return chapters, tuple(parts)

    for target_index, target in enumerate(normalized_targets):
        fmt = target["format"]
        target_dir = Path(target["output_dir"]).expanduser()
        selected_group_ids = [
            item_id for item_id in (items or ()) if item_id in export_groups
        ]
        group_positions = {
            item_id: position
            for position, item_id in enumerate(selected_group_ids, 1)
        }
        group_total = max(1, len(selected_group_ids))
        m4b_parts_by_group = {}
        m4b_volume_by_part = {}
        m4b_group_positions = {}
        if fmt == "m4b":
            group_ids = selected_group_ids
            m4b_group_positions = {
                item_id: position for position, item_id in enumerate(group_ids, 1)
            }
            sequence_entries = []
            for item_id in group_ids:
                group = dict(export_groups[item_id])
                children = tuple(group_children.get(item_id, ()))
                if not children:
                    continue
                chapters, parts = prepare_m4b_group_parts(
                    target, group, children
                )
                m4b_parts_by_group[item_id] = (chapters, parts)
                sequence_key = m4b_group_sequence_key(group, item_id)
                for part in parts:
                    preferred = (
                        group.get("source_volume_number")
                        if part.number == 1
                        else None
                    )
                    sequence_entries.append(
                        (
                            sequence_key,
                            item_id,
                            part.number,
                            preferred,
                            group.get("source_volume_total"),
                        )
                    )
            m4b_volume_by_part = assign_m4b_volume_numbers(sequence_entries)
        for item_id in items or ():
            if item_id in export_groups:
                group = dict(export_groups[item_id])
                children = tuple(group_children.get(item_id, ()))
                if not children:
                    continue
                merge_group = output_target_merges_group(target, group)
                group_name = sanitize_filename_component(
                    group.get("name"), fallback="Группа"
                )
                if fmt == "m4b":
                    prepared_parts = m4b_parts_by_group.get(item_id)
                    if prepared_parts is None:
                        prepared_parts = prepare_m4b_group_parts(
                            target, group, children
                        )
                    chapters, parts = prepared_parts
                    for part in parts:
                        first = part.chapters[0] if part.chapters else {}
                        last = part.chapters[-1] if part.chapters else {}
                        physical_source = str(
                            group.get("source_path")
                            or first.get("path")
                            or ""
                        )
                        volume_number, volume_total = m4b_volume_by_part.get(
                            (item_id, part.number),
                            (part.number, part.total),
                        )
                        context = {
                            "book": group_name,
                            "name": group_name,
                            "group": group_name,
                            "title": group_name,
                            "source_name": group_name,
                            "source_title": str(
                                group.get("source_title") or group_name
                            ),
                            "filename": Path(physical_source).stem if physical_source else group_name,
                            "index": volume_number,
                            "chapter": part.chapter_start,
                            "chapter_count": len(chapters),
                            "first_index": part.chapter_start,
                            "last_index": part.chapter_end,
                            "num": volume_number,
                            "group_index": m4b_group_positions.get(item_id, 1),
                            "file_index": part.chapter_start,
                            "first": part.chapter_start,
                            "last": part.chapter_end,
                            "range": format_chapter_range(
                                part.chapter_start,
                                part.chapter_end,
                                total_count=len(chapters),
                            ),
                            "first_name": first.get("title", ""),
                            "last_name": last.get("title", ""),
                            "part": volume_number,
                            "volume": volume_number,
                            "parts": volume_total,
                            "_local_parts": part.total,
                            "format": fmt,
                            "profile": target.get("profile", ""),
                            "ext": fmt,
                            "author": group.get("artist", ""),
                        }
                        basename = render_name(
                            target,
                            context,
                            group_name,
                            fmt,
                        )
                        add_m4b_record(
                            target_index,
                            target,
                            item_id,
                            target_dir / f"{basename}.{fmt}",
                            part,
                        )
                    continue

                if merge_group:
                    group_number = group_positions.get(item_id, 1)
                    source_volume = group.get("source_volume_number")
                    try:
                        volume_number = int(source_volume or group_number)
                    except (TypeError, ValueError, OverflowError):
                        volume_number = group_number
                    volume_number = max(1, volume_number)
                    try:
                        volume_total = int(
                            group.get("source_volume_total") or group_total
                        )
                    except (TypeError, ValueError, OverflowError):
                        volume_total = group_total
                    volume_total = max(volume_number, volume_total)
                    context = {
                        "book": group_name,
                        "name": group_name,
                        "group": group_name,
                        "title": group_name,
                        "source_name": group_name,
                        "source_title": str(
                            group.get("source_title") or group_name
                        ),
                        "index": group_number,
                        "chapter": 1,
                        "chapter_count": len(children),
                        "part": volume_number,
                        "volume": volume_number,
                        "parts": volume_total,
                        "first_index": 1,
                        "last_index": len(children),
                        "num": group_number,
                        "group_index": group_number,
                        "file_index": 1,
                        "first": 1,
                        "last": len(children),
                        "range": format_chapter_range(
                            1, len(children), total_count=len(children)
                        ),
                        "first_name": str(
                            export_files[children[0]].get("title", "")
                        ),
                        "last_name": str(
                            export_files[children[-1]].get("title", "")
                        ),
                        "format": fmt,
                        "profile": target.get("profile", ""),
                        "ext": fmt,
                        "author": group.get("artist", ""),
                    }
                    basename = render_name(target, context, group_name, fmt)
                    add_record(
                        target_index,
                        target,
                        item_id,
                        target_dir / f"{basename}.{fmt}",
                        "group",
                    )
                else:
                    file_dir = (
                        target_dir / group_name
                        if target.get("scope") == "group_subfolder"
                        or effective_group_subfolder(
                            merge_group, group.get("subfolder")
                        )
                        else target_dir
                    )
                    for index, file_id in enumerate(children, 1):
                        setting = normalize_export_file_record(
                            export_files[file_id]
                        )
                        title = effective_export_file_title(setting)
                        group_number = group_positions.get(item_id, 1)
                        source_volume = group.get("source_volume_number")
                        try:
                            volume_number = int(source_volume or group_number)
                        except (TypeError, ValueError, OverflowError):
                            volume_number = group_number
                        volume_number = max(1, volume_number)
                        try:
                            volume_total = int(
                                group.get("source_volume_total") or group_total
                            )
                        except (TypeError, ValueError, OverflowError):
                            volume_total = group_total
                        volume_total = max(volume_number, volume_total)
                        context = {
                            "book": group_name,
                            "name": title,
                            "group": group_name,
                            "title": title,
                            "source_name": setting["source_name"],
                            "source_title": setting["source_title"],
                            "filename": Path(setting["path"]).stem,
                            "index": index,
                            "chapter": index,
                            "chapter_count": len(children),
                            "part": volume_number,
                            "volume": volume_number,
                            "parts": volume_total,
                            "first_index": index,
                            "last_index": index,
                            "num": index,
                            "group_index": group_number,
                            "file_index": index,
                            "first": index,
                            "last": index,
                            "range": str(index),
                            "first_name": title,
                            "last_name": title,
                            "format": fmt,
                            "profile": target.get("profile", ""),
                            "ext": fmt,
                            "author": setting.get("artist", ""),
                        }
                        basename = render_name(target, context, title, fmt)
                        add_record(
                            target_index,
                            target,
                            file_id,
                            file_dir / f"{basename}.{fmt}",
                            "file",
                        )
            elif item_id in export_files:
                setting = normalize_export_file_record(export_files[item_id])
                title = effective_export_file_title(setting)
                context = {
                    "book": title,
                    "name": title,
                    "group": title,
                    "title": title,
                    "source_name": setting["source_name"],
                    "source_title": setting["source_title"],
                    "filename": Path(setting["path"]).stem,
                    "index": 1,
                    "chapter": 1,
                    "chapter_count": 1,
                    "part": 1,
                    "volume": 1,
                    "parts": 1,
                    "first_index": 1,
                    "last_index": 1,
                    "num": 1,
                    "group_index": 1,
                    "file_index": 1,
                    "first": 1,
                    "last": 1,
                    "range": "1",
                    "first_name": title,
                    "last_name": title,
                    "format": fmt,
                    "profile": target.get("profile", ""),
                    "ext": fmt,
                    "author": setting.get("artist", ""),
                }
                basename = render_name(target, context, title, fmt)
                add_record(
                    target_index,
                    target,
                    item_id,
                    target_dir / f"{basename}.{fmt}",
                    "file",
                )
    return tuple(records)


