def select_config_values(config, selected_groups, *, include_api_token=True):
    """Формирует переносимый профиль только из выбранных известных ключей."""
    rules = _config_group_rules_data()
    selected_keys = set()
    for group_name in selected_groups:
        selected_keys.update(rules.get(group_name, ()))
    selected = {
        key: copy.deepcopy(value)
        for key, value in config.items()
        if key in selected_keys
    }
    if not include_api_token:
        selected.pop("api_token", None)
    return selected


def merge_config_values(
    current_config,
    imported_config,
    selected_groups,
    *,
    include_api_token=True,
):
    """Возвращает копию конфига с выбранными полями импортируемого профиля."""
    selected_groups = tuple(selected_groups)
    merged = dict(current_config)
    selected = select_config_values(
        imported_config,
        selected_groups,
        include_api_token=include_api_token,
    )
    # В раннем формате output_format одновременно управлял книгой и универсальным
    # экспортом. Та же миграция, что выполняется при загрузке settings.json,
    # нужна и при выборочном импорте старого профиля в уже новый конфиг.
    if (
        "tags" in selected_groups
        and "output_format" in selected
        and "export_format" not in imported_config
    ):
        selected["export_format"] = copy.deepcopy(selected["output_format"])
    merged.update(selected)
    return merged


# Профили нормализатора хранятся отдельно от самой конфигурации. Обёртка с
# идентификатором позволяет переименовывать/редактировать профиль, не меняя
# ссылки на него в настройках. Встроенные профили намеренно не попадают в
# settings.json и всегда создаются заново из текущих значений библиотеки по умолчанию.
NORMALIZER_PROFILE_BUILTIN_IDS = {
    "tts": "builtin:tts",
    "safe": "builtin:safe",
}
NORMALIZER_PROFILE_CUSTOM_PREFIX = "custom:"
_NORMALIZER_PROFILE_CUSTOM_ID_RE = re.compile(r"custom:[0-9a-f]{32}\Z")
NORMALIZER_PROFILE_LIBRARY_SCHEMA = "silero-tts-studio-normalizer-profile-library"
NORMALIZER_PROFILE_LIBRARY_VERSION = 1


def _profile_content_digest(profile):
    """Детерминированный хэш для миграции старых исходных записей без идентификатора."""
    payload = json.dumps(
        profile, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()[:32]


def _normalizer_custom_profile_id(profile):
    return NORMALIZER_PROFILE_CUSTOM_PREFIX + _profile_content_digest(profile)


def _validate_normalizer_profile_id(profile_id, *, allow_builtin=True):
    if not isinstance(profile_id, str) or not profile_id.strip():
        raise ValueError("id профиля нормализации должен быть строкой")
    profile_id = profile_id.strip()
    if allow_builtin and profile_id in NORMALIZER_PROFILE_BUILTIN_IDS.values():
        return profile_id
    if _NORMALIZER_PROFILE_CUSTOM_ID_RE.fullmatch(profile_id):
        return profile_id
    raise ValueError("некорректный id профиля нормализации")


def make_normalizer_profile_entry(profile, *, profile_id=None):
    """Оборачивает переносимый профиль в стабильную запись ``id/profile``."""
    normalized = normalize_normalizer_profile(profile)
    if profile_id is None:
        profile_id = NORMALIZER_PROFILE_CUSTOM_PREFIX + uuid.uuid4().hex
    profile_id = _validate_normalizer_profile_id(profile_id)
    if profile_id in NORMALIZER_PROFILE_BUILTIN_IDS.values():
        expected = _builtin_normalizer_profile(profile_id)
        if normalized != expected:
            raise ValueError(
                f"содержимое встроенного профиля {profile_id} не совпадает"
            )
    return {"id": profile_id, "profile": normalized}


def normalize_normalizer_profile_entry(entry, *, legacy_index=0):
    """Нормализует запись библиотеки, поддерживая старые исходные профили."""
    if not isinstance(entry, dict):
        raise ValueError("запись профиля нормализации должна быть объектом")
    if "profile" in entry:
        unknown = sorted(set(entry) - {"id", "profile"})
        if unknown:
            raise ValueError(
                "неизвестные поля записи профиля: " + ", ".join(unknown)
            )
        if "id" not in entry:
            raise ValueError("в записи профиля отсутствует id")
        profile = normalize_normalizer_profile(entry["profile"])
        profile_id = _validate_normalizer_profile_id(entry["id"])
        if profile_id in NORMALIZER_PROFILE_BUILTIN_IDS.values():
            # Встроенные записи создаёт только программа; переносимые и
            # сохранённые библиотеки содержат пользовательские записи. Это
            # предотвращает рекурсивную проверку и подмену встроенного ID.
            raise ValueError("встроенный id нельзя хранить в библиотеке")
        return {"id": profile_id, "profile": profile}

    # До введения библиотеки ``settings.json`` мог содержать переносимые профили
    # напрямую. Хэш повторяется между запусками, поэтому ссылки стабильны.
    profile = normalize_normalizer_profile(entry)
    profile_id = _normalizer_custom_profile_id(profile)
    return {"id": profile_id, "profile": profile}


def _builtin_normalizer_profile(profile_id):
    """Возвращает каноническое содержимое одного встроенного профиля."""
    mode = next(
        (
            mode
            for mode, builtin_id in NORMALIZER_PROFILE_BUILTIN_IDS.items()
            if builtin_id == profile_id
        ),
        None,
    )
    if mode is None:
        raise ValueError("неизвестный встроенный профиль нормализации")
    config = {
        "normalizer_enabled": True,
        "normalizer_mode": mode,
        "normalizer_options": normalizer_mode_defaults(mode),
        "glossary_enabled": True,
        "auto_abbreviations": True,
        "auto_short_words": True,
    }
    return normalizer_profile_from_config(
        config,
        name="TTS (для озвучки)" if mode == "tts" else "Safe (бережный)",
    )


def builtin_normalizer_profile_entries():
    """Создаёт независимые неизменяемые встроенные записи TTS и Safe."""
    return [
        {"id": profile_id, "profile": _builtin_normalizer_profile(profile_id)}
        for profile_id in NORMALIZER_PROFILE_BUILTIN_IDS.values()
    ]


def normalizer_profile_library_from_profiles(profiles):
    """Строит переносимый пакет, исключая встроенные записи."""
    entries = []
    seen = set()
    builtin_identities = {
        (
            entry["profile"]["name"].casefold(),
            _normalizer_profile_identity_key(entry["profile"]),
        )
        for entry in builtin_normalizer_profile_entries()
    }
    for index, raw in enumerate(profiles or []):
        try:
            entry = normalize_normalizer_profile_entry(raw, legacy_index=index)
        except (TypeError, ValueError):
            continue
        if entry["id"] in NORMALIZER_PROFILE_BUILTIN_IDS.values():
            continue
        identity = (
            entry["profile"]["name"].casefold(),
            _normalizer_profile_identity_key(entry["profile"]),
        )
        if identity in builtin_identities:
            continue
        if entry["id"] in seen:
            continue
        seen.add(entry["id"])
        entries.append(entry)
    return {
        "schema": NORMALIZER_PROFILE_LIBRARY_SCHEMA,
        "version": NORMALIZER_PROFILE_LIBRARY_VERSION,
        "profiles": entries,
    }


def normalize_normalizer_profile_library(data):
    """Проверяет версионированный пакет и возвращает пользовательские записи с идентификаторами."""
    if not isinstance(data, dict):
        raise ValueError("библиотека профилей нормализации должна быть объектом")
    unknown = sorted(set(data) - {"schema", "version", "profiles"})
    if unknown:
        raise ValueError(
            "неизвестные поля библиотеки профилей нормализации: "
            + ", ".join(unknown)
        )
    if data.get("schema") != NORMALIZER_PROFILE_LIBRARY_SCHEMA:
        raise ValueError("неподдерживаемый формат библиотеки профилей нормализации")
    version = data.get("version")
    if isinstance(version, bool) or not isinstance(version, int):
        raise ValueError(
            "версия библиотеки профилей нормализации должна быть целым числом"
        )
    if version != NORMALIZER_PROFILE_LIBRARY_VERSION:
        raise ValueError(
            f"неподдерживаемая версия библиотеки профилей нормализации: {version}"
        )
    profiles = data.get("profiles")
    if not isinstance(profiles, list):
        raise ValueError("profiles библиотеки нормализации должен быть массивом")
    result, seen = [], set()
    for index, raw in enumerate(profiles):
        entry = normalize_normalizer_profile_entry(raw, legacy_index=index)
        if entry["id"] in NORMALIZER_PROFILE_BUILTIN_IDS.values():
            continue
        if entry["id"] in seen:
            raise ValueError(
                f"дублирующийся id профиля нормализации: {entry['id']}"
            )
        seen.add(entry["id"])
        result.append(entry)
    return result


def normalizer_profile_entries_from_config(config):
    """Возвращает встроенные и сохранённые пользовательские профили для интерфейса."""
    result = builtin_normalizer_profile_entries()
    builtin_ids = {item["id"] for item in result}
    for index, raw in enumerate((config or {}).get("normalizer_profiles", [])):
        try:
            entry = normalize_normalizer_profile_entry(raw, legacy_index=index)
        except (TypeError, ValueError):
            continue
        if entry["id"] in builtin_ids or any(
            item["id"] == entry["id"] for item in result
        ):
            continue
        # Настройки предварительных версий могли содержать собственное имя,
        # совпадающее со встроенным или с другим пользовательским профилем.
        # Оставляем стабильный идентификатор, но делаем подпись уникальной,
        # иначе выбор ttk.Combobox по имени всегда попадал бы в первую
        # встроенную запись.
        if normalizer_profile_name_conflict(
            entry["profile"]["name"], result
        ):
            entry["profile"]["name"] = unique_normalizer_profile_name(
                entry["profile"]["name"], result
            )
        result.append(entry)
    return result


def normalizer_profile_name_conflict(name, entries, *, exclude_id=None):
    identity = str(name or "").strip().casefold()
    if not identity:
        return True
    # Служебное значение выпадающего списка обозначает локальный снимок, не входящий в
    # библиотеку. Запись с тем же именем была бы визуально неотличима и выбор
    # по тексту всегда попадал бы в первый из двух одинаковых пунктов.
    if identity == "пользовательский".casefold():
        return True
    if any(
        item["profile"]["name"].casefold() == identity
        for item in builtin_normalizer_profile_entries()
    ):
        return True
    for raw in entries or []:
        try:
            entry = normalize_normalizer_profile_entry(raw)
        except (TypeError, ValueError):
            continue
        if exclude_id is not None and entry["id"] == exclude_id:
            continue
        if entry["profile"]["name"].casefold() == identity:
            return True
    return False


def unique_normalizer_profile_name(name, entries):
    base = str(name or "Пользовательский").strip() or "Пользовательский"
    if base.casefold() == "пользовательский".casefold():
        base = "Пользовательский профиль"
    if not normalizer_profile_name_conflict(base, entries):
        return base
    suffix = 2
    while normalizer_profile_name_conflict(f"{base} ({suffix})", entries):
        suffix += 1
    return f"{base} ({suffix})"


def normalizer_profile_identity(profile):
    """Снимок параметров профиля без имени и схемы для сопоставления в интерфейсе."""
    normalized = normalize_normalizer_profile(profile)
    return {
        "normalizer": copy.deepcopy(normalized["normalizer"]),
        "preprocessing": copy.deepcopy(normalized["preprocessing"]),
    }


def _normalizer_profile_identity_key(profile):
    return json.dumps(
        normalizer_profile_identity(profile),
        ensure_ascii=False,
        sort_keys=True,
    )


def matching_normalizer_profile_entry(config, entries=None):
    """Возвращает единственное совпадение текущих параметров по id/name."""
    source = config if isinstance(config, dict) else {}
    candidate = normalizer_profile_from_config(source, name="Текущие параметры")
    identity = normalizer_profile_identity(candidate)
    candidates = (
        list(entries)
        if entries is not None
        else normalizer_profile_entries_from_config(source)
    )
    matches = []
    for raw in candidates:
        try:
            entry = normalize_normalizer_profile_entry(raw)
        except (TypeError, ValueError):
            continue
        if normalizer_profile_identity(entry["profile"]) == identity:
            matches.append(entry)
    return matches[0] if len(matches) == 1 else None


def resolve_cache_audio_path(cache_dir, file_name):
    """Возвращает путь только к обычному имени файла внутри ``cache/audio``.

    Индекс кэша является локальным JSON, но его можно импортировать из архива
    или отредактировать вручную. Запрещаем абсолютные пути и ``..``, чтобы
    удаление/прослушивание записи не затронуло произвольный файл пользователя.
    """
    if not isinstance(file_name, str) or not file_name.strip():
        return None
    raw_name = file_name.strip()
    # Path на POSIX не считает обратную косую черту разделителем. Проверяем
    # оба варианта явно, поскольку индекс может быть перенесён с Windows.
    if "/" in raw_name or "\\" in raw_name or "\x00" in raw_name:
        return None
    candidate = Path(raw_name)
    if candidate.is_absolute() or candidate.name != str(candidate):
        return None
    if candidate.name in (".", ".."):
        return None
    return Path(cache_dir) / "audio" / candidate.name


def audio_export_kwargs(output_format, bitrate=None, tags=None, cover=None):
    """Формирует безопасные аргументы Pydub для выбранного контейнера."""
    fmt = str(output_format).lower().strip()
    kwargs = {"format": fmt}
    if fmt in {"mp3", "ogg", "opus", "m4a"} and bitrate:
        kwargs["bitrate"] = bitrate
    if tags:
        kwargs["tags"] = tags
    # Pydub передаёт cover как attached picture, что поддерживает его MP3-
    # механизм. WAV/OGG требуют другого представления обложек и иначе падают.
    if fmt == "mp3" and cover and Path(cover).is_file():
        kwargs["cover"] = str(cover)
    return kwargs


def _cover_mime_type(path):
    """Определяет MIME JPEG/PNG по сигнатуре, а не по расширению файла."""
    path = Path(path)
    try:
        with path.open("rb") as cover_file:
            signature = cover_file.read(16)
    except OSError:
        return None
    if signature.startswith(b"\xff\xd8\xff"):
        return "image/jpeg"
    if signature.startswith(b"\x89PNG\r\n\x1a\n"):
        return "image/png"
    return None


def _m4b_cover_codec(path):
    """Выбирает кодек обложки для совместимого контейнера M4B.

    JPEG уже является нативным форматом обложки MP4, поэтому его копирование
    сохраняет исходное изображение без повторной потери качества. PNG
    по-прежнему перекодируется в MJPEG ради одинакового поведения
    Apple-проигрывателей.
    """
    return "copy" if _cover_mime_type(path) == "image/jpeg" else "mjpeg"


def _xiph_metadata_block_picture(cover):
    """Возвращает блок изображения FLAC в кодировке Base64 для VorbisComment/OpusTags.

    Ogg Opus и Ogg Vorbis не хранят обложку как обычный видеопоток в файле.
    Стандартный способ Xiph — бинарная структура FLAC PICTURE, закодированная
    base64 в комментарии ``METADATA_BLOCK_PICTURE``. FFmpeg при чтении
    представляет такой комментарий как виртуальный ``attached_pic``-поток,
    поэтому существующее извлечение обложек продолжает работать.

    Одинаковая запись применяется к Ogg/Vorbis и Ogg/Opus.
    """
    path = Path(cover)
    mime_type = _cover_mime_type(path)
    if mime_type is None:
        raise ValueError("Обложка должна быть файлом JPEG или PNG")
    image_data = path.read_bytes()
    mime_bytes = mime_type.encode("ascii")
    description = b""
    picture = b"".join(
        (
            struct.pack(">I", 3),  # лицевая обложка
            struct.pack(">I", len(mime_bytes)),
            mime_bytes,
            struct.pack(">I", len(description)),
            description,
            # Размеры/глубина необязательны в Xiph picture block. Нули не
            # требуют декодировать изображение в Python и валидны для JPEG/PNG.
            struct.pack(">IIIII", 0, 0, 0, 0, len(image_data)),
            image_data,
        )
    )
    return base64.b64encode(picture).decode("ascii")


def _xiph_cover_metadata(cover, output_name=None):
    """Безопасно готовит обложку Xiph; ошибочная картинка не срывает звук."""
    if not cover or not Path(cover).is_file():
        return None
    try:
        return _xiph_metadata_block_picture(cover)
    except (OSError, ValueError) as exc:
        logging.warning(
            "Обложка пропущена%s: %s",
            f" для {output_name}" if output_name else "",
            exc,
        )
        return None


def _create_xiph_cover_metadata_file(cover, output_name=None):
    """Создаёт короткоживущий FFmetadata input без лимита командной строки.

    Base64 обычной книжной обложки легко превышает предел аргументов Windows
    или macOS. Поэтому передаём ``METADATA_BLOCK_PICTURE`` FFmpeg через файл,
    закрытый до запуска дочернего процесса, а вызывающий код удаляет его после
    завершения операции.
    """
    encoded_picture = _xiph_cover_metadata(cover, output_name)
    if not encoded_picture:
        return None
    SESSION_TEMP_DIR.mkdir(parents=True, exist_ok=True)
    metadata_path = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="ascii",
            newline="\n",
            prefix="opus_cover_",
            suffix=".ffmeta",
            dir=SESSION_TEMP_DIR,
            delete=False,
        ) as metadata_file:
            metadata_path = Path(metadata_file.name)
            metadata_file.write(";FFMETADATA1\n")
            metadata_file.write(
                f"METADATA_BLOCK_PICTURE={encoded_picture}\n"
            )
        return metadata_path
    except Exception:
        if metadata_path is not None:
            metadata_path.unlink(missing_ok=True)
        raise


def normalize_clipboard_text(value):
    """Декодирует пути из Finder, не изменяя обычный текст буфера обмена."""
    text = str(value)
    candidate = text.strip()
    if not candidate:
        return text

    if (
        len(candidate) >= 2
        and candidate[0] in {'"', "'"}
        and candidate[-1] == candidate[0]
    ):
        path_candidate = candidate[1:-1]
    else:
        path_candidate = candidate

    if path_candidate.lower().startswith("file://"):
        try:
            parsed = urllib.parse.urlsplit(path_candidate)
        except ValueError:
            return text
        path = urllib.parse.unquote(parsed.path)
        if parsed.netloc and parsed.netloc.lower() != "localhost":
            path = f"//{parsed.netloc}{path}"
        if platform.system() == "Windows" and re.match(r"^/[A-Za-z]:[\\/]", path):
            path = path[1:]
        return unicodedata.normalize("NFC", path)

    looks_like_path = (
        path_candidate.startswith(("/", "~/", "\\\\"))
        or re.match(r"^[A-Za-z]:[\\/]", path_candidate) is not None
    )
    if looks_like_path:
        return unicodedata.normalize(
            "NFC",
            urllib.parse.unquote(path_candidate),
        )
    return text


def duplicate_paths(paths):
    """Возвращает пути, конфликтующие на Windows и типичной файловой системе macOS."""
    groups = {}
    for path in paths:
        value = str(path)
        key = unicodedata.normalize("NFC", value).casefold()
        groups.setdefault(key, []).append(value)
    duplicates = {
        value
        for values in groups.values()
        if len(values) > 1
        for value in values
    }
    return sorted(
        duplicates,
        key=lambda value: (unicodedata.normalize("NFC", value).casefold(), value),
    )


def validate_export_output_paths(output_paths, source_paths=()):
    """Проверяет безопасность путей перед параллельной публикацией файлов.

    Проверка ничего не создаёт и не изменяет. Она отклоняет выходные пути,
    совпадающие после NFC-нормализации и приведения регистра, а также разные
    записи, ведущие к одному месту через символическую ссылку. Ни один результат
    не может совпадать с исходником напрямую, через символическую ссылку либо
    через уже существующую жёсткую ссылку.

    Возвращается неизменяемый кортеж ``Path`` в исходном порядке. При конфликте
    выбрасывается ``ValueError`` с путями, которые нужно исправить до запуска
    фоновых задач.
    """

    def path_value(value, kind):
        text = str(value or "").strip()
        if not text:
            raise ValueError(f"Пустой путь {kind} файла")
        return Path(text).expanduser()

    def normalized_identity(path, *, resolve=False):
        try:
            candidate = (
                path.resolve(strict=False)
                if resolve
                else path.absolute()
            )
        except (OSError, RuntimeError, ValueError):
            candidate = path
        return unicodedata.normalize("NFC", os.path.normpath(str(candidate))).casefold()

    def existing_file_identity(path):
        try:
            stat_result = path.stat()
        except (OSError, ValueError):
            return None
        return (stat_result.st_dev, stat_result.st_ino)

    outputs = tuple(path_value(path, "выходного") for path in output_paths)
    sources = tuple(path_value(path, "исходного") for path in source_paths)

    # Сначала сохраняем читаемое имя каждого владельца ключа. Проверяются и
    # записанный пользователем путь, и фактическое назначение существующих
    # символических ссылок/ссылочных каталогов.
    output_keys = {}
    for output in outputs:
        for identity in {
            normalized_identity(output),
            normalized_identity(output, resolve=True),
        }:
            previous = output_keys.get(identity)
            if previous is not None:
                raise ValueError(
                    "Несколько результатов будут записаны в один файл: "
                    f"{previous} и {output}"
                )
            output_keys[identity] = output

    source_keys = {}
    source_file_keys = {}
    for source in sources:
        for identity in {
            normalized_identity(source),
            normalized_identity(source, resolve=True),
        }:
            source_keys.setdefault(identity, source)
        file_identity = existing_file_identity(source)
        if file_identity is not None:
            source_file_keys.setdefault(file_identity, source)

    for output in outputs:
        for identity in {
            normalized_identity(output),
            normalized_identity(output, resolve=True),
        }:
            source = source_keys.get(identity)
            if source is not None:
                raise ValueError(
                    "Выходной файл совпадает с исходным: "
                    f"{output} и {source}"
                )
        # ``resolve()`` не объединяет жёсткие ссылки. Пара ``st_dev/st_ino``
        # имеет ту же семантику, что ``os.path.samefile``, без квадратичного
        # перебора всех исходников для больших библиотек.
        file_identity = existing_file_identity(output)
        source = source_file_keys.get(file_identity)
        if file_identity is not None and source is not None:
            raise ValueError(
                "Выходной файл совпадает с исходным: "
                f"{output} и {source}"
            )

    return outputs


def unique_new_file_paths(paths, existing_paths=()):
    """Оставляет новые локальные пути в исходном порядке без дублей.

    Дедупликация выполняется до фонового чтения метаданных. Это гарантирует,
    что последний уже существующий элемент не помешает отправить в UI
    накопившуюся неполную пачку действительно новых файлов.
    """

    def identity(value):
        try:
            normalized = str(Path(value).expanduser().resolve())
        except (OSError, RuntimeError, TypeError, ValueError):
            normalized = str(value)
        normalized = unicodedata.normalize("NFC", normalized)
        return normalized.casefold() if platform.system() == "Windows" else normalized

    seen = {identity(path) for path in existing_paths}
    result = []
    for path in paths:
        key = identity(path)
        if key in seen:
            continue
        seen.add(key)
        result.append(str(path))
    return tuple(result)


def normalize_output_filename(value, output_format, fallback="direct_output"):
    """Нормализует пользовательское имя файла прямого синтеза для всех целевых ОС."""
    raw_name = str(value or "").strip().replace("\\", "/").rsplit("/", 1)[-1]
    safe_format = str(output_format or "mp3").lower().strip()
    if safe_format not in {"mp3", "wav", "ogg", "opus", "m4a"}:
        safe_format = "mp3"
    # Расширение, указанное пользователем, считаем синтаксисом, а не частью
    # названия. Удаляем и повторяющиеся копии (``speech.m4a.m4a``), иначе после
    # добавления нормализованного расширения получится непригодный дубликат.
    stem = _template_basename(raw_name, safe_format) if raw_name else fallback
    stem = Path(stem).stem if stem else fallback
    safe_stem = sanitize_filename_component(stem, fallback=fallback)
    return f"{safe_stem}.{safe_format}"


def remove_cache_index_files(cache_dir):
    """Удаляет рабочий индекс кэша, резервную копию и временные снимки."""
    cache_dir = Path(cache_dir)
    for pattern in (
        "sentence_cache.json",
        "sentence_cache.json.bak",
        "sentence_cache.json.tmp",
        ".sentence_cache.json.*.tmp",
    ):
        for path in cache_dir.glob(pattern):
            path.unlink(missing_ok=True)


def validate_cache_index(data):
    """Проверяет актуальный формат ``sentence_cache.json``.

    Публичные GUI-релизы уже используют словарь метаданных. Древний формат
    ``hash -> строка пути`` намеренно не мигрируется: работа с ним скрывала бы
    повреждённый/чужой индекс и мешала безопасной оптимизации.
    """
    if not isinstance(data, dict):
        raise ValueError("корень индекса должен быть JSON-объектом")
    normalized = {}
    now = time.time()
    for cache_key, cache_info in data.items():
        if not isinstance(cache_key, str):
            raise ValueError("хэш записи кэша должен быть строкой")
        if not isinstance(cache_info, dict):
            raise ValueError(
                f"запись {cache_key!r} не является JSON-объектом метаданных"
            )
        entry = dict(cache_info)
        created_at = _safe_cache_timestamp(entry.get("created_at"), now)
        entry["created_at"] = created_at
        entry["last_accessed"] = _safe_cache_timestamp(
            entry.get("last_accessed"), created_at
        )
        entry["usage_count"] = _safe_cache_usage_count(
            entry.get("usage_count")
        )
        normalized[cache_key] = entry
    return normalized


def _safe_cache_timestamp(value, default=0.0):
    """Возвращает конечную метку времени для TTL/LRU."""
    try:
        timestamp = float(value)
    except (TypeError, ValueError, OverflowError):
        timestamp = float(default)
    return timestamp if math.isfinite(timestamp) else float(default)


def _safe_cache_usage_count(value, default=0):
    """Возвращает неотрицательный счётчик обращений к кэшу."""
    try:
        count = int(value)
    except (TypeError, ValueError, OverflowError):
        count = int(default)
    return max(0, count)


def read_cache_index_with_backup(cache_path):
    """Читает основной индекс, затем ``.bak``.

    Возвращает ``(data, source_path, errors)``. Ошибки не скрываются, но
    вызывающий код может продолжить с валидной резервной копией.
    """
    cache_path = Path(cache_path)
    backup_path = cache_path.with_suffix(cache_path.suffix + ".bak")
    errors = []
    for candidate in (cache_path, backup_path):
        if not candidate.exists():
            continue
        try:
            with open(candidate, "r", encoding="utf-8-sig") as file:
                return validate_cache_index(json.load(file)), candidate, errors
        except Exception as exc:
            errors.append((candidate, exc))
    return {}, None, errors


def write_cache_index_atomic(cache_dir, cache):
    """Атомарно публикует индекс и зеркальную валидную ``.bak``-копию."""
    cache_dir = Path(cache_dir)
    cache = validate_cache_index(cache)
    if not cache:
        remove_cache_index_files(cache_dir)
        return

    cache_dir.mkdir(parents=True, exist_ok=True)
    index_path = cache_dir / "sentence_cache.json"
    backup_path = index_path.with_suffix(index_path.suffix + ".bak")
    temp_path = index_path.with_name(
        f".{index_path.name}.{uuid.uuid4().hex}.tmp"
    )
    backup_temp_path = backup_path.with_name(
        f".{backup_path.name}.{uuid.uuid4().hex}.tmp"
    )
    try:
        with open(temp_path, "w", encoding="utf-8") as file:
            json.dump(cache, file, ensure_ascii=False, indent=4)
            file.flush()
            os.fsync(file.fileno())
        os.replace(temp_path, index_path)
        try:
            # Для кэша резервная копия должна отражать уже подтверждённое
            # состояние. Иначе восстановление могло воскресить удалённые ключи.
            # Пишем её через отдельный временный файл: авария во время copy2
            # оставит предыдущую валидную .bak, а не обрезанную копию.
            shutil.copy2(index_path, backup_temp_path)
            os.replace(backup_temp_path, backup_path)
        except OSError as exc:
            logging.warning("Не удалось обновить резервную копию кэша: %s", exc)
    finally:
        temp_path.unlink(missing_ok=True)
        backup_temp_path.unlink(missing_ok=True)


def unreferenced_cache_audio_paths(cache_dir, removed_entries, retained_cache):
    """Возвращает безопасные файлы, на которые больше не ссылается индекс."""
    retained_names = {
        info.get("file_name")
        for info in retained_cache.values()
        if isinstance(info, dict) and isinstance(info.get("file_name"), str)
    }
    paths = []
    seen = set()
    for cache_info in removed_entries:
        if not isinstance(cache_info, dict):
            continue
        filename = cache_info.get("file_name")
        if filename in retained_names:
            continue
        filepath = resolve_cache_audio_path(cache_dir, filename)
        if filepath is not None and filepath not in seen:
            seen.add(filepath)
            paths.append(filepath)
        elif filename:
            logging.warning(
                "Пропущено небезопасное имя файла в индексе кэша: %r",
                filename,
            )
    return paths


def clear_cache_storage(cache_dir):
    """Удаляет только принадлежащие приложению файлы синтезированного кэша.

    Нельзя безусловно делать ``rmtree(cache_dir / 'audio')``: пользователь
    может случайно выбрать общей папкой кэша домашний каталог, где уже есть
    собственная папка ``audio``. Формат имён приложения достаточно строг,
    чтобы удалить кэш и сохранить посторонние файлы вместе с glossary.json.
    """
    cache_dir = Path(cache_dir)
    # Сначала убираем индекс: даже частичный сбой последующего rmtree не
    # оставит JSON, указывающий на уже удалённые аудиофайлы.
    remove_cache_index_files(cache_dir)
    audio_dir = cache_dir / "audio"
    silence_dir = cache_dir / "silences"
    owned_patterns = (
        "[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]"
        "[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]"
        "[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]"
        "[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f].ogg",
        "temp_*.ogg",
        "prepared_*.ogg",
    )
    if audio_dir.is_dir():
        for pattern in owned_patterns:
            for path in audio_dir.glob(pattern):
                if path.is_file() or path.is_symlink():
                    path.unlink(missing_ok=True)

    if silence_dir.is_dir():
        for pattern in ("silence_*ms.ogg", ".silence_*.tmp.ogg"):
            for path in silence_dir.glob(pattern):
                if path.is_file() or path.is_symlink():
                    path.unlink(missing_ok=True)
        try:
            silence_dir.rmdir()
        except OSError:
            # Посторонние файлы/папки намеренно сохраняются.
            pass

    # Очень ранние локальные сборки могли оставлять рабочие OGG в корне.
    for pattern in ("temp_*.ogg", "prepared_*.ogg"):
        for path in cache_dir.glob(pattern):
            if path.is_file() or path.is_symlink():
                path.unlink(missing_ok=True)

    audio_dir.mkdir(parents=True, exist_ok=True)


def create_zip_archive_atomic(source_dir, destination):
    """Создаёт ZIP рядом с целью и публикует его одной заменой."""
    source_dir = Path(source_dir).resolve()
    destination = Path(destination).expanduser().with_suffix(".zip").resolve()
    destination.parent.mkdir(parents=True, exist_ok=True)
    temp_base = destination.with_name(
        f".{destination.stem}.{uuid.uuid4().hex}.tmp"
    )
    temp_archive = temp_base.with_suffix(temp_base.suffix + ".zip")
    try:
        created_path = Path(
            shutil.make_archive(
                str(temp_base),
                "zip",
                root_dir=source_dir.parent,
                base_dir=source_dir.name,
            )
        )
        if not created_path.is_file():
            raise OSError("Архиватор не создал выходной ZIP-файл")
        os.replace(created_path, destination)
        return destination
    finally:
        temp_archive.unlink(missing_ok=True)


def resolve_api_steps(config):
    """Возвращает включённый ``steps`` либо ``None`` для серверного значения по умолчанию.

    Отсутствующий ключ (старый конфиг) всегда означает прежнее поведение:
    параметр не добавляется в тело запроса. Проверка централизована, чтобы API и
    ключ кэша гарантированно использовали одно и то же целое значение.
    """
    enabled = _config_bool(config.get("api_steps_enabled", False))
    if not enabled:
        return None

    raw_value = config.get("api_steps", 16)
    if isinstance(raw_value, bool):
        raise ValueError("Steps должен быть положительным целым числом")

    try:
        if isinstance(raw_value, int):
            steps = raw_value
        elif isinstance(raw_value, float):
            if not raw_value.is_integer():
                raise ValueError
            steps = int(raw_value)
        else:
            raw_text = str(raw_value).strip()
            if not re.fullmatch(r"[+-]?\d+", raw_text):
                raise ValueError
            steps = int(raw_text)
    except (TypeError, ValueError):
        raise ValueError("Steps должен быть положительным целым числом") from None

    if steps < API_STEPS_MIN:
        raise ValueError("Steps должен быть положительным целым числом (1 или больше)")
    if steps > API_STEPS_MAX:
        raise ValueError(
            f"Steps должен быть не больше {API_STEPS_MAX}. "
            "Текущий Silero EnhancedTTS отклоняет большие значения с ошибкой HTTP 422."
        )
    return steps


def get_api_steps_warning(steps):
    """Возвращает предупреждение для большого steps, не запрещая запрос."""
    if steps is None or steps < API_STEPS_SOFT_WARNING:
        return None
    if steps >= API_STEPS_STRONG_WARNING:
        return (
            f"Вы выбрали Steps = {steps}. Начиная примерно с 32 заметного "
            "прироста качества обычно уже нет, а результат может стать менее "
            "стабильным. Синтез при этом займёт значительно больше времени."
        )
    return (
        f"Вы выбрали Steps = {steps}. Значения выше 16 экспериментальны: "
        "обработка станет дольше, а прирост качества не гарантирован."
    )


def analyze_cache_step_variants(cache):
    """Возвращает статистику старых и явных Steps-вариантов индекса."""
    stats = {
        "total": 0,
        "legacy": 0,
        "steps": 0,
        "steps_by_value": {},
        "shared_steps": 0,
    }
    if not isinstance(cache, dict):
        return stats

    for cache_info in cache.values():
        if not isinstance(cache_info, dict):
            continue
        stats["total"] += 1
        if cache_info.get("steps") is None:
            stats["legacy"] += 1
            continue

        stats["steps"] += 1
        raw_steps = cache_info.get("steps")
        try:
            steps_value = int(raw_steps)
        except (TypeError, ValueError):
            steps_value = str(raw_steps)
        stats["steps_by_value"][steps_value] = (
            stats["steps_by_value"].get(steps_value, 0) + 1
        )
        if not _config_bool(
            cache_info.get("steps_in_cache_key", True), default=True
        ):
            stats["shared_steps"] += 1
    return stats


def should_keep_cache_variant(cache_info, policy, current_steps=None):
    """Определяет, разрешает ли выбранная политика данный вариант качества.

    Эта проверка применяется после проверки актуальности текста. Записи старого
    формата без ``steps`` считаются старыми; известное значение сравнивается как
    целое число, чтобы JSON-строки старых промежуточных сборок не терялись.
    """
    if policy == CACHE_VARIANT_KEEP_ALL:
        return True

    raw_steps = cache_info.get("steps") if isinstance(cache_info, dict) else None
    is_legacy = raw_steps is None
    if policy == CACHE_VARIANT_KEEP_LEGACY:
        return is_legacy

    try:
        cached_steps = int(raw_steps) if raw_steps is not None else None
    except (TypeError, ValueError):
        cached_steps = raw_steps
    is_current = current_steps is not None and cached_steps == current_steps

    if policy == CACHE_VARIANT_KEEP_LEGACY_CURRENT:
        return is_legacy or is_current
    if policy == CACHE_VARIANT_KEEP_CURRENT:
        return is_current
    raise ValueError(f"Неизвестная политика вариантов кэша: {policy}")


def cache_content_hash(normalized_text, speaker):
    """Возвращает канонический хэш содержимого без параметров качества."""
    return hashlib.md5(
        f"{normalized_text}_{speaker}".encode("utf-8")
    ).hexdigest()


def cache_entry_matches_required_text(cache_info, required_hashes):
    """Проверяет запись по метаданным, не учитывая её пространство имён Steps."""
    if not isinstance(cache_info, dict):
        return False
    normalized_text = cache_info.get("normalized_text")
    speaker = cache_info.get("speaker")
    if (
        not isinstance(normalized_text, str)
        or not normalized_text
        or not isinstance(speaker, str)
        or not speaker
    ):
        return False
    return cache_content_hash(normalized_text, speaker) in required_hashes

def _find_bundled_binary(bin_name):
    if not getattr(sys, 'frozen', False):
        return None

    exe_dir = Path(sys.executable).resolve().parent
    bundle_dir = Path(getattr(sys, '_MEIPASS', exe_dir)).resolve()
    candidates = [
        bundle_dir / bin_name,
        exe_dir / bin_name,
        exe_dir.parent / "Frameworks" / bin_name,
        exe_dir.parent / "Resources" / bin_name,
        exe_dir.parent / "MacOS" / bin_name,
    ]

    for candidate in candidates:
        if candidate.exists():
            return str(candidate)
    return None

def _get_media_binary_path(tool_name):
    """Сначала ищет FFmpeg/FFprobe внутри пакета, затем в системе."""
    bin_name = f"{tool_name}.exe" if platform.system() == "Windows" else tool_name
    if getattr(sys, "frozen", False):
        local_bin = _find_bundled_binary(bin_name)
        if local_bin:
            return local_bin
    return _resolve_external_binary(bin_name) or bin_name


def get_ffmpeg_path():
    return _get_media_binary_path("ffmpeg")


def get_ffprobe_path():
    return _get_media_binary_path("ffprobe")


# Импорт Pydub и настройка путей FFmpeg
# При импорте Pydub один раз проверяет только PATH и успевает вывести ложное
# предупреждение в frozen/GUI-сборке, хотя встроенный FFmpeg уже найден нами по
# абсолютному пути. Подавляем исключительно это сообщение и только когда файл
# действительно существует; при реальном отсутствии зависимость по-прежнему
# явно диагностируется.
_PRE_RESOLVED_FFMPEG = get_ffmpeg_path()
if Path(_PRE_RESOLVED_FFMPEG).is_file():
    with warnings.catch_warnings():
        warnings.filterwarnings(
            "ignore",
            message=r"Couldn't find ffmpeg or avconv.*",
            category=RuntimeWarning,
        )
        from pydub import AudioSegment
else:
    from pydub import AudioSegment
from pydub.silence import detect_nonsilent


def _create_ffmpeg_concat_manifest(audio_files):
    """Создаёт закрытый перед запуском FFmpeg concat-манифест.

    Каждый вызов владеет только своим файлом. Общую папку ``temp`` нельзя
    рекурсивно очищать во время работы: другой поток или второй экземпляр
    приложения мог уже передать расположенный в ней манифест процессу FFmpeg,
    который ещё не успел открыть файл.
    """
    SESSION_TEMP_DIR.mkdir(parents=True, exist_ok=True)

    list_path = None
    try:
        # NamedTemporaryFile атомарно резервирует имя. delete=False необходим
        # на Windows: FFmpeg открывает файл уже после закрытия Python-дескриптора.
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            newline="\n",
            prefix="concat_",
            suffix=".txt",
            dir=SESSION_TEMP_DIR,
            delete=False,
        ) as manifest:
            list_path = Path(manifest.name)
            for audio_path in audio_files:
                safe_path = Path(audio_path).resolve().as_posix().replace("'", "'\\''")
                manifest.write(f"file '{safe_path}'\n")
        return list_path
    except Exception:
        if list_path is not None:
            list_path.unlink(missing_ok=True)
        raise


def _export_audio_atomic(audio_segment, out_path, **export_kwargs):
    """Экспортирует Pydub-сегмент рядом с целью и атомарно заменяет её."""
    out_path = Path(out_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    temp_path = out_path.with_name(
        f".audio_{uuid.uuid4().hex}.tmp{out_path.suffix}"
    )
    exported = None
    try:
        exported = audio_segment.export(temp_path, **export_kwargs)
        if hasattr(exported, "flush"):
            exported.flush()
        if hasattr(exported, "close"):
            exported.close()
            exported = None
        if not temp_path.exists():
            raise OSError(f"Кодировщик не создал временный файл {temp_path.name}")
        os.replace(temp_path, out_path)
        return out_path
    finally:
        if exported is not None and hasattr(exported, "close"):
            try:
                exported.close()
            except OSError:
                pass
        temp_path.unlink(missing_ok=True)


def _probe_audio_stream_profile(path):
    """Возвращает параметры первого аудиопотока и его контейнера.

    Для групповой сборки нельзя безусловно сводить любой материал к профилю
    внутреннего TTS-кэша (48 кГц, моно): пользователь может объединять музыку,
    стерео MP3 и WAV с более высокой частотой. Короткий проход ffprobe читает
    только заголовки и позволяет построить единый, но не заниженный профиль для
    concat-фильтра. Ошибка пробинга не скрывает последующую диагностику FFmpeg:
    вызывающий код применит консервативные резервные параметры.
    """
    startupinfo = None
    if platform.system() == "Windows":
        startupinfo = subprocess.STARTUPINFO()
        startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW

    command = [
        get_ffprobe_path(),
        "-v", "error",
        "-select_streams", "a:0",
        "-show_entries",
        (
            "stream=codec_name,profile,sample_fmt,sample_rate,channels,"
            "channel_layout,bit_rate,codec_tag_string,time_base,extradata_hash:"
            "format=format_name"
        ),
        # Extradata содержит настройки кодека, которые не видны по частоте и
        # каналам. Хэш позволяет не отдавать демультиплексору ``concat`` несовместимые
        # заголовки Vorbis/Opus, не передавая сами бинарные данные в Python.
        "-show_data", "-show_data_hash", "sha256",
        "-of", "json",
        str(Path(path)),
    ]
    try:
        completed = subprocess.run(
            command,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=30,
            startupinfo=startupinfo,
        )
        probe_data = json.loads(getattr(completed, "stdout", "") or "{}")
        streams = probe_data.get("streams", ())
        if not streams:
            return None
        sample_rate = int(streams[0].get("sample_rate", 0))
        channels = int(streams[0].get("channels", 0))
        if sample_rate <= 0 or channels <= 0:
            return None
        raw_bitrate = streams[0].get("bit_rate")
        try:
            bitrate = int(raw_bitrate) if raw_bitrate is not None else None
        except (TypeError, ValueError):
            bitrate = None
        # FFmpeg/ffprobe сообщает UINT32_MAX-1 для некоторых VBR Vorbis как
        # маркер «битрейт неизвестен». Это не реальный 4,29-Гбит/с поток и его
        # нельзя переносить в ``-b:a`` режима Auto.
        if bitrate is not None and bitrate >= 0xFFFFFF00:
            bitrate = None
        stream = streams[0]
        format_info = probe_data.get("format", {})
        return {
            "codec": str(stream.get("codec_name", "")).strip().lower(),
            "sample_rate": sample_rate,
            "channels": channels,
            "bitrate": bitrate if bitrate and bitrate > 0 else None,
            "format_name": str(format_info.get("format_name", "")).strip().lower(),
            "profile": str(stream.get("profile", "")).strip().lower(),
            "sample_fmt": str(stream.get("sample_fmt", "")).strip().lower(),
            "channel_layout": str(
                stream.get("channel_layout", "")
            ).strip().lower(),
            "codec_tag": str(
                stream.get("codec_tag_string", "")
            ).strip().lower(),
            "time_base": str(stream.get("time_base", "")).strip().lower(),
            "extradata_hash": str(
                stream.get("extradata_hash", "")
            ).strip().lower(),
        }
    except (OSError, subprocess.SubprocessError, TypeError, ValueError):
        return None


def _mp3_compatible_sample_rate(sample_rate):
    """Выбирает поддерживаемую libmp3lame частоту без лишнего понижения частоты дискретизации."""
    supported = (8000, 11025, 12000, 16000, 22050, 24000, 32000, 44100, 48000)
    sample_rate = max(1, int(sample_rate))
    for candidate in supported:
        if candidate >= sample_rate:
            return candidate
    return supported[-1]


def _opus_compatible_sample_rate(sample_rate):
    """Выбирает ближайшую частоту, поддерживаемую libopus."""
    supported = (8000, 12000, 16000, 24000, 48000)
    sample_rate = max(1, int(sample_rate))
    for candidate in supported:
        if candidate >= sample_rate:
            return candidate
    return supported[-1]


def _audio_profile_compatibility_error(
    output_format,
    sample_rate,
    channels,
    bitrate,
):
    """Объясняет несовместимый профиль до запуска FFmpeg.

    Поля экспорта общие для всех контейнеров, но кодеки принимают разные
    сочетания. Не оставляем эту проверку поздней ошибке ``Error while opening
    encoder`` и не подменяем явно выбранный пользователем битрейт молча.
    """
    fmt = str(output_format).strip().lower()
    sample_rate = int(sample_rate)
    channels = int(channels)
    bitrate_text = str(bitrate or "").strip().lower()
    if fmt in {"wav"} or not bitrate_text:
        return None
    match = re.fullmatch(r"([1-9]\d*)k", bitrate_text)
    if not match:
        return "Некорректный битрейт аудиопрофиля."
    bitrate_kbps = int(match.group(1))

    if fmt == "mp3" and not 8 <= bitrate_kbps <= 320:
        return "MP3 поддерживает битрейт от 8 до 320 кбит/с."
    if fmt == "mp3" and sample_rate <= 12000 and bitrate_kbps > 64:
        return (
            "MP3 с частотой 8–12 кГц поддерживает битрейт не выше "
            "64 кбит/с. Увеличьте частоту либо используйте режим «Авто»."
        )
    if fmt == "mp3" and sample_rate <= 24000 and bitrate_kbps > 160:
        return (
            "MP3 с частотой 16–24 кГц поддерживает битрейт не выше "
            "160 кбит/с. Выберите 128 кбит/с, увеличьте частоту до 32 кГц "
            "или используйте режим «Авто»."
        )

    if fmt == "opus" and not 6 <= bitrate_kbps <= 510:
        return (
            "Opus поддерживает битрейт от 6 до 510 кбит/с. Выберите "
            "совместимое значение либо используйте режим «Авто»."
        )

    # Для внутреннего этапа M4A и M4B используется AAC-LC. FFmpeg принимает
    # более широкий диапазон, но единый консервативный диапазон для речи не
    # позволяет случайно создать профиль, который многие проигрыватели книг
    # декодируют ненадёжно.
    if fmt in {"m4a", "m4b"} and not 16 <= bitrate_kbps <= 512:
        return (
            "AAC/M4B поддерживает битрейт от 16 до 512 кбит/с. Выберите "
            "совместимое значение либо используйте режим «Авто»."
        )

    if fmt == "ogg":
        if not 32 <= bitrate_kbps <= 500:
            return "OGG/Vorbis поддерживает битрейт от 32 до 500 кбит/с."
        if sample_rate > 48000:
            return (
                "OGG/Vorbis 88,2/96 кГц доступен только с битрейтом "
                "«Авто» (quality-режим кодировщика). Выберите «Авто» либо "
                "частоту не выше 48 кГц."
            )
        maximums = {
            (8000, 1): 32,
            (8000, 2): 64,
            (12000, 1): 48,
            (12000, 2): 96,
            (16000, 1): 96,
            (16000, 2): 192,
            (22050, 1): 64,
            (22050, 2): 128,
            (24000, 1): 64,
            (24000, 2): 128,
            (32000, 1): 128,
            (32000, 2): 320,
            (44100, 1): 192,
            (48000, 1): 192,
        }
        maximum = maximums.get((sample_rate, channels))
        if maximum is not None and bitrate_kbps > maximum:
            channel_text = "mono" if channels == 1 else "stereo"
            return (
                f"OGG/Vorbis {sample_rate / 1000:g} кГц {channel_text} "
                f"поддерживает выбранный режим битрейта не выше "
                f"{maximum} кбит/с. Уменьшите битрейт, увеличьте частоту "
                "или используйте режим «Авто»."
            )
    return None


def _select_book_audio_profile(
    output_format,
    *,
    sample_rate="auto",
    channels="auto",
    bitrate="128k",
):
    """Разрешает профиль финальной книги из канонического 48 kHz mono-кэша."""
    output_format = str(output_format).strip().lower()
    if output_format not in AUDIO_PROFILE_FORMATS:
        raise ValueError("Выбран неподдерживаемый формат финальной книги.")

    requested_rate = str(sample_rate).strip().lower()
    selected_rate = (
        CACHE_AUDIO_SAMPLE_RATE if requested_rate == "auto" else int(requested_rate)
    )
    if output_format == "mp3":
        compatible = _mp3_compatible_sample_rate(selected_rate)
        if requested_rate != "auto" and compatible != selected_rate:
            raise ValueError(
                "MP3/libmp3lame не поддерживает выбранную частоту. "
                "Выберите не более 48 кГц либо режим «Авто»."
            )
        selected_rate = compatible
    elif output_format == "opus":
        compatible = _opus_compatible_sample_rate(selected_rate)
        if requested_rate != "auto" and compatible != selected_rate:
            raise ValueError(
                "Opus поддерживает только 8, 12, 16, 24 и 48 кГц."
            )
        selected_rate = compatible

    requested_channels = str(channels).strip().lower()
    if requested_channels not in AUDIO_PROFILE_CHANNELS:
        raise ValueError("Некорректный режим каналов финальной книги.")
    selected_channels = 2 if requested_channels == "stereo" else 1

    requested_bitrate = str(bitrate).strip().lower()
    if output_format == "wav":
        selected_bitrate = None
    elif requested_bitrate == "auto":
        selected_bitrate = {
            "mp3": "128k",
            "opus": "48k",
            # AAC-LC используется и для самостоятельного M4A, и для
            # промежуточного потока M4B. 64 кбит/с — компактное значение для
            # речи; явный профиль может запросить любую поддерживаемую скорость.
            "m4a": "64k",
            # Для Vorbis отсутствие ``-b:a`` оставляет штатный режим качества/VBR.
            "ogg": None,
        }[output_format]
    else:
        selected_bitrate = requested_bitrate
    error = _audio_profile_compatibility_error(
        output_format,
        selected_rate,
        selected_channels,
        selected_bitrate,
    )
    if error:
        raise ValueError(error)
    return {
        "sample_rate": selected_rate,
        "channels": selected_channels,
        "bitrate": selected_bitrate,
    }


def _select_merge_audio_profile(
    sources,
    output_format,
    *,
    sample_rate="auto",
    channels="auto",
    bitrate="auto",
    cancelled=None,
    _probed_profiles=None,
):
    """Выбирает общий профиль для безопасного concat разнородных потоков.

    Максимальная входная частота не занижается, если это допускает выбранный
    контейнер/кодек. Полностью mono-набор остаётся mono; наличие stereo или
    многоканального входа сохраняет stereo-результат. Если хотя бы один файл не
    удалось исследовать, неизвестный поток консервативно считается 48 кГц
    stereo, а сам FFmpeg всё равно выполнит окончательную проверку/декодирование.
    """
    profiles = []
    unknown = []
    if _probed_profiles is None:
        probed_profiles = []
        for source in sources:
            if cancelled and cancelled():
                raise InterruptedError("Сборка остановлена пользователем")
            probed_profiles.append(_probe_audio_stream_profile(source))
    else:
        probed_profiles = list(_probed_profiles)
        if len(probed_profiles) != len(sources):
            raise ValueError("Внутренняя ошибка: число профилей не совпадает")
    for source, profile in zip(sources, probed_profiles):
        if cancelled and cancelled():
            raise InterruptedError("Сборка остановлена пользователем")
        if profile is None:
            unknown.append(Path(source).name)
        else:
            profiles.append(profile)

    if cancelled and cancelled():
        raise InterruptedError("Сборка остановлена пользователем")

    sample_rates = [profile["sample_rate"] for profile in profiles]
    if unknown or not sample_rates:
        sample_rates.append(CACHE_AUDIO_SAMPLE_RATE)
    requested_sample_rate = str(sample_rate).strip().lower()
    if requested_sample_rate != "auto":
        sample_rate = int(sample_rate)
    else:
        sample_rate = max(sample_rates)
    output_format = str(output_format).strip().lower()
    if output_format == "mp3":
        compatible_sample_rate = _mp3_compatible_sample_rate(sample_rate)
        if requested_sample_rate != "auto" and compatible_sample_rate != sample_rate:
            raise ValueError(
                "MP3/libmp3lame не поддерживает выбранную частоту "
                f"{sample_rate} Гц. Выберите частоту не выше 48 кГц либо "
                "режим «Авто»."
            )
        sample_rate = compatible_sample_rate
    elif output_format == "opus":
        compatible_sample_rate = _opus_compatible_sample_rate(sample_rate)
        if requested_sample_rate != "auto" and compatible_sample_rate != sample_rate:
            raise ValueError(
                "Opus/libopus поддерживает только 8, 12, 16, 24 и 48 кГц. "
                "Выберите поддерживаемую частоту либо режим «Авто»."
            )
        sample_rate = compatible_sample_rate

    requested_channels = str(channels).strip().lower()
    if requested_channels == "mono":
        channels = 1
    elif requested_channels == "stereo":
        channels = 2
    else:
        channels = 2 if unknown or any(
            profile["channels"] > 1 for profile in profiles
        ) else 1
    channel_layout = "stereo" if channels == 2 else "mono"

    requested_bitrate = str(bitrate).strip().lower()
    if output_format == "wav":
        selected_bitrate = None
    elif requested_bitrate != "auto":
        selected_bitrate = requested_bitrate
    else:
        # Битрейт имеет одинаковый смысл лишь у сжатых входов. Например,
        # ``bit_rate`` PCM/WAV описывает поток несжатых отсчётов и не должен
        # внезапно становиться целевым битрейтом MP3/OGG в режиме ``auto``.
        bitrates = [
            profile.get("bitrate")
            for profile in profiles
            if profile.get("codec") not in {
                "pcm_s16le", "pcm_s24le", "pcm_s32le", "pcm_f32le", "pcm_f64le"
            }
        ]
        selected_bitrate = (
            f"{round(bitrates[0] / 1000)}k"
            if (
                not unknown
                and bitrates
                and len(bitrates) == len(profiles)
                and all(value for value in bitrates)
                and len(set(bitrates)) == 1
            )
            else None
        )

    compatibility_error = _audio_profile_compatibility_error(
        output_format,
        sample_rate,
        channels,
        selected_bitrate,
    )
    if compatibility_error:
        if requested_bitrate == "auto":
            # В режиме ``auto`` параметры потока являются подсказкой, а не приказом.
            # Сохраняем частоту и каналы, но даём кодировщику выбрать
            # совместимый битрейт вместо заведомого падения.
            selected_bitrate = None
        else:
            raise ValueError(compatibility_error)

    if unknown:
        preview = ", ".join(unknown[:3])
        suffix = "…" if len(unknown) > 3 else ""
        logging.warning(
            "Не удалось определить аудиопрофиль %d входных файлов (%s%s); "
            "для них используется безопасный fallback 48 кГц stereo.",
            len(unknown),
            preview,
            suffix,
        )
    return {
        "sample_rate": sample_rate,
        "channels": channels,
        "channel_layout": channel_layout,
        "bitrate": selected_bitrate,
    }


def _stream_copy_expected_codec(output_format):
    """Возвращает физический кодек для формата, допустимого в быстром пути."""
    return {
        "mp3": "mp3",
        "ogg": "vorbis",
        "opus": "opus",
    }.get(str(output_format).strip().lower())


def _stream_copy_profile_signature(profile):
    """Ключ физических свойств потока для демультиплексора ``concat``.

    Дополнительные поля, которые ffprobe может не вернуть (например,
    ``extradata_hash`` у MP3), намеренно не превращаются в ложное различие:
    если поле отсутствует у всех профилей, оно не участвует в сравнении.
    Реальный ffprobe-профиль содержит все доступные поля; неполный профиль
    допускается для совместимости со сторонними вызывающими сторонами.
    """
    if not isinstance(profile, dict):
        return None
    required = ("codec", "sample_rate", "channels")
    if any(key not in profile for key in required):
        return None
    try:
        basic = (
            str(profile.get("codec", "")).strip().lower(),
            int(profile.get("sample_rate")),
            int(profile.get("channels")),
        )
    except (TypeError, ValueError, OverflowError):
        return None
    if not basic[0] or basic[1] <= 0 or basic[2] <= 0:
        return None
    optional_keys = (
        "format_name", "profile", "sample_fmt", "channel_layout", "codec_tag",
        "time_base", "extradata_hash",
    )
    optional = {
        key: str(profile[key]).strip().lower()
        for key in optional_keys
        if profile.get(key) not in (None, "")
    }
    bitrate = profile.get("bitrate")
    if bitrate in (None, ""):
        bitrate = None
    else:
        try:
            bitrate = int(bitrate)
        except (TypeError, ValueError, OverflowError):
            return None
        if bitrate <= 0:
            bitrate = None
    return basic + (bitrate, optional)


def _can_concat_stream_copy(
    profiles,
    output_format,
    merge_profile,
    *,
    pause_ms=0,
    speed=1.0,
    pitch=1.0,
    echo=False,
    cover=None,
    requested_bitrate="auto",
    allow_unknown_bitrate=False,
):
    """Проверяет, можно ли объединить входы без декодирования/кодирования.

    Копирование потока безопасно только для одинаковых физических потоков в одном
    контейнере. Любое изменение частоты, каналов, кодека, эффекта, паузы или
    обложки отправляет операцию в проверенный резервный путь с ``filter_complex``.
    Известный битрейт должен совпадать; одинаково неизвестный битрейт можно
    явно разрешить для VBR-потоков через ``allow_unknown_bitrate``. WAV
    намеренно никогда не использует этот путь.
    """
    fmt = str(output_format).strip().lower()
    expected_codec = _stream_copy_expected_codec(fmt)
    if expected_codec is None or not isinstance(merge_profile, dict):
        return False
    profiles = tuple(profiles or ())
    if len(profiles) < 2:
        return False
    try:
        if int(pause_ms or 0) != 0:
            return False
    except (TypeError, ValueError, OverflowError):
        return False
    if bool(cover):
        return False
    try:
        if float(speed) != 1.0 or float(pitch) != 1.0:
            return False
    except (TypeError, ValueError, OverflowError):
        return False
    if bool(echo):
        return False

    signatures = [_stream_copy_profile_signature(profile) for profile in profiles]
    if any(signature is None for signature in signatures):
        return False
    first = signatures[0]
    if any(signature[:3] != first[:3] for signature in signatures[1:]):
        return False
    if first[0] != expected_codec:
        return False
    # Ogg/Vorbis и Ogg/Opus используют один контейнер, но формат назначения
    # всё равно обязан совпадать с физическим кодеком. MP3 не принимаем из Ogg.
    expected_container = "mp3" if fmt == "mp3" else "ogg"
    for signature in signatures:
        container = signature[4].get("format_name")
        if container and expected_container not in {
            token.strip() for token in container.split(",")
        }:
            return False
        # Если ffprobe сообщил дополнительные физические признаки, они должны
        # совпадать. Поля, отсутствующие у всех (старые заглушки/старый ffprobe), не
    # мешают базовой проверке; неизвестное поле только у части входов — риск.
    optional_keys = (
        "format_name", "profile", "sample_fmt", "channel_layout", "codec_tag",
        "time_base", "extradata_hash",
    )
    for key in optional_keys:
        values = [signature[4].get(key) for signature in signatures]
        present = [value for value in values if value not in (None, "")]
        if present and (len(present) != len(values) or len(set(present)) != 1):
            return False

    target_rate = merge_profile.get("sample_rate")
    target_channels = merge_profile.get("channels")
    try:
        if int(target_rate) != first[1] or int(target_channels) != first[2]:
            return False
    except (TypeError, ValueError, OverflowError):
        return False

    source_bitrates = [signature[3] for signature in signatures]
    target_bitrate = merge_profile.get("bitrate")
    requested = str(requested_bitrate or "auto").strip().lower()
    if requested == "auto":
        # В режиме Auto профиль назначения не является приказом кодировщику:
        # для книги он может содержать безопасное значение по умолчанию
        # (например, 48k для Opus). Stream-copy при этом сохраняет реальный
        # входной поток. Разрешаем ветку, только если битрейт одинаково
        # известен у всех входов либо одинаково неизвестен (VBR), причём
        # последний вариант допускается только явным флагом вызывающего кода.
        known_bitrates = [value for value in source_bitrates if value is not None]
        if not known_bitrates and not allow_unknown_bitrate:
            return False
        if known_bitrates and (
            len(known_bitrates) != len(source_bitrates)
            or len(set(known_bitrates)) != 1
        ):
            return False
    elif target_bitrate in (None, ""):
        return False
    else:
        try:
            target_bitrate_value = int(str(target_bitrate).lower().rstrip("k")) * 1000
        except (TypeError, ValueError, OverflowError):
            return False
        if any(value is None or value != target_bitrate_value for value in source_bitrates):
            return False
    return True


def _run_ffmpeg_stream_copy_concat(
    audio_files,
    out_path,
    *,
    tags=None,
    cancelled=None,
):
    """Собирает однородные потоки через демультиплексор ``concat`` с ``-c:a copy``."""
    if cancelled and cancelled():
        raise InterruptedError("Сборка остановлена пользователем")
    sources = tuple(Path(path).expanduser().resolve() for path in audio_files)
    if len(sources) < 2:
        raise ValueError("Для stream copy нужны минимум два аудиофайла")
    missing = [str(path) for path in sources if not path.is_file()]
    if missing:
        raise FileNotFoundError(missing[0])
    list_path = _create_ffmpeg_concat_manifest(sources)
    out_path = Path(out_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    temp_path = out_path.with_name(
        f".audio_{uuid.uuid4().hex}.tmp{out_path.suffix}"
    )
    command = [
        get_ffmpeg_path(), "-y", "-hide_banner", "-loglevel", "error",
        "-f", "concat", "-safe", "0", "-i", str(list_path),
        "-map", "0:a:0", "-vn", "-sn", "-dn",
        "-map_metadata", "-1", "-map_chapters", "-1",
        "-c:a", "copy",
    ]
    for key, value in (tags or {}).items():
        if value:
            command.extend(["-metadata", f"{key}={value}"])
    command.append(str(temp_path))
    startupinfo = None
    if platform.system() == "Windows":
        startupinfo = subprocess.STARTUPINFO()
        startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
    process = None
    try:
        _validate_windows_command_length(command)
        with tempfile.TemporaryFile() as stderr_file:
            if cancelled and cancelled():
                raise InterruptedError("Сборка остановлена пользователем")
            process = subprocess.Popen(
                command,
                stdout=subprocess.DEVNULL,
                stderr=stderr_file,
                startupinfo=startupinfo,
            )
            while process.poll() is None:
                if cancelled and cancelled():
                    process.terminate()
                    try:
                        process.wait(timeout=3)
                    except subprocess.TimeoutExpired:
                        process.kill()
                        process.wait()
                    raise InterruptedError("Сборка остановлена пользователем")
                time.sleep(0.05)
            stderr = _read_ffmpeg_log(stderr_file)
            if process.returncode != 0 or not temp_path.is_file():
                detail = stderr.decode("utf-8", errors="ignore").strip()
                raise RuntimeError(
                    "FFmpeg не смог объединить однородные аудиофайлы"
                    + (f": {detail}" if detail else "")
                )
            if cancelled and cancelled():
                raise InterruptedError("Сборка остановлена пользователем")
            os.replace(temp_path, out_path)
            return out_path
    finally:
        if process is not None and process.poll() is None:
            process.kill()
            process.wait()
        list_path.unlink(missing_ok=True)
        temp_path.unlink(missing_ok=True)


def _read_ffmpeg_log(log_file, limit=262144):
    """Возвращает конец журнала FFmpeg без неограниченного чтения."""
    log_file.flush()
    log_file.seek(0, os.SEEK_END)
    size = log_file.tell()
    log_file.seek(max(0, size - int(limit)))
    return log_file.read()


def _ffmpeg_audio_effect_filters(
    *,
    speed=1.0,
    pitch=1.0,
    echo=False,
    echo_delay=300,
    echo_decay=0.3,
    sample_rate=CACHE_AUDIO_SAMPLE_RATE,
):
    """Возвращает общий FFmpeg-граф эффектов без промежуточного WAV."""
    filters = []
    pitch = float(pitch)
    speed = float(speed)
    sample_rate = max(1, int(sample_rate))
    if pitch != 1.0:
        filters.append(f"asetrate={int(sample_rate * pitch)}")
        filters.extend(AudioEffects._atempo_filters(1 / pitch))
        # asetrate меняет заявленную частоту потока; перед кодированием снова
        # приводим её к общему профилю текущей группы.
        filters.append(f"aresample={sample_rate}")
    if speed != 1.0:
        filters.extend(AudioEffects._atempo_filters(speed))
    if echo:
        filters.append(
            f"aecho=0.8:0.8:{int(echo_delay)}:{float(echo_decay)}"
        )
    return filters


def _validate_m4b_effects_disabled(
    *,
    speed=1.0,
    pitch=1.0,
    echo=False,
):
    """Запрещает эффекты для M4B на самом низком уровне.

    M4B главы получают временную шкалу из исходных длительностей. Скорость,
    тон (через ``asetrate``/``aresample``) и эхо меняют эту шкалу, поэтому
    M4B-экспорт не должен принимать такие параметры, даже если вызывающий код
    обошёл проверку интерфейса (например, в старом режиме одной цели или при
    интеграции, напрямую вызвавшей вспомогательную функцию FFmpeg).

    Некорректные числовые значения тоже считаются попыткой включить эффект:
    лучше выдать понятную ошибку, чем незаметно пропустить их в фильтр.
    """
    try:
        speed_value = float(speed)
        pitch_value = float(pitch)
    except (TypeError, ValueError, OverflowError):
        raise ValueError(
            "Эффекты для M4B отключены: скорость и тон должны быть 1.0"
        ) from None
    if not math.isfinite(speed_value) or not math.isfinite(pitch_value):
        raise ValueError(
            "Эффекты для M4B отключены: скорость и тон должны быть 1.0"
        )
    if (
        abs(speed_value - 1.0) > 1e-9
        or abs(pitch_value - 1.0) > 1e-9
        or _config_bool(echo, default=False)
    ):
        raise ValueError(
            "Эффекты для M4B отключены: временные метки глав должны "
            "соответствовать исходной длительности"
        )


def _validate_windows_command_length(command, *, system_name=None, limit=30000):
    """Даёт понятную ошибку до CreateProcess при слишком длинной FFmpeg-команде."""
    current_system = system_name or platform.system()
    if current_system != "Windows":
        return
    rendered_length = len(subprocess.list2cmdline([str(part) for part in command]))
    if rendered_length >= int(limit):
        raise ValueError(
            "Слишком много файлов или слишком длинные пути для одной сборки "
            "в Windows. Разделите группу на несколько частей или сократите "
            "пути к исходным файлам."
        )


def _normalize_audio_source_ranges(sources, source_ranges=None):
    """Проверяет необязательные диапазоны виртуальных аудиоисточников.

    Элементом может быть ``None``, пара ``(start, end)`` либо словарь с
    ``clip_start``/``clip_end``. Возвращаемые границы заданы в секундах и не
    изменяют исходный файл.
    """
    sources = tuple(sources or ())
    if source_ranges is None:
        return (None,) * len(sources)
    ranges = tuple(source_ranges)
    if len(ranges) != len(sources):
        raise ValueError(
            "Число диапазонов аудио не совпадает с числом источников"
        )
    normalized = []
    for index, raw in enumerate(ranges, 1):
        if raw in (None, ""):
            normalized.append(None)
            continue
        if isinstance(raw, dict):
            start = raw.get("clip_start")
            end = raw.get("clip_end")
        else:
            try:
                start, end = raw
            except (TypeError, ValueError):
                raise ValueError(
                    f"Некорректный диапазон аудиоисточника {index}"
                ) from None
        try:
            start = float(start)
            end = float(end)
        except (TypeError, ValueError, OverflowError):
            raise ValueError(
                f"Некорректные границы аудиоисточника {index}"
            ) from None
        if (
            not math.isfinite(start)
            or not math.isfinite(end)
            or start < 0
            or end <= start
        ):
            raise ValueError(
                f"Диапазон аудиоисточника {index} должен иметь конец позже начала"
            )
        normalized.append((start, end))
    return tuple(normalized)


FFMPEG_DECODE_BATCH_INPUTS = 32
FFMPEG_DECODE_BATCH_BYTES = 16000


def _plan_ffmpeg_decode_batches(sources, source_ranges):
    """Ограничивает число открытых входов и длину команды декодирования."""
    batches = []
    batch = []
    command_size = 0
    for source, source_range in zip(sources, source_ranges):
        # Запас включает ключи входа, диапазон и узел фильтра для паузы.
        entry_size = len(os.fsencode(source)) + 512
        if batch and (
            len(batch) >= FFMPEG_DECODE_BATCH_INPUTS
            or command_size + entry_size > FFMPEG_DECODE_BATCH_BYTES
        ):
            batches.append(tuple(batch))
            batch = []
            command_size = 0
        batch.append((source, source_range))
        command_size += entry_size
    if batch:
        batches.append(tuple(batch))
    return tuple(batches)


def _ffmpeg_merge_inputs(sources, source_ranges):
    """Добавляет точные диапазоны перед соответствующими входами FFmpeg."""
    args = []
    for source, source_range in zip(sources, source_ranges):
        if source_range is not None:
            start, end = source_range
            args.extend(["-ss", f"{start:.9f}", "-t", f"{end - start:.9f}"])
        args.extend(["-i", str(source)])
    return args


def _ffmpeg_merge_filter(source_ranges, sample_rate, channel_layout, pause_ms, *, trailing_pause=False):
    """Приводит независимые входы к общему PCM и соединяет их с паузами."""
    filters = []
    labels = []
    for index, source_range in enumerate(source_ranges):
        trim = "" if source_range is None else f"atrim=duration={source_range[1] - source_range[0]:.9f},"
        filters.append(
            f"[{index}:a:0]{trim}aresample={sample_rate},"
            "aformat=sample_fmts=fltp:"
            f"sample_rates={sample_rate}:channel_layouts={channel_layout},"
            f"asetpts=PTS-STARTPTS[a{index}]"
        )
        labels.append(f"[a{index}]")
        if pause_ms > 0 and (index < len(source_ranges) - 1 or trailing_pause):
            filters.append(
                f"anullsrc=r={sample_rate}:cl={channel_layout},"
                f"atrim=duration={pause_ms / 1000.0:.6f},asetpts=PTS-STARTPTS[p{index}]"
            )
            labels.append(f"[p{index}]")
    filters.append("".join(labels) + f"concat=n={len(labels)}:v=0:a=1[merged]")
    return filters


class _BatchedAudioFeeder:
    """Передаёт PCM небольшими порциями без файла размером со всю книгу."""

    def __init__(self, batches, sink, *, sample_rate, channels, channel_layout, pause_ms, cancelled):
        self.batches = batches
        self.sink = sink
        self.sample_rate = sample_rate
        self.channels = channels
        self.channel_layout = channel_layout
        self.pause_ms = pause_ms
        self.cancelled = cancelled
        self.stop_event = threading.Event()
        self.lock = threading.Lock()
        self.process = None
        self.error = None
        self.thread = threading.Thread(target=self._run, name="audio-batch-decoder", daemon=True)

    def stop(self):
        self.stop_event.set()
        with self.lock:
            if self.process is not None and self.process.poll() is None:
                try:
                    self.process.kill()
                except OSError:
                    pass

    def _check_cancelled(self):
        if self.stop_event.is_set() or (self.cancelled and self.cancelled()):
            raise InterruptedError("Сборка остановлена пользователем")

    def _run(self):
        try:
            for index, batch in enumerate(self.batches):
                self._check_cancelled()
                sources, ranges = zip(*batch)
                command = [get_ffmpeg_path(), "-hide_banner", "-loglevel", "error"]
                command.extend(_ffmpeg_merge_inputs(sources, ranges))
                command.extend([
                    "-filter_complex", ";".join(_ffmpeg_merge_filter(
                        ranges, self.sample_rate, self.channel_layout, self.pause_ms,
                        trailing_pause=index < len(self.batches) - 1,
                    )),
                    "-map", "[merged]", "-vn", "-sn", "-dn",
                    "-c:a", "pcm_f32le", "-f", "f32le",
                    "-ar", str(self.sample_rate), "-ac", str(self.channels), "pipe:1",
                ])
                _validate_windows_command_length(command)
                startupinfo = None
                if platform.system() == "Windows":
                    startupinfo = subprocess.STARTUPINFO()
                    startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
                with tempfile.TemporaryFile() as errors:
                    process = None
                    try:
                        with self.lock:
                            self._check_cancelled()
                            process = subprocess.Popen(
                                command, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                                stderr=errors, startupinfo=startupinfo,
                            )
                            self.process = process
                        while True:
                            self._check_cancelled()
                            chunk = process.stdout.read(256 * 1024)
                            if not chunk:
                                break
                            self.sink.write(chunk)
                        process.wait()
                        self._check_cancelled()
                        if process.returncode != 0:
                            detail = _read_ffmpeg_log(errors).decode("utf-8", errors="replace").strip()
                            raise RuntimeError(
                                f"FFmpeg не смог декодировать фрагменты (порция {index + 1}/{len(self.batches)})"
                                + (f": {detail}" if detail else "")
                            )
                    finally:
                        if process is not None:
                            if process.poll() is None:
                                process.kill()
                            process.wait()
                            process.stdout.close()
                        with self.lock:
                            self.process = None
        except BaseException as exc:
            self.error = exc
        finally:
            try:
                self.sink.close()
            except OSError:
                pass


def _export_merged_audio_ffmpeg(
    audio_files,
    out_path,
    *,
    output_format,
    bitrate=None,
    pause_ms=0,
    speed=1.0,
    pitch=1.0,
    echo=False,
    echo_delay=300,
    echo_decay=0.3,
    tags=None,
    cover=None,
    sample_rate="auto",
    channels="auto",
    bitrate_mode=None,
    cancelled=None,
    _probed_profiles=None,
    faststart=True,
    source_ranges=None,
):
    """Потоково объединяет аудиофайлы через FFmpeg.

    В обычном резервном режиме каждый вход декодируется и приводится к одинаковым
    частоте дискретизации, схеме каналов и формату отсчётов. Поэтому фильтр
    объединения безопасен
    для смеси MP3/WAV/OGG/Opus/M4A и не создаёт единый PCM
    ``AudioSegment``/временный RIFF. Это снимает как расход RAM на всю книгу,
    так и 4-ГиБ лимит WAV-заголовка. Если входы уже однородны и не нужны
    эффекты, паузы или обложка, вместо резервного режима выбирается демультиплексор
    объединения с
    ``-c:a copy`` без повторного кодирования.
    """
    if cancelled and cancelled():
        raise InterruptedError("Сборка остановлена пользователем")
    sources = tuple(Path(path).expanduser().resolve() for path in audio_files)
    if not sources:
        raise ValueError("Нет аудиофайлов для объединения")
    missing = [str(path) for path in sources if not path.is_file()]
    if missing:
        raise FileNotFoundError(missing[0])
    normalized_ranges = _normalize_audio_source_ranges(sources, source_ranges)

    fmt = str(output_format).strip().lower()
    if fmt not in {"mp3", "ogg", "opus", "wav", "m4a", "m4b"}:
        raise ValueError(f"Неподдерживаемый формат экспорта: {fmt}")
    if fmt == "m4b":
        # Проверку оставляем и в общем помощнике, и в экспортёре с главами. Старый
        # компактный экспортёр вызывал эту функцию для M4B напрямую и иначе мог
        # применить скорость, тон или эхо без проверки вызывающей стороны.
        _validate_m4b_effects_disabled(
            speed=speed,
            pitch=pitch,
            echo=echo,
        )
    # Настройки группы могут прийти из импортированного JSON, где пауза бывает
    # дробной строкой. Нормализуем её один раз, чтобы проверка копирования,
    # построение фильтра и запасной путь использовали одно безопасное значение.
    pause_ms = _normalized_pause_milliseconds(pause_ms)

    requested_bitrate = (
        str(bitrate_mode).strip().lower()
        if bitrate_mode is not None
        else str(bitrate or "auto").strip().lower()
    )
    # Пробируем каждый вход один раз: результат нужен и для выбора общего
    # профиля, и для консервативной проверки копирования потока. Повторный ffprobe на
    # больших группах заметно съедал бы выигрыш от быстрой ветки.
    if _probed_profiles is None:
        probed_profiles = []
        for source in sources:
            if cancelled and cancelled():
                raise InterruptedError("Сборка остановлена пользователем")
            probed_profiles.append(_probe_audio_stream_profile(source))
    else:
        probed_profiles = list(_probed_profiles)
        if len(probed_profiles) != len(sources):
            raise ValueError(
                "Внутренняя ошибка: число готовых аудиопрофилей не совпадает"
            )
    merge_profile = _select_merge_audio_profile(
        sources,
        fmt,
        sample_rate=sample_rate,
        channels=channels,
        bitrate=requested_bitrate,
        cancelled=cancelled,
        _probed_profiles=probed_profiles,
    )
    sample_rate = merge_profile["sample_rate"]
    channels = merge_profile["channels"]
    channel_layout = merge_profile["channel_layout"]

    # Копирование потока не умеет добавлять паузы/эффекты и не может менять
    # контейнерный кодек. Все остальные случаи остаются в прежнем
    # filter_complex-пути ниже.
    if not any(normalized_ranges) and _can_concat_stream_copy(
        probed_profiles,
        fmt,
        merge_profile,
        pause_ms=pause_ms,
        speed=speed,
        pitch=pitch,
        echo=echo,
        cover=cover,
        requested_bitrate=requested_bitrate,
        # Некоторые корректные VBR-потоки (особенно Ogg/Opus) не имеют
        # номинального ``bit_rate`` в ffprobe. Если значение неизвестно у
        # каждого входа, stream-copy сохраняет именно исходный VBR-поток;
        # смешанный набор известных и неизвестных значений вспомогательная функция всё равно отклонит.
        allow_unknown_bitrate=True,
    ):
        logging.info(
            "Однородная группа из %d файлов собирается без "
            "перекодирования (%s stream copy).",
            len(sources),
            fmt,
        )
        try:
            return _run_ffmpeg_stream_copy_concat(
                sources,
                out_path,
                tags=tags,
                cancelled=cancelled,
            )
        except RuntimeError as exc:
            # Даже одинаковые заголовки не гарантируют, что конкретный
            # контейнер/файл не имеет редкой временной базы на уровне пакетов или
            # несовместимости. Оптимизация не должна ломать материал, который
            # прежде успешно декодировался: повторяем прежним filter_complex.
            # InterruptedError и ошибки запуска FFmpeg сюда не входят.
            logging.warning(
                "Быстрая склейка без перекодирования не удалась (%s); "
                "повтор через безопасный filter_complex.",
                exc,
            )

    out_path = Path(out_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    temp_path = out_path.with_name(
        f".audio_{uuid.uuid4().hex}.tmp{out_path.suffix}"
    )
    decode_batches = _plan_ffmpeg_decode_batches(sources, normalized_ranges)
    batched_decode = len(decode_batches) > 1
    audio_input_count = 1 if batched_decode else len(sources)
    command = [get_ffmpeg_path(), "-y", "-hide_banner", "-loglevel", "error"]
    if batched_decode:
        # Независимое декодирование сохраняет границы Opus-предложений.
        # PCM передаётся по каналу: размер книги не увеличивает RAM или временный файл.
        command.extend([
            "-f", "f32le", "-ar", str(sample_rate), "-ac", str(channels),
            "-channel_layout", channel_layout, "-i", "pipe:0",
        ])
    else:
        command.extend(_ffmpeg_merge_inputs(sources, normalized_ranges))

    # M4B добавляет обложку на финальном этапе вместе с главами. Обычный
    # M4A получает её здесь как attached picture в MP4-контейнере.
    has_cover = bool(
        fmt in {"mp3", "m4a"} and cover and Path(cover).is_file()
    )
    xiph_metadata_path = (
        _create_xiph_cover_metadata_file(cover, out_path.name)
        if fmt in {"ogg", "opus"}
        else None
    )
    if xiph_metadata_path:
        command.extend(["-f", "ffmetadata", "-i", str(xiph_metadata_path)])
    if has_cover:
        command.extend(["-i", str(Path(cover).resolve())])
    elif cover and Path(cover).is_file() and fmt in {"wav", "m4b"}:
        logging.warning(
            "Обложка пропущена для %s: формат %s не поддерживает JPEG/PNG "
            "attached_pic этим способом.",
            out_path.name,
            fmt,
        )

    filters = _ffmpeg_merge_filter(
        (None,) if batched_decode else normalized_ranges,
        sample_rate, channel_layout, 0 if batched_decode else pause_ms,
    )
    effect_filters = _ffmpeg_audio_effect_filters(
        speed=speed,
        pitch=pitch,
        echo=echo,
        echo_delay=echo_delay,
        echo_decay=echo_decay,
        sample_rate=sample_rate,
    )
    output_label = "merged"
    if effect_filters:
        filters.append(f"[merged]{','.join(effect_filters)}[processed]")
        output_label = "processed"

    command.extend(
        [
            "-filter_complex",
            ";".join(filters),
            "-map",
            f"[{output_label}]",
        ]
    )
    if has_cover:
        cover_codec = (
            "mjpeg" if fmt == "mp3" else _m4b_cover_codec(Path(cover))
        )
        command.extend(
            [
                "-map",
                f"{audio_input_count}:v:0",
                "-c:v",
                cover_codec,
                "-disposition:v:0",
                "attached_pic",
                "-metadata:s:v",
                "title=Album cover",
                "-metadata:s:v",
                "comment=Cover (front)",
            ]
        )
        if fmt == "mp3":
            # ID3v2.3/APIC с JPEG наиболее стабильно отображается в Windows.
            command.extend(["-id3v2_version", "3"])
    else:
        command.extend(["-vn"])
    command.extend(
        ["-sn", "-dn", "-map_metadata", "-1", "-map_chapters", "-1"]
    )

    if fmt == "mp3":
        command.extend([
            "-c:a", "libmp3lame", "-b:a",
            str(merge_profile["bitrate"] or "128k"),
        ])
    elif fmt == "ogg":
        command.extend(["-c:a", "libvorbis"])
        if merge_profile["bitrate"]:
            command.extend(["-b:a", str(merge_profile["bitrate"])])
        else:
            # libvorbis поддерживает 88,2/96 кГц в режиме качества/VBR, но
            # не принимает для них явный номинальный битрейт. Для ``Auto``
            # ``quality=4`` даёт предсказуемый профиль без скрытого понижения частоты дискретизации.
            command.extend(["-q:a", "4"])
    elif fmt == "opus":
        command.extend(["-c:a", "libopus"])
        if merge_profile["bitrate"]:
            command.extend(["-b:a", str(merge_profile["bitrate"])])
    elif fmt in {"m4a", "m4b"}:
        command.extend([
            "-c:a", "aac", "-profile:a", "aac_low",
            "-b:a", str(merge_profile["bitrate"] or "64k"),
            "-f", "ipod",
        ])
        if faststart:
            command.extend(["-movflags", "+faststart"])
    else:
        # Обычный RIFF хранит размеры в 32 битах и перестаёт быть валидным
        # после ~4 ГиБ PCM. FFmpeg сам выберет классический RIFF для короткого
        # результата и RF64 для длинного, поэтому единая потоковая склейка
        # работает и для многотомных книг без прежней ошибки struct '<L'.
        command.extend(["-c:a", "pcm_s16le", "-rf64", "auto"])
    command.extend(["-ar", str(sample_rate), "-ac", str(channels)])
    for key, value in (tags or {}).items():
        if value:
            command.extend(["-metadata", f"{key}={value}"])
    if xiph_metadata_path:
        command.extend(["-map_metadata", str(audio_input_count)])
    command.append(str(temp_path))

    startupinfo = None
    if platform.system() == "Windows":
        startupinfo = subprocess.STARTUPINFO()
        startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW

    process = None
    feeder = None
    try:
        _validate_windows_command_length(command)
        with tempfile.TemporaryFile() as stderr_file:
            if cancelled and cancelled():
                raise InterruptedError("Сборка остановлена пользователем")
            process = subprocess.Popen(
                command,
                stdin=subprocess.PIPE if batched_decode else subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=stderr_file,
                startupinfo=startupinfo,
            )
            if batched_decode:
                feeder = _BatchedAudioFeeder(
                    decode_batches, process.stdin,
                    sample_rate=sample_rate, channels=channels,
                    channel_layout=channel_layout, pause_ms=pause_ms,
                    cancelled=cancelled,
                )
                feeder.thread.start()
            while process.poll() is None:
                if cancelled and cancelled():
                    if feeder is not None:
                        feeder.stop()
                    process.terminate()
                    try:
                        process.wait(timeout=3)
                    except subprocess.TimeoutExpired:
                        process.kill()
                        process.wait()
                    raise InterruptedError("Сборка остановлена пользователем")
                time.sleep(0.05)
            stderr = _read_ffmpeg_log(stderr_file)
            if process.returncode != 0 or not temp_path.is_file():
                detail = stderr.decode("utf-8", errors="ignore").strip()
                raise RuntimeError(
                    "FFmpeg не смог объединить аудиофайлы"
                    + (f": {detail}" if detail else "")
                )
            if feeder is not None:
                feeder.thread.join(timeout=1)
                if feeder.thread.is_alive():
                    raise RuntimeError("FFmpeg завершил кодирование до получения всех фрагментов")
                if feeder.error is not None:
                    raise feeder.error
            # Stop мог прийти одновременно с завершением короткой конвертации.
            # Не заменяем готовый файл после отмены, даже если цикл ожидания
            # уже не увидел работающий процесс.
            if cancelled and cancelled():
                raise InterruptedError("Сборка остановлена пользователем")
            os.replace(temp_path, out_path)
            return out_path
    finally:
        if feeder is not None:
            feeder.stop()
        if process is not None and process.poll() is None:
            process.kill()
            process.wait()
        if feeder is not None:
            feeder.thread.join()
        temp_path.unlink(missing_ok=True)
        if xiph_metadata_path is not None:
            xiph_metadata_path.unlink(missing_ok=True)


def _export_single_audio_ffmpeg(
    source,
    out_path,
    *,
    clip_start=None,
    clip_end=None,
    **kwargs,
):
    """Экспортирует один файл с тем же профилем, что и групповая сборка.

    Отдельный файл не должен обходить выбранные в UI частоту, каналы и режим
    битрейта. Один вход поэтому проходит через тот же ``filter_complex`` и
    потоковый FFmpeg-путь, но без паузы и без промежуточного PCM/WAV.
    """
    source_ranges = None
    if clip_start is not None or clip_end is not None:
        source_ranges = ((clip_start, clip_end),)
    if source_ranges is not None:
        kwargs["source_ranges"] = source_ranges
    return _export_merged_audio_ffmpeg([source], out_path, **kwargs)


def _probe_audio_duration(path):
    """Возвращает длительность аудиопотока в секундах.

    Длительность нужна только для глав M4B и читается отдельным лёгким
    ``ffprobe``-запросом. При ошибке возвращается ``0.0``: FFmpeg всё равно
    создаст звук, а вызывающий код запишет предупреждение о неточной главе.
    """
    startupinfo = None
    if platform.system() == "Windows":
        startupinfo = subprocess.STARTUPINFO()
        startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
    try:
        result = subprocess.run(
            [
                get_ffprobe_path(), "-v", "error", "-select_streams", "a:0",
                "-show_entries", "format=duration:stream=duration",
                "-of", "json", str(Path(path)),
            ],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=30,
            startupinfo=startupinfo,
        )
        data = json.loads(result.stdout or "{}")
        raw = data.get("format", {}).get("duration")
        if raw is None:
            streams = data.get("streams") or []
            raw = streams[0].get("duration") if streams else None
        value = float(raw)
        return value if math.isfinite(value) and value > 0 else 0.0
    except (OSError, subprocess.SubprocessError, TypeError, ValueError,
            KeyError, json.JSONDecodeError):
        return 0.0


def _ffprobe_time_value(value, *, time_base=None):
    """Преобразует время ffprobe в конечное неотрицательное число секунд."""
    try:
        result = float(value)
    except (TypeError, ValueError, OverflowError):
        return None
    if time_base not in (None, ""):
        try:
            numerator, denominator = str(time_base).split("/", 1)
            scale = float(numerator) / float(denominator)
            result *= scale
        except (TypeError, ValueError, ZeroDivisionError):
            return None
    if not math.isfinite(result) or result < 0:
        return None
    return result


def normalize_ffprobe_chapters(probe_data, *, source_name=""):
    """Нормализует главы и метаданные из JSON-ответа ffprobe.

    Временные метки ``start_time``/``end_time`` имеют приоритет над целыми
    значениями в ``time_base``. Отсутствующий конец восстанавливается по началу
    следующей главы или общей длительности контейнера. Пересекающиеся границы
    обрезаются по следующему началу, а пустые диапазоны исключаются из результата.
    Все исправления перечисляются в ``warnings``, чтобы вызывающий код мог
    показать их пользователю или записать в журнал.
    """
    if not isinstance(probe_data, dict):
        raise ValueError("ответ ffprobe должен быть объектом JSON")

    raw_format = probe_data.get("format")
    format_info = copy.deepcopy(raw_format) if isinstance(raw_format, dict) else {}
    raw_streams = probe_data.get("streams")
    streams = copy.deepcopy(raw_streams) if isinstance(raw_streams, list) else []
    has_embedded_cover = any(
        isinstance(stream, dict)
        and stream.get("codec_type") == "video"
        and bool((stream.get("disposition") or {}).get("attached_pic"))
        for stream in streams
    )
    format_duration = _ffprobe_time_value(format_info.get("duration"))
    raw_chapters = probe_data.get("chapters")
    if raw_chapters is None:
        raw_chapters = []
    if not isinstance(raw_chapters, list):
        raise ValueError("поле chapters в ответе ffprobe должно быть списком")

    source_label = f" в {source_name}" if source_name else ""
    warnings_list = []
    parsed = []
    for source_index, raw_chapter in enumerate(raw_chapters, 1):
        if not isinstance(raw_chapter, dict):
            warnings_list.append(
                f"Глава {source_index}{source_label} пропущена: запись не является объектом."
            )
            continue

        time_base = raw_chapter.get("time_base")
        start = _ffprobe_time_value(raw_chapter.get("start_time"))
        if start is None:
            start = _ffprobe_time_value(
                raw_chapter.get("start"), time_base=time_base
            )
        if start is None:
            warnings_list.append(
                f"Глава {source_index}{source_label} пропущена: отсутствует корректное начало."
            )
            continue

        end = _ffprobe_time_value(raw_chapter.get("end_time"))
        if end is None:
            end = _ffprobe_time_value(raw_chapter.get("end"), time_base=time_base)
        tags = raw_chapter.get("tags")
        tags = tags if isinstance(tags, dict) else {}
        tagged_title = next(
            (
                value
                for key, value in tags.items()
                if str(key).casefold() == "title" and value not in (None, "")
            ),
            "",
        )
        title = str(tagged_title or raw_chapter.get("title") or "").strip()
        if not title:
            title = f"Глава {source_index}"
        parsed.append(
            {
                "source_index": source_index,
                "start": start,
                "end": end,
                "title": title,
            }
        )

    ordered = sorted(parsed, key=lambda item: (item["start"], item["source_index"]))
    if ordered != parsed:
        warnings_list.append(
            f"Главы{source_label} были переставлены по времени начала."
        )

    unique = []
    for chapter in ordered:
        if unique and math.isclose(
            chapter["start"], unique[-1]["start"], rel_tol=0.0, abs_tol=1e-9
        ):
            warnings_list.append(
                f"Глава {chapter['source_index']}{source_label} пропущена: "
                "её начало совпадает с предыдущей главой."
            )
            continue
        unique.append(chapter)

    normalized = []
    for position, chapter in enumerate(unique):
        next_start = (
            unique[position + 1]["start"] if position + 1 < len(unique) else None
        )
        end = chapter["end"]
        if end is None or end <= chapter["start"]:
            replacement = next_start if next_start is not None else format_duration
            if replacement is not None and replacement > chapter["start"]:
                end = replacement
                warnings_list.append(
                    f"Конец главы {chapter['source_index']}{source_label} "
                    "восстановлен по соседней границе."
                )
            else:
                warnings_list.append(
                    f"Глава {chapter['source_index']}{source_label} пропущена: "
                    "невозможно определить положительную длительность."
                )
                continue
        if next_start is not None and end > next_start:
            end = next_start
            warnings_list.append(
                f"Конец главы {chapter['source_index']}{source_label} "
                "обрезан по началу следующей главы."
            )
        if format_duration is not None and end > format_duration:
            end = format_duration
            warnings_list.append(
                f"Конец главы {chapter['source_index']}{source_label} "
                "обрезан по длительности файла."
            )
        duration = end - chapter["start"]
        if not math.isfinite(duration) or duration <= 0:
            warnings_list.append(
                f"Глава {chapter['source_index']}{source_label} пропущена: "
                "получился пустой или пересекающийся диапазон."
            )
            continue
        normalized.append(
            {
                "start": chapter["start"],
                "end": end,
                "duration": duration,
                "title": chapter["title"],
            }
        )

    return {
        "chapters": normalized,
        "format": format_info,
        "streams": streams,
        "has_embedded_cover": has_embedded_cover,
        "warnings": warnings_list,
    }


def build_m4b_virtual_export_group(path, probe_result):
    """Строит виртуальную группу экспорта из встроенных глав M4B.

    Все главы ссылаются на один исходный контейнер, но содержат собственные
    ``clip_start``/``clip_end``. В ``cover`` не помещается путь к M4B: текущие
    кодировщики ожидают там уже извлечённый JPEG/PNG. ``cover_source`` хранит
    отложенный источник обложки, если ffprobe обнаружил attached picture.
    """
    if not isinstance(probe_result, dict):
        raise ValueError("результат чтения M4B должен быть объектом")
    source = Path(path)
    source_path = str(source)
    format_info = probe_result.get("format")
    format_info = format_info if isinstance(format_info, dict) else {}

    raw_tags = format_info.get("tags")
    tags = {}
    if isinstance(raw_tags, dict):
        tags.update(
            {
                str(key).casefold(): value
                for key, value in raw_tags.items()
                if value not in (None, "")
            }
        )
    for stream in probe_result.get("streams") or ():
        if not isinstance(stream, dict) or stream.get("codec_type") != "audio":
            continue
        stream_tags = stream.get("tags")
        if isinstance(stream_tags, dict):
            for key, value in stream_tags.items():
                if value not in (None, ""):
                    tags.setdefault(str(key).casefold(), value)

    def tag_value(*names):
        for name in names:
            value = tags.get(name.casefold())
            if value not in (None, ""):
                return str(value).strip()
        return ""

    def volume_pair(*names):
        """Читает пару N/T из тегов disc/track разных контейнеров."""
        for name in names:
            raw = tag_value(name)
            if not raw:
                continue
            match = re.search(r"(?<!\d)(\d+)\s*(?:/|of)\s*(\d+)(?!\d)", raw, re.I)
            if not match:
                match = re.search(r"(?<!\d)(\d+)(?!\d)", raw)
            if not match:
                continue
            try:
                number = int(match.group(1))
                total = int(match.group(2)) if match.lastindex and match.lastindex >= 2 else 0
            except (TypeError, ValueError, OverflowError):
                continue
            if number > 0:
                return number, max(number, total or number)
        return None, None

    metadata = {
        "artist": tag_value("artist", "tpe1"),
        "album": tag_value("album", "talb"),
        "album_artist": tag_value(
            "album_artist", "albumartist", "album artist", "tpe2"
        ),
        "genre": tag_value("genre", "tcon"),
        "composer": tag_value("composer", "tcom"),
        "year": tag_value("date", "year", "tdrc", "tyer", "creation_time"),
        "language": tag_value("language"),
        # В это поле можно безопасно помещать только уже извлечённое изображение.
        "cover": "",
    }
    source_volume_number, source_volume_total = volume_pair(
        "disc", "disk", "track"
    )
    cover_source = (
        source_path if bool(probe_result.get("has_embedded_cover")) else ""
    )
    # Альбом объединяет тома одной книги и поэтому не подходит как уникальное
    # имя группы при пакетном импорте. Название контейнера/файла сохраняет
    # различие томов, а общий альбом остаётся отдельным тегом.
    group_name = tag_value("title") or source.stem or "Аудиокнига"
    group = {
        "name": group_name,
        "source_name": source.stem or group_name,
        "source_title": tag_value("title") or group_name,
        # Импорт глав предназначен прежде всего для раздельной выгрузки. Цель
        # M4B всё равно объединяет выбранные главы независимо от этого флага.
        "merge": False,
        "subfolder": True,
        "pause": 0,
        "source_path": source_path,
        "source_kind": "m4b_chapters",
        "cover_source": cover_source,
        # Сохраняем исходную пару тома, чтобы разбор нескольких M4B не
        # зависел от порядка выбора файлов в диалоге.
        "source_volume_number": source_volume_number,
        "source_volume_total": source_volume_total,
        **metadata,
    }

    raw_chapters = probe_result.get("chapters")
    if not isinstance(raw_chapters, list):
        raise ValueError("результат чтения M4B не содержит списка глав")
    chapters = []
    for chapter_index, chapter in enumerate(raw_chapters, 1):
        if not isinstance(chapter, dict):
            raise ValueError(f"глава {chapter_index} должна быть объектом")
        try:
            start = float(chapter.get("start"))
            end = float(chapter.get("end"))
            duration = float(chapter.get("duration", end - start))
        except (TypeError, ValueError, OverflowError):
            raise ValueError(
                f"глава {chapter_index} содержит некорректные временные границы"
            ) from None
        if (
            not math.isfinite(start)
            or not math.isfinite(end)
            or not math.isfinite(duration)
            or start < 0
            or end <= start
            or duration <= 0
        ):
            raise ValueError(
                f"глава {chapter_index} содержит некорректные временные границы"
            )
        title = str(chapter.get("title") or f"Глава {chapter_index}").strip()
        item = {
            "path": source_path,
            "source_name": source.stem or group_name,
            "source_filename": source.name or f"{group_name}.m4b",
            "source_title": title or f"Глава {chapter_index}",
            "clip_start": start,
            "clip_end": end,
            "duration": duration,
            "title": title or f"Глава {chapter_index}",
            "chapter_index": chapter_index,
            "file_index": chapter_index,
            "source_volume_number": source_volume_number,
            "source_volume_total": source_volume_total,
            "cover_source": cover_source,
            **metadata,
        }
        chapters.append(item)

    return {
        "group": group,
        "chapters": chapters,
        "warnings": list(probe_result.get("warnings") or ()),
    }


def probe_m4b_chapters(path, *, timeout=30):
    """Читает встроенные главы M4B и метаданные контейнера через ffprobe."""
    source = Path(path)
    startupinfo = None
    if platform.system() == "Windows":
        startupinfo = subprocess.STARTUPINFO()
        startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
    command = [
        get_ffprobe_path(),
        "-v", "error",
        "-print_format", "json",
        "-show_format",
        "-show_chapters",
        "-show_streams",
        str(source),
    ]
    # FFprobe выводит JSON в UTF-8 независимо от системной кодировки Windows.
    try:
        result = subprocess.run(
            command,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout,
            startupinfo=startupinfo,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        detail = str(getattr(exc, "stderr", "") or exc).strip()
        raise RuntimeError(
            f"FFprobe не смог прочитать главы {source.name}: {detail}"
        ) from exc
    try:
        probe_data = json.loads(result.stdout or "{}")
    except (TypeError, json.JSONDecodeError) as exc:
        raise RuntimeError(
            f"FFprobe вернул некорректные данные для {source.name}."
        ) from exc
    return normalize_ffprobe_chapters(probe_data, source_name=source.name)


def _run_ffmpeg_checked(command, *, out_path=None, cancelled=None,
                        error_prefix="FFmpeg не смог создать файл",
                        progress_callback=None):
    """Запускает FFmpeg с отменой и общей диагностикой для M4B/экспорта."""
    if cancelled and cancelled():
        raise InterruptedError("Сборка остановлена пользователем")
    startupinfo = None
    if platform.system() == "Windows":
        startupinfo = subprocess.STARTUPINFO()
        startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
    _validate_windows_command_length(command)

    # ``ffmpeg`` не сообщает полезный процент для финального шага метаданных и
    # перепаковки MP4 без машинного протокола ``-progress``. Оставляем публичный
    # помощник лёгким: вызывающий код может получать примерный сигнал активности
    # пока процесс работает. ``progress_callback`` необязателен и не должен
    # менять исторический контракт отмены и ошибок.
    def notify_progress():
        if progress_callback is None:
            return
        try:
            progress_callback(-1, 1, "Сборка контейнера…")
        except Exception:
            logging.debug("Не удалось обновить прогресс FFmpeg", exc_info=True)

    process = None
    stderr_reader = None
    stderr_chunks = []
    try:
        process = subprocess.Popen(
            [str(part) for part in command],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.PIPE,
            startupinfo=startupinfo,
        )
        if process.stderr is not None:
            def drain_stderr():
                try:
                    stderr_chunks.append(process.stderr.read())
                except Exception:
                    stderr_chunks.append(b"")

            stderr_reader = threading.Thread(
                target=drain_stderr,
                name="ffmpeg-stderr-reader",
                daemon=True,
            )
            stderr_reader.start()
        # Сообщаем сразу, чтобы долгая перепаковка не оставляла интерфейс на
        # прежнем состоянии ожидания (обычно 0%/«Ожидание»).
        notify_progress()
        last_progress_notify = time.monotonic()
        while process.poll() is None:
            # Короткий сигнал активности поддерживает неопределённую полосу Tk
            # при очень большой перепаковке M4B. Не вызываем обработчик каждые
            # 50 мс: он может поставить слишком много задач в поток Tk.
            now = time.monotonic()
            if progress_callback is not None and now - last_progress_notify >= 0.5:
                notify_progress()
                last_progress_notify = now
            if cancelled and cancelled():
                process.terminate()
                try:
                    process.wait(timeout=3)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait()
                raise InterruptedError("Сборка остановлена пользователем")
            time.sleep(0.05)
        if stderr_reader is not None:
            stderr_reader.join()
        stderr = b"".join(stderr_chunks)
        if process.stderr:
            process.stderr.close()
        if cancelled and cancelled():
            raise InterruptedError("Сборка остановлена пользователем")
        if process.returncode != 0 or (
            out_path is not None and not Path(out_path).is_file()
        ):
            detail = stderr.decode("utf-8", errors="ignore").strip()
            raise RuntimeError(error_prefix + (f": {detail}" if detail else ""))
        return stderr
    finally:
        if process is not None and process.poll() is None:
            process.kill()
            process.wait()
        if stderr_reader is not None and stderr_reader.is_alive():
            stderr_reader.join(timeout=1)
        if process is not None and process.stderr is not None:
            process.stderr.close()


def _export_m4b_ffmpeg(
    audio_files,
    out_path,
    *,
    chapters=None,
    bitrate="64k",
    sample_rate=48000,
    channels=1,
    pause_ms=0,
    speed=1.0,
    pitch=1.0,
    echo=False,
    echo_delay=300,
    echo_decay=0.3,
    tags=None,
    cover=None,
    disk_number=None,
    disk_total=None,
    track_number=None,
    track_total=None,
    include_track_metadata=True,
    language=None,
    cancelled=None,
    max_duration_warning_seconds=23 * 3600,
    progress_callback=None,
    preencoded_audio=None,
    source_ranges=None,
):
    """Создаёт M4B с AAC-LC, главами, тегами и необязательной обложкой.

    ``include_track_metadata`` управляет только необязательным атомом MP4
    ``trkn``; метки глав и пара тома ``disc`` при этом не удаляются.

    Обычно входные файлы сначала сводятся во временный M4A той же потоковой
    вспомогательной функцией, что и обычная сборка. Для фоновой подготовки
    ``preencoded_audio`` может передать уже готовую AAC-основу. Затем отдельное
    перемультиплексирование добавляет ``ffmetadata`` с
    главами и прикреплённой обложкой, поэтому MP4/M4B получает корректную структуру
    даже при PNG-обложке. Временные имена находятся рядом с целью, а публикация
    результата выполняется атомарно.
    """
    sources = tuple(Path(path).expanduser().resolve() for path in audio_files)
    if not sources:
        raise ValueError("Нет аудиофайлов для M4B")
    normalized_ranges = _normalize_audio_source_ranges(sources, source_ranges)
    m4b_language = normalize_m4b_audio_language(
        language or (tags or {}).get("language")
    )
    _validate_m4b_effects_disabled(
        speed=speed,
        pitch=pitch,
        echo=echo,
    )
    # Низкоуровневый помощник принимает те же обозначения каналов, что и
    # аудиопрофили. Интерфейс обычно уже превращает ``auto`` в mono, но прямые
    # интеграции могут передать его как есть. M4B по умолчанию строится из
    # канонического моно-кэша TTS, поэтому ``auto`` следует этой политике, а не
    # доходит до ``int("auto")`` на этапе AAC.
    channel_mode = str(channels).strip().lower()
    if channel_mode in {"auto", "mono", "1"}:
        m4b_channels = 1
    elif channel_mode in {"stereo", "2"}:
        m4b_channels = 2
    else:
        raise ValueError(
            "Некорректный режим каналов M4B: выберите auto, mono или stereo."
        )

    def notify_progress(current, total, text):
        """Безопасно сообщает стадии сборки M4B внешнему UI.

        ``current``/``total`` — укрупнённые единицы (проверка глав, кодирование
        и перепаковка), а не процент по байтам. ``current == -1`` означает
        неопределённую операцию; интерфейс может анимировать полосу во время
        работы FFmpeg. Обратный вызов намеренно необязателен: устаревшее или закрытое
        окно Tk не должно ломать корректный M4B.
        """
        if progress_callback is None:
            return
        try:
            progress_callback(current, total, str(text or "Сборка M4B…"))
        except Exception:
            logging.debug("Не удалось обновить прогресс M4B", exc_info=True)

    # Две последние единицы — потенциально долгие кодирование AAC и перепаковка
    # MP4. Проверка глав быстрая, но даёт видимую активность при работе только с
    # кэшем или исходниками, когда API обратного вызова не используется.
    progress_total = max(1, len(sources) + 2)
    notify_progress(0, progress_total, "M4B: подготовка глав…")
    # Прямые вызовы помощника используют тот же целочисленный контракт в
    # миллисекундах, что планировщик и фоновый обработчик (в импортированном JSON бывают
    # дробные строки).
    pause_ms = _normalized_pause_milliseconds(pause_ms)
    missing = [str(path) for path in sources if not path.is_file()]
    if missing:
        raise FileNotFoundError(missing[0])
    out_path = Path(out_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)

    # Измеряем длительности один раз. Явные длительности глав от вызывающего
    # кода имеют приоритет, а пропущенные значения берутся из файлов.
    chapter_items = []
    supplied = list(chapters or ())
    for index, (source, source_range) in enumerate(
        zip(sources, normalized_ranges), 1
    ):
        if cancelled and cancelled():
            raise InterruptedError("Сборка остановлена пользователем")
        item = supplied[index - 1] if index <= len(supplied) else None
        if isinstance(item, dict):
            chapter = copy.deepcopy(item)
            title = str(chapter.get("title") or source.stem)
            try:
                duration = float(chapter.get("duration", 0) or 0)
            except (TypeError, ValueError, OverflowError):
                duration = 0.0
        elif item is not None:
            try:
                title, duration = item
            except (TypeError, ValueError):
                title, duration = source.stem, 0
            title = str(title or source.stem)
            try:
                duration = float(duration or 0)
            except (TypeError, ValueError, OverflowError):
                duration = 0.0
            chapter = {"title": title}
        else:
            title, duration = source.stem, 0
            chapter = {"title": title}
        if not math.isfinite(duration) or duration <= 0:
            duration = 0.0
        if duration <= 0:
            duration = (
                source_range[1] - source_range[0]
                if source_range is not None
                else _probe_audio_duration(source)
            )
        if duration <= 0:
            logging.warning(
                "Не удалось определить длительность главы %s; главы M4B "
                "могут иметь неточную границу.", source.name,
            )
        chapter["title"] = title
        chapter["duration"] = max(0.001, duration)
        chapter_items.append(chapter)
        notify_progress(
            index,
            progress_total,
            f"M4B: подготовка главы {index}/{len(sources)}…",
        )

    # Общий помощник вставляет паузу между файлами. Метаданные глав MP4 не
    # умеют надёжно представить зазор между соседними главами: мультиплексоры
    # обычно продлевают предыдущую главу до следующего START. Поэтому ниже
    # учитываем паузу в END предыдущей главы, как её видят проигрыватели и
    # ffprobe, а не создаём мнимый зазор, который перепаковка переназначит.
    m4b_duration = sum(float(item["duration"]) for item in chapter_items)
    m4b_duration += max(0, len(chapter_items) - 1) * max(0, int(pause_ms)) / 1000
    if max_duration_warning_seconds and m4b_duration > max_duration_warning_seconds:
        logging.warning(
            "M4B %s длительностью %.1f ч превышает рекомендуемый предел %.1f ч; "
            "для Apple Books лучше включить разбиение на части.",
            out_path.name, m4b_duration / 3600,
            max_duration_warning_seconds / 3600,
        )

    temp_m4a = None
    if preencoded_audio is None:
        # Длинное имя книги не дублируется во вложенных временных именах:
        # этап M4A создаёт собственный временный файл в том же каталоге.
        temp_m4a = out_path.with_name(
            f".m4b_{uuid.uuid4().hex}.stage.m4a"
        )
        encoded_audio = temp_m4a
    else:
        encoded_audio = Path(preencoded_audio).expanduser().resolve()
        if not encoded_audio.is_file():
            raise FileNotFoundError(
                f"Временная AAC-основа M4B не найдена: {encoded_audio}"
            )
    metadata_path = out_path.with_name(
        f".m4b_{uuid.uuid4().hex}.ffmeta"
    )
    temp_out = out_path.with_name(
        f".m4b_{uuid.uuid4().hex}.tmp{out_path.suffix or '.m4b'}"
    )
    try:
        if temp_m4a is not None:
            # Кодирование может занять гораздо больше времени, чем проверка.
            # Переключаем полосу в неопределённый режим и поддерживаем сигнал от
            # проверенного процесса FFmpeg; так лучше, чем застывшие 0%.
            notify_progress(
                -1,
                progress_total,
                f"M4B: кодирование аудио ({len(sources)} глав)…",
            )
            _export_merged_audio_ffmpeg(
                sources,
                encoded_audio,
                output_format="m4a",
                bitrate=bitrate,
                bitrate_mode=bitrate or "auto",
                sample_rate=str(sample_rate),
                channels=("stereo" if m4b_channels == 2 else "mono"),
                pause_ms=pause_ms,
                speed=speed,
                pitch=pitch,
                echo=echo,
                echo_delay=echo_delay,
                echo_decay=echo_decay,
                tags=None,
                cover=None,
                cancelled=cancelled,
                source_ranges=normalized_ranges,
                # Промежуточный файл сразу читается при финальном
                # перемультиплексировании M4B. ``faststart`` здесь только
                # удвоил бы ввод-вывод; он остаётся у конечного файла.
                faststart=False,
            )
        else:
            notify_progress(
                len(sources) + 1,
                progress_total,
                "M4B: применение итоговых глав и тегов…",
            )
        notify_progress(
            len(sources) + 1,
            progress_total,
            "M4B: добавление глав и тегов…",
        )
        # Строим временную шкалу глав с точной настроенной паузой между файлами.
        # Конец последней главы всегда не меньше одной миллисекунды.
        timeline = []
        cursor = 0.0
        pause_seconds = max(0, int(pause_ms)) / 1000.0
        for index, item in enumerate(chapter_items):
            start = cursor
            end = start + float(item["duration"])
            if index < len(chapter_items) - 1:
                end += pause_seconds
            timeline.append({"title": item["title"], "start": start, "end": end})
            cursor = end
        ffmetadata_tags = dict(tags or {})
        # ``disk`` — имя атома QuickTime, а не ключ метаданных FFmpeg. Если
        # импортированный словарь тегов содержит такое написание, удаляем его
        # при наличии авторитетной числовой пары тома, чтобы оно не затмило и не
        # запутало каноническое ``disc`` ниже.
        ffmetadata_tags.pop("disk", None)
        ffmetadata_tags.update(
            m4b_volume_metadata(
                disk_number,
                disk_total,
                track_number=track_number,
                track_total=track_total,
                include_track=include_track_metadata,
            )
        )
        metadata_path.write_text(
            build_ffmetadata_chapters(timeline, metadata=ffmetadata_tags),
            encoding="utf-8",
        )

        command = [
            get_ffmpeg_path(), "-y", "-hide_banner", "-loglevel", "error",
            "-i", str(encoded_audio), "-f", "ffmetadata", "-i", str(metadata_path),
        ]
        cover_path = Path(cover).expanduser() if cover else None
        if cover_path and cover_path.is_file():
            # Каждый входной адрес должен идти до параметров вывода. Если
            # добавить этот ``-i`` после ``-map``, FFmpeg сочтёт следующие
            # параметры входными; на некоторых сборках это приводит к ошибке.
            command.extend(["-i", str(cover_path.resolve())])
        elif cover:
            logging.warning("Обложка M4B не найдена: %s", cover)
        command.extend([
            "-map", "0:a:0", "-map_metadata", "1", "-map_chapters", "1",
            "-c:a", "copy",
            "-sn", "-dn", "-f", "ipod", "-brand", "M4B ",
            "-metadata", "media_type=2",
            "-metadata:s:a:0", f"language={m4b_language}",
            "-movflags", "+faststart",
        ])
        if cover_path and cover_path.is_file():
            command.extend([
                "-map", "2:v:0", "-c:v", _m4b_cover_codec(cover_path),
                "-disposition:v:0", "attached_pic",
            ])
        else:
            command.extend(["-vn"])
        metadata_tags = dict(ffmetadata_tags)
        # Мультиплексор MOV FFmpeg записывает атом iTunes ``disk`` из
        # канонического ключа ``disc``. Не добавляем буквальный алиас ``disk``:
        # MOV его игнорирует, а числовая строка ``N/T`` в ``disc`` правильно
        # сериализуется в атом QuickTime.
        for key, value in metadata_tags.items():
            if value not in (None, ""):
                command.extend(["-metadata", f"{key}={value}"])
        command.append(str(temp_out))
        checked_kwargs = {
            "out_path": temp_out,
            "cancelled": cancelled,
            "error_prefix": "FFmpeg не смог создать M4B",
        }
        # Не передаём новый именованный аргумент старым интеграциям и внешним
        # подменам, если отчёт о прогрессе не запрошен. Так сохраняется полная
        # совместимость прежнего контракта
        # `_run_ffmpeg_checked(command, out_path=..., cancelled=...)`, а новый
        # путь интерфейса получает расширенный статус.
        if progress_callback is not None:
            checked_kwargs["progress_callback"] = (
                lambda _current, _total, text: notify_progress(
                    -1, progress_total, f"M4B: {text}"
                )
            )
        _run_ffmpeg_checked(command, **checked_kwargs)
        if cancelled and cancelled():
            raise InterruptedError("Сборка остановлена пользователем")
        os.replace(temp_out, out_path)
        notify_progress(progress_total, progress_total, "M4B: готово")
        return out_path
    finally:
        if temp_m4a is not None:
            temp_m4a.unlink(missing_ok=True)
        metadata_path.unlink(missing_ok=True)
        temp_out.unlink(missing_ok=True)


def _prepare_api_audio_file(
    source_path,
    destination_path,
    *,
    trim_silence=True,
    silence_threshold=-55.0,
):
    """Приводит ответ API к единому Ogg/Opus 48 кГц, моно.

    При выключенной обрезке уже совместимый ответ EnhancedTTS публикуется без
    повторного кодирования с потерями. Если требуется обрезка либо сервер вернул
    другой кодек/параметры, результат атомарно кодируется в Opus 48 кбит/с.
    """
    source_path = Path(source_path)
    destination_path = Path(destination_path)
    source_codec, source_channels = _inspect_ogg_audio_header(source_path)

    # Opus сам декодируется в 48 кГц, но число каналов берётся из OpusHead.
    # Поэтому без повторного кодирования с потерями можно публиковать только уже
    # канонический монофонический ответ. Неожиданный стереофонический или
    # многоканальный Opus проходит обычные декодирование, сведение каналов и
    # кодирование ниже, даже когда автообрезка выключена.
    if (
        not trim_silence
        and source_codec == CACHE_AUDIO_CODEC
        and source_channels == CACHE_AUDIO_CHANNELS
    ):
        destination_path.parent.mkdir(parents=True, exist_ok=True)
        if source_path.resolve() == destination_path.resolve():
            return destination_path
        temp_path = destination_path.with_name(
            f".{destination_path.stem}.{uuid.uuid4().hex}.tmp{destination_path.suffix}"
        )
        try:
            shutil.copyfile(source_path, temp_path)
            _require_opus_audio_file(temp_path)
            os.replace(temp_path, destination_path)
            return destination_path
        finally:
            temp_path.unlink(missing_ok=True)

    audio_segment = _load_audio_segment(source_path, known_codec=source_codec)
    prepared_segment = audio_segment

    if trim_silence:
        nonsilent_ranges = detect_nonsilent(
            audio_segment,
            min_silence_len=50,
            silence_thresh=float(silence_threshold),
        )
        if nonsilent_ranges:
            start_trim = max(0, nonsilent_ranges[0][0] - 20)
            end_trim = min(len(audio_segment), nonsilent_ranges[-1][1] + 20)
            prepared_segment = audio_segment[start_trim:end_trim]

    prepared_segment = prepared_segment.set_frame_rate(
        CACHE_AUDIO_SAMPLE_RATE
    ).set_channels(CACHE_AUDIO_CHANNELS)
    result_path = _export_audio_atomic(
        prepared_segment,
        destination_path,
        format="ogg",
        codec=CACHE_AUDIO_FFMPEG_CODEC,
        bitrate=CACHE_AUDIO_BITRATE,
        parameters=[
            "-vbr", "on",
            "-compression_level", "10",
            "-application", "audio",
        ],
    )
    _require_opus_audio_file(result_path)
    return result_path


def _inspect_ogg_audio_header_details(path):
    """Читает кодек, каналы и идентификационный пакет Ogg.

    Разбор сигнатуры захвата и таблицы сегментов не позволяет случайной строке
    ``OpusHead`` в комментариях или аудиоданных выдать повреждённый/другой Ogg
    за канонический внутренний фрагмент. Читаются только первые 4 КиБ. Число
    каналов нужно для безопасного быстрого пути с побайтовым копированием ответа
    API: сам контейнер Opus всегда декодируется в 48 кГц, но может быть не
    монофоническим.
    """
    try:
        with open(path, "rb") as audio_file:
            header = audio_file.read(4096)
    except OSError:
        return None, None, None

    if len(header) < 27 or header[:4] != b"OggS" or header[4] != 0:
        return None, None, None
    segment_count = header[26]
    segment_table_end = 27 + segment_count
    if len(header) < segment_table_end:
        return None, None, None

    first_packet_size = 0
    packet_complete = False
    for lace_value in header[27:segment_table_end]:
        first_packet_size += lace_value
        if lace_value < 255:
            packet_complete = True
            break
    packet_end = segment_table_end + first_packet_size
    if not packet_complete or packet_end > len(header):
        return None, None, None

    first_packet = header[segment_table_end:packet_end]
    if first_packet.startswith(b"OpusHead"):
        channels = first_packet[9] if len(first_packet) >= 10 else None
        return "opus", channels if channels else None, first_packet
    if first_packet.startswith(b"\x01vorbis"):
        channels = first_packet[11] if len(first_packet) >= 12 else None
        return "vorbis", channels if channels else None, first_packet
    return None, None, None


def _inspect_ogg_audio_header(path):
    """Читает кодек и число каналов из идентификационного пакета Ogg."""
    codec, channels, _identity_packet = _inspect_ogg_audio_header_details(path)
    return codec, channels


def _detect_ogg_audio_codec(path):
    """Быстро определяет Opus/Vorbis по идентификационному пакету Ogg."""
    codec, _channels = _inspect_ogg_audio_header(path)
    return codec


def _require_opus_audio_file(path):
    """Проверяет физический кодек внутреннего фрагмента перед публикацией."""
    path = Path(path)
    codec = _detect_ogg_audio_codec(path)
    if codec != CACHE_AUDIO_CODEC:
        raise ValueError(
            f"Внутренний фрагмент {path.name} должен быть Ogg/Opus, "
            f"найден {codec or 'неизвестный/повреждённый формат'}"
        )
    return path


def _inspect_opus_audio_files(paths):
    """Проверяет кодек всех фрагментов кэша одним чтением их заголовков.

    Возвращает ``(пути, canonical)``. Для быстрого копирования нужны моно и одинаковый
    полный OpusHead (включая ``pre-skip``, ``gain`` и ``mapping family``).
    Немонофонический либо отличающийся Opus остаётся допустимым для прежней
    ветки кодирования, которая безопасно выполнит сведение каналов и нормализацию.
    """
    verified = tuple(Path(path) for path in paths)
    canonical = True
    identity_packet = None
    for path in verified:
        codec, channels, current_identity = _inspect_ogg_audio_header_details(path)
        if codec != CACHE_AUDIO_CODEC:
            raise ValueError(
                f"Внутренний фрагмент {path.name} должен быть Ogg/Opus, "
                f"найден {codec or 'неизвестный/повреждённый формат'}"
            )
        if identity_packet is None:
            identity_packet = current_identity
        canonical = (
            canonical
            and channels == CACHE_AUDIO_CHANNELS
            and current_identity is not None
            and current_identity == identity_packet
        )
    return verified, canonical


def _require_opus_audio_files(paths):
    """Не допускает смешанный Vorbis/Opus в concat внутреннего кэша."""
    verified, _canonical = _inspect_opus_audio_files(paths)
    return verified


def _load_audio_segment(path, *, known_codec=None):
    """Декодирует известный Ogg без отдельного запуска FFprobe.

    FFmpeg сам читает контейнер, а явный decoder позволяет Pydub не вызывать
    ``mediainfo_json``. Чтение Vorbis здесь предназначено для переноса старых
    данных, предпрослушивания и пользовательских файлов; внутреннее объединение принимает
    только уже канонизированный Opus. Для прочих форматов сохраняется обычное
    автоопределение.
    """
    path = Path(path)
    codec = str(known_codec or "").strip().lower()
    if not codec and path.suffix.lower() in {".ogg", ".oga", ".opus"}:
        codec = _detect_ogg_audio_codec(path) or ""
    if codec in {"opus", "vorbis"}:
        return AudioSegment.from_file(path, format="ogg", codec=codec)
    return AudioSegment.from_file(path)


def _cache_file_identity(path):
    """Возвращает признаки конкретной опубликованной версии cache-файла."""
    stat_result = Path(path).stat()
    return (
        stat_result.st_dev,
        stat_result.st_ino,
        stat_result.st_size,
        stat_result.st_mtime_ns,
    )


def _allocated_file_size(path):
    """Возвращает реально выделенный размер, где его сообщает ОС."""
    stat_result = Path(path).stat()
    blocks = getattr(stat_result, "st_blocks", 0)
    return blocks * 512 if blocks else stat_result.st_size


def _transcode_cache_audio_to_opus(path, publish_lock=None):
    """Атомарно перекодирует один Vorbis-фрагмент в канонический Ogg/Opus.

    Возвращает ``(status, old_size, new_size, old_allocated, new_allocated)``.
    При параллельной замене файла устаревший результат никогда не публикуется
    поверх новой версии.
    """
    path = Path(path)
    codec = _detect_ogg_audio_codec(path)
    old_size = path.stat().st_size
    old_allocated = _allocated_file_size(path)
    if codec == CACHE_AUDIO_CODEC:
        return (
            "already_opus",
            old_size,
            old_size,
            old_allocated,
            old_allocated,
        )
    if codec != "vorbis":
        raise ValueError(
            f"Ожидался Ogg/Vorbis, найден {codec or 'неизвестный формат'}"
        )

    source_identity = _cache_file_identity(path)
    converted_path = path.with_name(
        f".{path.stem}.{uuid.uuid4().hex}.opus{path.suffix}"
    )
    try:
        startupinfo = None
        if platform.system() == "Windows":
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
        result = subprocess.run(
            [
                get_ffmpeg_path(),
                "-y", "-v", "error",
                "-i", str(path),
                "-map", "0:a:0", "-vn", "-sn", "-dn",
                "-map_metadata", "-1",
                "-ar", str(CACHE_AUDIO_SAMPLE_RATE),
                "-ac", str(CACHE_AUDIO_CHANNELS),
                "-c:a", CACHE_AUDIO_FFMPEG_CODEC,
                "-b:a", CACHE_AUDIO_BITRATE,
                "-vbr", "on",
                "-compression_level", "10",
                "-application", "audio",
                "-threads", "1",
                str(converted_path),
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.PIPE,
            startupinfo=startupinfo,
        )
        if (
            result.returncode != 0
            or not converted_path.is_file()
            or converted_path.stat().st_size <= 0
            or _detect_ogg_audio_codec(converted_path) != CACHE_AUDIO_CODEC
        ):
            details = (
                result.stderr.decode("utf-8", errors="replace").strip()
                if result.stderr
                else ""
            )
            raise RuntimeError(
                details or "FFmpeg не создал корректный Ogg/Opus"
            )
        new_size = converted_path.stat().st_size
        new_allocated = _allocated_file_size(converted_path)

        def publish_if_unchanged():
            if _cache_file_identity(path) != source_identity:
                current_codec = _detect_ogg_audio_codec(path)
                if current_codec == CACHE_AUDIO_CODEC:
                    return (
                        "changed_to_opus",
                        old_size,
                        path.stat().st_size,
                        old_allocated,
                        _allocated_file_size(path),
                    )
                raise RuntimeError(
                    f"Файл {path.name} изменился во время перекодирования"
                )
            os.replace(converted_path, path)
            return (
                "converted",
                old_size,
                new_size,
                old_allocated,
                new_allocated,
            )

        if publish_lock is None:
            return publish_if_unchanged()
        with publish_lock:
            return publish_if_unchanged()
    finally:
        converted_path.unlink(missing_ok=True)


def transcode_cache_entries_to_opus(
    cache_dir,
    cache_data,
    *,
    cancel_event=None,
    max_workers=None,
    progress_callback=None,
    checkpoint_callback=None,
    checkpoint_every=None,
):
    """Перекодирует все безопасные уникальные файлы кэша и меняет метаданные.

    Индекс на диск не записывает: вызывающий код публикует его один раз после
    завершения файлов. Это делает функцию пригодной и для GUI, и для тестов.
    """
    cache_dir = Path(cache_dir)
    cancel_event = cancel_event or threading.Event()
    if max_workers is None:
        # Каждый FFmpeg ниже принудительно однопоточный. На больших кэшах
        # выгодно запускать до 24 коротких процессов параллельно; выше на M5 Max
        # прироста уже не было, а на слабых машинах предел автоматически ниже.
        max_workers = max(1, min(24, os.cpu_count() or 1))
    else:
        max_workers = max(1, int(max_workers))
    if checkpoint_every is not None:
        checkpoint_every = max(1, int(checkpoint_every))

    stats = {
        "converted": 0,
        "already_opus": 0,
        "missing": 0,
        "failed": 0,
        "old_size": 0,
        "new_size": 0,
        "old_allocated": 0,
        "new_allocated": 0,
        "cancelled": False,
        "index_changed": False,
        "index_dirty": False,
        "errors": [],
    }
    file_entries = []
    keys_by_path = {}
    for cache_key, cache_info in cache_data.items():
        if not isinstance(cache_info, dict):
            stats["failed"] += 1
            stats["errors"].append((str(cache_key), "некорректные метаданные"))
            continue
        filepath = resolve_cache_audio_path(
            cache_dir, cache_info.get("file_name", "")
        )
        if filepath is None:
            stats["failed"] += 1
            stats["errors"].append((str(cache_key), "небезопасный путь"))
            continue
        if filepath in keys_by_path:
            keys_by_path[filepath].append(cache_key)
            continue
        keys_by_path[filepath] = [cache_key]
        file_entries.append((cache_key, filepath))

    total = len(file_entries)
    completed = 0
    if progress_callback:
        progress_callback(completed, total, stats)
    iterator = iter(file_entries)
    pending = {}

    def submit_next(executor):
        if cancel_event.is_set():
            return False
        try:
            cache_key, filepath = next(iterator)
        except StopIteration:
            return False
        if not filepath.is_file():
            future = executor.submit(lambda: ("missing", None))
        else:
            future = executor.submit(_transcode_cache_audio_to_opus, filepath)
        pending[future] = (cache_key, filepath)
        return True

    with concurrent.futures.ThreadPoolExecutor(
        max_workers=max_workers,
        thread_name_prefix="cache-opus",
    ) as executor:
        # В очереди не держим больше одной задачи на обработчик: после остановки должны
        # завершиться только реально работающие FFmpeg, а не скрытый запас.
        for _ in range(max_workers):
            if not submit_next(executor):
                break

        while pending:
            done_futures, _ = concurrent.futures.wait(
                pending,
                return_when=concurrent.futures.FIRST_COMPLETED,
            )
            for future in done_futures:
                cache_key, filepath = pending.pop(future)
                completed += 1
                try:
                    result = future.result()
                    if result[0] == "missing":
                        stats["missing"] += 1
                    else:
                        (
                            status,
                            old_size,
                            new_size,
                            old_allocated,
                            new_allocated,
                        ) = result
                        stats["old_size"] += old_size
                        stats["new_size"] += new_size
                        stats["old_allocated"] += old_allocated
                        stats["new_allocated"] += new_allocated
                        if status in {"converted", "changed_to_opus"}:
                            stats["converted"] += 1
                        else:
                            stats["already_opus"] += 1
                        for referenced_key in keys_by_path.get(
                            filepath, (cache_key,)
                        ):
                            cache_info = cache_data.get(referenced_key)
                            if (
                                isinstance(cache_info, dict)
                                and cache_info.get("audio_codec")
                                != CACHE_AUDIO_CODEC
                            ):
                                cache_info["audio_codec"] = CACHE_AUDIO_CODEC
                                stats["index_changed"] = True
                                stats["index_dirty"] = True
                except Exception as exc:
                    stats["failed"] += 1
                    stats["errors"].append((str(filepath), str(exc)))

                if progress_callback and (
                    completed == total or completed % 100 == 0
                ):
                    progress_callback(completed, total, stats)
                if (
                    checkpoint_callback
                    and checkpoint_every is not None
                    and stats["index_dirty"]
                    and completed % checkpoint_every == 0
                ):
                    checkpoint_callback(cache_data)
                    stats["index_dirty"] = False
                if not cancel_event.is_set():
                    submit_next(executor)

            if cancel_event.is_set():
                stats["cancelled"] = completed < total

    if completed < total:
        stats["cancelled"] = True
    if checkpoint_callback and stats["index_dirty"]:
        checkpoint_callback(cache_data)
        stats["index_dirty"] = False
    return stats


def _canonicalize_cached_audio_if_needed(
    path,
    known_codec=None,
    publish_lock=None,
):
    """Лениво приводит найденный в кэше старый Vorbis к Opus для безопасной склейки.

    Для быстрой пересборки большого старого кэша лучше заранее запустить
    массовую миграцию во вкладке «Кэш». Этот резервный путь гарантирует корректность
    смешанного/частично мигрированного кэша и никогда не меняет уже готовый Opus.
    """
    path = Path(path)
    # Заголовок является источником истины: метаданные индекса могут отставать,
    # если приложение завершили после атомарной замены файла, но до записи JSON,
    # либо ошибочно утверждать ``audio_codec: opus`` для старого Vorbis.
    codec = _detect_ogg_audio_codec(path)
    if codec == CACHE_AUDIO_CODEC:
        return CACHE_AUDIO_CODEC
    if codec != "vorbis":
        raise ValueError(f"Не удалось определить кодек Ogg-файла {path.name}")
    _transcode_cache_audio_to_opus(path, publish_lock=publish_lock)
    _require_opus_audio_file(path)
    return CACHE_AUDIO_CODEC


def _write_text_atomic(path, content):
    """Атомарно записывает UTF-8 текст, не оставляя обрезанный файл."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp_path = path.with_name(f".{uuid.uuid4().hex}.tmp")
    try:
        with open(temp_path, "w", encoding="utf-8") as file:
            file.write(str(content))
            file.flush()
            os.fsync(file.fileno())
        os.replace(temp_path, path)
        return path
    finally:
        temp_path.unlink(missing_ok=True)


def collect_normalizer_text_files(source_dir, *, include_subdirs=True):
    """Возвращает TXT из папки в стабильном порядке для пакетной нормализации."""
    root = Path(source_dir).expanduser().resolve()
    if not root.is_dir():
        raise ValueError(f"папка источников не существует: {root}")
    if include_subdirs:
        tree = scan_source_tree(root, extensions=(".txt",))
        return tuple(
            Path(node.path).expanduser().resolve()
            for node in flatten_source_tree(tree)
            if isinstance(node, SourceNode) and node.is_file
        )
    entries = []
    try:
        with os.scandir(root) as iterator:
            for entry in iterator:
                if entry.name.startswith("."):
                    continue
                try:
                    if entry.is_file(follow_symlinks=False) and Path(
                        entry.name
                    ).suffix.lower() == ".txt":
                        entries.append(Path(entry.path).resolve())
                except OSError as exc:
                    logging.warning(
                        "Пропущен недоступный текстовый файл %s: %s",
                        entry.path,
                        exc,
                    )
    except OSError as exc:
        raise OSError(f"не удалось прочитать каталог {root}: {exc}") from exc
    entries.sort(key=natural_book_import_sort_key)
    return tuple(entries)


def validate_normalizer_folder_paths(source_dir, output_dir):
    """Проверяет, что результаты не могут попасть в дерево исходных TXT."""
    source_root = Path(source_dir).expanduser().resolve()
    output_root = Path(output_dir).expanduser().resolve()
    if not source_root.is_dir():
        raise ValueError(f"папка источников не существует: {source_root}")
    if source_root.is_relative_to(output_root) or output_root.is_relative_to(source_root):
        raise ValueError(
            "Папка назначения должна отличаться от папки источников; "
            "они не должны находиться одна внутри другой. "
            "Выберите отдельную папку для результатов."
        )
    if output_root.exists() and not output_root.is_dir():
        raise ValueError(f"путь назначения не является папкой: {output_root}")
    return source_root, output_root


def normalize_text_folder(
    source_dir,
    output_dir,
    normalization_context,
    *,
    include_subdirs=True,
    overwrite=False,
    cancel_event=None,
    progress_callback=None,
    files=None,
):
    """Пакетно нормализует TXT без API и изменения исходной папки.

    Контекст нормализации должен быть создан через
    :meth:`TTSProcessor.normalization_context`, поэтому одиночный и пакетный
    режимы используют одинаковые правила, глоссарий и обработку разделителей.
    Аргумент ``files`` позволяет передать снимок списка, уже проверенный UI;
    это исключает расхождение прогресса, если каталог меняется во время запуска.
    """
    source_root, output_root = validate_normalizer_folder_paths(source_dir, output_dir)
    if files is None:
        files = collect_normalizer_text_files(
            source_root,
            include_subdirs=include_subdirs,
        )
    else:
        normalized_files = []
        for raw_path in files:
            path = Path(raw_path).expanduser().resolve()
            try:
                path.relative_to(source_root)
            except ValueError as exc:
                raise ValueError(
                    f"файл пакетной нормализации находится вне исходной папки: {path}"
                ) from exc
            normalized_files.append(path)
        files = tuple(normalized_files)
    summary = {
        "total": len(files),
        "written": 0,
        "skipped_existing": 0,
        "errors": [],
        "skipped_fragments": 0,
        "empty_results": 0,
        "cancelled": False,
    }
    for index, source_path in enumerate(files, 1):
        if cancel_event is not None and cancel_event.is_set():
            summary["cancelled"] = True
            break
        try:
            relative_path = source_path.relative_to(source_root)
            output_path = output_root / relative_path
            if not output_path.parent.resolve().is_relative_to(output_root):
                raise ValueError("подпапка назначения ведёт за пределы папки результатов")
            if output_path.exists() and not overwrite:
                summary["skipped_existing"] += 1
                status = "пропущен: уже существует"
            else:
                raw_text = source_path.read_text(encoding="utf-8-sig")
                result = normalization_context.preview_normalization(raw_text)
                normalized_text = str(
                    result.get("normalized_text_for_file", "")
                )
                _write_text_atomic(output_path, normalized_text)
                summary["written"] += 1
                summary["skipped_fragments"] += len(
                    result.get("skipped", ()) or ()
                )
                if not normalized_text.strip():
                    summary["empty_results"] += 1
                    status = "сохранён пустой результат"
                else:
                    status = "сохранён"
                logging.info(
                    "Нормализованный текст сохранён: source=%s; output=%s",
                    source_path,
                    output_path,
                )
            if progress_callback:
                progress_callback(index, len(files), source_path.name, status)
        except Exception as exc:
            summary["errors"].append(
                {"source": str(source_path), "error": str(exc)}
            )
            logging.error(
                "Не удалось нормализовать текст %s: %s",
                source_path,
                exc,
            )
            if progress_callback:
                progress_callback(index, len(files), source_path.name, "ошибка")
    return summary

