def template_helper_context(context_kind):
    """Возвращает описание контекста помощника без изменяемых ссылок наружу."""
    try:
        spec = TEMPLATE_HELPER_CONTEXTS[str(context_kind)]
    except KeyError:
        raise TemplateError(f"неизвестный контекст шаблона: {context_kind}") from None
    return {
        "fields": tuple(spec["fields"]),
        "start_fields": frozenset(spec["start_fields"]),
        "width_fields": frozenset(spec["width_fields"]),
        "empty_allowed": bool(spec["empty_allowed"]),
        "presets": tuple(spec["presets"]),
    }


def build_template_helper_token(
    context_kind,
    field_name,
    mode="plain",
    value=1,
    *,
    start=None,
    width=None,
    adaptive=False,
):
    """Строит один безопасный токен для вставки в строку шаблона."""
    spec = template_helper_context(context_kind)
    fields = {field for field, _label, _description in spec["fields"]}
    field_name = str(field_name or "")
    if field_name not in fields:
        raise TemplateError(f"поле {{{field_name}}} недоступно в этом контексте")

    # Новая форма с независимыми параметрами позволяет сочетать старт с
    # разрядностью. Старые mode/value оставлены для совместимости вызовов.
    if adaptive:
        if field_name not in spec["width_fields"]:
            raise TemplateError(
                f"поле {{{field_name}}} не поддерживает адаптивную разрядность"
            )
        if width is not None:
            raise TemplateError(
                "адаптивную и фиксированную разрядность нельзя выбрать одновременно"
            )
        if start is not None:
            try:
                start = int(start)
            except (TypeError, ValueError, OverflowError):
                raise TemplateError(
                    "начальный номер должен быть целым числом"
                ) from None
            if start < 0:
                raise TemplateError("начальный номер не может быть отрицательным")
            return "{" + field_name + f":{start}:00d" + "}"
        return "{" + field_name + ":00d}"

    if start is not None or width is not None:
        if start is not None:
            if field_name not in spec["start_fields"]:
                raise TemplateError(
                    f"поле {{{field_name}}} не поддерживает начальный номер"
                )
            try:
                start = int(start)
            except (TypeError, ValueError, OverflowError):
                raise TemplateError(
                    "начальный номер должен быть целым числом"
                ) from None
            if start < 0:
                raise TemplateError("начальный номер не может быть отрицательным")
        if width is not None:
            if field_name not in spec["width_fields"]:
                raise TemplateError(
                    f"поле {{{field_name}}} не поддерживает ведущие нули"
                )
            try:
                width = int(width)
            except (TypeError, ValueError, OverflowError):
                raise TemplateError("разрядность должна быть целым числом") from None
            if not 1 <= width <= 9:
                raise TemplateError("разрядность должна быть от 1 до 9")
        if start is not None and width is not None:
            return "{" + field_name + f":{start}:0{width}d" + "}"
        if start is not None:
            return "{" + field_name + f":{start}" + "}"
        if width is not None:
            return "{" + field_name + f":0{width}d" + "}"
        return "{" + field_name + "}"

    mode = str(mode or "plain")
    if mode == "plain":
        return "{" + field_name + "}"
    try:
        number = int(value)
    except (TypeError, ValueError, OverflowError):
        raise TemplateError("параметр счётчика должен быть целым числом") from None
    if mode == "start":
        if field_name not in spec["start_fields"]:
            raise TemplateError(f"поле {{{field_name}}} не поддерживает начальный номер")
        if number < 0:
            raise TemplateError("начальный номер не может быть отрицательным")
        return "{" + field_name + f":{number}" + "}"
    if mode == "width":
        if field_name not in spec["width_fields"]:
            raise TemplateError(f"поле {{{field_name}}} не поддерживает ведущие нули")
        if not 1 <= number <= 9:
            raise TemplateError("ширина должна быть от 1 до 9")
        return "{" + field_name + f":0{number}d" + "}"
    if mode in {"adaptive", "auto"}:
        if field_name not in spec["width_fields"]:
            raise TemplateError(
                f"поле {{{field_name}}} не поддерживает адаптивную разрядность"
            )
        return "{" + field_name + ":00d}"
    raise TemplateError(f"неизвестный режим поля: {mode}")


def render_template_helper_preview(
    context_kind,
    template,
    *,
    book_names=(),
    single_file=False,
    preview_data=None,
):
    """Возвращает примеры тем же рендерером, что использует рабочая операция.

    ``preview_data`` необязателен и содержит снимок уже импортированных
    элементов. В интерфейсе он заменяет учебные значения реальными именами,
    но старые программные вызовы без снимка сохраняют прежний результат.
    """
    context_kind = str(context_kind)
    spec = template_helper_context(context_kind)
    value = str(template or "")
    if not value and not spec["empty_allowed"]:
        raise TemplateError("шаблон не может быть пустым")
    preview_data = dict(preview_data or {})

    if context_kind == "book_import":
        raw_names = preview_data.get("book_names", book_names)
        names = [Path(str(name)).stem for name in raw_names if str(name).strip()]
        if not names:
            names = ["Моя книга I", "Моя книга II"]
        elif len(names) == 1 and not preview_data.get("actual_files"):
            names.append("Следующая книга")
        actual_values = bool(preview_data.get("actual_files"))
        chapter_titles = tuple(preview_data.get("chapter_titles", ()))
        authors = tuple(preview_data.get("authors", ()))
        chapter_count = 1 if single_file else 12
        if actual_values:
            if single_file:
                samples = [(1, 1)]
            elif len(names) == 1:
                samples = [(1, 1), (1, min(2, chapter_count))]
            else:
                samples = [(1, 1), (1, min(2, chapter_count)), (2, 1)]
        else:
            samples = [(1, 1), (1, min(2, chapter_count)), (2, 1)]
            if single_file:
                samples = [(1, 1), (2, 1)]
        titles = ("Глава 1. Начало", "Глава 2. Продолжение", "Глава 1. Начало")
        return tuple(
            render_book_import_filename(
                value,
                book_name=names[min(book_position - 1, len(names) - 1)],
                chapter_title=(
                    chapter_titles[index]
                    if index < len(chapter_titles)
                    else ("Книга" if single_file else titles[index])
                ) if not actual_values else (
                    chapter_titles[index]
                    if index < len(chapter_titles)
                    else ("Название книги" if single_file else "Заголовок главы")
                ),
                author=(
                    authors[index]
                    if index < len(authors)
                    else "Автор книги"
                ) if not actual_values else (
                    authors[index] if index < len(authors) else "Автор не извлечён"
                ),
                chapter_position=chapter_position,
                chapter_count=chapter_count,
                book_position=book_position,
                book_count=max(2, len(names)),
            )
            for index, (book_position, chapter_position) in enumerate(samples)
        )

    if context_kind == "group_sequence":
        if not value.strip():
            raise TemplateError("шаблон имени группы не может быть пустым")
        _group_sequence_placeholders(value)
        names = list(
            str(item).strip()
            for item in preview_data.get("existing_names", ())
            if str(item).strip()
        )
        for _index in range(3):
            names.append(next_sequence_name(value, names))
        return tuple(names[-3:])

    if context_kind == "output_file":
        validate_filename_template(value, TEMPLATE_FIELDS_OUTPUT)
        supplied_contexts = tuple(
            item for item in preview_data.get("file_contexts", ())
            if isinstance(item, Mapping)
        )
        if not supplied_contexts:
            supplied_contexts = tuple(
                {
                    "book": "Моя книга",
                    "name": f"Глава {index}",
                    "group": "Моя книга",
                    "title": f"Глава {index}",
                    "source_name": f"audio_{index:03d}",
                    "source_title": f"Глава {index}",
                    "filename": f"audio_{index:03d}",
                    "index": index,
                    "chapter": index,
                    "group_index": 1,
                    "file_index": index,
                    "chapter_count": 3,
                    "part": 1,
                    "volume": 1,
                    "parts": 1,
                    "first_index": index,
                    "last_index": index,
                    "first_name": f"Глава {index}",
                    "last_name": f"Глава {index}",
                    "num": index,
                    "range": str(index),
                    "format": "mp3",
                    "ext": "mp3",
                    "author": "",
                    "profile": "",
                }
                for index in range(1, 4)
            )
        results = []
        renderer = (
            render_m4b_part_template
            if preview_data.get("grouped_source")
            else render_output_file_template
        )
        for supplied in supplied_contexts[:3]:
            context = {
                "book": "Моя книга",
                "name": "Глава 1",
                "group": "Моя книга",
                "title": "Глава 1",
                "source_name": "audio_001",
                "source_title": "Глава 1",
                "filename": "audio_001",
                "index": 1,
                "chapter": 1,
                "group_index": 1,
                "file_index": 1,
                "chapter_count": len(supplied_contexts),
                "part": 1,
                "volume": 1,
                "parts": 1,
                "first_index": 1,
                "last_index": 1,
                "first_name": "Глава 1",
                "last_name": "Глава 1",
                "num": 1,
                "range": "1",
                "format": "mp3",
                "ext": "mp3",
                "author": "",
                "profile": "",
            }
            context.update(dict(supplied))
            ext = str(context.get("ext") or context.get("format") or "mp3").strip().lstrip(".") or "mp3"
            if value.strip():
                rendered = renderer(
                    value,
                    context,
                    TEMPLATE_FIELDS_OUTPUT,
                )
            else:
                rendered = str(
                    context.get("name")
                    or context.get("title")
                    or context.get("filename")
                    or "Аудиофайл"
                )
            rendered = _template_basename(rendered, ext)
            results.append(
                sanitize_filename_component(
                    rendered,
                    fallback=str(context.get("name") or "Аудиофайл"),
                )
                + "."
                + ext
            )
        return tuple(results)

    if context_kind in {"m4b_part", "m4b_album"}:
        allowed = SOURCE_M4B_TEMPLATE_FIELDS
        validate_filename_template(value, allowed)
        supplied_contexts = tuple(
            item for item in preview_data.get("contexts", ())
            if isinstance(item, Mapping)
        )
        results = []
        part_contexts = supplied_contexts or tuple({"part": part} for part in range(1, 4))
        total_parts = max(1, len(part_contexts))
        for offset, supplied in enumerate(part_contexts, 1):
            part = int(supplied.get("part", supplied.get("volume", offset)) or offset)
            first_index = (part - 1) * 10 + 1
            last_index = part * 10
            context = {
                "book": "Моя книга",
                "name": f"Том {part}",
                "group": f"Том {part}",
                "title": f"Том {part}",
                "source_name": f"Том {part}",
                "source_title": f"Исходный том {part}",
                "index": part,
                "chapter": first_index,
                "group_index": part,
                "file_index": 1,
                "chapter_count": 30,
                "part": part,
                "volume": part,
                "parts": 3,
                "first_index": first_index,
                "last_index": last_index,
                "num": part,
                "first": first_index,
                "last": last_index,
                "range": f"{first_index:03d}-{last_index:03d}",
                "first_name": f"{first_index:03d}. Начало",
                "last_name": f"{last_index:03d}. Конец",
                "format": "m4b",
                "ext": "m4b",
                "profile": "M4A AAC-LC 64 кбит/с",
                "author": "Автор Книги",
            }
            context.update(dict(supplied))
            context.setdefault("part", part)
            context.setdefault("volume", part)
            context.setdefault("num", part)
            context.setdefault("index", part)
            context.setdefault("group_index", part)
            context.setdefault("file_index", 1)
            context.setdefault("parts", total_parts)
            context.setdefault("first_index", first_index)
            context.setdefault("last_index", last_index)
            context.setdefault("range", f"{first_index:03d}-{last_index:03d}")
            context.setdefault("format", "m4b")
            context.setdefault("ext", "m4b")
            context.setdefault("filename", context.get("first_name", ""))
            if context_kind == "m4b_album":
                rendered = render_m4b_album_template(value, context, fallback="Моя книга")
                results.append(rendered or "(тег альбома из настроек)")
                continue
            effective = value.strip() or SOURCE_M4B_NO_RANGE_TEMPLATE
            rendered = render_m4b_part_template(effective, context, allowed)
            rendered = _template_basename(rendered, "m4b")
            if _m4b_template_needs_part_suffix(effective, context, allowed):
                rendered = _append_m4b_part_suffix(
                    rendered,
                    context,
                    fallback="Моя книга",
                )
            rendered = sanitize_filename_component(
                rendered,
                fallback=f"Моя книга Часть {part}",
                max_length=180,
            )
            results.append(rendered + ".m4b")
        return tuple(results)

    if context_kind == "m4b_chapter":
        validate_filename_template(value, M4B_CHAPTER_TEMPLATE_FIELDS)
        chapter_groups = tuple(
            item for item in preview_data.get("chapter_groups", ())
            if isinstance(item, Mapping)
        )
        if chapter_groups:
            rendered = []
            for group_data in chapter_groups[:3]:
                chapters = list(group_data.get("chapters", ()) or ())
                if not chapters:
                    continue
                rendered_group = render_m4b_chapter_titles(
                    chapters[:3],
                    value,
                    book=group_data.get("book", "Книга"),
                    group=group_data.get("group", group_data.get("book", "Книга")),
                    part=group_data.get("part", 1),
                    parts=group_data.get("parts", len(chapter_groups)),
                    chapter_start=group_data.get("chapter_start", 1),
                    chapter_count=group_data.get("chapter_count", len(chapters)),
                    profile=group_data.get("profile", ""),
                    author=group_data.get("author", ""),
                    global_start=group_data.get("global_start", 1),
                    global_offset=group_data.get("global_offset"),
                    group_index=group_data.get(
                        "group_index", group_data.get("part", 1)
                    ),
                )
                rendered.extend(item["title"] for item in rendered_group)
                if len(rendered) >= 3:
                    break
            if rendered:
                return tuple(rendered[:3])
        first = render_m4b_chapter_titles(
            [
                {"index": 1, "file_index": 1, "title": "Пролог", "duration": 1},
                {"index": 2, "file_index": 2, "title": "Первая встреча", "duration": 1},
            ],
            value,
            book="Моя книга",
            group="Том 1",
            part=1,
            parts=2,
            chapter_start=1,
            chapter_count=3,
            global_start=1,
        )
        second = render_m4b_chapter_titles(
            [{"index": 3, "file_index": 1, "title": "Продолжение", "duration": 1}],
            value,
            book="Моя книга",
            group="Том 2",
            part=2,
            parts=2,
            chapter_start=3,
            chapter_count=3,
            global_start=1,
            group_index=2,
        )
        return tuple(item["title"] for item in [*first, *second])

    raise TemplateError(f"предпросмотр не поддерживает контекст: {context_kind}")


def _template_helper_preset_name(value):
    """Нормализует короткое имя пользовательского варианта."""
    name = re.sub(r"\s+", " ", str(value or "")).strip()
    if not name:
        raise TemplateError("укажите название готового варианта")
    if len(name) > 80:
        raise TemplateError("название готового варианта длиннее 80 символов")
    return name


def normalize_template_helper_presets(data):
    """Очищает локальную библиотеку пользовательских вариантов шаблонов."""
    if not isinstance(data, dict):
        return {}
    normalized = {}
    for context_kind in TEMPLATE_HELPER_CONTEXTS:
        raw_entries = data.get(context_kind, ())
        if not isinstance(raw_entries, (list, tuple)):
            continue
        builtin_names = {
            str(label).casefold()
            for label, _template in TEMPLATE_HELPER_CONTEXTS[context_kind]["presets"]
        }
        seen_names = set()
        entries = []
        for raw_entry in raw_entries[:100]:
            if not isinstance(raw_entry, dict):
                continue
            try:
                name = _template_helper_preset_name(raw_entry.get("name"))
                template = str(raw_entry.get("template", ""))
                if len(template) > 2000:
                    raise TemplateError("шаблон длиннее 2000 символов")
                identity = name.casefold()
                if identity in builtin_names or identity in seen_names:
                    continue
                render_template_helper_preview(context_kind, template)
            except (TemplateError, TypeError, ValueError, OverflowError):
                continue
            seen_names.add(identity)
            entries.append({"name": name, "template": template})
        if entries:
            normalized[context_kind] = entries
    return normalized


def template_helper_preset_entries(context_kind, custom_presets=None):
    """Объединяет неизменяемые встроенные и локальные варианты контекста."""
    spec = template_helper_context(context_kind)
    custom = normalize_template_helper_presets(custom_presets or {})
    result = [
        {"name": label, "template": template, "builtin": True}
        for label, template in spec["presets"]
    ]
    result.extend(
        {
            "name": entry["name"],
            "template": entry["template"],
            "builtin": False,
        }
        for entry in custom.get(str(context_kind), ())
    )
    return tuple(result)


def save_template_helper_preset(custom_presets, context_kind, name, template):
    """Добавляет или заменяет один пользовательский вариант в копии библиотеки."""
    context_kind = str(context_kind)
    spec = template_helper_context(context_kind)
    name = _template_helper_preset_name(name)
    template = str(template or "")
    if len(template) > 2000:
        raise TemplateError("шаблон длиннее 2000 символов")
    if name.casefold() in {
        str(label).casefold() for label, _value in spec["presets"]
    }:
        raise TemplateError("встроенный готовый вариант нельзя заменить")
    render_template_helper_preview(context_kind, template)

    result = normalize_template_helper_presets(custom_presets or {})
    entries = list(result.get(context_kind, ()))
    replacement = {"name": name, "template": template}
    for index, entry in enumerate(entries):
        if entry["name"].casefold() == name.casefold():
            entries[index] = replacement
            break
    else:
        if len(entries) >= 100:
            raise TemplateError("для одного раздела можно сохранить до 100 вариантов")
        entries.append(replacement)
    result[context_kind] = entries
    return result


def delete_template_helper_preset(custom_presets, context_kind, name):
    """Удаляет пользовательский вариант, не позволяя затронуть встроенный."""
    context_kind = str(context_kind)
    spec = template_helper_context(context_kind)
    identity = _template_helper_preset_name(name).casefold()
    if identity in {
        str(label).casefold() for label, _value in spec["presets"]
    }:
        raise TemplateError("встроенный готовый вариант нельзя удалить")
    result = normalize_template_helper_presets(custom_presets or {})
    entries = [
        entry
        for entry in result.get(context_kind, ())
        if entry["name"].casefold() != identity
    ]
    if entries:
        result[context_kind] = entries
    else:
        result.pop(context_kind, None)
    return result


def merge_book_import_paths(current_paths, added_paths):
    """Добавляет пути в очередь импорта по порядку, исключая дубликаты."""
    merged = []
    identities = set()
    for raw_path in [*current_paths, *added_paths]:
        value = str(raw_path).strip()
        if not value:
            continue
        expanded = str(Path(value).expanduser())
        identity = _book_import_path_identity(expanded)
        if identity in identities:
            continue
        identities.add(identity)
        merged.append(expanded)
    return merged


def natural_book_import_sort_key(path):
    """Строит естественный ключ имени книги; одинаковые имена остаются стабильны."""
    value = str(path or "")
    name = unicodedata.normalize("NFC", Path(value).name)
    parts = []
    for part in re.split(r"(\d+|[A-Za-z]+)", name):
        if not part:
            continue
        if part.isdigit():
            parts.append((0, int(part)))
            continue
        roman_value = _roman_book_number(part)
        if roman_value is not None:
            parts.append((0, roman_value))
        else:
            parts.append((1, part.casefold()))
    parts = tuple(parts)
    return parts


def _roman_book_number(value):
    """Возвращает значение канонического римского номера в верхнем регистре."""
    text = str(value or "")
    if not text or text != text.upper():
        return None
    if re.fullmatch(
        r"M{0,3}(?:CM|CD|D?C{0,3})(?:XC|XL|L?X{0,3})"
        r"(?:IX|IV|V?I{0,3})",
        text,
    ) is None:
        return None
    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    previous = 0
    for symbol in reversed(text):
        current = values[symbol]
        if current < previous:
            total -= current
        else:
            total += current
            previous = current
    return total or None


def sort_book_import_paths(paths):
    """Возвращает очередь, естественно отсортированную по имени файла."""
    return sorted(list(paths or ()), key=natural_book_import_sort_key)


def replace_book_import_path(paths, index, new_path):
    """Заменяет один путь без изменения позиции и без скрытого дубликата."""
    result = list(paths or ())
    try:
        index = int(index)
    except (TypeError, ValueError, OverflowError):
        raise ValueError("не выбрана строка очереди") from None
    if index < 0 or index >= len(result):
        raise ValueError("не выбрана строка очереди")
    value = str(new_path or "").strip()
    if not value:
        raise ValueError("путь к книге не может быть пустым")
    expanded = str(Path(value).expanduser())
    identity = _book_import_path_identity(expanded)
    for other_index, other_path in enumerate(result):
        if other_index != index and _book_import_path_identity(other_path) == identity:
            raise ValueError("эта книга уже находится в очереди")
    result[index] = expanded
    return result


def move_book_import_paths(paths, selected_indices, direction):
    """Перемещает выбранные строки очереди на одну позицию с сохранением блока."""
    result = list(paths or ())
    if direction not in {-1, 1}:
        raise ValueError("направление должно быть -1 или 1")
    selected = {
        int(index)
        for index in selected_indices or ()
        if isinstance(index, int) or str(index).lstrip("-").isdigit()
    }
    selected = {index for index in selected if 0 <= index < len(result)}
    order = sorted(selected, reverse=direction > 0)
    for index in order:
        neighbour = index + direction
        if not (0 <= neighbour < len(result)) or neighbour in selected:
            continue
        result[index], result[neighbour] = result[neighbour], result[index]
        selected.remove(index)
        selected.add(neighbour)
    return result, tuple(sorted(selected))


def can_move_book_import_paths(paths, selected_indices, direction):
    """Проверяет, может ли хотя бы одна выбранная строка сдвинуться."""
    if direction not in {-1, 1}:
        return False
    count = len(paths or ())
    selected = {
        int(index)
        for index in selected_indices or ()
        if isinstance(index, int) or str(index).lstrip("-").isdigit()
    }
    selected = {index for index in selected if 0 <= index < count}
    return any(
        0 <= index + direction < count
        and index + direction not in selected
        for index in selected
    )


class BookExtractor:
    """Утилита для извлечения текста из различных форматов книг (EPUB, FB2, DOCX)."""

    SUPPORTED_EXTENSIONS = {".epub", ".fb2", ".docx", ".txt"}

    @staticmethod
    def _clean_html_text(soup, block_tags):
        """
        Умная очистка HTML: сохраняет абзацы, но игнорирует переносы строк
        внутри встроенных тегов (em, strong, b, i) и форматирования кода.
        """
        # 1. Принудительные переносы заменяем на маркер блока
        for tag in soup.find_all(['br', 'hr']):
            tag.replace_with('\n___BLOCK___\n')

        # 2. Ставим маркер блока после каждого блочного тега.
        for tag in soup.find_all(block_tags):
            tag.insert_after('\n___BLOCK___\n')

        # 3. Извлекаем весь текст, заменяя ВСЕ внутренние переносы на пробелы
        raw_text = soup.get_text(separator=' ')

        # 4. Разбиваем текст по нашим маркерам и очищаем от лишних пробелов
        blocks = []
        for block in raw_text.split('___BLOCK___'):
            clean = re.sub(r'\s+', ' ', block).strip()
            if clean:
                blocks.append(clean)

        # 5. Склеиваем чистые абзацы
        return "\n".join(blocks)

    @staticmethod
    def _is_epub_cover_document(item, link=None):
        """Распознаёт явную страницу обложки EPUB без догадок по тексту.

        Некоторые генераторы помещают отрисованный документ обложки в
        навигационную таблицу. Он может содержать название книги, поэтому
        общий очиститель HTML иначе превращает его в короткую искусственную
        главу. Требование, чтобы и заголовок навигации, и идентификатор
        манифеста/файла указывали на ``cover``, не позволяет удалить обычную
        главу лишь из-за названия «Обложка».
        """
        cover_names = {
            "cover",
            "cover-page",
            "cover_page",
            "coverpage",
            "обложка",
        }
        title = str(getattr(link, "title", "") or "").strip().casefold()
        href = str(
            getattr(link, "href", "")
            or getattr(item, "file_name", "")
            or ""
        ).split("#", 1)[0]
        file_stem = Path(href).stem.strip().casefold()
        item_id = str(getattr(item, "id", "") or "").strip().casefold()
        if link is not None:
            return title in cover_names and (
                file_stem in cover_names or item_id in cover_names
            )
        # EPUB без пригодной навигационной таблицы использует spine. В этом
        # случае требуем два независимых признака из манифеста, прежде чем
        # исключать документ: нет человекочитаемого заголовка TOC для проверки.
        return file_stem in cover_names and item_id in cover_names

    @staticmethod
    def extract_epub(filepath):
        book = epub.read_epub(str(filepath))
        chapters = []
        author = ""

        try:
            creators = book.get_metadata('DC', 'creator')
            if creators:
                raw_author = creators[0][0]
                author = str(raw_author).strip() if raw_author is not None else ""
        except (AttributeError, IndexError, TypeError) as exc:
            logging.debug("Не удалось прочитать автора EPUB: %s", exc)

        # Блочные теги для EPUB
        epub_blocks = ['p', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'li', 'blockquote']

        def parse_toc(toc_list):
            items = []
            for item in toc_list:
                if isinstance(item, epub.Link):
                    items.append(item)
                elif isinstance(item, (tuple, list)):
                    for sub in item:
                        if isinstance(sub, (list, tuple)): items.extend(parse_toc(sub))
                        elif isinstance(sub, epub.Link): items.append(sub)
            return items

        links = parse_toc(book.toc)
        if links:
            for link in links:
                href = link.href.split('#')[0]
                for item in book.get_items():
                    if item.file_name == href:
                        if BookExtractor._is_epub_cover_document(item, link):
                            break
                        html_content = item.get_content().decode('utf-8', errors='ignore')
                        soup = BeautifulSoup(html_content, 'html.parser')
                        text = BookExtractor._clean_html_text(soup, epub_blocks)
                        if text: chapters.append((link.title, text))
                        break
        else:
            for item_id in book.spine:
                item = book.get_item_with_id(item_id[0])
                if item.get_type() == ebooklib.ITEM_DOCUMENT:
                    if BookExtractor._is_epub_cover_document(item):
                        continue
                    html_content = item.get_content().decode('utf-8', errors='ignore')
                    soup = BeautifulSoup(html_content, 'html.parser')
                    text = BookExtractor._clean_html_text(soup, epub_blocks)
                    if text: chapters.append(("Глава", text))

        return chapters, author

    @staticmethod
    def extract_fb2(filepath):
        # Передаём анализатору байты: XML-декларация FB2 сама задаёт кодировку.
        # Принудительный UTF-8 ломал легальные старые книги в windows-1251.
        with open(filepath, 'rb') as f:
            soup = BeautifulSoup(f, 'xml')

        chapters = []
        author = ""

        try:
            a_tag = soup.find('author')
            if a_tag:
                fn = a_tag.find('first-name')
                ln = a_tag.find('last-name')
                fn_str = fn.get_text(strip=True) if fn else ""
                ln_str = ln.get_text(strip=True) if ln else ""
                author = f"{fn_str} {ln_str}".strip()
        except (AttributeError, TypeError) as exc:
            logging.debug("Не удалось прочитать автора FB2: %s", exc)

        # Блочные теги для FB2
        fb2_blocks = ['p', 'v', 'subtitle', 'text-author', 'title', 'empty-line']

        body = soup.find('body')
        if not body:
            return [("Книга", BookExtractor._clean_html_text(soup, fb2_blocks))], author

        sections = body.find_all('section', recursive=False)
        if not sections: sections = body.find_all('section')
        if not sections:
            return [("Книга", BookExtractor._clean_html_text(body, fb2_blocks))], author

        for sec in sections:
            title_tag = sec.find('title')
            title = title_tag.get_text(strip=True) if title_tag else "Глава"
            text = BookExtractor._clean_html_text(sec, fb2_blocks)
            if text: chapters.append((title, text))

        return chapters, author

    @staticmethod
    def extract_docx(filepath):
        doc = docx.Document(filepath)
        chapters = []
        current_title = "Вступление"
        current_text = []

        # DOCX не подвержен проблеме тегов: python-docx выдаёт чистый текст параграфа.
        for p in doc.paragraphs:
            if p.style.name.startswith('Heading'):
                if current_text:
                    chapters.append((current_title, "\n".join(current_text)))
                    current_text = []
                current_title = p.text.strip() or "Глава"
                current_text.append(current_title)
            else:
                if p.text.strip(): current_text.append(p.text.strip())

        if current_text:
            chapters.append((current_title, "\n".join(current_text)))

        return chapters

    @staticmethod
    def split_txt_by_regex(filepath, pattern):
        with open(filepath, 'r', encoding='utf-8-sig') as f:
            text = f.read()

        if not pattern:
            return [("Текст", text)]

        matches = list(re.finditer(pattern, text, flags=re.MULTILINE))
        if not matches:
            return [("Текст", text)]

        chapters = []
        if matches[0].start() > 0:
            intro = text[:matches[0].start()].strip('\n')
            if intro.strip(): chapters.append(("Вступление", intro))

        for i, match in enumerate(matches):
            start = match.start()
            end = matches[i+1].start() if i+1 < len(matches) else len(text)
            content = text[start:end].strip('\n')
            title = match.group(0).strip()
            if content.strip(): chapters.append((title, content))

        return chapters

    @staticmethod
    def extract_file(filepath, regex_pattern="", single_file=False):
        """Извлекает главы и автора из одного поддерживаемого файла.

        Единая точка входа нужна пакетному импорту: обработка одной книги и
        прежний одиночный сценарий используют одинаковые правила. В режиме
        одного TXT найденные главы объединяются, но метаданные автора EPUB/FB2
        сохраняются для шаблона имени.
        """
        source_path = Path(filepath).expanduser()
        if not source_path.is_file():
            raise FileNotFoundError(f"Файл не найден: {source_path}")

        extension = source_path.suffix.lower()
        if extension not in BookExtractor.SUPPORTED_EXTENSIONS:
            raise ValueError(
                f"Неподдерживаемый формат {extension or '(без расширения)'}: "
                f"{source_path.name}"
            )

        author = ""
        if extension == ".epub":
            chapters, author = BookExtractor.extract_epub(source_path)
        elif extension == ".fb2":
            chapters, author = BookExtractor.extract_fb2(source_path)
        elif extension == ".docx":
            chapters = BookExtractor.extract_docx(source_path)
        else:
            chapters = BookExtractor.split_txt_by_regex(
                source_path,
                "" if single_file else regex_pattern,
            )

        if single_file:
            combined_text = "\n\n".join(
                str(content).strip()
                for _title, content in chapters
                if str(content).strip()
            )
            chapters = [("Книга", combined_text)] if combined_text else []

        return chapters, author

    @staticmethod
    def import_files(
        filepaths,
        out_dir,
        template,
        regex_pattern="",
        single_file=False,
        progress_callback=None,
    ):
        """Последовательно импортирует книги, не прерывая очередь из-за одной ошибки.

        Возвращает по записи на каждый исходный файл. Поле ``error`` равно
        ``None`` при успехе, а ``saved_files`` содержит созданные TXT. Обратный
        вызов получает ``(номер, всего, путь, этап, значение)`` и может безопасно
        переслать прогресс в главный поток GUI.
        """
        _parse_book_import_template(template)
        sources = [Path(path).expanduser() for path in filepaths]
        total_books = len(sources)
        results = []

        def notify(book_index, source_path, stage, value=None):
            if not progress_callback:
                return
            try:
                progress_callback(
                    book_index,
                    total_books,
                    source_path,
                    stage,
                    value,
                )
            except Exception:
                # Ошибка необязательного индикатора не должна останавливать
                # импорт книги или оставшуюся очередь.
                logging.exception("Не удалось обновить прогресс импорта книг")

        for book_index, source_path in enumerate(sources, 1):
            notify(book_index, source_path, "extract")
            try:
                chapters, author = BookExtractor.extract_file(
                    source_path,
                    regex_pattern=regex_pattern,
                    single_file=single_file,
                )
                if not chapters:
                    raise ValueError("Не удалось найти текст или главы в файле.")

                notify(book_index, source_path, "save", len(chapters))
                saved_files = BookExtractor.save_chapters(
                    chapters,
                    out_dir,
                    source_path,
                    template,
                    author=author,
                    book_index=book_index,
                    book_count=total_books,
                )
                result = {
                    "path": str(source_path),
                    "book_index": book_index,
                    "saved_files": saved_files,
                    "chapter_count": len(chapters),
                    "error": None,
                }
                results.append(result)
                notify(book_index, source_path, "complete", len(saved_files))
            except Exception as exc:
                logging.exception("Не удалось импортировать книгу %s", source_path)
                result = {
                    "path": str(source_path),
                    "book_index": book_index,
                    "saved_files": [],
                    "chapter_count": 0,
                    "error": str(exc) or exc.__class__.__name__,
                }
                results.append(result)
                notify(book_index, source_path, "error", result["error"])

        return results

    @staticmethod
    def save_chapters(
        chapters,
        out_dir,
        orig_filename,
        template,
        author="",
        *,
        book_index=1,
        book_count=1,
    ):
        total = len(chapters)
        out_dir = Path(out_dir)
        out_dir.mkdir(parents=True, exist_ok=True)

        saved_files = []
        name_no_ext = Path(orig_filename).stem
        parsed_template, counter_starts = _parse_book_import_template(template)
        try:
            queue_index = max(1, int(book_index))
        except (TypeError, ValueError, OverflowError):
            queue_index = 1
        try:
            queue_count = max(queue_index, int(book_count))
        except (TypeError, ValueError, OverflowError):
            queue_count = queue_index

        occupied_names = {
            _book_import_name_identity(path.name)
            for path in out_dir.iterdir()
            if path.is_file()
        }
        planned_files = []

        for idx, (title, content) in enumerate(chapters, 0):
            filename = _render_book_import_filename(
                parsed_template,
                counter_starts,
                book_name=name_no_ext,
                chapter_title=title,
                author=author,
                chapter_position=idx + 1,
                chapter_count=total,
                book_position=queue_index,
                book_count=queue_count,
            )
            base_filename = Path(filename).stem
            duplicate_index = 2
            while _book_import_name_identity(filename) in occupied_names:
                suffix = f" ({duplicate_index})"
                trimmed = base_filename[: max(1, 180 - len(suffix))].rstrip(". ")
                filename = f"{trimmed}{suffix}.txt"
                duplicate_index += 1
            occupied_names.add(_book_import_name_identity(filename))
            planned_files.append((idx, filename, content))

        created_paths = []
        try:
            for idx, filename, content in planned_files:
                out_path = out_dir / filename
                _write_text_atomic(out_path, content)
                created_paths.append(out_path)
                saved_files.append(filename)
                logging.info(
                    "Импорт книги: сохранена глава %d/%d: %s",
                    idx + 1,
                    total,
                    out_path,
                )
        except Exception:
            for created_path in reversed(created_paths):
                try:
                    created_path.unlink(missing_ok=True)
                except OSError:
                    logging.exception(
                        "Не удалось удалить неполный результат импорта %s",
                        created_path,
                    )
            raise

        return saved_files
# Графический интерфейс
class TTSApp:
    """Главный класс графического интерфейса приложения."""
    STATUS_COLORS_LIGHT = {
        "info": "#003366",
        "success": "#14532D",
        "warning": "#7C2D12",
        "error": "#7F1D1D",
        "text": "#000000",
        "muted": "#525252",
    }
    STATUS_COLORS_DARK = {
        "info": "#7DD3FC",
        "success": "#86EFAC",
        "warning": "#FDBA74",
        "error": "#FCA5A5",
        "text": "#FFFFFF",
        "muted": "#D1D5DB",
    }

    def __init__(self, root):
        self.root = root
        self.root.title("Silero TTS Studio")

        # Фоновые потоки не должны обращаться к Tcl/Tk напрямую. Они складывают
        # вызовы сюда, а главный поток регулярно исполняет их в цикле Tk.
        self._ui_queue = queue.SimpleQueue()
        self.root.after(25, self._drain_ui_queue)

        self.settings_vars = {}
        self.config = self.load_settings()

        # Старые версии сохраняли вычисляемый путь глоссария в settings.json.
        # Источник истины — cache_dir; удаляем устаревший ключ, чтобы он не
        # выглядел как импортированный путь и не переезжал в новые конфиги.
        self.config.pop("glossary_path", None)

        # Общий лимитер нужен до построения вкладок: их инициализация может
        # вызвать save_settings().
        self.shared_rate_limiter = RateLimiter(
            self.config.get("api_max_requests", 15),
            self.config.get("api_time_window", 15.0),
        )

        # Динамический размер окна (70% от экрана по центру)
        screen_width = self.root.winfo_screenwidth()
        screen_height = self.root.winfo_screenheight()
        w = int(screen_width * 0.7)
        h = int(screen_height * 0.7)
        x = int((screen_width - w) / 2)
        y = int((screen_height - h) / 2)
        self.root.geometry(f"{w}x{h}+{x}+{y}")
        # Не позволяем вручную сжать окно до состояния, в котором нижние
        # действия экспортной вкладки и кнопки тегов оказываются за границей.
        # На маленьком экране предел автоматически уменьшается до доступного.
        self.root.minsize(
            max(360, min(900, screen_width - 40)),
            max(320, min(520, screen_height - 80)),
        )

        self.processor = None
        self.batch_processor = None
        self.direct_processor = None
        self.processing_thread = None
        self.direct_thread = None
        self.last_direct_audio = None
        self.last_direct_audio_has_effects = False
        self._batch_hard_stop_requested = False
        self._direct_hard_stop_requested = False
        # Все операции, способные читать/менять индекс кэша, координируются
        # единым состоянием. Отдельные bool сохранены как совместимые запросы
        # через методы is_cache_*(), но источником истины является эта строка.
        self._cache_operation = None
        self._cache_optimization_running = False
        self._cache_archive_running = False
        self._cache_transcode_cancel = None
        self._cache_ui_loading = False
        self._cache_ui_loaded = False
        self._cache_state_generation = 0
        self._cache_ui_request_id = 0
        self._import_running = False
        self._import_thread = None
        # Не повторяем одно и то же предупреждение для Steps при каждом файле.
        # При смене значения ключ меняется и предупреждение снова показывается.
        self._confirmed_steps_warnings = set()
        self._is_closing = False
        self._shared_cache_dir = None
        self._shared_cache = None
        self._shared_processing_statuses = None
        self._shared_cache_lock = threading.RLock()
        self._shared_synthesis_inflight = {}
        # Защита со счётчиком ссылок общая для пакетного и прямого процессоров.
        # Запуск источника с несколькими выходами может удерживать пути кэша
        # для отложенного этапа M4B, пока прямому синтезу всё ещё разрешено
        # использовать тот же индекс в оперативной памяти, поэтому локального флага процессора
        # было бы недостаточно.
        self._shared_cache_eviction_state = {
            "deferred": 0,
            "pending": False,
        }
        self._direct_force_active = False
        self._cache_ui_filter_after_id = None
        self._settings_save_after_id = None
        self._is_dark_appearance = False
        self._appearance_check_after_id = None
        self._status_label_kinds = {}
        self._palette_widget_kinds = {}

        self._export_lock = False
        self._export_running = False
        # Для кодирования/ремуксинга M4B нет дешёвого расчёта процента по байтам.
        # На этих этапах индикатор экспорта переключается на неопределённую
        # анимацию и возвращается в определённый режим после каждого
        # завершённого результата.
        self._export_progress_indeterminate = False
        self._export_import_thread = None
        self._export_thread = None
        self._export_session_save_after_id = None
        self._restoring_export_project_session = False
        self._export_project_explicitly_cleared = False

        # Виртуальный предварительный план M4B для вкладки «Синтез из папки».
        # Он группирует TXT только в Treeview и никогда не меняет файлы на
        # диске. Фактические длительности появятся лишь после синтеза.
        self._source_plan_groups = {}
        self._source_plan_estimates = {}
        self._source_plan_template = normalize_source_m4b_template(
            self.config.get("synthesis_m4b_template")
        )
        # Пустой шаблон альбома имеет смысл (он явно отключает переопределение
        # M4B исходников), а значение по умолчанию группирует все части как один
        # альбом в проигрывателях вроде Apple Books.
        self._source_plan_album_template = normalize_source_m4b_album_template(
            self.config.get("synthesis_m4b_album_template")
        )
        self._source_plan_reload_pending = False
        self._source_plan_snapshot = None
        self._source_plan_dirty = False
        self._source_plan_revision = 0
        self._source_completed_regular_targets = {}
        self._source_completed_m4b_targets = {}
        self._source_session_save_after_id = None
        self._source_session_input_dir = None
        self._source_session_input_signature = {}
        self._source_session_config_signature = None
        self._restoring_source_session = False
        # Перестроение M4B по фактической длительности рассчитывается после
        # создания неизменяемого снимка запуска планировщиком источников.
        # Сохраняем принятый результат и между перезапусками приложения,
        # чтобы успешное перестроение сразу не заменялось прежними границами,
        # основанными только на оценке.
        self._source_runtime_m4b_records = None
        self._source_status_activity = None
        # Фоновый обработчик подготавливает новое разбиение по длительности.
        # ``finish_processing`` принимает его только после успеха всей очереди,
        # чтобы ошибка или остановка не заменили план частичным результатом.
        self._pending_source_m4b_ui_plan = None
        self._source_run_has_m4b = False
        # Запуск выбранного подмножества не должен помечать полный виртуальный
        # план M4B актуальным: его результаты не охватывают остальные главы.
        # Этот флаг фиксирует точный снимок запуска, а не текущее выделение.
        self._source_run_m4b_full = False
        self._source_run_plan_full = False
        self._source_run_has_targets = False
        # Значение True действует, пока индикатор файлов вкладки источников
        # анимируется во время длительного заключительного этапа M4B. Оно хранится отдельно
        # от режима ttk, поскольку некоторые версии Tk непоследовательно
        # предоставляют ``cget('mode')``.
        self._source_file_progress_indeterminate = False
        self._source_plan_running = False
        try:
            self.synthesis_targets = list(
                normalize_output_target_directories(
                    [
                        normalize_output_target(item)
                        for item in self.config.get(
                            SYNTHESIS_TARGETS_CONFIG_KEY, []
                        )
                        if isinstance(item, dict)
                    ]
                )
            )
        except (TypeError, ValueError) as exc:
            logging.warning("Набор целей синтеза не загружен: %s", exc)
            self.synthesis_targets = []

        self.font_size_var = tk.IntVar(value=self.config.get("ui_font_size", 10))

        self.notebook = ttk.Notebook(self.root)
        self.notebook.pack(fill=tk.BOTH, expand=True)

        self.tab_main = ttk.Frame(self.notebook)
        self.tab_direct = ttk.Frame(self.notebook)
        self.tab_import = ttk.Frame(self.notebook)
        self.tab_utils = ttk.Frame(self.notebook)
        self.tab_settings = ttk.Frame(self.notebook)
        self.tab_glossary = ttk.Frame(self.notebook)
        self.tab_normalizer = ttk.Frame(self.notebook)
        self.tab_cache = ttk.Frame(self.notebook)
        self.tab_help = ttk.Frame(self.notebook)

        self._main_notebook_tabs = (
            self.tab_main,
            self.tab_direct,
            self.tab_import,
            self.tab_utils,
            self.tab_settings,
            self.tab_glossary,
            self.tab_normalizer,
            self.tab_cache,
            self.tab_help,
        )
        for tab, label in zip(
            self._main_notebook_tabs,
            main_notebook_tab_labels(w),
        ):
            self.notebook.add(tab, text=label)

        self.setup_main_tab()
        self.setup_direct_tab()
        self.setup_import_tab()
        self.setup_utils_tab()
        self.setup_settings_tab()
        self.setup_glossary_tab()
        self.setup_normalizer_tab()
        self.setup_cache_tab()
        self.setup_help_tab()

        self.notebook.bind("<<NotebookTabChanged>>", self.on_tab_change)
        self.root.bind(
            "<Configure>",
            self._update_main_notebook_tab_labels,
            add="+",
        )
        # Мягкая страховка после закрытия системного окна сообщения: если Aqua не
        # вернул локальный Tk-фокус, первый обычный клик назначает его именно
        # на нажатый виджет. focus_force не используется и потому приложение
        # не отбирает фокус у другого окна без действия пользователя.
        self.root.bind_all(
            "<ButtonPress-1>", self._restore_focus_on_app_click, add="+"
        )
        self.load_files()
        self.update_fonts()

        self.apply_theme()

        if sys.platform == "darwin":
            # Tk 9 сообщает эффективное оформление Aqua напрямую. Tk 8.6 не
        # предоставляет этот API, поэтому резервный путь через RGB ниже сохраняет
        # совместимость.
            self._appearance_check_after_id = self.root.after(1000, self._check_system_appearance)

        self.root.protocol("WM_DELETE_WINDOW", self.on_closing)

        if sys.platform == "darwin":
            self._setup_mac_hotkeys()
            self._setup_mac_startup_focus()
        else:
            self._fix_cyrillic_clipboard()

        self.root.after(300, self._silent_pre_warm_tabs)


    def _update_main_notebook_tab_labels(self, event=None):
        """Сохраняет читаемые названия вкладок при небольшой ширине окна."""
        if event is not None and getattr(event, "widget", None) is not self.root:
            return
        try:
            width = int(getattr(event, "width", 0) or self.root.winfo_width())
            labels = main_notebook_tab_labels(width)
            for tab, label in zip(self._main_notebook_tabs, labels):
                if self.notebook.tab(tab, "text") != label:
                    self.notebook.tab(tab, text=label)
        except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError):
            pass


    def _post_to_ui(self, callback, *args, **kwargs):
        """Потокобезопасно ставит вызов Tkinter в очередь главного потока."""
        if getattr(self, "_is_closing", False):
            return
        self._ui_queue.put((callback, args, kwargs))

    def _restore_focus_on_app_click(self, event):
        """Подтверждает локальный фокус после клика и обновляет элементы Aqua."""
        widget = getattr(event, "widget", None)
        if widget is None or getattr(self, "_is_closing", False):
            return
        try:
            if widget.winfo_toplevel() is not self.root:
                return
        except (AttributeError, tk.TclError):
            return

        def restore_after_click():
            if getattr(self, "_is_closing", False):
                return
            try:
                if not self.root.winfo_exists() or self.root.state() == "iconic":
                    return
                # К моменту цикла простоя штатные привязки Entry/Button/Treeview уже
                # выбрали правильный дочерний виджет. Повторный focus_set на
                # нём активирует локальный Tk-контекст, но не заменяет выбор
                # пользователя. Для клика по пустому Frame сохраняется старое
                # поле; если фокуса действительно нет, используем сам виджет.
                target = self.root.focus_get()
                try:
                    if target is not None and target.winfo_toplevel() is not self.root:
                        target = None
                except (AttributeError, tk.TclError):
                    target = None
                if target is None:
                    target = widget
                try:
                    if not target.winfo_exists():
                        target = self.root
                except (AttributeError, tk.TclError):
                    target = self.root
                target.focus_set()

                # Нативные Progressbar/Scale Aqua иногда продолжают выглядеть
                # неактивными, хотя клик уже вернул NSWindow приложению. Тот же
                # Отложенная перерисовка с объединением повторов используется после
                # Map/Activate и не меняет
                # выбранную тему или значения виджетов.
                if (
                    sys.platform == "darwin"
                    and not getattr(self, "_mac_window_active", False)
                ):
                    self._schedule_mac_restore_refresh()
            except tk.TclError:
                pass

        try:
            self.root.after_idle(restore_after_click)
        except tk.TclError:
            pass

    def _run_messagebox(self, dialog_function, title, message, **options):
        """Показывает системный диалог с владельцем и возвращает Tk-фокус.

        На macOS ``messagebox`` без ``parent`` создаёт нативный alert, который
        не всегда возвращает keyboard focus главному NSWindow после закрытия.
        Явный владелец делает alert оконно-модальным, а отложенный ``focus_set``
        восстанавливает именно тот Tk-виджет, в котором пользователь работал.
        ``focus_force`` намеренно не используется: он мог бы перехватить фокус,
        если пользователь переключился в другое приложение.
        """
        try:
            previous_focus = self.root.focus_get()
        except tk.TclError:
            previous_focus = None

        options.setdefault("parent", self.root)
        try:
            return dialog_function(title, message, **options)
        finally:
            self._schedule_focus_after_messagebox(previous_focus)

    def _schedule_focus_after_messagebox(self, previous_focus=None):
        """Возвращает локальный фокус после полного закрытия системного диалога."""
        if getattr(self, "_is_closing", False):
            return

        def restore_focus():
            if getattr(self, "_is_closing", False):
                return
            try:
                if not self.root.winfo_exists():
                    return
                target = previous_focus
                if target is None or not target.winfo_exists():
                    target = self.root
                target.focus_set()
            except (AttributeError, tk.TclError):
                try:
                    self.root.focus_set()
                except tk.TclError:
                    pass

        try:
            self.root.after_idle(restore_focus)
        except tk.TclError:
            pass

    def _show_info(self, title, message, **options):
        return self._run_messagebox(messagebox.showinfo, title, message, **options)

    def _show_warning(self, title, message, **options):
        return self._run_messagebox(messagebox.showwarning, title, message, **options)

    def _show_error(self, title, message, **options):
        return self._run_messagebox(messagebox.showerror, title, message, **options)

    def _ask_yes_no(self, title, message, **options):
        return self._run_messagebox(messagebox.askyesno, title, message, **options)

    def _ask_yes_no_cancel(self, title, message, **options):
        return self._run_messagebox(
            messagebox.askyesnocancel, title, message, **options
        )

    def _create_synthesis_processor(self, config):
        """Создаёт процессор и делит RAM-кэш между одновременно активными вкладками."""
        cache_dir = Path(config["cache_dir"]).expanduser().resolve()
        active_processors = tuple(
            processor
            for processor in (self.batch_processor, self.direct_processor)
            if processor is not None
        )
        if active_processors and any(processor.cache_dir.resolve() != cache_dir for processor in active_processors):
            raise RuntimeError("Нельзя одновременно синтезировать с разными папками кэша")
        shared_cache = self._shared_cache if self._shared_cache_dir == cache_dir else None
        processor = TTSProcessor(
            config,
            shared_rate_limiter=self.shared_rate_limiter,
            error_callback=self.show_critical_error,
            shared_cache=shared_cache,
            shared_cache_lock=self._shared_cache_lock,
            shared_processing_statuses=(
                self._shared_processing_statuses
                if self._shared_cache_dir == cache_dir
                else None
            ),
            shared_cache_eviction_state=self._shared_cache_eviction_state,
            shared_synthesis_inflight=self._shared_synthesis_inflight,
        )
        # Первый процессор загружает индекс штатным _load_cache(); следующие
        # получают уже тот же объект dict.
        self._shared_cache_dir = cache_dir
        self._shared_cache = processor.cache
        self._shared_processing_statuses = processor.processing_statuses_ram
        return processor

    def _release_shared_cache_if_idle(self):
        """Не держит устаревшую RAM-копию после завершения обоих синтезов."""
        if self.batch_processor is None and self.direct_processor is None:
            self._shared_cache_dir = None
            self._shared_cache = None
            self._shared_processing_statuses = None

    def _drain_ui_queue(self):
        """Исполняет UI-вызовы порциями, не монополизируя цикл Tk."""
        processed = 0
        deadline = time.monotonic() + 0.008
        queue_was_limited = False

        while processed < 200 and time.monotonic() < deadline:
            try:
                callback, args, kwargs = self._ui_queue.get_nowait()
            except queue.Empty:
                break

            try:
                callback(*args, **kwargs)
            except Exception:
                logging.exception("Ошибка отложенного UI-вызова")
            processed += 1

        if processed >= 200 or time.monotonic() >= deadline:
            queue_was_limited = True

        try:
            if self.root.winfo_exists():
                # Если производитель данных быстрее UI, отдаём Tk возможность обработать
                # клики/перерисовку и продолжаем почти сразу следующей порцией.
                self.root.after(1 if queue_was_limited else 25, self._drain_ui_queue)
        except tk.TclError:
            pass

    def _silent_pre_warm_tabs(self):
        """Тихо завершает геометрию вкладок без чтения их данных с диска."""
        tabs_list = list(self.notebook.tabs())

        def _step():
            if not tabs_list:
                return
            tab_id = tabs_list.pop(0)
            try:
                widget = self.notebook.nametowidget(tab_id)
                # В частности, вкладка кэша остаётся ленивой: здесь нет вызова
                # load_cache_ui() и нет построения строк Treeview.
                widget.update_idletasks()
            except tk.TclError as exc:
                logging.debug("Не удалось прогреть вкладку %s: %s", tab_id, exc)
            if tabs_list:
                self.root.after(15, _step)

        self.root.after(100, _step)

    def _setup_mac_startup_focus(self):
        """Один раз поднимает главное окно после его первого появления на macOS."""
        if sys.platform != "darwin":
            return

        self._mac_startup_focus_done = False
        self._mac_window_active = False
        self._mac_startup_focus_after_id = None
        self._mac_startup_map_bind_id = self.root.bind("<Map>", self._on_mac_initial_map, add="+")
        # Повторный Map корневого toplevel после сворачивания не должен снова
        # перехватывать фокус, но Aqua иногда оставляет элементы темы в
        # неактивном сером состоянии до следующей активации приложения.
        self._mac_restore_map_bind_id = self.root.bind(
            "<Map>", self._on_mac_restore_map, add="+"
        )
        # На Aqua активность окна и фокус — разные состояния. После возврата
        # свёрнутого приложения Tk может уже иметь state == normal, но нативные
        # Scale/Progressbar всё ещё нарисованы как элементы неактивного окна.
        # <Activate> приходит именно при возврате NSWindow в активное состояние
        # и потому дополняет (но не заменяет) <Map>.
        self._mac_restore_activate_bind_id = self.root.bind(
            "<Activate>", self._on_mac_restore_activate, add="+"
        )
        self._mac_restore_deactivate_bind_id = self.root.bind(
            "<Deactivate>", self._on_mac_restore_deactivate, add="+"
        )
        # update_idletasks() во время построения большого интерфейса иногда успевает
        # отобразить root до установки bind. after_idle служит одноразовой страховкой.
        self.root.after_idle(self._schedule_mac_startup_focus)

    def _on_mac_initial_map(self, event):
        """Игнорирует Map дочерних окон и повторные Map после сворачивания."""
        if event.widget is not self.root or self._mac_startup_focus_done:
            return
        self._schedule_mac_startup_focus()

    def _on_mac_restore_map(self, event):
        """Перерисовывает Aqua после восстановления, не отбирая фокус."""
        if event.widget is not self.root or not self._mac_startup_focus_done:
            return
        self._schedule_mac_restore_refresh()

    def _on_mac_restore_activate(self, event):
        """Повторяет перерисовку, когда восстановленное Aqua-окно стало активным."""
        if event.widget is not self.root:
            return
        self._mac_window_active = True
        if not self._mac_startup_focus_done:
            return
        self._schedule_mac_restore_refresh()

    def _on_mac_restore_deactivate(self, event):
        """Запоминает потерю системной активности без принудительного фокуса."""
        if event.widget is self.root:
            self._mac_window_active = False

    def _schedule_mac_restore_refresh(self):
        """Объединяет близкие Map/Activate в одну отложенную перерисовку."""
        after_id = getattr(self, "_mac_restore_refresh_after_id", None)
        if after_id is not None:
            try:
                self.root.after_cancel(after_id)
            except tk.TclError:
                pass
        self._mac_restore_refresh_after_id = self.root.after(
            25, self._refresh_mac_after_restore
        )

    def _invalidate_mac_aqua_widgets(self):
        """Просит все ttk-потомки перечитать нативное состояние Aqua."""
        # ttk::ThemeChanged — штатный механизм Tk, который рассылает
        # <<ThemeChanged>> всем потомкам. Некоторые версии Aqua не
        # инвалидируют нативное состояние отрисовки Scale/Progressbar только от
        # виртуального события, поэтому дополнительно переустанавливаем уже
        # выбранную тему: это не меняет оформление или значения виджетов, но
        # заставляет движок темы пересоздать системные элементы управления.
        theme_reloaded = False
        try:
            style = ttk.Style(self.root)
            current_theme = style.theme_use()
            if current_theme:
                style.theme_use(current_theme)
                theme_reloaded = True
        except tk.TclError:
            pass
        if not theme_reloaded:
            try:
                self.root.tk.call("ttk::ThemeChanged")
            except tk.TclError:
                try:
                    self.root.event_generate("<<ThemeChanged>>", when="tail")
                except tk.TclError:
                    pass
        try:
            self.root.event_generate("<Expose>", when="tail")
            self.root.after_idle(self.root.update_idletasks)
        except tk.TclError:
            pass

    def _refresh_mac_after_restore(self):
        """Даёт Aqua один цикл простоя и инвалидирует отрисовку всех потомков."""
        self._mac_restore_refresh_after_id = None
        try:
            if not self.root.winfo_exists() or self.root.state() != "normal":
                return
            # На Tk 9 явный режим auto заставляет NSWindow повторно применить
            # текущее оформление. На Tk 8.6 опция отсутствует и безопасно
            # пропускается, после чего Expose обновляет обычные виджеты.
            try:
                self.root.tk.call(
                    "wm", "attributes", self.root._w, "-appearance", "auto"
                )
            except tk.TclError:
                pass
            self._invalidate_mac_aqua_widgets()
            self._check_system_appearance(reschedule=False)
        except tk.TclError:
            pass

    def _schedule_mac_startup_focus(self):
        """Планирует единственную активацию после завершения отрисовки окна."""
        if self._mac_startup_focus_done:
            return
        if self._mac_startup_focus_after_id is None:
            self._mac_startup_focus_after_id = self.root.after(200, self._run_mac_startup_focus)

    def _run_mac_startup_focus(self):
        self._mac_startup_focus_after_id = None
        if self._mac_startup_focus_done:
            return
        self._mac_startup_focus_done = True
        bind_id = getattr(self, "_mac_startup_map_bind_id", None)
        if bind_id:
            try:
                self.root.unbind("<Map>", bind_id)
            except tk.TclError:
                pass
            self._mac_startup_map_bind_id = None
        self._force_mac_focus()
        self._schedule_mac_restore_refresh()

    def _force_mac_focus(self, *args):
        """Активирует приложение и поднимает окно; вызывается только при старте."""
        if sys.platform != "darwin":
            return

        # Finder-сборке иногда нужна явная активация процесса. Не вызываем
        # objc_msgSend через ctypes: на разных ABI неверная сигнатура такого
        # вызова приводит к нативному SIGSEGV, который Python поймать не может.
        # Системный `open` выполняет активацию вне процесса Tk.
        if is_frozen_mac:
            try:
                subprocess.Popen(
                    ["/usr/bin/open", "-a", str(Path(sys.executable).resolve().parents[2])],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
            except (OSError, IndexError) as exc:
                logging.debug(f"Ошибка стартовой активации .app: {exc}")

        try:
            # Одноразово поднимаем окно над Terminal/Finder, затем снимаем
            # topmost без повторного focus_force и без вложенного root.update().
            self.root.attributes("-topmost", True)
            self.root.lift()
            self.root.focus_force()
            self.root.after(120, self._release_mac_startup_topmost)
        except tk.TclError as e:
            logging.debug(f"Не удалось поднять стартовое окно Tk: {e}")

    def _release_mac_startup_topmost(self):
        """Снимает только временный topmost, не вмешиваясь в текущий фокус."""
        try:
            if self.root.winfo_exists():
                self.root.attributes("-topmost", False)
        except tk.TclError:
            pass

    def _paste_clipboard_once(self, event):
        """Вставляет буфер один раз для физического и виртуального события вставки."""
        widget = getattr(event, "widget", None)
        if not isinstance(widget, (tk.Text, tk.Entry, ttk.Entry)):
            try:
                widget = self.root.focus_get()
            except tk.TclError:
                widget = None
        if not isinstance(widget, (tk.Text, tk.Entry, ttk.Entry)):
            return "break"

        try:
            clipboard_text = self.root.clipboard_get()
        except Exception:
            clipboard_text = ""
        if not clipboard_text and sys.platform == "darwin":
            try:
                clipboard_text = subprocess.check_output(
                    ["/usr/bin/pbpaste"],
                    text=True,
                    stderr=subprocess.DEVNULL,
                )
            except Exception:
                clipboard_text = ""
        if not clipboard_text:
            return "break"

        # Tk сопоставляет Ctrl/Command+V с <<Paste>>, а Studio дополнительно
        # ловит физическую клавишу ради кириллической раскладки. Оба обработчика
        # могут прийти в одной итерации цикла событий. Защита живёт ровно до цикла простоя и
        # не мешает следующему самостоятельному нажатию.
        if getattr(self, "_clipboard_paste_widget", None) is widget:
            return "break"
        self._clipboard_paste_widget = widget

        def clear_paste_guard():
            if getattr(self, "_clipboard_paste_widget", None) is widget:
                self._clipboard_paste_widget = None

        try:
            self.root.after_idle(clear_paste_guard)
        except tk.TclError:
            clear_paste_guard()

        clipboard_text = normalize_clipboard_text(clipboard_text)
        try:
            if isinstance(widget, tk.Text):
                if widget.tag_ranges(tk.SEL):
                    widget.delete(tk.SEL_FIRST, tk.SEL_LAST)
                widget.insert(tk.INSERT, clipboard_text)
            else:
                try:
                    if widget.selection_present():
                        widget.delete(tk.SEL_FIRST, tk.SEL_LAST)
                except (AttributeError, tk.TclError):
                    pass
                widget.insert(tk.INSERT, clipboard_text)
        except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError):
            pass
        return "break"

    def _fix_cyrillic_clipboard(self):
        """Универсальный и надежный обработчик горячих клавиш без дублей (Win/Linux, RU/EN)"""

        def get_target_widget(event):
            w = event.widget
            if not isinstance(w, (tk.Text, tk.Entry, ttk.Entry)):
                w = self.root.focus_get()
            return w if isinstance(w, (tk.Text, tk.Entry, ttk.Entry)) else None

        def smart_copy(event):
            w = get_target_widget(event)
            if not w:
                return "break"

            text_to_copy = ""
            try:
                if isinstance(w, tk.Text) and w.tag_ranges(tk.SEL):
                    text_to_copy = w.get(tk.SEL_FIRST, tk.SEL_LAST)
                elif isinstance(w, (tk.Entry, ttk.Entry)):
                    if hasattr(w, 'selection_present') and w.selection_present():
                        text_to_copy = w.selection_get()
                    else:
                        sel = w.selection_range()
                        if sel:
                            text_to_copy = w.get()[sel[0]:sel[1]]
            except Exception:
                pass

            if text_to_copy:
                self.root.clipboard_clear()
                self.root.clipboard_append(text_to_copy)
            return "break"

        def smart_cut(event):
            w = get_target_widget(event)
            if not w:
                return "break"

            text_to_copy = ""
            try:
                if isinstance(w, tk.Text) and w.tag_ranges(tk.SEL):
                    text_to_copy = w.get(tk.SEL_FIRST, tk.SEL_LAST)
                    w.delete(tk.SEL_FIRST, tk.SEL_LAST)
                elif isinstance(w, (tk.Entry, ttk.Entry)):
                    if hasattr(w, 'selection_present') and w.selection_present():
                        text_to_copy = w.selection_get()
                        w.delete(tk.SEL_FIRST, tk.SEL_LAST)
                    else:
                        sel = w.selection_range()
                        if sel:
                            start, end = sel
                            text_to_copy = w.get()[start:end]
                            w.delete(start, end)
            except Exception:
                pass

            if text_to_copy:
                self.root.clipboard_clear()
                self.root.clipboard_append(text_to_copy)
            return "break"

        def smart_paste(event):
            return self._paste_clipboard_once(event)

        def smart_select_all(event):
            w = get_target_widget(event)
            if not w:
                return "break"
            try:
                if isinstance(w, tk.Text):
                    w.tag_add(tk.SEL, "1.0", "end-1c")
                    w.mark_set(tk.INSERT, "1.0")
                elif isinstance(w, (tk.Entry, ttk.Entry)):
                    w.selection_range(0, tk.END)
                    w.icursor(tk.END)
            except Exception:
                pass
            return "break"

        def smart_undo_redo(event):
            w = get_target_widget(event)
            if not w:
                return "break"
            if isinstance(w, tk.Text):
                try:
                    if event.state & 0x0001:  # клавиша Shift
                        w.edit_redo()
                    else:
                        w.edit_undo()
                except Exception:
                    pass
            return "break"

        def handle_global_shortcuts(event):
            # Проверяем зажатый Ctrl (маска 0x0004)
            if not (event.state & 0x0004):
                return None

            kc = event.keycode
            char = str(event.char)

            # Коды клавиш (Win: 67, 86, 88, 65, 90 / Linux: 54, 55, 53, 38, 52)
            # + Страховка через ASCII символы управления (\x03, \x16, \x18, \x01, \x1a)
            is_c = kc in (67, 54) or char in ('\x03', 'c', 'с')
            is_v = kc in (86, 55) or char in ('\x16', 'v', 'м')
            is_x = kc in (88, 53) or char in ('\x18', 'x', 'ч')
            is_a = kc in (65, 38) or char in ('\x01', 'a', 'ф')
            is_z = kc in (90, 52) or char in ('\x1a', 'z', 'я')

            if is_c:
                return smart_copy(event)
            elif is_v:
                return smart_paste(event)
            elif is_x:
                return smart_cut(event)
            elif is_a:
                return smart_select_all(event)
            elif is_z:
                return smart_undo_redo(event)

            return None

        # 1. Физические и виртуальное событие ведут в один обработчик.
        # Это сохраняет резервные коды клавиш для кириллицы и исключает двойную
        # вставку, когда Tk также генерирует стандартный <<Paste>>.
        for w_class in ('Text', 'Entry', 'TEntry'):
            self.root.bind_class(w_class, '<<Paste>>', smart_paste)
            self.root.bind_class(w_class, '<Control-v>', smart_paste)
            self.root.bind_class(w_class, '<Control-V>', smart_paste)
            self.root.bind_class(w_class, '<Control-c>', smart_copy)
            self.root.bind_class(w_class, '<Control-C>', smart_copy)
            self.root.bind_class(w_class, '<Control-x>', smart_cut)
            self.root.bind_class(w_class, '<Control-X>', smart_cut)
            self.root.bind_class(w_class, '<Control-a>', smart_select_all)
            self.root.bind_class(w_class, '<Control-A>', smart_select_all)
            self.root.bind_class(w_class, '<Control-z>', smart_undo_redo)
            self.root.bind_class(w_class, '<Control-Z>', smart_undo_redo)

        # 2. Глобальный перехватчик для русской раскладки и нетипичных клавиатур
        self.root.bind("<KeyPress>", handle_global_shortcuts, add="+")

    def get_status_color(self, status="info"):
        """Возвращает цвет статуса для текущего светлого/тёмного оформления."""
        palette = self.STATUS_COLORS_DARK if self._is_dark_appearance else self.STATUS_COLORS_LIGHT
        return palette.get(status, palette["text"])

    def _register_palette_widget(self, widget, status="text"):
        """Запоминает семантический цвет статической подписи для смены темы."""
        self._palette_widget_kinds[widget] = status
        return widget

    def _set_status_label(self, label, text, status="info"):
        """Задаёт текст и семантический цвет, чтобы пережить смену темы."""
        # Прямые итоговые сообщения/статусы заменяют адаптивную строку
        # активности. Очистка здесь не позволяет последующему изменению размера
        # окна вернуть имя последнего обработанного файла после того, как очередь
        # уже перешла в «Ожидание» или показала ошибку.
        if (
            label is getattr(self, "lbl_current_text", None)
            and not getattr(self, "_rendering_source_activity", False)
        ):
            self._source_status_activity = None
        self._status_label_kinds[label] = status
        label.config(text=text, foreground=self.get_status_color(status))

    def _render_compact_label(self, label, full_text=None, *, reserve=0,
                              fallback_chars=72):
        """Рендерит длинную подпись в одну строку по фактической ширине.

        Нижние панели обеих рабочих вкладок не должны увеличивать ширину
        окна из-за пояснения или имени профиля. Полная строка хранится на
        Python-объекте label (``_compact_full_text``), а на экране показывается
        её средне-сокращённая версия. Это позволяет после изменения размера раскрыть
        больше текста и при этом не терять начало/конец имени.
        """
        if label is None:
            return
        if full_text is not None:
            try:
                setattr(label, "_compact_full_text", str(full_text))
            except Exception:
                pass
        try:
            source = getattr(label, "_compact_full_text", "")
        except Exception:
            source = ""
        raw_source = str(source or "")
        source = (
            normalize_display_text(raw_source, fallback="")
            if raw_source.strip()
            else ""
        )
        text = (
            middle_ellipsize(source, max_chars=fallback_chars, fallback="")
            if source
            else ""
        )
        try:
            parent = label.master
            parent_width = int(parent.winfo_width())
            available = max(0, parent_width - int(reserve))
            if available > 1:
                font_name = str(label.cget("font") or "TkDefaultFont")
                try:
                    label_font = tkfont.nametofont(font_name, root=self.root)
                except (AttributeError, tk.TclError):
                    label_font = tkfont.nametofont("TkDefaultFont", root=self.root)
                text = (
                    middle_ellipsize_to_width(
                        source,
                        available,
                        label_font.measure,
                        fallback="",
                    )
                    if source
                    else ""
                )
            # ``wraplength=0`` важен: узкий родитель должен обрезать строку
            # многоточием, а не увеличиваться до второй/третьей строки по вертикали.
            label.configure(text=text, wraplength=0)
        except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError):
            try:
                label.configure(text=text, wraplength=0)
            except (AttributeError, tk.TclError):
                pass

    def _bind_compact_label(self, frame, label, full_text, *, reserve=0,
                            fallback_chars=72):
        """Связывает подпись с изменением размера родительского ряда без переноса строк."""
        if label is None:
            return
        try:
            setattr(label, "_compact_full_text", str(full_text))
        except Exception:
            pass

        def render(_event=None):
            self._render_compact_label(
                label,
                reserve=reserve,
                fallback_chars=fallback_chars,
            )

        try:
            frame.bind("<Configure>", render, add="+")
        except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError):
            pass
        render()

    def _make_collapsible_hint(
        self,
        parent,
        text,
        *,
        title="Подсказка",
        wraplength=680,
        initially_open=False,
        status="muted",
        resize_toplevel=False,
    ):
        """Создаёт компактную раскрываемую подсказку для служебного окна.

        Большие поясняющие тексты полезны, но не должны отнимать высоту у
        списка/редактора.  Поэтому по умолчанию показывается только кнопка
        ``? Подсказка``; полный текст раскрывается по явному клику.  Метод не
        использует всплывающие окна и потому одинаково работает на Aqua,
        Windows и Linux, а переносы вычисляются по фактической ширине строки.

        Возвращается кортеж ``(shell, body, toggle)``.  ``body`` уже
        зарегистрирован в палитре приложения и его можно удалить из
        ``_palette_widget_kinds`` при закрытии модального окна.
        """
        shell = ttk.Frame(parent)
        shell.columnconfigure(0, weight=1)
        state = {"open": bool(initially_open), "closed_height": None}
        toggle = ttk.Button(shell, text=f"? {title}")
        toggle.grid(row=0, column=0, sticky=tk.W)
        body = self._register_palette_widget(
            ttk.Label(
                shell,
                text=normalize_display_text(str(text or ""), fallback=""),
                foreground=self.get_status_color(status),
                wraplength=max(240, int(wraplength)),
                justify=tk.LEFT,
                anchor=tk.W,
            ),
            status,
        )
        body.grid(row=1, column=0, sticky=tk.EW, pady=(3, 0))

        def resize_body(event=None):
            try:
                width = int(getattr(event, "width", 0) or shell.winfo_width())
                if width > 1:
                    body.configure(wraplength=max(240, width - 8))
            except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError):
                pass

        def toggle_hint():
            toplevel = shell.winfo_toplevel()
            previous_height = 0
            if resize_toplevel and isinstance(toplevel, tk.Toplevel):
                try:
                    previous_height = int(toplevel.winfo_height())
                except (AttributeError, tk.TclError, TypeError, ValueError):
                    previous_height = 0
            if not state["open"]:
                state["closed_height"] = previous_height
            state["open"] = not state["open"]
            try:
                if state["open"]:
                    body.grid()
                    toggle.configure(text="? Скрыть подсказку")
                else:
                    body.grid_remove()
                    toggle.configure(text=f"? {title}")
                shell.update_idletasks()
                resize_body()
                if resize_toplevel and isinstance(toplevel, tk.Toplevel):
                    toplevel.update_idletasks()
                    requested_height = int(toplevel.winfo_reqheight())
                    minimum_height = int(toplevel.minsize()[1] or 1)
                    screen_limit = max(
                        minimum_height,
                        int(toplevel.winfo_screenheight()) - 80,
                    )
                    if state["open"]:
                        target_height = max(
                            previous_height,
                            min(requested_height, screen_limit),
                        )
                    else:
                        target_height = max(
                            minimum_height,
                            min(
                                previous_height,
                                max(state["closed_height"] or 0, requested_height),
                            ),
                        )
                    width = int(toplevel.winfo_width())
                    x = int(toplevel.winfo_x())
                    y = min(
                        int(toplevel.winfo_y()),
                        max(0, int(toplevel.winfo_screenheight()) - target_height - 40),
                    )
                    toplevel.geometry(
                        f"{width}x{target_height}+{max(0, x)}+{max(0, y)}"
                    )
            except (AttributeError, RuntimeError, tk.TclError):
                pass

        toggle.configure(command=toggle_hint)
        shell.bind("<Configure>", resize_body, add="+")
        # Диалоги являются transient-окнами и могут закрываться несколькими
        # способами (Применить, Escape, оконный менеджер). Автоматически удаляем
        # зарегистрированную подпись, чтобы последующая смена темы никогда не
        # обращалась к уничтоженному виджету.
        try:
            body.bind(
                "<Destroy>",
                lambda _event: self._palette_widget_kinds.pop(body, None),
                add="+",
            )
        except (AttributeError, tk.TclError, TypeError):
            pass
        if not state["open"]:
            body.grid_remove()
        else:
            toggle.configure(text="? Скрыть подсказку")
        resize_body()
        return shell, body, toggle

    def _template_helper_existing_group_names(self):
        """Возвращает видимые имена групп для предпросмотра нового имени."""
        return tuple(
            str(group.get("name") or "").strip()
            for group in getattr(self, "export_groups", {}).values()
            if isinstance(group, Mapping) and str(group.get("name") or "").strip()
        )

    def _template_helper_source_preview_data(self):
        """Строит небольшой снимок TXT/частей для помощника источников."""
        paths = getattr(self, "_source_path_by_id", {})
        plan_groups = getattr(self, "_source_plan_groups", {})
        book = resolve_source_book_name(getattr(self, "config", {}))
        groups = []
        if plan_groups:
            group_ids = tuple(plan_groups)
            for index, group_id in enumerate(group_ids, 1):
                group = plan_groups.get(group_id, {})
                file_ids = tuple(group.get("file_ids", ()) or ())
                stems = [
                    Path(str(paths[file_id])).stem
                    for file_id in file_ids
                    if file_id in paths
                ]
                name = str(group.get("name") or book).strip() or book
                groups.append((name, stems, index))
        if not groups:
            file_ids = tuple(self._source_tree_file_ids()) if hasattr(self, "_source_tree_file_ids") else tuple(paths)
            stems = [Path(str(paths[file_id])).stem for file_id in file_ids if file_id in paths]
            if stems:
                groups = [(book, stems, 1)]
        total_parts = max(1, len(groups))
        contexts = []
        chapter_groups = []
        offset = 0
        for name, stems, part in groups[:3]:
            first_index = offset + 1
            last_index = offset + max(1, len(stems))
            context = {
                "book": book,
                "name": name,
                "group": name,
                "title": name,
                "source_name": name,
                "source_title": name,
                "filename": stems[0] if stems else name,
                "index": part,
                "chapter": first_index,
                "chapter_count": sum(max(1, len(item[1])) for item in groups),
                "part": part,
                "volume": part,
                "parts": total_parts,
                "first_index": first_index,
                "last_index": last_index,
                "num": part,
                "first": first_index,
                "last": last_index,
                "range": format_chapter_range(first_index, last_index),
                "first_name": stems[0] if stems else name,
                "last_name": stems[-1] if stems else name,
                "format": "m4b",
                "ext": "m4b",
                "profile": "",
                "author": "",
            }
            contexts.append(context)
            chapter_groups.append(
                {
                    "book": book,
                    "group": name,
                    "part": part,
                    "parts": total_parts,
                    "chapter_start": first_index,
                    "chapter_count": sum(max(1, len(item[1])) for item in groups),
                    "global_offset": offset,
                    "chapters": [
                        {
                            "title": stem,
                            "source_name": stem,
                            "source_title": stem,
                        }
                        for stem in stems
                    ],
                }
            )
            offset += len(stems)
        return {"contexts": contexts, "chapter_groups": chapter_groups}

    def _template_helper_export_preview_data(self, format_hint="m4b"):
        """Строит снимок выбранной группы/файла экспорта для помощника."""
        tree = getattr(self, "export_tree", None)
        groups = getattr(self, "export_groups", {})
        files = getattr(self, "export_files", {})
        try:
            selected = tuple(tree.selection()) if tree is not None else ()
        except (AttributeError, tk.TclError):
            selected = ()
        item_id = selected[0] if selected else ""
        if not item_id:
            try:
                roots = tuple(tree.get_children("")) if tree is not None else ()
                item_id = roots[0] if roots else ""
            except (AttributeError, tk.TclError):
                item_id = ""
        if item_id in groups:
            group = dict(groups.get(item_id) or {})
            try:
                children = tuple(tree.get_children(item_id))
            except (AttributeError, tk.TclError):
                children = ()
            records = [normalize_export_file_record(files[file_id]) for file_id in children if file_id in files]
            name = str(group.get("name") or "Группа").strip() or "Группа"
        elif item_id in files:
            group = {}
            records = [normalize_export_file_record(files[item_id])]
            name = effective_export_file_title(records[0]) if records else "Аудиофайл"
        else:
            return {}
        format_hint = str(format_hint or "m4b").strip().lower().lstrip(".") or "m4b"
        stems = [str(record.get("source_name") or Path(record["path"]).stem) for record in records]
        file_contexts = []
        for index, record in enumerate(records, 1):
            physical_stem = Path(record["path"]).stem
            title = effective_export_file_title(record)
            file_contexts.append(
                {
                    "book": name,
                    "name": title,
                    "group": name,
                    "title": title,
                    "source_name": str(record.get("source_name") or physical_stem),
                    "source_title": str(record.get("source_title") or title),
                    "filename": physical_stem,
                    "index": index,
                    "chapter": index,
                    "chapter_count": len(records) or 1,
                    "range": str(index),
                    "format": format_hint,
                    "ext": format_hint,
                    "profile": "",
                    "author": str(record.get("artist") or group.get("artist") or ""),
                }
            )
        contexts = [{
            "book": name,
            "name": name,
            "group": name,
            "title": name,
            "source_name": name if len(records) > 1 else (stems[0] if stems else name),
            "source_title": str(group.get("source_title") or name),
            "filename": stems[0] if stems else name,
            "index": 1,
            "chapter": 1,
            "chapter_count": len(records) or 1,
            "part": 1,
            "volume": 1,
            "parts": 1,
            "first_index": 1,
            "last_index": len(records) or 1,
            "num": 1,
            "first": 1,
            "last": len(records) or 1,
            "range": format_chapter_range(1, len(records) or 1),
            "first_name": stems[0] if stems else name,
            "last_name": stems[-1] if stems else name,
            "format": format_hint,
            "ext": format_hint,
            "profile": "",
            "author": str(group.get("artist") or ""),
        }]
        chapters = [{
            "title": effective_export_file_title(record),
            "source_name": str(record.get("source_name") or ""),
            "source_title": str(record.get("source_title") or ""),
            "path": record.get("path", ""),
        } for record in records]
        return {
            "contexts": contexts,
            "file_contexts": file_contexts,
            "chapter_groups": [{
                "book": name,
                "group": name,
                "part": 1,
                "parts": 1,
                "chapter_start": 1,
                "chapter_count": len(chapters) or 1,
                "chapters": chapters,
            }],
        }

    def _open_template_helper(
        self,
        target_var,
        context_kind,
        *,
        owner=None,
        target_entry=None,
        title="Помощник шаблона",
        book_names=(),
        single_file=False,
        preview_data=None,
        existing_names=(),
    ):
        """Редактирует строку шаблона с живым предпросмотром результата."""
        owner = owner or self.root
        spec = template_helper_context(context_kind)
        previous_grab = None
        try:
            previous_grab = self.root.grab_current()
        except tk.TclError:
            pass

        dialog = tk.Toplevel(self.root)
        dialog.withdraw()
        dialog.title(title)
        dialog.transient(owner)
        dialog.grab_set()
        dialog.resizable(True, True)

        template_var = tk.StringVar(master=dialog, value=str(target_var.get() or ""))
        field_var = tk.StringVar(master=dialog)
        start_enabled_var = tk.BooleanVar(master=dialog, value=False)
        start_number_var = tk.StringVar(master=dialog, value="1")
        width_enabled_var = tk.BooleanVar(master=dialog, value=False)
        width_number_var = tk.StringVar(master=dialog, value="3")
        adaptive_width_var = tk.BooleanVar(master=dialog, value=False)
        preset_var = tk.StringVar(master=dialog)

        body = ttk.Frame(dialog, padding=12)
        body.pack(fill=tk.BOTH, expand=True)
        body.columnconfigure(0, weight=1)
        body.rowconfigure(5, weight=1)

        ttk.Label(body, text="Шаблон:").grid(row=0, column=0, sticky=tk.W)
        template_entry = ttk.Entry(body, textvariable=template_var)
        template_entry.grid(row=1, column=0, sticky=tk.EW, pady=(3, 8))

        staged_presets = {
            "value": normalize_template_helper_presets(
                self.config.get("template_helper_presets", {})
            ),
            "dirty": False,
        }
        preset_by_label = {}
        preset_row = ttk.Frame(body)
        preset_row.grid(row=2, column=0, sticky=tk.EW, pady=(0, 8))
        preset_row.columnconfigure(1, weight=1)
        ttk.Label(preset_row, text="Готовый вариант:").grid(
            row=0, column=0, sticky=tk.W, padx=(0, 8)
        )
        preset_combo = ttk.Combobox(
            preset_row,
            textvariable=preset_var,
            values=tuple(preset_by_label),
            state="readonly",
        )
        preset_combo.grid(row=0, column=1, sticky=tk.EW)

        def use_preset():
            selected = preset_by_label.get(preset_var.get())
            if selected is None:
                return
            template_var.set(selected["template"])
            template_entry.icursor(tk.END)
            template_entry.focus_set()

        preset_actions = ttk.Frame(preset_row)
        preset_actions.grid(row=1, column=1, sticky=tk.E, pady=(5, 0))
        ttk.Button(preset_actions, text="Подставить", command=use_preset).pack(
            side=tk.LEFT
        )
        save_preset_button = ttk.Button(
            preset_actions,
            text="Сохранить вариант…",
        )
        save_preset_button.pack(side=tk.LEFT, padx=(6, 0))
        delete_preset_button = ttk.Button(
            preset_actions,
            text="Удалить",
            state=tk.DISABLED,
        )
        delete_preset_button.pack(side=tk.LEFT, padx=(6, 0))

        def refresh_preset_choices(selected_name=None):
            entries = template_helper_preset_entries(
                context_kind,
                staged_presets["value"],
            )
            preset_by_label.clear()
            preset_by_label.update({entry["name"]: entry for entry in entries})
            labels = tuple(preset_by_label)
            preset_combo.configure(values=labels)
            if selected_name in preset_by_label:
                preset_var.set(selected_name)
            elif preset_var.get() not in preset_by_label:
                preset_var.set(labels[0] if labels else "")
            selected = preset_by_label.get(preset_var.get())
            delete_preset_button.configure(
                state=(
                    tk.NORMAL
                    if selected is not None and not selected["builtin"]
                    else tk.DISABLED
                )
            )

        initial_entries = template_helper_preset_entries(
            context_kind,
            staged_presets["value"],
        )
        if initial_entries:
            current_template = template_var.get()
            matching = next(
                (
                    entry["name"]
                    for entry in initial_entries
                    if entry["template"] == current_template
                ),
                initial_entries[0]["name"],
            )
            refresh_preset_choices(matching)

        field_frame = ttk.LabelFrame(body, text="Добавить поле", padding=8)
        field_frame.grid(row=3, column=0, sticky=tk.EW, pady=(0, 8))
        field_frame.columnconfigure(0, weight=1)

        field_display_to_name = {
            f"{label} — {{{field}}}": field
            for field, label, _description in spec["fields"]
        }
        field_description = {
            field: description
            for field, _label, description in spec["fields"]
        }
        field_name_to_display = {
            field: display for display, field in field_display_to_name.items()
        }
        field_combo = ttk.Combobox(
            field_frame,
            textvariable=field_var,
            values=tuple(field_display_to_name),
            state="readonly",
        )
        field_combo.grid(
            row=0,
            column=0,
            columnspan=3,
            sticky=tk.EW,
            padx=(0, 8),
        )

        counter_options = ttk.Frame(field_frame)
        counter_options.grid(
            row=1,
            column=0,
            columnspan=3,
            sticky=tk.W,
            padx=(0, 8),
            pady=(5, 0),
        )
        start_check = ttk.Checkbutton(
            counter_options,
            text="Начать с:",
            variable=start_enabled_var,
        )
        start_check.pack(side=tk.LEFT)
        start_spin = ttk.Spinbox(
            counter_options,
            textvariable=start_number_var,
            from_=0,
            to=999999,
            width=7,
        )
        start_spin.pack(side=tk.LEFT, padx=(3, 10))
        width_check = ttk.Checkbutton(
            counter_options,
            text="Разрядность:",
            variable=width_enabled_var,
        )
        width_check.pack(side=tk.LEFT)
        width_spin = ttk.Spinbox(
            counter_options,
            textvariable=width_number_var,
            from_=1,
            to=9,
            width=3,
        )
        width_spin.pack(side=tk.LEFT, padx=(3, 0))
        adaptive_check = ttk.Checkbutton(
            counter_options,
            text="Адаптивно",
            variable=adaptive_width_var,
        )
        adaptive_check.pack(side=tk.LEFT, padx=(10, 0))
        insert_button = ttk.Button(field_frame, text="Вставить")
        insert_button.grid(row=0, column=3, rowspan=2, sticky=tk.E)

        field_hint = self._register_palette_widget(
            ttk.Label(
                field_frame,
                text="",
                foreground=self.get_status_color("muted"),
                justify=tk.LEFT,
                anchor=tk.W,
            ),
            "muted",
        )
        field_hint.grid(row=2, column=0, columnspan=4, sticky=tk.EW, pady=(5, 0))

        preview_frame = ttk.LabelFrame(body, text="Пример результата", padding=8)
        preview_frame.grid(row=5, column=0, sticky=tk.NSEW)
        preview_frame.columnconfigure(0, weight=1)
        preview_frame.rowconfigure(0, weight=1)
        preview_list = tk.Listbox(
            preview_frame,
            height=4,
            exportselection=False,
            activestyle="none",
        )
        preview_list.grid(row=0, column=0, sticky=tk.NSEW)
        preview_y_scroll = ttk.Scrollbar(
            preview_frame,
            orient=tk.VERTICAL,
            command=preview_list.yview,
        )
        preview_y_scroll.grid(row=0, column=1, sticky=tk.NS)
        preview_scroll = ttk.Scrollbar(
            preview_frame,
            orient=tk.HORIZONTAL,
            command=preview_list.xview,
        )

        def update_preview_scroll(first, last):
            preview_scroll.set(first, last)
            if float(first) > 0.0 or float(last) < 1.0:
                preview_scroll.grid(row=1, column=0, sticky=tk.EW)
            else:
                preview_scroll.grid_remove()

        preview_list.configure(
            xscrollcommand=update_preview_scroll,
            yscrollcommand=preview_y_scroll.set,
        )
        preview_scroll.grid(row=1, column=0, sticky=tk.EW)
        preview_scroll.grid_remove()

        status_label = self._register_palette_widget(
            ttk.Label(
                body,
                text="",
                foreground=self.get_status_color("muted"),
                justify=tk.LEFT,
                anchor=tk.W,
                wraplength=660,
            ),
            "muted",
        )
        status_label.grid(row=6, column=0, sticky=tk.EW, pady=(6, 0))

        def update_preset_actions(*_args):
            selected = preset_by_label.get(preset_var.get())
            delete_preset_button.configure(
                state=(
                    tk.NORMAL
                    if selected is not None and not selected["builtin"]
                    else tk.DISABLED
                )
            )

        def save_current_preset():
            try:
                render_template_helper_preview(
                    context_kind,
                    template_var.get(),
                    book_names=book_names,
                    single_file=single_file,
                    preview_data={
                        **dict(preview_data or {}),
                        "existing_names": tuple(existing_names),
                    },
                )
            except (TemplateError, ValueError, KeyError, TypeError) as exc:
                self._set_status_label(status_label, str(exc), "error")
                return
            initial_name = preset_var.get()
            selected = preset_by_label.get(initial_name)
            if selected is not None and selected["builtin"]:
                initial_name = ""
            name = simpledialog.askstring(
                "Сохранить готовый вариант",
                "Название варианта:",
                initialvalue=initial_name,
                parent=dialog,
            )
            if name is None:
                return
            normalized_name = re.sub(r"\s+", " ", str(name)).strip()
            existing = next(
                (
                    entry
                    for entry in template_helper_preset_entries(
                        context_kind,
                        staged_presets["value"],
                    )
                    if not entry["builtin"]
                    and entry["name"].casefold() == normalized_name.casefold()
                ),
                None,
            )
            if existing is not None and not messagebox.askyesno(
                "Заменить готовый вариант",
                f"Вариант «{existing['name']}» уже существует. Заменить его?",
                parent=dialog,
            ):
                return
            try:
                staged_presets["value"] = save_template_helper_preset(
                    staged_presets["value"],
                    context_kind,
                    normalized_name,
                    template_var.get(),
                )
            except TemplateError as exc:
                self._set_status_label(status_label, str(exc), "error")
                return
            staged_presets["dirty"] = True
            refresh_preset_choices(normalized_name)
            self._set_status_label(
                status_label,
                "Вариант подготовлен. Нажмите «Применить», чтобы сохранить изменения.",
                "success",
            )

        def delete_selected_preset():
            selected = preset_by_label.get(preset_var.get())
            if selected is None or selected["builtin"]:
                return
            try:
                staged_presets["value"] = delete_template_helper_preset(
                    staged_presets["value"],
                    context_kind,
                    selected["name"],
                )
            except TemplateError as exc:
                self._set_status_label(status_label, str(exc), "error")
                return
            staged_presets["dirty"] = True
            refresh_preset_choices()
            self._set_status_label(
                status_label,
                "Удаление подготовлено. Нажмите «Применить», чтобы сохранить изменения.",
                "warning",
            )

        save_preset_button.configure(command=save_current_preset)
        delete_preset_button.configure(command=delete_selected_preset)
        preset_var.trace_add("write", update_preset_actions)

        def resize_helper_text(event=None):
            try:
                width = int(getattr(event, "width", 0) or body.winfo_width())
                # Оставляем запас под внутренние отступы и границу Label:
                # на Aqua перенос ровно по ширине родителя обрезал последнюю
                # букву строки в компактном окне.
                wraplength = max(240, width - 24)
                status_label.configure(wraplength=wraplength)
                field_hint.configure(wraplength=wraplength)
            except (AttributeError, tk.TclError, TypeError, ValueError):
                pass

        body.bind("<Configure>", resize_helper_text, add="+")

        buttons = ttk.Frame(body)
        buttons.grid(row=7, column=0, sticky=tk.EW, pady=(10, 0))
        apply_button = ttk.Button(buttons, text="Применить")
        apply_button.pack(side=tk.RIGHT)

        closed = {"value": False}

        def close_dialog():
            if closed["value"]:
                return
            closed["value"] = True
            try:
                dialog.grab_release()
            except tk.TclError:
                pass
            try:
                dialog.destroy()
            except tk.TclError:
                pass
            if previous_grab is not None and previous_grab is not dialog:
                try:
                    if previous_grab.winfo_exists():
                        previous_grab.grab_set()
                        previous_grab.lift()
                except (AttributeError, tk.TclError):
                    pass
            focus_target = target_entry or owner
            try:
                if focus_target.winfo_exists():
                    focus_target.focus_set()
            except (AttributeError, tk.TclError):
                pass

        ttk.Button(buttons, text="Отмена", command=close_dialog).pack(
            side=tk.RIGHT, padx=(0, 6)
        )

        def selected_field_name():
            return field_display_to_name.get(field_var.get(), "")

        def update_field_controls(*_args):
            field_name = selected_field_name()
            supports_start = field_name in spec["start_fields"]
            supports_width = field_name in spec["width_fields"]
            if not supports_start and start_enabled_var.get():
                start_enabled_var.set(False)
            if not supports_width and width_enabled_var.get():
                width_enabled_var.set(False)
            if not supports_width and adaptive_width_var.get():
                adaptive_width_var.set(False)
            if adaptive_width_var.get() and width_enabled_var.get():
                width_enabled_var.set(False)
            try:
                start_check.configure(
                    state=tk.NORMAL if supports_start else tk.DISABLED
                )
                start_spin.configure(
                    state=(
                        tk.NORMAL
                        if supports_start and start_enabled_var.get()
                        else tk.DISABLED
                    )
                )
                width_check.configure(
                    state=(
                        tk.NORMAL
                        if supports_width and not adaptive_width_var.get()
                        else tk.DISABLED
                    )
                )
                width_spin.configure(
                    state=(
                        tk.NORMAL
                        if supports_width
                        and width_enabled_var.get()
                        and not adaptive_width_var.get()
                        else tk.DISABLED
                    )
                )
                adaptive_check.configure(
                    state=tk.NORMAL if supports_width else tk.DISABLED
                )
            except tk.TclError:
                pass
            description = field_description.get(field_name, "")
            try:
                token = build_template_helper_token(
                    context_kind,
                    field_name,
                    start=(start_number_var.get() if start_enabled_var.get() else None),
                    width=(width_number_var.get() if width_enabled_var.get() else None),
                    adaptive=adaptive_width_var.get(),
                )
                suffix = f". Будет вставлено: {token}."
            except TemplateError as exc:
                suffix = f". Ошибка: {exc}."
            field_hint.configure(
                text=(description.rstrip(".!?…") + suffix).strip()
            )

        def insert_field():
            field_name = selected_field_name()
            try:
                token = build_template_helper_token(
                    context_kind,
                    field_name,
                    start=(start_number_var.get() if start_enabled_var.get() else None),
                    width=(width_number_var.get() if width_enabled_var.get() else None),
                    adaptive=adaptive_width_var.get(),
                )
            except TemplateError as exc:
                self._set_status_label(status_label, str(exc), "error")
                return
            try:
                if template_entry.selection_present():
                    first = template_entry.index(tk.SEL_FIRST)
                    last = template_entry.index(tk.SEL_LAST)
                    template_entry.delete(first, last)
                    template_entry.insert(first, token)
                    template_entry.icursor(first + len(token))
                else:
                    cursor = template_entry.index(tk.INSERT)
                    template_entry.insert(cursor, token)
                    template_entry.icursor(cursor + len(token))
            except tk.TclError:
                template_var.set(template_var.get() + token)
                template_entry.icursor(tk.END)
            template_entry.focus_set()

        insert_button.configure(command=insert_field)

        def refresh_preview(*_args):
            preview_list.delete(0, tk.END)
            try:
                examples = render_template_helper_preview(
                    context_kind,
                    template_var.get(),
                    book_names=book_names,
                    single_file=single_file,
                    preview_data={
                        **dict(preview_data or {}),
                        "existing_names": tuple(existing_names),
                    },
                )
            except (TemplateError, ValueError, KeyError, TypeError) as exc:
                preview_list.insert(tk.END, "Исправьте шаблон, чтобы увидеть пример.")
                self._set_status_label(status_label, str(exc), "error")
                apply_button.configure(state=tk.DISABLED)
                return
            for index, example in enumerate(examples, 1):
                preview_list.insert(tk.END, f"{index}. {example}")
            self._set_status_label(
                status_label,
                (
                    "Шаблон корректен. Это пример: фактические названия глав "
                    "и суффиксы совпадений зависят от исходных файлов."
                    if context_kind == "book_import"
                    else "Шаблон корректен; пример построен рабочим рендерером."
                ),
                "success",
            )
            apply_button.configure(state=tk.NORMAL)
            try:
                preview_list.xview_moveto(0.0)
            except tk.TclError:
                pass

        def apply_template():
            if str(apply_button.cget("state")) == str(tk.DISABLED):
                return
            previous_template = str(target_var.get() or "")
            previous_presets = copy.deepcopy(
                self.config.get("template_helper_presets", {})
            )
            target_var.set(template_var.get())
            if staged_presets["dirty"]:
                self.config["template_helper_presets"] = copy.deepcopy(
                    staged_presets["value"]
                )
                if not self.save_settings():
                    target_var.set(previous_template)
                    self.config["template_helper_presets"] = previous_presets
                    self._set_status_label(
                        status_label,
                        "Не удалось сохранить готовые варианты в settings.json.",
                        "error",
                    )
                    return
            close_dialog()

        apply_button.configure(command=apply_template)
        template_var.trace_add("write", refresh_preview)
        field_var.trace_add("write", update_field_controls)
        start_enabled_var.trace_add("write", update_field_controls)
        start_number_var.trace_add("write", update_field_controls)
        width_enabled_var.trace_add("write", update_field_controls)
        width_number_var.trace_add("write", update_field_controls)
        adaptive_width_var.trace_add("write", update_field_controls)
        if field_display_to_name:
            first_field = next(iter(field_display_to_name.values()))
            field_var.set(field_name_to_display[first_field])
        update_field_controls()
        refresh_preview()

        dialog.protocol("WM_DELETE_WINDOW", close_dialog)
        dialog.bind("<Escape>", lambda _event: close_dialog())
        dialog.bind("<Control-Return>", lambda _event: apply_template())
        dialog.bind("<Command-Return>", lambda _event: apply_template())
        try:
            dialog.minsize(560, 450)
        except tk.TclError:
            pass
        self._center_popup(
            dialog,
            720,
            500,
            fit_screen=True,
            owner=owner,
        )
        resize_helper_text()
        template_entry.focus_set()
        template_entry.icursor(tk.END)

    def _post_status_label(self, label, text, status="info"):
        """Потокобезопасный вариант ``_set_status_label()``."""
        self._post_to_ui(self._set_status_label, label, text, status)

    def _render_export_activity_status(self):
        """Подгоняет рабочий статус под текущую ширину окна и шрифт."""
        activity = getattr(self, "_export_status_activity", None)
        label = getattr(self, "lbl_export_status", None)
        if not activity or label is None:
            return
        action, subject, status = activity
        prefix = f"{normalize_display_text(action, fallback='Обработка')}: "
        text = format_export_activity_status(action, subject)
        try:
            frame_width = int(label.master.winfo_width())
            if frame_width > 1:
                max_text_width = min(
                    max(80, int(frame_width * 0.58)),
                    max(20, frame_width - 20),
                )
                font_name = str(label.cget("font") or "TkDefaultFont")
                try:
                    label_font = tkfont.nametofont(font_name, root=self.root)
                except tk.TclError:
                    label_font = tkfont.nametofont(
                        "TkDefaultFont", root=self.root
                    )
                subject_width = max(
                    8, max_text_width - label_font.measure(prefix)
                )
                # Счётчик готовых результатов важнее имени и этапа. Для пула
                # рядом сохраняется ``активно: K``; последовательная ветка
                # оставляет только ``Готово N/T``. Многоточие применяется к
                # оставшейся части, поэтому узкое окно не скрывает прогресс.
                progress_parts = str(subject).split(" · ")
                if (
                    len(progress_parts) >= 2
                    and progress_parts[0].startswith("Готово ")
                ):
                    fixed_parts = [progress_parts.pop(0)]
                    if (
                        progress_parts
                        and progress_parts[0].startswith("активно: ")
                    ):
                        fixed_parts.append(progress_parts.pop(0))
                    counters = " · ".join(fixed_parts)
                    detail = " · ".join(progress_parts)
                    counters_with_separator = (
                        counters + " · " if detail else counters
                    )
                    detail_width = (
                        subject_width
                        - label_font.measure(counters_with_separator)
                    )
                    if detail and detail_width > label_font.measure("…"):
                        fitted_subject = (
                            counters_with_separator
                            + middle_ellipsize_to_width(
                                detail,
                                detail_width,
                                label_font.measure,
                            )
                        )
                    else:
                        fitted_subject = middle_ellipsize_to_width(
                            counters,
                            subject_width,
                            label_font.measure,
                        )
                else:
                    fitted_subject = middle_ellipsize_to_width(
                        subject,
                        subject_width,
                        label_font.measure,
                    )
                text = prefix + fitted_subject
        except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError):
            # До первого показа окна или во время его закрытия достаточно
            # консервативного ограничения по символам.
            pass
        self._set_status_label(label, text, status)

    def _set_export_activity_status(self, action, subject, status="warning"):
        """Показывает имя без изменения ``title``, тегов или выходного пути."""
        self._export_status_activity = (action, subject, status)
        self._render_export_activity_status()

    def _render_source_activity_status(self):
        """Подгоняет статус синтеза под доступную ширину без потери конца имени."""
        activity = getattr(self, "_source_status_activity", None)
        label = getattr(self, "lbl_current_text", None)
        if not activity or label is None:
            return
        action, subject, status = activity
        prefix = f"{normalize_display_text(action, fallback='Обработка')}: "
        text = prefix + normalize_display_text(subject, fallback="Ожидание...")
        try:
            frame_width = int(label.master.winfo_width())
            if frame_width > 1:
                max_text_width = max(80, frame_width - 20)
                font_name = str(label.cget("font") or "TkDefaultFont")
                try:
                    label_font = tkfont.nametofont(font_name, root=self.root)
                except tk.TclError:
                    label_font = tkfont.nametofont(
                        "TkDefaultFont", root=self.root
                    )
                subject_width = max(
                    8, max_text_width - label_font.measure(prefix)
                )
                fitted_subject = middle_ellipsize_to_width(
                    subject,
                    subject_width,
                    label_font.measure,
                )
                text = prefix + fitted_subject
        except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError):
            text = prefix + middle_ellipsize(subject, max_chars=120)
        self._rendering_source_activity = True
        try:
            self._set_status_label(label, text, status)
        finally:
            self._rendering_source_activity = False

    def _set_source_activity_status(self, action, subject, status="info"):
        """Запоминает полный статус, чтобы перерисовать его после изменения размера."""
        self._source_status_activity = (action, subject, status)
        self._render_source_activity_status()

    def _post_export_activity_status(self, action, subject, status="warning"):
        """Потокобезопасно публикует рабочий статус экспорта."""
        self._post_to_ui(
            self._set_export_activity_status, action, subject, status
        )

    def _set_export_status(self, text, status="info"):
        """Устанавливает обычный статус и отменяет адаптивное имя операции."""
        self._export_status_activity = None
        self._set_status_label(self.lbl_export_status, text, status)

    def _post_export_status(self, text, status="info"):
        """Потокобезопасный вариант ``_set_export_status()``."""
        self._post_to_ui(self._set_export_status, text, status)

    def _detect_dark_appearance(self):
        """Безопасно определяет системную тёмную тему, не вызывая AppKit."""
        if sys.platform != "darwin":
            return False

        # Новые сборки Tk для Aqua возвращают эффективную тему окна напрямую.
        # На старом Tk 8.6 атрибут отсутствует и даёт обычный TclError.
        try:
            return bool(int(self.root.tk.call("wm", "attributes", self.root._w, "-isdark")))
        except (tk.TclError, TypeError, ValueError):
            pass

        # Запасной вариант для Tk 8.6/9: системный семантический цвет разрешается
        # с учётом оформления именно этого окна. Внешний процесс и AppKit не нужны.
        for color_name in (
            "systemWindowBackgroundColor",
            self.root.cget("background"),
        ):
            try:
                red, green, blue = self.root.winfo_rgb(color_name)
                # Простая яркость здесь нужна лишь для двоичной классификации,
                # а не для расчёта WCAG-контраста самих статусных цветов.
                brightness = (0.2126 * red + 0.7152 * green + 0.0722 * blue) / 65535
                return brightness < 0.5
            except (tk.TclError, TypeError, ValueError):
                continue
        return False

    def _check_system_appearance(self, *, reschedule=True):
        """Обновляет статусные цвета при смене темы macOS на лету."""
        if reschedule:
            self._appearance_check_after_id = None
        if self._is_closing:
            return

        is_dark = self._detect_dark_appearance()
        if is_dark != self._is_dark_appearance:
            self._is_dark_appearance = is_dark
            self._refresh_status_colors()
            # Tk 9 обычно обновляет нативные элементы управления сам, но принудительная
            # рассылка нужна для уже открытых/недавно восстановленных окон.
            self._invalidate_mac_aqua_widgets()

        if reschedule:
            try:
                self._appearance_check_after_id = self.root.after(
                    1500, self._check_system_appearance
                )
            except tk.TclError:
                pass

    def reset_global_fx(self):
        """Сброс эффектов во вкладке Настройки к дефолтным значениям"""
        if "fx_speed" in self.settings_vars: self.settings_vars["fx_speed"].set(1.0)
        if "fx_pitch" in self.settings_vars: self.settings_vars["fx_pitch"].set(1.0)
        if "fx_echo" in self.settings_vars: self.settings_vars["fx_echo"].set(False)
        if "fx_echo_delay" in self.settings_vars: self.settings_vars["fx_echo_delay"].set(300)
        if "fx_echo_decay" in self.settings_vars: self.settings_vars["fx_echo_decay"].set(0.3)

        if hasattr(self, 'lbl_speed_val'): self.lbl_speed_val.config(text="1.0x")
        if hasattr(self, 'lbl_pitch_val'): self.lbl_pitch_val.config(text="1.00")
        if hasattr(self, 'lbl_delay_val'): self.lbl_delay_val.config(text="300мс")
        if hasattr(self, 'lbl_decay_val'): self.lbl_decay_val.config(text="0.3")

        self.save_settings()
        self._show_info("Успех", "Глобальные эффекты сброшены по умолчанию!")

    def _natural_sort_key(self, text):
        """Ключ для сортировки файлов человеком, а не машиной (Глава 2 будет перед Глава 10)"""
        return [int(c) if c.isdigit() else c.lower() for c in re.split(r'(\d+)', str(text))]

    @staticmethod
    def _persistent_export_cover(cover_path, *, destination_dir=None):
        """Копирует временную обложку импорта в каталог сохранённого проекта."""
        raw_path = str(cover_path or "").strip()
        if not raw_path:
            return ""
        source = Path(raw_path).expanduser()
        if not source.is_file():
            return raw_path
        try:
            source.resolve().relative_to(SESSION_TEMP_DIR.resolve())
        except (OSError, RuntimeError, ValueError):
            return raw_path

        try:
            digest = hashlib.sha256(source.read_bytes()).hexdigest()
            suffix = source.suffix.lower()
            if suffix not in {".jpg", ".jpeg", ".png"}:
                suffix = ".jpg"
            cover_dir = Path(destination_dir or EXPORT_PROJECT_COVERS_DIR)
            cover_dir.mkdir(parents=True, exist_ok=True)
            destination = cover_dir / f"{digest}{suffix}"
            if not destination.exists():
                temp_path = destination.with_name(
                    f".{destination.name}.{uuid.uuid4().hex}.tmp"
                )
                try:
                    shutil.copy2(source, temp_path)
                    os.replace(temp_path, destination)
                finally:
                    temp_path.unlink(missing_ok=True)
            return str(destination)
        except (OSError, RuntimeError) as exc:
            logging.warning(
                "Не удалось сохранить обложку проекта экспорта %s: %s",
                source,
                exc,
            )
            return raw_path

    def _build_export_project_snapshot(self):
        """Создаёт переносимый снимок видимого дерева и устойчивых обложек."""
        groups = copy.deepcopy(getattr(self, "export_groups", {}))
        files = copy.deepcopy(getattr(self, "export_files", {}))
        for settings in (*groups.values(), *files.values()):
            if isinstance(settings, dict) and settings.get("cover"):
                settings["cover"] = self._persistent_export_cover(
                    settings["cover"]
                )
        root_items = tuple(self.export_tree.get_children(""))
        group_children = {
            group_id: tuple(self.export_tree.get_children(group_id))
            for group_id in groups
            if self.export_tree.exists(group_id)
        }
        return build_export_project_session(
            root_items,
            group_children,
            groups,
            files,
        )

    def _save_export_project_session(self):
        """Атомарно сохраняет дерево вкладки «Экспорт и сборка»."""
        self._export_session_save_after_id = None
        if (
            getattr(self, "_restoring_export_project_session", False)
            or getattr(self, "_is_closing", False)
            or not hasattr(self, "export_tree")
        ):
            return True
        if (
            getattr(self, "_export_project_explicitly_cleared", False)
            and not self.export_tree.get_children("")
        ):
            return True
        try:
            self._write_json_atomic(
                EXPORT_PROJECT_FILE,
                self._build_export_project_snapshot(),
                backup=True,
            )
            return True
        except Exception:
            logging.exception("Не удалось сохранить проект экспорта")
            return False

    def _schedule_export_project_save(self, *_args):
        """Объединяет частые изменения полей в одну запись проекта."""
        if (
            getattr(self, "_restoring_export_project_session", False)
            or getattr(self, "_is_closing", False)
            or not hasattr(self, "root")
        ):
            return
        self._export_project_explicitly_cleared = False
        pending = getattr(self, "_export_session_save_after_id", None)
        if pending is not None:
            try:
                self.root.after_cancel(pending)
            except tk.TclError:
                pass
        try:
            self._export_session_save_after_id = self.root.after(
                350,
                self._save_export_project_session,
            )
        except tk.TclError:
            self._export_session_save_after_id = None

    def _delete_export_project_session(self):
        """Удаляет снимки только после явного действия «Очистить всё»."""
        pending = getattr(self, "_export_session_save_after_id", None)
        if pending is not None:
            try:
                self.root.after_cancel(pending)
            except tk.TclError:
                pass
            self._export_session_save_after_id = None
        for path in (
            EXPORT_PROJECT_FILE,
            EXPORT_PROJECT_FILE.with_suffix(EXPORT_PROJECT_FILE.suffix + ".bak"),
        ):
            try:
                path.unlink(missing_ok=True)
            except OSError as exc:
                logging.warning("Не удалось удалить снимок экспорта %s: %s", path, exc)
        try:
            if EXPORT_PROJECT_COVERS_DIR.is_dir():
                shutil.rmtree(EXPORT_PROJECT_COVERS_DIR)
        except OSError as exc:
            logging.warning(
                "Не удалось удалить сохранённые обложки проекта экспорта: %s",
                exc,
            )

    def _restore_export_project_session(self):
        """Восстанавливает последний список экспорта без обращения к аудио."""
        candidates = (
            EXPORT_PROJECT_FILE,
            EXPORT_PROJECT_FILE.with_suffix(EXPORT_PROJECT_FILE.suffix + ".bak"),
        )
        project = None
        loaded_from = None
        for candidate in candidates:
            if not candidate.is_file():
                continue
            try:
                with open(candidate, "r", encoding="utf-8-sig") as file:
                    project = normalize_export_project_session(json.load(file))
                loaded_from = candidate
                break
            except Exception as exc:
                logging.warning(
                    "Не удалось прочитать проект экспорта %s: %s",
                    candidate,
                    exc,
                )
        if project is None:
            return

        self._restoring_export_project_session = True
        missing_sources = set()
        try:
            for item in project["items"]:
                if item["kind"] == "group":
                    group_id = f"group_{uuid.uuid4().hex[:8]}"
                    settings = copy.deepcopy(item["settings"])
                    settings.setdefault("name", "Группа")
                    settings.setdefault("merge", True)
                    settings.setdefault("subfolder", True)
                    settings.setdefault("pause", 0)
                    self.export_groups[group_id] = settings
                    self.export_tree.insert(
                        "",
                        tk.END,
                        iid=group_id,
                        text=str(settings.get("name") or "Группа"),
                        values=("00:00", ""),
                        open=True,
                    )
                    parent_id = group_id
                    records = item["files"]
                else:
                    parent_id = ""
                    records = (item["settings"],)

                for raw_record in records:
                    record = normalize_export_file_record(raw_record)
                    file_id = f"file_{uuid.uuid4().hex[:8]}"
                    self.export_files[file_id] = record
                    self.export_tree.insert(
                        parent_id,
                        tk.END,
                        iid=file_id,
                        text=export_file_source_label(record),
                        values=(
                            self.format_duration(record.get("duration", 0)),
                            str(record.get("title", "")),
                        ),
                    )
                    if not Path(record["path"]).is_file():
                        missing_sources.add(record["path"])

                if parent_id:
                    self.update_group_duration(parent_id)

            self.update_total_export_duration()
            self._refresh_export_tree_action_states()
            if loaded_from != EXPORT_PROJECT_FILE:
                try:
                    self._write_json_atomic(EXPORT_PROJECT_FILE, project)
                except Exception as exc:
                    logging.warning(
                        "Не удалось восстановить основной снимок экспорта: %s",
                        exc,
                    )
        finally:
            self._restoring_export_project_session = False
        if missing_sources:
            logging.warning(
                "В восстановленном проекте экспорта пока недоступно файлов: %s. "
                "Записи сохранены на случай подключения внешнего диска.",
                len(missing_sources),
            )

    def _sort_export_tree(self, col, reverse):
        """Натуральная сортировка дерева экспорта (Глава 2 будет перед Глава 10)"""
        if getattr(self, "_export_lock", False) or getattr(self, "_export_running", False):
            return
        def sort_key(item_id):
            if col == "#0":
                value = self.export_tree.item(item_id, "text")
            else:
                value = self.export_tree.set(item_id, col)
            if col == "duration":
                seconds = 0
                for part in str(value).split(":"):
                    try:
                        seconds = seconds * 60 + int(part)
                    except (TypeError, ValueError):
                        return 0
                return seconds
            return self._natural_sort_key(value)

        # 1. Сортируем корневые элементы (группы или файлы без групп)
        roots = list(self.export_tree.get_children(""))
        roots.sort(key=sort_key, reverse=reverse)
        for idx, item in enumerate(roots):
            self.export_tree.move(item, "", idx)

        # 2. Сортируем файлы внутри каждой группы
        for g_id in self.export_groups:
            children = list(self.export_tree.get_children(g_id))
            children.sort(key=sort_key, reverse=reverse)
            for idx, item in enumerate(children):
                self.export_tree.move(item, g_id, idx)

        # Меняем направление для следующего клика
        self.export_tree.heading(col, command=lambda: self._sort_export_tree(col, not reverse))
        self._refresh_export_tree_action_states()
        self._schedule_export_project_save()

    def ungroup_export_items(self):
        """Удаляет группу, но оставляет файлы (переносит их в корень)"""
        if getattr(self, "_export_lock", False) or getattr(self, "_export_running", False):
            return
        selected = self.export_tree.selection()
        groups = [i for i in selected if i in self.export_groups]

        if not groups:
            self._show_info("Внимание", "Выделите группу(ы) для разгруппировки.")
            return

        for g_id in groups:
            parent = self.export_tree.parent(g_id)
            # Переносим всех детей на уровень выше (или в корень)
            for child in self.export_tree.get_children(g_id):
                self.export_tree.move(child, parent, tk.END)
            # Удаляем саму группу
            del self.export_groups[g_id]
            self.export_tree.delete(g_id)
        self.current_selected_export_item = None
        self.export_tree.selection_remove(*self.export_tree.selection())
        self._disable_export_settings()
        self.update_total_export_duration()
        self._refresh_export_tree_action_states()
        self._schedule_export_project_save()

    def _export_tree_interaction_blocked(self, tree):
        """Не даёт обходным решениям для macOS и Treeview менять замороженный экспорт."""
        return (
            tree is getattr(self, "export_tree", None)
            and (
                getattr(self, "_export_lock", False)
                or getattr(self, "_export_running", False)
            )
        )

    def _mac_multiselect(self, event, tree):
        """Атомарное выделение с гарантированной зачисткой призраков на macOS"""
        if self._export_tree_interaction_blocked(tree):
            return "break"
        try:
            tree.focus_set()
        except Exception:
            pass

        item = tree.identify_row(event.y)
        if item:
            current_sel = set(tree.selection())
            if item in current_sel:
                current_sel.remove(item)
            else:
                current_sel.add(item)

            # Атомарно задаем весь новый массив выделения и принудительно перерисовываем
            tree.selection_set(tuple(current_sel))
            tree.focus(item)
            tree.event_generate("<<TreeviewSelect>>")
            tree.update_idletasks()
        return "break"

    def _bind_mac_treeview_clicks(self, tree):
        """Единое исправление для macOS и ttk.Treeview: фокус и резервный выбор строки."""
        if sys.platform != "darwin":
            return

        tree.bind("<ButtonPress-1>", lambda e, t=tree: self._mac_tree_button_press(e, t), add="+")
        tree.bind("<Command-ButtonPress-1>", lambda e, t=tree: self._mac_multiselect(e, t))

    def _mac_tree_button_press(self, event, tree):
        if self._export_tree_interaction_blocked(tree):
            return "break"
        try:
            tree.focus_set()
        except Exception:
            pass

        item = tree.identify_row(event.y)
        region = tree.identify_region(event.x, event.y)
        if item and region in ("tree", "cell") and not self._mac_event_has_selection_modifier(event):
            tree.after_idle(lambda t=tree, i=item: self._mac_ensure_tree_plain_click(t, i))

    def _mac_event_has_selection_modifier(self, event):
        state = getattr(event, "state", 0)
        return bool(state & (0x0001 | 0x0004 | 0x0008 | 0x0010))

    def _mac_ensure_tree_plain_click(self, tree, item):
        if self._export_tree_interaction_blocked(tree):
            return
        try:
            if not tree.winfo_exists() or not tree.exists(item):
                return
            if tuple(tree.selection()) != (item,) or tree.focus() != item:
                tree.selection_set(item)
                tree.focus(item)
                tree.event_generate("<<TreeviewSelect>>")
            else:
                tree.focus(item)
        except tk.TclError:
            pass

    def _setup_mac_hotkeys(self):
        """Обработка горячих клавиш macOS и безопасное исправление первого клика."""
        # Универсальные хоткеи для работы с буфером обмена
        for widget_cls in ("Text", "Entry", "TEntry"):
            self.root.bind_class(
                widget_cls, "<<Paste>>", self._paste_clipboard_once
            )
            self.root.bind_class(widget_cls, "<Command-Key>", self._dispatch_mac_cmd)


    def _dispatch_mac_cmd(self, event):
        """Нативная обработка горячих клавиш macOS и путей Finder."""
        w = event.widget
        kc = event.keycode
        char = str(event.char).lower()

        if not isinstance(w, (tk.Text, tk.Entry, ttk.Entry)):
            w = self.root.focus_get()
            if not isinstance(w, (tk.Text, tk.Entry, ttk.Entry)):
                return

        # Вставка (⌘V) с автоматическим декодированием кириллицы и путей Finder
        if kc == 9 or char in ('v', 'м', '\x16'):
            return self._paste_clipboard_once(event)

        # Копирование (⌘C)
        elif kc == 8 or char in ('c', 'с', '\x03'):
            try:
                text_to_copy = ""
                if isinstance(w, tk.Text) and w.tag_ranges(tk.SEL):
                    text_to_copy = w.get(tk.SEL_FIRST, tk.SEL_LAST)
                elif isinstance(w, (ttk.Entry, tk.Entry)) and w.selection_present():
                    text_to_copy = w.selection_get()

                if text_to_copy:
                    self.root.clipboard_clear()
                    self.root.clipboard_append(text_to_copy)
                    try:
                        p = subprocess.Popen(["pbcopy"], stdin=subprocess.PIPE, text=True)
                        p.communicate(input=text_to_copy)
                    except (OSError, subprocess.SubprocessError) as exc:
                        logging.debug("pbcopy недоступен: %s", exc)
            except (tk.TclError, AttributeError) as exc:
                logging.debug("Ошибка копирования в буфер macOS: %s", exc)
            return "break"

        # Вырезание (⌘X)
        elif kc == 7 or char in ('x', 'ч', '\x18'):
            try:
                text_to_copy = ""
                if isinstance(w, tk.Text) and w.tag_ranges(tk.SEL):
                    text_to_copy = w.get(tk.SEL_FIRST, tk.SEL_LAST)
                    w.delete(tk.SEL_FIRST, tk.SEL_LAST)
                elif isinstance(w, (ttk.Entry, tk.Entry)) and w.selection_present():
                    text_to_copy = w.selection_get()
                    w.delete(tk.SEL_FIRST, tk.SEL_LAST)

                if text_to_copy:
                    self.root.clipboard_clear()
                    self.root.clipboard_append(text_to_copy)
                    try:
                        p = subprocess.Popen(["pbcopy"], stdin=subprocess.PIPE, text=True)
                        p.communicate(input=text_to_copy)
                    except (OSError, subprocess.SubprocessError) as exc:
                        logging.debug("pbcopy недоступен: %s", exc)
            except (tk.TclError, AttributeError) as exc:
                logging.debug("Ошибка вырезания в буфер macOS: %s", exc)
            return "break"

        # Выделить всё (⌘A)
        elif kc == 0 or char in ('a', 'ф', '\x01'):
            try:
                if isinstance(w, tk.Text):
                    w.tag_add(tk.SEL, "1.0", "end-1c")
                    w.mark_set(tk.INSERT, "1.0")
                    w.focus_set()
                elif isinstance(w, (ttk.Entry, tk.Entry)):
                    w.select_range(0, tk.END)
                    w.icursor(tk.END)
                    w.focus_set()
            except (tk.TclError, AttributeError) as exc:
                logging.debug("Ошибка выделения текста на macOS: %s", exc)
            return "break"

        # Отмена и повтор (⌘Z / ⌘Shift+Z)
        elif kc == 6 or char in ('z', 'я', '\x1a'):
            try:
                if isinstance(w, tk.Text):
                    if event.state & 1:
                        w.edit_redo()
                    else:
                        w.edit_undo()
            except Exception as e:
                logging.debug(f"Ошибка Undo/Redo: {e}")
            return "break"

    def _get_smart_dir(self, current_path, is_file=False):
        """Возвращает единый безопасный начальный путь файлового диалога."""
        return resolve_dialog_initial_dir(current_path, file_path=is_file)

    def _path_var_changed(self, key, variable):
        """Синхронизирует вручную редактируемый путь с ``self.config``.

        Поля путей раньше обновляли конфиг только при явном сохранении либо
        при запуске конкретной операции.  Поэтому, например, после ручной
        правки ``input_dir`` нажатие «Обновить папку» сначала читало старое
        значение из ``self.config``. Отслеживание здесь намеренно не создаёт
        каталоги и не пишет JSON на каждый введённый символ: он лишь помечает
        свежее значение в памяти.  Валидация/создание каталога выполняется на
        ``FocusOut``/``Enter`` либо перед операцией.
        """
        if getattr(self, "_is_updating_ui", False) or getattr(
            self, "_is_closing", False
        ):
            return
        try:
            value = str(variable.get()).strip()
        except (AttributeError, tk.TclError, TypeError, ValueError):
            return
        self.config[key] = value

        # ``direct_output_dir`` отображается в двух местах. Оба Entry используют
        # один StringVar в обычном окне, но после импорта старого конфига одна
        # из ссылок может быть создана отдельно — синхронизируем её мягко.
        if key == "direct_output_dir":
            mirror = getattr(self, "settings_vars", {}).get(key)
            if mirror is not None and mirror is not variable:
                try:
                    if str(mirror.get()) != value:
                        mirror.set(value)
                except (AttributeError, tk.TclError, TypeError, ValueError):
                    pass
            direct_var = getattr(self, "direct_output_dir_var", None)
            if direct_var is not None and direct_var is not variable:
                try:
                    if str(direct_var.get()) != value:
                        direct_var.set(value)
                except (AttributeError, tk.TclError, TypeError, ValueError):
                    pass

        # Компактный путь экспорта виден вместе со сводкой набора целей.
        # Обновляем его сразу после ручного ввода, чтобы фактическое назначение
        # (общее для одной цели, отдельное по форматам для нескольких) было
        # понятно до следующей сборки. Необязательное обновление сводки не
        # должно мешать ручному редактированию пути.
        if key == "export_dir":
            try:
                self._refresh_output_targets_summary()
            except (AttributeError, KeyError, tk.TclError, TypeError, ValueError):
                pass

    def _commit_path_var(self, key, variable):
        """Проверяет и сохраняет путь после завершения ручного ввода."""
        self._path_var_changed(key, variable)
        if getattr(self, "_is_updating_ui", False) or getattr(
            self, "_is_closing", False
        ):
            return
        # ``save_settings()`` повторно считывает все Entry и вызывает ``ensure_dirs``;
        # это важно для обязательных папок и сохраняет единый путь восстановления
        # недоступного внешнего диска.  Ошибка остаётся в журнале, а Tk не
        # получает исключение из привязанного обработчика.
        try:
            self.save_settings()
        except Exception:
            logging.exception("Не удалось сохранить путь %s после ручного ввода", key)

    def _bind_path_entry(self, entry, key, variable):
        """Привязывает Entry пути к живому конфигу и безопасной фиксации.

        ``trace_add`` нужен для кнопок, которые не переводят фокус (часто так
        ведут себя системные кнопки Aqua), а FocusOut/Enter — для дискового
        сохранения после завершения редактирования.  Повторные привязки одной
        StringVar не создают дополнительные обработчики отслеживания.
        """
        if not hasattr(self, "_path_var_trace_ids"):
            self._path_var_trace_ids = {}
        if key not in self._path_var_trace_ids:
            try:
                trace_id = variable.trace_add(
                    "write",
                    lambda *_args, _key=key, _var=variable: self._path_var_changed(
                        _key, _var
                    ),
                )
                self._path_var_trace_ids[key] = (variable, trace_id)
            except (AttributeError, tk.TclError, TypeError):
                # Очень старые сборки Tk могут не предоставлять ``trace_add``;
                # явная синхронизация по фокусу/
                # операции продолжает работать.
                self._path_var_trace_ids[key] = None

        try:
            entry.bind(
                "<FocusOut>",
                lambda _event, _key=key, _var=variable: self._commit_path_var(
                    _key, _var
                ),
                add="+",
            )
            entry.bind(
                "<Return>",
                lambda _event, _key=key, _var=variable: self._commit_path_var(
                    _key, _var
                ),
                add="+",
            )
        except (AttributeError, tk.TclError, TypeError):
            pass

    @staticmethod
    def _write_json_atomic(path, data, *, backup=False):
        """Записывает JSON атомарно и не оставляет обрезанный рабочий файл."""
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        temp_path = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
        backup_path = path.with_suffix(path.suffix + ".bak")
        backup_temp_path = backup_path.with_name(
            f".{backup_path.name}.{uuid.uuid4().hex}.tmp"
        )
        try:
            with open(temp_path, "w", encoding="utf-8") as file:
                json.dump(data, file, indent=4, ensure_ascii=False)
                file.flush()
                os.fsync(file.fileno())
            if backup and path.exists():
                # Повреждённый основной файл не должен вытеснить последнюю рабочую
                # резервную копию. Это особенно важно после запуска, который
                # уже восстановил настройки из ``.bak``.
                preserve_current = True
                try:
                    with open(path, "r", encoding="utf-8-sig") as current_file:
                        current_data = json.load(current_file)
                    if isinstance(data, dict) and not isinstance(current_data, dict):
                        raise ValueError("корень текущего JSON не является объектом")
                except (OSError, UnicodeError, ValueError, json.JSONDecodeError) as exc:
                    preserve_current = False
                    logging.warning(
                        "Повреждённый JSON %s не записан поверх резервной копии: %s",
                        path,
                        exc,
                    )
                if preserve_current:
                    # Сначала готовим резервную копию во временном имени. Если
                    # копирование прервалось, существующий ``.bak`` не повреждается.
                    shutil.copy2(path, backup_temp_path)
                    os.replace(backup_temp_path, backup_path)
            os.replace(temp_path, path)
        finally:
            temp_path.unlink(missing_ok=True)
            backup_temp_path.unlink(missing_ok=True)

    def _config_dialog_initial_dir(self):
        return resolve_dialog_initial_dir(
            self.config.get("last_config_dir", ""), BASE_DIR
        )

    def _glossary_dialog_initial_dir(self):
        return resolve_dialog_initial_dir(
            self.config.get("last_glossary_dir", ""), BASE_DIR
        )

    def _remember_dialog_directory(self, key, selected_path):
        """Запоминает историю интерфейса отдельно от переносимых групп профиля."""
        if not selected_path:
            return
        selected = Path(selected_path).expanduser()
        directory = selected if selected.is_dir() else selected.parent
        self.config[key] = str(directory)
        self.save_settings()

    @staticmethod
    def _set_descendant_state(widget, state, *, skip=()):
        """Рекурсивно меняет состояние интерактивных ttk/tk-виджетов."""
        skip_ids = {id(item) for item in skip}
        for child in widget.winfo_children():
            if id(child) in skip_ids:
                continue
            try:
                child.configure(state=state)
            except (tk.TclError, TypeError):
                pass
            TTSApp._set_descendant_state(child, state, skip=skip)

    def _center_popup(self, dialog, width, height, fit_screen=False, owner=None):
        """Центрирует диалог; опционально вписывает его в доступный экран."""
        owner = owner or self.root
        owner.update_idletasks()

        p_x = owner.winfo_rootx()
        p_y = owner.winfo_rooty()
        p_w = owner.winfo_width()
        p_h = owner.winfo_height()

        if fit_screen:
            screen_w = max(1, dialog.winfo_screenwidth())
            screen_h = max(1, dialog.winfo_screenheight())
            width = min(int(width), max(360, screen_w - 40))
            height = min(int(height), max(240, screen_h - 80))

        x = max(0, p_x + (p_w - width) // 2)
        y = max(0, p_y + (p_h - height) // 2)

        dialog.geometry(f"{width}x{height}+{x}+{y}")

        # Показываем окно после вычисления окончательной позиции.
        dialog.deiconify()
        # ``transient``/``grab_set`` задают владельца и модальность. ``lift`` достаточно для
        # показа над ``root``, но в отличие от ``focus_force`` не обесцвечивает выделение
        # в ранее активном Entry/Text при каждом открытии служебного окна.
        dialog.lift(owner)

    def _create_wait_popup(self, title, message, modal=True, owner=True):
        popup = tk.Toplevel(self.root)
        popup.withdraw()  # Скрываем окно до завершения настройки.

        popup.title(title)
        popup.resizable(False, False)
        if owner:
            popup.transient(self.root)
        if modal:
            popup.grab_set()

        ttk.Label(popup, text=message, font=("", 10)).pack(pady=(15, 5))
        bar = ttk.Progressbar(popup, mode='indeterminate')
        bar.pack(fill=tk.X, padx=20, pady=5)
        bar.start(10)

        self._center_popup(popup, 320, 100)  # Показываем настроенное окно по центру.

        return popup

    @staticmethod
    def _close_popup_safely(popup):
        """Закрывает только служебное окно, предварительно снимая его ``grab``."""
        try:
            if popup.grab_current() == popup:
                popup.grab_release()
        except tk.TclError:
            pass
        try:
            popup.destroy()
        except tk.TclError:
            pass

    def _tree_select_all(self, event):
        """Рекурсивно выделяет все элементы (включая вложенные файлы) в дереве Экспорта"""
        tree = event.widget
        if self._export_tree_interaction_blocked(tree):
            return "break"
        def get_all(item=""):
            res = []
            for c in tree.get_children(item):
                res.append(c)
                res.extend(get_all(c))
            return res
        tree.selection_set(get_all())
        return "break"

    def on_closing(self):
        """Безопасно останавливает работу и закрывает главное окно."""
        if self._is_closing:
            return

        # Операции, которые атомарно публикуют/удаляют индекс и аудиофайлы,
        # нельзя обрывать вместе с фоновым потоком-демоном. В отличие от синтеза у них
        # нет безопасной команды «Стоп», поэтому сначала просим дождаться конца.
        if self.is_cache_operation_running():
            operation = getattr(self, "_cache_operation", None)
            self._show_warning(
                "Операция с кэшем выполняется",
                "Дождитесь завершения операции «"
                f"{CACHE_OPERATION_LABELS.get(operation, operation)}» перед "
                "закрытием приложения. Окно прогресса можно скрыть, но сама "
                "операция должна завершиться.",
            )
            return
        if getattr(self, "_import_running", False):
            self._show_warning(
                "Импорт выполняется",
                "Дождитесь завершения импорта книги перед закрытием приложения, "
                "чтобы не получить неполный набор глав.",
            )
            return
        if getattr(self, "_export_lock", False):
            self._show_warning(
                "Чтение аудиофайлов выполняется",
                "Дождитесь завершения добавления аудиофайлов в проект перед "
                "закрытием приложения.",
            )
            return
        if getattr(self, "_export_running", False):
            self._show_warning(
                "Экспорт выполняется",
                "Сначала нажмите «Стоп» и дождитесь завершения текущего файла, "
                "затем закройте приложение.",
            )
            return
        if getattr(self, "_normalizer_batch_running", False):
            self._show_warning(
                "Пакетная нормализация выполняется",
                "Дождитесь завершения нормализации или нажмите «Стоп» "
                "во вкладке «Нормализатор». Закройте приложение после "
                "сохранения текущего файла.",
            )
            return

        glossary_dirty = bool(getattr(self, "_glossary_dirty", False))
        glossary_editor = getattr(self, "txt_glossary", None)
        if glossary_editor is not None:
            try:
                glossary_dirty = glossary_dirty or bool(
                    glossary_editor.edit_modified()
                )
            except tk.TclError:
                pass
        if glossary_dirty:
            save_glossary = self._ask_yes_no_cancel(
                "Глоссарий изменён",
                "В редакторе глоссария есть несохранённые изменения.\n\n"
                "Сохранить их перед закрытием?",
                icon="warning",
            )
            if save_glossary is None:
                return
            if save_glossary and not self.save_glossary_ui(show_popup=False):
                return

        # Сначала проходим барьер сохранения. При ошибке окно и его таймеры
        # остаются рабочими, а остановленные обработчики завершаются штатно.
        save_errors = []
        for processor in (self.batch_processor, self.direct_processor):
            if processor is None:
                continue
            try:
                if not processor.is_stopped:
                    processor.stop()
            except Exception as exc:
                logging.exception("Не удалось остановить синтез перед закрытием")
                save_errors.append(f"Остановка синтеза: {exc}")
            try:
                if processor.flush_cache() is False:
                    raise OSError("не удалось записать индекс кэша")
            except Exception as exc:
                logging.exception("Не удалось сохранить кэш перед закрытием")
                save_errors.append(f"Кэш: {exc}")
            try:
                if processor._save_processing_statuses() is False:
                    raise OSError("не удалось записать статусы обработки")
            except Exception as exc:
                logging.exception("Не удалось сохранить статусы перед закрытием")
                save_errors.append(f"Статусы обработки: {exc}")
        try:
            if self.save_settings() is False:
                raise OSError("не удалось записать настройки")
        except Exception as exc:
            logging.exception("Не удалось сохранить настройки перед закрытием")
            save_errors.append(f"Настройки: {exc}")
        export_session_after_id = getattr(
            self, "_export_session_save_after_id", None
        )
        try:
            if self._save_export_project_session() is False:
                raise OSError("не удалось записать дерево экспорта")
        except Exception as exc:
            logging.exception("Не удалось сохранить дерево перед закрытием")
            save_errors.append(f"Дерево экспорта: {exc}")
        source_session_after_id = getattr(self, "_source_session_save_after_id", None)
        try:
            if self._save_source_session() is False:
                raise OSError("не удалось записать разбиение исходников")
        except Exception as exc:
            logging.exception("Не удалось сохранить разбиение перед закрытием")
            save_errors.append(f"Разбиение исходников: {exc}")
        if save_errors:
            self._is_closing = False
            self._export_session_save_after_id = export_session_after_id
            self._source_session_save_after_id = source_session_after_id
            self._show_error(
                "Закрытие отменено",
                "Не удалось сохранить данные перед закрытием. Окно оставлено "
                "открытым. Проверьте доступность папки и свободное место на диске, "
                "затем повторите закрытие.\n\n" + "\n".join(save_errors),
            )
            return

        if export_session_after_id is not None:
            try:
                self.root.after_cancel(export_session_after_id)
            except tk.TclError:
                pass
            self._export_session_save_after_id = None
        if source_session_after_id is not None:
            try:
                self.root.after_cancel(source_session_after_id)
            except tk.TclError:
                pass
            self._source_session_save_after_id = None
        self._is_closing = True

        appearance_after_id = getattr(self, "_appearance_check_after_id", None)
        if appearance_after_id is not None:
            try:
                self.root.after_cancel(appearance_after_id)
            except tk.TclError:
                pass
            self._appearance_check_after_id = None

        restore_after_id = getattr(self, "_mac_restore_refresh_after_id", None)
        if restore_after_id is not None:
            try:
                self.root.after_cancel(restore_after_id)
            except tk.TclError:
                pass
            self._mac_restore_refresh_after_id = None

        settings_after_id = getattr(self, "_settings_save_after_id", None)
        if settings_after_id is not None:
            try:
                self.root.after_cancel(settings_after_id)
            except tk.TclError:
                pass
            self._settings_save_after_id = None

        self._discard_last_direct_preview()

        # Не удаляем ``SESSION_TEMP_DIR``: фоновые задачи этого экземпляра могут
        # ещё ждать FFmpeg. Каждая операция ``concat`` удалит только собственный
        # манифест в ``finally``, уже после завершения ``subprocess.run()``.
        self.root.destroy()

    def update_fonts(self, *args):
        """Обновление размера шрифта во всех текстовых блоках (разделители зафиксированы)"""
        size = self.font_size_var.get()
        if hasattr(self, 'direct_text'): self.direct_text.config(font=("Arial", size))
        if hasattr(self, 'txt_glossary'): self.txt_glossary.config(font=("Courier", size))
        if hasattr(self, 'normalizer_source_text'):
            self.normalizer_source_text.config(font=("Arial", size))
        if hasattr(self, 'normalizer_result_text'):
            self.normalizer_result_text.config(font=("Arial", size))
        if hasattr(self, 'help_text_widget'): self.help_text_widget.config(font=("Arial", size))
        self.config["ui_font_size"] = size

        if not getattr(self, '_is_updating_ui', False):
            self.save_settings()

    def reset_direct_fx(self):
        """Сброс эффектов на вкладке Прямой синтез"""
        self.dir_speed_var.set(1.0)
        self.dir_pitch_var.set(1.0)
        self.dir_echo_var.set(False)
        self.dir_echo_delay_var.set(300)
        self.dir_echo_decay_var.set(0.3)
        if hasattr(self, 'lbl_dir_speed'): self.lbl_dir_speed.config(text="1.0x")
        if hasattr(self, 'lbl_dir_pitch'): self.lbl_dir_pitch.config(text="1.00")
        if hasattr(self, 'lbl_dir_delay'): self.lbl_dir_delay.config(text="300мс")
        if hasattr(self, 'lbl_dir_decay'): self.lbl_dir_decay.config(text="0.3")

    def reset_export_fx(self):
        """Сброс эффектов на вкладке Экспорт без надписи 'мс'"""
        self.exp_speed_var.set(1.0)
        self.exp_pitch_var.set(1.0)
        self.exp_echo_var.set(False)
        self.exp_delay_var.set(300)
        self.exp_decay_var.set(0.3)
        if hasattr(self, 'lbl_exp_speed'): self.lbl_exp_speed.config(text="1.0x")
        if hasattr(self, 'lbl_exp_pitch'): self.lbl_exp_pitch.config(text="1.00")
        if hasattr(self, 'lbl_exp_delay'): self.lbl_exp_delay.config(text="300")
        if hasattr(self, 'lbl_exp_decay'): self.lbl_exp_decay.config(text="0.3")

    def _refresh_status_colors(self):
        """Перекрашивает постоянные статусы, не меняя их текущий смысл."""
        if hasattr(self, "tree"):
            self.tree.tag_configure("queued", foreground=self.get_status_color("muted"))
            self.tree.tag_configure("success", foreground=self.get_status_color("success"))
            self.tree.tag_configure("warning", foreground=self.get_status_color("warning"))
            self.tree.tag_configure("error", foreground=self.get_status_color("error"))
            self.tree.tag_configure(
                "processing",
                foreground=self.get_status_color("text"),
                font=("", 10, "bold"),
            )

        # Постоянные информационные подписи и динамические статусы хранят
        # семантический тип, поэтому при смене темы не становятся все синими.
        labels = {
            getattr(self, "lbl_cache_count", None): "info",
            getattr(self, "lbl_export_total_time", None): "info",
        }
        labels.update(self._palette_widget_kinds)
        labels.update(self._status_label_kinds)
        for label, status in labels.items():
            if not label:
                continue
            try:
                if label.winfo_exists():
                    label.config(foreground=self.get_status_color(status))
            except tk.TclError:
                pass

    def apply_theme(self, *args):
        """Включает нативную системную тему ОС и статусную палитру."""
        try:
            self.root.title("Silero TTS Studio")
        except tk.TclError:
            pass

        style = ttk.Style()
        os_name = platform.system()
        default_theme = "vista" if os_name == "Windows" else "aqua" if os_name == "Darwin" else "clam"
        try:
            style.theme_use(default_theme)
        except tk.TclError:
            try:
                style.theme_use("default")
            except tk.TclError:
                pass

        self._is_dark_appearance = self._detect_dark_appearance()
        self._refresh_status_colors()

    def full_ui_refresh(self):
        """Обновляет значения интерфейса и шрифты."""
        self._is_updating_ui = True
        try:
            self.set_ui_from_config()
            self.update_fonts()
            self.root.update_idletasks()
        finally:
            self._is_updating_ui = False

    def ensure_dirs(self, keys=None):
        """Создаёт рабочие папки, восстанавливая недоступные значения."""
        try:
            APP_DATA_DIR.mkdir(parents=True, exist_ok=True)
            if not hasattr(self, "config"):
                return {}
            _, recovered = ensure_config_directories(self.config, keys=keys)
        except Exception as exc:
            logging.error("Ошибка авто-создания директорий: %s", exc)
            return {}

        for key in recovered:
            variable = (
                self.settings_vars.get(key)
                if hasattr(self, "settings_vars")
                else None
            )
            if variable is not None:
                try:
                    variable.set(self.config[key])
                except (AttributeError, tk.TclError):
                    pass
        if (
            "direct_output_dir" in recovered
            and hasattr(self, "direct_output_dir_var")
        ):
            try:
                self.direct_output_dir_var.set(
                    self.config["direct_output_dir"]
                )
            except tk.TclError:
                pass
        return recovered

    def load_settings(self, path=SETTINGS_FILE):
        """Безопасная загрузка настроек с авто-созданием папки"""
        path = Path(path)

        loaded_config = {}
        backup_path = path.with_suffix(path.suffix + ".bak")
        candidates = [candidate for candidate in (path, backup_path) if candidate.exists()]
        for candidate in candidates:
            try:
                with open(candidate, 'r', encoding='utf-8-sig') as f:
                    loaded_config = json.load(f)
                if not isinstance(loaded_config, dict):
                    raise ValueError("корень settings.json должен быть JSON-объектом")
                if candidate == backup_path:
                    logging.warning(
                        "Настройки восстановлены из резервной копии %s",
                        backup_path,
                    )
                    try:
                        # Исправляем основной файл без ротации: исправный .bak остаётся
                        # страховкой и не будет затёрт повреждённым файлом при
                        # следующем автосохранении.
                        self._write_json_atomic(path, loaded_config)
                    except Exception as recovery_exc:
                        logging.error(
                            "Не удалось восстановить основной файл настроек %s: %s",
                            path,
                            recovery_exc,
                        )
                break
            except Exception as e:
                logging.error(f"Ошибка загрузки конфига {candidate}: {e}")
                loaded_config = {}
        cfg = normalize_config(loaded_config)
        try:
            ensure_config_directories(cfg)
        except Exception as exc:
            # Если недоступно даже переносимое значение по умолчанию, не рушим построение интерфейса:
            # конкретная операция с диском позднее покажет штатную ошибку.
            logging.error("Не удалось подготовить рабочие папки: %s", exc)
        # Флажок тегов прямого синтеза является подтверждением только для текущего
        # сеанса. Удаляем также значение, случайно сохранённое предварительными
        # версиями, чтобы приложение всегда стартовало в безопасном режиме.
        cfg.pop("direct_apply_tags", None)
        # Удаляем устаревшие поля, чтобы они не влияли на текущую конфигурацию.
        cfg.pop("api_emotion_enabled", None)
        cfg.pop("api_emotion", None)
        return cfg


    def update_config_from_ui(self):
        for key, var in list(self.settings_vars.items()):
            if key == "direct_apply_tags":
                continue
            try:
                self.config[key] = var.get()
            except Exception:
                pass

        # На вкладке прямого синтеза есть удобный дубль поля папки. Если
        # пользователь печатал именно в нём, оно является самым свежим.
        if hasattr(self, "direct_output_dir_var"):
            direct_dir = str(self.direct_output_dir_var.get()).strip()
            if direct_dir:
                self.config["direct_output_dir"] = direct_dir

        if hasattr(self, "include_subdirs_var"):
            self.config["include_subdirs"] = bool(self.include_subdirs_var.get())

        # Параметры универсального сборщика не дублируют настройки финального
        # вывода TTS: у внешних файлов есть собственные частота и каналы, а
        # режим ``auto`` должен сохраняться между запусками.
        for key, attr_name in (
            ("export_format", "export_fmt_var"),
            ("export_bitrate", "export_bitrate_var"),
            ("export_sample_rate", "export_sample_rate_var"),
            ("export_channels", "export_channels_var"),
        ):
            variable = getattr(self, attr_name, None)
            if variable is not None:
                try:
                    self.config[key] = str(variable.get()).strip().lower()
                except tk.TclError:
                    pass

        for key, attr_name in (
            ("export_apply_fx", "export_apply_fx_var"),
            ("export_parallel_enabled", "export_parallel_var"),
            ("export_fx_speed", "exp_speed_var"),
            ("export_fx_pitch", "exp_pitch_var"),
            ("export_fx_echo", "exp_echo_var"),
            ("export_fx_echo_delay", "exp_delay_var"),
            ("export_fx_echo_decay", "exp_decay_var"),
        ):
            variable = getattr(self, attr_name, None)
            if variable is not None:
                try:
                    self.config[key] = variable.get()
                except tk.TclError:
                    pass

        for key, attr_name in (
            ("export_m4b_template", "export_m4b_template_var"),
            ("export_m4b_max_duration_hours", "export_m4b_hours_var"),
            ("export_m4b_max_chapters", "export_m4b_chapters_var"),
            ("export_m4b_bitrate", "export_m4b_bitrate_var"),
        ):
            variable = getattr(self, attr_name, None)
            if variable is not None:
                try:
                    self.config[key] = variable.get()
                except tk.TclError:
                    pass

        for key, attr_name in (
            (
                "synthesis_m4b_reflow_actual_duration",
                "synthesis_m4b_reflow_actual_var",
            ),
            ("synthesis_m4b_reflow_minutes", "synthesis_m4b_reflow_minutes_var"),
        ):
            variable = getattr(self, attr_name, None)
            if variable is not None:
                try:
                    self.config[key] = variable.get()
                except tk.TclError:
                    pass

        # Набор целей хранится как обычный JSON и не зависит от активных переменных Tk,
        # объектов. Некорректная временная запись не должна ломать сохранение
        # остального конфига.
        if hasattr(self, "export_targets"):
            try:
                normalized_targets = normalize_output_target_directories(
                    self.export_targets
                )
                self.export_targets = list(normalized_targets)
                self.config["export_targets"] = copy.deepcopy(
                    self.export_targets
                )
            except (TypeError, ValueError) as exc:
                logging.warning("Набор выходов не сохранён: %s", exc)

        if hasattr(self, "synthesis_targets"):
            try:
                normalized_targets = list(
                    normalize_output_target_directories(
                        self.synthesis_targets
                    )
                )
                self.synthesis_targets = copy.deepcopy(normalized_targets)
                self.config[SYNTHESIS_TARGETS_CONFIG_KEY] = copy.deepcopy(
                    normalized_targets
                )
                self.config[SOURCE_OUTPUT_TARGETS_CONFIG_KEY] = copy.deepcopy(
                    normalized_targets
                )
            except (TypeError, ValueError) as exc:
                logging.warning("Набор целей синтеза не сохранён: %s", exc)

        self.config.pop("direct_apply_tags", None)

        # Combobox хранит представление «Другое», а в конфигурации/API требуется
        # одно целое число. Ключи, используемые только интерфейсом, не должны
        # попадать в ``settings.json``.
        if "api_steps_choice" in self.settings_vars:
            steps_choice = self.settings_vars["api_steps_choice"].get()
            if steps_choice == "Другое":
                custom_steps = str(
                    self.settings_vars["api_steps_custom"].get()
                ).strip()
                # Пустое/недописанное поле тоже сохраняем как есть. Иначе в
                # в ``config`` оставалась предыдущая предустановка (обычно 16), и нажатие
                # «Синтезировать» неожиданно проходило валидацию.
                self.config["api_steps"] = custom_steps
            elif steps_choice:
                self.config["api_steps"] = steps_choice

        self.config.pop("api_steps_choice", None)
        self.config.pop("api_steps_custom", None)
        # Собираем разделители из всех активных полей
        if hasattr(self, 'separator_entries'):
            seps = [ent.get().strip() for ent in self.separator_entries if ent.get().strip()]
            self.config["separator_symbols"] = "\n".join(seps)

    def _validate_api_steps_ui(self, show_popup=True, confirm_large=True):
        """Проверяет ``steps`` и при необходимости просит подтвердить большое значение."""
        self.update_config_from_ui()
        try:
            steps = resolve_api_steps(self.config)
        except ValueError as exc:
            logging.error(f"Некорректная настройка API steps: {exc}")
            if show_popup:
                self._show_error("Некорректный Steps", str(exc))
            return False
        if steps is not None:
            self.config["api_steps"] = steps

        warning = get_api_steps_warning(steps) if confirm_large else None
        warning_key = steps
        if warning and warning_key not in self._confirmed_steps_warnings:
            if not show_popup:
                return False
            if not self._ask_yes_no(
                "Экспериментальное значение Steps",
                f"{warning}\n\nПродолжить с этим значением?",
                icon="warning",
            ):
                return False
            self._confirmed_steps_warnings.add(warning_key)
        return True

    def _persist_settings_snapshot(self, snapshot, path=SETTINGS_FILE):
        """Атомарно пишет уже подготовленный снимок, не читая остальные поля интерфейса."""
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        self._write_json_atomic(path, snapshot, backup=True)

    def save_settings(self, path=SETTINGS_FILE, show_popup=False):
        """Безопасное сохранение настроек с авто-созданием папки и уведомлением"""
        try:
            # Сначала забираем свежий текст из Entry, затем валидируем именно
            # его. Весь путь сохранения находится внутри одной границы обработки ошибок:
            # недоступный каталог не должен ронять обратный вызов Tk.
            self.update_config_from_ui()
            self.ensure_dirs()
            path = Path(path)

            # Обычные автосохранения (пути, шрифт, закрытие окна) не должны
            # блокироваться временно недописанным полем «Другое». Строгая
            # проверка выполняется перед синтезом/оптимизацией кэша.
            self._persist_settings_snapshot(self.config, path)
        except Exception as e:
            logging.error(f"Ошибка сохранения конфига {path}: {e}")
            if show_popup:
                self._show_error("Ошибка", f"Не удалось сохранить настройки:\n{e}")
            return False

        try:
            self.shared_rate_limiter.update_limits(
                self.config.get("api_max_requests", 15),
                self.config.get("api_time_window", 15.0),
            )
        except Exception:
            # ``settings.json`` уже атомарно записан; сбой необязательного обновления
            # лимитера не должен выдавать ложную ошибку сохранения.
            logging.exception("Не удалось обновить лимитер после сохранения")

        # Файл уже успешно заменён. Ошибка необязательной перерисовки не должна
        # выдавать ложное «сохранение не удалось» и провоцировать откат памяти
        # при том, что ``settings.json`` содержит новый снимок.
        for refresh in (
            self._refresh_global_normalizer_settings_summary,
            self._refresh_normalizer_scope_status,
            self._refresh_audio_profile_summaries,
        ):
            try:
                refresh()
            except Exception:
                logging.exception(
                    "Не удалось обновить интерфейс после сохранения настроек"
                )
        try:
            self._sync_glossary_editor_cache(prompt_if_dirty=show_popup)
        except Exception:
            logging.exception("Не удалось синхронизировать редактор глоссария")
        if show_popup:
            self._show_info("Успех", "Настройки успешно сохранены!")
        return True

    def _schedule_settings_save(self, *_args, delay_ms=350):
        """Объединяет серию печати в одну запись ``settings.json``."""
        if getattr(self, "_is_updating_ui", False) or getattr(self, "_is_closing", False):
            return
        pending = getattr(self, "_settings_save_after_id", None)
        if pending is not None:
            try:
                self.root.after_cancel(pending)
            except tk.TclError:
                pass
        self._settings_save_after_id = self.root.after(
            delay_ms, self._run_scheduled_settings_save
        )

    def _run_scheduled_settings_save(self):
        self._settings_save_after_id = None
        self.save_settings()

    def _sync_api_steps_widgets(self, *args, focus_custom=False):
        """Синхронизирует экспериментальные виджеты Steps без записей отслеживания."""
        if not hasattr(self, "api_steps_combobox"):
            return

        enabled = _config_bool(self.settings_vars["api_steps_enabled"].get())
        choice = self.settings_vars["api_steps_choice"].get()
        preset = None
        if choice != "Другое":
            try:
                preset = int(choice)
            except (TypeError, ValueError):
                preset = 16
                self.settings_vars["api_steps_choice"].set("16")

        if preset is not None:
            self.settings_vars["api_steps"].set(preset)

        self.api_steps_combobox.config(state="readonly" if enabled else tk.DISABLED)
        custom_state = tk.NORMAL if enabled and choice == "Другое" else tk.DISABLED
        self.api_steps_custom_entry.config(state=custom_state)
        if hasattr(self, "api_steps_cache_check"):
            self.api_steps_cache_check.config(
                state=tk.NORMAL if enabled else tk.DISABLED
            )
        if focus_custom and custom_state == tk.NORMAL:
            # На Tk 9 первый клик сразу после смены состояния ``readonly`` у
            # Combobox иногда лишь активирует Entry. Перенос фокуса через цикл
            # простоя делает поле готовым к вводу без ``focus_force`` и без
            # побочных эффектов macOS.
            self.root.after_idle(self.api_steps_custom_entry.focus_set)

    def _load_api_steps_widgets_from_config(self):
        """Показывает предустановку либо «Другое» после загрузки/импорта конфига."""
        if not hasattr(self, "api_steps_combobox"):
            return

        raw_value = self.config.get("api_steps", 16)
        try:
            raw_text = str(raw_value).strip()
            if not re.fullmatch(r"[+-]?\d+", raw_text):
                raise ValueError
            value = int(raw_text)
        except (TypeError, ValueError):
            value = None

        if value in API_STEPS_PRESETS:
            self.settings_vars["api_steps_choice"].set(str(value))
            self.settings_vars["api_steps_custom"].set("")
            self.settings_vars["api_steps"].set(value)
        else:
            self.settings_vars["api_steps_choice"].set("Другое")
            self.settings_vars["api_steps_custom"].set(str(raw_value))
            if value is not None:
                self.settings_vars["api_steps"].set(value)

        self.settings_vars["api_steps_enabled"].set(
            _config_bool(self.config.get("api_steps_enabled", False))
        )
        self.settings_vars["cache_include_steps"].set(
            _config_bool(self.config.get("cache_include_steps", True), default=True)
        )
        self._sync_api_steps_widgets()

    def _config_group_rules(self):
        """Точные списки ключей для независимого импорта групп настроек."""
        return _config_group_rules_data()

    def set_ui_from_config(self):
        """Заполняет поля интерфейса из ``self.config`` с полной блокировкой событий отслеживания."""
        self._is_updating_ui = True
        try:
            self.ensure_dirs()

            # 1. Загрузка динамических полей разделителей
            if hasattr(self, 'separators_container') and self.separators_container.winfo_exists():
                try:
                    for child in self.separators_container.winfo_children():
                        child.destroy()
                    self.separator_entries.clear()

                    raw_seps = str(self.config.get("separator_symbols", "")).strip()
                    if not raw_seps:
                        raw_seps = DEFAULT_CONFIG["separator_symbols"]
                        self.config["separator_symbols"] = raw_seps

                    raw_seps = raw_seps.replace("\\n", "\n").replace(",", "\n")
                    seps_list = [s.strip() for s in raw_seps.split("\n") if s.strip()]

                    for sep in seps_list:
                        self.add_separator_row(sep)

                    if not self.separator_entries:
                        for default_sep in DEFAULT_CONFIG["separator_symbols"].split("\n"):
                            self.add_separator_row(default_sep)
                except Exception as e:
                    logging.error(f"Ошибка загрузки разделителей: {e}")

            # 2. Переменные настроек
            for key, var in list(self.settings_vars.items()):
                if key in self.config:
                    val = self.config[key]
                    if val is not None:
                        try:
                            if isinstance(var, tk.BooleanVar):
                                var.set(_config_bool(val))
                            elif isinstance(var, tk.IntVar):
                                var.set(int(float(val)))
                            elif isinstance(var, tk.DoubleVar):
                                var.set(float(val))
                            else:
                                var.set(str(val))
                        except Exception as e:
                            try:
                                var.set(str(val))
                            except (tk.TclError, TypeError) as fallback_error:
                                logging.debug(
                                    "Не удалось восстановить UI-поле %s: %s / %s",
                                    key,
                                    e,
                                    fallback_error,
                                )

            # Представление предустановки/«Другое» является деталью интерфейса и заново
            # строится из единственного сохраняемого значения ``api_steps``.
            self._load_api_steps_widgets_from_config()

            # 3. Поля на вкладке "Экспорт"
            if hasattr(self, 'export_outdir_var'):
                self.export_outdir_var.set(str(self.config.get("export_dir", "")))
            if hasattr(self, 'export_fmt_var'):
                self.export_fmt_var.set(
                    str(
                        self.config.get(
                            "export_format",
                            self.config.get("output_format", "mp3"),
                        )
                    )
                )
            if hasattr(self, 'export_bitrate_var'):
                self.export_bitrate_var.set(str(self.config.get("export_bitrate", "auto")))
            if hasattr(self, "export_parallel_var"):
                self.export_parallel_var.set(
                    _config_bool(
                        self.config.get("export_parallel_enabled", False),
                        default=False,
                    )
                )
            if hasattr(self, "export_sample_rate_var"):
                self.export_sample_rate_var.set(
                    str(self.config.get("export_sample_rate", "auto"))
                )
            if hasattr(self, "export_channels_var"):
                self.export_channels_var.set(
                    str(self.config.get("export_channels", "auto"))
                )
            if hasattr(self, "export_m4b_template_var"):
                self.export_m4b_template_var.set(
                    str(self.config.get("export_m4b_template", DEFAULT_CONFIG["export_m4b_template"]))
                )
            if hasattr(self, "export_m4b_hours_var"):
                self.export_m4b_hours_var.set(
                    float(
                        self.config.get(
                            "export_m4b_max_duration_hours",
                            DEFAULT_M4B_MAX_DURATION_HOURS,
                        )
                    )
                )
            if hasattr(self, "export_m4b_chapters_var"):
                self.export_m4b_chapters_var.set(
                    int(self.config.get("export_m4b_max_chapters", 0))
                )
            if hasattr(self, "export_m4b_bitrate_var"):
                self.export_m4b_bitrate_var.set(
                    str(self.config.get("export_m4b_bitrate", "64k"))
                )
            if hasattr(self, "synthesis_m4b_reflow_actual_var"):
                self.synthesis_m4b_reflow_actual_var.set(
                    _config_bool(
                        self.config.get(
                            "synthesis_m4b_reflow_actual_duration", False
                        ),
                        default=False,
                    )
                )
            if hasattr(self, "synthesis_m4b_reflow_minutes_var"):
                self.synthesis_m4b_reflow_minutes_var.set(
                    float(
                        self.config.get(
                            "synthesis_m4b_reflow_minutes", 60.0
                        )
                    )
                )
            # Имена M4B исходников редактируются в асинхронном диалоге плана,
            # а не в ``settings_vars``. После импорта/сброса настроек приводим
            # снимок в памяти в соответствие, чтобы следующий план/запуск
            # использовал сохранённое значение, а не устаревшее значение сеанса.
            if hasattr(self, "_source_plan_template"):
                self._source_plan_template = normalize_source_m4b_template(
                    self.config.get("synthesis_m4b_template")
                )
            if hasattr(self, "_source_plan_album_template"):
                self._source_plan_album_template = (
                    normalize_source_m4b_album_template(
                        self.config.get("synthesis_m4b_album_template")
                    )
                )
            # После импорта/сброса синхронизируем снимок диалога с сохранённой
            # конфигурацией. Иначе последующее нажатие «Применить» могло бы
            # записать устаревший набор целей из памяти поверх нового конфига.
            if hasattr(self, "export_targets"):
                try:
                    self.export_targets = list(
                        normalize_output_target_directories(
                            [
                                normalize_output_target(item)
                                for item in self.config.get("export_targets", [])
                                if isinstance(item, dict)
                            ]
                        )
                    )
                except (TypeError, ValueError) as exc:
                    logging.warning("Набор выходов в настройках отброшен: %s", exc)
                    self.export_targets = []
            if hasattr(self, "synthesis_targets"):
                try:
                    self.synthesis_targets = list(
                        normalize_output_target_directories(
                            [
                                normalize_output_target(item)
                                for item in self.config.get(
                                    SYNTHESIS_TARGETS_CONFIG_KEY, []
                                )
                                if isinstance(item, dict)
                            ]
                        )
                    )
                except (TypeError, ValueError) as exc:
                    logging.warning(
                        "Набор целей синтеза в настройках отброшен: %s", exc
                    )
                    self.synthesis_targets = []
                self._refresh_source_output_targets_summary()
            if hasattr(self, 'direct_output_dir_var'):
                try:
                    self.direct_output_dir_var.set(
                        str(self.config.get("direct_output_dir", DEFAULT_DIRECT_OUTPUT_DIR))
                    )
                except Exception:
                    pass
            if hasattr(self, "include_subdirs_var"):
                self.include_subdirs_var.set(
                    _config_bool(self.config.get("include_subdirs", False))
                )

            # 4. Ползунки и текстовые подписи чисел
            try:
                sp = float(self.config.get("fx_speed", 1.0))
                pt = float(self.config.get("fx_pitch", 1.0))
                ec = _config_bool(self.config.get("fx_echo", False))
                ed = int(float(self.config.get("fx_echo_delay", 300)))
                ey = float(self.config.get("fx_echo_decay", 0.3))

                if hasattr(self, 'lbl_speed_val'): self.lbl_speed_val.config(text=f"{sp:.1f}x")
                if hasattr(self, 'lbl_pitch_val'): self.lbl_pitch_val.config(text=f"{pt:.2f}")
                if hasattr(self, 'lbl_delay_val'): self.lbl_delay_val.config(text=f"{ed}мс")
                if hasattr(self, 'lbl_decay_val'): self.lbl_decay_val.config(text=f"{ey:.1f}")

                if hasattr(self, 'dir_speed_var'):
                    self.dir_speed_var.set(sp)
                    self.dir_pitch_var.set(pt)
                    self.dir_echo_var.set(ec)
                    self.dir_echo_delay_var.set(ed)
                    self.dir_echo_decay_var.set(ey)
                    if hasattr(self, 'lbl_dir_speed'): self.lbl_dir_speed.config(text=f"{sp:.1f}x")
                    if hasattr(self, 'lbl_dir_pitch'): self.lbl_dir_pitch.config(text=f"{pt:.2f}")
                    if hasattr(self, 'lbl_dir_delay'): self.lbl_dir_delay.config(text=f"{ed}мс")
                    if hasattr(self, 'lbl_dir_decay'): self.lbl_dir_decay.config(text=f"{ey:.1f}")

                if hasattr(self, 'exp_speed_var'):
                    export_sp = float(self.config.get("export_fx_speed", sp))
                    export_pt = float(self.config.get("export_fx_pitch", pt))
                    export_ec = _config_bool(
                        self.config.get("export_fx_echo", ec)
                    )
                    export_ed = int(
                        float(self.config.get("export_fx_echo_delay", ed))
                    )
                    export_ey = float(
                        self.config.get("export_fx_echo_decay", ey)
                    )
                    self.exp_speed_var.set(export_sp)
                    self.exp_pitch_var.set(export_pt)
                    self.exp_echo_var.set(export_ec)
                    self.exp_delay_var.set(export_ed)
                    self.exp_decay_var.set(export_ey)
                    if hasattr(self, 'export_apply_fx_var'):
                        self.export_apply_fx_var.set(
                            _config_bool(
                                self.config.get("export_apply_fx", False)
                            )
                        )
                    if hasattr(self, 'lbl_exp_speed'): self.lbl_exp_speed.config(text=f"{export_sp:.1f}x")
                    if hasattr(self, 'lbl_exp_pitch'): self.lbl_exp_pitch.config(text=f"{export_pt:.2f}")
                    if hasattr(self, 'lbl_exp_delay'): self.lbl_exp_delay.config(text=f"{export_ed}")
                    if hasattr(self, 'lbl_exp_decay'): self.lbl_exp_decay.config(text=f"{export_ey:.1f}")
            except Exception as e:
                logging.error(f"Ошибка ползунков: {e}")

            # 5. Шрифт и тема
            if hasattr(self, 'font_size_var') and "ui_font_size" in self.config:
                try:
                    self.font_size_var.set(int(self.config["ui_font_size"]))
                except (tk.TclError, TypeError, ValueError) as exc:
                    logging.debug("Не удалось применить размер шрифта: %s", exc)

        finally:
            self._is_updating_ui = False
        if (
            hasattr(self, "normalizer_preview_vars")
            and self.normalizer_preview_vars
        ):
            self._load_normalizer_preview_from_config()
        self._refresh_global_normalizer_settings_summary()
        self._refresh_audio_profile_summaries()
        self._refresh_source_settings_summary()

    def import_config(self):
        if getattr(self, "_source_plan_running", False):
            self._show_warning(
                "План M4B выполняется",
                "Дождитесь завершения расчёта частей M4B перед импортом "
                "настроек, чтобы не смешать старый план с новой папкой TXT.",
            )
            return
        filepath = filedialog.askopenfilename(
            initialdir=self._config_dialog_initial_dir(),
            filetypes=[("JSON files", "*.json")],
        )
        if not filepath: return

        try:
            with open(filepath, 'r', encoding='utf-8-sig') as f:
                imported_data = json.load(f)
            if not isinstance(imported_data, dict): raise ValueError()
        except Exception as e:
            self._show_error("Ошибка", f"Не удалось прочитать файл:\n{e}")
            return

        dialog = tk.Toplevel(self.root)
        dialog.withdraw()
        dialog.title("Импорт настроек")
        dialog.transient(self.root)
        dialog.grab_set()

        ttk.Label(dialog, text="Какие настройки из файла применить?").pack(pady=10, padx=20)

        vars_dict = {
            "api": (tk.BooleanVar(value=True), "API и Лимиты (без токена)"),
            "folders": (tk.BooleanVar(value=True), "Пути к папкам"),
            "source_tree": (
                tk.BooleanVar(value=True),
                "Дерево исходников и зеркальные подпапки",
            ),
            "pauses": (tk.BooleanVar(value=True), "Паузы и Разделители"),
            "cache": (tk.BooleanVar(value=True), "Настройки Кэша"),
            "normalizer": (
                tk.BooleanVar(value=True),
                "Нормализатор и применение глоссария",
            ),
            "effects": (tk.BooleanVar(value=True), "Эффекты (Скорость, Тон)"),
            "tags": (
                tk.BooleanVar(value=True),
                "Вывод, аудиопрофили и Теги ID3",
            ),
            "workspace": (
                tk.BooleanVar(value=True),
                "Параметры вкладок (прямой синтез и импорт книг)",
            ),
        }

        for key, (var, text) in vars_dict.items():
            ttk.Checkbutton(dialog, text=text, variable=var).pack(anchor=tk.W, padx=30, pady=2)

        include_api_token_var = tk.BooleanVar(value=False)
        ttk.Checkbutton(
            dialog,
            text="Импортировать API Token (секрет)",
            variable=include_api_token_var,
        ).pack(anchor=tk.W, padx=50, pady=(0, 4))

        def do_import():
            selected_groups = [
                group_key
                for group_key, (var, _) in vars_dict.items()
                if var.get()
            ]
            try:
                candidate_config = normalize_config(
                    merge_config_values(
                        self.config,
                        imported_data,
                        selected_groups,
                        include_api_token=include_api_token_var.get(),
                    )
                )
                ensure_config_directories(candidate_config)
                resolved_steps = resolve_api_steps(candidate_config)
                if resolved_steps is not None:
                    candidate_config["api_steps"] = resolved_steps
                candidate_config["last_config_dir"] = str(
                    Path(filepath).expanduser().parent
                )
                # Сначала фиксируем весь снимок на диске. При ошибке текущие
                # конфигурация и интерфейс остаются без изменений, а диалог можно повторить.
                self._persist_settings_snapshot(candidate_config)
            except ValueError as exc:
                self._show_error(
                    "Некорректные настройки",
                    str(exc),
                    parent=dialog,
                )
                return
            except Exception as exc:
                logging.error("Не удалось сохранить импорт настроек: %s", exc)
                self._show_error(
                    "Ошибка сохранения",
                    f"Импорт не применён:\n{exc}",
                    parent=dialog,
                )
                return

            self.config = candidate_config
            try:
                self.shared_rate_limiter.update_limits(
                    self.config.get("api_max_requests", 15),
                    self.config.get("api_time_window", 15.0),
                )
            except Exception:
                logging.exception(
                    "Настройки импортированы, но runtime-лимитер не обновлён"
                )
            dialog.destroy()
            self.full_ui_refresh()
            self._sync_glossary_editor_cache(prompt_if_dirty=True)
            self.load_files()
            self._show_info("Успех", "Выбранные настройки успешно применены!")

        buttons = ttk.Frame(dialog)
        buttons.pack(fill=tk.X, padx=20, pady=15)
        ttk.Button(
            buttons,
            text="Отмена",
            command=dialog.destroy,
        ).pack(side=tk.RIGHT)
        ttk.Button(
            buttons,
            text="Импортировать",
            command=do_import,
        ).pack(side=tk.RIGHT, padx=(0, 7))
        dialog.protocol("WM_DELETE_WINDOW", dialog.destroy)
        dialog.bind("<Escape>", lambda _event: dialog.destroy())
        self._center_popup(dialog, 470, 350, fit_screen=True)

    def reset_config(self):
        """Сброс рабочих настроек с сохранением темы оформления и размера шрифта"""
        if getattr(self, "_source_plan_running", False):
            self._show_warning(
                "План M4B выполняется",
                "Дождитесь завершения расчёта частей M4B перед сбросом "
                "настроек.",
            )
            return
        if self._ask_yes_no("Сбросить настройки", "Сбросить рабочие настройки (паузы, лимиты, пути) к значениям по умолчанию?"):
            try:
                # 1. Сохраняем текущие визуальные предпочтения пользователя
                current_font_size = self.config.get("ui_font_size", 10)

                # 2. Загружаем дефолты и восстанавливаем визуал
                candidate_config = normalize_config(copy.deepcopy(DEFAULT_CONFIG))
                candidate_config["ui_font_size"] = current_font_size
                ensure_config_directories(candidate_config)

                # 3. Записываем снимок до изменения работающего приложения.
                # Если диск недоступен, прежние конфигурация и интерфейс остаются целыми.
                self._persist_settings_snapshot(candidate_config)
                self.config = candidate_config

                # 4. Полный проход для чистой перерисовки интерфейса
                self.full_ui_refresh()
                self._sync_glossary_editor_cache(prompt_if_dirty=True)
                self.load_files()

                self._show_info("Успех", "Все рабочие настройки сброшены!\n(Тема и размер шрифта сохранены).")
            except Exception as e:
                logging.error(f"Ошибка сброса настроек: {e}")
                self._show_error("Ошибка", f"Не удалось сбросить настройки:\n{e}")

    # --- Вкладка "Синтез из папки" ---
    def setup_main_tab(self):
        # Нижние строки вкладки намеренно оставлены отдельными: на небольших
        # экранах это позволяет переносить действия без изменения порядка
        # управления.  Умеренные отступы дают дереву несколько дополнительных
        # строк, не превращая интерфейс в плотную «панель инструментов».
        list_frame = ttk.Frame(self.tab_main, padding=8)
        list_frame.pack(fill=tk.BOTH, expand=True)

        # Подсказка использует системное обозначение клавиши-модификатора.
        ctrl_key = "Command (⌘)" if sys.platform == "darwin" else "Ctrl"
        self._register_palette_widget(
            ttk.Label(
                list_frame,
                text=f"💡 Вы можете выделять несколько строк мышкой с зажатым {ctrl_key} или Shift",
                font=("", 8, "italic"),
                foreground=self.get_status_color("muted"),
            ),
            "muted",
        ).pack(anchor=tk.W, pady=(0, 5))
        # ``selectmode="extended"`` разрешает множественное выделение.
        # Имя уже находится в штатной колонке ``#0`` Treeview.  Раньше мы
        # дополнительно выводили то же самое значение в колонке ``filename``;
        # в режиме подпапок это давало три колонки и визуальный дубль.  Поле
        # ``filename`` оставляем во внутренних значениях для совместимости со
        # старыми обратными вызовами, но скрываем через ``displaycolumns``.
        self.tree = ttk.Treeview(
            list_frame,
            columns=("status", "filename"),
            show="tree headings",
            selectmode="extended",
            displaycolumns=("status",),
        )
        if sys.platform == "darwin":
            self._bind_mac_treeview_clicks(self.tree)
        self.tree.heading("#0", text="Имя файла")
        self.tree.heading("status", text="Статус")
        # Статус включает текущий формат фоновой сборки FFmpeg, поэтому ему
        # требуется немного больше места; колонка имени остаётся адаптивной.
        self.tree.column("status", width=190, minwidth=150, anchor=tk.CENTER)
        self.tree.column("#0", width=530, minwidth=160, anchor=tk.W)
        # ``filename`` — старое внутреннее значение, а не отдельная видимая колонка.
        # Источник и виртуальная часть отображаются в #0, статус — рядом.
        self.tree.column("filename", width=0, minwidth=0, stretch=False)
        self.tree.pack(fill=tk.BOTH, expand=True, side=tk.LEFT)

        scrollbar = ttk.Scrollbar(list_frame, orient=tk.VERTICAL, command=self.tree.yview)
        self.tree.configure(yscroll=scrollbar.set)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        self.tree.tag_configure('queued', foreground=self.get_status_color("muted"))
        self.tree.tag_configure('processing', foreground=self.get_status_color("text"), font=('', 10, 'bold'))
        self.tree.tag_configure('success', foreground=self.get_status_color("success"))
        self.tree.tag_configure('warning', foreground=self.get_status_color("warning"))
        self.tree.tag_configure('error', foreground=self.get_status_color("error"))

        prog_frame = ttk.Frame(self.tab_main, padding=(8, 2, 8, 3))
        prog_frame.pack(fill=tk.X)
        prog_frame.columnconfigure(1, weight=1)

        self.lbl_current_text = ttk.Label(
            prog_frame,
            text="Ожидание...",
            font=('', 10, 'italic'),
            foreground=self.get_status_color("info"),
            anchor=tk.W,
        )
        self.lbl_current_text.grid(
            row=0,
            column=0,
            columnspan=3,
            sticky=tk.EW,
            pady=(0, 4),
        )
        self._status_label_kinds[self.lbl_current_text] = "info"
        prog_frame.bind(
            "<Configure>",
            lambda _event: self._render_source_activity_status(),
            add="+",
        )

        ttk.Label(prog_frame, text="Файл:").grid(row=1, column=0, sticky=tk.W)
        self.file_progress = ttk.Progressbar(
            prog_frame,
            orient=tk.HORIZONTAL,
            mode='determinate',
        )
        self.file_progress.grid(row=1, column=1, padx=10, pady=2, sticky=tk.EW)
        self.lbl_file_pct = ttk.Label(prog_frame, text="0%")
        self.lbl_file_pct.grid(row=1, column=2)

        ttk.Label(prog_frame, text="Общий:").grid(row=2, column=0, sticky=tk.W)
        self.total_progress = ttk.Progressbar(
            prog_frame,
            orient=tk.HORIZONTAL,
            mode='determinate',
        )
        self.total_progress.grid(row=2, column=1, padx=10, pady=2, sticky=tk.EW)
        self.lbl_total_pct = ttk.Label(prog_frame, text="0/0")
        self.lbl_total_pct.grid(row=2, column=2)

        self.auto_scroll_var = tk.BooleanVar(value=True)
        self.chk_auto_scroll = ttk.Checkbutton(
            prog_frame,
            text="Автопрокрутка",
            variable=self.auto_scroll_var,
        )
        self.chk_auto_scroll.grid(
            row=3, column=1, sticky=tk.E, padx=(0, 8), pady=(3, 0)
        )
        self.btn_go_current = ttk.Button(prog_frame, text="📍 К текущему файлу", command=self.scroll_to_current, state=tk.DISABLED)
        self.btn_go_current.grid(row=3, column=2, sticky=tk.E, pady=(3, 0))

        # Общая папка синтеза из папки редактируется в «Настройки → Папки». На
        # рабочей вкладке её больше не дублируем: это освобождает строку для
        # очереди и исключает рассинхронизацию двух видимых Entry. Живую
        # StringVar всё равно создаём здесь до ``setup_settings_tab()``, чтобы
        # настройки могли подключить к ней единственное поле редактирования.
        self.source_output_dir_var = tk.StringVar(
            value=str(self.config.get("output_dir", DEFAULT_OUTPUT_DIR))
        )
        # Повторно используем эту переменную в «Настройки → Папки». Единая
        # живая переменная предотвращает расхождение поля настроек и конфигурации выполнения.
        self.settings_vars["output_dir"] = self.source_output_dir_var

        # Настройки очереди раньше занимали несколько строк прямо под
        # прогресс-барами. Сохраняем те же основные переменные (их читают
        # фоновый обработчик и импорт или сброс конфигурации), но показываем редактор в
        # отдельном компактном окне.  Временные значения окна создаются
        # ниже; до нажатия «Применить» они не влияют на текущий запуск.
        self.settings_vars["skip_existing"] = tk.BooleanVar(
            value=_config_bool(self.config.get("skip_existing", True), default=True)
        )
        self.include_subdirs_var = tk.BooleanVar(
            value=_config_bool(self.config.get("include_subdirs", False))
        )
        self.batch_prepared_text_var = tk.BooleanVar(value=False)

        # Кнопка и однострочная расшифровка оставляют основную вкладку
        # свободной для очереди и действий M4B.
        source_settings_frame = ttk.Frame(self.tab_main, padding=(8, 0, 8, 3))
        source_settings_frame.pack(fill=tk.X)
        self.btn_source_settings = ttk.Button(
            source_settings_frame,
            text="⚙ Настройки синтеза…",
            command=self.open_source_synthesis_settings_dialog,
        )
        self.btn_source_settings.pack(side=tk.LEFT, padx=2)
        self.lbl_source_settings_summary = self._register_palette_widget(
            ttk.Label(
                source_settings_frame,
                text="",
                foreground=self.get_status_color("muted"),
                anchor=tk.W,
                justify=tk.LEFT,
                # Длинная сводка не должна увеличивать запрашиваемую ширину всей
                # вкладки. ``_bind_compact_label`` хранит полный текст во вспомогательном
                # атрибуте и выводит только то, что помещается в одну строку.
                wraplength=0,
                width=1,
            ),
            "muted",
        )
        self.lbl_source_settings_summary.pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(8, 2)
        )
        self._bind_compact_label(
            source_settings_frame,
            self.lbl_source_settings_summary,
            "",
            # Учитываем кнопку слева вместе с отступами. На узком окне
            # прежний резерв был меньше её фактической ширины на Aqua,
            # поэтому последний символ сводки попадал под границу строки.
            reserve=230,
        )
        self.lbl_source_settings_summary.bind(
            "<Configure>",
            lambda _event: self._refresh_source_settings_summary(),
            add="+",
        )

        # Перестроение M4B остаётся частью общего редактора настроек. Сами
        # виджеты создаются в скрытом Toplevel, чтобы существующие методы
        # блокировки (``start``/``stop`` и планировщик) продолжали работать по тем же
        # атрибутам даже когда окно закрыто.
        self.synthesis_m4b_reflow_actual_var = tk.BooleanVar(
            value=_config_bool(
                self.config.get("synthesis_m4b_reflow_actual_duration", False),
                default=False,
            )
        )
        try:
            reflow_minutes = float(
                self.config.get("synthesis_m4b_reflow_minutes", 60.0) or 60.0
            )
        except (TypeError, ValueError, OverflowError):
            reflow_minutes = 60.0
        self.synthesis_m4b_reflow_minutes_var = tk.DoubleVar(
            value=reflow_minutes
        )
        self._source_settings_dialog = None
        self._source_settings_stage_vars = {}
        self._source_settings_popup_widgets = {}
        self._source_settings_dialog_open = False
        self._source_settings_stage_dirty = False
        self._create_source_synthesis_settings_dialog()
        self._refresh_source_settings_summary()

        btn_frame = ttk.Frame(self.tab_main, padding=(8, 2, 8, 3))
        btn_frame.pack(fill=tk.X)
        btn_frame.columnconfigure(1, weight=1)
        run_actions_frame = ttk.Frame(btn_frame)
        run_actions_frame.grid(row=0, column=0, sticky=tk.W)
        folder_actions_frame = ttk.Frame(btn_frame)
        folder_actions_frame.grid(row=0, column=1, sticky=tk.E)

        self.btn_start_all = ttk.Button(run_actions_frame, text="▶ Старт (Все)", command=lambda: self.start_processing(only_selected=False))
        self.btn_start_all.pack(side=tk.LEFT, padx=2)

        self.btn_start_sel = ttk.Button(run_actions_frame, text="▶ Старт (Выбранные)", command=lambda: self.start_processing(only_selected=True))
        self.btn_start_sel.pack(side=tk.LEFT, padx=2)

        self.btn_stop = ttk.Button(run_actions_frame, text="⏹ Стоп", command=self.stop_processing, state=tk.DISABLED)
        self.btn_stop.pack(side=tk.LEFT, padx=2)

        self.btn_hard_stop = ttk.Button(run_actions_frame, text="☠️ Принудительно", command=self.hard_stop_processing, state=tk.DISABLED)
        self.btn_hard_stop.pack(side=tk.LEFT, padx=2)

        self.btn_source_reset_groups = ttk.Button(
            folder_actions_frame,
            text="↩ Сбросить разбиение…",
            command=self.reset_source_m4b_groups,
        )
        self.btn_source_reset_groups.pack(side=tk.RIGHT, padx=2)

        self.btn_refresh = ttk.Button(folder_actions_frame, text="🔄 Обновить папку", command=self.load_files)
        self.btn_refresh.pack(side=tk.RIGHT, padx=2)

        self.btn_remove_sel = ttk.Button(folder_actions_frame, text="🗑 Удалить из списка", command=self.remove_selected_from_queue)
        self.btn_remove_sel.pack(side=tk.RIGHT, padx=2)

        def resize_source_actions(event=None):
            """Сокращает подписи действий только на действительно узком окне."""
            width = int(getattr(event, "width", 0) or btn_frame.winfo_width())
            compact = width < 1200
            self.btn_start_all.configure(text="▶ Все" if compact else "▶ Старт (Все)")
            self.btn_start_sel.configure(
                text="▶ Выбранные" if compact else "▶ Старт (Выбранные)"
            )
            self.btn_hard_stop.configure(
                text="☠ Прервать" if compact else "☠️ Принудительно"
            )
            self.btn_refresh.configure(
                text="🔄 Обновить" if compact else "🔄 Обновить папку"
            )
            self.btn_remove_sel.configure(
                text="🗑 Удалить" if compact else "🗑 Удалить из списка"
            )
            # Сброс остаётся рядом с обновлением и с полной подписью даже
            # на узком экране или при увеличенном системном шрифте.
            required_width = 16 + sum(
                button.winfo_reqwidth() + 4
                for button in (
                    self.btn_start_all, self.btn_start_sel, self.btn_stop,
                    self.btn_hard_stop, self.btn_remove_sel, self.btn_refresh,
                    self.btn_source_reset_groups,
                )
            )
            wrapped = width < required_width
            folder_actions_frame.grid_configure(
                row=1 if wrapped else 0,
                column=0 if wrapped else 1,
                columnspan=2 if wrapped else 1,
                pady=(3, 0) if wrapped else 0,
            )

        btn_frame.bind("<Configure>", resize_source_actions, add="+")

        # План M4B — отдельное подготовительное действие. Вынос в собственную
        # строку не сжимает основные кнопки «Старт/Стоп» на небольших окнах и
        # подчёркивает, что это оценочная организация TXT до синтеза, а не
        # отдельный параллельный режим кодирования.
        plan_frame = ttk.Frame(self.tab_main, padding=(8, 0, 8, 3))
        plan_frame.pack(fill=tk.X)
        self.btn_prepare_m4b_plan = ttk.Button(
            plan_frame,
            text="🧩 Подготовить оценочный план M4B…",
            command=self.prepare_m4b_source_plan,
        )
        self.btn_prepare_m4b_plan.pack(side=tk.LEFT, padx=2)
        self.source_m4b_plan_hint_shell, self.lbl_source_m4b_plan_hint, _ = (
            self._make_collapsible_hint(
                plan_frame,
                (
                    "Группирует целые TXT по символам и приблизительной "
                    "длительности; после синтеза при выбранном M4B точные "
                    "длительности и таймкоды считаются автоматически."
                ),
                title="О плане M4B",
                wraplength=560,
                initially_open=False,
            )
        )
        self.source_m4b_plan_hint_shell.pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(8, 2)
        )

        manual_plan_frame = ttk.Frame(self.tab_main, padding=(8, 0, 8, 3))
        manual_plan_frame.pack(fill=tk.X)
        self.btn_source_group_selection = ttk.Button(
            manual_plan_frame,
            text="📁 Выделенное в часть",
            command=self.group_selected_source_items,
        )
        self.btn_source_group_selection.pack(side=tk.LEFT, padx=2)
        self.btn_source_merge_groups = ttk.Button(
            manual_plan_frame,
            text="🔗 Объединить части",
            command=self.merge_selected_source_groups,
        )
        self.btn_source_merge_groups.pack(side=tk.LEFT, padx=2)
        self.btn_source_rename_group = ttk.Button(
            manual_plan_frame,
            text="✏ Переименовать часть",
            command=self.rename_selected_source_group,
        )
        self.btn_source_rename_group.pack(side=tk.LEFT, padx=2)
        self.btn_source_group_tags = ttk.Button(
            manual_plan_frame,
            text="🏷 Теги части…",
            command=self.edit_selected_source_group_tags,
        )
        self.btn_source_group_tags.pack(side=tk.LEFT, padx=2)
        self.source_m4b_manual_hint_shell, self.lbl_source_m4b_manual_hint, _ = (
            self._make_collapsible_hint(
                manual_plan_frame,
                (
                    "Для объединения выбирайте соседние виртуальные части "
                    "или TXT внутри них; для нового разбиения — соседние "
                    "TXT. Меняется только виртуальный план, файлы на диске "
                    "остаются на месте. Имя части можно "
                    "изменить кнопкой «Переименовать часть» или двойным "
                    "щелчком по строке виртуальной группы. «Обновить папку» "
                    "сохраняет разбиение. «Сбросить разбиение» после подтверждения "
                    "удаляет ручные группы и их локальные теги и возвращает структуру папки. "
                    "Файлы на диске не изменяются."
                ),
                title="О ручном разбиении",
                wraplength=560,
                initially_open=False,
            )
        )
        self.source_m4b_manual_hint_shell.pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(8, 2)
        )

        def resize_manual_plan_actions(event=None):
            """Оставляет действия плана M4B доступными на узких окнах."""
            width = int(
                getattr(event, "width", 0) or manual_plan_frame.winfo_width()
            )
            # На Aqua кнопки запрашивают больше места, чем следует из длины
            # подписи. Порог учитывает также сворачиваемую подсказку справа,
            # чтобы промежуточная ширина около 1100 px не обрезала её заголовок.
            compact = width < 1240
            self.btn_source_group_selection.configure(
                text="📁 В часть" if compact else "📁 Выделенное в часть"
            )
            self.btn_source_merge_groups.configure(
                text="🔗 Слить" if compact else "🔗 Объединить части"
            )
            self.btn_source_rename_group.configure(
                text="✏ Имя части" if compact else "✏ Переименовать часть"
            )
            self.btn_source_group_tags.configure(
                text="🏷 Теги" if compact else "🏷 Теги части…"
            )

        manual_plan_frame.bind(
            "<Configure>", resize_manual_plan_actions, add="+"
        )

        # Набор целей синтеза из папки отделён от универсального экспортёра.
        # Пустой набор сохраняет старый режим одного формата; после явного
        # выбора целей очередь один раз получает аудио из API/кэша и затем
        # последовательно создаёт выбранные выходы (M4B — отдельным
        # последующим этапом после сбора всех глав).
        source_output_frame = ttk.Frame(self.tab_main, padding=(8, 0, 8, 3))
        source_output_frame.pack(fill=tk.X)
        self.btn_source_output_targets = ttk.Button(
            source_output_frame,
            text="🧩 Выходы для книги…",
            command=self.open_source_output_targets_dialog,
        )
        self.btn_source_output_targets.pack(side=tk.LEFT, padx=2)
        self.lbl_source_output_targets_summary = ttk.Label(
            source_output_frame,
            text="Набор форматов: используется основной формат.",
            foreground=self.get_status_color("muted"),
            anchor=tk.W,
            justify=tk.LEFT,
            wraplength=0,
        )
        self._register_palette_widget(
            self.lbl_source_output_targets_summary,
            "muted",
        ).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(8, 2))
        self._bind_compact_label(
            source_output_frame,
            self.lbl_source_output_targets_summary,
            self.lbl_source_output_targets_summary.cget("text"),
            reserve=220,
        )
        self._refresh_source_output_targets_summary()

        # Сначала резервируем нижние строки управления, затем отдаём всё
        # оставшееся место дереву. При небольшой высоте окна расширяемый список
        # больше не вытесняет строку выходных форматов за нижнюю границу.
        for widget in (
            list_frame,
            prog_frame,
            source_settings_frame,
            btn_frame,
            plan_frame,
            manual_plan_frame,
            source_output_frame,
        ):
            widget.pack_forget()
        for widget in (
            source_output_frame,
            manual_plan_frame,
            plan_frame,
            btn_frame,
            source_settings_frame,
            prog_frame,
        ):
            widget.pack(side=tk.BOTTOM, fill=tk.X)
        list_frame.pack(side=tk.TOP, fill=tk.BOTH, expand=True)

        # Виртуальные M4B-части не являются файлами на диске, поэтому
        # стандартное редактирование Treeview к ним не применяется. Двойной
        # щелчок по строке части открывает тот же безопасный диалог, что и
        # явная кнопка «Переименовать часть».
        self.tree.bind(
            "<Double-1>", self._on_source_tree_double_click, add="+"
        )

    def _create_source_synthesis_settings_dialog(self):
        """Создаёт невидимые совместимые элементы для старых ссылок фоновых потоков.

        Пакетный фоновый обработчик и процедуры блокировки исторически обращаются к
        ``chk_*``/``*_entry`` напрямую.  Эти виджеты намеренно не размещаются
        геометрическим менеджером: пользователь редактирует подготовленные копии в
        отдельном окне, а ссылки остаются существующими и безопасными для
        фоновых обратных вызовов и импорта старых конфигураций.
        """
        compat = ttk.Frame(self.tab_main)
        self._source_settings_compat_frame = compat
        self.chk_include_subdirs = ttk.Checkbutton(
            compat,
            text="Включать подпапки (дерево)",
            variable=self.include_subdirs_var,
            command=self._toggle_source_tree_mode,
        )
        self.chk_batch_prepared_text = ttk.Checkbutton(
            compat,
            text="Текст уже подготовлен",
            variable=self.batch_prepared_text_var,
        )
        self.chk_source_m4b_reflow = ttk.Checkbutton(
            compat,
            text="Перестроить M4B по фактической длительности",
            variable=self.synthesis_m4b_reflow_actual_var,
        )
        self.source_m4b_reflow_minutes_entry = ttk.Entry(
            compat,
            textvariable=self.synthesis_m4b_reflow_minutes_var,
            width=8,
        )
        # Без ``pack``/``grid``: неприсоединённый родитель скрывает совместимые виджеты,
        # не уничтожая их и не влияя на запрашиваемый размер. Они по-прежнему
        # принимают вызовы `configure`/`state` при очистке фонового потока.

    def _source_setting_value(self, key, default=None):
        variable = self.settings_vars.get(key)
        if variable is None:
            return default
        try:
            return variable.get()
        except (AttributeError, tk.TclError, TypeError, ValueError):
            return default

    def _refresh_source_settings_summary(self):
        """Обновляет короткую сводку скрытых параметров синтеза."""
        label = getattr(self, "lbl_source_settings_summary", None)
        if label is None:
            return
        skip = "да" if _config_bool(self._source_setting_value("skip_existing", True), default=True) else "нет"
        include_var = getattr(self, "include_subdirs_var", None)
        prepared_var = getattr(self, "batch_prepared_text_var", None)
        try:
            include_value = include_var.get() if include_var is not None else False
        except (AttributeError, tk.TclError, TypeError, ValueError):
            include_value = False
        try:
            prepared_value = prepared_var.get() if prepared_var is not None else False
        except (AttributeError, tk.TclError, TypeError, ValueError):
            prepared_value = False
        include = "да" if _config_bool(include_value, default=False) else "нет"
        prepared = "да" if _config_bool(prepared_value, default=False) else "нет"
        reflow_var = getattr(self, "synthesis_m4b_reflow_actual_var", None)
        try:
            reflow_value = reflow_var.get() if reflow_var is not None else False
        except (AttributeError, tk.TclError, TypeError, ValueError):
            reflow_value = False
        reflow = _config_bool(reflow_value, default=False)
        book_name = resolve_source_book_name(self.config)
        try:
            reflow_limit = float(self.synthesis_m4b_reflow_minutes_var.get())
            reflow_text = (
                f"второй проход: {reflow_limit:g} мин"
                if reflow
                else "второй проход: выкл."
            )
        except (AttributeError, tk.TclError, TypeError, ValueError):
            reflow_text = "второй проход: проверьте лимит" if reflow else "второй проход: выкл."
        reserve = 230
        try:
            if label.winfo_width() > 1:
                reserve = max(
                    reserve,
                    label.master.winfo_width() - label.winfo_width(),
                )
        except (AttributeError, tk.TclError):
            pass
        self._render_compact_label(
            label,
            (
                f"Книга: {book_name} · готовые: {skip} · дерево: {include} · "
                f"подготовленный текст: {prepared} · {reflow_text}"
            ),
            reserve=reserve,
            fallback_chars=96,
        )

    def open_source_synthesis_settings_dialog(self):
        """Открывает отложенные настройки вкладки «Синтез из папки»."""
        if any(
            (
                getattr(self, "_source_plan_running", False),
                getattr(self, "batch_processor", None) is not None,
                getattr(self, "_import_running", False),
            )
        ):
            return
        existing = getattr(self, "_source_settings_dialog", None)
        if existing is not None:
            try:
                if existing.winfo_exists():
                    existing.lift(self.root)
                    return
            except tk.TclError:
                pass

        dialog = tk.Toplevel(self.root)
        dialog.withdraw()
        dialog.title("Продвинутые настройки синтеза")
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.resizable(True, True)
        self._source_settings_dialog = dialog
        self._source_settings_dialog_open = True

        # Нижняя панель пакуется первой и всегда остаётся доступной. Основное
        # содержимое может уменьшаться, но не скрывает «Применить» и «Отмена».
        footer = ttk.Frame(dialog, padding=(14, 5, 14, 12))
        footer.pack(side=tk.BOTTOM, fill=tk.X)

        source_hint_shell, _source_hint_body, _source_hint_toggle = (
            self._make_collapsible_hint(
                dialog,
                (
                    "Здесь собраны параметры очереди. Изменения попадут в "
                    "программу только после «Применить»; «Отмена» ничего не "
                    "сохраняет. Общая папка для аудио задаётся в разделе "
                    "«Настройки → Папки»; на этой вкладке отдельного поля "
                    "пути нет, чтобы не создавать два конкурирующих значения."
                ),
                title="Как работают настройки",
                wraplength=560,
                initially_open=False,
                resize_toplevel=True,
            )
        )
        source_hint_shell.pack(fill=tk.X, padx=14, pady=(10, 6))

        body_shell = ttk.Frame(dialog)
        body_shell.pack(fill=tk.BOTH, expand=True)
        canvas_background = ttk.Style(dialog).lookup("TFrame", "background")
        if not canvas_background:
            canvas_background = dialog.cget("background")
        body_canvas = tk.Canvas(
            body_shell,
            highlightthickness=0,
            bd=0,
            background=canvas_background,
        )
        body_scroll = ttk.Scrollbar(
            body_shell, orient=tk.VERTICAL, command=body_canvas.yview
        )
        body = ttk.Frame(body_canvas, padding=(14, 0, 14, 4))
        body_window = body_canvas.create_window(
            (0, 0), window=body, anchor="nw"
        )
        body_canvas.configure(yscrollcommand=body_scroll.set)
        body_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        body_scroll.pack(side=tk.RIGHT, fill=tk.Y)
        body.columnconfigure(1, weight=1)

        def sync_source_settings_scroll(_event=None):
            try:
                body_canvas.configure(scrollregion=body_canvas.bbox("all"))
                width = body_canvas.winfo_width()
                if width > 1:
                    body_canvas.itemconfigure(body_window, width=width)
            except tk.TclError:
                pass

        def scroll_source_settings(event):
            try:
                delta = getattr(event, "delta", 0)
                if delta:
                    body_canvas.yview_scroll(
                        -1 * int(delta / 120 or (-1 if delta < 0 else 1)),
                        "units",
                    )
                elif getattr(event, "num", None) == 4:
                    body_canvas.yview_scroll(-3, "units")
                elif getattr(event, "num", None) == 5:
                    body_canvas.yview_scroll(3, "units")
            except (AttributeError, tk.TclError, TypeError, ValueError):
                pass

        body.bind("<Configure>", sync_source_settings_scroll, add="+")
        body_canvas.bind("<Configure>", sync_source_settings_scroll, add="+")
        for wheel_widget in (body_canvas, body):
            wheel_widget.bind("<MouseWheel>", scroll_source_settings, add="+")
            wheel_widget.bind("<Button-4>", scroll_source_settings, add="+")
            wheel_widget.bind("<Button-5>", scroll_source_settings, add="+")

        staged = {
            "book_name": tk.StringVar(
                value=resolve_source_book_name(self.config)
            ),
            "skip_existing": tk.BooleanVar(
                value=_config_bool(self._source_setting_value("skip_existing", True), default=True)
            ),
            "include_subdirs": tk.BooleanVar(
                value=_config_bool(self.include_subdirs_var.get(), default=False)
            ),
            "prepared": tk.BooleanVar(
                value=_config_bool(self.batch_prepared_text_var.get(), default=False)
            ),
            "reflow": tk.BooleanVar(
                value=_config_bool(self.synthesis_m4b_reflow_actual_var.get(), default=False)
            ),
            "reflow_minutes": tk.StringVar(
                value=str(self.synthesis_m4b_reflow_minutes_var.get())
            ),
            "auto_split_long": tk.BooleanVar(
                value=_config_bool(
                    self.config.get("source_m4b_auto_split_long", True),
                    default=True,
                )
            ),
            "m4b_template": tk.StringVar(
                value=self._current_source_m4b_template()
            ),
            "m4b_album_template": tk.StringVar(
                value=normalize_source_m4b_album_template(
                    getattr(
                        self,
                        "_source_plan_album_template",
                        self.config.get("synthesis_m4b_album_template"),
                    )
                )
            ),
        }
        self._source_settings_stage_vars = staged

        queue_frame = ttk.LabelFrame(body, text="Очередь", padding=8)
        queue_frame.grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        for variable, text in (
            (staged["skip_existing"], "Пропускать уже готовые файлы"),
            (staged["include_subdirs"], "Включать подпапки как дерево"),
            (staged["prepared"], "Текст уже подготовлен (только этот запуск)"),
        ):
            ttk.Checkbutton(queue_frame, text=text, variable=variable).pack(
                anchor=tk.W, pady=1
            )

        book_frame = ttk.LabelFrame(body, text="Книга", padding=8)
        book_frame.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        book_frame.columnconfigure(1, weight=1)
        ttk.Label(book_frame, text="Название книги:").grid(
            row=0, column=0, sticky=tk.W, padx=(0, 8)
        )
        ttk.Entry(book_frame, textvariable=staged["book_name"]).grid(
            row=0, column=1, sticky=tk.EW
        )

        m4b_frame = ttk.LabelFrame(body, text="M4B после синтеза", padding=8)
        m4b_frame.grid(row=2, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        m4b_frame.columnconfigure(1, weight=1)
        ttk.Label(m4b_frame, text="Шаблон имени части:").grid(
            row=0, column=0, sticky=tk.W, pady=(0, 3)
        )
        source_name_template_row = ttk.Frame(m4b_frame)
        source_name_template_row.grid(
            row=0, column=1, sticky=tk.EW, pady=(0, 3)
        )
        source_name_template_row.columnconfigure(0, weight=1)
        source_name_template_entry = ttk.Entry(
            source_name_template_row,
            textvariable=staged["m4b_template"],
        )
        source_name_template_entry.grid(row=0, column=0, sticky=tk.EW)
        ttk.Button(
            source_name_template_row,
            text="Помощник…",
            command=lambda: self._open_template_helper(
                staged["m4b_template"],
                "m4b_part",
                owner=dialog,
                target_entry=source_name_template_entry,
                title="Помощник имени M4B",
                preview_data=self._template_helper_source_preview_data(),
            ),
        ).grid(row=0, column=1, padx=(6, 0))
        ttk.Label(m4b_frame, text="Шаблон альбома частей:").grid(
            row=1, column=0, sticky=tk.W, pady=3
        )
        source_album_template_row = ttk.Frame(m4b_frame)
        source_album_template_row.grid(row=1, column=1, sticky=tk.EW, pady=3)
        source_album_template_row.columnconfigure(0, weight=1)
        source_album_template_entry = ttk.Entry(
            source_album_template_row,
            textvariable=staged["m4b_album_template"],
        )
        source_album_template_entry.grid(row=0, column=0, sticky=tk.EW)
        ttk.Button(
            source_album_template_row,
            text="Помощник…",
            command=lambda: self._open_template_helper(
                staged["m4b_album_template"],
                "m4b_album",
                owner=dialog,
                target_entry=source_album_template_entry,
                title="Помощник альбома M4B",
                preview_data=self._template_helper_source_preview_data(),
            ),
        ).grid(row=0, column=1, padx=(6, 0))
        ttk.Checkbutton(
            m4b_frame,
            text="Автоматически делить книги длиннее 24 часов (тома до 23:50)",
            variable=staged["auto_split_long"],
        ).grid(row=2, column=0, columnspan=2, sticky=tk.W, pady=(5, 0))
        reflow_check = ttk.Checkbutton(
            m4b_frame,
            text="Перестроить части по фактической длительности",
            variable=staged["reflow"],
        )
        reflow_check.grid(row=3, column=0, columnspan=2, sticky=tk.W, pady=(3, 0))
        ttk.Label(m4b_frame, text="Лимит части, мин:").grid(
            row=4, column=0, sticky=tk.W, pady=(5, 1)
        )
        reflow_entry = ttk.Entry(
            m4b_frame, textvariable=staged["reflow_minutes"], width=10
        )
        reflow_entry.grid(row=4, column=1, sticky=tk.W, pady=(5, 1))
        m4b_hint_shell, _m4b_hint_body, _m4b_hint_toggle = (
            self._make_collapsible_hint(
                m4b_frame,
                (
                    "Пустой шаблон имени использует имя виртуальной группы, "
                    "а без подготовленного плана — {book}. Номер тома: "
                    "{volume}; {volume:10} начинает с 10, а {volume:03d} "
                    "добавляет ведущие нули. Также доступны {book}, {name}, "
                    "{range}, {first_name}, {last_name}, {part}, {parts}. "
                    "Границы проходят только между целыми TXT; длинная глава "
                    "не режется. При включённой защите 24 часов, фактическом "
                    "переразбиении или собственном лимите окончательные M4B "
                    "публикуются после проверки всей книги, но измерение и "
                    "AAC-подготовка идут в фоне. Без этих проверок фиксированные "
                    "непересекающиеся части сразу собираются в готовые файлы. "
                    "При пропуске готовых файлов неизменённые успешные M4B "
                    "повторно не подготавливаются даже с включённым переразбиением. "
                    "Нестандартный шаблон альбома "
                    "имеет приоритет над тегом из настроек; стандартный "
                    "{book} используется как запасной вариант."
                ),
                title="О ручном разбиении",
                wraplength=540,
                initially_open=False,
                resize_toplevel=True,
            )
        )
        m4b_hint_shell.grid(
            row=5,
            column=0,
            columnspan=2,
            sticky=tk.EW,
            pady=(4, 0),
        )

        self._source_settings_popup_widgets = {
            "reflow_check": reflow_check,
            "reflow_entry": reflow_entry,
        }

        def sync_reflow_state(*_args):
            try:
                reflow_entry.configure(
                    state=tk.NORMAL if staged["reflow"].get() else tk.DISABLED
                )
            except tk.TclError:
                pass

        staged["reflow"].trace_add("write", sync_reflow_state)
        sync_reflow_state()

        status = ttk.Label(
            footer, text="", foreground=self.get_status_color("error"),
            wraplength=560, justify=tk.LEFT,
        )
        status.pack(fill=tk.X, pady=(0, 3))

        def close_dialog():
            self._source_settings_stage_vars = {}
            self._source_settings_popup_widgets = {}
            self._source_settings_dialog_open = False
            self._source_settings_dialog = None
            self._close_popup_safely(dialog)

        def apply_changes():
            try:
                minutes = float(str(staged["reflow_minutes"].get()).strip() or 0)
                if not math.isfinite(minutes) or minutes < 0:
                    raise ValueError("лимит M4B должен быть неотрицательным числом")
                if staged["reflow"].get() and minutes <= 0:
                    raise ValueError("включённый второй проход M4B требует положительный лимит")
                template_input = str(staged["m4b_template"].get() or "").strip()
                m4b_template = template_input or SOURCE_M4B_NO_RANGE_TEMPLATE
                m4b_album_template = str(
                    staged["m4b_album_template"].get() or ""
                ).strip()
                book_name = re.sub(
                    r"\s+", " ", str(staged["book_name"].get() or "")
                ).strip()
                if not book_name:
                    book_name = resolve_source_book_name(
                        dict(
                            self.config,
                            source_book_name="",
                            source_m4b_book_name="",
                        ),
                        self.config.get("input_dir"),
                    )
                validate_filename_template(
                    m4b_template, SOURCE_M4B_TEMPLATE_FIELDS
                )
                validate_filename_template(
                    m4b_album_template, SOURCE_M4B_TEMPLATE_FIELDS
                )
            except (TypeError, ValueError, OverflowError, TemplateError) as exc:
                status.configure(text=str(exc))
                return

            try:
                candidate = normalize_config(copy.deepcopy(self.config))
                candidate["skip_existing"] = bool(staged["skip_existing"].get())
                candidate["include_subdirs"] = bool(staged["include_subdirs"].get())
                candidate["synthesis_m4b_reflow_actual_duration"] = bool(staged["reflow"].get())
                candidate["synthesis_m4b_reflow_minutes"] = minutes
                candidate["source_m4b_auto_split_long"] = bool(
                    staged["auto_split_long"].get()
                )
                candidate["synthesis_m4b_template"] = m4b_template
                candidate["synthesis_m4b_album_template"] = m4b_album_template
                candidate["source_book_name"] = book_name
                candidate["source_book_name_input_dir"] = str(
                    Path(candidate.get("input_dir", DEFAULT_INPUT_DIR)).expanduser()
                )
                candidate = normalize_config(candidate)
                self._persist_settings_snapshot(candidate)
            except Exception as exc:
                status.configure(text=f"Не удалось сохранить настройки: {exc}")
                logging.exception("Не удалось применить настройки синтеза")
                return

            old_include = bool(self.include_subdirs_var.get())
            old_template = self._current_source_m4b_template()
            old_book_name = resolve_source_book_name(self.config)
            current_groups = None
            if getattr(self, "_source_plan_groups", {}):
                try:
                    current_groups = self._current_source_m4b_groups()
                except ValueError:
                    current_groups = None
            self.config = candidate
            self._is_updating_ui = True
            try:
                self.settings_vars["skip_existing"].set(candidate["skip_existing"])
                self.include_subdirs_var.set(candidate["include_subdirs"])
                self.synthesis_m4b_reflow_actual_var.set(
                    candidate["synthesis_m4b_reflow_actual_duration"]
                )
                self.synthesis_m4b_reflow_minutes_var.set(
                    candidate["synthesis_m4b_reflow_minutes"]
                )
                self.batch_prepared_text_var.set(bool(staged["prepared"].get()))
                self._source_plan_template = m4b_template
                self._source_plan_album_template = m4b_album_template
            finally:
                self._is_updating_ui = False
            if old_book_name != book_name:
                self._source_plan_dirty = True
                self._invalidate_source_runtime_m4b_plan()
            self._refresh_source_settings_summary()
            close_dialog()
            if (
                current_groups
                and (
                    old_template != m4b_template
                    or old_book_name != book_name
                )
                and old_include == bool(candidate["include_subdirs"])
            ):
                self._apply_manual_source_m4b_groups(current_groups)
            if old_include != bool(candidate["include_subdirs"]):
                try:
                    self.load_files()
                except Exception as exc:
                    logging.exception("Не удалось обновить дерево после изменения подпапок")
                    self._show_error("Ошибка дерева", str(exc))

        ttk.Button(footer, text="Отмена", command=close_dialog).pack(
            side=tk.RIGHT, padx=(6, 0)
        )
        ttk.Button(footer, text="Применить", command=apply_changes).pack(
            side=tk.RIGHT
        )
        dialog.protocol("WM_DELETE_WINDOW", close_dialog)
        dialog.bind("<Escape>", lambda _event: close_dialog())
        try:
            dialog.minsize(540, 390)
        except (AttributeError, tk.TclError):
            pass
        self._center_popup(dialog, 660, 490, fit_screen=True)

