    def _refresh_import_files_listbox(self, selected_indices=()):
        """Синхронизирует видимый список с очередью текущего сеанса."""
        listbox = getattr(self, "import_files_listbox", None)
        if listbox is not None:
            listbox.delete(0, tk.END)
            for index, filepath in enumerate(self.import_filepaths, 1):
                listbox.insert(tk.END, f"{index}. {filepath}")
            listbox.xview_moveto(0.0)
            valid_selection = sorted(
                {
                    int(index)
                    for index in selected_indices or ()
                    if 0 <= int(index) < len(self.import_filepaths)
                }
            )
            for index in valid_selection:
                listbox.selection_set(index)
            if valid_selection:
                listbox.activate(valid_selection[0])
                listbox.see(valid_selection[0])
        self.import_filepath_var.set(
            self.import_filepaths[-1] if self.import_filepaths else ""
        )
        self._update_import_queue_actions()

    def _add_import_files(self, filepaths):
        """Добавляет книги без перестановки очереди и повторяющихся путей."""
        self.import_filepaths = merge_book_import_paths(
            getattr(self, "import_filepaths", []),
            filepaths,
        )
        self._refresh_import_files_listbox()

    def _remove_selected_import_files(self):
        """Удаляет только отмеченные строки очереди, сохраняя порядок остальных."""
        listbox = getattr(self, "import_files_listbox", None)
        if listbox is None:
            return
        selected = set(listbox.curselection())
        if not selected:
            return
        self.import_filepaths = [
            filepath
            for index, filepath in enumerate(self.import_filepaths)
            if index not in selected
        ]
        next_index = min(selected) if selected else 0
        if self.import_filepaths:
            next_index = min(next_index, len(self.import_filepaths) - 1)
            self._refresh_import_files_listbox((next_index,))
        else:
            self._refresh_import_files_listbox()

    def _edit_selected_import_path(self):
        """Редактирует один путь очереди, не меняя файл на диске."""
        if getattr(self, "_import_running", False):
            return
        listbox = getattr(self, "import_files_listbox", None)
        selected = tuple(listbox.curselection()) if listbox is not None else ()
        if len(selected) != 1:
            self._show_warning(
                "Выберите одну книгу",
                "Для изменения пути выберите ровно одну строку очереди.",
            )
            return
        selected_index = int(selected[0])
        current_path = self.import_filepaths[selected_index]

        dialog = tk.Toplevel(self.root)
        dialog.title("Изменить путь к книге")
        dialog.transient(self.root)
        dialog.grab_set()
        body = ttk.Frame(dialog, padding=12)
        body.pack(fill=tk.BOTH, expand=True)
        ttk.Label(body, text="Путь к исходной книге:").pack(anchor=tk.W)
        path_var = tk.StringVar(value=current_path)
        path_row = ttk.Frame(body)
        path_row.pack(fill=tk.X, pady=(5, 10))
        path_entry = ttk.Entry(path_row, textvariable=path_var)
        path_entry.pack(side=tk.LEFT, fill=tk.X, expand=True)

        def choose_replacement():
            chosen = filedialog.askopenfilename(
                parent=dialog,
                initialdir=self._get_smart_dir(path_var.get(), is_file=True),
                filetypes=[("Книги", "*.epub *.fb2 *.docx *.txt")],
            )
            if chosen:
                path_var.set(chosen)

        ttk.Button(
            path_row,
            text="📁",
            width=3,
            command=choose_replacement,
        ).pack(side=tk.LEFT, padx=(5, 0))

        def apply_replacement():
            value = normalize_clipboard_text(path_var.get()).strip()
            candidate = Path(value).expanduser() if value else None
            if candidate is None or not candidate.is_file():
                self._show_error("Файл не найден", f"Не найдена книга:\n{value}")
                return
            if candidate.suffix.lower() not in BookExtractor.SUPPORTED_EXTENSIONS:
                self._show_error(
                    "Неподдерживаемый формат",
                    "Выберите EPUB, FB2, DOCX или TXT.",
                )
                return
            try:
                self.import_filepaths = replace_book_import_path(
                    self.import_filepaths,
                    selected_index,
                    candidate,
                )
            except ValueError as exc:
                self._show_error("Не удалось изменить путь", str(exc))
                return
            dialog.destroy()
            self._refresh_import_files_listbox((selected_index,))

        buttons = ttk.Frame(body)
        buttons.pack(fill=tk.X)
        ttk.Button(
            buttons,
            text="Применить",
            command=apply_replacement,
        ).pack(side=tk.RIGHT)
        ttk.Button(
            buttons,
            text="Отмена",
            command=lambda: self._close_popup_safely(dialog),
        ).pack(
            side=tk.RIGHT, padx=(0, 6)
        )
        dialog.protocol(
            "WM_DELETE_WINDOW",
            lambda: self._close_popup_safely(dialog),
        )
        dialog.bind("<Return>", lambda _event: apply_replacement())
        dialog.bind(
            "<Escape>",
            lambda _event: self._close_popup_safely(dialog),
        )
        self._center_popup(dialog, 720, 140, fit_screen=True)
        path_entry.focus_set()
        path_entry.icursor(tk.END)

    def _move_selected_import_files(self, direction):
        """Перемещает выбранные книги на одну строку вверх или вниз."""
        if getattr(self, "_import_running", False):
            return
        listbox = getattr(self, "import_files_listbox", None)
        selected = tuple(listbox.curselection()) if listbox is not None else ()
        self.import_filepaths, moved = move_book_import_paths(
            self.import_filepaths,
            selected,
            direction,
        )
        self._refresh_import_files_listbox(moved)

    def _sort_import_files_by_name(self):
        """Сортирует очередь естественно и сохраняет текущее выделение."""
        if getattr(self, "_import_running", False):
            return
        listbox = getattr(self, "import_files_listbox", None)
        selected_indices = tuple(
            listbox.curselection()
        ) if listbox is not None else ()
        selected_ids = {
            _book_import_path_identity(self.import_filepaths[index])
            for index in selected_indices
            if 0 <= index < len(self.import_filepaths)
        }
        self.import_filepaths = sort_book_import_paths(self.import_filepaths)
        selected = tuple(
            index
            for index, filepath in enumerate(self.import_filepaths)
            if _book_import_path_identity(filepath) in selected_ids
        )
        self._refresh_import_files_listbox(selected)

    def _clear_import_files(self):
        """Очищает очередь книг текущего сеанса."""
        self.import_filepaths = []
        self._refresh_import_files_listbox()

    def _update_import_queue_actions(self):
        """Блокирует изменение очереди во время импорта и уточняет действия."""
        running = bool(getattr(self, "_import_running", False))
        paths = getattr(self, "import_filepaths", [])
        listbox = getattr(self, "import_files_listbox", None)
        selection = tuple(listbox.curselection()) if listbox is not None else ()
        has_selection = bool(selection)
        widget_states = (
            (getattr(self, "btn_import_add", None), not running),
            (
                getattr(self, "btn_import_edit", None),
                not running and len(selection) == 1,
            ),
            (
                getattr(self, "btn_import_remove", None),
                not running and has_selection,
            ),
            (getattr(self, "btn_import_clear", None), not running and bool(paths)),
            (
                getattr(self, "btn_import_up", None),
                not running
                and can_move_book_import_paths(paths, selection, -1),
            ),
            (
                getattr(self, "btn_import_down", None),
                not running
                and can_move_book_import_paths(paths, selection, 1),
            ),
            (getattr(self, "btn_import_sort", None), not running and len(paths) > 1),
            (getattr(self, "btn_import_start", None), not running and bool(paths)),
        )
        for widget, enabled in widget_states:
            if widget is not None:
                widget.config(state=tk.NORMAL if enabled else tk.DISABLED)

    def start_import(self):
        if getattr(self, "_import_running", False):
            return
        if getattr(self, "_source_plan_running", False):
            self._show_warning(
                "План M4B выполняется",
                "Дождитесь завершения расчёта частей M4B перед импортом "
                "глав в папку исходников.",
            )
            return
        template = self.settings_vars["import_template"].get().strip()
        if not template:
            self._show_error("Ошибка", "Шаблон имени файла не может быть пустым.")
            return
        try:
            _parse_book_import_template(template)
        except TemplateError as exc:
            self._show_error("Ошибка шаблона имени", str(exc))
            return
        self.save_settings()
        filepaths = list(getattr(self, "import_filepaths", []))
        # Совместимость с одиночным программным заполнением старого поля.
        legacy_filepath = self.import_filepath_var.get().strip()
        if not filepaths and legacy_filepath:
            filepaths = merge_book_import_paths([], [legacy_filepath])
        if not filepaths:
            self._show_error("Ошибка", "Добавьте хотя бы одну книгу в очередь.")
            return

        # ``save_settings()`` уже проверил свежий Entry и при необходимости
        # заменил недоступный каталог на переносимое значение по умолчанию. Берём итог из ``config``,
        # а не прежнее значение Tk-переменной.
        out_dir = str(self.config.get("import_outdir", "")).strip()
        regex_pattern = self.settings_vars["import_regex"].get()
        single_file = self.settings_vars["import_single_file"].get()
        if not out_dir:
            self._show_error("Ошибка", "Укажите папку для сохранения глав.")
            return
        self._import_running = True
        self._update_import_queue_actions()
        self._set_status_label(
            self.lbl_import_status,
            f"Подготовка пакетного импорта: {len(filepaths)} книг…",
            "text",
        )

        def report_progress(book_index, total_books, source_path, stage, value):
            prefix = f"Книга {book_index}/{total_books}: {source_path.name}"
            if stage == "extract":
                message, status = f"{prefix} — извлечение текста…", "text"
            elif stage == "save":
                message, status = f"{prefix} — сохранение глав: {value}", "warning"
            elif stage == "complete":
                message, status = f"{prefix} — сохранено файлов: {value}", "success"
            else:
                message, status = f"{prefix} — ошибка: {value}", "error"
            self._post_status_label(self.lbl_import_status, message, status)

        def run():
            try:
                results = BookExtractor.import_files(
                    filepaths,
                    out_dir,
                    template,
                    regex_pattern=regex_pattern,
                    single_file=single_file,
                    progress_callback=report_progress,
                )
                successful = [result for result in results if not result["error"]]
                failed = [result for result in results if result["error"]]
                saved_count = sum(
                    len(result["saved_files"]) for result in successful
                )
                summary_lines = [
                    f"Обработано книг: {len(successful)} из {len(results)}",
                    f"Сохранено TXT-файлов: {saved_count}",
                    f"Папка: {out_dir}",
                ]
                if failed:
                    summary_lines.append("")
                    summary_lines.append("Не удалось обработать:")
                    for result in failed[:8]:
                        summary_lines.append(
                            f"• {Path(result['path']).name}: {result['error']}"
                        )
                    if len(failed) > 8:
                        summary_lines.append(f"• …и ещё {len(failed) - 8}")
                summary = "\n".join(summary_lines)

                if successful:
                    self._post_to_ui(self.load_files)
                if failed and successful:
                    self._post_status_label(
                        self.lbl_import_status,
                        "Импорт завершён с предупреждениями.",
                        "warning",
                    )
                    self._post_to_ui(
                        self._show_warning,
                        "Пакетный импорт завершён",
                        summary,
                    )
                elif failed:
                    self._post_status_label(
                        self.lbl_import_status,
                        "Не удалось импортировать выбранные книги.",
                        "error",
                    )
                    self._post_to_ui(
                        self._show_error,
                        "Ошибка пакетного импорта",
                        summary,
                    )
                else:
                    self._post_status_label(
                        self.lbl_import_status,
                        "Пакетный импорт завершён.",
                        "success",
                    )
                    self._post_to_ui(
                        self._show_info,
                        "Пакетный импорт завершён",
                        summary,
                    )

            except Exception as e:
                logging.exception("Ошибка пакетного импорта")
                error_message = f"Не удалось завершить пакетный импорт:\n{e}"
                self._post_status_label(self.lbl_import_status, "Ошибка!", "error")
                self._post_to_ui(self._show_error, "Ошибка", error_message)
            finally:
                def finish_import_ui():
                    self._import_running = False
                    self._import_thread = None
                    self._update_import_queue_actions()
                self._post_to_ui(finish_import_ui)

        self._import_thread = threading.Thread(target=run, daemon=True)
        try:
            self._import_thread.start()
        except Exception as exc:
            self._import_thread = None
            self._import_running = False
            self._update_import_queue_actions()
            self._set_status_label(self.lbl_import_status, "Ошибка запуска.", "error")
            logging.exception("Не удалось запустить поток пакетного импорта")
            self._show_error(
                "Ошибка", f"Не удалось запустить импорт:\n{exc}"
            )

    # Вкладка «Экспорт и сборка»
    def setup_utils_tab(self):
        frame = ttk.Frame(self.tab_utils, padding=6)
        frame.pack(fill=tk.BOTH, expand=True)

        self.export_groups = {}
        self.export_files = {}
        self.group_counter = 0
        self.export_targets = list(
            normalize_output_target_directories(
                [
                    normalize_output_target(target)
                    for target in self.config.get("export_targets", [])
                    if isinstance(target, dict)
                ]
            )
        )

        # 1. Индикатор прогресса размещается внизу, чтобы оставаться видимым.
        prog_frame = ttk.Frame(frame)
        prog_frame.pack(side=tk.BOTTOM, fill=tk.X, pady=(2, 0))
        self.lbl_export_status = ttk.Label(
            prog_frame,
            text="Ожидание...",
            anchor=tk.W,
            foreground=self.get_status_color("info"),
        )
        self.lbl_export_status.pack(side=tk.LEFT)
        self._status_label_kinds[self.lbl_export_status] = "info"
        self._export_status_activity = None
        # Не задаём фиксированную длину: на узком окне она создавала белую
        # полосу/выталкивала дерево, а на широком оставляла неиспользованное
        # место. Геометрия ряда сама распределяет доступную ширину.
        self.export_progress = ttk.Progressbar(prog_frame, orient=tk.HORIZONTAL, mode='determinate')
        self.export_progress.pack(side=tk.RIGHT, fill=tk.X, expand=True, padx=(8, 0))
        prog_frame.bind(
            "<Configure>",
            lambda _event: self._render_export_activity_status(),
            add="+",
        )

        self.export_frame = ttk.LabelFrame(frame, text="Экспорт", padding=(3, 2))
        self.export_frame.pack(side=tk.BOTTOM, fill=tk.X, pady=(2, 1))
        export_frame = self.export_frame

        row1 = ttk.Frame(export_frame)
        row1.pack(fill=tk.X, pady=1)
        ttk.Label(row1, text="Общая папка:").pack(side=tk.LEFT, padx=5)

        self.export_outdir_var = tk.StringVar(value=self.config.get("export_dir", ""))
        def choose_exp_dir():
            init_dir = self._get_smart_dir(self.export_outdir_var.get())
            res = filedialog.askdirectory(initialdir=init_dir)
            if res:
                self.export_outdir_var.set(res)
                self.config["export_dir"] = res
                self.save_settings()

        self.btn_export_dir = ttk.Button(row1, text="📁", width=3, command=choose_exp_dir)
        self.btn_export_dir.pack(side=tk.RIGHT, padx=5)
        self.ent_export_dir = ttk.Entry(row1, textvariable=self.export_outdir_var)
        self.ent_export_dir.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=5)
        self._bind_path_entry(
            self.ent_export_dir,
            "export_dir",
            self.export_outdir_var,
        )

        row2 = ttk.Frame(export_frame)
        row2.pack(fill=tk.X, pady=1)
        ttk.Label(row2, text="Формат:").pack(side=tk.LEFT, padx=(5, 2))
        self.export_fmt_var = tk.StringVar(
            value=self.config.get("export_format", self.config.get("output_format", "mp3"))
        )
        self.cb_export_fmt = ttk.Combobox(
            row2,
            textvariable=self.export_fmt_var,
            # M4A — обычный однофайловый выход AAC, доступный и в компактном
            # селекторе, и в многократно используемых аудиопрофилях. M4B остаётся
            # в диалоге набора выходов, поскольку помимо параметров потока ему
            # нужны метаданные глав и томов.
            values=["mp3", "wav", "ogg", "opus", "m4a"],
            width=5,
            state="readonly",
        )
        self.cb_export_fmt.pack(side=tk.LEFT)

        ttk.Label(row2, text="Битрейт:").pack(side=tk.LEFT, padx=(10, 2))
        self.export_bitrate_var = tk.StringVar(
            value=self.config.get("export_bitrate", "auto")
        )
        self.cb_export_bitrate = ttk.Combobox(
            row2,
            textvariable=self.export_bitrate_var,
            values=["auto", "32k", "48k", "64k", "96k", "128k", "192k", "256k", "320k"],
            width=6,
            state="readonly",
        )
        self.cb_export_bitrate.pack(side=tk.LEFT)

        ttk.Label(row2, text="Частота:").pack(side=tk.LEFT, padx=(10, 2))
        self.export_sample_rate_var = tk.StringVar(
            value=self.config.get("export_sample_rate", "auto")
        )
        self.cb_export_sample_rate = ttk.Combobox(
            row2,
            textvariable=self.export_sample_rate_var,
            values=[
                "auto", "8000", "12000", "16000", "22050", "24000",
                "32000", "44100", "48000", "88200", "96000",
            ],
            width=7,
            state="readonly",
        )
        self.cb_export_sample_rate.pack(side=tk.LEFT)

        ttk.Label(row2, text="Каналы:").pack(side=tk.LEFT, padx=(10, 2))
        self.export_channels_var = tk.StringVar(
            value=self.config.get("export_channels", "auto")
        )
        self.cb_export_channels = ttk.Combobox(
            row2,
            textvariable=self.export_channels_var,
            values=["auto", "mono", "stereo"],
            width=7,
            state="readonly",
        )
        self.cb_export_channels.pack(side=tk.LEFT)

        self.btn_audio_profiles_export = ttk.Button(
            row2,
            text="🎛 Аудиопрофили…",
            command=lambda: self.open_audio_profiles_dialog("export"),
        )
        self.btn_audio_profiles_export.pack(side=tk.RIGHT, padx=(10, 5))
        self.btn_output_targets = ttk.Button(
            row2,
            text="🧩 Набор выходов…",
            command=self.open_output_targets_dialog,
        )
        self.btn_output_targets.pack(side=tk.RIGHT, padx=(4, 0))

        self.export_fmt_var.trace_add(
            "write", lambda *_args: self._sync_export_mode_controls()
        )

        self.export_apply_fx_var = tk.BooleanVar(
            value=_config_bool(self.config.get("export_apply_fx", False))
        )
        self.export_parallel_var = tk.BooleanVar(
            value=_config_bool(
                self.config.get("export_parallel_enabled", False),
                default=False,
            )
        )
        self.export_parallel_var.trace_add("write", self._schedule_settings_save)

        # Режим обновления тегов отключает параметры сборки, поэтому
        # сам флаг размещается ниже этих параметров, в строке действий.
        self.export_tags_only_var = tk.BooleanVar(value=False)

        row3 = ttk.Frame(export_frame)
        row3.pack(fill=tk.X, pady=1)

        self.chk_export_fx = ttk.Checkbutton(
            row3,
            text="Наложить эффекты",
            variable=self.export_apply_fx_var,
        )
        self.chk_export_fx.pack(side=tk.LEFT, padx=(5, 8))

        ttk.Label(row3, text="Скор:").pack(side=tk.LEFT, padx=1)
        self.exp_speed_var = tk.DoubleVar(
            value=self.config.get("export_fx_speed", self.config.get("fx_speed", 1.0))
        )
        self.lbl_exp_speed = ttk.Label(row3, text=f"{self.exp_speed_var.get():.1f}x", width=4)
        self.lbl_exp_speed.pack(side=tk.LEFT)
        self.scale_exp_speed = ttk.Scale(
            row3,
            from_=0.5,
            to=3.0,
            variable=self.exp_speed_var,
            command=lambda value: self.lbl_exp_speed.config(
                text=f"{float(value):.1f}x"
            ),
        )
        self.scale_exp_speed.pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=2
        )

        ttk.Label(row3, text="Тон:").pack(side=tk.LEFT, padx=(4, 1))
        self.exp_pitch_var = tk.DoubleVar(
            value=self.config.get("export_fx_pitch", self.config.get("fx_pitch", 1.0))
        )
        self.lbl_exp_pitch = ttk.Label(row3, text=f"{self.exp_pitch_var.get():.2f}", width=4)
        self.lbl_exp_pitch.pack(side=tk.LEFT)
        self.scale_exp_pitch = ttk.Scale(
            row3,
            from_=0.5,
            to=2.0,
            variable=self.exp_pitch_var,
            command=lambda value: self.lbl_exp_pitch.config(
                text=f"{float(value):.2f}"
            ),
        )
        self.scale_exp_pitch.pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=2
        )

        self.exp_echo_var = tk.BooleanVar(
            value=self.config.get("export_fx_echo", self.config.get("fx_echo", False))
        )
        self.chk_exp_echo = ttk.Checkbutton(
            row3, text="Эхо", variable=self.exp_echo_var
        )
        self.chk_exp_echo.pack(side=tk.LEFT, padx=(4, 2))

        ttk.Label(row3, text="Зад:").pack(side=tk.LEFT, padx=1)
        self.exp_delay_var = tk.IntVar(
            value=self.config.get(
                "export_fx_echo_delay", self.config.get("fx_echo_delay", 300)
            )
        )
        self.lbl_exp_delay = ttk.Label(row3, text=f"{self.exp_delay_var.get()}", width=4)
        self.lbl_exp_delay.pack(side=tk.LEFT)
        self.scale_exp_delay = ttk.Scale(
            row3,
            from_=50,
            to=1000,
            variable=self.exp_delay_var,
            command=lambda value: self.lbl_exp_delay.config(
                text=f"{int(float(value))}"
            ),
        )
        self.scale_exp_delay.pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=2
        )

        ttk.Label(row3, text="Сил:").pack(side=tk.LEFT, padx=(4, 1))
        self.exp_decay_var = tk.DoubleVar(
            value=self.config.get(
                "export_fx_echo_decay", self.config.get("fx_echo_decay", 0.3)
            )
        )
        self.lbl_exp_decay = ttk.Label(row3, text=f"{self.exp_decay_var.get():.1f}", width=3)
        self.lbl_exp_decay.pack(side=tk.LEFT)
        self.scale_exp_decay = ttk.Scale(
            row3,
            from_=0.1,
            to=0.8,
            variable=self.exp_decay_var,
            command=lambda value: self.lbl_exp_decay.config(
                text=f"{float(value):.1f}"
            ),
        )
        self.scale_exp_decay.pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=2
        )
        self.btn_reset_export_fx = ttk.Button(
            row3, text="🔄 Сброс", command=self.reset_export_fx
        )
        self.btn_reset_export_fx.pack(side=tk.RIGHT, padx=2)
        self.export_fx_value_controls = (
            self.scale_exp_speed,
            self.scale_exp_pitch,
            self.chk_exp_echo,
            self.scale_exp_delay,
            self.scale_exp_decay,
            self.btn_reset_export_fx,
        )

        # M4B параметры находятся отдельной компактной строкой. Они не
        # меняют обычный сценарий одного формата и применяются только при
        # выборе M4B (AAC-LC с главами).
        m4b_frame = ttk.LabelFrame(
            export_frame, text="M4B (AAC-LC, главы)", padding=(4, 2)
        )
        m4b_frame.pack(fill=tk.X, pady=(1, 1))
        ttk.Label(m4b_frame, text="Шаблон имени M4B:").pack(side=tk.LEFT, padx=(1, 3))
        self.export_m4b_template_var = tk.StringVar(
            value=self.config.get(
                "export_m4b_template", DEFAULT_CONFIG["export_m4b_template"]
            )
        )
        ttk.Entry(
            m4b_frame, textvariable=self.export_m4b_template_var, width=34
        ).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 5))
        ttk.Label(m4b_frame, text="часы:").pack(side=tk.LEFT, padx=(2, 2))
        self.export_m4b_hours_var = tk.DoubleVar(
            value=self.config.get(
                "export_m4b_max_duration_hours",
                DEFAULT_M4B_MAX_DURATION_HOURS,
            )
        )
        ttk.Entry(m4b_frame, textvariable=self.export_m4b_hours_var, width=5).pack(
            side=tk.LEFT, padx=(0, 4)
        )
        ttk.Label(m4b_frame, text="главы:").pack(side=tk.LEFT, padx=(2, 2))
        self.export_m4b_chapters_var = tk.IntVar(
            value=self.config.get("export_m4b_max_chapters", 0)
        )
        ttk.Entry(
            m4b_frame, textvariable=self.export_m4b_chapters_var, width=5
        ).pack(side=tk.LEFT, padx=(0, 4))
        ttk.Label(
            m4b_frame,
            text="0 = авто для книг >24 ч",
        ).pack(side=tk.LEFT, padx=(0, 2))
        # Значение сохраняется только как резерв для старых настроек одного
        # формата. Новые цели M4B получают битрейт, частоту и каналы из
        # совместимого профиля MP4/M4A (AAC-LC) в редакторе набора выходов.
        self.export_m4b_bitrate_var = tk.StringVar(
            value=str(self.config.get("export_m4b_bitrate", "64k"))
        )
        self.cb_export_m4b_bitrate = ttk.Combobox(
            m4b_frame,
            textvariable=self.export_m4b_bitrate_var,
            values=["32k", "48k", "64k", "96k", "128k", "192k", "256k"],
            state="readonly",
            width=6,
        )
        self.export_m4b_controls = m4b_frame

        # Сохраняем компактную строку параметров целой, но поясняем язык шаблона
        # непосредственно в месте использования. Подсказка намеренно находится
        # в отдельной строке с переносом, чтобы длинный список заполнителей не
        # сжимал элементы битрейта и снова не создавал горизонтальное переполнение.
        self.export_m4b_template_hint = self._register_palette_widget(
            ttk.Label(
                export_frame,
                text=(
                    "Поля имени: {book}; {name}/{group}/{title}; {filename} — "
                    "физическое имя исходника; {source_name}/{source_title}; "
                    "{part}/{num}/{volume}/{index}; {chapter}; {parts}; {range}; "
                    "{first_index}/{last_index}; {first_name}/{last_name}. "
                    "Обычное :N задаёт старт номера, :03d — ширину. Пусто — "
                    "имя группы; при совпадении добавляется «Часть N»."
                ),
                foreground=self.get_status_color("muted"),
                wraplength=760,
                justify=tk.LEFT,
                anchor=tk.W,
            ),
            "muted",
        )
        self.export_m4b_template_hint.pack(fill=tk.X, padx=5, pady=(0, 1))

        # Сводка получает собственную строку: длинное имя/расшифровка больше не
        # сжимает ни флажок тегов, ни кнопки запуска.
        profile_summary_row = ttk.Frame(export_frame)
        profile_summary_row.pack(fill=tk.X, pady=(0, 1))
        self.lbl_export_audio_profile_summary = self._register_palette_widget(
            ttk.Label(
                profile_summary_row,
                text="",
                foreground=self.get_status_color("muted"),
                font=("", 9),
                anchor=tk.W,
                justify=tk.LEFT,
                wraplength=0,
            ),
            "muted",
        )
        self.lbl_export_audio_profile_summary.pack(
            fill=tk.X, expand=True, padx=5
        )
        self._bind_compact_label(
            profile_summary_row,
            self.lbl_export_audio_profile_summary,
            "",
            reserve=10,
            fallback_chars=96,
        )

        # Подробные параметры экспорта находятся в транзакционном всплывающем окне.
        # Оставляем два многократно используемых менеджера в этой компактной
        # строке, чтобы они были заметны без открытия второго модального окна,
        # а основная вкладка показывала лишь читаемую сводку активных настроек.
        self.export_compact_row = row2
        self.btn_export_settings = ttk.Button(
            row2,
            text="⚙ Параметры сборки…",
            command=self.open_export_settings_dialog,
        )
        self.btn_export_settings.pack(side=tk.LEFT, padx=(5, 2))

        # Сохраняем основные переменные и виджеты для фоновых потоков,
        # применения профилей и импорта настроек, но убираем их подробные строки
        # из основной вкладки. ``pack_forget`` вместо ``destroy`` сохраняет
        # старые обратные вызовы; окно редактирует
        # подготовленные копии и записывает их в те же переменные.
        # Общий каталог назначения оставляем видимым на основной вкладке экспорта.
        # Он намеренно не входит в «Параметры сборки…»: это всплывающее окно содержит
        # только параметры формата/эффектов/M4B, а каталог назначения — доступная
        # непосредственно перед запуском настройка уровня операции.
        for child in tuple(row2.winfo_children()):
            if child not in (
                self.btn_export_settings,
                self.btn_audio_profiles_export,
                self.btn_output_targets,
            ):
                try:
                    child.pack_forget()
                except tk.TclError:
                    pass
        row3.pack_forget()
        m4b_frame.pack_forget()
        self.export_m4b_template_hint.pack_forget()

        # Команды сборки вынесены в отдельную строку: параметры профиля и
        # эффекты остаются доступными даже при небольшой ширине окна.
        row4 = ttk.Frame(export_frame)
        row4.pack(fill=tk.X, pady=(1, 0))

        export_actions = ttk.Frame(row4)
        export_actions.pack(side=tk.RIGHT)
        self.btn_export_start = ttk.Button(
            export_actions,
            text="🚀 Начать сборку",
            command=self.start_export_process,
        )
        self.btn_export_start.pack(side=tk.LEFT, padx=(0, 5))
        self.btn_export_stop = ttk.Button(
            export_actions,
            text="⏹ Стоп",
            command=self.stop_export_process,
            state=tk.DISABLED,
        )
        self.btn_export_stop.pack(side=tk.LEFT)

        self.chk_export_tags_only = ttk.Checkbutton(
            row4,
            text="Только обновить теги в исходных файлах",
            variable=self.export_tags_only_var,
        )
        self.chk_export_tags_only.pack(side=tk.LEFT, padx=5)

        self.chk_export_parallel = ttk.Checkbutton(
            row4,
            text="Параллельно",
            variable=self.export_parallel_var,
        )
        self.chk_export_parallel.pack(side=tk.LEFT, padx=(5, 2))

        # Блокировка интерфейса при включении режима «только теги».
        self.export_tags_only_var.trace_add(
            "write", lambda *_args: self._sync_export_mode_controls()
        )

        for variable in (
            self.export_fmt_var,
            self.export_bitrate_var,
            self.export_sample_rate_var,
            self.export_channels_var,
            self.export_apply_fx_var,
            self.export_parallel_var,
            self.exp_speed_var,
            self.exp_pitch_var,
            self.exp_echo_var,
            self.exp_delay_var,
            self.exp_decay_var,
            self.export_m4b_template_var,
            self.export_m4b_hours_var,
            self.export_m4b_chapters_var,
            self.export_m4b_bitrate_var,
        ):
            variable.trace_add(
                "write", lambda *_args: self._refresh_audio_profile_summaries()
            )
        self._refresh_audio_profile_summaries()

        self.export_mid_frame = ttk.Frame(frame)
        self.export_mid_frame.pack(side=tk.BOTTOM, fill=tk.X, pady=(2, 1))

        mid_row1 = ttk.Frame(self.export_mid_frame)
        mid_row1.pack(fill=tk.X, pady=1)
        self.btn_export_add_group = ttk.Button(mid_row1, text="📁 Добавить группу", command=self.add_export_group)
        self.btn_export_add_group.pack(side=tk.LEFT, padx=1)
        self.btn_export_add_folder = ttk.Button(mid_row1, text="📂 Добавить папку", command=self.add_export_folder)
        self.btn_export_add_folder.pack(side=tk.LEFT, padx=1)
        self.btn_export_add_files = ttk.Button(mid_row1, text="🎵 Добавить аудио", command=self.add_export_files)
        self.btn_export_add_files.pack(side=tk.LEFT, padx=1)
        self.btn_export_group_selected = ttk.Button(
            mid_row1,
            text="🔗 Объединить",
            command=self.merge_selected_export_items,
        )
        self.btn_export_group_selected.pack(side=tk.LEFT, padx=(10, 1))
        self.btn_export_ungroup = ttk.Button(mid_row1, text="📤 Разгруппировать", command=self.ungroup_export_items)
        self.btn_export_ungroup.pack(side=tk.LEFT, padx=1)

        mid_row2 = ttk.Frame(self.export_mid_frame)
        mid_row2.pack(fill=tk.X, pady=1)
        self.btn_export_remove = ttk.Button(mid_row2, text="➖ Удалить", command=self.remove_export_items)
        self.btn_export_remove.pack(side=tk.LEFT, padx=1)
        self.btn_export_down = ttk.Button(mid_row2, text="⬇", width=3, command=lambda: self.move_export_item(1))
        self.btn_export_down.pack(side=tk.LEFT, padx=1)
        self.btn_export_up = ttk.Button(mid_row2, text="⬆", width=3, command=lambda: self.move_export_item(-1))
        self.btn_export_up.pack(side=tk.LEFT, padx=1)
        self.btn_export_auto_split = ttk.Button(mid_row2, text="⏱ Авто-разбивка", command=self.auto_split_export)
        self.btn_export_auto_split.pack(side=tk.LEFT, padx=(10, 1))
        self.btn_export_split_m4b = ttk.Button(
            mid_row2,
            text="📖 Разобрать M4B…",
            command=self.add_export_m4b_chapters,
        )
        self.btn_export_split_m4b.pack(side=tk.LEFT, padx=1)
        self.btn_export_clear = ttk.Button(
            mid_row2,
            text="🧹 Очистить всё",
            command=self.clear_export_project,
        )
        self.btn_export_clear.pack(side=tk.RIGHT, padx=1)

        def resize_export_action_labels(event=None):
            """Сокращает команды сборщика только на действительно узком окне."""
            width = int(
                getattr(event, "width", 0)
                or self.export_mid_frame.winfo_width()
            )
            compact = 1 < width < 840
            labels = (
                (self.btn_export_add_group, "📁 Группа", "📁 Добавить группу"),
                (self.btn_export_add_folder, "📂 Папка", "📂 Добавить папку"),
                (self.btn_export_add_files, "🎵 Аудио", "🎵 Добавить аудио"),
                (self.btn_export_group_selected, "🔗 Объединить", "🔗 Объединить"),
                (self.btn_export_ungroup, "📤 Разгруп.", "📤 Разгруппировать"),
                (self.btn_export_auto_split, "⏱ Разбивка", "⏱ Авто-разбивка"),
                (self.btn_export_split_m4b, "📖 M4B…", "📖 Разобрать M4B…"),
            )
            for button, short_text, full_text in labels:
                button.configure(text=short_text if compact else full_text)

        self.export_mid_frame.bind(
            "<Configure>", resize_export_action_labels, add="+"
        )
        self.root.after_idle(resize_export_action_labels)

        # 4. Верхняя панель с деревом
        # Дерево получает больший вес, чтобы занимать основную часть панели.
        self.export_top_pane = ttk.PanedWindow(frame, orient=tk.HORIZONTAL)
        self.export_top_pane.pack(side=tk.TOP, fill=tk.BOTH, expand=True)
        top_pane = self.export_top_pane

        tree_frame = ttk.Frame(top_pane)
        top_pane.add(tree_frame, weight=4)

        # Заголовок дерева с общей длительностью
