        def resize_export_tree_columns(event=None):
            """Умещает три колонки и показывает прокрутку только при нужде."""
            width = int(getattr(event, "width", 0) or tree_body.winfo_width())
            available = max(1, width - vertical_scrollbar.winfo_reqwidth())
            duration_width = 90
            minimum_source = 120
            minimum_title = 95
            if available >= minimum_source + minimum_title + duration_width:
                remaining = max(1, available - duration_width)
                source_width = max(
                    minimum_source,
                    int(remaining * 0.56),
                )
                title_width = max(
                    minimum_title,
                    remaining - source_width,
                )
                source_width = max(
                    minimum_source,
                    remaining - title_width,
                )
                self.export_tree.column("#0", width=source_width)
                self.export_tree.column("title", width=title_width)
                self.export_tree.column("duration", width=duration_width)
                horizontal_scrollbar.grid_remove()
            else:
                self.export_tree.column("#0", width=150)
                self.export_tree.column("title", width=120)
                self.export_tree.column("duration", width=duration_width)
                horizontal_scrollbar.grid()

