        def resize_export_panes(event):
            """Сохраняет читаемую ширину дерева на небольших экранах."""
            width = int(getattr(event, "width", 0) or top_pane.winfo_width())
            if width <= 1:
                return
            # Редактору группы нужно около 480 px, но дерево не должно сжиматься
            # до одинаковых обрезанных названий соседних томов.
            tree_width = min(
                max(330, int(width * 0.38)),
                max(220, width - 480),
            )
            try:
                top_pane.sashpos(0, tree_width)
            except (AttributeError, IndexError, tk.TclError):
                pass

