    def _refresh_source_output_targets_summary(self):
        """Показывает активный набор целей синтеза из папки."""
        label = getattr(self, "lbl_source_output_targets_summary", None)
        if label is None:
            return
        raw_targets = getattr(self, "synthesis_targets", None)
        if raw_targets is None:
            raw_targets = self.config.get(SYNTHESIS_TARGETS_CONFIG_KEY, ())
        try:
            normalized_targets = [
                normalize_output_target(item)
                for item in raw_targets
                if isinstance(item, (dict, OutputTarget))
            ]
            targets = [
                item
                for item in normalized_targets
                if _config_bool(item.get("enabled", True), default=True)
            ]
        except (TypeError, ValueError):
            normalized_targets = []
            targets = []
        if not targets:
            if normalized_targets:
                self._render_compact_label(
                    label,
                    "Набор форматов сохранён, но все цели отключены; "
                    "нажмите «Выходы для книги…» → «Основной формат» "
                    "или включите хотя бы одну цель.",
                    reserve=180,
                    fallback_chars=96,
                )
                return
            try:
                legacy_format = str(
                    self.config.get("output_format", "mp3")
                ).upper()
            except (TypeError, ValueError):
                legacy_format = "MP3"
            self._render_compact_label(
                label,
                f"Набор форматов: основной {legacy_format}; дополнительных целей нет.",
                reserve=180,
                fallback_chars=96,
            )
            return
        descriptions = []
        for target in targets:
            raw_format = str(target.get("format", "")).lower()
            fmt = (
                "M4B (AAC-LC)"
                if raw_format == "m4b"
                else AUDIO_PROFILE_FORMAT_LABELS.get(
                    raw_format, raw_format.upper()
                )
            )
            bitrate = str(target.get("bitrate", "auto"))
            detail = "без потерь" if raw_format == "wav" else bitrate
            assembly_label = (
                "по группам"
                if raw_format == "m4b"
                or target.get("assembly_mode") == "merge"
                else "по главам"
            )
            descriptions.append(f"{fmt} {detail} · {assembly_label}")
        has_m4b = any(
            str(target.get("format", "")).lower() == "m4b"
            for target in targets
        )
        m4b_policy = ""
        if has_m4b:
            if _config_bool(
                self.config.get("synthesis_m4b_reflow_actual_duration", False)
            ):
                m4b_policy = " · M4B: глобальное перестроение после всей книги."
            elif _config_bool(
                self.config.get("source_m4b_auto_split_long", True),
                default=True,
            ):
                m4b_policy = " · M4B: AAC в фоне, проверка частей после книги."
            elif any(
                _finite_nonnegative_float(
                    target.get("max_duration_seconds", 0), default=0.0
                ) > 0
                for target in targets
                if str(target.get("format", "")).lower() == "m4b"
            ):
                m4b_policy = " · M4B: AAC в фоне, проверка лимита после книги."
            else:
                m4b_policy = " · M4B: фиксированные части собираются в фоне."
        self._render_compact_label(
            label,
            "Цели синтеза: " + ", ".join(descriptions) + "." + m4b_policy,
            reserve=180,
            fallback_chars=96,
        )

    def _refresh_output_targets_summary(self):
        """Обновляет короткую подпись активного набора форматов."""
        label = getattr(self, "lbl_export_audio_profile_summary", None)
        if label is None:
            return
        targets = [
            target for target in getattr(self, "export_targets", ())
            if isinstance(target, dict) and target.get("enabled", True)
        ]
        if not targets:
            stored_targets = [
                target for target in getattr(self, "export_targets", ())
                if isinstance(target, dict)
            ]
            if stored_targets:
                self._set_export_profile_summary(
                    "Набор выходов сохранён, но все его цели отключены; "
                    "включите хотя бы один формат перед сборкой."
                )
                return
            # Компактный экспортёр по-прежнему поддерживает полезный режим
            # одного профиля. Показываем его текущие настройки, если явный
            # набор выходов не задан: пустая подпись выглядела как сломанная
            # кнопка профиля и скрывала факт применения сохранённого значения.
            try:
                self._set_export_profile_summary(
                    self._current_audio_profile_summary("export")
                )
            except (AttributeError, KeyError, tk.TclError, TypeError, ValueError):
                self._set_export_profile_summary(
                    "Параметры профиля пока недоступны."
                )
            return
        summaries = []
        profile_names = {}
        try:
            profile_names = {
                entry["id"]: entry["profile"].get("name", "Профиль")
                for entry in audio_profile_entries_from_config(self.config)
            }
        except (TypeError, ValueError, KeyError):
            profile_names = {}
        for item in targets:
            fmt = str(item.get("format", "")).upper()
            bitrate = str(item.get("bitrate", "auto"))
            if fmt == "WAV":
                detail = "без потерь"
            elif fmt == "M4B":
                detail = f"AAC {bitrate}"
            else:
                detail = bitrate
            profile = str(item.get("profile", "")).strip()
            profile_label = profile_names.get(profile)
            if profile and profile_label is None:
                profile_label = f"недоступный {profile[:18]}"
            # Одиночная цель всегда использует общую компактную папку.
            # Мигратор настроек обычно уже очищает ``output_dir``, но сохраняем
            # достоверность сводки для старого снимка в памяти, присвоенного
            # напрямую внешней интеграцией.
            explicit_dir = (
                str(item.get("output_dir", "") or "").strip()
                if len(targets) > 1
                else ""
            )
            if explicit_dir:
                # Показываем переопределение явно, а не выводим его как
                # неотличимое назначение. Это особенно полезно, когда
                # пользователь редактирует компактное поле общей папки, а
                # старая строка цели всё ещё указывает на другой каталог проекта.
                destination = "отдельно: " + middle_ellipsize(
                    explicit_dir, max_chars=46
                )
            else:
                common_dir = str(self.config.get("export_dir", "") or "").strip()
                destination = "общая: " + (
                    middle_ellipsize(common_dir, max_chars=46)
                    if common_dir
                    else "не задана"
                )
            assembly_mode = (
                "merge"
                if fmt == "M4B"
                else str(item.get("assembly_mode") or "inherit").lower()
            )
            assembly_label = {
                "merge": "одним файлом",
                "files": "по файлам",
                "inherit": "как у группы",
            }.get(assembly_mode, "как у группы")
            summaries.append(
                f"{fmt} {detail} · {assembly_label}"
                + (f" · {profile_label}" if profile_label else "")
                + f" → {destination}"
            )
        names = ", ".join(summaries)
        self._set_export_profile_summary(
            f"Выход: {names}. "
            + (
                "Цели одного TXT выполняются последовательно из одного "
                "снимка; готовые цели разных TXT могут кодироваться "
                "параллельно под общим лимитом FFmpeg; каталоги и "
                "профили задаются в «Набор выходов…»."
                if len(targets) > 1
                else (
                    "Одна активная цель всегда использует общую папку "
                    "экспорта; все группы попадут туда."
                )
            )
        )

    def _set_export_profile_summary(self, text):
        """Сохраняет полную сводку и показывает её однострочную версию.

        Всплывающее окно остаётся источником всех подробностей. В основной
        вкладке длинный список форматов/профилей не должен занимать несколько
        строк и вытеснять дерево, поэтому изменение размера просто перерисовывает эту
        строку по фактической ширине.
        """
        label = getattr(self, "lbl_export_audio_profile_summary", None)
        if label is None:
            return
        self._render_compact_label(label, text, reserve=10, fallback_chars=96)

    def open_source_output_targets_dialog(self):
        """Открывает набор выходов из контекста текущей книги.

        В отличие от универсального экспортёра этот набор хранится в
        ``synthesis_targets`` и используется очередью «Синтез из папки».
        Пустой набор сохраняет совместимый старый режим одного формата.
        """
        book_name = resolve_source_book_name(self.config) or "текущей книги"
        self._output_targets_dialog_context = {
            "kind": "source",
            "book_name": middle_ellipsize(book_name, max_chars=72),
        }
        try:
            self.open_output_targets_dialog()
        finally:
            # ``open_output_targets_dialog`` использует контекст при создании
            # модального окна. Очистка здесь также защищает вызывающие стороны,
            # которые подменяют метод или досрочно возвращаются из него.
            self._output_targets_dialog_context = None

    def open_output_targets_dialog(self):
        """Настраивает несколько форматов экспорта без изменения прежнего пути."""
        dialog_context = getattr(self, "_output_targets_dialog_context", None)
        self._output_targets_dialog_context = None
        source_context = (
            isinstance(dialog_context, dict)
            and dialog_context.get("kind") == "source"
        )
        source_book_name = (
            str(dialog_context.get("book_name") or "текущей книги")
            if source_context
            else ""
        )
        # Один и тот же редактор обслуживает универсальный экспортёр и очередь
        # синтеза источника. Сохраняем их списки целей полностью независимыми:
        # изменение профиля источника никогда не должно молча менять готовый
        # пресет экспорта (и наоборот).
        target_attr = "synthesis_targets" if source_context else "export_targets"
        target_config_key = (
            SYNTHESIS_TARGETS_CONFIG_KEY if source_context else "export_targets"
        )
        target_profile_scope = "book" if source_context else "export"
        target_values = getattr(self, target_attr, None)
        if target_values is None:
            target_values = self.config.get(target_config_key, ())
        try:
            if source_context:
                target_values = list(normalize_source_synthesis_targets(target_values))
            else:
                target_values = [
                    normalize_output_target(item)
                    for item in target_values
                    if isinstance(item, (dict, OutputTarget))
                ]
        except (TypeError, ValueError) as exc:
            logging.warning(
                "Цели %s не удалось прочитать для редактора: %s",
                target_config_key,
                exc,
            )
            target_values = []
        if (
            getattr(self, "_export_running", False)
            or getattr(self, "_export_lock", False)
            or (source_context and getattr(self, "batch_processor", None) is not None)
            or (source_context and getattr(self, "_source_plan_running", False))
        ):
            return
        dialog = tk.Toplevel(self.root)
        dialog.withdraw()
        if source_context:
            dialog.title(f"Набор выходов — {source_book_name}")
            intro_text = (
                "«Отдельные файлы» — по одному на TXT; «Один файл» — по "
                "виртуальной группе, а без плана — по всему выбранному "
                "набору TXT. Можно добавить MP3 дважды: по главам и по "
                "группам, задав разные папки или шаблоны имён. Одна цель "
                "использует общую папку аудио; несколько — подпапки форматов "
                "или указанные пути."
            )
        else:
            dialog.title("Набор выходных форматов")
            intro_text = (
                "Выберите форматы. При одной активной цели все группы "
                "сохраняются в общей папке экспорта, указанной в основной "
                "вкладке; индивидуальный каталог строки не используется. "
                "При двух и более целях пустая строка получает отдельную "
                "подпапку формата, а заполненная строка задаёт осознанный "
                "отдельный путь. Кнопка «↺ Общая папка для всех» сбрасывает "
                "такие пути. В столбце «Сборка» каждый формат может наследовать "
                "флажок группы, объединяться в один файл или сохранять главы "
                "отдельно; M4B всегда объединяет главы книги."
            )
        dialog.transient(self.root)
        # Этот редактор владеет подготовленной копией списка целей. Не позволяем
        # основному окну или второму редактору менять состояние за ним, пока
        # пользователь явно не применит снимок или не отменит его.
        dialog.grab_set()
        dialog.resizable(True, True)

        # Храним цели упорядоченным списком. Формат не является уникальным
        # ключом: пользователь может обоснованно запросить, например, MP3 128 кбит/с
        # и MP3 64 кбит/с в разные каталоги. Прежнее представление в виде словаря
        # молча объединяло такие строки и не позволяло открыть редактор.
        existing_items = [
            copy.deepcopy(item)
            for item in target_values
            if isinstance(item, dict)
        ]
        profile_entries = audio_profile_entries_from_config(self.config)
        profile_by_id = {entry["id"]: entry for entry in profile_entries}
        # Стабильный идентификатор нужен в JSON/журналах, а не в каждой видимой
        # строке выпадающего списка. Имена уже сделаны уникальными нормализатором профилей;
        # короткий суффикс оставляем только как защиту от дубликатов имён.
        profile_labels = ["Текущие параметры"]
        profile_label_to_id = {}
        used_profile_labels = set(profile_labels)
        profile_label_by_id = {}
        for entry in profile_entries:
            name = str(entry["profile"].get("name") or "Профиль")
            label = name
            if label in used_profile_labels:
                label = f"{name} · {entry['id'][-6:]}"
            used_profile_labels.add(label)
            profile_labels.append(label)
            profile_label_to_id[label] = entry["id"]
            profile_label_by_id[entry["id"]] = label

        def profile_choices_for_format(fmt, old_profile=""):
            """Возвращает только профили, совместимые с одним форматом вывода.

            ``Текущие параметры`` доступен всегда. Удалённый или старый профиль,
            несовместимый с форматом, представлен временным элементом
            ``Недоступен``, поэтому применение диалога не перезаписывает молча
            старый JSON; выбрать такой профиль для изменённого формата нельзя.
            """
            fmt = str(fmt or "").strip().lower()
            choices = ["Текущие параметры"]
            for entry in profile_entries:
                if audio_profile_target_compatible(entry["profile"], fmt):
                    label = profile_label_by_id.get(entry["id"])
                    if label and label not in choices:
                        choices.append(label)
            if old_profile:
                entry = profile_by_id.get(old_profile)
                if entry is None or not audio_profile_target_compatible(
                    entry["profile"], fmt
                ):
                    base = f"Недоступен: {old_profile}"
                    missing_label = base
                    suffix = 2
                    while missing_label in profile_label_to_id and profile_label_to_id[
                        missing_label
                    ] != old_profile:
                        missing_label = f"{base} ({suffix})"
                        suffix += 1
                    profile_label_to_id[missing_label] = old_profile
                    if missing_label not in choices:
                        choices.append(missing_label)
            return choices

        def preferred_profile_for_format(fmt):
            """Выбирает сохранённый профиль, а для M4B — базовый AAC-LC."""
            preferred_key = (
                "default_book_audio_profile_id"
                if source_context
                else "default_export_audio_profile_id"
            )
            candidates = (
                str(self.config.get(preferred_key, "") or ""),
                "builtin:m4a-64k" if str(fmt).lower() == "m4b" else "",
            )
            for profile_id in candidates:
                entry = profile_by_id.get(profile_id)
                if entry is not None and audio_profile_target_compatible(
                    entry["profile"], fmt
                ):
                    return profile_id
            return ""
        if source_context:
            current_source_format = self.settings_vars.get("output_format")
            try:
                current_fmt = str(current_source_format.get()).lower()
            except (AttributeError, tk.TclError, TypeError, ValueError):
                current_fmt = str(self.config.get("output_format", "mp3")).lower()
        else:
            current_fmt = str(getattr(self, "export_fmt_var", tk.StringVar(value="mp3")).get()).lower()
        # Прокручиваем только строки целей. Нижний колонтитул и подсказка
        # остаются видимыми даже при большом количестве настроенных выходов.
        rows_shell = ttk.Frame(dialog)
        rows_shell.pack(fill=tk.BOTH, expand=True, padx=14)
        canvas_background = ttk.Style(dialog).lookup("TFrame", "background")
        if not canvas_background:
            canvas_background = dialog.cget("background")
        rows_canvas = tk.Canvas(
            rows_shell,
            # Увеличенная начальная высота оставляет несколько строк целей
            # видимыми до прокрутки. Canvas по-прежнему расширяется вместе с
            # диалогом, поэтому на большом мониторе его можно увеличить ещё.
            height=300,
            highlightthickness=0,
            bd=0,
            background=canvas_background,
        )
        rows_scroll = ttk.Scrollbar(
            rows_shell, orient=tk.VERTICAL, command=rows_canvas.yview
        )
        rows_horizontal_scroll = ttk.Scrollbar(
            rows_shell, orient=tk.HORIZONTAL, command=rows_canvas.xview
        )
        rows = ttk.Frame(rows_canvas)
        rows_window = rows_canvas.create_window((0, 0), window=rows, anchor="nw")
        rows_canvas.configure(
            yscrollcommand=rows_scroll.set,
            xscrollcommand=rows_horizontal_scroll.set,
        )
        rows_shell.columnconfigure(0, weight=1)
        rows_shell.rowconfigure(0, weight=1)
        rows_canvas.grid(row=0, column=0, sticky=tk.NSEW)
        rows_scroll.grid(row=0, column=1, sticky=tk.NS)
        rows_horizontal_scroll.grid(row=1, column=0, sticky=tk.EW)
        rows_horizontal_scroll.grid_remove()
        rows.columnconfigure(2, weight=2, minsize=120)
        rows.columnconfigure(4, weight=1, minsize=155)
        rows.columnconfigure(3, weight=1, minsize=110)
        rows.columnconfigure(5, weight=0, minsize=40)
        directory_sync_suspended = {"value": False}

        headers = (
            "", "Формат", "Папка (2+ цели)", "", "Профиль",
            "Сборка", "Том N/T", "Действия",
        )
        header_widgets = []
        for col, text in enumerate(headers):
            header = ttk.Label(rows, text=text)
            header.grid(
                row=0, column=col, sticky=tk.W, padx=3, pady=(0, 3)
            )
            header_widgets.append(header)
        controls = []

        def _sync_target_rows(_event=None):
            try:
                viewport_width = rows_canvas.winfo_width()
                # Сохраняем явную границу старого режима для совместимых
                # проверок, но теперь она управляет компактной строкой, а не
                # принудительной горизонтальной прокруткой.
                narrow_viewport = viewport_width < 857
                compact_layout = 1 < viewport_width < 900 or narrow_viewport
                visible_headers = (
                    ("", "Формат", "Профиль", "Сборка", "Том N/T", "Действия")
                    if compact_layout else headers
                )
                for column, header in enumerate(header_widgets):
                    if column < len(visible_headers):
                        header.configure(text=visible_headers[column])
                        header.grid()
                    else:
                        header.grid_remove()
                rows.columnconfigure(2, weight=1 if compact_layout else 2,
                                     minsize=155 if compact_layout else 120)
                rows.columnconfigure(4, weight=0 if compact_layout else 1,
                                     minsize=40 if compact_layout else 155)
                for row_control in controls:
                    if compact_layout != bool(row_control.get("compact_layout")):
                        row_control["compact_layout"] = compact_layout
                        _place_target_row(row_control, controls.index(row_control))
                    remove_button = row_control.get("remove_widget")
                    if remove_button is not None:
                        # На небольшом экране текстовая кнопка занимает место,
                        # необходимое для полей профиля и шаблона. Символ корзины
                        # остаётся однозначным, а на обычной ширине возвращается
                        # подпись для лучшей заметности действия.
                        try:
                            remove_button.configure(
                                text="🗑" if compact_layout else "🗑 Удалить",
                                width=3 if compact_layout else 11,
                            )
                        except tk.TclError:
                            pass
                    m4b_hint = row_control.get("m4b_hint_shell")
                    if m4b_hint is not None:
                        try:
                            if compact_layout:
                                m4b_hint.grid_configure(
                                    row=1,
                                    column=1,
                                    columnspan=2,
                                    sticky=tk.W,
                                    padx=(0, 0),
                                    pady=(4, 0),
                                )
                            else:
                                m4b_hint.grid_configure(
                                    row=0,
                                    column=2,
                                    columnspan=1,
                                    sticky=tk.W,
                                    padx=(8, 0),
                                    pady=(0, 0),
                                )
                        except tk.TclError:
                            pass
                    filename_hint = row_control.get("filename_hint_widget")
                    if filename_hint is not None:
                        try:
                            filename_hint.configure(
                                wraplength=(
                                    max(320, viewport_width - 220)
                                    if compact_layout
                                    else 680
                                )
                            )
                        except tk.TclError:
                            pass
                    filename_row = row_control.get("filename_template_row")
                    filename_entry = row_control.get("filename_template_widget")
                    filename_helper = row_control.get("filename_helper_widget")
                    chapter_row = row_control.get("chapter_template_row")
                    chapter_helper = row_control.get("chapter_helper_widget")
                    for row, entry, helper in (
                        (filename_row, filename_entry, filename_helper),
                        (chapter_row, row_control.get("chapter_template_entry"), chapter_helper),
                    ):
                        if row is None or entry is None or helper is None:
                            continue
                        try:
                            if compact_layout:
                                entry.grid_configure(row=0, column=0, sticky=tk.EW)
                                helper.grid_configure(
                                    row=1,
                                    column=0,
                                    sticky=tk.W,
                                    padx=0,
                                    pady=(4, 0),
                                )
                            else:
                                entry.grid_configure(row=0, column=0, sticky=tk.EW)
                                helper.grid_configure(
                                    row=0,
                                    column=1,
                                    sticky=tk.W,
                                    padx=(6, 0),
                                    pady=0,
                                )
                        except tk.TclError:
                            pass
                if viewport_width > 1:
                    # При обычной ширине сетка сама ужимает поля и не показывает
                    # лишнюю белую полосу. В узком режиме кнопка удаления
                    # становится компактной, а подсказка M4B переносится вниз,
                    # поэтому принудительная широкая полоса больше не нужна.
                    table_width = max(viewport_width, 857 if narrow_viewport else 0)
                    if compact_layout:
                        table_width = viewport_width
                    rows_canvas.itemconfigure(
                        rows_window,
                        width=table_width,
                    )
                rows_canvas.configure(scrollregion=rows_canvas.bbox("all"))
                bbox = rows_canvas.bbox("all")
                content_width = (
                    max(0, bbox[2] - bbox[0])
                    if bbox is not None
                    else 0
                )
                if viewport_width > 1 and content_width > viewport_width + 1:
                    rows_horizontal_scroll.grid()
                else:
                    rows_canvas.xview_moveto(0)
                    rows_horizontal_scroll.grid_remove()
            except tk.TclError:
                pass

        rows.bind("<Configure>", _sync_target_rows, add="+")
        rows_canvas.bind("<Configure>", _sync_target_rows, add="+")

        def _target_rows_wheel(event):
            try:
                delta = getattr(event, "delta", 0)
                if delta:
                    rows_canvas.yview_scroll(
                        -1 * int(delta / 120 or (-1 if delta < 0 else 1)),
                        "units",
                    )
                elif getattr(event, "num", None) == 4:
                    rows_canvas.yview_scroll(-3, "units")
                elif getattr(event, "num", None) == 5:
                    rows_canvas.yview_scroll(3, "units")
            except (AttributeError, tk.TclError, TypeError, ValueError):
                pass

        for wheel_widget in (rows_canvas, rows):
            wheel_widget.bind("<MouseWheel>", _target_rows_wheel, add="+")
            wheel_widget.bind("<Button-4>", _target_rows_wheel, add="+")
            wheel_widget.bind("<Button-5>", _target_rows_wheel, add="+")

        def _place_target_row(row_control, index):
            """Размещает одну логическую цель и необязательную строку сведений M4B."""
            compact_layout = bool(row_control.get("compact_layout"))
            row_stride = 3 if compact_layout else 2
            main_row = index * row_stride + 1
            main_widgets = tuple(row_control.get("main_widgets", ()))
            if compact_layout and len(main_widgets) >= 8:
                # На узком экране каталог переносится под основную строку.
                # Так поле шаблона и кнопки профилей не обрезаются и не требуют
                # горизонтальной прокрутки.
                compact_widgets = (
                    (0, main_widgets[0]),
                    (1, main_widgets[1]),
                    (2, main_widgets[4]),
                    (3, main_widgets[5]),
                    (4, main_widgets[6]),
                    (5, main_widgets[7]),
                )
                for column, widget in compact_widgets:
                    widget.grid(
                        row=main_row,
                        column=column,
                        padx=(3, 0) if column == 5 else 3,
                        sticky=tk.W,
                    )
                main_widgets[2].grid(
                    row=main_row + 1,
                    column=1,
                    columnspan=4,
                    sticky=tk.EW,
                    padx=3,
                    pady=(2, 0),
                )
                main_widgets[3].grid(
                    row=main_row + 1,
                    column=5,
                    sticky=tk.W,
                    padx=(3, 0),
                    pady=(2, 0),
                )
            else:
                for column, widget in enumerate(main_widgets):
                    options = {
                        "row": main_row,
                        "column": column,
                        "columnspan": 1,
                        "rowspan": 1,
                        "padx": (3, 0) if column == 7 else 3,
                    }
                    if column in (2, 4):
                        options["sticky"] = tk.EW
                    elif column in (0, 1, 5, 6):
                        options["sticky"] = tk.W
                    widget.grid(**options)

            detail = row_control.get("detail_widget")
            if detail is None:
                return
            detail.grid(
                row=main_row + (2 if compact_layout else 1),
                column=1,
                columnspan=6 if compact_layout else 7,
                sticky=tk.EW,
                padx=3,
                pady=(2, 4),
            )
            m4b_detail = row_control.get("m4b_detail_widget")
            if m4b_detail is not None:
                if row_control["format"].get() == "m4b":
                    m4b_detail.grid()
                else:
                    m4b_detail.grid_remove()

        def _row_profile_changed(row_control, *, initial=False, format_changed=True):
            # Изменение формата может сделать ранее выбранный профиль
            # несовместимым. Оставляем отсутствующий старый идентификатор видимым, но
            # заменяем похожее имя на «Текущие параметры», если оно больше
            # не подходит.
            selected = row_control["profile"].get()
            profile_id = profile_label_to_id.get(selected, "")
            fmt = row_control["format"].get()
            old_format = str(
                (row_control.get("old") or {}).get("format", "")
            ).strip().lower()
            if fmt != old_format and format_changed:
                if not initial:
                    # Новый формат должен начинаться с текущих полей/профиля,
                    # а не со снимков (битрейта, шаблона имени или эффектов),
                    # относящихся к прежнему кодеку/контейнеру.
                    row_control["old"] = {}
                    try:
                        row_control["filename_template"].set("")
                    except (AttributeError, tk.TclError):
                        pass
                if fmt == "m4b" and not profile_id:
                    preferred_id = preferred_profile_for_format(fmt)
                    preferred_label = profile_label_by_id.get(preferred_id)
                    if preferred_label:
                        row_control["profile"].set(preferred_label)
                        profile_id = preferred_id
            if profile_id:
                entry = profile_by_id.get(profile_id)
                if entry is None or not audio_profile_target_compatible(
                    entry["profile"], fmt
                ):
                    # Отсутствующий ``id`` можно сохранять, только пока исходный
                    # формат не изменён (чтобы старый JSON проходил цикл чтения и записи).
                    # После изменения формата строки небезопасно переносить
                    # несовместимую ссылку в новую цель.
                    if (
                        not selected.startswith("Недоступен:")
                        or fmt != old_format
                    ):
                        row_control["profile"].set("Текущие параметры")
                        profile_id = ""
            choices = profile_choices_for_format(fmt, profile_id)
            if row_control.get("old") and fmt == old_format:
                choices = ["Сохранённые параметры", *choices]
            row_control["profile_values"] = choices
            row_control["profile_widget"].configure(values=choices)
            if row_control["profile"].get() not in choices:
                row_control["profile"].set("Текущие параметры")
            assembly_widget = row_control.get("assembly_widget")
            assembly_var = row_control.get("assembly")
            if assembly_widget is not None and assembly_var is not None:
                try:
                    if fmt == "m4b":
                        assembly_var.set(OUTPUT_TARGET_ASSEMBLY_LABELS["merge"])
                        assembly_widget.state(["disabled"])
                    elif source_context:
                        if assembly_var.get() not in (
                            OUTPUT_TARGET_ASSEMBLY_LABELS["files"],
                            OUTPUT_TARGET_ASSEMBLY_LABELS["merge"],
                        ):
                            assembly_var.set(OUTPUT_TARGET_ASSEMBLY_LABELS["files"])
                        assembly_widget.state(["!disabled", "readonly"])
                    else:
                        if assembly_var.get() not in OUTPUT_TARGET_ASSEMBLY_BY_LABEL:
                            assembly_var.set(
                                OUTPUT_TARGET_ASSEMBLY_LABELS["inherit"]
                            )
                        assembly_widget.state(["!disabled", "readonly"])
                except tk.TclError:
                    pass
            track_widget = row_control.get("track_widget")
            if track_widget is not None:
                try:
                    if fmt == "m4b":
                        track_widget.state(["!disabled"])
                    else:
                        track_widget.state(["disabled"])
                except tk.TclError:
                    pass
            detail = row_control.get("detail_widget")
            if detail is not None:
                try:
                    label = row_control.get("filename_label_widget")
                    if label is not None:
                        label.configure(
                            text=(
                                "Имя файла части:"
                                if fmt == "m4b"
                                else "Шаблон имени файла:"
                            )
                        )
                    hint = row_control.get("filename_hint_widget")
                    if hint is not None:
                        hint.configure(
                            text=(
                                (
                                    "Для синтеза из папки имя части задаётся в плане M4B. "
                                    "Измените его там; это поле цели не используется."
                                    if source_context and fmt == "m4b"
                                    else (
                                        "Пусто — имя группы; при нескольких частях добавляется «Часть N». "
                                        "Поля: {book}, {part}, {range}, {first_name}, {last_name}, {filename}."
                                        if fmt == "m4b"
                                        else (
                                            "Пусто — имя виртуальной группы, а без плана — имя книги. "
                                            "Поля: {name}, {filename}, {index}, {book}, {group}, {range}."
                                            if source_context and assembly_var.get()
                                            == OUTPUT_TARGET_ASSEMBLY_LABELS["merge"]
                                            else (
                                                "Пусто — имя TXT. Поля: {name}, {filename}, {index}, {book}, {group}, {range}."
                                                if source_context
                                                else "Пусто — имя Title. Поля: {name}, {filename}, {index}, {book}, {group}, {source_name}, {range}."
                                            )
                                        )
                                    )
                                )
                            )
                        )
                    filename_entry = row_control.get("filename_template_widget")
                    filename_helper = row_control.get("filename_helper_widget")
                    for widget in (filename_entry, filename_helper):
                        if widget is None:
                            continue
                        if source_context and fmt == "m4b":
                            widget.state(["disabled"])
                        else:
                            widget.state(["!disabled"])
                    detail.grid()
                    m4b_detail = row_control.get("m4b_detail_widget")
                    if m4b_detail is not None:
                        if fmt == "m4b":
                            m4b_detail.grid()
                        else:
                            m4b_detail.grid_remove()
                except tk.TclError:
                    pass
            _sync_target_rows()

        def _destroy_target_rows():
            for row_control in list(controls):
                for widget in row_control.get("widgets", ()):
                    try:
                        widget.destroy()
                    except tk.TclError:
                        pass
            controls.clear()

        def _sync_target_directory_controls(*_args):
            """Показывает каталоги строк только для настоящего набора из нескольких целей."""
            if directory_sync_suspended["value"]:
                return
            active_count = 0
            for item in controls:
                try:
                    active_count += bool(item["enabled"].get())
                except (KeyError, AttributeError, tk.TclError):
                    continue
            allow_overrides = active_count >= 2
            for item in controls:
                try:
                    active = bool(item["enabled"].get())
                except (KeyError, AttributeError, tk.TclError):
                    active = False
                entry_widget = item.get("directory_widget")
                choose_widget = item.get("directory_choose_widget")
                # Не очищаем подготовленный каталог только потому, что
                # пользователь временно отключил другую строку. Поле каталога
                # входит в несохранённый снимок редактора и должно переживать
                # цикл отключения/повторного включения. Политика каталога для
                # одной цели применяется лишь при сборе/применении строк
                # (через ``normalize_output_target_directories``) либо после
                # явного действия «Общая папка» ниже.
                for widget in (entry_widget, choose_widget):
                    if widget is None:
                        continue
                    try:
                        if allow_overrides:
                            widget.state(["!disabled"])
                        else:
                            widget.state(["disabled"])
                    except (AttributeError, tk.TclError):
                        pass

        def target_preview_data(row_control):
            """Показывает имена из дерева той вкладки, где открыт редактор."""
            fmt = row_control["format"].get()
            if not source_context:
                return self._template_helper_export_preview_data(format_hint=fmt)
            snapshot = self._template_helper_source_preview_data()
            if fmt == "m4b":
                return snapshot
            if row_control["assembly"].get() == OUTPUT_TARGET_ASSEMBLY_LABELS["merge"]:
                contexts = [dict(item) for item in snapshot.get("contexts", ())]
                for item in contexts:
                    item["range"] = format_chapter_range(
                        item["first_index"], item["last_index"],
                        total_count=item["chapter_count"],
                    )
            else:
                paths = getattr(self, "_source_path_by_id", {})
                file_ids = tuple(self._source_tree_file_ids())
                book = resolve_source_book_name(self.config)
                contexts = []
                for index, file_id in enumerate(file_ids, 1):
                    if file_id not in paths:
                        continue
                    stem = Path(paths[file_id]).stem
                    contexts.append({
                        "book": book, "name": stem, "group": book,
                        "title": stem, "source_name": stem,
                        "source_title": stem, "filename": stem,
                        "index": index, "chapter": index,
                        "chapter_count": len(file_ids), "range": str(index),
                    })
            profile = profile_label_to_id.get(row_control["profile"].get(), "")
            for item in contexts:
                item.update(format=fmt, ext=fmt, profile=profile)
            return {
                "file_contexts": contexts,
                "grouped_source": row_control["assembly"].get()
                == OUTPUT_TARGET_ASSEMBLY_LABELS["merge"],
            }

        def add_target_row(old=None, *, enabled_default=True):
            old = copy.deepcopy(old or {})
            fmt = str(old.get("format") or current_fmt or "mp3").strip().lower()
            if fmt not in EXPORT_OUTPUT_FORMATS:
                fmt = current_fmt if current_fmt in EXPORT_OUTPUT_FORMATS else "mp3"
            enabled = tk.BooleanVar(
                value=_config_bool(old.get("enabled", enabled_default), default=enabled_default)
            )
            include_track_metadata = tk.BooleanVar(
                value=_config_bool(
                    old.get("include_track_metadata"), default=True
                )
            )
            chapter_title_template = tk.StringVar(
                value=str(old.get("chapter_title_template", "") or "")
            )
            initial_filename_template = str(
                old.get("filename_template", "") or ""
            )
            if fmt == "m4b" and not source_context and "filename_template" not in old:
                current_m4b_template = getattr(self, "export_m4b_template_var", None)
                try:
                    initial_filename_template = str(
                        current_m4b_template.get() if current_m4b_template is not None else ""
                    ).strip()
                except (AttributeError, tk.TclError, TypeError, ValueError):
                    initial_filename_template = str(
                        self.config.get("export_m4b_template", "") or ""
                    ).strip()
            filename_template = tk.StringVar(value=initial_filename_template)
            format_var = tk.StringVar(value=fmt)
            directory = tk.StringVar(value=str(old.get("output_dir", "")))
            assembly_mode = str(
                old.get("assembly_mode") or "inherit"
            ).strip().lower()
            if assembly_mode not in OUTPUT_TARGET_ASSEMBLY_MODES:
                assembly_mode = "inherit"
            if fmt == "m4b":
                assembly_mode = "merge"
            elif source_context and assembly_mode == "inherit":
                assembly_mode = "files"
            assembly_var = tk.StringVar(
                value=OUTPUT_TARGET_ASSEMBLY_LABELS[assembly_mode]
            )
            old_profile = str(old.get("profile", ""))
            choices = profile_choices_for_format(fmt, old_profile)
            if old:
                choices = ["Сохранённые параметры", *choices]
            if old_profile in profile_by_id and audio_profile_target_compatible(
                profile_by_id[old_profile]["profile"], fmt
            ):
                profile_default = profile_label_by_id[old_profile]
            elif old_profile:
                profile_default = next(
                    (item for item in choices if item.startswith("Недоступен:")),
                    "Текущие параметры",
                )
            elif old:
                profile_default = "Сохранённые параметры"
            else:
                preferred_id = preferred_profile_for_format(fmt)
                profile_default = profile_label_by_id.get(
                    preferred_id, "Текущие параметры"
                )
            profile_var = tk.StringVar(value=profile_default)
            row_control = {
                "enabled": enabled,
                "include_track_metadata": include_track_metadata,
                "filename_template": filename_template,
                "chapter_title_template": chapter_title_template,
                "format": format_var,
                "directory": directory,
                "assembly": assembly_var,
                "profile": profile_var,
                "initial_profile": profile_default,
                "audio_selection_changed": False,
                "profile_widget": None,
                "profile_values": choices,
                "old": old,
                "widgets": [],
            }
            check = ttk.Checkbutton(rows, variable=enabled)
            format_combo = ttk.Combobox(
                rows, textvariable=format_var, values=EXPORT_OUTPUT_FORMATS,
                state="readonly", width=9,
            )
            entry = ttk.Entry(rows, textvariable=directory, width=24)
            choose_button = ttk.Button(
                rows, text="📁", width=3,
                command=lambda var=directory: self._choose_output_target_dir(
                    var, parent=dialog
                ),
            )
            profile_combo = ttk.Combobox(
                rows, textvariable=profile_var, values=choices,
                state="readonly", width=24,
            )
            assembly_combo = ttk.Combobox(
                rows,
                textvariable=assembly_var,
                values=(
                    tuple(OUTPUT_TARGET_ASSEMBLY_LABELS[mode] for mode in ("files", "merge"))
                    if source_context
                    else tuple(OUTPUT_TARGET_ASSEMBLY_LABELS.values())
                ),
                state="readonly",
                width=15,
            )
            if fmt == "m4b":
                assembly_combo.state(["disabled"])
            track_check = ttk.Checkbutton(
                rows,
                text="N/T",
                variable=include_track_metadata,
            )
            if fmt != "m4b":
                track_check.state(["disabled"])
            # Оставляем удаление явным. Старую кнопку только со знаком минус
            # было легко не заметить; она выглядела скорее как компактный
            # переключатель, чем как разрушающее действие. Кнопка по-прежнему
            # действует на свою строку, поэтому после перестановки не устаревает
            # дополнительное состояние выделения.
            remove_button = ttk.Button(
                rows,
                text="🗑 Удалить",
                width=11,
                command=lambda item=row_control: remove_target_row(item),
            )
            detail_shell = ttk.Frame(rows)
            detail_shell.columnconfigure(1, weight=1)
            filename_label = ttk.Label(
                detail_shell,
                text=("Имя файла части:" if fmt == "m4b" else "Шаблон имени файла:"),
            )
            filename_label.grid(
                row=0,
                column=0,
                sticky=tk.W,
                padx=(0, 6),
                pady=(0, 3),
            )
            filename_template_row = ttk.Frame(detail_shell)
            filename_template_row.grid(row=0, column=1, sticky=tk.EW)
            filename_template_row.columnconfigure(0, weight=1)
            filename_template_entry = ttk.Entry(
                filename_template_row,
                textvariable=filename_template,
                width=40,
            )
            filename_template_entry.grid(row=0, column=0, sticky=tk.EW)
            filename_helper_button = ttk.Button(
                filename_template_row,
                text="Помощник…",
                command=lambda var=filename_template, entry=filename_template_entry, fmt_var=format_var, row=row_control: self._open_template_helper(
                    var,
                    "m4b_part" if fmt_var.get() == "m4b" else "output_file",
                    owner=dialog,
                    target_entry=entry,
                    title=(
                        "Помощник имени части M4B"
                        if fmt_var.get() == "m4b"
                        else "Помощник имени выходного файла"
                    ),
                    preview_data=target_preview_data(row),
                ),
            )
            filename_helper_button.grid(row=0, column=1, padx=(6, 0))
            filename_hint = self._register_palette_widget(
                ttk.Label(
                    detail_shell,
                    text=(
                        "Пусто — имя Title. Поля: {name}, {filename}, {index}, "
                        "{book}, {group}, {source_name}, {range}."
                    ),
                    foreground=self.get_status_color("muted"),
                    justify=tk.LEFT,
                    anchor=tk.W,
                    wraplength=680,
                ),
                "muted",
            )
            filename_hint.grid(
                row=1,
                column=1,
                sticky=tk.EW,
                padx=(0, 6),
                pady=(0, 4),
            )
            if source_context and fmt == "m4b":
                filename_template_entry.state(["disabled"])
                filename_helper_button.state(["disabled"])
                filename_hint.configure(
                    text=(
                        "Для синтеза из папки имя части задаётся в плане M4B. "
                        "Измените его там; это поле цели не используется."
                    )
                )
            m4b_detail = ttk.Frame(detail_shell)
            m4b_detail.columnconfigure(1, weight=1)
            m4b_detail.grid(row=2, column=0, columnspan=3, sticky=tk.EW)
            ttk.Label(m4b_detail, text="Метки глав M4B:").grid(
                row=0, column=0, sticky=tk.W, padx=(0, 6)
            )
            chapter_template_row = ttk.Frame(m4b_detail)
            chapter_template_row.grid(row=0, column=1, sticky=tk.EW)
            chapter_template_row.columnconfigure(0, weight=1)
            chapter_template_entry = ttk.Entry(
                chapter_template_row,
                textvariable=chapter_title_template,
                width=40,
            )
            chapter_template_entry.grid(row=0, column=0, sticky=tk.EW)
            chapter_helper_button = ttk.Button(
                chapter_template_row,
                text="Помощник…",
                command=lambda var=chapter_title_template, entry=chapter_template_entry, row=row_control: (
                    self._open_template_helper(
                        var,
                        "m4b_chapter",
                        owner=dialog,
                        target_entry=entry,
                        title="Помощник меток глав M4B",
                        preview_data=target_preview_data(row),
                    )
                ),
            )
            chapter_helper_button.grid(row=0, column=1, padx=(6, 0))
            hint_shell, _hint_body, _hint_toggle = self._make_collapsible_hint(
                m4b_detail,
                "Пустое поле сохраняет исходные названия глав. "
                "Пример: Глава {volume_index:03d}: {name}. "
                "{global_index} — сквозной номер по книге; {volume_index} — "
                "номер в текущем томе, он начинается с 1 заново. "
                "После двоеточия можно задать начало шкалы: "
                "{global_index:10} означает 10 для первой главы книги и "
                "продолжает глобальную позицию в следующих томах; "
                "{volume_index:10} означает 10 для первой главы каждого "
                "тома. Запись :03d задаёт ширину и ведущие нули. "
                "Доступные поля: "
                + ", ".join(
                    "{" + field + "}"
                    for field in M4B_CHAPTER_TEMPLATE_FIELD_ORDER
                ),
                title="Поля шаблона",
                wraplength=680,
                initially_open=False,
            )
            hint_shell.grid(row=0, column=2, sticky=tk.W, padx=(8, 0))
            row_control["profile_widget"] = profile_combo
            row_control["format_widget"] = format_combo
            row_control["assembly_widget"] = assembly_combo
            row_control["track_widget"] = track_check
            row_control["directory_widget"] = entry
            row_control["directory_choose_widget"] = choose_button
            row_control["filename_label_widget"] = filename_label
            row_control["filename_template_widget"] = filename_template_entry
            row_control["filename_helper_widget"] = filename_helper_button
            row_control["filename_hint_widget"] = filename_hint
            row_control["filename_template_row"] = filename_template_row
            row_control["chapter_template_row"] = chapter_template_row
            row_control["chapter_template_entry"] = chapter_template_entry
            row_control["chapter_helper_widget"] = chapter_helper_button
            row_control["remove_widget"] = remove_button
            row_control["m4b_hint_shell"] = hint_shell
            row_control["detail_widget"] = detail_shell
            row_control["m4b_detail_widget"] = m4b_detail
            row_control["main_widgets"] = [
                check, format_combo, entry, choose_button, profile_combo,
                assembly_combo, track_check, remove_button,
            ]
            row_control["widgets"] = row_control["main_widgets"] + [detail_shell]
            controls.append(row_control)
            _place_target_row(row_control, len(controls) - 1)
            format_var.trace_add(
                "write", lambda *_args, item=row_control: _row_profile_changed(item)
            )
            profile_combo.bind(
                "<<ComboboxSelected>>",
                lambda _event, item=row_control: item.__setitem__("audio_selection_changed", True),
                add="+",
            )
            assembly_combo.bind(
                "<<ComboboxSelected>>",
                lambda _event, item=row_control: _row_profile_changed(
                    item, format_changed=False
                ),
                add="+",
            )
            # Обновляем подпись и подсказку сразу. Trace срабатывает только
            # при последующем изменении формата, поэтому без этого вызова
            # уже созданная строка M4B показывала подсказку обычного файла.
            _row_profile_changed(row_control, initial=True)
            enabled.trace_add("write", _sync_target_directory_controls)
            _sync_target_directory_controls()
            return row_control

        def remove_target_row(row_control):
            if row_control not in controls:
                return
            # Редактор целей всегда должен сохранять хотя бы одну редактируемую
            # строку. Это инвариант интерфейса, а не правило хранения: пользователь всё
            # ещё может отменить диалог или выбрать «Основной формат» в контексте
            # источника, полностью выйдя из режима нескольких целей. Эта защита
            # также не позволяет случайному клику превратить набор экспорта в
            # недопустимое пустое состояние редактора.
            if len(controls) <= 1:
                self._show_info(
                    "Нельзя удалить цель",
                    "В наборе должна остаться хотя бы одна цель. "
                    "Изменения будут сохранены только после нажатия «Применить».",
                    parent=dialog,
                )
                return
            controls.remove(row_control)
            for widget in row_control.get("widgets", ()):
                try:
                    widget.destroy()
                except tk.TclError:
                    pass
            # Повторно раскладываем оставшиеся строки, чтобы после удаления цели
            # не возникало пустот. Повторное использование виджетов сохраняет
            # привязки переменных.
            for index, item in enumerate(controls):
                _place_target_row(item, index)
            _sync_target_directory_controls()
            _sync_target_rows()

        def use_common_directory_for_targets():
            """Очищает каталоги целей после явного действия пользователя.

            Каталог является осознанным переопределением только в наборе из
            нескольких целей; одна активная цель автоматически использует общую
            папку. Это действие сразу сбрасывает все назначения нескольких целей.
            Оно меняет только несохранённые строки диалога; файлы и сохранённые
            настройки затрагиваются лишь после «Применить».
            """
            explicit_count = 0
            for item in controls:
                variable = item.get("directory")
                if variable is None:
                    continue
                try:
                    explicit_count += bool(str(variable.get() or "").strip())
                except (AttributeError, tk.TclError, TypeError, ValueError):
                    # Закрывающаяся/частично уничтоженная строка Tk не должна
                    # передавать исключение из обратного вызова действия в цикл событий;
                    # обычный путь «Применить» всё равно проверяет значения.
                    continue
            if not explicit_count:
                return
            if not self._ask_yes_no(
                "Использовать общую папку",
                "Очистить индивидуальные папки у целей и передать их "
                "планировщику?\n\n"
                "При одной цели будет использована общая папка; при "
                "нескольких целях программа создаст отдельные подпапки "
                "форматов. Файлы на диске не изменяются.",
                parent=dialog,
                icon="warning",
            ):
                return
            for item in controls:
                variable = item.get("directory")
                if variable is not None:
                    try:
                        variable.set("")
                    except (AttributeError, tk.TclError):
                        pass

        directory_sync_suspended["value"] = True
        try:
            if existing_items:
                for old in existing_items:
                    add_target_row(old, enabled_default=True)
            else:
                add_target_row(None, enabled_default=True)
        finally:
            directory_sync_suspended["value"] = False
        _sync_target_directory_controls()

        target_actions = ttk.Frame(dialog)
        target_actions.pack(fill=tk.X, padx=14, pady=(4, 0))
        add_target_button = ttk.Button(
            target_actions,
            text="＋ Добавить цель",
            command=lambda: add_target_row({}, enabled_default=True),
        )
        add_target_button.pack(side=tk.LEFT)
        ttk.Button(
            target_actions,
            text="↺ Общая папка для всех",
            command=use_common_directory_for_targets,
        ).pack(side=tk.LEFT, padx=(8, 0))

        target_help_text = (
            (
                "Обычная склейка поддерживает эффекты и сохраняет заданные "
                "группы целиком. M4B всегда объединяет главы без эффектов; "
                "его имена и границы задаются в плане, а N/T — номера томов "
                "в медиатеке. Профиль копируется в цель при применении; "
                "последующая правка профиля цель не меняет."
            )
            if source_context
            else (
                "Профиль копирует параметры в цель при нажатии «Применить»; "
                "последующее редактирование профиля цель не меняет. Для M4B "
                "доступен совместимый AAC-профиль без эффектов, а каждый файл "
                "группы становится главой. Поле «Шаблон имени файла» задаёт "
                "имя каждого результата, в том числе при разборе M4B; поле "
                "«Метки глав M4B» меняет названия глав, а пустое значение "
                "сохраняет исходные. Флажок N/T добавляет дополнительный номер "
                "тома для сортировки в медиатеке."
            )
        )
        target_help_text += (
            " Сохранённые параметры оставляют настройки звука этой цели. "
            "Чтобы заменить их, явно выберите профиль или «Текущие параметры» "
            "для копирования общих настроек."
        )
        detailed_target_help = normalize_display_text(
            f"{intro_text} {target_help_text}", fallback=""
        )
        target_hint_shell, target_help, _target_hint_toggle = (
            self._make_collapsible_hint(
                dialog,
                detailed_target_help,
                title="О наборе выходов",
                wraplength=760,
                initially_open=False,
            )
        )
        target_hint_shell.pack(fill=tk.X, anchor=tk.W, padx=14, pady=(8, 4))

        buttons = ttk.Frame(dialog)
        # Сначала резервируем нижние действия: раскрытая подсказка должна
        # уменьшать область прокрутки, а не выталкивать «Применить» за окно.
        buttons.pack(side=tk.BOTTOM, before=rows_shell, fill=tk.X, padx=14, pady=(6, 12))
        target_hint_shell.pack_configure(side=tk.BOTTOM, before=rows_shell)
        target_actions.pack_configure(side=tk.BOTTOM, before=rows_shell)
        result = {"saved": False}

        # Компактные элементы управления имеют разные имена на двух вкладках.
        # Разрешаем их лениво, чтобы диалог целей источника не зависел от уже
        # созданных виджетов экспорта.
        target_var_names = {
            "format": "output_format" if source_context else "export_fmt_var",
            "bitrate": "output_bitrate" if source_context else "export_bitrate_var",
            "sample_rate": "output_sample_rate" if source_context else "export_sample_rate_var",
            "channels": "output_channels" if source_context else "export_channels_var",
            "apply_effects": "fx_enabled" if source_context else "export_apply_fx_var",
            "speed": "fx_speed" if source_context else "exp_speed_var",
            "pitch": "fx_pitch" if source_context else "exp_pitch_var",
            "echo": "fx_echo" if source_context else "exp_echo_var",
            "echo_delay": "fx_echo_delay" if source_context else "exp_delay_var",
            "echo_decay": "fx_echo_decay" if source_context else "exp_decay_var",
            # Для M4B исходников задан речевой битрейт AAC по умолчанию 64 кбит/с. Он не
            # должен наследовать компактный битрейт MP3 (обычно 128 кбит/с) лишь
            # потому, что текущий формат книги — MP3.
            "m4b_bitrate": "synthesis_m4b_bitrate_var" if source_context else "export_m4b_bitrate_var",
            "m4b_hours": "synthesis_m4b_hours_var" if source_context else "export_m4b_hours_var",
            "m4b_chapters": "synthesis_m4b_chapters_var" if source_context else "export_m4b_chapters_var",
            "m4b_template": "synthesis_m4b_template_var" if source_context else "export_m4b_template_var",
        }
        target_config_keys = {
            # Группировкой M4B исходников владеет диалог виртуального плана источника;
            # в нём нет компактных полей часов/глав/шаблона для каждой цели.
            # Оставляем эти значения пустыми, не заимствуя настройки экспорта.
            "m4b_hours": None if source_context else "export_m4b_max_duration_hours",
            "m4b_chapters": None if source_context else "export_m4b_max_chapters",
            "m4b_template": None if source_context else "export_m4b_template",
            "m4b_bitrate": "synthesis_m4b_bitrate" if source_context else "export_m4b_bitrate",
        }

        def _current_export_value(variable_name, fallback):
            # Сохраняем имя помощника для совместимости с вызывающими сторонами;
            # в контексте источника он также читает ``settings_vars``.
            variable = None
            if source_context:
                variable = self.settings_vars.get(variable_name)
            if variable is None:
                variable = getattr(self, variable_name, None)
            if variable is None:
                return fallback
            try:
                value = variable.get()
            except (
                AttributeError,
                tk.TclError,
                TypeError,
                ValueError,
                OverflowError,
            ):
                return fallback
            return value if str(value).strip() else fallback

        def _current_target_value(field, fallback):
            return _current_export_value(target_var_names.get(field, field), fallback)

        def _target_config_value(field, fallback):
            key = target_config_keys.get(field)
            if key is None:
                return fallback
            value = self.config.get(key, fallback)
            return value if value not in (None, "") else fallback

        def _current_target_template():
            """Читает текущий шаблон M4B, не считая пустое значение отсутствующим.

            Компактное поле M4B намеренно допускает пустое значение (оно просит
            планировщик использовать короткое запасное имя). Общая вспомогательная
            функция значений выше обоснованно подставляет резервное значение для пустых
            необязательных полей, но здесь это скопировало бы устаревшее значение
            ``{book} Главы {range}`` в новую строку цели до выполнения отложенного
            сохранения настроек.
            """
            variable = None
            if source_context:
                variable = self.settings_vars.get(
                    target_var_names.get("m4b_template")
                )
            if variable is None:
                variable = getattr(
                    self, target_var_names.get("m4b_template", ""), None
                )
            if variable is not None:
                try:
                    return str(variable.get() or "").strip()
                except (
                    AttributeError,
                    tk.TclError,
                    TypeError,
                    ValueError,
                    OverflowError,
                ):
                    pass
            # У вызова без интерфейса или вызова старого формата может не быть компактной
            # переменной Tk; в таком случае используем сохранённое значение,
            # сохраняя явную пустую строку вместо жёстко заданного значения.
            return str(
                _target_config_value("m4b_template", "") or ""
            ).strip()

        def _selected_export_value(
            profile_id,
            profile_values,
            old,
            key,
            current_variable,
            fallback,
            saved_key=None,
        ):
            """Разрешает одно поле снимка, не обращаясь преждевременно к переменным Tk.

            Именованный профиль имеет приоритет для содержащихся в нём полей.
            Специальный выбор ``Текущие параметры`` (пустой идентификатор профиля)
            намеренно читает текущие компактные элементы, даже если ``old``
            содержит снимок после прежнего нажатия «Применить». Временно нечитаемый
            введённый элемент использует сохранённое поле, поэтому частично
            отредактированный диалог безопасно проходит цикл чтения и записи. Для
            импортированного/удалённого профиля сохраняем значение цели и
            обращаемся к текущим элементам только при отсутствии этого поля.
            Важно выполнять поиск текущего значения внутри ветвей: незавершённый
            ``DoubleVar``/``IntVar`` в несвязанном компактном элементе не должен
            делать невозможным применение корректного сохранённого профиля.
            """
            if profile_id and key in profile_values:
                return profile_values[key]
            if not profile_id:
                # Частично отредактированная переменная Tk может быть нечитаемой.
                # Только в этом случае предпочитаем корректный сохранённый снимок,
                # но любое корректное текущее значение всё равно заменяет
                # устаревший снимок.
                missing = object()
                current = _current_export_value(current_variable, missing)
                if current is not missing:
                    return current
                saved_key = key if saved_key is None else saved_key
                if saved_key in old:
                    return old[saved_key]
                return fallback
            saved_key = key if saved_key is None else saved_key
            if saved_key in old:
                return old[saved_key]
            return _current_export_value(current_variable, fallback)

        def collect_targets():
            selected = []
            for row_control in controls:
                fmt = str(row_control["format"].get() or "").strip().lower()
                if fmt not in EXPORT_OUTPUT_FORMATS:
                    raise ValueError("Неизвестный формат цели: " + fmt)
                enabled = row_control["enabled"]
                directory = row_control["directory"]
                old = row_control.get("old") or {}
                if not isinstance(old, dict):
                    old = {}
                # Сохраняем явно отключённую цель, чтобы повторное открытие и
                # применение диалога её не стирало. Строки, которые никогда не
                # входили в набор и остаются снятыми, — лишь заполнители интерфейса; их
                # не следует сериализовать как шесть отключённых форматов.
                if not enabled.get() and not old:
                    continue
                assembly_mode = OUTPUT_TARGET_ASSEMBLY_BY_LABEL.get(
                    str(row_control["assembly"].get() or "").strip(),
                    "inherit",
                )
                if fmt == "m4b":
                    assembly_mode = "merge"
                elif source_context and assembly_mode == "inherit":
                    assembly_mode = "files"
                if (
                    old
                    and fmt == str(old.get("format", "")).strip().lower()
                    and (
                        row_control["profile"].get() == "Сохранённые параметры"
                        or (
                            not row_control.get("audio_selection_changed")
                            and row_control["profile"].get() == row_control.get("initial_profile")
                        )
                    )
                ):
                    # Каталог, имя и способ сборки не заменяют сохранённый звук
                    # настройками другого профиля. Его параметры копируются
                    # повторно только после явного выбора в этой строке.
                    target = copy.deepcopy(old)
                    target.update(
                        output_dir=directory.get().strip(),
                        enabled=bool(enabled.get()),
                        assembly_mode=assembly_mode,
                        filename_template=(
                            "" if source_context and fmt == "m4b"
                            else row_control["filename_template"].get()
                        ),
                        chapter_title_template=row_control["chapter_title_template"].get(),
                        include_track_metadata=_config_bool(
                            row_control["include_track_metadata"].get(), default=True
                        ),
                    )
                    try:
                        selected.append(normalize_output_target(target))
                    except (TypeError, ValueError) as exc:
                        raise ValueError(f"{fmt.upper()}: {exc}") from exc
                    continue
                profile_id = profile_label_to_id.get(
                    row_control["profile"].get(), ""
                )
                if profile_id and fmt == "m4b":
                    # Старая или импортированная строка может ссылаться на AAC-профиль,
                    # в котором эффекты были включены до появления ограничения
                    # M4B на временную шкалу глав. Такой профиль оставляем видимым
                    # как «Недоступен» для диагностики, но не сохраняем снова как
                    # выбранный профиль M4B.
                    profile_entry = profile_by_id.get(profile_id)
                    if profile_entry is None or not audio_profile_target_compatible(
                        profile_entry["profile"], "m4b"
                    ):
                        profile_id = ""
                        try:
                            row_control["profile"].set("Текущие параметры")
                        except (AttributeError, tk.TclError, TypeError, ValueError):
                            pass
                profile_values = {}
                if profile_id:
                    entry = profile_by_id.get(profile_id)
                    if entry is not None and audio_profile_target_compatible(
                        entry["profile"], fmt
                    ):
                        profile_values = audio_profile_config_values(
                            entry["profile"], target_profile_scope
                        )
                profile_effects_enabled = False
                if profile_id:
                    entry = profile_by_id.get(profile_id)
                    if entry is not None and audio_profile_target_compatible(
                        entry["profile"], fmt
                    ):
                        try:
                            profile_effects_enabled = bool(
                                normalize_audio_profile(entry["profile"])["audio"]
                                ["effects"].get("enabled", False)
                            )
                        except (TypeError, ValueError, KeyError):
                            profile_effects_enabled = False
                        if source_context:
                            profile_values["fx_enabled"] = profile_effects_enabled
                old_effects = old.get("effects", {})
                if not isinstance(old_effects, dict):
                    old_effects = {}
                if fmt == "m4b":
                    bitrate = str(
                        _selected_export_value(
                            profile_id,
                            profile_values,
                            old,
                            "output_bitrate" if source_context else "export_bitrate",
                            target_var_names["m4b_bitrate"],
                            _target_config_value("m4b_bitrate", "64k"),
                            "bitrate",
                        )
                        or "64k"
                    )
                    sample_rate = _selected_export_value(
                        profile_id,
                        profile_values,
                        old,
                        "output_sample_rate" if source_context else "export_sample_rate",
                        target_var_names["sample_rate"],
                        "auto",
                        "sample_rate",
                    )
                    channels = _selected_export_value(
                        profile_id,
                        profile_values,
                        old,
                        "output_channels" if source_context else "export_channels",
                        target_var_names["channels"],
                        "auto",
                        "channels",
                    )
                    if "max_duration_seconds" in old:
                        max_duration = old["max_duration_seconds"]
                    else:
                        raw_hours = _current_target_value(
                            "m4b_hours", _target_config_value("m4b_hours", 0)
                        )
                        try:
                            max_duration = float(raw_hours or 0) * 3600
                        except (TypeError, ValueError, OverflowError):
                            max_duration = 0.0
                    if "max_chapters" in old:
                        max_chapters = old["max_chapters"]
                    else:
                        raw_chapters = _current_target_value(
                            "m4b_chapters", _target_config_value("m4b_chapters", 0)
                        )
                        try:
                            max_chapters = int(float(raw_chapters or 0))
                        except (TypeError, ValueError, OverflowError):
                            max_chapters = 0
                    # Для синтеза из папки именами частей управляет виртуальный план
                    # источников. В обычном экспорте шаблон строки цели управляет
                    # именем каждой M4B-части и виден рядом с шаблоном меток глав.
                    if source_context:
                        filename_template = ""
                    elif "filename_template" in old:
                        filename_template = row_control["filename_template"].get()
                    else:
                        filename_template = _current_target_template()
                        # Новая строка уже получила текущее значение в поле UI.
                        # Если пользователь очистил его, это осознанное имя группы,
                        # а не повод вернуть старый глобальный шаблон.
                        if "filename_template" not in old:
                            filename_template = row_control["filename_template"].get()
                    target = OutputTarget(
                        format=fmt,
                        output_dir=directory.get().strip(),
                        enabled=bool(enabled.get()),
                        bitrate=bitrate,
                        sample_rate=sample_rate,
                        channels=channels,
                        profile=profile_id,
                        filename_template=filename_template,
                        chapter_title_template=(
                            row_control["chapter_title_template"].get()
                        ),
                        max_duration_seconds=max_duration,
                        max_chapters=max_chapters,
                        split_mode=old.get("split_mode", "none"),
                        scope=old.get("scope", "selected"),
                        assembly_mode=assembly_mode,
                        include_track_metadata=_config_bool(
                            row_control["include_track_metadata"].get(),
                            default=True,
                        ),
                    )
                else:
                    target = OutputTarget(
                        format=fmt,
                        output_dir=directory.get().strip(),
                        enabled=bool(enabled.get()),
                        bitrate=(
                            _selected_export_value(
                                profile_id,
                                profile_values,
                                old,
                                "output_bitrate" if source_context else "export_bitrate",
                                target_var_names["bitrate"],
                                "auto",
                                "bitrate",
                            )
                            if fmt != "wav" else "auto"
                        ),
                        sample_rate=_selected_export_value(
                            profile_id,
                            profile_values,
                            old,
                            "output_sample_rate" if source_context else "export_sample_rate",
                            target_var_names["sample_rate"],
                            "auto",
                            "sample_rate",
                        ),
                        channels=_selected_export_value(
                            profile_id,
                            profile_values,
                            old,
                            "output_channels" if source_context else "export_channels",
                            target_var_names["channels"],
                            "auto",
                            "channels",
                        ),
                        profile=profile_id,
                        apply_effects=_selected_export_value(
                            profile_id,
                            profile_values,
                            old,
                            "fx_enabled" if source_context else "export_apply_fx",
                            target_var_names["apply_effects"],
                            profile_effects_enabled if profile_id else source_context,
                            "apply_effects",
                        ),
                        effects={
                            "speed": _selected_export_value(
                                profile_id,
                                profile_values,
                                old_effects,
                                "fx_speed" if source_context else "export_fx_speed",
                                target_var_names["speed"],
                                1.0,
                                "speed",
                            ),
                            "pitch": _selected_export_value(
                                profile_id,
                                profile_values,
                                old_effects,
                                "fx_pitch" if source_context else "export_fx_pitch",
                                target_var_names["pitch"],
                                1.0,
                                "pitch",
                            ),
                            "echo": _selected_export_value(
                                profile_id,
                                profile_values,
                                old_effects,
                                "fx_echo" if source_context else "export_fx_echo",
                                target_var_names["echo"],
                                False,
                                "echo",
                            ),
                            "echo_delay": _selected_export_value(
                                profile_id,
                                profile_values,
                                old_effects,
                                "fx_echo_delay" if source_context else "export_fx_echo_delay",
                                target_var_names["echo_delay"],
                                300,
                                "echo_delay",
                            ),
                            "echo_decay": _selected_export_value(
                                profile_id,
                                profile_values,
                                old_effects,
                                "fx_echo_decay" if source_context else "export_fx_echo_decay",
                                target_var_names["echo_decay"],
                                0.3,
                                "echo_decay",
                            ),
                        },
                        filename_template=row_control["filename_template"].get(),
                        split_mode=old.get("split_mode", "none"),
                        max_duration_seconds=old.get("max_duration_seconds", 0),
                        max_chapters=old.get("max_chapters", 0),
                        scope=old.get("scope", "selected"),
                        assembly_mode=assembly_mode,
                        include_track_metadata=_config_bool(
                            row_control["include_track_metadata"].get(),
                            default=True,
                        ),
                    )
                try:
                    selected.append(normalize_output_target(target))
                except (TypeError, ValueError) as exc:
                    raise ValueError(f"{fmt.upper()}: {exc}") from exc
            if not any(item.get("enabled", True) for item in selected):
                raise ValueError("Выберите хотя бы один активный формат.")
            return selected

        def export_current_targets():
            try:
                snapshot = collect_targets()
                # Сохраняем переносимость пресетов с одной целью: профиль
                # должен отложить выбор каталога до общей папки экспорта
                # получателя, а не нести устаревший абсолютный путь с машины
                # отправителя.
                snapshot = list(normalize_output_target_directories(snapshot))
            except (TypeError, ValueError) as exc:
                self._show_error("Некорректная цель", str(exc), parent=dialog)
                return
            self._export_output_targets_profile(snapshot, parent=dialog)

        def import_into_dialog():
            try:
                imported = self._select_output_targets_profile(parent=dialog)
            except Exception as exc:
                self._show_error(
                    "Ошибка", f"Не удалось импортировать набор:\n{exc}", parent=dialog
                )
                return
            if not imported:
                return
            directory_sync_suspended["value"] = True
            try:
                _destroy_target_rows()
                for target in imported:
                    add_target_row(target, enabled_default=True)
                if not controls:
                    add_target_row({}, enabled_default=True)
            finally:
                directory_sync_suspended["value"] = False
            _sync_target_directory_controls()
            _sync_target_rows()

        def _capture_target_state():
            """Сохраняет только состояние целей для атомарного применения.

            ``save_settings`` читает несколько текущих элементов и может вернуть
            ``False`` после ошибки диска. Узкий снимок здесь не позволяет потерять
            несвязанные правки и одновременно даёт восстановить каждое поле,
            которое этому диалогу разрешено публиковать (включая прежний псевдоним
            источника).
            """
            config_state = {}
            for key in (target_config_key, SOURCE_OUTPUT_TARGETS_CONFIG_KEY):
                if key in self.config:
                    config_state[key] = (True, copy.deepcopy(self.config[key]))
                else:
                    config_state[key] = (False, None)
            return {
                "attr_present": hasattr(self, target_attr),
                "attr": copy.deepcopy(getattr(self, target_attr, None)),
                "config": config_state,
            }

        def _restore_target_state(snapshot):
            if snapshot.get("attr_present"):
                setattr(self, target_attr, copy.deepcopy(snapshot.get("attr")))
            else:
                try:
                    delattr(self, target_attr)
                except AttributeError:
                    pass
            for key, (present, value) in snapshot.get("config", {}).items():
                if present:
                    self.config[key] = copy.deepcopy(value)
                else:
                    self.config.pop(key, None)

        def apply_targets():
            try:
                selected = collect_targets()
                normalized_selected = list(
                    normalize_output_target_directories(selected)
                )
            except (TypeError, ValueError) as exc:
                self._show_error("Некорректная цель", str(exc), parent=dialog)
                return
            previous = _capture_target_state()
            try:
                setattr(self, target_attr, normalized_selected)
                self.config[target_config_key] = copy.deepcopy(normalized_selected)
                if source_context:
                    # Синхронизируем переходное имя для старых снимков настроек
                    # и фоновых потоков источника, которые ещё читают этот псевдоним.
                    self.config[SOURCE_OUTPUT_TARGETS_CONFIG_KEY] = copy.deepcopy(
                        normalized_selected
                    )
                if self.save_settings() is False:
                    raise OSError("настройки не удалось записать на диск")
            except Exception as exc:
                _restore_target_state(previous)
                self._show_error(
                    "Ошибка сохранения",
                    f"Изменения не применены:\n{exc}",
                    parent=dialog,
                )
                logging.exception("Не удалось применить набор выходов")
                return
            if source_context:
                self._schedule_source_session_save()
            result["saved"] = True
            if source_context:
                self._refresh_source_output_targets_summary()
            else:
                self._refresh_output_targets_summary()
            self._close_popup_safely(dialog)

        def use_legacy_source_target():
            """Возвращает синтез из папки к одному основному формату.

            Пустой список целей — это не ошибка, а явный совместимый режим:
            очередь снова использует ``output_format``/``output_dir``. Это
            отдельное действие вместо попытки применить окно с выключенными
            строками: сохранённые отключённые цели можно оставить в JSON,
            но пользователь должен иметь простой способ выйти из набора.
            Экспортная вкладка такой кнопки не получает, поскольку её пустой
            список уже означает прежний путь независимо от контекста.
            """
            if not source_context:
                return
            previous = _capture_target_state()
            try:
                setattr(self, target_attr, [])
                self.config[target_config_key] = []
                self.config[SOURCE_OUTPUT_TARGETS_CONFIG_KEY] = []
                if self.save_settings() is False:
                    raise OSError("настройки не удалось записать на диск")
            except Exception as exc:
                _restore_target_state(previous)
                self._show_error(
                    "Ошибка сохранения",
                    f"Изменения не применены:\n{exc}",
                    parent=dialog,
                )
                logging.exception("Не удалось вернуть основной формат")
                return
            self._schedule_source_session_save()
            result["saved"] = True
            self._refresh_source_output_targets_summary()
            self._close_popup_safely(dialog)

        ttk.Button(buttons, text="Применить", command=apply_targets).pack(side=tk.RIGHT)
        if source_context:
            ttk.Button(
                buttons,
                text="Основной формат",
                command=use_legacy_source_target,
            ).pack(side=tk.LEFT, padx=(6, 0))
        ttk.Button(
            buttons,
            text="Экспорт JSON…",
            command=export_current_targets,
        ).pack(side=tk.LEFT)
        ttk.Button(
            buttons,
            text="Импорт JSON…",
            command=import_into_dialog,
        ).pack(side=tk.LEFT, padx=(6, 0))
        ttk.Button(buttons, text="Отмена", command=lambda: self._close_popup_safely(dialog)).pack(
            side=tk.RIGHT, padx=(0, 6)
        )
        def resize_output_targets_text(event=None):
            """Подгоняет переносы по ширине, не создавая лишнюю строку."""
            try:
                width = int(getattr(event, "width", 0) or dialog.winfo_width())
                if width > 1:
                    wrap = max(480, width - 28)
                    target_help.configure(wraplength=wrap)
            except (AttributeError, RuntimeError, tk.TclError, TypeError, ValueError):
                pass

        dialog.bind("<Configure>", resize_output_targets_text, add="+")
        dialog.protocol("WM_DELETE_WINDOW", lambda: self._close_popup_safely(dialog))
        dialog.bind("<Escape>", lambda _event: self._close_popup_safely(dialog))
        # Начальная геометрия вмещает строки целей и ограничивается экраном.
        try:
            screen_w = max(360, int(dialog.winfo_screenwidth()) - 40)
            screen_h = max(240, int(dialog.winfo_screenheight()) - 80)
            dialog.minsize(min(760, screen_w), min(500, screen_h))
        except (AttributeError, tk.TclError):
            pass
        self._center_popup(dialog, 1020, 640, fit_screen=True)

    def _choose_output_target_dir(self, variable, parent=None):
        options = {"initialdir": self._get_smart_dir(variable.get())}
        if parent is not None:
            options["parent"] = parent
        selected = filedialog.askdirectory(**options)
        if selected:
            variable.set(selected)

    def _export_output_targets_profile(self, targets, parent=None):
        message_options = {"parent": parent} if parent is not None else {}
        try:
            data = output_target_library_from_targets(targets)
        except (TypeError, ValueError) as exc:
            self._show_error("Пустой набор", str(exc), **message_options)
            return
        options = {
            "initialdir": resolve_dialog_initial_dir(
                self.config.get("last_config_dir", ""), BASE_DIR
            ),
            "defaultextension": ".json",
            "filetypes": [("JSON files", "*.json")],
            "initialfile": "output_targets.json",
        }
        if parent is not None:
            options["parent"] = parent
        filepath = filedialog.asksaveasfilename(**options)
        if not filepath:
            return
        try:
            self._write_json_atomic(filepath, data)
            self._remember_dialog_directory("last_config_dir", filepath)
            self._show_info(
                "Успех",
                f"Набор выходов экспортирован в:\n{filepath}",
                **message_options,
            )
        except Exception as exc:
            self._show_error(
                "Ошибка",
                f"Не удалось экспортировать набор:\n{exc}",
                **message_options,
            )

    def export_output_targets_profile(self):
        """Экспортирует сохранённый набор (совместимость с внешними вызовами)."""
        self._export_output_targets_profile(getattr(self, "export_targets", ()))

    def _select_output_targets_profile(self, parent=None):
        options = {
            "initialdir": resolve_dialog_initial_dir(
                self.config.get("last_config_dir", ""), BASE_DIR
            ),
            "filetypes": [("JSON files", "*.json")],
        }
        if parent is not None:
            options["parent"] = parent
        filepath = filedialog.askopenfilename(**options)
        if not filepath:
            return None
        with open(filepath, "r", encoding="utf-8-sig") as file:
            data = normalize_output_target_library(json.load(file))
        self._remember_dialog_directory("last_config_dir", filepath)
        return data["targets"]

    def import_output_targets_profile(self):
        """Импортирует набор и применяет его атомарно через старый API."""
        # ``save_settings`` сначала синхронизирует все текущие поля Tk, а затем
        # может завершиться ошибкой (например, если родительский каталог
        # настроек больше недоступен для записи). Сохраняем снимок до импорта,
        # пока этот барьер записи не пройден. Иначе неудачный импорт оставил бы
        # новые поля целей в памяти, тогда как старый файл настроек остался на
        # диске, и последующий экспорт неожиданно использовал бы несохранённые цели.
        had_config = hasattr(self, "config")
        config_ref = getattr(self, "config", None)
        previous_config = copy.deepcopy(config_ref)
        had_export_targets = hasattr(self, "export_targets")
        previous_export_targets = copy.deepcopy(
            getattr(self, "export_targets", None)
        )
        try:
            targets = self._select_output_targets_profile()
            if not targets:
                return
            targets = list(normalize_output_target_directories(targets))
            self.export_targets = copy.deepcopy(targets)
            self.config["export_targets"] = copy.deepcopy(targets)
            if self.save_settings() is False:
                raise OSError("настройки не удалось записать на диск")
            self._refresh_output_targets_summary()
            self._show_info("Успех", "Набор выходов импортирован.")
        except Exception as exc:
            # Восстанавливаем и атрибут целей, и полный снимок конфигурации.
            # ``save_settings`` может обновить несвязанные ключи при
            # синхронизации переменных интерфейса, поэтому восстановление только
            # ``export_targets`` оставило бы в памяти частично применённый импорт.
            # По возможности сохраняем исходную идентичность словаря: виджеты и
            # интеграции могут хранить ссылку на ``self.config``.
            if isinstance(config_ref, dict):
                try:
                    config_ref.clear()
                    config_ref.update(copy.deepcopy(previous_config or {}))
                    self.config = config_ref
                except Exception:
                    self.config = copy.deepcopy(previous_config)
            elif had_config:
                self.config = copy.deepcopy(previous_config)
            else:
                try:
                    del self.config
                except AttributeError:
                    pass
            if had_export_targets:
                self.export_targets = copy.deepcopy(previous_export_targets)
            else:
                try:
                    del self.export_targets
                except AttributeError:
                    pass
            logging.exception("Не удалось импортировать набор выходных форматов")
            self._show_error("Ошибка", f"Не удалось импортировать набор:\n{exc}")

    def _compact_export_settings_text(self):
        """Возвращает короткое описание параметров, видимое в основной вкладке."""
        def value(attr, fallback=""):
            variable = getattr(self, attr, None)
            if variable is None:
                return fallback
            try:
                raw = variable.get()
            except (AttributeError, tk.TclError, TypeError, ValueError):
                return fallback
            return str(raw).strip() or fallback

        fmt = value("export_fmt_var", "mp3").lower()
        bitrate = value("export_bitrate_var", "auto").lower()
        sample_rate = value("export_sample_rate_var", "auto").lower()
        channels = value("export_channels_var", "auto").lower()
        is_m4b = fmt == "m4b"
        if is_m4b:
            # Компактный M4B сохраняется для старых проектов и прямых вызовов,
            # хотя новые пользователи обычно настраивают его как цель вывода.
            # Его битрейт AAC не зависит от общего битрейта экспорта.
            bitrate = value("export_m4b_bitrate_var", "64k").lower()
            bitrate_text = f"AAC {bitrate}"
        elif fmt == "wav":
            bitrate_text = "без потерь"
        else:
            bitrate_text = bitrate
        rate_text = "авто" if sample_rate == "auto" else f"{sample_rate} Гц"
        channels_text = {
            "auto": "авто каналы",
            "mono": "mono",
            "stereo": "stereo",
        }.get(channels, channels)
        # ``export_apply_fx_var`` — основная переменная Tk. Старое имя без
        # суффикса ``_var`` молча возвращало ``False``, из-за чего компактная
        # сводка сообщала об отключённых эффектах даже после их включения
        # пользователем во всплывающем окне.
        effects = (
            "не применяются"
            if is_m4b
            else ("вкл." if _config_bool(value("export_apply_fx_var", False)) else "выкл.")
        )
        directory = middle_ellipsize(value("export_outdir_var", "папка не выбрана"), 36)
        if is_m4b:
            profile_prefix = "Разовые параметры M4B"
        else:
            try:
                profile = self._audio_profile_from_current_ui(
                    "export", "Текущие параметры"
                )
                matching_name = matching_audio_profile_name(
                    profile, self.config.get("audio_profiles", [])
                )
                profile_prefix = (
                    f"Профиль «{matching_name}»"
                    if matching_name
                    else "Разовые параметры"
                )
            except (AttributeError, KeyError, tk.TclError, TypeError, ValueError):
                profile_prefix = "Разовые параметры"
        text = (
            f"{profile_prefix}: {fmt.upper()} {bitrate_text} · "
            f"{rate_text} · {channels_text} · "
            f"эффекты {effects} · общая папка: {directory}"
        )
        if is_m4b:
            template = value("export_m4b_template_var", DEFAULT_EXPORT_M4B_TEMPLATE)
            hours = value("export_m4b_hours_var", "0")
            chapters = value("export_m4b_chapters_var", "0")
            template_display = middle_ellipsize(template or "{book}", 24)
            text += (
                f" · шаблон: {template_display}"
                f" · лимит: {hours} ч / {chapters} глав"
            )
        return text

    def open_export_settings_dialog(self):
        """Открывает компактный транзакционный редактор параметров сборки.

        Основная вкладка намеренно сохраняет основные переменные Tk для фоновых
        потоков и менеджеров профилей, поддерживающих обратную совместимость.
        Этот диалог редактирует независимые подготовленные переменные; только
        «Применить» копирует проверенный снимок обратно и сохраняет его. Поэтому
        закрытие/«Отмена» не оставляет частично введённые значения в следующем
        экспорте.
        """
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return

        def current(attr, fallback=""):
            variable = getattr(self, attr, None)
            if variable is None:
                return fallback
            try:
                return variable.get()
            except (AttributeError, tk.TclError, TypeError, ValueError):
                return fallback

        dialog = tk.Toplevel(self.root)
        dialog.withdraw()
        dialog.title("Продвинутые параметры сборки")
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.resizable(True, True)

        export_settings_hint_shell, _export_settings_hint_body, _export_settings_hint_toggle = (
            self._make_collapsible_hint(
                dialog,
                (
                    "Настройки применяются только после кнопки «Применить». "
                    "Общая папка задаётся прямо на вкладке «Экспорт и сборка»; "
                    "профили и набор выходов открываются отдельными менеджерами."
                ),
                title="Как работают параметры",
                wraplength=650,
                initially_open=False,
            )
        )
        export_settings_hint_shell.pack(fill=tk.X, padx=14, pady=(10, 6))

        # Прокручиваемая область делает окно удобным на маленьком экране и не
        # возвращает горизонтальную белую полосу на основную вкладку.
        body_shell = ttk.Frame(dialog)
        body_shell.pack(fill=tk.BOTH, expand=True, padx=14)
        body_canvas = tk.Canvas(
            body_shell,
            highlightthickness=0,
            bd=0,
            background=ttk.Style(dialog).lookup("TFrame", "background")
            or dialog.cget("background"),
        )
        body_scroll = ttk.Scrollbar(
            body_shell, orient=tk.VERTICAL, command=body_canvas.yview
        )
        body = ttk.Frame(body_canvas, padding=(2, 0, 2, 6))
        body_window = body_canvas.create_window((0, 0), window=body, anchor="nw")
        body_canvas.configure(yscrollcommand=body_scroll.set)
        body_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        body_scroll.pack(side=tk.RIGHT, fill=tk.Y)

        def sync_body(_event=None):
            try:
                body_canvas.configure(scrollregion=body_canvas.bbox("all"))
                width = body_canvas.winfo_width()
                if width > 1:
                    body_canvas.itemconfigure(body_window, width=width)
            except tk.TclError:
                pass

        body.bind("<Configure>", sync_body, add="+")
        body_canvas.bind("<Configure>", sync_body, add="+")

        def wheel(event):
            try:
                delta = getattr(event, "delta", 0)
                if delta:
                    body_canvas.yview_scroll(
                        -int(delta / 120 or (-1 if delta < 0 else 1)), "units"
                    )
                elif getattr(event, "num", None) == 4:
                    body_canvas.yview_scroll(-3, "units")
                elif getattr(event, "num", None) == 5:
                    body_canvas.yview_scroll(3, "units")
            except (AttributeError, tk.TclError, TypeError, ValueError):
                pass

        for widget in (body_canvas, body):
            widget.bind("<MouseWheel>", wheel, add="+")
            widget.bind("<Button-4>", wheel, add="+")
            widget.bind("<Button-5>", wheel, add="+")

        def numeric_current(attr, fallback, converter=float):
            """Читает частично отредактированное значение Tk, не прерывая создание окна."""
            raw = current(attr, fallback)
            try:
                value = converter(raw)
                if isinstance(value, float) and not math.isfinite(value):
                    raise ValueError
                return value
            except (TypeError, ValueError, OverflowError):
                return converter(fallback)

        staged = {
            "format": tk.StringVar(value=str(current("export_fmt_var", "mp3")).lower()),
            "bitrate": tk.StringVar(value=str(current("export_bitrate_var", "auto")).lower()),
            "sample_rate": tk.StringVar(value=str(current("export_sample_rate_var", "auto")).lower()),
            "channels": tk.StringVar(value=str(current("export_channels_var", "auto")).lower()),
            "apply_fx": tk.BooleanVar(value=_config_bool(current("export_apply_fx_var", False))),
            "speed": tk.DoubleVar(value=numeric_current("exp_speed_var", 1.0)),
            "pitch": tk.DoubleVar(value=numeric_current("exp_pitch_var", 1.0)),
            "echo": tk.BooleanVar(value=_config_bool(current("exp_echo_var", False))),
            "delay": tk.DoubleVar(value=numeric_current("exp_delay_var", 300)),
            "decay": tk.DoubleVar(value=numeric_current("exp_decay_var", 0.3)),
            "m4b_template": tk.StringVar(value=str(current("export_m4b_template_var", "") or "")),
            "m4b_hours": tk.StringVar(value=str(current("export_m4b_hours_var", DEFAULT_M4B_MAX_DURATION_HOURS) or "")),
            "m4b_chapters": tk.StringVar(value=str(current("export_m4b_chapters_var", 0) or "0")),
            "m4b_bitrate": tk.StringVar(value=str(current("export_m4b_bitrate_var", "64k") or "64k").lower()),
        }

        # Два столбца оставляют подписи читаемыми в узком окне.
        body.columnconfigure(0, weight=0)
        body.columnconfigure(1, weight=1)
        body_row = 0

        def make_section(title):
            nonlocal body_row
            frame = ttk.LabelFrame(body, text=title, padding=(8, 6))
            frame.grid(
                row=body_row,
                column=0,
                columnspan=2,
                sticky=tk.EW,
                pady=(5, 4),
            )
            frame.columnconfigure(1, weight=1)
            body_row += 1
            return frame

        def add_combo(parent, row_index, label, key, values, width=14):
            ttk.Label(parent, text=label, anchor=tk.W).grid(
                row=row_index,
                column=0,
                sticky=tk.W,
                padx=(0, 12),
                pady=3,
            )
            widget = ttk.Combobox(
                parent,
                textvariable=staged[key],
                values=list(values),
                state="readonly",
                width=width,
            )
            widget.grid(
                row=row_index,
                column=1,
                sticky=tk.EW,
                padx=(0, 2),
                pady=3,
            )
            return widget

        def add_entry(parent, row_index, label, key, width=28):
            ttk.Label(parent, text=label, anchor=tk.W).grid(
                row=row_index,
                column=0,
                sticky=tk.W,
                padx=(0, 12),
                pady=3,
            )
            widget = ttk.Entry(parent, textvariable=staged[key], width=width)
            widget.grid(
                row=row_index,
                column=1,
                sticky=tk.EW,
                padx=(0, 2),
                pady=3,
            )
            return widget

        # Общий каталог экспорта относится к основной вкладке «Экспорт и
        # сборка», где он виден непосредственно перед запуском. Намеренно не
        # дублируем его в этом расширенном редакторе.
        output_section = make_section("Формат и параметры вывода")
        format_combo = add_combo(
            output_section,
            0,
            "Формат:",
            "format",
            ("mp3", "wav", "ogg", "opus", "m4a", "m4b"),
            width=12,
        )
        bitrate_widget = add_combo(
            output_section,
            1,
            "Битрейт:",
            "bitrate",
            ("auto", "32k", "48k", "64k", "96k", "128k", "192k", "256k", "320k"),
            width=12,
        )
        add_combo(
            output_section,
            2,
            "Частота дискретизации:",
            "sample_rate",
            AUDIO_PROFILE_SAMPLE_RATES,
            width=14,
        )
        add_combo(
            output_section,
            3,
            "Каналы:",
            "channels",
            AUDIO_PROFILE_CHANNELS,
            width=14,
        )

        effects_section = make_section("Эффекты постобработки")
        effect_widgets = []
        effect_toggle = ttk.Checkbutton(
            effects_section,
            text="Наложить эффекты",
            variable=staged["apply_fx"],
        )
        effect_toggle.grid(
            row=0,
            column=0,
            columnspan=2,
            sticky=tk.W,
            pady=(0, 4),
        )
        effect_widgets.append(effect_toggle)

        def add_scale(parent, row_index, label, key, from_, to, formatter):
            ttk.Label(parent, text=label, anchor=tk.W).grid(
                row=row_index,
                column=0,
                sticky=tk.W,
                padx=(0, 12),
                pady=3,
            )
            control = ttk.Frame(parent)
            control.grid(
                row=row_index,
                column=1,
                sticky=tk.EW,
                padx=(0, 2),
                pady=3,
            )
            control.columnconfigure(0, weight=1)
            value_label = ttk.Label(
                control,
                text=formatter(staged[key].get()),
                width=9,
                anchor=tk.E,
            )
            value_label.grid(row=0, column=1, sticky=tk.E, padx=(10, 0))
            scale = ttk.Scale(
                control,
                from_=from_,
                to=to,
                variable=staged[key],
                command=lambda value, target=value_label, fn=formatter: target.configure(
                    text=fn(float(value))
                ),
            )
            scale.grid(row=0, column=0, sticky=tk.EW)
            effect_widgets.append(scale)
            return scale

        add_scale(
            effects_section,
            1,
            "Скорость:",
            "speed",
            0.5,
            3.0,
            lambda value: f"{float(value):.1f}x",
        )
        add_scale(
            effects_section,
            2,
            "Тон:",
            "pitch",
            0.5,
            2.0,
            lambda value: f"{float(value):.2f}",
        )
        echo_toggle = ttk.Checkbutton(
            effects_section,
            text="Эхо",
            variable=staged["echo"],
        )
        echo_toggle.grid(row=3, column=0, columnspan=2, sticky=tk.W, pady=3)
        effect_widgets.append(echo_toggle)
        add_scale(
            effects_section,
            4,
            "Задержка:",
            "delay",
            50,
            1000,
            lambda value: f"{int(float(value))} мс",
        )
        add_scale(
            effects_section,
            5,
            "Сила:",
            "decay",
            0.1,
            0.8,
            lambda value: f"{float(value):.1f}",
        )

        m4b_section = make_section("M4B (AAC-LC, главы)")
        m4b_control_widgets = []
        m4b_template_entry = add_entry(
            m4b_section,
            0,
            "Шаблон имени:",
            "m4b_template",
            width=32,
        )
        m4b_control_widgets.append(m4b_template_entry)
        m4b_template_helper_button = ttk.Button(
            m4b_section,
            text="Помощник…",
            command=lambda: self._open_template_helper(
                staged["m4b_template"],
                "m4b_part",
                owner=dialog,
                target_entry=m4b_template_entry,
                title="Помощник имени M4B",
                preview_data=self._template_helper_export_preview_data(),
            ),
        )
        m4b_template_helper_button.grid(
            row=0,
            column=2,
            sticky=tk.W,
            padx=(6, 0),
            pady=3,
        )
        m4b_control_widgets.append(m4b_template_helper_button)
        m4b_control_widgets.append(
            add_entry(m4b_section, 1, "Лимит часов (0 = авто):", "m4b_hours", width=12)
        )
        m4b_control_widgets.append(
            add_entry(
                m4b_section,
                2,
                "Макс. глав (0 = без лимита):",
                "m4b_chapters",
                width=12,
            )
        )
        m4b_bitrate_widget = add_combo(
            m4b_section,
            3,
            "AAC-битрейт:",
            "m4b_bitrate",
            ("32k", "48k", "64k", "96k", "128k", "192k", "256k"),
            width=12,
        )
        m4b_control_widgets.append(m4b_bitrate_widget)
        export_template_hint_shell, _export_template_hint_body, _export_template_hint_toggle = (
            self._make_collapsible_hint(
                m4b_section,
                (
                    "Поля шаблона: {book}, {name}/{group}/{title}, {range}, "
                    "{part}, {parts}, {first_index}, {last_index}. Пусто — "
                    "имя книги; при нескольких частях добавляется «Часть N»."
                ),
                title="Поля шаблона",
                wraplength=620,
                initially_open=False,
            )
        )
        export_template_hint_shell.grid(
            row=4,
            column=0,
            columnspan=3,
            sticky=tk.EW,
            pady=(5, 0),
        )

        def refresh_staged_state(*_args):
            is_wav = staged["format"].get().lower() == "wav"
            is_m4b = staged["format"].get().lower() == "m4b"
            bitrate_widget.configure(
                state=tk.DISABLED if (is_wav or is_m4b) else "readonly"
            )
            effects_allowed = not is_m4b
            for widget in effect_widgets:
                try:
                    widget.configure(
                        state=tk.NORMAL if effects_allowed else tk.DISABLED
                    )
                except (AttributeError, tk.TclError, TypeError):
                    pass
            try:
                effect_toggle.configure(
                    text=(
                        "Наложить эффекты"
                        if effects_allowed
                        else "Наложить эффекты (для M4B недоступно)"
                    )
                )
            except (AttributeError, tk.TclError, TypeError):
                pass
            if is_m4b:
                # Сохраняем подготовленные значения ``speed``/``pitch``/``echo`` на случай, если
                # пользователь вернётся к другому формату, но никогда не фиксируем
                # флаг эффектов для цели M4B.
                try:
                    staged["apply_fx"].set(False)
                except (AttributeError, tk.TclError, TypeError, ValueError):
                    pass
            # Явные ссылки нужны: поля M4B вложены в прокручиваемый раздел.
            for widget in m4b_control_widgets:
                try:
                    if widget is m4b_bitrate_widget:
                        widget.configure(
                            state="readonly" if is_m4b else tk.DISABLED
                        )
                    else:
                        widget.configure(
                            state=tk.NORMAL if is_m4b else tk.DISABLED
                        )
                except (AttributeError, tk.TclError, TypeError):
                    pass

        staged["format"].trace_add("write", refresh_staged_state)

        footer = ttk.Frame(dialog)
        footer.pack(fill=tk.X, padx=14, pady=(7, 12))
        status = ttk.Label(footer, text="", foreground=self.get_status_color("error"))
        status.pack(side=tk.LEFT, fill=tk.X, expand=True)

        def close_dialog():
            self._close_popup_safely(dialog)

        def apply_changes():
            try:
                fmt = str(staged["format"].get()).strip().lower()
                bitrate = str(staged["bitrate"].get()).strip().lower()
                sample_rate = str(staged["sample_rate"].get()).strip().lower()
                channels = str(staged["channels"].get()).strip().lower()
                if fmt not in {"mp3", "wav", "ogg", "opus", "m4a", "m4b"}:
                    raise ValueError("неподдерживаемый формат")
                if bitrate != "auto" and not re.fullmatch(r"[1-9]\d*k", bitrate):
                    raise ValueError("некорректный битрейт")
                if sample_rate not in AUDIO_PROFILE_SAMPLE_RATES:
                    raise ValueError("некорректная частота дискретизации")
                if channels not in AUDIO_PROFILE_CHANNELS:
                    raise ValueError("некорректное число каналов")
                speed = float(staged["speed"].get())
                pitch = float(staged["pitch"].get())
                delay = int(float(staged["delay"].get()))
                decay = float(staged["decay"].get())
                if not all(math.isfinite(value) for value in (speed, pitch, decay)):
                    raise ValueError("числовые параметры эффектов должны быть конечными")
                if speed < 0.5 or speed > 3.0 or pitch < 0.5 or pitch > 2.0:
                    raise ValueError("скорость и тон вне допустимого диапазона")
                if delay < 50 or delay > 1000 or decay < 0.1 or decay > 0.8:
                    raise ValueError("параметры эхо вне допустимого диапазона")
                hours = float(str(staged["m4b_hours"].get()).strip() or 0)
                chapters = int(float(str(staged["m4b_chapters"].get()).strip() or 0))
                m4b_bitrate = str(staged["m4b_bitrate"].get()).strip().lower()
                if not math.isfinite(hours) or hours < 0 or chapters < 0:
                    raise ValueError("лимиты M4B должны быть неотрицательными")
                if not re.fullmatch(r"[1-9]\d*k", m4b_bitrate):
                    raise ValueError("некорректный AAC-битрейт M4B")
                m4b_kbps = int(m4b_bitrate[:-1])
                if not 16 <= m4b_kbps <= 512:
                    raise ValueError("AAC-битрейт M4B должен быть от 16 до 512 кбит/с")
                template = str(staged["m4b_template"].get() or "").strip()
                validate_filename_template(template, TEMPLATE_FIELDS_OUTPUT)
            except (TypeError, ValueError, OverflowError, TemplateError) as exc:
                status.configure(text=str(exc))
                return

            attrs = {
                "export_fmt_var": fmt,
                "export_bitrate_var": bitrate,
                "export_sample_rate_var": sample_rate,
                "export_channels_var": channels,
                "export_apply_fx_var": (
                    False
                    if fmt == "m4b"
                    else bool(staged["apply_fx"].get())
                ),
                "exp_speed_var": speed,
                "exp_pitch_var": pitch,
                "exp_echo_var": bool(staged["echo"].get()),
                "exp_delay_var": delay,
                "exp_decay_var": decay,
                "export_m4b_template_var": template,
                "export_m4b_hours_var": hours,
                "export_m4b_chapters_var": chapters,
                "export_m4b_bitrate_var": m4b_bitrate,
            }
            old_values = {}
            old_config = copy.deepcopy(self.config)
            try:
                for attr, new_value in attrs.items():
                    variable = getattr(self, attr)
                    old_values[attr] = variable.get()
                    variable.set(new_value)
                if self.save_settings() is False:
                    raise OSError("настройки не удалось записать на диск")
            except Exception as exc:
                self.config = old_config
                for attr, old_value in old_values.items():
                    try:
                        getattr(self, attr).set(old_value)
                    except (AttributeError, tk.TclError):
                        pass
                status.configure(text=f"Не удалось применить: {exc}")
                logging.exception("Не удалось применить параметры сборки")
                return

            self._sync_export_mode_controls()
            self._refresh_audio_profile_summaries()
            self._close_popup_safely(dialog)

        ttk.Button(footer, text="Отмена", command=close_dialog).pack(side=tk.RIGHT, padx=(6, 0))
        ttk.Button(footer, text="Применить", command=apply_changes).pack(side=tk.RIGHT)
        dialog.protocol("WM_DELETE_WINDOW", close_dialog)
        dialog.bind("<Escape>", lambda _event: close_dialog())
        refresh_staged_state()
        self._center_popup(dialog, 660, 640, fit_screen=True)

    # --- Логика интерфейса Сборщика ---
    def _sync_export_mode_controls(self):
        """Восстанавливает специальные состояния полей режима экспорта."""
        if getattr(self, "_export_running", False):
            return
        tags_only = bool(self.export_tags_only_var.get())
        normal_state = tk.DISABLED if tags_only else tk.NORMAL
        combo_state = tk.DISABLED if tags_only else "readonly"
        self.btn_export_dir.configure(state=normal_state)
        self.ent_export_dir.configure(state=normal_state)
        self.cb_export_fmt.configure(state=combo_state)
        fmt = str(self.export_fmt_var.get()).strip().lower()
        bitrate_state = (
            tk.DISABLED
            if tags_only or fmt in {"wav", "m4b"}
            else "readonly"
        )
        self.cb_export_bitrate.configure(state=bitrate_state)
        self.cb_export_sample_rate.configure(state=combo_state)
        self.cb_export_channels.configure(state=combo_state)
        # Временные метки глав M4B основаны на неизменённой временной шкале
        # исходника. Отключаем компактные элементы эффектов сразу после выбора
        # M4B, чтобы пользователь увидел ограничение в редакторе, а не узнал о
        # нём после начала долгого кодирования. Низкоуровневые экспортёры
        # повторяют эту защиту для старых и интеграционных вызовов.
        effects_state = (
            tk.DISABLED
            if tags_only or fmt == "m4b"
            else tk.NORMAL
        )
        if fmt == "m4b" and hasattr(self, "export_apply_fx_var"):
            try:
                self.export_apply_fx_var.set(False)
            except (AttributeError, tk.TclError, TypeError, ValueError):
                pass
        self.chk_export_fx.configure(state=effects_state)
        if hasattr(self, "export_m4b_controls"):
            self._set_descendant_state(self.export_m4b_controls, normal_state)
        if hasattr(self, "btn_output_targets"):
            self.btn_output_targets.configure(state=normal_state)
        if hasattr(self, "btn_export_settings"):
            self.btn_export_settings.configure(state=normal_state)
        for control in getattr(self, "export_fx_value_controls", ()):
            control.configure(state=effects_state)
        audio_profiles_button = getattr(self, "btn_audio_profiles_export", None)
        if audio_profiles_button is not None:
            audio_profiles_button.configure(state=normal_state)
        self.btn_export_start.configure(state=tk.NORMAL)
        self.btn_export_stop.configure(state=tk.DISABLED)
        self.chk_export_tags_only.configure(state=tk.NORMAL)
        if hasattr(self, "chk_export_parallel"):
            self.chk_export_parallel.configure(state=normal_state)

    def _refresh_export_tree_action_states(self):
        """Согласует действия над деревом с содержимым и выделением.

        Общая блокировка импорта/сборки имеет приоритет. В обычном состоянии
        кнопки не должны выглядеть доступными, если соответствующей операции
        нечего делать: удаление и объединение требуют выделения,
        разгруппировка — выбранной группы, перемещение — соседней позиции, а
        авторазбивка — хотя бы одного аудиофайла.
        """
        tree = getattr(self, "export_tree", None)
        if tree is None:
            return

        blocked = bool(
            getattr(self, "_export_running", False)
            or getattr(self, "_export_lock", False)
        )
        try:
            roots = tuple(tree.get_children(""))
            selected = tuple(tree.selection()) if not blocked else ()
            selected = tuple(item for item in selected if tree.exists(item))
        except (AttributeError, tk.TclError, TypeError):
            roots = ()
            selected = ()

        has_project_items = bool(
            roots
            or getattr(self, "export_groups", {})
            or getattr(self, "export_files", {})
        )
        try:
            has_audio_files = any(
                tree.exists(file_id)
                for file_id in getattr(self, "export_files", {})
            )
        except (AttributeError, tk.TclError, TypeError):
            has_audio_files = False

        selected_groups = tuple(
            item for item in selected
            if item in getattr(self, "export_groups", {})
        )

        def can_move(direction):
            for item in selected:
                try:
                    parent = tree.parent(item)
                    siblings = tuple(tree.get_children(parent))
                    index = siblings.index(item)
                except (AttributeError, tk.TclError, TypeError, ValueError):
                    continue
                if direction < 0 and index > 0:
                    return True
                if direction > 0 and index < len(siblings) - 1:
                    return True
            return False

        action_states = (
            ("btn_export_remove", bool(selected)),
            ("btn_export_group_selected", bool(selected)),
            ("btn_export_ungroup", bool(selected_groups)),
            ("btn_export_up", can_move(-1)),
            ("btn_export_down", can_move(1)),
            ("btn_export_auto_split", has_audio_files),
            ("btn_export_clear", has_project_items),
        )
        for attr, enabled in action_states:
            widget = getattr(self, attr, None)
            if widget is None:
                continue
            try:
                widget.configure(
                    state=(
                        tk.NORMAL
                        if enabled and not blocked
                        else tk.DISABLED
                    )
                )
            except (AttributeError, tk.TclError, TypeError):
                pass

        empty_label = getattr(self, "lbl_export_empty", None)
        if empty_label is not None:
            try:
                if roots:
                    empty_label.place_forget()
                else:
                    empty_label.place(
                        relx=0.5,
                        rely=0.5,
                        anchor=tk.CENTER,
                    )
                    empty_label.lift()
            except (AttributeError, tk.TclError, TypeError):
                pass

    def _sync_group_subfolder_state(self):
        """Блокирует подпапку для склеенной группы и поясняет причину."""
        if not hasattr(self, "chk_subfolder"):
            return
        item = getattr(self, "current_selected_export_item", None)
        editable_group = bool(item and item in self.export_groups)
        enabled = (
            editable_group
            and not bool(self.grp_merge_var.get())
            and not getattr(self, "_export_running", False)
            and not getattr(self, "_export_lock", False)
        )
        self.chk_subfolder.configure(state=tk.NORMAL if enabled else tk.DISABLED)
        if hasattr(self, "lbl_subfolder_hint"):
            if not editable_group:
                hint = "Настройка доступна только для группы."
            elif bool(self.grp_merge_var.get()):
                hint = "Недоступно: файлы группы склеиваются в один трек."
            else:
                hint = "Отдельные файлы будут сохранены в папку с именем группы."
            self.lbl_subfolder_hint.configure(text=hint)

    def _disable_export_settings(self):
        for tab in (
            self.grp_tab_basic,
            self.grp_tab_tags,
            self.grp_tab_mass,
        ):
            self._set_descendant_state(tab, tk.DISABLED)

        try:
            self.ent_pause.configure(state=tk.DISABLED)
            self.btn_mass_apply_basic.configure(state=tk.DISABLED)
            self.btn_apply_to_group_files.configure(state=tk.DISABLED)
            self.btn_apply_to_parent.configure(state=tk.DISABLED)
            self.btn_apply_to_selected.configure(state=tk.DISABLED)
            self.btn_apply_to_all.configure(state=tk.DISABLED)
        except (AttributeError, tk.TclError):
            pass

    def _enable_export_settings(self, item):
        is_group = item in self.export_groups
        parent = self.export_tree.parent(item)
        is_group_file = (not is_group) and bool(parent)  # Файл внутри группы

        for tab in (
            self.grp_tab_basic,
            self.grp_tab_tags,
            self.grp_tab_mass,
        ):
            self._set_descendant_state(tab, tk.NORMAL)

        try:
            self.ent_pause.configure(state=tk.NORMAL)
            self.btn_apply_to_selected.configure(state=tk.NORMAL)
            self.btn_apply_to_all.configure(state=tk.NORMAL)
        except (AttributeError, tk.TclError):
            pass

        if not is_group:
            self.chk_merge.configure(state=tk.DISABLED)
            self.chk_subfolder.configure(state=tk.DISABLED)
            self.ent_pause.configure(state=tk.DISABLED)
            # Массовое применение доступно только для групп.
            self.btn_mass_apply_basic.configure(state=tk.DISABLED)
            self.lbl_grp_name.config(text="Название трека (Title):")
            self.group_settings_frame.config(text="Настройки файла")

            self.btn_apply_to_group_files.configure(state=tk.DISABLED)
            if is_group_file:
                self.btn_apply_to_parent.configure(state=tk.NORMAL)
            else:
                self.btn_apply_to_parent.configure(state=tk.DISABLED)  # Файл в корне
        else:
            self.btn_mass_apply_basic.configure(state=tk.NORMAL)
            self.lbl_grp_name.config(text="Имя группы (имя файла/папки):")
            self.group_settings_frame.config(text="Настройки группы")

            self.btn_apply_to_group_files.configure(state=tk.NORMAL)
            self.btn_apply_to_parent.configure(state=tk.DISABLED)
        self._sync_group_subfolder_state()

    def on_export_tree_select(self, event):
        self._refresh_export_tree_action_states()
        if (
            getattr(self, "_export_lock", False)
            or getattr(self, "_export_running", False)
        ):
            return
        selected = self.export_tree.selection()
        if not selected:
            self.current_selected_export_item = None
            self._disable_export_settings()
            return

        item = selected[0]
        is_group = item in self.export_groups
        settings = self.export_groups.get(item) if is_group else self.export_files.get(item)
        if settings is None:
            self.current_selected_export_item = None
            self._disable_export_settings()
            return

        self._is_updating_ui = True
        try:
            self.current_selected_export_item = item

            # Передаём сам ``item``, чтобы функция различила файл, группу и корень.
            self._enable_export_settings(item)

            self.grp_name_var.set(settings.get("name" if is_group else "title", ""))
            self.grp_artist_var.set(settings.get("artist", ""))
            self.grp_album_var.set(settings.get("album", ""))
            self.grp_album_artist_var.set(settings.get("album_artist", ""))
            self.grp_genre_var.set(settings.get("genre", ""))
            self.grp_composer_var.set(settings.get("composer", ""))
            self.grp_year_var.set(settings.get("year", ""))
            self.grp_cover_var.set(settings.get("cover", ""))

            if is_group:
                self.grp_merge_var.set(settings.get("merge", True))
                self.grp_subfolder_var.set(settings.get("subfolder", True))
                self.grp_pause_var.set(settings.get("pause", 1000))
        finally:
            self._is_updating_ui = False
        self._sync_group_subfolder_state()

    def save_export_item_settings(self, *args):
        if (
            getattr(self, '_is_updating_ui', False)
            or getattr(self, '_export_running', False)
            or getattr(self, '_export_lock', False)
        ):
            return
        item = self.current_selected_export_item
        if not item or not self.export_tree.exists(item): return

        is_group = item in self.export_groups
        target_dict = self.export_groups if is_group else self.export_files

        if is_group:
            previous_name = str(target_dict[item].get("name") or "")
            current_name = str(self.grp_name_var.get() or "")
            target_dict[item]["name"] = current_name
            if previous_name != current_name and target_dict[item].get(
                "_group_name_auto"
            ):
                # Явное редактирование отключает автоматическое выравнивание
                # серии, чтобы пользовательское название не было перезаписано.
                target_dict[item]["_group_name_auto"] = False
                target_dict[item].pop("_group_name_template", None)
                target_dict[item].pop("_group_name_number", None)
            target_dict[item]["merge"] = self.grp_merge_var.get()
            target_dict[item]["subfolder"] = self.grp_subfolder_var.get()
            try:
                target_dict[item]["pause"] = self.grp_pause_var.get()
            except tk.TclError: pass
        else:
            target_dict[item]["title"] = self.grp_name_var.get()

        target_dict[item]["artist"] = self.grp_artist_var.get()
        target_dict[item]["album"] = self.grp_album_var.get()
        target_dict[item]["album_artist"] = self.grp_album_artist_var.get()
        target_dict[item]["genre"] = self.grp_genre_var.get()
        target_dict[item]["composer"] = self.grp_composer_var.get()
        target_dict[item]["year"] = self.grp_year_var.get()
        target_dict[item]["cover"] = self.grp_cover_var.get()

        if is_group:
            self.export_tree.item(item, text=self.grp_name_var.get())
        else:
            self.export_tree.set(item, "title", self.grp_name_var.get())
        self._schedule_export_project_save()

    def apply_pause_mass(self):
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return
        try:
            val = self.grp_pause_var.get()
        except tk.TclError:
            return  # Игнорируем, если введено не число

        # Сохраняем как дефолтное значение
        self.config["default_group_pause"] = val
        self.save_settings()

        # Применяем ко всем существующим группам
        for g_id in self.export_groups:
            self.export_groups[g_id]["pause"] = val

        self._schedule_export_project_save()
        self._show_info("Успех", f"Пауза {val} мс применена ко всем группам и сохранена как значение по умолчанию!")

    def update_total_export_duration(self):
        """Пересчитывает и отображает общее время всех файлов в дереве экспорта"""
        total_sec = 0.0
        # Считаем только файлы, чтобы избежать двойного счета групп
        for f_id, f_data in self.export_files.items():
            if self.export_tree.exists(f_id):
                dur_str = self.export_tree.set(f_id, "duration")
                parts = dur_str.split(':')
                if len(parts) == 3: total_sec += int(parts[0])*3600 + int(parts[1])*60 + int(parts[2])
                elif len(parts) == 2: total_sec += int(parts[0])*60 + int(parts[1])

        self.lbl_export_total_time.config(text=f"Общее время: {self.format_duration(total_sec)}")


    def open_mass_apply_dialog(self):
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return
        if not self.current_selected_export_item or self.current_selected_export_item not in self.export_groups:
            self._show_warning("Внимание", "Выберите группу-эталон, настройки которой вы хотите применить к остальным.")
            return

        dialog = tk.Toplevel(self.root)
        dialog.withdraw()  # Скрываем окно до завершения настройки.

        dialog.title("Массовое применение")
        dialog.transient(self.root)
        dialog.grab_set()

        ttk.Label(
            dialog,
            text="Какие настройки текущей группы применить ко всем остальным группам?",
            justify=tk.CENTER,
            wraplength=440,
        ).pack(pady=10)

        var_merge = tk.BooleanVar(value=True)
        var_subfolder = tk.BooleanVar(value=True)
        var_pause = tk.BooleanVar(value=True)
        var_save_default = tk.BooleanVar(value=False)

        ttk.Checkbutton(dialog, text="Склеить файлы в один трек", variable=var_merge).pack(anchor=tk.W, padx=30, pady=2)
        ttk.Checkbutton(dialog, text="Сохранять в подпапку", variable=var_subfolder).pack(anchor=tk.W, padx=30, pady=2)
        ttk.Checkbutton(dialog, text="Пауза между файлами", variable=var_pause).pack(anchor=tk.W, padx=30, pady=2)

        ttk.Separator(dialog, orient=tk.HORIZONTAL).pack(fill=tk.X, pady=10, padx=10)
        ttk.Checkbutton(dialog, text="Сохранить эти значения по умолчанию", variable=var_save_default).pack(anchor=tk.W, padx=30, pady=2)

        def apply_changes():
            val_merge = self.grp_merge_var.get()
            val_subfolder = self.grp_subfolder_var.get()
            try:
                val_pause = self.grp_pause_var.get()
            except tk.TclError:
                val_pause = 1000

            for g_id, g_data in self.export_groups.items():
                if var_merge.get(): g_data["merge"] = val_merge
                if var_subfolder.get(): g_data["subfolder"] = val_subfolder
                if var_pause.get(): g_data["pause"] = val_pause

            if var_save_default.get():
                if var_pause.get(): self.config["default_group_pause"] = val_pause
                self.save_settings()

            self._schedule_export_project_save()
            dialog.destroy()
            self._show_info("Успех", "Настройки успешно применены ко всем группам!")

        buttons = ttk.Frame(dialog)
        buttons.pack(fill=tk.X, padx=20, pady=15)
        ttk.Button(
            buttons,
            text="Отмена",
            command=dialog.destroy,
        ).pack(side=tk.RIGHT)
        ttk.Button(
            buttons,
            text="Применить",
            command=apply_changes,
        ).pack(side=tk.RIGHT, padx=(0, 7))
        dialog.protocol("WM_DELETE_WINDOW", dialog.destroy)
        dialog.bind("<Escape>", lambda _event: dialog.destroy())

        # Показываем окно после завершения настройки и центрирования.
        self._center_popup(dialog, 350, 250)

    def apply_tags_mass(self, scope="group_files"):
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return
        if not self.current_selected_export_item: return

        artist = self.grp_artist_var.get()
        album_artist = self.grp_album_artist_var.get()
        album = self.grp_album_var.get()
        genre = self.grp_genre_var.get()
        composer = self.grp_composer_var.get()
        year = self.grp_year_var.get()
        cover = self.grp_cover_var.get()

        item = self.current_selected_export_item
        is_group = item in self.export_groups
        parent_g_id = item if is_group else self.export_tree.parent(item)

        def apply_to_item(i_id):
            target = self.export_groups if i_id in self.export_groups else self.export_files
            target[i_id]["artist"] = artist
            target[i_id]["album"] = album
            target[i_id]["album_artist"] = album_artist
            target[i_id]["genre"] = genre
            target[i_id]["composer"] = composer
            target[i_id]["year"] = year
            target[i_id]["cover"] = cover

        if scope == "selected":
            selected = self.export_tree.selection()
            for sel_id in selected:
                apply_to_item(sel_id)
            self._show_info("Успех", "Теги применены ко всем выделенным элементам!")

        elif scope == "parent_group" and not is_group:
            if parent_g_id in self.export_groups:
                apply_to_item(parent_g_id)
            self._show_info("Успех", "Теги скопированы в родительскую группу!")

        elif scope == "group_files":
            if parent_g_id:
                for f_id in self.export_tree.get_children(parent_g_id):
                    apply_to_item(f_id)
            self._show_info("Успех", "Теги применены ко всем файлам в группе!")

        elif scope == "all":
            # 1. Применяем к группам и их файлам
            for g_id in self.export_groups:
                apply_to_item(g_id)
                for f_id in self.export_tree.get_children(g_id):
                    apply_to_item(f_id)
            # 2. Применяем к одиночным файлам в корне
            for f_id in self.export_tree.get_children(""):
                if f_id in self.export_files:
                    apply_to_item(f_id)
            self._show_info("Успех", "Теги применены абсолютно ко всем группам и файлам!")
        self._schedule_export_project_save()

    def move_export_item(self, direction):
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return
        selected = self.export_tree.selection()
        if not selected: return
        ordered = list(selected)
        if direction > 0:
            ordered.reverse()
        affected_groups = set()
        for item in ordered:
            parent = self.export_tree.parent(item)
            idx = self.export_tree.index(item)
            siblings = self.export_tree.get_children(parent)
            new_index = max(0, min(len(siblings) - 1, idx + direction))
            self.export_tree.move(item, parent, new_index)
            if parent in self.export_groups:
                affected_groups.add(parent)
        for group_id in affected_groups:
            self.update_group_duration(group_id)
        self._refresh_export_tree_action_states()
        self._schedule_export_project_save()

    def merge_selected_export_items(self):
        """Объединяет группы и/или файлы без изменения аудио на диске."""
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return
        selected_items = tuple(self.export_tree.selection())
        if not selected_items:
            self._show_warning(
                "Внимание",
                "Выделите группы или аудиофайлы для объединения.",
            )
            return

        plan = plan_export_merge(
            self.export_tree.get_children(""),
            {
                group_id: self.export_tree.get_children(group_id)
                for group_id in self.export_groups
            },
            selected_items,
            self.export_groups,
            self.export_files,
        )
        target_group = plan["target_group"]
        source_groups = plan["source_groups"]
        files_to_move = plan["file_ids"]

        selected_groups = tuple(
            group_id
            for group_id in (target_group, *source_groups)
            if group_id is not None
        )
        unknown_children = [
            child_id
            for group_id in selected_groups
            for child_id in self.export_tree.get_children(group_id)
            if child_id not in self.export_files
        ]
        if unknown_children:
            self._show_error(
                "Не удалось объединить",
                "Структура списка временно рассинхронизирована. Обновите "
                "список или перезапустите приложение; слияние не выполнялось.",
            )
            logging.error(
                "Слияние экспорта отменено: неизвестные дочерние узлы %s",
                unknown_children,
            )
            return

        roots = tuple(self.export_tree.get_children(""))
        root_positions = {item_id: index for index, item_id in enumerate(roots)}
        contributing_positions = [
            root_positions[group_id]
            for group_id in selected_groups
            if group_id in root_positions
        ]
        for file_id in files_to_move:
            parent_id = self.export_tree.parent(file_id)
            root_id = parent_id or file_id
            if root_id in root_positions:
                contributing_positions.append(root_positions[root_id])

        file_needs_move = any(
            self.export_tree.exists(file_id)
            and self.export_tree.parent(file_id) != target_group
            for file_id in files_to_move
        )
        if target_group is not None and not source_groups and not file_needs_move:
            self._show_info(
                "Объединять нечего",
                (
                    "В выбранной группе нет аудиофайлов."
                    if not files_to_move
                    else (
                        "Выбрана только одна готовая группа — объединять нечего."
                        if selected_items == (target_group,)
                        else "Все выбранные файлы уже находятся в этой группе."
                    )
                ),
            )
            return
        if target_group is None and not files_to_move:
            self._show_warning(
                "Пусто",
                "В выбранных элементах нет аудиофайлов.",
            )
            return

        if source_groups:
            target_name = self.export_groups.get(target_group, {}).get(
                "name", "целевая группа"
            )
            if not self._ask_yes_no(
                "Объединить группы",
                f"Сохранить имя, теги и настройки группы «{target_name}» "
                f"и перенести в неё выбранные файлы?\n\n"
                f"Остальные выбранные группы ({len(source_groups)}) "
                "будут удалены из проекта. Порядок файлов будет взят из "
                "текущего дерева, а итоговая группа займёт место первого "
                "выбранного источника. Файлы на диске не изменятся.",
                icon="warning",
            ):
                return

        if target_group is None:
            target_group = self.add_export_group()
            if target_group is None:
                return
        if contributing_positions:
            self.export_tree.move(target_group, "", min(contributing_positions))

        affected_groups = set()
        for file_id in files_to_move:
            if not self.export_tree.exists(file_id):
                continue
            previous_parent = self.export_tree.parent(file_id)
            if previous_parent in self.export_groups and previous_parent != target_group:
                affected_groups.add(previous_parent)
            self.export_tree.move(file_id, target_group, tk.END)

        for group_id in source_groups:
            if not self.export_tree.exists(group_id):
                self.export_groups.pop(group_id, None)
                continue
            if self.export_tree.get_children(group_id):
                logging.warning(
                    "Группа %s не удалена после слияния: остались неизвестные дочерние узлы",
                    group_id,
                )
                continue
            self.export_groups.pop(group_id, None)
            self.export_tree.delete(group_id)

        for group_id in affected_groups:
            if group_id != target_group and self.export_tree.exists(group_id):
                self.update_group_duration(group_id)

        self.update_group_duration(target_group)
        self.current_selected_export_item = None
        self.export_tree.selection_set(target_group)
        self.export_tree.focus(target_group)
        self.on_export_tree_select(None)
        self._schedule_export_project_save()

    def group_selected_into_new(self):
        """Совместимое имя прежней команды для внешних вызовов."""
        return self.merge_selected_export_items()

    def _renumber_adaptive_export_groups(self, template):
        """Обновляет ширину номеров автоматически созданной серии групп."""
        try:
            renames = adaptive_group_sequence_renames(
                template,
                tuple(self.export_groups.items()),
            )
        except (TemplateError, TypeError, ValueError):
            return
        if not renames:
            return
        for group_id, group_name in renames.items():
            settings = self.export_groups.get(group_id)
            if settings is None:
                continue
            settings["name"] = group_name
            if hasattr(self, "export_tree") and self.export_tree.exists(group_id):
                self.export_tree.item(group_id, text=group_name)
            if getattr(self, "current_selected_export_item", None) == group_id:
                updating = getattr(self, "_is_updating_ui", False)
                self._is_updating_ui = True
                try:
                    self.grp_name_var.set(group_name)
                finally:
                    self._is_updating_ui = updating
        self._schedule_export_project_save()

    def add_export_group(self, name=None, *, name_template=None, name_number=None):
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return None
        g_id = f"group_{uuid.uuid4().hex[:8]}"

        auto_name = name is None
        if not name:
            template = self.settings_vars["default_group_name"].get()
            g_name = next_sequence_name(
                template,
                (group.get("name", "") for group in self.export_groups.values()),
            )
        else:
            g_name = name
            template = str(name_template or "").strip()

        settings = {
            "name": g_name, "merge": True, "subfolder": True,
            "pause": self.config.get("default_group_pause", 1000),
            "artist": "", "album": "","album_artist": "", "genre": "", "composer": "", "year": "", "cover": ""
        }
        if auto_name or template:
            sequence_template = str(template or "").strip()
            if sequence_template:
                if name_number is None:
                    name_number = _group_sequence_number_from_name(
                        sequence_template,
                        g_name,
                    )
                settings.update(
                    {
                        "_group_name_auto": True,
                        "_group_name_template": sequence_template,
                        "_group_name_number": name_number,
                    }
                )
        self.export_groups[g_id] = settings
        self.export_tree.insert(
            "", tk.END, iid=g_id, text=g_name, values=("00:00", ""), open=True
        )
        self.export_tree.selection_set(g_id)
        if auto_name:
            self._renumber_adaptive_export_groups(template)
        self._refresh_export_tree_action_states()
        self._schedule_export_project_save()
        return g_id

    def _set_export_ui_state(self, state):
        """Блокирует редактирование дерева во время фонового чтения файлов."""
        if hasattr(self, 'export_mid_frame'):
            self._set_descendant_state(self.export_mid_frame, state)
        if hasattr(self, "export_tree"):
            try:
                self.export_tree.state(("disabled",) if state == tk.DISABLED else ("!disabled",))
            except tk.TclError:
                pass
        if hasattr(self, "group_settings_frame"):
            self._set_descendant_state(self.group_settings_frame, state)
        if hasattr(self, "btn_export_start"):
            self.btn_export_start.configure(state=state)
        if state != tk.DISABLED:
            self._sync_export_mode_controls()
            selected = self.export_tree.selection() if hasattr(self, "export_tree") else ()
            if selected:
                self.on_export_tree_select(None)
            else:
                self.current_selected_export_item = None
                self._disable_export_settings()
        self._refresh_export_tree_action_states()

    def _set_export_running_state(self, running):
        """Замораживает весь изменяемый проект до завершения сборки."""
        self._export_running = bool(running)
        state = tk.DISABLED if running else tk.NORMAL
        self._set_descendant_state(self.export_mid_frame, state)
        self._set_descendant_state(
            self.export_frame,
            state,
            skip=(self.btn_export_stop,) if running else (),
        )
        self._set_descendant_state(self.group_settings_frame, state)
        try:
            self.export_tree.state(("disabled",) if running else ("!disabled",))
        except tk.TclError:
            pass

        if running:
            self.current_selected_export_item = None
            self._disable_export_settings()
            self.btn_export_start.configure(state=tk.DISABLED)
            self.btn_export_stop.configure(state=tk.NORMAL)
        else:
            self.btn_export_stop.configure(state=tk.DISABLED)
            self._sync_export_mode_controls()
            selected = self.export_tree.selection()
            if selected:
                self.on_export_tree_select(None)
            else:
                self.current_selected_export_item = None
                self._disable_export_settings()
        self._refresh_export_tree_action_states()

    def _set_export_progress_indeterminate(self, active):
        """Включает/выключает анимацию прогресса длительной операции M4B.

        Вызывающие стороны обращаются к виджетам Tk только через
        ``_post_to_ui``. Метод также терпим к закрытию окна во время фонового
        процесса FFmpeg.
        """
        active = bool(active)
        progressbar = getattr(self, "export_progress", None)
        if progressbar is None:
            self._export_progress_indeterminate = active
            return
        try:
            if active:
                if not getattr(self, "_export_progress_indeterminate", False):
                    progressbar.configure(mode="indeterminate")
                    progressbar.start(12)
                    self._export_progress_indeterminate = True
            elif getattr(self, "_export_progress_indeterminate", False):
                progressbar.stop()
                progressbar.configure(mode="determinate")
                self._export_progress_indeterminate = False
        except (AttributeError, tk.TclError, TypeError):
            self._export_progress_indeterminate = active

    def _choose_export_destination(
        self,
        *,
        item_count=0,
        source_label="выбранные файлы",
        new_group_name="",
    ):
        """Выбирает место добавления файлов до изменения проекта.

        Возвращает снимок ``{"kind": ..., "group_id": ..., "name": ...}``
        либо ``None`` при отмене. Окно намеренно не меняет дерево, пути и
        состояние фонового импорта до явного подтверждения.
        """
        selected_group = None
        selected = ()
        try:
            selected = tuple(self.export_tree.selection())
        except (AttributeError, tk.TclError):
            selected = ()
        if selected:
            item_id = selected[0]
            if item_id in self.export_groups:
                selected_group = item_id
            else:
                try:
                    parent_id = self.export_tree.parent(item_id)
                except (AttributeError, tk.TclError):
                    parent_id = ""
                if parent_id in self.export_groups:
                    selected_group = parent_id

        current_name = ""
        if selected_group is not None:
            current_name = str(
                self.export_groups.get(selected_group, {}).get(
                    "name", "текущая группа"
                )
                or "текущая группа"
            )

        dialog = tk.Toplevel(self.root)
        dialog.withdraw()
        dialog.title("Куда добавить файлы")
        dialog.transient(self.root)
        dialog.resizable(False, False)
        dialog.grab_set()

        result = {"value": None}
        default_kind = "current" if selected_group is not None else "root"
        choice_var = tk.StringVar(master=dialog, value=default_kind)

        body = ttk.Frame(dialog, padding=14)
        body.pack(fill=tk.BOTH, expand=True)
        count_text = f" ({int(item_count)} шт.)" if item_count else ""
        ttk.Label(
            body,
            text=f"{source_label}{count_text}. Выберите место назначения:",
            justify=tk.LEFT,
            wraplength=520,
        ).pack(anchor=tk.W, pady=(0, 9))

        options = ttk.LabelFrame(body, text="Назначение", padding=(9, 6))
        options.pack(fill=tk.X)
        current_text = (
            f"В текущую группу «{middle_ellipsize(current_name, 48)}»"
            if selected_group is not None
            else "В текущую группу (сначала выберите группу)"
        )
        current_radio = ttk.Radiobutton(
            options,
            text=current_text,
            value="current",
            variable=choice_var,
            state=tk.NORMAL if selected_group is not None else tk.DISABLED,
        )
        current_radio.pack(anchor=tk.W, pady=2)
        root_radio = ttk.Radiobutton(
            options,
            text="В корень проекта",
            value="root",
            variable=choice_var,
        )
        root_radio.pack(anchor=tk.W, pady=2)
        new_text = "Создать новую группу"
        if new_group_name:
            new_text += f" «{middle_ellipsize(new_group_name, 42)}»"
        ttk.Radiobutton(
            options,
            text=new_text,
            value="new",
            variable=choice_var,
        ).pack(anchor=tk.W, pady=2)

        buttons = ttk.Frame(body)
        buttons.pack(fill=tk.X, pady=(12, 0))

        def finish(value):
            result["value"] = value
            self._close_popup_safely(dialog)

        def apply_choice():
            kind = choice_var.get()
            if kind == "current" and selected_group is None:
                choice_var.set("root")
                return
            finish(kind)

        ttk.Button(
            buttons,
            text="Отмена",
            command=lambda: finish(None),
        ).pack(side=tk.RIGHT)
        ttk.Button(
            buttons,
            text="Продолжить",
            command=apply_choice,
        ).pack(side=tk.RIGHT, padx=(0, 7))
        dialog.protocol("WM_DELETE_WINDOW", lambda: finish(None))
        dialog.bind("<Escape>", lambda _event: finish(None))
        dialog.bind("<Return>", lambda _event: apply_choice())
        self._center_popup(dialog, 580, 255, fit_screen=True)
        try:
            (current_radio if selected_group is not None else root_radio).focus_set()
        except (AttributeError, tk.TclError):
            pass
        self.root.wait_window(dialog)

        kind = result["value"]
        if kind is None:
            return None
        return {
            "kind": kind,
            "group_id": selected_group if kind == "current" else "",
            "name": str(new_group_name or "").strip(),
        }

    def add_export_files(self, files=None, target_group=None):
        if getattr(self, '_export_lock', False) or getattr(self, '_export_running', False):
            return

        interactive_selection = files is None
        if files is None:
            # Берём последний зафиксированный путь
            last_dir = self.config.get("last_browse_dir", "")
            init_dir = resolve_dialog_initial_dir(last_dir, BASE_DIR)

            files = filedialog.askopenfilenames(
                initialdir=init_dir,
                filetypes=[("Audio Files", "*.mp3 *.wav *.ogg *.opus *.m4a *.m4b")]
            )
        if not files: return

        destination = None
        if interactive_selection and target_group is None:
            destination = self._choose_export_destination(
                item_count=len(files),
                source_label="Выбранные аудиофайлы",
            )
            if destination is None:
                return
            if destination["kind"] == "current":
                target_group = destination["group_id"]
            elif destination["kind"] == "root":
                target_group = ""

        if getattr(self, "_export_lock", False) or getattr(self, "_export_running", False):
            return

        # Новую группу нужно создать до включения блокировки импорта: сама
        # ``add_export_group`` намеренно отказывается менять дерево во время
        # чтения метаданных. На этом этапе проект ещё не блокируется, а выбор
        # назначения уже подтверждён пользователем.
        if destination is not None and destination["kind"] == "new":
            files = unique_new_file_paths(files, ())
            if not files:
                self._set_export_status("Файлы уже присутствуют.", "info")
                return
            target_group = self.add_export_group()
            if target_group is None:
                return

        chosen_dir = str(Path(files[0]).parent)
        self.config["last_browse_dir"] = chosen_dir
        if not self.export_outdir_var.get().strip():
            self.export_outdir_var.set(chosen_dir)
            self.config["export_dir"] = chosen_dir
        self.save_settings()

        self._export_lock = True
        self._set_export_ui_state(tk.DISABLED)

        try:
            if target_group is None:
                selected = self.export_tree.selection()
                if selected:
                    sel_item = selected[0]
                    if sel_item in self.export_groups:
                        target_group = sel_item  # Новые файлы добавляются в выбранную группу.
                    else:
                        # Для выбранного файла используем его родительскую группу.
                        target_group = self.export_tree.parent(sel_item)
                else:
                    target_group = ""  # Без выделения добавляем файлы в корень.

            existing_paths = set()
            if destination is None or destination["kind"] != "new":
                for child in self.export_tree.get_children(target_group):
                    if child in self.export_files:
                        existing_paths.add(self.export_files[child]["path"])

            # Убираем уже добавленные и повторно выбранные пути заранее. Тогда
            # фоновый обработчик всегда видит точное `total_files` и гарантированно публикует
            # последнюю неполную пачку, даже если исходный список заканчивался
            # существующим элементом.
            files = unique_new_file_paths(files, existing_paths)

            self._set_export_status(
                "Чтение тегов и извлечение обложек…", "warning"
            )

            # Фоновая загрузка метаданных
            def run_import():
                try:
                    added_count = 0
                    total_files = len(files)
                    batch_data = []  # Накопитель для пакетной отрисовки

                    for i, f in enumerate(files):
                        meta = self.get_audio_metadata(f)
                        f_id = f"file_{uuid.uuid4().hex[:8]}"
                        batch_data.append((f_id, f, meta))
                        added_count += 1

                        # Отправляем пачку в интерфейс каждые 10 файлов ИЛИ если это последний файл
                        if len(batch_data) >= 10 or (i + 1) == total_files:
                            # Передаём аргументы явно, чтобы исключить позднее связывание замыкания.
                            def update_ui(batch, curr):
                                for fid, fp, m in batch:
                                    record = normalize_export_file_record({
                                        "path": fp, "title": m["title"], "artist": m["artist"],
                                        "album": m["album"], "album_artist": m["album_artist"],
                                        "genre": m["genre"], "composer": m["composer"],
                                        "year": m["year"],
                                        "language": m.get("language", ""),
                                        "cover": m["cover"],
                                        "source_name": Path(fp).stem,
                                        "source_filename": Path(fp).name,
                                        "source_title": m["title"],
                                        # Сохраняем точную длительность для
                                        # меток глав M4B; Treeview показывает
                                        # округлённое значение только для интерфейса.
                                        "duration": float(m.get("duration", 0) or 0),
                                    })
                                    self.export_files[fid] = record
                                    self.export_tree.insert(
                                        target_group,
                                        tk.END,
                                        iid=fid,
                                        text=export_file_source_label(record),
                                        values=(
                                            self.format_duration(m["duration"]),
                                            str(record.get("title", "")),
                                        ),
                                    )

                                self._refresh_export_tree_action_states()

                                self._set_export_status(
                                    f"Добавлено {curr}/{total_files}…", "warning"
                                )

                            self._post_to_ui(update_ui, batch_data.copy(), i + 1)
                            batch_data.clear()  # Очищаем накопитель для следующей пачки

                    # Финализация
                    def finish_ui():
                        if target_group != "":
                            self.update_group_duration(target_group)

                        self.update_total_export_duration()

                        if added_count == 0:
                            self._set_export_status(
                                "Файлы уже присутствуют.", "info"
                            )
                        else:
                            self._set_export_status("Ожидание...", "info")

                        self._schedule_export_project_save()
                        self._export_lock = False
                        self._export_import_thread = None
                        self._set_export_ui_state(tk.NORMAL)

                    self._post_to_ui(finish_ui)

                except Exception as e:
                    logging.error(f"Ошибка при добавлении файлов: {e}")
                    def fail_ui():
                        self._set_export_status(
                            "Ошибка при добавлении!", "error"
                        )
                        self._export_lock = False
                        self._export_import_thread = None
                        self._set_export_ui_state(tk.NORMAL)
                    self._post_to_ui(fail_ui)

            self._export_import_thread = threading.Thread(
                target=run_import, daemon=True
            )
            self._export_import_thread.start()

        except Exception as e:
            logging.error(f"Ошибка инициализации импорта: {e}")
            self._export_import_thread = None
            self._export_lock = False
            self._set_export_ui_state(tk.NORMAL)

    def add_export_m4b_chapters(self, files=None):
        """Добавляет главы M4B как виртуальные элементы дерева экспорта."""
        if getattr(self, "_export_lock", False) or getattr(
            self, "_export_running", False
        ):
            return

        if files is None:
            files = filedialog.askopenfilenames(
                initialdir=resolve_dialog_initial_dir(
                    self.config.get("last_browse_dir", ""), BASE_DIR
                ),
                filetypes=[("Аудиокниги M4B", "*.m4b")],
            )
        if not files:
            return

        existing_sources = {
            str(group.get("source_path", ""))
            for group in self.export_groups.values()
            if group.get("source_kind") == "m4b_chapters"
        }
        files = tuple(
            path
            for path in unique_new_file_paths(files, existing_sources)
            if Path(path).suffix.casefold() == ".m4b"
        )
        if not files:
            self._show_info(
                "Нет новых книг",
                "Выбранные M4B уже разобраны или имеют неподдерживаемое расширение.",
            )
            return

        chosen_dir = str(Path(files[0]).parent)
        self.config["last_browse_dir"] = chosen_dir
        if not self.export_outdir_var.get().strip():
            self.export_outdir_var.set(chosen_dir)
            self.config["export_dir"] = chosen_dir
        self.save_settings()

        self._export_lock = True
        self._set_export_ui_state(tk.DISABLED)
        self._set_export_status(
            f"Чтение глав M4B: 0/{len(files)}…", "warning"
        )

        def run_import():
            imported = []
            failures = []
            warnings_list = []
            try:
                for index, filepath in enumerate(files, 1):
                    try:
                        prepared = build_m4b_virtual_export_group(
                            filepath,
                            probe_m4b_chapters(filepath),
                        )
                        if not prepared.get("chapters"):
                            raise ValueError("в контейнере нет встроенных глав")
                        if prepared.get("group", {}).get("cover_source"):
                            cover = str(
                                self.get_audio_metadata(filepath).get("cover", "")
                                or ""
                            )
                            if cover:
                                prepared["group"]["cover"] = cover
                                for chapter in prepared["chapters"]:
                                    chapter["cover"] = cover
                        imported.append(prepared)
                        for warning in prepared.get("warnings", ()):
                            warning = str(warning).strip()
                            if warning:
                                warnings_list.append(warning)
                                logging.warning("Импорт глав M4B: %s", warning)
                    except Exception as exc:
                        failures.append((str(filepath), str(exc)))
                        logging.exception(
                            "Не удалось разобрать главы M4B %s", filepath
                        )
                    self._post_export_status(
                        f"Чтение глав M4B: {index}/{len(files)}…", "warning"
                    )

                def finish_ui():
                    inserted_groups = []
                    try:
                        for prepared in imported:
                            group = copy.deepcopy(prepared["group"])
                            group_id = f"group_{uuid.uuid4().hex[:8]}"
                            self.export_groups[group_id] = group
                            self.export_tree.insert(
                                "",
                                tk.END,
                                iid=group_id,
                                text=group["name"],
                                values=("00:00", ""),
                                open=True,
                            )
                            inserted_groups.append(group_id)
                            for chapter in prepared["chapters"]:
                                file_id = f"file_{uuid.uuid4().hex[:8]}"
                                chapter = copy.deepcopy(chapter)
                                self.export_files[file_id] = chapter
                                self.export_tree.insert(
                                    group_id,
                                    tk.END,
                                    iid=file_id,
                                    text=export_file_source_label(chapter),
                                    values=(
                                        self.format_duration(chapter["duration"]),
                                        str(chapter.get("title", "")),
                                    ),
                                )
                            self.update_group_duration(group_id)

                        self.update_total_export_duration()
                        if inserted_groups:
                            selected = inserted_groups[-1]
                            self.export_tree.selection_set(selected)
                            self.export_tree.focus(selected)
                            self.export_tree.see(selected)

                        if failures and inserted_groups:
                            preview = "\n".join(
                                f"{Path(path).name}: {error}"
                                for path, error in failures[:5]
                            )
                            suffix = "\n…" if len(failures) > 5 else ""
                            self._show_warning(
                                "M4B разобраны частично",
                                f"Добавлено книг: {len(inserted_groups)}. "
                                f"Не удалось прочитать: {len(failures)}.\n\n"
                                f"{preview}{suffix}",
                            )
                        elif failures:
                            preview = "\n".join(
                                f"{Path(path).name}: {error}"
                                for path, error in failures[:5]
                            )
                            suffix = "\n…" if len(failures) > 5 else ""
                            self._show_error(
                                "M4B не разобраны",
                                "Ни в одном выбранном файле не удалось "
                                f"прочитать встроенные главы.\n\n{preview}{suffix}",
                            )
                        elif warnings_list:
                            self._show_warning(
                                "M4B разобраны с предупреждениями",
                                f"Добавлено книг: {len(inserted_groups)}. "
                                "Некоторые границы глав были исправлены; "
                                "подробности записаны в журнал.",
                            )
                        elif inserted_groups:
                            self._show_info(
                                "M4B разобраны",
                                f"Добавлено книг: {len(inserted_groups)}. "
                                "Главы доступны в дереве без создания "
                                "временных аудиофайлов.",
                            )
                        else:
                            self._show_error(
                                "M4B не разобраны",
                                "Ни в одном выбранном файле не удалось "
                                "прочитать встроенные главы.",
                            )

                        if failures and not inserted_groups:
                            self._set_export_status(
                                "Ошибка разбора M4B!", "error"
                            )
                        else:
                            self._set_export_status("Ожидание...", "info")
                        self._schedule_export_project_save()
                    finally:
                        self._export_lock = False
                        self._export_import_thread = None
                        self._set_export_ui_state(tk.NORMAL)

                self._post_to_ui(finish_ui)
            except Exception:
                logging.exception("Ошибка пакетного разбора M4B")

                def fail_ui():
                    self._set_export_status("Ошибка разбора M4B!", "error")
                    self._export_lock = False
                    self._export_import_thread = None
                    self._set_export_ui_state(tk.NORMAL)
                    self._show_error(
                        "Ошибка",
                        "Не удалось завершить разбор выбранных M4B. "
                        "Подробности записаны в журнал.",
                    )

                self._post_to_ui(fail_ui)

        self._export_import_thread = threading.Thread(
            target=run_import,
            daemon=True,
            name="m4b-chapter-import",
        )
        try:
            self._export_import_thread.start()
        except Exception:
            self._export_import_thread = None
            self._export_lock = False
            self._set_export_ui_state(tk.NORMAL)
            logging.exception("Не удалось запустить разбор M4B")
            self._show_error(
                "Ошибка",
                "Не удалось запустить разбор M4B. Подробности записаны в журнал.",
            )

    def add_export_folder(self):
        if getattr(self, '_export_lock', False) or getattr(self, '_export_running', False):
             self._show_warning("Занято", "Дождитесь окончания предыдущего импорта файлов.")
             return

        # Берём последний зафиксированный путь
        last_dir = self.config.get("last_browse_dir", "")
        init_dir = resolve_dialog_initial_dir(last_dir, BASE_DIR)

        folder = filedialog.askdirectory(initialdir=init_dir)
        if not folder: return

        files = sorted(
            [
                str(path)
                for path in Path(folder).glob("*.*")
                if path.suffix.lower() in {
                    ".mp3", ".wav", ".ogg", ".opus", ".m4a", ".m4b"
                }
            ],
            key=self._natural_sort_key,
        )
        if not files:
            self._show_info("Пусто", "В папке нет аудиофайлов.")
            return

        destination = self._choose_export_destination(
            item_count=len(files),
            source_label=f"Аудиофайлы из папки «{Path(folder).name}»",
            new_group_name=Path(folder).name,
        )
        if destination is None:
            return

        if getattr(self, "_export_lock", False) or getattr(self, "_export_running", False):
            return

        if destination["kind"] == "new":
            target_group = self.add_export_group(name=destination["name"])
            if target_group is None:
                return
        elif destination["kind"] == "current":
            target_group = destination["group_id"]
        else:
            target_group = ""
        self.config["last_browse_dir"] = str(Path(folder).parent)
        self.save_settings()
        self.add_export_files(files=files, target_group=target_group)

    def get_audio_metadata(self, filepath):
        """Читает длительность, теги и извлекает обложку через ffprobe/ffmpeg"""
        cmd = [get_ffprobe_path(), "-v", "quiet", "-print_format", "json", "-show_format", "-show_streams", filepath]
        try:
            startupinfo = None
            if platform.system() == "Windows":
                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW

            # Декодируем вывод перед разбором JSON.
            out = subprocess.check_output(cmd, startupinfo=startupinfo).decode('utf-8', errors='ignore')
            data = json.loads(out)

            # MP3 обычно показывает теги на уровне контейнера, тогда как Ogg
            # Vorbis/Opus FFmpeg возвращает VorbisComment/OpusTags у аудио-
            # потока. Читаем оба места, иначе при повторном импорте Opus в интерфейсе
            # визуально пропадали альбом и другие уже записанные поля.
            tags = {
                k.lower(): v
                for k, v in data.get("format", {}).get("tags", {}).items()
            }
            for stream in data.get("streams", []):
                if stream.get("codec_type") != "audio":
                    continue
                for key, value in stream.get("tags", {}).items():
                    tags.setdefault(key.lower(), value)
            duration = float(data.get("format", {}).get("duration", 0.0))

            cover_path = ""
            # Ищем видеопоток (в аудиофайлах это обложка)
            has_cover = any(s.get("codec_type") == "video" for s in data.get("streams", []))
            if has_cover:
                covers_dir = SESSION_TEMP_DIR / "covers"
                covers_dir.mkdir(parents=True, exist_ok=True)
                cover_file = covers_dir / f"cover_{uuid.uuid4().hex}.jpg"

                # Извлекаем 1 кадр обложки
                ffmpeg_cmd = [get_ffmpeg_path(), "-y", "-i", filepath, "-an", "-vframes", "1", str(cover_file)]
                cover_result = subprocess.run(
                    ffmpeg_cmd,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    startupinfo=startupinfo,
                )

                if cover_result.returncode == 0 and cover_file.exists():
                    cover_path = str(cover_file.resolve())
                else:
                    cover_file.unlink(missing_ok=True)

            # Учитываем стандартные и сырые ключи ID3.
            title = tags.get("title", tags.get("tit2", Path(filepath).stem))
            artist = tags.get("artist", tags.get("tpe1", ""))
            album = tags.get("album", tags.get("talb", ""))
            album_artist = tags.get("album_artist", tags.get("albumartist", tags.get("tpe2", "")))
            genre = tags.get("genre", tags.get("tcon", ""))
            composer = tags.get("composer", tags.get("tcom", ""))
            year = tags.get("date", tags.get("year", tags.get("tyer", tags.get("tdrc", ""))))
            language = tags.get("language", "")

            return {
                "duration": duration,
                "title": title,
                "artist": artist,
                "album": album,
                "album_artist": album_artist,
                "genre": genre,
                "composer": composer,
                "year": year,
                "language": language,
                "cover": cover_path
            }
        except Exception as e:
            logging.error(f"Ошибка чтения метаданных {filepath}: {e}")
            return {"duration": 0.0, "title": Path(filepath).stem, "artist": "","album_artist":"","genre":"", "album": "", "composer": "", "year": "", "language": "", "cover": ""}

    def format_duration(self, seconds):
        m, s = divmod(int(seconds), 60)
        h, m = divmod(m, 60)
        return f"{h:02d}:{m:02d}:{s:02d}" if h > 0 else f"{m:02d}:{s:02d}"

    def update_group_duration(self, group_id):
        total_sec = 0.0
        for child in self.export_tree.get_children(group_id):
            dur_str = self.export_tree.set(child, "duration")
            # Простой парсинг обратно в секунды для суммы
            parts = dur_str.split(':')
            if len(parts) == 3: total_sec += int(parts[0])*3600 + int(parts[1])*60 + int(parts[2])
            elif len(parts) == 2: total_sec += int(parts[0])*60 + int(parts[1])
        self.export_tree.set(
            group_id,
            "duration",
            self.format_duration(total_sec),
        )
        self.update_total_export_duration()

    def remove_export_items(self):
        """Безопасное удаление элементов с защитой от фантомных дочерних узлов"""
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return
        selected = self.export_tree.selection()
        groups_to_update = set()

        for item in selected:
            # 1. Элемент мог быть удалён ранее вместе с родительской группой.
            if not self.export_tree.exists(item):
                if item in self.export_groups: del self.export_groups[item]
                if item in self.export_files: del self.export_files[item]
                continue

            # 2. Группа
            if item in self.export_groups:
                # Удаляем из словаря все входящие в неё файлы.
                for child in self.export_tree.get_children(item):
                    if child in self.export_files:
                        del self.export_files[child]
                del self.export_groups[item]
                self.export_tree.delete(item)

            # 3. Одиночный файл
            elif item in self.export_files:
                parent = self.export_tree.parent(item)
                if parent: groups_to_update.add(parent)
                del self.export_files[item]
                self.export_tree.delete(item)

        # Пересчитываем длительность для оставшихся групп и общее время
        for g in groups_to_update:
            if self.export_tree.exists(g):
                self.update_group_duration(g)

        self.update_total_export_duration()
        self.current_selected_export_item = None
        self._disable_export_settings()
        self._refresh_export_tree_action_states()
        self._schedule_export_project_save()

    def clear_export_project(self):
        """Очищает только текущий список, никогда не удаляя аудио с диска."""
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return

        root_items = tuple(self.export_tree.get_children(""))
        file_count = len(self.export_files)
        group_count = len(self.export_groups)
        if not root_items and not file_count and not group_count:
            self._export_project_explicitly_cleared = True
            self._delete_export_project_session()
            self._show_info("Пусто", "Список экспорта уже пуст.")
            return

        if not self._ask_yes_no(
            "Очистить весь список",
            f"Убрать из проекта все группы ({group_count}) "
            f"и аудиофайлы ({file_count})?\n\n"
            "Сами файлы на диске не будут удалены.",
            icon="warning",
        ):
            return

        for item_id in root_items:
            if self.export_tree.exists(item_id):
                self.export_tree.delete(item_id)
        self.export_groups.clear()
        self.export_files.clear()
        self.group_counter = 0
        self.current_selected_export_item = None
        self._disable_export_settings()
        self.update_total_export_duration()
        self.export_progress["value"] = 0
        self._set_export_status("Ожидание...", "info")
        self._refresh_export_tree_action_states()
        self._export_project_explicitly_cleared = True
        self._delete_export_project_session()

    def auto_split_export(self):
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return

        root_items = tuple(self.export_tree.get_children(""))
        group_children = {
            group_id: tuple(self.export_tree.get_children(group_id))
            for group_id in self.export_groups
        }
        all_files = ordered_export_file_ids(
            root_items, group_children, self.export_files.keys()
        )

        if not all_files:
            self._show_info("Пусто", "Сначала добавьте аудиофайлы.")
            return

        dialog = tk.Toplevel(self.root)
        dialog.withdraw()  # Скрываем окно до завершения настройки.
        dialog.title("Авто-разбивка")
        dialog.transient(self.root)
        dialog.grab_set()

        ttk.Label(dialog, text="Максимальная длительность группы (минут):").pack(pady=(10, 0))
        limit_var = tk.IntVar(value=60)
        ttk.Entry(dialog, textvariable=limit_var, justify=tk.CENTER).pack(pady=5)

        ttk.Label(
            dialog,
            text=(
                "Шаблон: {num}; {num:N}, где N — стартовый номер; "
                "{num:00d} — адаптивные нули"
            ),
            justify=tk.CENTER,
        ).pack(pady=(10, 0))
        template_var = tk.StringVar(value=self.settings_vars["default_group_name"].get())
        template_row = ttk.Frame(dialog)
        template_row.pack(fill=tk.X, padx=20, pady=5)
        auto_split_template_entry = ttk.Entry(
            template_row,
            textvariable=template_var,
            justify=tk.CENTER,
        )
        auto_split_template_entry.pack(side=tk.LEFT, fill=tk.X, expand=True)
        ttk.Button(
            template_row,
            text="Помощник…",
            command=lambda: self._open_template_helper(
                template_var,
                "group_sequence",
                owner=dialog,
                target_entry=auto_split_template_entry,
                title="Помощник имени группы",
                existing_names=self._template_helper_existing_group_names(),
            ),
        ).pack(side=tk.LEFT, padx=(6, 0))

        def do_split():
            try:
                limit_minutes = limit_var.get()
                if limit_minutes <= 0:
                    raise ValueError
                limit_sec = limit_minutes * 60
            except (tk.TclError, TypeError, ValueError):
                self._show_error(
                    "Ошибка", "Введите положительное число минут!", parent=dialog
                )
                return

            template = template_var.get().strip()
            if not template:
                self._show_error(
                    "Ошибка", "Шаблон имени группы не может быть пустым.",
                    parent=dialog,
                )
                return
            try:
                _template_value, parsed_placeholders, start_index = (
                    _group_sequence_placeholders(template)
                )
            except TemplateError as exc:
                self._show_error("Ошибка", str(exc), parent=dialog)
                return
            self.settings_vars["default_group_name"].set(template)
            self.save_settings()
            dialog.destroy()

            file_durs = {}
            for f_id in all_files:
                dur_str = self.export_tree.set(f_id, "duration")
                parts = dur_str.split(':')
                sec = 0
                if len(parts) == 3: sec = int(parts[0])*3600 + int(parts[1])*60 + int(parts[2])
                elif len(parts) == 2: sec = int(parts[0])*60 + int(parts[1])
                file_durs[f_id] = sec

            groups_data = split_export_file_ids(all_files, file_durs, limit_sec)

            if not groups_data: return

            # Сначала строим новую структуру в памяти. Дерево изменяем только
            # после успешного расчёта, чтобы ошибка шаблона/длительности не
            # оставила проект наполовину перегруппированным.
            planned_groups = []

            adaptive_template = any(
                number_format == ADAPTIVE_COUNTER_FORMAT
                for _match, _start, number_format in parsed_placeholders
            )
            fixed_template = any(
                number_format
                and number_format != ADAPTIVE_COUNTER_FORMAT
                for _match, _start, number_format in parsed_placeholders
            )
            adaptive_width = None
            if adaptive_template:
                last_number = start_index + len(groups_data) - 1
                adaptive_width = max(
                    1,
                    len(str(abs(int(start_index)))),
                    len(str(abs(int(last_number)))),
                )

            for idx, group_files in enumerate(groups_data, 0):
                current_number = start_index + idx
                if adaptive_template or fixed_template:
                    g_name = _render_group_sequence_name(
                        template,
                        current_number,
                        adaptive_width,
                    )
                else:
                    current_num = format_sequence_number(
                        current_number,
                        len(groups_data),
                        start_index=start_index,
                    )
                    g_name = _GROUP_SEQUENCE_PLACEHOLDER_RE.sub(
                        current_num,
                        template,
                    )
                planned_groups.append((g_name, group_files))

            for item in self.export_tree.get_children():
                self.export_tree.delete(item)
            self.export_groups.clear()
            self.current_selected_export_item = None

            for index, (g_name, group_files) in enumerate(planned_groups):
                g_id = self.add_export_group(
                    name=g_name,
                    name_template=template,
                    name_number=start_index + index,
                )
                for f_id in group_files:
                    record = normalize_export_file_record(self.export_files[f_id])
                    self.export_files[f_id] = record
                    self.export_tree.insert(
                        g_id,
                        tk.END,
                        iid=f_id,
                        text=export_file_source_label(record),
                        values=(
                            self.format_duration(file_durs[f_id]),
                            str(record.get("title", "")),
                        ),
                    )
                self.update_group_duration(g_id)
            self.export_tree.selection_remove(*self.export_tree.selection())
            self._disable_export_settings()
            self._refresh_export_tree_action_states()
            self._schedule_export_project_save()

        buttons = ttk.Frame(dialog)
        buttons.pack(fill=tk.X, padx=20, pady=10)
        ttk.Button(
            buttons,
            text="Отмена",
            command=dialog.destroy,
        ).pack(side=tk.RIGHT)
        ttk.Button(
            buttons,
            text="Разбить",
            command=do_split,
        ).pack(side=tk.RIGHT, padx=(0, 7))
        dialog.protocol("WM_DELETE_WINDOW", dialog.destroy)
        dialog.bind("<Escape>", lambda _event: dialog.destroy())

        self._center_popup(dialog, 350, 220)

    # --- Процесс Экспорта ---
    def stop_export_process(self):
        self.is_export_stopped = True
        self.btn_export_stop.config(state=tk.DISABLED)
        self._set_export_status("Остановка…", "warning")

    def _finish_export_process_ui(self, outcome):
        """Возвращает интерфейс сборщика в устойчивое состояние после фонового потока.

        При штатной пользовательской остановке обработчик сперва ставит в очередь
        интерфейса модальное сообщение и лишь затем этот обратный вызов, поэтому сброс виден
        после закрытия сообщения. Успех, частичный успех и реальная ошибка
        сохраняют свои финальные статус и прогресс для диагностики.
        """
        self._export_thread = None
        self._set_export_running_state(False)
        # Успешный или аварийный запуск M4B мог завершиться, пока индикатор
        # находился в неопределённом режиме. Останавливаем анимацию, даже если
        # итоговое значение намеренно сохраняется для диагностики.
        self._set_export_progress_indeterminate(False)
        if outcome == "stopped":
            self.export_progress.configure(value=0)
            self._set_export_status("Ожидание...", "info")
        self.is_export_stopped = False

    def _update_file_tags_inplace(self, fp, f_tags, cov, title_for_status):
        """Обновляет теги файла прямо в его исходной папке на диске без конвертации"""
        source_path = Path(fp)
        # Тестовые и внешние вызовы могут использовать вспомогательную функцию без полностью
        # построенного Tk-приложения. В реальном фоновом обработчике очередь всегда есть.
        if hasattr(self, "_ui_queue"):
            self._post_export_activity_status(
                "Теги",
                title_for_status or source_path.name,
                "warning",
            )
        elif hasattr(self, "_post_status_label"):
            self._post_status_label(
                self.lbl_export_status,
                format_export_activity_status(
                    "Теги", title_for_status or source_path.name
                ),
                "warning",
            )

        if not source_path.is_file():
            logging.error("Исходный аудиофайл для тегирования не найден: %s", fp)
            return False
        temp_file = source_path.with_name(
            f".tags_{uuid.uuid4().hex}.tmp{source_path.suffix}"
        )
        cmd = [get_ffmpeg_path(), "-y", "-i", str(source_path)]

        ext = source_path.suffix.lower()
        cover_supported = ext in {".mp3", ".m4a", ".m4b"}
        xiph_metadata_path = (
            _create_xiph_cover_metadata_file(cov, source_path.name)
            if ext in {".ogg", ".opus"}
            else None
        )
        if xiph_metadata_path is not None:
            cmd.extend(["-f", "ffmetadata", "-i", str(xiph_metadata_path)])
        if cov and os.path.isfile(cov) and cover_supported:
            cover_codec = (
                "mjpeg" if ext == ".mp3" else _m4b_cover_codec(cov)
            )
            cmd.extend([
                "-i", str(cov), "-map", "0:a:0", "-map", "1:v:0",
                "-c:a", "copy", "-c:v", cover_codec,
                "-disposition:v:0", "attached_pic",
                "-metadata:s:v", "title=Album cover",
                "-metadata:s:v", "comment=Cover (front)",
            ])
            if ext == ".mp3":
                cmd.extend(["-id3v2_version", "3"])
        else:
            # Входной виртуальный ``attached_pic`` у файла Xiph является
            # представлением METADATA_BLOCK_PICTURE. При новой обложке явно
            # копируем лишь аудио, чтобы старый блок изображения не задублировался.
            if ext in {".ogg", ".opus"}:
                # FFmpeg предоставляет METADATA_BLOCK_PICTURE как виртуальный
                # видеопоток, который мультиплексор Opus не может скопировать
                # обратно. Всегда выбираем только настоящий аудиопоток, а затем
                # записываем новый комментарий ниже.
                cmd.extend(["-map", "0:a:0", "-c:a", "copy"])
            else:
                cmd.extend(["-map", "0", "-c", "copy"])
            if (
                cov
                and os.path.isfile(cov)
                and not cover_supported
                and ext not in {".ogg", ".opus"}
            ):
                logging.warning(
                    "Обложка пропущена при обновлении тегов %s: формат %s "
                    "не поддерживает attached picture этим способом.",
                    source_path.name,
                    ext or "без расширения",
                )

        # M4B хранит номера томов и тип аудиокниги вне редактируемых полей.
        # Сохраняем их вместе с главами, явно очищая только поля интерфейса,
        # которые пользователь оставил пустыми.
        cmd.extend(["-map_metadata", "0" if ext == ".m4b" else "-1"])
        if ext == ".m4b":
            for key in (
                "title", "artist", "album", "album_artist", "genre",
                "composer", "date", "language",
            ):
                if not (f_tags or {}).get(key):
                    cmd.extend(["-metadata", f"{key}="])

        if f_tags:
            for k, v in f_tags.items():
                if v: cmd.extend(["-metadata", f"{k}={v}"])
        if xiph_metadata_path is not None:
            cmd.extend(["-map_metadata", "1"])

        cmd.append(str(temp_file))

        startupinfo = None
        if platform.system() == "Windows":
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW

        try:
            res = subprocess.run(
                cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, startupinfo=startupinfo
            )
            if res.returncode == 0 and temp_file.exists():
                os.replace(temp_file, source_path)
                return True

            err_log = (
                res.stderr.decode('utf-8', errors='ignore')
                if res.stderr
                else "Неизвестная ошибка"
            )
            logging.error(f"Ошибка FFmpeg при обновлении тегов {fp}:\n{err_log}")
            return False
        except Exception:
            logging.exception("Ошибка запуска FFmpeg при обновлении тегов %s", fp)
            return False
        finally:
            temp_file.unlink(missing_ok=True)
            if xiph_metadata_path is not None:
                xiph_metadata_path.unlink(missing_ok=True)

    def _run_output_target_set(
        self,
        items,
        group_children,
        export_groups,
        export_files,
        targets,
        base_dir,
        *,
        apply_fx=False,
        default_effects=None,
        cancelled=None,
        progress_callback=None,
        planned_records=None,
        settings_snapshot=None,
        max_workers=1,
        _reuse_planned_records=False,
        _active_target_indices=None,
        _m4b_job_filter=None,
        _file_job_filter=None,
        _prepared_records_by_target_item=None,
    ):
        """Экспортирует цели, параллельно обрабатывая независимые элементы.

        Цели выполняются в заданном порядке. При ``max_workers > 1`` обычная
        цель параллелит каждую независимую выходную запись: склеенную группу,
        корневой файл или отдельный файл несклеенной группы. Цель M4B параллелит
        уже спланированные выходные части. Поэтому авторазбиение одной большой
        группы использует тот же общий лимит FFmpeg, что и несколько групп.
        Значение ``0`` выбирает число логических процессоров; значение по
        умолчанию ``1`` сохраняет детерминированность прямых вызовов и тестов.

        Приватные аргументы предназначены только для дочерних заданий
        внутреннего пула. Они ограничивают проход одной целью и одним
        результатом, но оставляют доступным общий план и его индекс для
        нумерации N/T и глав.
        """
        items = tuple(items)
        active_target_indices = (
            None
            if _active_target_indices is None
            else frozenset(int(value) for value in _active_target_indices)
        )
        m4b_job_filter = (
            None
            if _m4b_job_filter is None
            else frozenset(_m4b_job_filter)
        )
        file_job_filter = (
            None
            if _file_job_filter is None
            else frozenset(_file_job_filter)
        )
        # Фоновый обработчик должен использовать те же неизменяемые значения M4B по
        # умолчанию, которые прошли предварительную проверку. ``settings_snapshot`` передаётся
        # из пути запуска; резервный путь сохраняет обратную совместимость прямых и
        # интеграционных вызывающих сторон.
        runtime_config = (
            settings_snapshot
            if isinstance(settings_snapshot, dict)
            else getattr(self, "config", {})
        )
        if not isinstance(runtime_config, dict):
            runtime_config = {}
        normalized_targets = plan_output_targets(
            [normalize_output_target(target) for target in targets],
            base_dir,
            legacy_single_dir=base_dir,
        )
        # Старые/импортированные записи экспорта могут не содержать точную
        # длительность, использованную фоновой проверкой метаданных. Разрешаем
        # отсутствующие длительности M4B в этом фоновом потоке (никогда не в
        # потоке Tk), затем перестраиваем чистый план, чтобы ограничение
        # длительности действительно разделяло те же части, которые будут
        # закодированы.
        duration_overrides = {}
        # Дочерние задания пула получают уже замороженный снимок родителя и
        # только читают его. Повторная глубокая копия всего проекта для каждого
        # выходного файла превращала подготовку большой группы в O(N²).
        runtime_export_files = (
            export_files
            if _reuse_planned_records
            else copy.deepcopy(export_files)
        )

        def safe_duration(value):
            try:
                result = float(value or 0)
            except (TypeError, ValueError, OverflowError):
                return 0.0
            return result if math.isfinite(result) and result > 0 else 0.0

        if (
            not _reuse_planned_records
            and any(target.get("format") == "m4b" for target in normalized_targets)
        ):
            selected_file_ids = []
            selected_file_id_set = set()
            for item_id in items:
                candidates = (
                    group_children.get(item_id, ())
                    if item_id in export_groups
                    else (item_id,)
                )
                for file_id in candidates:
                    if (
                        file_id in runtime_export_files
                        and file_id not in selected_file_id_set
                    ):
                        selected_file_id_set.add(file_id)
                        selected_file_ids.append(file_id)
            for file_id in selected_file_ids:
                if cancelled and cancelled():
                    raise InterruptedError("Сборка остановлена пользователем")
                setting = runtime_export_files[file_id]
                duration = safe_duration(setting.get("duration", 0))
                if duration <= 0:
                    duration = _probe_audio_duration(setting.get("path", ""))
                if duration > 0:
                    setting["duration"] = duration
                    duration_overrides[file_id] = duration
            try:
                planned_records = plan_export_target_paths(
                    items,
                    group_children,
                    export_groups,
                    runtime_export_files,
                    normalized_targets,
                    base_dir,
                    m4b_template=runtime_config.get(
                        "export_m4b_template", DEFAULT_CONFIG["export_m4b_template"]
                    ),
                    m4b_max_duration_seconds=float(
                        runtime_config.get(
                            "export_m4b_max_duration_hours",
                            DEFAULT_M4B_MAX_DURATION_HOURS,
                        )
                        or 0
                    ) * 3600,
                    m4b_max_chapters=int(
                        runtime_config.get("export_m4b_max_chapters", 0) or 0
                    ),
                )
            except (TypeError, ValueError, TemplateError) as exc:
                # Проверка во время выполнения может обнаружить дополнительную часть M4B,
                # о которой интерфейс не мог знать. Если при пересчёте обнаруживается
                # настоящая ошибка конфликта/шаблона, прерываем работу с этой
                # диагностикой, а не молча возвращаемся к устаревшим путям.
                logging.warning("Не удалось уточнить план M4B: %s", exc)
                if duration_overrides:
                    raise
        # Планировщик знает, что объединённая группа — один результат, а группа
        # M4B может превратиться в несколько частей. Раньше подсчёт дочерних
        # элементов источника здесь заставлял индикатор остановиться ниже 100%
        # (или перескочить выше него).
        planned_records = tuple(planned_records or ())
        if planned_records and not _reuse_planned_records:
            # M4B может уточнить число частей после фонового ffprobe, поэтому
            # повторяем чистую проверку уже для окончательного рабочего плана.
            # Это закрывает редкий конфликт, которого ещё не было видно UI.
            validate_export_output_paths(
                (record["path"] for record in planned_records),
                (
                    settings.get("path", "")
                    for settings in runtime_export_files.values()
                ),
            )
        total_units = max(
            1,
            len(planned_records)
            if planned_records
            else sum(
                len(group_children.get(item, ()))
                if item in export_groups
                else 1
                for item in items
            ) * len(normalized_targets),
        )
        if _prepared_records_by_target_item is None:
            records_by_target_item = {}
            for record in planned_records:
                records_by_target_item.setdefault(
                    (record.get("target_index"), record.get("item_id")), []
                ).append(record)
        else:
            records_by_target_item = _prepared_records_by_target_item

        try:
            worker_limit = int(max_workers)
        except (TypeError, ValueError, OverflowError):
            worker_limit = 1
        if worker_limit == 0:
            worker_limit = max(1, os.cpu_count() or 1)
        elif worker_limit < 0:
            worker_limit = 1
        item_set = frozenset(items)

        def m4b_record_job_key(record):
            part = record.get("part")
            part_number = getattr(part, "number", None) if part is not None else None
            return (
                int(record.get("target_index", 0)),
                record.get("item_id"),
                part_number,
            )

        def parallel_job_label(target, item_id, record=None):
            """Возвращает короткое стабильное имя задания для общего статуса."""
            if isinstance(record, dict) and record.get("path"):
                try:
                    return Path(record["path"]).name
                except (TypeError, ValueError, OSError):
                    pass
            if item_id in export_groups:
                name = export_groups[item_id].get("name") or "Группа"
            else:
                setting = runtime_export_files.get(item_id, {})
                raw_path = setting.get("path")
                try:
                    name = Path(raw_path).name if raw_path else ""
                except (TypeError, ValueError, OSError):
                    name = ""
                name = name or setting.get("title") or "Аудиофайл"
            fmt = str(target.get("format") or "").lower()
            format_name = _SYNTHESIS_STATUS_FORMAT_NAMES.get(fmt, fmt.upper())
            return f"{name} [{format_name}]" if format_name else str(name)

        jobs_by_target = []
        # Последовательный путь не нуждается в полном графе заданий. Это также
        # важно для дочерних вызовов пула: каждый из них уже ограничен одной
        # записью и не должен снова обходить весь проект.
        if worker_limit > 1:
            parent_by_file = {
                file_id: group_id
                for group_id, children in group_children.items()
                for file_id in children
            }
            for target_index, target in enumerate(normalized_targets):
                if target.get("format") == "m4b" and planned_records:
                    jobs = []
                    for record in planned_records:
                        if record.get("target_index") != target_index:
                            continue
                        item_id = record.get("item_id")
                        if item_id not in item_set:
                            continue
                        job_token = m4b_record_job_key(record)
                        jobs.append(
                            (
                                item_id,
                                frozenset((job_token,)),
                                None,
                                job_token,
                                parallel_job_label(target, item_id, record),
                            )
                        )
                elif planned_records:
                    jobs = []
                    for record in planned_records:
                        if record.get("target_index") != target_index:
                            continue
                        output_item_id = record.get("item_id")
                        root_item_id = parent_by_file.get(
                            output_item_id,
                            output_item_id,
                        )
                        if root_item_id not in item_set:
                            continue
                        job_token = (target_index, output_item_id, None)
                        jobs.append(
                            (
                                root_item_id,
                                None,
                                frozenset(((target_index, output_item_id),)),
                                job_token,
                                parallel_job_label(
                                    target,
                                    output_item_id,
                                    record,
                                ),
                            )
                        )
                else:
                    jobs = [
                        (
                            item_id,
                            None,
                            None,
                            (target_index, item_id, None),
                            parallel_job_label(target, item_id),
                        )
                        for item_id in items
                    ]
                if jobs:
                    jobs_by_target.append((target_index, tuple(jobs)))

        parallel_job_count = max(
            (len(jobs) for _target_index, jobs in jobs_by_target),
            default=0,
        )
        worker_limit = min(
            max(1, worker_limit),
            max(1, parallel_job_count),
        )

        if worker_limit > 1 and parallel_job_count > 1:
            # Длительности и общий M4B-план рассчитаны выше ровно один раз.
            # Каждое дочернее задание всё равно получает полный план: только
            # так независимо кодируемые части сохраняют общие N/T, сквозные
            # номера глав и уже проверенные выходные пути.
            parallel_cancel = threading.Event()
            progress_lock = threading.Lock()
            parallel_completed = 0
            parallel_active = {}

            def combined_cancelled():
                return parallel_cancel.is_set() or bool(
                    cancelled and cancelled()
                )

            def aggregate_subject(preferred_subject="", finished_token=None):
                active_values = tuple(
                    value
                    for token, value in parallel_active.items()
                    if token != finished_token
                )
                visible_subject = next(
                    iter(active_values),
                    str(preferred_subject or "").strip(),
                )
                return format_parallel_export_status(
                    parallel_completed,
                    total_units,
                    len(active_values),
                    visible_subject,
                )

            def report_parallel_progress(job_token, current, _total, subject):
                nonlocal parallel_completed
                if not progress_callback:
                    return
                try:
                    current_value = float(current)
                except (TypeError, ValueError, OverflowError):
                    current_value = 0.0
                with progress_lock:
                    if current_value == PROGRESS_STATUS_ONLY or current_value < 0:
                        progress_callback(
                            PROGRESS_STATUS_ONLY,
                            total_units,
                            aggregate_subject(subject),
                        )
                        return
                    # Дочерний обработчик имеет собственный локальный счётчик.
                    # Внешний счётчик фиксирует каждую успешно опубликованную
                    # единицу один раз и выдаёт callbacks строго в порядке 1..N.
                    if current_value.is_integer():
                        completed_subject = parallel_active.get(
                            job_token,
                            subject,
                        )
                        parallel_completed += 1
                        progress_callback(
                            parallel_completed,
                            total_units,
                            aggregate_subject(
                                completed_subject,
                                finished_token=(
                                    job_token if planned_records else None
                                ),
                            ),
                        )

            def run_child(
                target_index,
                item_id,
                part_filter,
                output_filter,
                job_token,
                job_label,
            ):
                if combined_cancelled():
                    raise InterruptedError("Сборка остановлена пользователем")
                if progress_callback:
                    with progress_lock:
                        parallel_active[job_token] = job_label
                        progress_callback(
                            PROGRESS_STATUS_ONLY,
                            total_units,
                            aggregate_subject(job_label),
                        )
                try:
                    return self._run_output_target_set(
                        (item_id,),
                        group_children,
                        export_groups,
                        runtime_export_files,
                        normalized_targets,
                        base_dir,
                        apply_fx=apply_fx,
                        default_effects=default_effects,
                        cancelled=combined_cancelled,
                        progress_callback=(
                            lambda current, total, subject: report_parallel_progress(
                                job_token, current, total, subject
                            )
                        ),
                        planned_records=planned_records,
                        settings_snapshot=runtime_config,
                        max_workers=1,
                        _reuse_planned_records=True,
                        _active_target_indices=(target_index,),
                        _m4b_job_filter=part_filter,
                        _file_job_filter=output_filter,
                        _prepared_records_by_target_item=(
                            records_by_target_item
                        ),
                    )
                finally:
                    if progress_callback:
                        with progress_lock:
                            parallel_active.pop(job_token, None)
                            progress_callback(
                                PROGRESS_STATUS_ONLY,
                                total_units,
                                aggregate_subject(),
                            )

            # Цели остаются последовательными. Внутри каждой цели пул получает
            # все независимые результаты: обычные верхнеуровневые элементы или
            # отдельные части M4B после окончательного авторазбиения.
            for target_index, target_jobs in jobs_by_target:
                first_error = None
                with concurrent.futures.ThreadPoolExecutor(
                    max_workers=min(worker_limit, len(target_jobs)),
                    thread_name_prefix="export-output",
                ) as executor:
                    futures = [
                        executor.submit(
                            run_child,
                            target_index,
                            item_id,
                            part_filter,
                            output_filter,
                            job_token,
                            job_label,
                        )
                        for (
                            item_id,
                            part_filter,
                            output_filter,
                            job_token,
                            job_label,
                        ) in target_jobs
                    ]
                    for future in concurrent.futures.as_completed(futures):
                        try:
                            future.result()
                        except Exception as exc:
                            if first_error is None:
                                first_error = exc
                                parallel_cancel.set()
                                for pending in futures:
                                    pending.cancel()
                if first_error is not None:
                    raise first_error
                if combined_cancelled():
                    raise InterruptedError("Сборка остановлена пользователем")
            return

        completed_units = 0
        effects = default_effects or {
            "speed": 1.0,
            "pitch": 1.0,
            "echo": False,
            "echo_delay": 300,
            "echo_decay": 0.3,
        }

        def build_tags(settings):
            result = {}
            for source_key, target_key in (
                ("title", "title"), ("artist", "artist"),
                ("album", "album"), ("album_artist", "album_artist"),
                ("genre", "genre"), ("composer", "composer"),
                ("year", "date"), ("language", "language"),
            ):
                if settings.get(source_key):
                    result[target_key] = settings[source_key]
            return result

        def build_m4b_tags(settings, fallback_album=""):
            """Формирует метаданные M4B со стабильным запасным значением альбома.

            Читатели M4B (в частности Apple Books) используют поле альбома для
            группировки частей аудиокниги. У сгруппированного экспорта уже есть
            естественное резервное значение — имя группы, тогда как у отдельного файла
            группы нет, поэтому используются его заголовок и, наконец, имя
            файла. Явные метаданные альбома всегда имеют приоритет; заменяется
            только пустое значение или значение из пробелов.
            """
            settings = dict(settings or {})
            tags = build_tags(settings)
            if str(tags.get("album") or "").strip():
                return tags

            candidates = [fallback_album, settings.get("title")]
            raw_path = settings.get("path")
            if raw_path:
                try:
                    candidates.append(Path(raw_path).stem)
                except (TypeError, ValueError, OSError):
                    pass
            for candidate in candidates:
                album = str(candidate or "").strip()
                if album:
                    tags["album"] = album
                    break
            return tags

        def inherited_file_settings(group, file_settings):
            result = normalize_export_file_record(file_settings)
            for key in (
                "artist", "album", "album_artist", "genre", "composer",
                "year", "language", "cover",
            ):
                if not result.get(key) and group.get(key):
                    result[key] = group[key]
            return result

        # Вручную собранное дерево экспорта может содержать несколько групп M4B,
        # являющихся томами одной книги. ``plan_m4b_parts`` нумерует каждую
        # группу локально, поэтому прямая передача ``part.number/part.total``
        # в FFmpeg дала бы ``1/1`` (или повторяющееся ``1/N``) для каждой группы.
        # Строим одну детерминированную последовательность по уже проверенному
        # плану. Эффективные альбом/исполнитель разрешаются по той же политике
        # наследования, что и ниже в фоновом обработчике. Непустой альбом — явный контракт
        # группировки; пустому альбому назначается частный ключ группы, чтобы
        # несвязанные проекты не объединялись лишь из-за совпавших запасных имён.
        m4b_volume_numbers = {}
        m4b_volume_entries = []
        # Метки глав используют отдельный счётчик, не связанный с метаданными
        # диска/дорожки MP4. Для подготовленных вручную групп явный общий альбом
        # означает, что группы относятся к одной книге; накапливаем нулевое
        # смещение глав для каждого тома этой последовательности. Группы без
        # явного альбома намеренно получают частный ключ и поэтому начинают
        # собственную глобальную нумерацию глав.
        m4b_chapter_offsets = {}
        m4b_chapter_counts = {}
        m4b_chapter_sequence_keys = {}
        needs_m4b_sequence_metadata = any(
            target.get("format") == "m4b"
            and (
                active_target_indices is None
                or target_index in active_target_indices
            )
            for target_index, target in enumerate(normalized_targets)
        )

        def canonical_target_index(value):
            """Использует одинаковую форму ключа для новых и переносимых планов.

            Обычные планировщики выдают целочисленные индексы целей, тогда как
            JSON/снимок сеанса может содержать значение как строку. Канонизация
            здесь согласует поиск смещения глав с циклом фонового обработчика
            ``enumerate(normalized_targets)`` ниже.
            """
            try:
                return int(value)
            except (TypeError, ValueError, OverflowError):
                return str(value or "")

        for record in (
            planned_records if needs_m4b_sequence_metadata else ()
        ):
            if record.get("kind") != "m4b":
                continue
            item_id = record.get("item_id")
            group = export_groups.get(item_id)
            if not isinstance(group, dict):
                # У отдельных файлов M4B нет ручной последовательности томов.
                # Сохраняем историческое поведение (без искусственной пары 1/1).
                continue
            children = tuple(group_children.get(item_id, ()))
            file_settings = [
                inherited_file_settings(group, dict(export_files[file_id]))
                for file_id in children
                if file_id in export_files
            ]
            tags_settings = dict(group)
            first_setting = file_settings[0] if file_settings else {}
            for key in (
                "artist", "album", "album_artist", "genre",
                "composer", "year", "language", "cover",
            ):
                if not tags_settings.get(key) and first_setting.get(key):
                    tags_settings[key] = first_setting[key]
            album = str(tags_settings.get("album") or "").strip()
            album_is_explicit = bool(album)
            if not album:
                album = str(group.get("name") or "Группа").strip()
            # В распространённых медиатеках альбом и исполнитель альбома не
            # зависят от регистра. Добавляем эффективного исполнителя вторым
            # компонентом, чтобы две книги с одинаковым названием альбома не
            # получили одну последовательность при разных авторах. Отсутствующий
            # исполнитель остаётся отдельным пустым значением и может быть явно
            # задан пользователем в тегах группы.
            album_artist = str(
                tags_settings.get("album_artist")
                or tags_settings.get("artist")
                or ""
            ).strip()
            if album_is_explicit:
                album_key = (
                    "album",
                    album.casefold(),
                    album_artist.casefold(),
                )
            else:
                # Не объединяем запасные имена из разных групп. Идентификатор
                # группы не записывается в метаданные, а лишь ограничивает
                # область внутренней карты нумерации.
                album_key = ("group", str(item_id))
            part = record.get("part")
            part_number = getattr(part, "number", None)
            if part_number is None:
                continue
            try:
                part_number = int(part_number)
            except (TypeError, ValueError, OverflowError):
                continue
            try:
                chapter_count_for_offset = len(part.chapters or ())
            except (AttributeError, TypeError):
                chapter_count_for_offset = 0
            if chapter_count_for_offset <= 0:
                try:
                    chapter_count_for_offset = max(
                        0,
                        int(part.chapter_end) - int(part.chapter_start) + 1,
                    )
                except (AttributeError, TypeError, ValueError, OverflowError):
                    chapter_count_for_offset = 0
            target_key = canonical_target_index(record.get("target_index"))
            record_key = (target_key, item_id, part_number)
            # Корректный планировщик выдаёт каждый ключ один раз. Сохраняем
            # первое значение, чтобы частично заполненный старый снимок оставался
            # детерминированным и поздний дубликат не сдвигал уже отрисованные метки.
            if record_key in m4b_chapter_sequence_keys:
                continue
            m4b_chapter_counts.setdefault(record_key, chapter_count_for_offset)
            m4b_chapter_sequence_keys.setdefault(
                record_key, (target_key, album_key)
            )
            m4b_volume_entries.append(
                (
                    album_key,
                    target_key,
                    item_id,
                    part_number,
                    group.get("source_volume_number") if part_number == 1 else None,
                    group.get("source_volume_total"),
                )
            )
        m4b_chapter_counters = {}
        m4b_chapter_sequence_totals = {}
        sequence_entries = []
        for (
            album_key,
            target_index,
            item_id,
            part_number,
            preferred_volume,
            source_volume_total,
        ) in m4b_volume_entries:
            sequence_key = (target_index, album_key)
            sequence_entries.append(
                (
                    sequence_key,
                    (target_index, item_id),
                    part_number,
                    preferred_volume,
                    source_volume_total,
                )
            )
            record_key = (target_index, item_id, part_number)
            m4b_chapter_offsets[record_key] = m4b_chapter_counters.get(
                sequence_key, 0
            )
            count = m4b_chapter_counts.get(record_key, 0)
            m4b_chapter_counters[sequence_key] = (
                m4b_chapter_counters.get(sequence_key, 0) + count
            )
            m4b_chapter_sequence_totals[sequence_key] = (
                m4b_chapter_sequence_totals.get(sequence_key, 0) + count
            )
        assigned_volumes = assign_m4b_volume_numbers(sequence_entries)
        for (item_key, local_part), (number, total) in assigned_volumes.items():
            target_index, item_id = item_key
            m4b_volume_numbers[(target_index, item_id, local_part)] = (
                number,
                total,
            )
        m4b_chapter_total_by_record = {
            record_key: m4b_chapter_sequence_totals.get(sequence_key, 0)
            for record_key, sequence_key in m4b_chapter_sequence_keys.items()
        }

        for target_index, target_data in enumerate(normalized_targets):
            if (
                active_target_indices is not None
                and target_index not in active_target_indices
            ):
                continue
            if cancelled and cancelled():
                raise InterruptedError("Сборка остановлена пользователем")
            target = normalize_output_target(target_data)
            fmt = target["format"]
            target_dir = Path(target["output_dir"]).expanduser()
            target_dir.mkdir(parents=True, exist_ok=True)
            selected_group_ids = [
                item_id for item_id in (items or ()) if item_id in export_groups
            ]
            group_positions = {
                item_id: position
                for position, item_id in enumerate(selected_group_ids, 1)
            }
            target_effects = target.get("effects") or effects
            use_fx = bool(target.get("apply_effects", apply_fx))
            speed = float(target_effects.get("speed", effects["speed"])) if use_fx else 1.0
            pitch = float(target_effects.get("pitch", effects["pitch"])) if use_fx else 1.0
            echo = bool(target_effects.get("echo", effects["echo"])) if use_fx else False
            echo_delay = int(target_effects.get("echo_delay", effects["echo_delay"]))
            echo_decay = float(target_effects.get("echo_decay", effects["echo_decay"]))
            bitrate = target.get("bitrate", "auto")
            if fmt == "m4b" and bitrate == "auto":
                bitrate = runtime_config.get("export_m4b_bitrate", "64k")
            sample_rate = target.get("sample_rate", "auto")
            channels = target.get("channels", "auto")

            if fmt == "m4b" and use_fx:
                # Временные метки глав описывают неизменённые исходные файлы.
                # ``speed``/``pitch``/``echo`` меняют длительность или временную шкалу, поэтому их
                # незаметное применение создало бы вводящие в заблуждение главы.
                if (
                    abs(speed - 1.0) > 1e-9
                    or abs(pitch - 1.0) > 1e-9
                    or echo
                ):
                    raise ValueError(
                        "Эффекты для M4B пока недоступны: отключите эффекты "
                        "для цели M4B, чтобы сохранить точные главы."
                    )
                # Старая цель всё ещё может содержать ``apply_effects=true`` с
                # нейтральными значениями. Для сэмплов это безвредно, но
                # каноническое состояние фонового обработчика должно всё равно указывать, что
                # эффекты M4B отключены, чтобы другие ветки случайно не применили их.
                use_fx = False

            def planned_for(item_id, *, kind=None, part_number=None):
                candidates = records_by_target_item.get((target_index, item_id), ())
                for record in candidates:
                    if kind is not None and record.get("kind") != kind:
                        continue
                    part = record.get("part")
                    if part_number is not None and (
                        part is None or getattr(part, "number", None) != part_number
                    ):
                        continue
                    return Path(record["path"])
                return None

            def emit_activity(subject, stage="сборка"):
                if progress_callback:
                    progress_callback(
                        PROGRESS_STATUS_ONLY,
                        total_units,
                        format_sequential_export_status(
                            completed_units,
                            total_units,
                            subject,
                            stage,
                        ),
                    )

            def emit_progress(subject):
                nonlocal completed_units
                completed_units += 1
                if progress_callback:
                    progress_callback(
                        completed_units,
                        total_units,
                        format_sequential_export_status(
                            completed_units,
                            total_units,
                            subject,
                        ),
                    )

            # ``_export_m4b_ffmpeg`` сообщает о проверках глав и сигналах
            # активности кодировщика, но ни одно из этих значений не является
            # надёжным процентом готовности финального результата. Оставляем
            # определённый индикатор на последнем *завершённом* результате и
            # используем отдельный маркер только для текста активности.
            # Подробное описание исходников остаётся в журнале. В интерфейсе
            # показывается только имя результата: длинный диапазон глав не
            # должен вытеснять счётчик общего прогресса.
            m4b_output_name = "M4B"

            def m4b_progress(current, total, text):
                """Публикует активность M4B, не перемещая индикатор прогресса."""
                if not progress_callback:
                    return
                stage = re.sub(
                    r"^(?:(?:M4B|FFmpeg)\s*:\s*)+",
                    "",
                    str(text or "").strip(),
                    flags=re.IGNORECASE,
                ).rstrip(" .…")
                if stage.casefold() == "готово":
                    return
                # Ячейка результата фиксируется ровно один раз через
                # ``emit_progress`` после успешного возврата FFmpeg. Это
                # предотвращает неопределённую анимацию и заметное дрожание,
                # вызванное множеством мелких проверок и сигналов обратного вызова.
                emit_activity(
                    m4b_output_name,
                    text or "M4B: сборка…",
                )

            for item_id in items:
                if cancelled and cancelled():
                    raise InterruptedError("Сборка остановлена пользователем")
                if item_id in export_groups:
                    group = dict(export_groups[item_id])
                    children = tuple(group_children.get(item_id, ()))
                    merge_group = output_target_merges_group(target, group)
                    if (
                        fmt != "m4b"
                        and merge_group
                        and file_job_filter is not None
                        and (target_index, item_id) not in file_job_filter
                    ):
                        continue
                    if (
                        fmt != "m4b"
                        and not merge_group
                        and file_job_filter is not None
                    ):
                        selected_children = {
                            file_id
                            for selected_target, file_id in file_job_filter
                            if selected_target == target_index
                        }
                        children = tuple(
                            file_id
                            for file_id in children
                            if file_id in selected_children
                        )
                    if not children:
                        continue
                    file_settings = [
                        inherited_file_settings(group, dict(export_files[file_id]))
                        for file_id in children
                    ]
                    for file_id, setting in zip(children, file_settings):
                        if file_id in duration_overrides:
                            setting["duration"] = duration_overrides[file_id]
                    sources = [setting["path"] for setting in file_settings]
                    source_ranges = [
                        setting
                        if setting.get("clip_start") is not None
                        or setting.get("clip_end") is not None
                        else None
                        for setting in file_settings
                    ]
                    group_name = sanitize_filename_component(
                        _template_basename(group.get("name"), fmt),
                        fallback="Группа",
                    )
                    if merge_group:
                        tags_settings = dict(group)
                        # Экспорт на уровне группы должен сохранять тот же
                        # контракт наследования метаданных, что и старый экспортёр:
                        # пустые поля группы берутся из первого исходного файла.
                        # Иначе экспорт Opus/M4B через цель мог бы молча потерять
                        # поля альбома и исполнителя, хотя исходные метаданные уже загружены в дерево.
                        first_setting = file_settings[0] if file_settings else {}
                        for key in (
                            "artist", "album", "album_artist", "genre",
                            "composer", "year", "language", "cover",
                        ):
                            if not tags_settings.get(key) and first_setting.get(key):
                                tags_settings[key] = first_setting[key]
                        if not tags_settings.get("title"):
                            tags_settings["title"] = group.get("name", group_name)
                        tags = build_tags(tags_settings)
                        if fmt == "m4b":
                            # Сгруппированный M4B — это том аудиокниги, а не
                            # безымянная коллекция исходных файлов. Если ни группа,
                            # ни её первый источник не задают тег альбома, используем
                            # имя группы, чтобы медиатеки (особенно Apple Books)
                            # хранили все части под одним альбомом. Явный альбом
                            # группы/файла сохраняет приоритет.
                            tags = build_m4b_tags(
                                tags_settings,
                                # Сохраняем удобное для чтения имя группы, если
                                # оно непусто, но для отсутствующего имени или
                                # имени из одних пробелов используем уже очищенный
                                # резервное имя.
                                fallback_album=(
                                    str(group.get("name") or "").strip()
                                    or group_name
                                ),
                            )
                            chapter_records = [
                                {
                                    "file_index": index,
                                    "title": effective_export_file_title(setting),
                                    "source_name": setting.get("source_name", ""),
                                    "source_title": setting.get("source_title", ""),
                                    "path": setting.get("path", ""),
                                    "duration": safe_duration(setting.get("duration", 0)),
                                }
                                for index, setting in enumerate(file_settings, 1)
                            ]
                            pause_ms = _normalized_pause_milliseconds(group.get("pause", 0))
                            # Синхронизируем второй проход планирования фонового обработчика с
                            # ``plan_export_target_paths`` выше. Планировщик предварительной проверки
                            # включает автоматическую политику для длинной книги
                            # при явном нулевом лимите после измерения всей группы.
                            # Ранее повторное использование только
                            # ``effective_m4b_duration_limit`` молча сворачивало
                            # запланированные части обратно в один файл длительностью
                            # более 24 часов во время кодирования.
                            requested_duration_limit = target.get(
                                "max_duration_seconds", 0
                            )
                            estimated_total = sum(
                                safe_duration(chapter.get("duration", 0))
                                for chapter in chapter_records
                            ) + max(0, len(chapter_records) - 1) * pause_ms / 1000.0
                            duration_limit = resolve_m4b_auto_duration_limit(
                                estimated_total,
                                requested_duration_limit,
                            )
                            parts = plan_m4b_parts(
                                chapter_records,
                                max_duration_seconds=duration_limit,
                                max_chapters=int(target.get("max_chapters", 0) or 0),
                                pause_seconds=pause_ms / 1000.0,
                            )
                            if not parts:
                                parts = (M4BPart(1, 1, 1, len(sources), 0, chapter_records),)
                            for part in parts:
                                job_key = (target_index, item_id, part.number)
                                if (
                                    m4b_job_filter is not None
                                    and job_key not in m4b_job_filter
                                ):
                                    continue
                                part_sources = sources[part.chapter_start - 1:part.chapter_end]
                                part_source_ranges = source_ranges[
                                    part.chapter_start - 1:part.chapter_end
                                ]
                                first = part.chapters[0] if part.chapters else {}
                                last = part.chapters[-1] if part.chapters else {}
                                volume_number, volume_total = m4b_volume_numbers.get(
                                    (target_index, item_id, part.number),
                                    (part.number, part.total),
                                )
                                context = {
                                    "book": group_name,
                                    "name": group_name,
                                    "group": group_name,
                                    "title": group_name,
                                    "source_name": group_name,
                                    "source_title": str(
                                        group.get("source_title") or group_name
                                    ),
                                    "filename": Path(
                                        str(
                                            group.get("source_path")
                                            or first.get("path")
                                            or ""
                                        )
                                    ).stem or group_name,
                                    "index": volume_number,
                                    "chapter": part.chapter_start,
                                    "chapter_count": len(chapter_records),
                                    "first_index": part.chapter_start,
                                    "last_index": part.chapter_end,
                                    "num": volume_number,
                                    "group_index": group_positions.get(item_id, 1),
                                    "file_index": part.chapter_start,
                                    "first": part.chapter_start,
                                    "last": part.chapter_end,
                                    "range": format_chapter_range(
                                        part.chapter_start,
                                        part.chapter_end,
                                        total_count=len(chapter_records),
                                    ),
                                    "first_name": first.get("title", ""),
                                    "last_name": last.get("title", ""),
                                    "part": volume_number,
                                    "volume": volume_number,
                                    "parts": volume_total,
                                    "_local_parts": part.total,
                                    "format": fmt,
                                    "profile": target.get("profile", ""),
                                    "ext": fmt,
                                    "author": group.get("artist", ""),
                                }
                                template = _effective_export_m4b_template(
                                    target.get("filename_template"),
                                    runtime_config.get(
                                        "export_m4b_template",
                                        DEFAULT_CONFIG["export_m4b_template"],
                                    ),
                                )
                                try:
                                    rendered = (
                                        render_m4b_part_template(
                                            template,
                                            context,
                                            TEMPLATE_FIELDS_OUTPUT,
                                        )
                                        if template
                                        else group_name
                                    )
                                except TemplateError as exc:
                                    raise ValueError(f"Шаблон M4B: {exc}") from exc
                                # Синхронизируем резервный путь фонового обработчика с
                                # чистым планировщиком предварительной проверки. Пользователь может
                                # указать расширение в шаблоне;
                                # добавляем его ровно один раз, даже если в устаревшем или
                                # частичном снимке нет запланированного пути.
                                rendered = _template_basename(rendered, fmt)
                                if _m4b_template_needs_part_suffix(
                                    template,
                                    context,
                                    TEMPLATE_FIELDS_OUTPUT,
                                ) or (
                                    not template
                                    and _m4b_context_has_multiple_parts(context)
                                ):
                                    rendered = _append_m4b_part_suffix(
                                        rendered,
                                        context,
                                        fallback=group_name,
                                    )
                                name = sanitize_filename_component(
                                    rendered, fallback=group_name
                                )
                                out_file = planned_for(
                                    item_id, kind="m4b", part_number=part.number
                                ) or target_dir / f"{name}.{fmt}"
                                m4b_output_name = Path(out_file).name
                                m4b_activity_subject = format_m4b_activity_subject(
                                    group_name,
                                    m4b_output_name,
                                    part_sources,
                                    chapter_start=part.chapter_start,
                                    chapter_end=part.chapter_end,
                                )
                                logging.info("Сборка M4B: %s", m4b_activity_subject)
                                emit_activity(m4b_output_name, "подготовка")
                                chapter_label_items = copy.deepcopy(
                                    part.chapters
                                )
                                chapter_sequence_key = (
                                    target_index,
                                    item_id,
                                    part.number,
                                )
                                chapter_offset = m4b_chapter_offsets.get(
                                    chapter_sequence_key,
                                    0,
                                )
                                # ``part.chapters`` содержит индексы относительно
                                # родительской группы (поэтому для каждого вручную созданного
                                # тома они снова начинаются с 1). Заменяем их порядковыми номерами
                                # общей последовательности альбома перед рендерингом;
                                # это сохраняет непрерывность ``global_index`` между
                                # группами и автоматически разделёнными частями, оставляя
                                # ``volume_index`` локальным для этого выходного файла.
                                for local_offset, chapter_item in enumerate(
                                    chapter_label_items
                                ):
                                    if isinstance(chapter_item, dict):
                                        chapter_item["global_index"] = (
                                            chapter_offset + local_offset + 1
                                        )
                                chapter_count_for_labels = (
                                    m4b_chapter_total_by_record.get(
                                        chapter_sequence_key,
                                        len(chapter_records),
                                    )
                                )
                                rendered_chapters = render_m4b_chapter_titles(
                                    chapter_label_items,
                                    target.get("chapter_title_template", ""),
                                    book=group_name,
                                    group=group_name,
                                    # Для нескольких групп одного альбома
                                    # ``part`` — номер итогового тома книги, а
                                    # не локальная часть каждой группы (которая
                                    # почти всегда снова равна 1).
                                    part=volume_number,
                                    parts=volume_total,
                                    chapter_start=part.chapter_start,
                                    chapter_count=chapter_count_for_labels,
                                    profile=target.get("profile", ""),
                                    author=group.get("artist", ""),
                                    global_start=1,
                                    group_index=group_positions.get(item_id, 1),
                                )
                                _export_m4b_ffmpeg(
                                    part_sources,
                                    out_file,
                                    chapters=rendered_chapters,
                                    bitrate=bitrate,
                                    sample_rate=(48000 if sample_rate == "auto" else int(sample_rate)),
                                    channels=(1 if channels in {"auto", "mono"} else 2),
                                    pause_ms=pause_ms,
                                    speed=speed,
                                    pitch=pitch,
                                    echo=echo,
                                    echo_delay=echo_delay,
                                    echo_decay=echo_decay,
                                    tags=tags,
                                    disk_number=volume_number,
                                    disk_total=volume_total,
                                    track_number=volume_number,
                                    track_total=volume_total,
                                    include_track_metadata=_config_bool(
                                        target.get("include_track_metadata"),
                                        default=True,
                                    ),
                                    cover=group.get("cover") or file_settings[0].get("cover"),
                                    cancelled=cancelled,
                                    source_ranges=part_source_ranges,
                                    **(
                                        {"progress_callback": m4b_progress}
                                        if progress_callback is not None
                                        else {}
                                    ),
                                )
                                # Фиксируем единицу только после успешной записи полной
                                # части M4B. Внутренние проверки глав и состояния обновляют текст
                                # статуса, но намеренно не двигают индикатор.
                                emit_progress(m4b_output_name)
                        else:
                            out_file = planned_for(item_id, kind="group") or target_dir / f"{group_name}.{fmt}"
                            emit_activity(Path(out_file).name)
                            _export_merged_audio_ffmpeg(
                                sources,
                                out_file,
                                output_format=fmt,
                                bitrate=None if bitrate == "auto" else bitrate,
                                bitrate_mode=bitrate,
                                sample_rate=sample_rate,
                                channels=channels,
                                pause_ms=_normalized_pause_milliseconds(
                                    group.get("pause", 0)
                                ),
                                speed=speed,
                                pitch=pitch,
                                echo=echo,
                                echo_delay=echo_delay,
                                echo_decay=echo_decay,
                                tags=tags,
                                cover=group.get("cover") or file_settings[0].get("cover"),
                                cancelled=cancelled,
                                source_ranges=source_ranges,
                            )
                            emit_progress(Path(out_file).name)
                    else:
                        file_target_dir = (
                            target_dir / group_name
                            if target.get("scope") == "group_subfolder"
                            or effective_group_subfolder(
                                merge_group, group.get("subfolder")
                            )
                            else target_dir
                        )
                        file_target_dir.mkdir(parents=True, exist_ok=True)
                        for file_index, (file_id, setting) in enumerate(
                            zip(children, file_settings),
                            1,
                        ):
                            if (
                                fmt != "m4b"
                                and file_job_filter is not None
                                and (target_index, file_id) not in file_job_filter
                            ):
                                continue
                            name = sanitize_filename_component(
                                setting.get("title"), fallback=Path(setting["path"]).stem
                            )
                            out_file = planned_for(item_id=file_id, kind="file") or file_target_dir / f"{name}.{fmt}"
                            if fmt == "m4b":
                                m4b_output_name = Path(out_file).name
                                m4b_activity_subject = format_m4b_activity_subject(
                                    group_name,
                                    m4b_output_name,
                                    (setting.get("path", ""),),
                                    chapter_start=file_index,
                                    chapter_end=file_index,
                                )
                                logging.info("Сборка M4B: %s", m4b_activity_subject)
                                emit_activity(m4b_output_name, "подготовка")
                                single_chapters = render_m4b_chapter_titles(
                                    [{
                                        "title": effective_export_file_title(setting),
                                        "source_name": setting.get("source_name", ""),
                                        "source_title": setting.get("source_title", ""),
                                        "path": setting.get("path", ""),
                                        "duration": setting.get("duration", 0),
                                    }],
                                    target.get("chapter_title_template", ""),
                                    book=group_name,
                                    group=group_name,
                                    part=1,
                                    parts=1,
                                    chapter_start=file_index,
                                    chapter_count=len(children),
                                    profile=target.get("profile", ""),
                                    author=setting.get("artist", ""),
                                    global_start=1,
                                )
                                _export_m4b_ffmpeg(
                                    [setting["path"]], out_file,
                                    chapters=single_chapters,
                                    bitrate=bitrate,
                                    sample_rate=(48000 if sample_rate == "auto" else int(sample_rate)),
                                    channels=(1 if channels in {"auto", "mono"} else 2),
                                    tags=build_m4b_tags(
                                        setting, fallback_album=group_name
                                    ),
                                    cover=setting.get("cover"),
                                    include_track_metadata=_config_bool(
                                        target.get("include_track_metadata"),
                                        default=True,
                                    ),
                                    speed=speed, pitch=pitch, echo=echo,
                                    echo_delay=echo_delay, echo_decay=echo_decay,
                                    cancelled=cancelled,
                                    source_ranges=(setting,),
                                    **(
                                        {"progress_callback": m4b_progress}
                                        if progress_callback is not None
                                        else {}
                                    ),
                                )
                            else:
                                emit_activity(Path(out_file).name)
                                _export_single_audio_ffmpeg(
                                    setting["path"], out_file,
                                    output_format=fmt,
                                    bitrate=None if bitrate == "auto" else bitrate,
                                    bitrate_mode=bitrate,
                                    sample_rate=sample_rate, channels=channels,
                                    speed=speed, pitch=pitch, echo=echo,
                                    echo_delay=echo_delay, echo_decay=echo_decay,
                                    tags=build_tags(setting), cover=setting.get("cover"),
                                    clip_start=setting.get("clip_start"),
                                    clip_end=setting.get("clip_end"),
                                    cancelled=cancelled,
                            )
                            emit_progress(Path(out_file).name)
                elif item_id in export_files:
                    if (
                        fmt != "m4b"
                        and file_job_filter is not None
                        and (target_index, item_id) not in file_job_filter
                    ):
                        continue
                    if (
                        fmt == "m4b"
                        and m4b_job_filter is not None
                        and (target_index, item_id, None) not in m4b_job_filter
                    ):
                        continue
                    setting = normalize_export_file_record(export_files[item_id])
                    if item_id in duration_overrides:
                        setting["duration"] = duration_overrides[item_id]
                    name = sanitize_filename_component(
                        setting.get("title"), fallback=Path(setting["path"]).stem
                    )
                    out_file = planned_for(item_id, kind="file") or target_dir / f"{name}.{fmt}"
                    if fmt == "m4b":
                        m4b_output_name = Path(out_file).name
                        m4b_activity_subject = format_m4b_activity_subject(
                            "Отдельный файл",
                            m4b_output_name,
                            (setting.get("path", ""),),
                            chapter_start=1,
                            chapter_end=1,
                        )
                        logging.info("Сборка M4B: %s", m4b_activity_subject)
                        emit_activity(m4b_output_name, "подготовка")
                        single_chapters = render_m4b_chapter_titles(
                            [{
                                "title": effective_export_file_title(setting),
                                "source_name": setting.get("source_name", ""),
                                "source_title": setting.get("source_title", ""),
                                "path": setting.get("path", ""),
                                "duration": setting.get("duration", 0),
                            }],
                            target.get("chapter_title_template", ""),
                            book=name,
                            group=name,
                            part=1,
                            parts=1,
                            chapter_start=1,
                            chapter_count=1,
                            profile=target.get("profile", ""),
                            author=setting.get("artist", ""),
                            global_start=1,
                        )
                        _export_m4b_ffmpeg(
                            [setting["path"]], out_file,
                            chapters=single_chapters,
                            bitrate=bitrate,
                            sample_rate=(48000 if sample_rate == "auto" else int(sample_rate)),
                            channels=(1 if channels in {"auto", "mono"} else 2),
                            tags=build_m4b_tags(setting), cover=setting.get("cover"),
                            include_track_metadata=_config_bool(
                                target.get("include_track_metadata"), default=True
                            ),
                            speed=speed, pitch=pitch, echo=echo,
                            echo_delay=echo_delay, echo_decay=echo_decay,
                            cancelled=cancelled,
                            source_ranges=(setting,),
                            **(
                                {"progress_callback": m4b_progress}
                                if progress_callback is not None
                                else {}
                            ),
                        )
                    else:
                        emit_activity(Path(out_file).name)
                        _export_single_audio_ffmpeg(
                            setting["path"], out_file,
                            output_format=fmt,
                            bitrate=None if bitrate == "auto" else bitrate,
                            bitrate_mode=bitrate,
                            sample_rate=sample_rate, channels=channels,
                            speed=speed, pitch=pitch, echo=echo,
                            echo_delay=echo_delay, echo_decay=echo_decay,
                            tags=build_tags(setting), cover=setting.get("cover"),
                            clip_start=setting.get("clip_start"),
                            clip_end=setting.get("clip_end"),
                            cancelled=cancelled,
                        )
                    emit_progress(Path(out_file).name)

    def start_export_process(self):
        if getattr(self, "_export_running", False) or getattr(self, "_export_lock", False):
            return
        items = self.export_tree.get_children()
        if not items:
            self._show_warning("Пусто", "Список пуст. Добавьте аудиофайлы или группы.")
            return

        has_any_files = False
        for item in items:
            if item in self.export_files:
                has_any_files = True
                break
            elif item in self.export_groups and len(self.export_tree.get_children(item)) > 0:
                has_any_files = True
                break

        if not has_any_files:
            self._show_warning("Нет файлов", "Добавьте аудиофайлы перед началом сборки.")
            return

        # В режиме «Только теги» каталог вывода не требуется.
        tags_only = self.export_tags_only_var.get()
        if tags_only and any(
            data.get("clip_start") is not None
            or data.get("clip_end") is not None
            for data in self.export_files.values()
            if isinstance(data, dict)
        ):
            self._show_warning(
                "Виртуальные главы M4B",
                "Обновление тегов в исходных файлах недоступно для виртуальных "
                "глав M4B: несколько элементов указывают на один контейнер. "
                "Выберите выходной формат и создайте отдельные файлы.",
            )
            return
        out_dir_str = self.export_outdir_var.get().strip()

        # В наборе с несколькими целями общий каталог необязателен, если у каждой
        # цели указан собственный каталог. Определяем/запрашиваем его только после
        # чтения набора целей ниже; это исключает диалог в допустимом случае.
        out_dir = Path(out_dir_str).expanduser() if out_dir_str else None

        # Все источники должны существовать до заморозки интерфейса. Иначе сборка
        # могла закончиться частичным результатом лишь потому, что один файл
        # был перемещён после добавления в дерево.
        missing_sources = [
            data.get("path", "")
            for data in self.export_files.values()
            if not data.get("path") or not Path(data["path"]).is_file()
        ]
        if missing_sources:
            preview = "\n".join(str(path) for path in missing_sources[:5])
            suffix = "\n…" if len(missing_sources) > 5 else ""
            self._show_error(
                "Нет исходных файлов",
                f"Не найдено файлов: {len(missing_sources)}\n\n{preview}{suffix}",
            )
            return

        # Сначала читаем явный набор выходных данных, не трогая компактные поля.
        # Набор целей содержит собственные неизменяемые снимки профилей, поэтому
        # незавершённое разовое значение в компактной панели не должно мешать
        # запуску полностью корректного экспорта MP3/Opus/M4A/M4B. Действие «Только
        # теги» намеренно обходит этот набор: оно обновляет метаданные источника
        # и не должно зависеть от выходного профиля или назначения.
        raw_output_targets = tuple(
            target
            for target in getattr(self, "export_targets", ())
            if isinstance(target, (dict, OutputTarget))
        )
        if tags_only:
            output_targets = []
        else:
            try:
                output_targets = [
                    normalize_output_target(target)
                    for target in raw_output_targets
                    if (
                        _config_bool(target.get("enabled"), default=True)
                        if isinstance(target, dict)
                        else _config_bool(target.enabled, default=True)
                    )
                ]
            except (TypeError, ValueError) as exc:
                self._show_error("Некорректный набор выходов", str(exc))
                return
            if raw_output_targets and not output_targets:
                # Не следует молча возвращаться к устаревшему компактному экспортёру:
                # импортированный/сохранённый набор, в котором отключены все строки, —
                # явный выбор пользователя и требует понятной диагностики.
                self._show_error(
                    "Нет активных целей",
                    "В наборе выходов все цели отключены. "
                    "Включите хотя бы один формат перед сборкой.",
                )
                return
        has_target_set = bool(output_targets)
        explicit_target_set = has_target_set

        # Настройки и интерфейс обычно переносят устаревшее одиночное переопределение сразу
        # после загрузки. Ещё раз нормализуем его на границе операции для
        # интеграций, которые напрямую присваивают ``self.export_targets``: единственная
        # цель всегда должна следовать общей папке, введённой на этой вкладке.
        if output_targets:
            directory_diagnostic = output_target_directory_diagnostics(
                output_targets,
                out_dir if out_dir_str else "",
                base_dir=out_dir if out_dir is not None else None,
            )
            if directory_diagnostic.get("single_mismatch"):
                explicit_dir = directory_diagnostic["explicit"][0]
                logging.info(
                    "Старый отдельный каталог единственной цели %s "
                    "проигнорирован; все группы будут сохранены в общую "
                    "папку %s.",
                    explicit_dir,
                    directory_diagnostic.get("common") or "(не задана)",
                )
            normalized_output_set = list(
                normalize_output_target_directories(raw_output_targets)
            )
            output_targets = [
                target
                for target in normalized_output_set
                if _config_bool(target.get("enabled", True), default=True)
            ]
            # Сохраняем согласованность снимка в памяти и его сводки с
            # фактическим планом, не отбрасывая временно отключённые строки;
            # настройки сохраняются обычным путём.
            self.export_targets = copy.deepcopy(normalized_output_set)
            self.config["export_targets"] = copy.deepcopy(
                normalized_output_set
            )

        # Все значения Tk и структура дерева снимаются до запуска потока.
        # В фоне используются только обычные Python-объекты.
        apply_fx = bool(self.export_apply_fx_var.get())
        try:
            if apply_fx and not tags_only:
                sp = float(self.exp_speed_var.get())
                pt = float(self.exp_pitch_var.get())
                ec = bool(self.exp_echo_var.get())
                ed = int(self.exp_delay_var.get())
                ey = float(self.exp_decay_var.get())
            else:
                sp, pt, ec, ed, ey = 1.0, 1.0, False, 300, 0.3
            if not all(math.isfinite(value) for value in (sp, pt, ey)):
                raise ValueError("эффекты должны быть конечными числами")
        except (TypeError, ValueError, OverflowError) as exc:
            if has_target_set and not tags_only:
                # Строки целей содержат собственные эффекты. Оставляем компактный
                # резервный вариант нейтральным, если эти необязательные поля редактируются
                # не полностью.
                logging.warning(
                    "Быстрые эффекты экспорта не прочитаны; используется "
                    "профиль каждой цели: %s", exc,
                )
                sp, pt, ec, ed, ey = 1.0, 1.0, False, 300, 0.3
            else:
                self._show_error(
                    "Некорректные эффекты",
                    f"Проверьте значения скорости, тона и эха:\n\n{exc}",
                )
                return

        fmt = self.export_fmt_var.get().strip().lower()
        bitrate = self.export_bitrate_var.get().strip().lower()
        sample_rate = self.export_sample_rate_var.get().strip().lower()
        channels = self.export_channels_var.get().strip().lower()
        # Эти четыре значения используются только устаревшим компактным экспортёром. Явный
        # набор выходных данных проверяется отдельно ниже — с профилем и форматом каждой строки.
        if not has_target_set and not tags_only:
            if fmt not in {"mp3", "wav", "ogg", "opus", "m4a", "m4b"}:
                self._show_error("Ошибка", "Выбран неподдерживаемый формат экспорта.")
                return
            if bitrate != "auto" and not re.fullmatch(r"[1-9]\d*k", bitrate):
                self._show_error("Ошибка", "Некорректный битрейт экспорта.")
                return
            if sample_rate != "auto" and sample_rate not in {
                "8000", "12000", "16000", "22050", "24000", "32000",
                "44100", "48000", "88200", "96000"
            }:
                self._show_error("Ошибка", "Некорректная частота экспорта.")
                return
            if channels not in {"auto", "mono", "stereo"}:
                self._show_error("Ошибка", "Некорректный режим каналов экспорта.")
                return
        group_children = {
            group_id: tuple(self.export_tree.get_children(group_id))
            for group_id in self.export_groups
        }
        export_groups = {
            group_id: settings.copy()
            for group_id, settings in self.export_groups.items()
        }
        export_files = {
            file_id: settings.copy()
            for file_id, settings in self.export_files.items()
        }
        unknown_children = [
            child_id
            for group_id, children in group_children.items()
            for child_id in children
            if child_id not in export_files
        ]
        unknown_roots = [
            item_id
            for item_id in items
            if item_id not in export_groups and item_id not in export_files
        ]
        if unknown_children or unknown_roots:
            unknown_ids = tuple(dict.fromkeys((*unknown_roots, *unknown_children)))
            preview = ", ".join(str(item_id) for item_id in unknown_ids[:5])
            suffix = ", …" if len(unknown_ids) > 5 else ""
            logging.error(
                "Экспорт отменён: дерево содержит неизвестные элементы %s%s",
                preview,
                suffix,
            )
            self._show_error(
                "Структура списка повреждена",
                "Некоторые элементы дерева потеряли внутренние настройки. "
                "Очистите список и добавьте исходные файлы повторно.\n\n"
                f"Элементы: {preview}{suffix}",
            )
            return

        needs_common_dir = (
            not output_targets
            or any(not str(target.get("output_dir", "")).strip() for target in output_targets)
        )
        if not tags_only and not out_dir_str and needs_common_dir:
            self._show_warning(
                "Папка не выбрана",
                "Пожалуйста, укажите папку для сохранения результатов экспорта.",
            )
            chosen = filedialog.askdirectory(
                initialdir=resolve_dialog_initial_dir(
                    self.config.get("export_dir", ""),
                    self.config.get("last_browse_dir", ""),
                    BASE_DIR,
                )
            )
            if chosen:
                self.export_outdir_var.set(chosen)
                out_dir_str = chosen
                out_dir = Path(chosen).expanduser()
                self.config["export_dir"] = chosen
                self.save_settings()
            else:
                return
        # Явным каталогам целей не нужен общий каталог, но стабильная база всё же
        # передаётся чистому планировщику для относительных путей.
        if out_dir is None and not tags_only:
            out_dir = Path(BASE_DIR)
        if out_dir is not None and not tags_only and needs_common_dir:
            try:
                out_dir.mkdir(parents=True, exist_ok=True)
            except OSError as exc:
                logging.error("Не удалось создать папку экспорта %s: %s", out_dir, exc)
                self._show_error(
                    "Ошибка папки",
                    f"Не удалось создать папку экспорта:\n{out_dir}\n\n{exc}",
                )
                return
        if tags_only:
            # Эти значения никогда не используются обработчиком обновления тегов на месте. Оставляем
            # обычные значения по умолчанию, чтобы старую ветку было проще понимать,
            # даже если отключённое компактное поле содержит недописанный
            # текст из предыдущего сеанса.
            m4b_template = DEFAULT_CONFIG["export_m4b_template"]
            m4b_max_duration_seconds = (
                float(DEFAULT_CONFIG["export_m4b_max_duration_hours"]) * 3600
            )
            m4b_max_chapters = int(DEFAULT_CONFIG["export_m4b_max_chapters"])
        else:
            try:
                m4b_template = self.export_m4b_template_var.get().strip()
                raw_m4b_hours = float(self.export_m4b_hours_var.get() or 0)
                raw_m4b_chapters = int(self.export_m4b_chapters_var.get() or 0)
                if not math.isfinite(raw_m4b_hours) or raw_m4b_hours < 0:
                    raise ValueError(
                        "лимит часов должен быть конечным и неотрицательным"
                    )
                if raw_m4b_chapters < 0:
                    raise ValueError("число глав не может быть отрицательным")
                m4b_max_duration_seconds = raw_m4b_hours * 3600
                m4b_max_chapters = raw_m4b_chapters
            except (TypeError, ValueError, OverflowError) as exc:
                if has_target_set:
                    # Явные строки целей уже содержат собственные лимиты и
                    # снимки шаблонов. Частично отредактированная компактная строка M4B не должна
                    # блокировать независимые цели.
                    logging.warning(
                        "Быстрые параметры M4B не прочитаны; используется "
                        "снимок каждой цели: %s", exc,
                    )
                    # Некорректное поле длительности не должно возрождать
                    # исторический шаблон диапазона после того, как пользователь намеренно
                    # очистил поле имени файла. Сохраняем последнее значение интерфейса,
                    # если его можно прочитать; используем сохранённые настройки
                    # только если сама переменная Tk недоступна.
                    try:
                        m4b_template = str(
                            self.export_m4b_template_var.get() or ""
                        ).strip()
                    except (AttributeError, tk.TclError, TypeError, ValueError):
                        m4b_template = str(
                            self.config.get(
                                "export_m4b_template",
                                DEFAULT_CONFIG["export_m4b_template"],
                            )
                            or ""
                        ).strip()
                    m4b_max_duration_seconds = (
                        float(DEFAULT_CONFIG["export_m4b_max_duration_hours"]) * 3600
                    )
                    m4b_max_chapters = int(
                        DEFAULT_CONFIG["export_m4b_max_chapters"]
                    )
                else:
                    self._show_error(
                        "Некорректные параметры M4B",
                        f"Проверьте лимит часов и число глав:\n\n{exc}",
                    )
                    return
        # Фиксируем все резервные значения M4B, используемые обработчиком целей. Вкладка
        # настроек остаётся редактируемой во время экспорта, но эти изменения должны
        # влиять только на следующий запуск, а не на уже частично спланированный текущий.
        export_runtime_config = copy.deepcopy(self.config)
        export_runtime_config.update(
            {
                "export_m4b_template": m4b_template,
                "export_m4b_max_duration_hours": (
                    m4b_max_duration_seconds / 3600.0
                ),
                "export_m4b_max_chapters": m4b_max_chapters,
                "export_parallel_enabled": _config_bool(
                    self.export_parallel_var.get()
                    if hasattr(self, "export_parallel_var")
                    else self.config.get("export_parallel_enabled", False),
                    default=False,
                ),
            }
        )
        try:
            export_runtime_config["export_m4b_bitrate"] = str(
                self.export_m4b_bitrate_var.get()
            ).strip().lower()
        except (AttributeError, tk.TclError, TypeError, ValueError):
            export_runtime_config["export_m4b_bitrate"] = str(
                self.config.get("export_m4b_bitrate", "64k")
            ).strip().lower()
        # Пустой сохранённый набор означает один быстрый формат из основной
        # панели. Представляем его обычной целью только в снимке запуска: так
        # одиночный режим получает тот же планировщик и параллельную обработку
        # независимых групп, не превращаясь в сохранённый пользовательский набор.
        if not tags_only and not output_targets:
            try:
                output_targets = (
                    compact_export_output_target(
                        output_format=fmt,
                        bitrate=bitrate,
                        sample_rate=sample_rate,
                        channels=channels,
                        apply_effects=apply_fx,
                        effects={
                            "speed": sp,
                            "pitch": pt,
                            "echo": ec,
                            "echo_delay": ed,
                            "echo_decay": ey,
                        },
                        m4b_bitrate=export_runtime_config[
                            "export_m4b_bitrate"
                        ],
                        m4b_max_duration_seconds=m4b_max_duration_seconds,
                        m4b_max_chapters=m4b_max_chapters,
                    ),
                )
            except (TypeError, ValueError, OverflowError) as exc:
                self._show_error(
                    "Некорректные параметры вывода",
                    f"Проверьте быстрые параметры сборки:\n\n{exc}",
                )
                return
        # И явно настроенный набор, и временная быстрая цель проходят через
        # общий обработчик. Режим изменения исходных тегов остаётся отдельным:
        # он не создаёт выходные файлы и не должен менять порядок записей.
        if output_targets:
            try:
                planned_target_records = plan_export_target_paths(
                    items,
                    group_children,
                    export_groups,
                    export_files,
                    output_targets,
                    out_dir,
                    m4b_template=m4b_template,
                    m4b_max_duration_seconds=m4b_max_duration_seconds,
                    m4b_max_chapters=m4b_max_chapters,
                )
            except (TypeError, ValueError, TemplateError) as exc:
                self._show_error(
                    "Невозможно спланировать набор",
                    f"Проверьте шаблоны и названия выходных файлов:\n\n{exc}",
                )
                return
            if not planned_target_records:
                self._show_warning(
                    "Пустой набор", "Выбранные цели не содержат элементов для экспорта."
                )
                return
            try:
                validate_export_output_paths(
                    (record["path"] for record in planned_target_records),
                    (
                        settings.get("path", "")
                        for settings in export_files.values()
                    ),
                )
            except ValueError as exc:
                self._show_error(
                    "Конфликт выходных файлов",
                    f"Исправьте пути или шаблоны перед сборкой:\n\n{exc}",
                )
                return
            # Сохраняем в снимке фонового обработчика точные каталоги, выбранные планировщиком
            # (включая автоматические подкаталоги для каждого формата).
            output_targets = tuple(
                record_target
                for record_target in {
                    id(record["target"]): record["target"]
                    for record in planned_target_records
                }.values()
            )
            target_directories = tuple(
                dict.fromkeys(
                    str(Path(target.get("output_dir", "")).expanduser())
                    for target in output_targets
                    if str(target.get("output_dir", "")).strip()
                )
            )
            if len(target_directories) == 1:
                target_location_text = f"Сохранено в: {target_directories[0]}"
            elif target_directories:
                preview = "\n".join(target_directories[:8])
                suffix = "\n…" if len(target_directories) > 8 else ""
                target_location_text = (
                    "Результаты сохранены в каталоги:\n" + preview + suffix
                )
            else:
                target_location_text = f"Сохранено в: {out_dir}"
            logging.info(
                "Набор выходов запланирован (%d файлов): %s",
                len(planned_target_records),
                "; ".join(
                    f"{str(target.get('format', '')).upper()} → "
                    f"{str(Path(target.get('output_dir') or out_dir).expanduser())}"
                    for target in output_targets
                ),
            )
            self.save_settings()
            self._set_export_running_state(True)
            self._set_export_progress_indeterminate(False)
            self.export_progress["value"] = 0
            self.is_export_stopped = False
            target_effects = {
                "speed": sp,
                "pitch": pt,
                "echo": ec,
                "echo_delay": ed,
                "echo_decay": ey,
            }

            def run_target_set():
                outcome = "running"
                try:
                    def report_progress(current, total, subject):
                        try:
                            current_value = float(current)
                        except (TypeError, ValueError, OverflowError):
                            current_value = 0.0
                        status_only = current_value == PROGRESS_STATUS_ONLY
                        indeterminate = current_value < 0 and not status_only
                        if status_only:
                            # Внутренние обратные вызовы проверки и состояния M4B несут
                            # полезный текст, но не достоверный процент. Оставляем индикатор
                            # на последнем завершённом результате; меняется только
                            # подпись активности. Это намеренно отдельное служебное значение от ``-1``,
                            # чтобы интеграции, которым всё ещё нужна неопределённая анимация,
                            # сохраняли историческое поведение.
                            self._post_to_ui(
                                self._set_export_progress_indeterminate, False
                            )
                        elif indeterminate:
                            self._post_to_ui(
                                self._set_export_progress_indeterminate, True
                            )
                        else:
                            # Определённое обновление также останавливает прежнюю анимацию M4B
                            # перед установкой абсолютного значения.
                            # Дробные значения — диагностические подэлементы (например,
                            # проверка главы), а не завершённые выходные
                            # файлы. Игнорируем их, чтобы индикатор двигался только
                            # после того, как ``emit_progress`` зафиксирует файл.
                            try:
                                is_fractional = not current_value.is_integer()
                            except AttributeError:
                                is_fractional = False
                            self._post_to_ui(
                                self._set_export_progress_indeterminate, False
                            )
                            if not is_fractional:
                                self._post_to_ui(
                                    self.export_progress.configure,
                                    maximum=max(1, total),
                                    value=int(current_value),
                                )
                        self._post_export_activity_status(
                            "Экспорт", subject, "warning"
                        )

                    self._run_output_target_set(
                        items,
                        group_children,
                        export_groups,
                        export_files,
                        output_targets,
                        out_dir,
                        apply_fx=apply_fx,
                        default_effects=target_effects,
                        cancelled=lambda: self.is_export_stopped,
                        progress_callback=report_progress,
                        planned_records=planned_target_records,
                        settings_snapshot=export_runtime_config,
                        max_workers=(
                            export_runtime_config.get("max_parallel_encodes", 0)
                            if _config_bool(
                                export_runtime_config.get(
                                    "export_parallel_enabled", False
                                ),
                                default=False,
                            )
                            else 1
                        ),
                    )
                    if self.is_export_stopped:
                        outcome = "stopped"
                        self._post_export_status("Сборка прервана!", "warning")
                        self._post_to_ui(
                            self._show_warning,
                            "Остановлено",
                            "Процесс сборки был прерван пользователем.",
                        )
                    else:
                        outcome = "success"
                        self._post_export_status("Готово!", "success")
                        completion_text = (
                            "Набор форматов собран."
                            if explicit_target_set
                            else "Сборка успешно завершена."
                        )
                        self._post_to_ui(
                            self._show_info,
                            "Успех",
                            completion_text + "\n" + target_location_text,
                        )
                except InterruptedError:
                    outcome = "stopped"
                    self.is_export_stopped = True
                    self._post_export_status("Сборка прервана!", "warning")
                    self._post_to_ui(
                        self._show_warning,
                        "Остановлено",
                        "Процесс сборки был прерван пользователем.",
                    )
                except Exception as exc:
                    outcome = "error"
                    logging.exception("Ошибка набора выходных форматов")
                    self._post_export_status("Ошибка!", "error")
                    self._post_to_ui(
                        self._show_error,
                        "Ошибка",
                        f"Произошла ошибка при сборке набора:\n{exc}",
                    )
                finally:
                    self._post_to_ui(self._finish_export_process_ui, outcome)

            self._export_thread = threading.Thread(
                target=run_target_set, daemon=True
            )
            try:
                self._export_thread.start()
            except Exception as exc:
                self._export_thread = None
                self._set_export_running_state(False)
                self._set_export_status("Ошибка запуска сборки.", "error")
                logging.exception("Не удалось запустить набор выходов")
                self._show_error("Ошибка", f"Не удалось запустить сборку:\n{exc}")
            return

        if not tags_only:
            planned_outputs = []
            for item_id in items:
                if item_id in export_groups:
                    group = export_groups[item_id]
                    group_name = sanitize_filename_component(
                        _template_basename(group.get("name"), fmt),
                        fallback="Группа",
                    )
                    children = group_children.get(item_id, ())
                    # Пустая группа не создаёт файл в фоновом обработчике, значит и
                    # предварительная проверка не должна резервировать для неё выходное имя.
                    if not children:
                        continue
                    if group.get("merge"):
                        planned_outputs.append(out_dir / f"{group_name}.{fmt}")
                    else:
                        target = (
                            out_dir / group_name
                            if effective_group_subfolder(
                                group.get("merge"), group.get("subfolder")
                            )
                            else out_dir
                        )
                        for file_id in children:
                            source = export_files[file_id]
                            name = sanitize_filename_component(
                                _template_basename(source.get("title"), fmt),
                                fallback=Path(source["path"]).stem,
                            )
                            planned_outputs.append(target / f"{name}.{fmt}")
                elif item_id in export_files:
                    source = export_files[item_id]
                    name = sanitize_filename_component(
                        _template_basename(source.get("title"), fmt),
                        fallback=Path(source["path"]).stem,
                    )
                    planned_outputs.append(out_dir / f"{name}.{fmt}")

            duplicates = duplicate_paths(planned_outputs)
            if duplicates:
                preview = "\n".join(duplicates[:5])
                self._show_error(
                    "Совпадающие имена",
                    "Несколько элементов будут записаны в один файл. "
                    "Измените названия:\n\n" + preview,
                )
                return

        self.save_settings()
        self._set_export_running_state(True)
        self._set_export_progress_indeterminate(False)
        self.export_progress['value'] = 0
        self.is_export_stopped = False

        def run_export():
            outcome = "running"
            try:
                total_files = len(export_files)
                processed_files = 0
                failed_files = 0

                def build_tags(settings_dict):
                    t = {}
                    if settings_dict.get("title"): t["title"] = settings_dict["title"]
                    if settings_dict.get("artist"): t["artist"] = settings_dict["artist"]
                    if settings_dict.get("album"): t["album"] = settings_dict["album"]
                    if settings_dict.get("album_artist"): t["album_artist"] = settings_dict["album_artist"]
                    if settings_dict.get("genre"): t["genre"] = settings_dict["genre"]
                    if settings_dict.get("composer"): t["composer"] = settings_dict["composer"]
                    if settings_dict.get("year"): t["date"] = settings_dict["year"]
                    if settings_dict.get("language"): t["language"] = settings_dict["language"]
                    return t

                # Обновление тегов в исходных файлах
                if tags_only:
                    for item_id in items:
                        if self.is_export_stopped: break

                        # Группа
                        if item_id in export_groups:
                            g_set = export_groups[item_id]
                            g_tags = build_tags(g_set)
                            files = group_children.get(item_id, ())

                            for f_id in files:
                                if self.is_export_stopped: break
                                f_set = export_files[f_id]
                                fp = f_set["path"]  # Используем сохранённый исходный путь.

                                f_tags = build_tags(f_set)
                                for k in ["artist", "album", "album_artist", "genre", "composer", "date"]:
                                    if k not in f_tags and g_tags.get(k):
                                        f_tags[k] = g_tags[k]
                                cov = f_set.get("cover") or g_set.get("cover")

                                if not self._update_file_tags_inplace(
                                    fp, f_tags, cov, f_set.get("title", "")
                                ):
                                    failed_files += 1

                                processed_files += 1
                                pct = int((processed_files / total_files) * 100) if total_files > 0 else 0
                                self._post_to_ui(self.export_progress.config, value=pct)

                        # Одиночный файл
                        elif item_id in export_files:
                            f_set = export_files[item_id]
                            fp = f_set["path"]  # Используем сохранённый исходный путь.

                            f_tags = build_tags(f_set)
                            cov = f_set.get("cover")

                            if not self._update_file_tags_inplace(
                                fp, f_tags, cov, f_set.get("title", "")
                            ):
                                failed_files += 1

                            processed_files += 1
                            pct = int((processed_files / total_files) * 100) if total_files > 0 else 0
                            self._post_to_ui(self.export_progress.config, value=pct)

                # Полный экспорт в выбранный каталог
                else:
                    for item_idx, item_id in enumerate(items):
                        if self.is_export_stopped: break

                        if item_id in export_groups:
                            g_id = item_id
                            g_set = export_groups[g_id]
                            g_name = g_set["name"]
                            safe_group_name = sanitize_filename_component(
                                _template_basename(g_name, fmt),
                                fallback="Группа",
                            )
                            files = group_children.get(g_id, ())
                            if not files: continue

                            if g_set["merge"]:
                                pause_ms = g_set["pause"]

                                first_f_set = export_files.get(files[0], {})
                                for key in [
                                    "artist", "album", "album_artist", "genre",
                                    "composer", "year", "language", "cover",
                                ]:
                                    if not g_set.get(key) and first_f_set.get(key):
                                        g_set[key] = first_f_set[key]

                                merge_sources = []
                                for f_id in files:
                                    if self.is_export_stopped:
                                        break
                                    merge_sources.append(export_files[f_id]["path"])

                                if self.is_export_stopped:
                                    break
                                self._post_export_activity_status(
                                    "Склейка",
                                    g_name,
                                    "warning",
                                )
                                g_set["title"] = g_name
                                tags = build_tags(g_set)
                                out_file = out_dir / f"{safe_group_name}.{fmt}"
                                _export_merged_audio_ffmpeg(
                                    merge_sources,
                                    out_file,
                                    output_format=fmt,
                                    bitrate=None if bitrate == "auto" else bitrate,
                                    bitrate_mode=bitrate,
                                    sample_rate=sample_rate,
                                    channels=channels,
                                    pause_ms=pause_ms,
                                    speed=sp if apply_fx else 1.0,
                                    pitch=pt if apply_fx else 1.0,
                                    echo=ec if apply_fx else False,
                                    echo_delay=ed,
                                    echo_decay=ey,
                                    tags=tags,
                                    cover=g_set.get("cover"),
                                    cancelled=lambda: self.is_export_stopped,
                                )
                                processed_files += len(files)
                                pct = (
                                    int((processed_files / total_files) * 100)
                                    if total_files > 0
                                    else 0
                                )
                                self._post_to_ui(
                                    self.export_progress.config, value=pct
                                )

                            else:
                                target_dir = (
                                    out_dir / safe_group_name
                                    if effective_group_subfolder(
                                        g_set.get("merge"), g_set.get("subfolder")
                                    )
                                    else out_dir
                                )
                                target_dir.mkdir(parents=True, exist_ok=True)

                                for i, f_id in enumerate(files):
                                    if self.is_export_stopped: break

                                    f_set = export_files[f_id]
                                    fp = f_set["path"]

                                    f_tags = build_tags(f_set)
                                    g_tags = build_tags(g_set)
                                    for k in ["artist", "album", "album_artist", "genre", "composer", "date"]:
                                        if k not in f_tags and g_tags.get(k):
                                            f_tags[k] = g_tags[k]

                                    cov = f_set.get("cover") or g_set.get("cover")

                                    self._post_export_activity_status(
                                        "Экспорт",
                                        f_set["title"],
                                        "warning",
                                    )
                                    safe_name = sanitize_filename_component(
                                        _template_basename(
                                            f_set["title"], fmt
                                        ),
                                        fallback=Path(fp).stem,
                                    )
                                    out_file = target_dir / f"{safe_name}.{fmt}"
                                    # Один вход всё равно проходит через общий
                                    # граф FFmpeg: так выбранные частота,
                                    # каналы, битрейт и эффекты одинаково
                                    # применяются и к склейке, и к отдельным
                                    # файлам без промежуточного PCM/WAV.
                                    _export_single_audio_ffmpeg(
                                        fp,
                                        out_file,
                                        output_format=fmt,
                                        bitrate=None if bitrate == "auto" else bitrate,
                                        bitrate_mode=bitrate,
                                        sample_rate=sample_rate,
                                        channels=channels,
                                        speed=sp if apply_fx else 1.0,
                                        pitch=pt if apply_fx else 1.0,
                                        echo=ec if apply_fx else False,
                                        echo_delay=ed,
                                        echo_decay=ey,
                                        tags=f_tags,
                                        cover=cov,
                                        cancelled=lambda: self.is_export_stopped,
                                    )

                                    processed_files += 1
                                    pct = int((processed_files / total_files) * 100) if total_files > 0 else 0
                                    self._post_to_ui(self.export_progress.config, value=pct)

                        elif item_id in export_files:
                            f_id = item_id
                            f_set = export_files[f_id]
                            fp = f_set["path"]

                            f_tags = build_tags(f_set)
                            cov = f_set.get("cover")

                            self._post_export_activity_status(
                                "Экспорт",
                                f_set["title"],
                                "warning",
                            )
                            safe_name = sanitize_filename_component(
                                _template_basename(f_set["title"], fmt),
                                fallback=Path(fp).stem,
                            )
                            out_file = out_dir / f"{safe_name}.{fmt}"
                            _export_single_audio_ffmpeg(
                                fp,
                                out_file,
                                output_format=fmt,
                                bitrate=None if bitrate == "auto" else bitrate,
                                bitrate_mode=bitrate,
                                sample_rate=sample_rate,
                                channels=channels,
                                speed=sp if apply_fx else 1.0,
                                pitch=pt if apply_fx else 1.0,
                                echo=ec if apply_fx else False,
                                echo_delay=ed,
                                echo_decay=ey,
                                tags=f_tags,
                                cover=cov,
                                cancelled=lambda: self.is_export_stopped,
                            )

                            processed_files += 1
                            pct = int((processed_files / total_files) * 100) if total_files > 0 else 0
                            self._post_to_ui(self.export_progress.config, value=pct)

                if self.is_export_stopped:
                    outcome = "stopped"
                    self._post_export_status("Сборка прервана!", "warning")
                    self._post_to_ui(self._show_warning, "Остановлено", "Процесс сборки был прерван пользователем.")
                else:
                    if failed_files:
                        outcome = "warning"
                        msg = (
                            f"Обработка завершена с ошибками: {failed_files}.\n"
                            "Подробности записаны в журнал."
                        )
                        self._post_export_status(
                            "Готово с ошибками.", "warning"
                        )
                        self._post_to_ui(self._show_warning, "Готово", msg)
                    else:
                        outcome = "success"
                        msg = "Теги успешно обновлены в исходных файлах!" if tags_only else f"Сборка успешно завершена!\nСохранено в: {out_dir}"
                        self._post_export_status("Готово!", "success")
                        self._post_to_ui(self._show_info, "Успех", msg)

            except InterruptedError:
                # Отмена потоковой склейки FFmpeg является штатным исходом:
                # вспомогательная функция уже завершила дочерний процесс и удалила временный файл.
                outcome = "stopped"
                self.is_export_stopped = True
                self._post_export_status("Сборка прервана!", "warning")
                self._post_to_ui(
                    self._show_warning,
                    "Остановлено",
                    "Процесс сборки был прерван пользователем.",
                )
            except Exception as e:
                outcome = "error"
                logging.exception("Ошибка сборки")
                error_message = f"Произошла ошибка при сборке:\n{e}"
                self._post_export_status("Ошибка!", "error")
                self._post_to_ui(self._show_error, "Ошибка", error_message)
            finally:
                self._post_to_ui(self._finish_export_process_ui, outcome)

        self._export_thread = threading.Thread(target=run_export, daemon=True)
        try:
            self._export_thread.start()
        except Exception as exc:
            self._export_thread = None
            self._set_export_running_state(False)
            self._set_export_status("Ошибка запуска сборки.", "error")
            logging.exception("Не удалось запустить поток экспорта")
            self._show_error(
                "Ошибка", f"Не удалось запустить сборку:\n{exc}"
            )

    def add_separator_row(self, initial_value=""):
        """Добавляет новую строку с ttk.Entry для разделителя с прямой записью текста."""
        if not hasattr(self, 'separators_container') or not self.separators_container.winfo_exists():
            return

        row_frame = ttk.Frame(self.separators_container)
        row_frame.pack(fill=tk.X, pady=2)

        # Прямое создание поля ввода без временного StringVar (защита от сборщика мусора)
        ent = ttk.Entry(row_frame)
        ent.insert(0, str(initial_value))  # Записываем значение непосредственно в поле.
        ent.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 5))

        btn_del = ttk.Button(row_frame, text="❌", width=3, command=lambda: self.remove_separator_row(row_frame, ent))
        btn_del.pack(side=tk.RIGHT)

        self.separator_entries.append(ent)

    def remove_separator_row(self, row_frame, entry_widget):
        """Удаляет строчку разделителя"""
        if entry_widget in self.separator_entries:
            self.separator_entries.remove(entry_widget)
        row_frame.destroy()


    # Вкладка «Настройки»
    def setup_settings_tab(self):
        btn_frame = ttk.Frame(self.tab_settings, padding=10)
        btn_frame.pack(side=tk.BOTTOM, fill=tk.X)
        def save_settings_from_button():
            # Сохранение конфига не запускает API: большое значение здесь лишь
            # валидируем, а подтверждение показываем непосредственно перед API.
            if self._validate_api_steps_ui(confirm_large=False):
                self.save_settings(show_popup=True)

        ttk.Button(btn_frame, text="💾 Сохранить", command=save_settings_from_button).pack(side=tk.LEFT, padx=5)
        ttk.Button(btn_frame, text="📂 Загрузить конфиг", command=self.import_config).pack(side=tk.LEFT, padx=5)
        ttk.Button(btn_frame, text="📤 Экспорт конфига", command=self.export_config).pack(side=tk.LEFT, padx=5)
        ttk.Button(btn_frame, text="🔄 Сбросить", command=self.reset_config).pack(side=tk.LEFT, padx=5)

        set_notebook = ttk.Notebook(self.tab_settings)
        set_notebook.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
        self.tab_settings.pack_propagate(False)

        scrolling_forms = {}

        def make_settings_tab(title):
            view = ttk.Frame(set_notebook)
            view.columnconfigure(0, weight=1)
            view.rowconfigure(0, weight=1)
            background = ttk.Style(view).lookup("TFrame", "background")
            canvas = tk.Canvas(
                view, highlightthickness=0, bd=0,
                background=background or self.root.cget("background"),
            )
            scrollbar = ttk.Scrollbar(view, orient=tk.VERTICAL, command=canvas.yview)
            surface = ttk.Frame(canvas)
            surface.columnconfigure(0, weight=1)
            form = ttk.Frame(surface, padding=10)
            form.grid(row=0, column=0, sticky=tk.EW)
            window = canvas.create_window((0, 0), window=surface, anchor="nw")
            canvas.configure(yscrollcommand=scrollbar.set)
            canvas.grid(row=0, column=0, sticky=tk.NSEW)

            def sync_scroll(_event=None):
                try:
                    width = canvas.winfo_width()
                    viewport_height = canvas.winfo_height()
                    content_height = form.winfo_reqheight()
                    # Нативный фон закрывает Canvas и под короткой формой.
                    # Отдельная форма сохраняет свою высоту при сворачивании подсказок.
                    surface_height = max(content_height, viewport_height)
                    if width > 1:
                        canvas.itemconfigure(window, width=width, height=surface_height)
                    canvas.configure(scrollregion=(0, 0, width, surface_height))
                    if content_height > viewport_height:
                        scrollbar.grid(row=0, column=1, sticky=tk.NS)
                    else:
                        canvas.yview_moveto(0)
                        scrollbar.grid_remove()
                except tk.TclError:
                    pass

            form.bind("<Configure>", sync_scroll, add="+")
            canvas.bind("<Configure>", sync_scroll, add="+")
            scrolling_forms[canvas] = form
            set_notebook.add(view, text=title)
            return form

        def scroll_settings(event):
            try:
                # Обработчик окна охватывает и добавленные позднее разделители,
                # но не вмешивается в прокрутку остальных вкладок и диалогов.
                canvas = event.widget
                while canvas is not None and canvas not in scrolling_forms:
                    canvas = getattr(canvas, "master", None)
                if canvas is None:
                    return
                if scrolling_forms[canvas].winfo_reqheight() <= canvas.winfo_height():
                    return
                delta = getattr(event, "delta", 0)
                if delta:
                    canvas.yview_scroll(
                        (-1 if delta > 0 else 1) * max(1, round(abs(delta) / 120)),
                        "units",
                    )
                elif getattr(event, "num", None) == 4:
                    canvas.yview_scroll(-3, "units")
                elif getattr(event, "num", None) == 5:
                    canvas.yview_scroll(3, "units")
            except (AttributeError, tk.TclError, TypeError, ValueError):
                pass

        for sequence in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
            self.root.bind(sequence, scroll_settings, add="+")

        # Короткие заголовки сохраняют доступ ко всем внутренним вкладкам на
        # экранах шириной 900 px. Полные названия разделов видны в их полях.
        tab_api = make_settings_tab("API")
        tab_folders = make_settings_tab("Папки")
        tab_pauses = make_settings_tab("Паузы")
        tab_cache = make_settings_tab("Кэш")
        tab_normalization = make_settings_tab("Нормализация")
        tab_effects = make_settings_tab("Эффекты")
        tab_output = make_settings_tab("Вывод и теги")

        def add_entry(parent, label, key, row, vtype=tk.StringVar):
            ttk.Label(parent, text=label).grid(row=row, column=0, sticky=tk.W, pady=2, padx=5)
            var = vtype(value=self.config.get(key, ""))
            self.settings_vars[key] = var
            ttk.Entry(parent, textvariable=var).grid(row=row, column=1, sticky="ew", pady=2, padx=5)

        def add_combobox(parent, label, key, row, values):
            ttk.Label(parent, text=label).grid(row=row, column=0, sticky=tk.W, pady=2, padx=5)
            var = tk.StringVar(value=self.config.get(key, values[0]))
            self.settings_vars[key] = var
            cb = ttk.Combobox(parent, textvariable=var, values=values, state="readonly")
            cb.grid(row=row, column=1, sticky="ew", pady=2, padx=5)

        def add_dir_entry(parent, label, key, row, is_file=False):
            ttk.Label(parent, text=label).grid(row=row, column=0, sticky=tk.W, pady=2, padx=5)
            # Папка прямого синтеза уже показана на одноимённой вкладке. Оба Entry
            # должны использовать один StringVar, а не две рассинхронизируемые
            # копии одного значения.
            if key == "direct_output_dir" and hasattr(self, "direct_output_dir_var"):
                var = self.direct_output_dir_var
            elif key == "output_dir" and hasattr(self, "source_output_dir_var"):
                # ``source_output_dir_var`` создаётся до вкладки настроек, чтобы
                # единственный видимый редактор в «Настройки → Папки» мог использовать
                # то же текущее значение, что и фоновый обработчик источника. Вкладка источника
                # намеренно не отображает дублирующее поле.
                var = self.source_output_dir_var
            else:
                var = tk.StringVar(value=self.config.get(key, ""))
            self.settings_vars[key] = var
            f = ttk.Frame(parent)
            f.grid(row=row, column=1, sticky="ew", pady=2, padx=5)
            path_entry = ttk.Entry(f, textvariable=var)
            path_entry.pack(side=tk.LEFT, fill=tk.X, expand=True)
            self._bind_path_entry(path_entry, key, var)
            def cmd():
                init_dir = self._get_smart_dir(var.get(), is_file=is_file)
                res = filedialog.askopenfilename(initialdir=init_dir) if is_file else filedialog.askdirectory(initialdir=init_dir)
                if res: var.set(res)
            ttk.Button(f, text="📁", width=3, command=cmd).pack(side=tk.RIGHT, padx=2)

        def add_check(parent, label, key, row):
            var = tk.BooleanVar(value=self.config.get(key, False))
            self.settings_vars[key] = var
            ttk.Checkbutton(parent, text=label, variable=var).grid(row=row, column=0, columnspan=2, sticky=tk.W, pady=2, padx=5)

        # 1. Раздел API
        add_entry(tab_api, "API Token:", "api_token", 0)
        add_entry(tab_api, "API URL:", "api_url", 1)
        add_entry(tab_api, "Спикер (Голос):", "speaker", 2)

        steps_frame = ttk.LabelFrame(
            tab_api,
            text="Экспериментально: скорость / качество синтеза (steps)",
            padding=8,
        )
        steps_frame.grid(row=3, column=0, columnspan=2, sticky="ew", pady=(10, 4), padx=5)
        steps_frame.columnconfigure(1, weight=1)

        self.settings_vars["api_steps_enabled"] = tk.BooleanVar(
            value=_config_bool(self.config.get("api_steps_enabled", False))
        )
        ttk.Checkbutton(
            steps_frame,
            text="Передавать параметр steps в Silero API",
            variable=self.settings_vars["api_steps_enabled"],
            command=self._sync_api_steps_widgets,
        ).grid(row=0, column=0, sticky=tk.W)

        initial_steps_raw = self.config.get("api_steps", 16)
        initial_steps = initial_steps_raw
        try:
            initial_text = str(initial_steps).strip()
            if not re.fullmatch(r"[+-]?\d+", initial_text):
                raise ValueError
            initial_steps = int(initial_text)
        except (TypeError, ValueError):
            # Не маскируем ошибочный импорт значением 16: пользователь увидит
            # исходное значение в поле «Другое» и явную ошибку при сохранении.
            initial_steps = 0
        initial_choice = str(initial_steps) if initial_steps in API_STEPS_PRESETS else "Другое"

        ttk.Label(steps_frame, text="Steps:").grid(row=1, column=0, sticky=tk.W, pady=(5, 2))
        self.settings_vars["api_steps_choice"] = tk.StringVar(value=initial_choice)
        self.settings_vars["api_steps"] = tk.IntVar(value=initial_steps)
        self.api_steps_combobox = ttk.Combobox(
            steps_frame,
            textvariable=self.settings_vars["api_steps_choice"],
            values=[str(value) for value in API_STEPS_PRESETS] + ["Другое"],
            state="readonly",
            width=12,
        )
        self.api_steps_combobox.grid(row=1, column=1, sticky=tk.W, pady=(5, 2))
        self.api_steps_combobox.bind(
            "<<ComboboxSelected>>",
            lambda _event: self._sync_api_steps_widgets(focus_custom=True),
        )

        ttk.Label(steps_frame, text=f"Своё значение (целое {API_STEPS_MIN}–{API_STEPS_MAX}):").grid(
            row=2, column=0, sticky=tk.W, pady=2
        )
        self.settings_vars["api_steps_custom"] = tk.StringVar(
            value="" if initial_choice != "Другое" else str(initial_steps_raw)
        )
        self.api_steps_custom_entry = ttk.Entry(
            steps_frame,
            textvariable=self.settings_vars["api_steps_custom"],
            width=14,
        )
        self.api_steps_custom_entry.grid(row=2, column=1, sticky=tk.W, pady=2)

        self.settings_vars["cache_include_steps"] = tk.BooleanVar(
            value=_config_bool(self.config.get("cache_include_steps", True), default=True)
        )
        self.api_steps_cache_check = ttk.Checkbutton(
            steps_frame,
            text="Учитывать steps в ключе кэша (рекомендуется)",
            variable=self.settings_vars["cache_include_steps"],
        )
        self.api_steps_cache_check.grid(
            row=3, column=0, columnspan=2, sticky=tk.W, pady=(3, 0)
        )

        def enforce_steps_cache_key(*_args):
            if (
                _config_bool(self.settings_vars["api_steps_enabled"].get())
                and not _config_bool(self.settings_vars["cache_include_steps"].get())
            ):
                if not self._ask_yes_no(
                    "Общий кэш Steps",
                    "Без учёта Steps разные значения качества используют один "
                    "и тот же ключ и могут заменять друг друга. Оставить общий "
                    "старый кэш?",
                    icon="warning",
                ):
                    self.settings_vars["cache_include_steps"].set(True)

        self.api_steps_cache_check.configure(command=enforce_steps_cache_key)

        steps_hint, _steps_hint_body, _steps_hint_toggle = (
            self._make_collapsible_hint(
                steps_frame,
                (
                    "Выключено = параметр не отправляется (серверное значение "
                    "по умолчанию и старый кэш). 16 — значение API по "
                    "умолчанию; 8 — быстрее, немного хуже; 4 — ещё быстрее, "
                    "но заметно хуже; 12 — промежуточный вариант. Выше 16 "
                    "будет предупреждение, допустимый диапазон сейчас 1–72."
                ),
                title="О параметре steps",
                wraplength=700,
                initially_open=False,
            )
        )
        # Широкая строка даёт тексту мало переносов и остаётся компактной даже
        # после раскрытия. Сетка лимитов 2×2 ниже сохраняет достаточно высоты
        # для параметра параллельных сборок FFmpeg.
        steps_hint.grid(
            row=4, column=0, columnspan=2, sticky=tk.EW, pady=(5, 0)
        )
        self._sync_api_steps_widgets()

